          GUID = "0F468522",
          NextDialogue = 6101902,
          RougeTalkActorType = 3
        },
        [6101902] = {
          ContentTC = "「年輕人，你知道艾利西安在哪個方向嗎？」\n老人開口，聲音枯啞。\n「我在這附近轉了幾圈，怎麼也找不見回家的路……」",
          DialogueId = 6101902,
          GUID = "0F46854C",
          NextOptions = {
            [1] = 6101903
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101903] = {
          ContentTC = "沉默。",
          DialogueId = 6101903,
          GUID = "0F468576",
          NextDialogue = 6101904,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101904] = {
          ContentTC = "「是嗎……你也迷路了嗎。唉……」\n老人長歎一聲，垂下了頭。",
          DialogueId = 6101904,
          GUID = "0F4685A0",
          NextOptions = {
            [1] = 6101905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101905] = {
          ContentTC = "詢問他是否可以給你一件武器。",
          DialogueId = 6101905,
          GUID = "0F4685CA",
          NextDialogue = 6101906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101906] = {
          ContentTC = "「武器？你是說地上的這些？」\n「噢……我想起來了，我是……一名鐵匠。」\n「我為一些人製造了武器，幫助他們逃離，然後——」",
          DialogueId = 6101906,
          GUID = "0F4685F4",
          NextDialogue = 6101907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101907] = {
          ContentTC = "老人的目光黯淡了一瞬，似是終於想起了自己來到此地的緣由。\n隨後，他輕輕搖了搖頭，向你報以一個滄桑的笑容。",
          DialogueId = 6101907,
          GUID = "0F46861E",
          NextDialogue = 6101908,
          RougeTalkActorType = 3
        },
        [6101908] = {
          ContentTC = "「當然可以，孩子。」\n「請隨意挑選吧，希望它能護你平安。」",
          DialogueId = 6101908,
          GUID = "0F468648",
          NextOptions = {
            [1] = 6101909,
            [2] = 6101910
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101909] = {
          ContentTC = "從老人左手邊的武器中挑選。",
          DialogueId = 6101909,
          GUID = "0F468672",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101910] = {
          ContentTC = "從老人右手邊的武器中挑選。",
          DialogueId = 6101910,
          GUID = "0F46869C",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101911] = {
          ContentTC = "你將挑選的武器收入囊中。\n老人似乎已經忘了你的存在，只是一言不發地注視著手中的鐵錘，似是陷入了思考。",
          DialogueId = 6101911,
          GUID = "0F4686C6",
          RougeTalkActorType = 3
        },
        [6102001] = {
          ContentTC = "你聽見金屬撞擊的聲音。火花飛濺，融化在篝火的光明中。\n你循著聲音的方向看去，老人在簡陋的鍛造台邊用力揮動著鐵錘，汗珠從他的額前滴落。",
          DialogueId = 6102001,
          GUID = "0F46958A",
          NextDialogue = 6102002,
          RougeTalkActorType = 3
        },
        [6102002] = {
          ContentTC = "「年輕人，你好啊！」\n見到你，老人熱情地打招呼。",
          DialogueId = 6102002,
          GUID = "0F4695B4",
          NextOptions = {
            [1] = 6102003
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102003] = {
          ContentTC = "您好。",
          DialogueId = 6102003,
          GUID = "0F4695DE",
          NextDialogue = 6102004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102004] = {
          ContentTC = "「看樣子，你也被困在這地方了吧？」老人指了指自己，「我也是。」",
          DialogueId = 6102004,
          GUID = "0F469608",
          NextOptions = {
            [1] = 6102005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102005] = {
          ContentTC = "我們又見面了。",
          DialogueId = 6102005,
          GUID = "0F469632",
          NextDialogue = 6102006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102006] = {
          ContentTC = "「我們見過面嗎？」老人有些困惑，「我倒是不記得了，最近記性越來越差……」",
          DialogueId = 6102006,
          GUID = "0F46965C",
          NextDialogue = 6102007,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102007] = {
          ContentTC = "「這地方危險，我造了些武器，你挑一件帶走吧。」\n老人爽朗地向你展示他的作品。\n「我想著，橫豎都找不到出去的路，不如做回老本行。說不定哪天，我造的武器能幫到某位了不得的騎士大人，把我們帶出這個鬼地方。」",
          DialogueId = 6102007,
          GUID = "0F469686",
          NextOptions = {
            [1] = 6102008,
            [2] = 6102009,
            [3] = 6102010
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102008] = {
          ContentTC = "從剛鑄成的新武器中挑選。",
          DialogueId = 6102008,
          GUID = "0F4696B0",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102009] = {
          ContentTC = "從排列整齊的成品中挑選。",
          DialogueId = 6102009,
          GUID = "0F4696DA",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102010] = {
          ContentTC = "從蒙塵的儲藏角落中挑選。",
          DialogueId = 6102010,
          GUID = "0F469704",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102011] = {
          ContentTC = "帶著挑選的武器，你在老人親切的道別聲中繼續前進。",
          DialogueId = 6102011,
          GUID = "0F46972E",
          RougeTalkActorType = 3
        },
        [6102101] = {
          ContentTC = "篝火明滅，勾勒出詩人低垂的側臉。\n她半跪在篝火旁，伸出手指，在煙灰中緩緩勾勒出蜿蜒的紋路。",
          DialogueId = 6102101,
          GUID = "0F46A5F2",
          NextDialogue = 6102102,
          RougeTalkActorType = 3
        },
        [6102102] = {
          ContentTC = "「若無處可逃，那便接受命運吧；」\n「若文字無法成為刺破謊言的利刃，那便讓它成為砌築美夢的磚瓦吧——」\n詩人停頓了一下，微微抬起指尖。\n「唔……」",
          DialogueId = 6102102,
          GUID = "0F46A61C",
          NextDialogue = 6102103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102103] = {
          ContentTC = "腦海中的回憶忽然被喚醒，你確信自己曾經聽過這首詩。\n一縷煙灰拂過臉頰，幾乎是下意識地，你輕聲念出了那空缺的最後一句——",
          DialogueId = 6102103,
          GUID = "0F46A646",
          NextOptions = {
            [1] = 6102104
          },
          RougeTalkActorType = 3
        },
        [6102104] = {
          ContentTC = "「書寫一個謊言，點燃一束不熄的火光。」",
          DialogueId = 6102104,
          GUID = "0F46A670",
          NextDialogue = 6102105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102105] = {
          ContentTC = "「嗯……？！」\n詩人抬起頭來，驚喜地看著你。\n「多麼美妙的詞句啊，這正是我想要的結尾！沒想到竟能在這裡遇上一位知己，真是幸運。」",
          DialogueId = 6102105,
          GUID = "0F46A69A",
          NextOptions = {
            [1] = 6102106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102106] = {
          ContentTC = "「其實這是另一個時間的你寫下的。」",
          DialogueId = 6102106,
          GUID = "0F46A6C4",
          NextDialogue = 6102107,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102107] = {
          ContentTC = "「『另一個時間』……？」\n詩人先是露出訝異的神情，然後目光很快變得明亮，像是被那篝火點燃了一般。\n「原來如此……您是特別的——是這首敘事詩的主角，是我將在時間的其他方向再度遇見的人，對嗎？」",
          DialogueId = 6102107,
          GUID = "0F46A6EE",
          NextOptions = {
            [1] = 6102108
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102108] = {
          ContentTC = "點頭。",
          DialogueId = 6102108,
          GUID = "0F46A718",
          NextDialogue = 6102109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102109] = {
          ContentTC = "「那麼這句詩究竟算是您寫的，還是我寫的呢？嗬嗬……真是個迷人的疑問，我想聖樹學院的學者們也會為您的故事傾倒。」\n詩人咯咯地笑起來。\n「下次見面的時候，還請允許我為您作一首詩。現在，請伸出手來，收下我的祝福吧。」",
          DialogueId = 6102109,
          GUID = "0F46A742",
          NextOptions = {
            [1] = 6102110,
            [2] = 6102111
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102110] = {
          ContentTC = "伸出左手。",
          DialogueId = 6102110,
          GUID = "0F46A76C",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102111] = {
          ContentTC = "伸出右手。",
          DialogueId = 6102111,
          GUID = "0F46A796",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102112] = {
          ContentTC = "詩人用指尖殘留的煙灰在你的手心寫下了什麼。\n你依舊無法理解這些文字的含義，但你能感覺到它鮮明的溫度，熱烈卻不至於將人灼傷。\n當你再次抬頭，詩人已經不知所蹤。",
          DialogueId = 6102112,
          GUID = "0F46A7C0",
          RougeTalkActorType = 3
        },
        [6102201] = {
          ContentTC = "「那無常的命運之神啊，時而令我們歡喜，時而令我們苦痛……」\n「常懷虔誠之心……祂潔白的紡線終會將我們與那眾天之天的樂土連綴……」\n少年認真而虔誠地朗讀著書本上的詞句，對你的出現渾然不覺。",
          DialogueId = 6102201,
          GUID = "0F46B65A",
          NextDialogue = 6102202,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102202] = {
          ContentTC = "你悄然走到少年身邊，飛快地瞥了一眼他手中的書。\n如你記憶中那般，書頁上的聖歌被充滿惡意的漆黑文字覆蓋。\n那文字扭動著，似要掙脫出紙面。",
          DialogueId = 6102202,
          GUID = "0F46B684",
          NextDialogue = 6102203,
          RougeTalkActorType = 3
        },
        [6102203] = {
          ContentTC = "「您好……您也想看書嗎？」\n少年終於注意到你，好奇地抬起了頭。",
          DialogueId = 6102203,
          GUID = "0F46B6AE",
          NextOptions = {
            [1] = 6102204,
            [2] = 6102208
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102204] = {
          ContentTC = "阻止他繼續讀下去。",
          DialogueId = 6102204,
          GUID = "0F46B6D8",
          IsKeyOption = true,
          NextDialogue = 6102205,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102205] = {
          ContentTC = "你將那本書從少年的手中抽出，用力地合上。",
          DialogueId = 6102205,
          GUID = "0F46B702",
          NextDialogue = 6102206,
          RougeTalkActorType = 3
        },
        [6102206] = {
          ContentTC = "「您沒事吧？！」\n少年擔憂地站起來，隨機又茫然地看向自己空無一物的雙手。\n「咦？我……不用再讀書了嗎？我……自由了嗎？」",
          DialogueId = 6102206,
          GUID = "0F46B72C",
          NextDialogue = 6102207,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102207] = {
          ContentTC = "你忍住指尖的痛楚，微笑著向他點了點頭，然後將那本書扔進篝火裡。\n火焰猛然升起，黑色的荊棘席卷著火舌一起向你襲來——",
          DialogueId = 6102207,
          GUID = "0F46B756",
          RougeTalkActorType = 3
        },
        [6102208] = {
          ContentTC = "沉默。",
          DialogueId = 6102208,
          GUID = "0F46B780",
          IsKeyOption = true,
          NextDialogue = 6102209,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102209] = {
          ContentTC = "你知道，無論你在此刻做出怎樣的行動，都無法真正改變少年的命運。\n你還有更重要的事去做——收集琉璃，徹底結束這個漫長的噩夢。",
          DialogueId = 6102209,
          GUID = "0F46B7AA",
          NextDialogue = 6102210,
          RougeTalkActorType = 3
        },
        [6102210] = {
          ContentTC = "頃刻間，黑色的荊棘蔓延，吞噬了少年的身影。\n你輕輕地歎息一聲，繼續前進。",
          DialogueId = 6102210,
          GUID = "0F46B7D4",
          RougeTalkActorType = 3
        },
        [6102301] = {
          ContentTC = "「孩子……快看，這裡有一堆篝火。」\n火光的對面，孑然一身的女人微笑著抬起頭，火光映出她憔悴的容顏。\n「真暖和呀，謝謝您，好心的陌生人。」",
          DialogueId = 6102301,
          GUID = "0F46C6C2",
          NextOptions = {
            [1] = 6102302
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102302] = {
          ContentTC = "詢問她所說的孩子在哪裡。",
          DialogueId = 6102302,
          GUID = "0F46C6EC",
          NextDialogue = 6102303,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102303] = {
          ContentTC = "「我的孩子就在這裡呀，您看。」",
          DialogueId = 6102303,
          GUID = "0F46C716",
          NextDialogue = 6102304,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102304] = {
          ContentTC = "順著女人示意的方向，你看到了一塊半人高的、覆滿青苔的岩石。\n在岩石中央偏上的部分，一枚亮閃閃的胸針被鑲嵌在石縫間，四周爬滿了細密的青苔圍繞，如同一顆被埋葬的心。\n女人溫柔地愛撫著岩石的表面，對手上沾染的泥土渾然不覺。",
          DialogueId = 6102304,
          GUID = "0F46C740",
          NextOptions = {
            [1] = 6102305,
            [2] = 6102308
          },
          RougeTalkActorType = 3
        },
        [6102305] = {
          ContentTC = "指出真相。",
          DialogueId = 6102305,
          GUID = "0F46C76A",
          IsKeyOption = true,
          NextDialogue = 6102306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102306] = {
          ContentTC = "「您在胡說什麼？！」\n女人的眼中瞬間升起尖銳的敵意，她緊緊地將那塊岩石護在身後，歇斯底裡地大叫起來。\n「這就是我的孩子……她就在這裡，我再也不會讓任何人帶走她……不會……」",
          DialogueId = 6102306,
          GUID = "0F46C794",
          NextDialogue = 6102307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102307] = {
          ContentTC = "你一時啞然。\n或許不該戳破這個美夢的，你早知這毫無意義。\n於是你起身離開，將篝火留給了女人和她的「孩子」。與此同時，潛伏在黑暗中的幽影伺機向你襲來——",
          DialogueId = 6102307,
          GUID = "0F46C7BE",
          RougeTalkActorType = 3
        },
        [6102308] = {
          ContentTC = "附和她。",
          DialogueId = 6102308,
          GUID = "0F46C7E8",
          IsKeyOption = true,
          NextDialogue = 6102309,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102309] = {
          ContentTC = "「謝謝您。這孩子從小就怕生，但她好像很喜歡您呢。」\n女人語氣和藹，雙手仍時不時輕撫那塊岩石。\n「您是一個人出門的嗎？這可不行，您的家人會擔心的……快回家去吧。」",
          DialogueId = 6102309,
          GUID = "0F46C812",
          NextDialogue = 6102310,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102310] = {
          ContentTC = "你禮貌地向她道謝，隨後便起身繼續前進。\n女人和她的「孩子」的身影，漸漸模糊在篝火的陰影中。",
          DialogueId = 6102310,
          GUID = "0F46C83C",
          RougeTalkActorType = 3
        },
        [6102401] = {
          ContentTC = "「不見了……不見了……」\n少女睜著空洞的雙眼，匍匐在地上摸索著，指甲幾乎要嵌入地面。",
          DialogueId = 6102401,
          GUID = "0F46D72A",
          NextOptions = {
            [1] = 6102402
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102402] = {
          ContentTC = "詢問她在找什麼。",
          DialogueId = 6102402,
          GUID = "0F46D754",
          NextDialogue = 6102403,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102403] = {
          ContentTC = "「我的石頭……石頭……之前明明就在這裡的……」\n她喃喃說著，幾乎是絕望地注視著你腳下的篝火。\n「我的火焰……要熄滅了……怎麼辦……怎麼辦……」",
          DialogueId = 6102403,
          GUID = "0F46D77E",
          NextOptions = {
            [1] = 6102404,
            [2] = 6102408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102404] = {
          ContentTC = "幫助她。",
          DialogueId = 6102404,
          GUID = "0F46D7A8",
          IsKeyOption = true,
          NextDialogue = 6102405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102405] = {
          ContentTC = "你試著回憶她喜歡的那些石子的模樣。雖然不確定它們的來曆，但你判斷用火焰魔法應該能製造出相似的東西。\n於是你試著利用篝火，凝聚力量——\n頃刻間，金黃色亮閃閃的小石頭如同流星一般墜落，互相碰撞發出清脆悅耳的聲響。",
          DialogueId = 6102405,
          GUID = "0F46D7D2",
          NextDialogue = 6102406,
          RougeTalkActorType = 3
        },
        [6102406] = {
          ContentTC = "「啊……！我的石頭——這就是我的石頭！謝謝您，神明的使者！」\n少女如獲至寶地一顆顆撿起那些石頭，小心翼翼地用裙擺兜起來。",
          DialogueId = 6102406,
          GUID = "0F46D7FC",
          NextDialogue = 6102407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102407] = {
          ContentTC = "那些結晶確實和你此前在少女懷中見到的石子一模一樣，你不禁開始懷疑它們是否從一開始就是你在某次旅途中不經意間留下的痕跡。\n無論如何，少女已經再次找回了她的「確定」，而你，也必須繼續踏上旅途。",
          DialogueId = 6102407,
          GUID = "0F46D826",
          RougeTalkActorType = 3
        },
        [6102408] = {
          ContentTC = "告訴她世事本就不可能一直如我們所願。",
          DialogueId = 6102408,
          GUID = "0F46D850",
          IsKeyOption = true,
          NextDialogue = 6102409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102409] = {
          ContentTC = "「我知道……我知道。」\n「所以我已經放棄了……我不再看那些書，不再思考魔法的起源，也不再追問那座塔裡有什麼了……」\n「現在我想要的只是一片火光而已，連這也不可以嗎？」",
          DialogueId = 6102409,
          GUID = "0F46D87A",
          NextDialogue = 6102410,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102410] = {
          ContentTC = "你無言以對。\n少女忽然站了起來，在你來得及做出反應之前，毅然踏進了火焰之中。\n慢慢地，少女的身影與火光融為一體，消失不見。\n你轉過身，繼續踏上旅途。",
          DialogueId = 6102410,
          GUID = "0F46D8A4",
          RougeTalkActorType = 3
        },
        [6102501] = {
          ContentTC = "篝火安靜地燃燒著，這一次你並未看到任何幻象。\n就在你打算離去的時候，地面上一些閃閃發光的東西引起了你的注意——\n那是一些金黃色的小石子，一顆一顆散落在地，仿若墜入凡塵的星星。",
          DialogueId = 6102501,
          GUID = "0F46E792",
          NextOptions = {
            [1] = 6102502,
            [2] = 6102506
          },
          RougeTalkActorType = 3
        },
        [6102502] = {
          ContentTC = "撿起石子扔進火焰中。",
          DialogueId = 6102502,
          GUID = "0F46E7BC",
          IsKeyOption = true,
          NextDialogue = 6102503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102503] = {
          ContentTC = "火焰越燒越旺，然後開始反常地向側面延伸。\n你謹慎地退後了一步，忽然間，一個身影從火焰中顯現出來，你這才看清楚，那向側面延伸的光芒並非火焰，而是少女的發絲。",
          DialogueId = 6102503,
          GUID = "0F46E7E6",
          NextDialogue = 6102504,
          RougeTalkActorType = 3
        },
        [6102504] = {
          ContentTC = "「您好！您發現了我的小石子，是嗎？」\n少女從篝火中跳出來，晃了晃腦袋，金色的石子劈裡啪啦地墜落在地。\n「我再也不用去外面找了——您看，只要走進這火裡，我就可以自己製造小石子了！」",
          DialogueId = 6102504,
          GUID = "0F46E810",
          NextDialogue = 6102505,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102505] = {
          ContentTC = "「請原諒我沒有時間與您多作寒暄——我還沒有收集滿一百四十六顆呢。」\n「不過我倒是發現了一些或許對您有用的東西或許，請收下吧，祝您旅途順利！」\n少女將什麼東西塞到你的手中，然後轉身消失在了火焰裡。",
          DialogueId = 6102505,
          GUID = "0F46E83A",
          NextDialogue = 6102510,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102506] = {
          ContentTC = "安靜地觀察。",
          DialogueId = 6102506,
          GUID = "0F46E864",
          IsKeyOption = true,
          NextDialogue = 6102507,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102507] = {
          ContentTC = "火焰仍在靜靜燃燒，恍惚間，你似乎從中聽到了一個聲音。",
          DialogueId = 6102507,
          GUID = "0F46E88E",
          NextDialogue = 6102508,
          RougeTalkActorType = 3
        },
        [6102508] = {
          ContentTC = "「是的……是的。我記住了。」\n少女平靜而幸福的聲音透過火焰傳來。\n「疑問要適可而止。火是神明的饋贈，不是物質的反應。就像這些小石子，它們是神明賜予我的寶物，讓我能夠安然入睡……」",
          DialogueId = 6102508,
          GUID = "0F46E8B8",
          NextDialogue = 6102509,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102509] = {
          ContentTC = "你沉默地轉身離開，一顆石子恰巧滾落在道路前方，你無意間將它踩碎成了粉末。\n神明賜予的寶物，原來如此脆弱。",
          DialogueId = 6102509,
          GUID = "0F46E8E2",
          NextDialogue = 6102510,
          RougeTalkActorType = 3
        },
        [6102510] = {
          ContentTC = "你忽然想，那片火焰到底是為少女帶來幸福的「確定」，還是將她永遠困在這裡的「枷鎖」呢？\n或許，這二者本來就沒什麼區別。",
          DialogueId = 6102510,
          GUID = "0F46E90C",
          RougeTalkActorType = 3
        },
        [6102601] = {
          ContentTC = "「對不起，都是我的錯……我太笨了，記不全聖歌……我太懶了，沒有堅持聽完布道……」\n「神明大人，請原諒我……」",
          DialogueId = 6102601,
          GUID = "0F46F7FA",
          NextDialogue = 6102602,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102602] = {
          ContentTC = "女孩旁若無人地懺悔著——又或許，是她已經看不見旁人了。\n她的病情看上去比上次更加糟糕，連雙眼都變得黯淡無光。",
          DialogueId = 6102602,
          GUID = "0F46F824",
          NextDialogue = 6102603,
          RougeTalkActorType = 3
        },
        [6102603] = {
          ContentTC = "「您是……那位旅人……已經……過去很久了嗎？」\n女孩終於注意到你，慢慢地轉過頭來。\n「旅人……請您告訴我……為什麼，我日夜不停地向神明祈禱，神明卻從來不回應我？」",
          DialogueId = 6102603,
          GUID = "0F46F84E",
          NextOptions = {
            [1] = 6102604,
            [2] = 6102608
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102604] = {
          ContentTC = "鼓勵她繼續祈禱。",
          DialogueId = 6102604,
          GUID = "0F46F878",
          IsKeyOption = true,
          NextDialogue = 6102605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102605] = {
          ContentTC = "既然還沒到改寫結局的時刻，那麼將謊言延續下去也無妨……至少，那也是一種「希望」。\n你告訴她，只要繼續祈禱，總有一天你們都能得到拯救。\n這不完全是謊話——你相信深淵終會被戰勝，只不過她的祈禱無關緊要，真正的答案在於你手中的這盞提燈。",
          DialogueId = 6102605,
          GUID = "0F46F8A2",
          NextDialogue = 6102606,
          RougeTalkActorType = 3
        },
        [6102606] = {
          ContentTC = "「我明白了……我相信您。」\n女孩雙手交握，繼續低聲祈禱，聲音中多出了幾分堅定。",
          DialogueId = 6102606,
          GUID = "0F46F8CC",
          NextDialogue = 6102607,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102607] = {
          ContentTC = "你輕歎了一口氣，握緊手中的提燈，繼續前行。",
          DialogueId = 6102607,
          GUID = "0F46F8F6",
          RougeTalkActorType = 3
        },
        [6102608] = {
          ContentTC = "告訴她神明不會回應。",
          DialogueId = 6102608,
          GUID = "0F46F920",
          IsKeyOption = true,
          NextDialogue = 6102609,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102609] = {
          ContentTC = "「神明……不會回應我嗎？」\n「是因為我的罪孽太深，已經不值得拯救了嗎？」\n女孩絕望地看著你，淚水順著她布滿膿瘡的臉頰滑落。",
          DialogueId = 6102609,
          GUID = "0F46F94A",
          NextOptions = {
            [1] = 6102610
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102610] = {
          ContentTC = "「是因為你本來就沒有罪。」",
          DialogueId = 6102610,
          GUID = "0F46F974",
          NextDialogue = 6102611,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102611] = {
          ContentTC = "「咦……？」\n女孩愣住了，眼中浮現出深深的困惑。",
          DialogueId = 6102611,
          GUID = "0F46F99E",
          NextDialogue = 6102612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102612] = {
          ContentTC = "你對她露出一個堅定的微笑，告訴她，你一定會找到辦法結束她的痛苦。\n女孩看著你，似懂非懂地點了點頭。這時你注意到，她的傷口不再流血了。\n於是，你向她揮手作別，握緊手中的提燈，繼續前行。",
          DialogueId = 6102612,
          GUID = "0F46F9C8",
          RougeTalkActorType = 3
        },
        [6102701] = {
          ContentTC = "「芙薩，滿月女神——\n「輝光足跡的主宰，命運絲線的編織者……\n「穹頂與月華為證，虔信頌歌向你獻上……」",
          DialogueId = 6102701,
          GUID = "0F470862",
          NextDialogue = 6102702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102702] = {
          ContentTC = "人們的身形自火中浮現，他們齊聲念著獻給神明的禱言。",
          DialogueId = 6102702,
          GUID = "0F47088C",
          NextDialogue = 6102703,
          RougeTalkActorType = 3
        },
        [6102703] = {
          ContentTC = "「你是誰？一位迷路的旅人？」\n一位祈禱者看見了你，她笑著向你伸出手。\n「與我們一起向滿月女神祈禱吧，祂定會為你的前路賜福！」",
          DialogueId = 6102703,
          GUID = "0F4708B6",
          NextDialogue = 6102704,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102704] = {
          ContentTC = "他們的頌歌獻給<H>第九位神明</>，命運之神<H>芙薩</>。\n祂是滿月的主宰，祂抽引月華，織成命運之線。",
          DialogueId = 6102704,
          GUID = "0F4708E0",
          NextOptions = {
            [1] = 6102705,
            [2] = 6102709
          },
          RougeTalkActorType = 3
        },
        [6102705] = {
          ContentTC = "加入他們的祈禱。",
          DialogueId = 6102705,
          GUID = "0F47090A",
          IsKeyOption = true,
          NextDialogue = 6102706,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102706] = {
          ContentTC = "這是幼時的你最不喜歡的場合。你不喜歡那些空洞的溢美之詞，背下來轉頭就忘記。但如今，你卻生出一絲懷念。\n你加入了他們的祈禱。",
          DialogueId = 6102706,
          GUID = "0F470934",
          NextDialogue = 6102707,
          RougeTalkActorType = 3
        },
        [6102707] = {
          ContentTC = "「芙薩，命運無序亂流中恒常劃過天幕的滿月之神。\n「向你致敬，願你護佑你的信徒，\n「賜予我們無可挑剔的幸運與幸福。」",
          DialogueId = 6102707,
          GUID = "0F47095E",
          NextDialogue = 6102708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102708] = {
          ContentTC = "你閉上雙眼，跟著虔誠的信眾默念。\n最後一句念完，你睜開眼，他們的身影已經消失不見。",
          DialogueId = 6102708,
          GUID = "0F470988",
          RougeTalkActorType = 3
        },
        [6102709] = {
          ContentTC = "不願加入他們的祈禱。",
          DialogueId = 6102709,
          GUID = "0F4709B2",
          IsKeyOption = true,
          NextDialogue = 6102710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102710] = {
          ContentTC = "「拒絕？你——為什麼？」\n祈禱者尖利地叫出聲。\n「異端者——莫非你是暗月派的信徒？涅法的追隨者？」",
          DialogueId = 6102710,
          GUID = "0F4709DC",
          NextDialogue = 6102711,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102711] = {
          ContentTC = "聽到那個禁忌的名字，信徒們齊齊轉過臉來，他們的面孔變得扭曲而猙獰。\n你歎了口氣——你得想辦法從他們的團團包圍中抽身了。",
          DialogueId = 6102711,
          GUID = "0F470A06",
          RougeTalkActorType = 3
        },
        [6102801] = {
          ContentTC = "「命運紡線之剪，永恒寂靜的主宰者……\n「深淵與長夜為證，請聆聽我卑微的禱言……」",
          DialogueId = 6102801,
          GUID = "0F4718CA",
          NextDialogue = 6102802,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102802] = {
          ContentTC = "人們的身形自火中浮現，他們齊聲念著獻給神明的禱言。\n你靜靜聆聽著。那是你並不熟悉的禱文。",
          DialogueId = 6102802,
          GUID = "0F4718F4",
          NextDialogue = 6102803,
          RougeTalkActorType = 3
        },
        [6102803] = {
          ContentTC = "「你是誰？一位迷路的旅人？」\n一位祈禱者看見了你，她笑著向你伸出手。\n「還是說，你也同樣窺破了天機，想要同我們一起投入真正的救主——涅法的懷抱？」",
          DialogueId = 6102803,
          GUID = "0F47191E",
          NextDialogue = 6102804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102804] = {
          ContentTC = "<H>涅法</>——你記得這個名字。\n它不常出現在艾利西安正教信眾的筆下，你只在塵封的古老尺牘間見過這個名字。這是一個禁忌的名字，早已被遺忘的<H>第十位神明</>。",
          DialogueId = 6102804,
          GUID = "0F471948",
          NextDialogue = 6102805,
          RougeTalkActorType = 3
        },
        [6102805] = {
          ContentTC = "祂是滿月與命運之神芙薩的姊妹，暗月與死亡之神。\n她的同胞姐姐紡織命運絲線，她則剪斷命運。\n兩位神明無休止的爭鬥帶來月相盈虛，卷動潮汐。\n那麼，祂的信徒，便應該是……",
          DialogueId = 6102805,
          GUID = "0F471972",
          NextOptions = {
            [1] = 6102806
          },
          RougeTalkActorType = 3
        },
        [6102806] = {
          ContentTC = "詢問他們的信仰。",
          DialogueId = 6102806,
          GUID = "0F47199C",
          NextDialogue = 6102807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102807] = {
          ContentTC = "「既然出現在這兒，你應該已經知曉，這片深淵不是死物。它活著，不斷生長，不斷延伸。」\n「騎士團的黃金聖劍無法擊退黑暗的浪潮，滿月的光輝不能穿透幽邃的寂靜。」\n「正如一切光芒都向著熄滅飛馳，一切活物都終有一死——消亡是唯一可以確定的東西。我們的深淵，才是世界本真的模樣。」\n「歡迎加入<H>暗月教派</>，親愛的旅人。」",
          DialogueId = 6102807,
          GUID = "0F4719C6",
          NextOptions = {
            [1] = 6102808,
            [2] = 6102811
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102808] = {
          ContentTC = "回應他們的邀請。",
          DialogueId = 6102808,
          GUID = "0F4719F0",
          IsKeyOption = true,
          NextDialogue = 6102809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102809] = {
          ContentTC = "即使只是虛影，你也不想觸怒他們，增加無謂的糾纏。\n於是你開始煞有介事地復述起你聽過的那些關於暗月教派的傳言——「死亡的本能」啦，「涅法的救贖」啦，「深淵即永恒」啦……人們的臉上露出微笑，他們不住地點頭，附和起你的高談闊論。",
          DialogueId = 6102809,
          GUID = "0F471A1A",
          NextDialogue = 6102810,
          RougeTalkActorType = 3
        },
        [6102810] = {
          ContentTC = "「你的博學令我們感歎，你的智慧令我們折服。請收下這些禮物吧，陌生的朋友！」\n你蒙混過關了。還好，你並非少時的每一場布道和論辯都在走神。",
          DialogueId = 6102810,
          GUID = "0F471A44",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102811] = {
          ContentTC = "拒絕他們的邀請。",
          DialogueId = 6102811,
          GUID = "0F471A6E",
          IsKeyOption = true,
          NextDialogue = 6102812,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102812] = {
          ContentTC = "在這場漫長的苦旅中，你也曾多次思考過生的意義，死的意義。你也曾相信死亡便是唯一的解。\n但<H>那幾次意外的相逢</>讓你堅定了你無數次行走在黑暗中的意義——\n你要驅散這片黑暗，以自己的軀殼為薪柴。即使只是短暫的光，你也將灼燒這片凝滯的不朽。",
          DialogueId = 6102812,
          GUID = "0F471A98",
          NextDialogue = 6102813,
          RougeTalkActorType = 3
        },
        [6102813] = {
          ContentTC = "「深淵並非永恒，你們只是生者留下的虛影。\n你舉起武器。\n「回到你該去的地方吧，亡者們——」",
          DialogueId = 6102813,
          GUID = "0F471AC2",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102901] = {
          ContentTC = "你在篝火旁坐下休息。\n忽然間，你注意到了一種奇怪的響聲。一開始它好像就在你耳畔，然後漸漸遠了一點，移到了頭頂。\n聲音越來越響，窸窸窣窣，似乎是某種柔軟的東西在互相摩擦。",
          DialogueId = 6102901,
          GUID = "0F472932",
          NextDialogue = 6102902,
          RougeTalkActorType = 3
        },
        [6102902] = {
          ContentTC = "「嗨！幸運的旅人！」",
          DialogueId = 6102902,
          GUID = "0F47295C",
          NextDialogue = 6102903,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102903] = {
          ContentTC = "色彩斑斕的羽毛從頭頂落下來。你從來沒有一次在深淵裡同時看到這麼多顏色。\n現在，你被包圍在一地羽毛中間，好像被街頭玩整蠱遊戲的小傢伙們偶然選中的倒黴路人，尷尬中還透著一絲微妙的可悲。",
          DialogueId = 6102903,
          GUID = "0F472986",
          NextDialogue = 6102904,
          RougeTalkActorType = 3
        },
        [6102904] = {
          ContentTC = "「我說，你怎麼一點反應也沒有？你在深淵裡待這麼久了，不覺得無聊嗎？」\n戴著滑稽的鳥頭面具的人從上方倒立著緩緩降落下來，讓自己的視線與你齊平。\n你不知道他是怎麼保持這個動作的，但這不重要，重要的是他面具上的尖嘴快要戳到你的臉了。",
          DialogueId = 6102904,
          GUID = "0F4729B0",
          NextOptions = {
            [1] = 6102905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102905] = {
          ContentTC = "我沒空陪你胡鬧。",
          DialogueId = 6102905,
          GUID = "0F4729DA",
          NextDialogue = 6102906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102906] = {
          ContentTC = "「別這麼冷淡嘛，傳頌會的老傢伙們應該教過你吧，日行一善會有好報的。」\n「跟我<H>玩個遊戲</>，贏了就給你獎勵，輸了也沒有懲罰。穩賺不賠，怎麼樣？」",
          DialogueId = 6102906,
          GUID = "0F472A04",
          NextOptions = {
            [1] = 6102907
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102907] = {
          ContentTC = "好吧。",
          DialogueId = 6102907,
          GUID = "0F472A2E",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103001] = {
          ContentTC = "「哦，讓我們唱一首歌兒給<H>沙利葉</>吧！\n「他是艾利西安的聖者。\n「他聆聽芙薩的啟示，教給世人慈悲、寬恕與愛，\n「讓那朱紅的艾利西安大地，重綻和平的新枝。」",
          DialogueId = 6103001,
          GUID = "0F47399A",
          NextDialogue = 6103002,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103002] = {
          ContentTC = "你看到一位吟遊詩人打扮的老者正摩挲著一截斷壁。\n這處斷壁相對完整，借著微弱的燈光，你看到了一幅巨大的壁畫，畫的正是詩人口中的<H>沙利葉</>。\n兩千年的聖者，最初的<H>七美德</>之一，「節製」席。\n詩人徑自唱著歌，對你的到來充耳不聞。",
          DialogueId = 6103002,
          GUID = "0F4739C4",
          NextOptions = {
            [1] = 6103003
          },
          RougeTalkActorType = 3
        },
        [6103003] = {
          ContentTC = "繼續聽下去。",
          DialogueId = 6103003,
          GUID = "0F4739EE",
          NextDialogue = 6103004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103004] = {
          ContentTC = "「但聖者的心卻始終因一事而痛楚，\n「那便是芙薩給世人的應許，那眾天之天。\n「終於有一天，他在碧波之畔靜坐七十又七日後，\n「他於滿月之下洞悉真理，於湖中抵達永恒。」",
          DialogueId = 6103004,
          GUID = "0F473A18",
          NextDialogue = 6103005,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103005] = {
          ContentTC = "你知道他在唱什麼。\n沙利葉在湖畔得到滿月與命運女神芙薩的啟示，他的靈魂從此前往眾天之天，得到了「永恒」。他也成為第一位「神選者」。\n自他之後，又陸續有人身上顯現出聖痕，那是被神選中的徽記。他們陸續經由聖湖，抵達應許之地。\n這些早期傳頌會曆史你並不陌生。",
          DialogueId = 6103005,
          GUID = "0F473A42",
          NextOptions = {
            [1] = 6103006
          },
          RougeTalkActorType = 3
        },
        [6103006] = {
          ContentTC = "繼續聽下去。",
          DialogueId = 6103006,
          GUID = "0F473A6C",
          NextDialogue = 6103007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103007] = {
          ContentTC = "「可兩千年後，當我站在起伏的山巒凝望聖湖，\n「為何那裡只剩下漆黑的漩渦？\n「沙利葉啊，我們智慧的聖者——\n「告訴我，女神應許的樂園究竟在何處？」",
          DialogueId = 6103007,
          GUID = "0F473A96",
          NextDialogue = 6103008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103008] = {
          ContentTC = "詩人邊唱著，邊落下淚來。他終於從遙遠的曆史，唱到了眼前的現在——這片幽暗的深淵。\n不知從何時起，傳頌會兩千年來最神聖潔淨的聖湖，一夜之間突然為這汙濁的混沌所取代。\n就像一千年前那些棄教的墮落者所言的那樣——「九神已死！」\n要繼續聽下去嗎？",
          DialogueId = 6103008,
          GUID = "0F473AC0",
          NextOptions = {
            [1] = 6103009,
            [2] = 6103013
          },
          RougeTalkActorType = 3
        },
        [6103009] = {
          ContentTC = "繼續聽下去。",
          DialogueId = 6103009,
          GUID = "0F473AEA",
          IsKeyOption = true,
          NextDialogue = 6103010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103010] = {
          ContentTC = "「為何那穢濁的深淵沒有言語？\n「那滿月的銀輝遍照我身，為何女神不曾回答？\n「沙利葉啊，難道真的如暗月派的信徒所言——\n「你從未前往眾天之天，而是背向著明月，成為了魔鬼？」",
          DialogueId = 6103010,
          GUID = "0F473B14",
          NextDialogue = 6103011,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103011] = {
          ContentTC = "「請等一下——你說什麼？」\n詩人唱出了你始料未及的詞句，那是流傳於異端者中最隱秘的流言——聖湖從不曾神聖，所謂的由沙利葉而始的神選從一開始就是一場盛大的獻祭。\n從<H>某個人</>口中，你聽過相同的推測。",
          DialogueId = 6103011,
          GUID = "0F473B3E",
          NextDialogue = 6103012,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103012] = {
          ContentTC = "可詩人只是繼續旁若無人地撥弄著他的七弦琴，開始唱下一首歌謠，仿佛你並不存在於他的時空。\n他的聲音越來越遠，直到身影消失不見。",
          DialogueId = 6103012,
          GUID = "0F473B68",
          RougeTalkActorType = 3
        },
        [6103013] = {
          ContentTC = "離開此地。",
          DialogueId = 6103013,
          GUID = "0F473B92",
          IsKeyOption = true,
          NextDialogue = 6103014,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103014] = {
          ContentTC = "你打了幾聲招呼，嚐試吸引詩人的注意。你想和他聊聊，但他只是兀自唱著那首古老的歌謠。\n大概無法從他口中得到什麼有價值的情報了，於是你轉身離開。",
          DialogueId = 6103014,
          GUID = "0F473BBC",
          RougeTalkActorType = 3
        },
        [6200101] = {
          ContentTC = "數位年輕人的交談聲從不遠處傳來，你已經很久沒在深淵中聽到這樣的聲音了——熱烈的、鮮活的、尚未被深淵的黑暗侵染的聲音。\n你很確信這聲音的來源並非亡靈，也不是幻影，而是活生生的人類。而且，從談話的氣氛可以推斷出，他們一定才剛來到這裡不久。",
          DialogueId = 6200101,
          GUID = "0F857412",
          NextDialogue = 6200102,
          RougeTalkActorType = 3
        },
        [6200102] = {
          ContentTC = "你忍不住循著聲音所在的方向走去。環繞四周的迷霧逐漸散開，你見到了四位年輕的騎士。\n他們的衣著和裝備各自有別，但身上都佩戴著象征艾利西安的聖鳶尾徽章。",
          DialogueId = 6200102,
          GUID = "0F85743C",
          NextDialogue = 6200103,
          RougeTalkActorType = 3
        },
        [6200103] = {
          ContentTC = "「是這個方向沒錯嗎，隊長？」\n年輕的金發女騎士三步並作兩步跨上古舊的台階，又一口氣跳了下來。\n「這看起來只是一座廢墟而已。」",
          DialogueId = 6200103,
          GUID = "0F857466",
          NextDialogue = 6200104,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200104] = {
          ContentTC = "「至少我確定我們沒來過這裡。」\n被稱作隊長的青年騎士邁著沉穩的步伐從她身邊走過。\n「在聖湖裡很難辨別方向，現在也只能走一步算一步了。」",
          DialogueId = 6200104,
          GUID = "0F857490",
          NextDialogue = 6200105,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200105] = {
          ContentTC = "「還有——你這麼上躥下跳的不累嗎，凱希？」\n看著自己那位活潑的同伴，青年無奈地歎了一口氣。\n「這裡的環境凶險，還是謹慎為好，別在戰鬥之外的事情上消耗體力。」",
          DialogueId = 6200105,
          GUID = "0F8574BA",
          NextDialogue = 6200106,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200106] = {
          ContentTC = "「一點也不累！我又不像你，拿著那麼重的長劍和盾牌。」\n女孩輕巧地用食指勾住手槍，在空中轉了個圈。\n「說起來，這裡為什麼叫『聖湖』？我看這裡到處都是穢獸和詭異的幻象，實在不怎麼神聖呀。」",
          DialogueId = 6200106,
          GUID = "0F8574E4",
          NextDialogue = 6200107,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200107] = {
          ContentTC = "「凱希，注意你的言辭。」\n手執長杖的男性卡戎司祭一臉嚴肅地開口。\n「聖湖是受神選召之人蒙受神恩的聖地，如今雖被黑暗侵染，可我們身為艾利西安的一羽，仍應心懷敬畏。」",
          DialogueId = 6200107,
          GUID = "0F85750E",
          NextDialogue = 6200108,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200108] = {
          ContentTC = "四人之中的最後一位——身披鬥篷、背著一張長弓的女術士聽到他的話，不以為然地輕笑了一聲。黑色的兜帽遮住了她的面龐，你看不清她的表情。",
          DialogueId = 6200108,
          GUID = "0F857538",
          NextDialogue = 6200109,
          RougeTalkActorType = 3
        },
        [6200109] = {
          ContentTC = "似是想要緩解尷尬，身為隊長的青年張了張嘴，卻什麼也說不出來。正當他左右為難的時候，他注意到了你。",
          DialogueId = 6200109,
          GUID = "0F857562",
          NextDialogue = 6200110,
          RougeTalkActorType = 3
        },
        [6200110] = {
          ContentTC = "「閣下看起來不像是騎士團的人，莫非是誤入此地的平民？」",
          DialogueId = 6200110,
          GUID = "0F85758C",
          NextOptions = {
            [1] = 6200111
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200111] = {
          ContentTC = "我是一位旅人。",
          DialogueId = 6200111,
          GUID = "0F8575B6",
          NextDialogue = 6200112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200112] = {
          ContentTC = "「旅人……？」青年的臉上掠過一瞬的困惑，又旋即恢復溫和的勸誡，「那麼，或許您有所不知，此處是艾利西安的聖地，目前由於一些原因變得非常危險，並不適宜旅行。」",
          DialogueId = 6200112,
          GUID = "0F8575E0",
          NextDialogue = 6200113,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200113] = {
          ContentTC = "「我叫弗林，是艾利西安傳頌會下屬飛羽騎士團的騎士，這幾位都是我的同伴。如果您不介意的話，我們可以護送您離開此地。」",
          DialogueId = 6200113,
          GUID = "0F85760A",
          NextOptions = {
            [1] = 6200114
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200114] = {
          ContentTC = "不必了，我還有未完成的目標。",
          DialogueId = 6200114,
          GUID = "0F857634",
          NextDialogue = 6200115,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200115] = {
          ContentTC = "「我必須提醒您，這裡不止是聖地，也是禁地。作為騎士，我們有義務驅逐外來者。」",
          DialogueId = 6200115,
          GUID = "0F85765E",
          NextDialogue = 6200116,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200116] = {
          ContentTC = "「……怎麼驅逐？」伴隨一聲不屑的冷笑，身披鬥篷的女術士終於開口，「難道不是連我們自己都不知道該怎麼出去嗎？」\n她的話語冰涼，如寒冬的雪粒擦過臉頰。",
          DialogueId = 6200116,
          GUID = "0F857688",
          NextDialogue = 6200117,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char04"
        },
        [6200117] = {
          ContentTC = "「呃……好啦好啦。」金發的女騎士打起了圓場，「我看這位『客人』身手還不錯，也不像是瀆神者。反正不影響我們的任務，就當做沒看見吧？」",
          DialogueId = 6200117,
          GUID = "0F8576B2",
          NextDialogue = 6200118,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200118] = {
          ContentTC = "「對了對了，旅人閣下。」她推開弗林，擠到你面前，「您有沒有見過一位大約十三四歲，粉色長發，手持一柄巨劍的女劍士？」",
          DialogueId = 6200118,
          GUID = "0F8576DC",
          NextOptions = {
            [1] = 6200119
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200119] = {
          ContentTC = "……沒有。",
          DialogueId = 6200119,
          GUID = "0F857706",
          NextDialogue = 6200120,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200120] = {
          ContentTC = "「是嗎……那麼，如果您之後遇見了她，請幫忙轉告一聲——就說<H>靜默黃昏</>小隊正在找她，好嗎？拜托您了！」",
          DialogueId = 6200120,
          GUID = "0F857730",
          NextOptions = {
            [1] = 6200121
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200121] = {
          ContentTC = "你們為什麼要找她？",
          DialogueId = 6200121,
          GUID = "0F85775A",
          NextDialogue = 6200122,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200122] = {
          ContentTC = "「雖然有些難以啟齒，但她算是我們的……指揮官。呃，我也不能說得太多，否則米爾頓又該數落我了。」",
          DialogueId = 6200122,
          GUID = "0F857784",
          NextDialogue = 6200123,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200123] = {
          ContentTC = "「既然知道就別多嘴。」司祭皺起了眉頭。「別再橫生枝節了，任務要緊，我們走吧。」",
          DialogueId = 6200123,
          GUID = "0F8577AE",
          NextDialogue = 6200124,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200124] = {
          ContentTC = "「您真的不需要幫助嗎？」青年再次擔憂地看向你，「這裡真的非常危險，或許您可以和我們同路前行。」",
          DialogueId = 6200124,
          GUID = "0F8577D8",
          NextOptions = {
            [1] = 6200125
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200125] = {
          ContentTC = "真的不需要。",
          DialogueId = 6200125,
          GUID = "0F857802",
          NextDialogue = 6200126,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200126] = {
          ContentTC = "「好吧。既然您堅定如此……」",
          DialogueId = 6200126,
          GUID = "0F85782C",
          NextOptions = {
            [1] = 6200127
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200127] = {
          ContentTC = "既然這麼危險，你們不害怕嗎？",
          DialogueId = 6200127,
          GUID = "0F857856",
          IsKeyOption = true,
          NextDialogue = 6200128,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200128] = {
          ContentTC = "「心懷信仰，自然不會畏懼。」青年露出了篤定的笑容，「有緣再會，閣下，願滿月之神護佑您的旅途。」",
          DialogueId = 6200128,
          GUID = "0F857880",
          NextDialogue = 6200129,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200129] = {
          ContentTC = "騎士們結伴離開了，你的眼前又只剩下延綿不絕的迷霧。",
          DialogueId = 6200129,
          GUID = "0F8578AA",
          RougeTalkActorType = 3
        },
        [6200201] = {
          ContentTC = "年輕的女騎士從黑暗中現身，金色發絲如同一道流瀉的燈光照亮了混沌。\n她和上一次見面時不太一樣了——她的衣擺多了幾道破損之處，沾上了一些暗紅色的痕跡。",
          DialogueId = 6200201,
          GUID = "0F85847A",
          NextDialogue = 6200202,
          RougeTalkActorType = 3
        },
        [6200202] = {
          ContentTC = "「是你呀，旅人閣下，又見面了！」她似是有些疲憊，卻依舊打起精神向你用力揮手。",
          DialogueId = 6200202,
          GUID = "0F8584A4",
          NextOptions = {
            [1] = 6200203
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200203] = {
          ContentTC = "你的同伴們呢？",
          DialogueId = 6200203,
          GUID = "0F8584CE",
          NextDialogue = 6200204,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200204] = {
          ContentTC = "「唔……剛才我們遇到了好些穢獸，還有很多幽靈——我是說，那些黑暗裡的影子……」",
          DialogueId = 6200204,
          GUID = "0F8584F8",
          NextDialogue = 6200205,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200205] = {
          ContentTC = "「我拚命驅逐了它們，回過神來，大家就都不見了。你見到他們了嗎？」",
          DialogueId = 6200205,
          GUID = "0F858522",
          NextOptions = {
            [1] = 6200206
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200206] = {
          ContentTC = "沒有。",
          DialogueId = 6200206,
          GUID = "0F85854C",
          NextDialogue = 6200207,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200207] = {
          ContentTC = "凱希垂下了眼眸，像一朵浮雲飄過，遮住了太陽。",
          DialogueId = 6200207,
          GUID = "0F858576",
          NextDialogue = 6200208,
          RougeTalkActorType = 3
        },
        [6200208] = {
          ContentTC = "「弗林總是念叨說，戰鬥的時候要注意隊形，要互相照應……唉，如果我聽他的話，不那麼隨性就好了。」",
          DialogueId = 6200208,
          GUID = "0F8585A0",
          NextDialogue = 6200209,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200209] = {
          ContentTC = "「我根本不知道聖湖是這樣的地方。平時我就算不小心掉隊，也很快就能找到他們。可是這裡……明明是剛才走過的地方，回頭一看已經完全不一樣了。就像是……」\n她攥緊了拳頭。\n「就像是那些影子把大家帶走了……連他們留下的痕跡也一並抹除了。」",
          DialogueId = 6200209,
          GUID = "0F8585CA",
          NextOptions = {
            [1] = 6200210
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200210] = {
          ContentTC = "別擔心，你們一定會再次相遇的，就像你遇見我一樣。",
          DialogueId = 6200210,
          GUID = "0F8585F4",
          NextDialogue = 6200211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200211] = {
          ContentTC = "凱希有些驚訝地眨了眨眼，盯著你看了一會兒。",
          DialogueId = 6200211,
          GUID = "0F85861E",
          NextDialogue = 6200212,
          RougeTalkActorType = 3
        },
        [6200212] = {
          ContentTC = "「我們以前見過嗎？」\n她明亮的雙眸中倒映出你的容顏。那容顏讓你覺得陌生。",
          DialogueId = 6200212,
          GUID = "0F858648",
          NextDialogue = 6200213,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200213] = {
          ContentTC = "「我總覺得，你身上有種似曾相識的感覺——我不是說上次見面，而是更早之前，在我們還沒進入聖湖的時候……」",
          DialogueId = 6200213,
          GUID = "0F858672",
          NextOptions = {
            [1] = 6200214
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200214] = {
          ContentTC = "只是錯覺吧。",
          DialogueId = 6200214,
          GUID = "0F85869C",
          NextDialogue = 6200215,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200215] = {
          ContentTC = "「嗯，也對。」\n她勾起嘴角笑了笑，像被遮蔽的陽光努力穿越雲層透出了一絲光亮。",
          DialogueId = 6200215,
          GUID = "0F8586C6",
          NextDialogue = 6200216,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200216] = {
          ContentTC = "「和他們失散以後，我已經一個人走了很久、很久。如果不是遇到了你，我都要懷疑自己是受到神罰，掉進什麼地獄了呢。」",
          DialogueId = 6200216,
          GUID = "0F8586F0",
          NextDialogue = 6200217,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200217] = {
          ContentTC = "「也許我只是對<H>活著的生命</>的氣息產生了懷念吧。」",
          DialogueId = 6200217,
          GUID = "0F85871A",
          NextOptions = {
            [1] = 6200218
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200218] = {
          ContentTC = "希望你能早日和同伴會合。",
          DialogueId = 6200218,
          GUID = "0F858744",
          IsKeyOption = true,
          NextDialogue = 6200219,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200219] = {
          ContentTC = "「嗯，謝謝！沒關係啦，他們都是非常厲害的騎士。就算沒有我在，也一定沒問題的。是我必須要找到他們才行……」",
          DialogueId = 6200219,
          GUID = "0F85876E",
          NextDialogue = 6200220,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200220] = {
          ContentTC = "「再見，旅人閣下。祝你也能實現自己的目標。」",
          DialogueId = 6200220,
          GUID = "0F858798",
          NextDialogue = 6200221,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        }
      }
    end
  },
  {
    MinKey = 6200221,
    MaxKey = 6201602,
    Loader = function()
      return {
        [6200221] = {
          ContentTC = "凱希向你揮了揮手，轉身離開了。\n四周又昏暗下去，仿佛長夜從未迎來過天明。",
          DialogueId = 6200221,
          GUID = "0F8587C2",
          RougeTalkActorType = 3
        },
        [6200301] = {
          ContentTC = "斷瓦頹垣，又一片廢墟。\n這並沒有什麼特別的，你在深淵中無數次見過這樣的光景——",
          DialogueId = 6200301,
          GUID = "0F8594E2",
          NextDialogue = 6200302,
          RougeTalkActorType = 3
        },
        [6200302] = {
          ContentTC = "不僅僅是指那些碎裂的建築殘片，還包括那些散落其中不會再被人執起的武器、若隱若現地橫躺在廢墟之下停止了呼吸的身體。血腥味，煙塵味。\n你見得太多了。又是一些自願或不得已被獻祭給「聖湖」的靈魂，僅此而已。",
          DialogueId = 6200302,
          GUID = "0F85950C",
          NextDialogue = 6200303,
          RougeTalkActorType = 3
        },
        [6200303] = {
          ContentTC = "忽然，一枚染血的徽章引起了你的注意——那鳶尾是你再熟悉不過的紋樣。你不久前見過這枚徽章。",
          DialogueId = 6200303,
          GUID = "0F859536",
          NextDialogue = 6200304,
          RougeTalkActorType = 3
        },
        [6200304] = {
          ContentTC = "你撥開碎落的石塊，看到一把血跡斑斑的長劍。它直直地插在地上，或許是因為握著劍的那個人直到最後也不願就此倒下，仍在徒勞地試圖支起身體。",
          DialogueId = 6200304,
          GUID = "0F859560",
          NextDialogue = 6200305,
          RougeTalkActorType = 3
        },
        [6200305] = {
          ContentTC = "然後，你看到了碎裂的法杖、淩亂的斷箭、損毀的手槍。\n現在你知道這些靈魂的名字了。",
          DialogueId = 6200305,
          GUID = "0F85958A",
          NextDialogue = 6200306,
          RougeTalkActorType = 3
        },
        [6200306] = {
          ContentTC = "「心懷信仰，自然不會畏懼」——也不知道，在最後一刻，他們所堅持的信仰是否為他們免除了死亡的苦痛？\n你無從知曉，也不必知曉。",
          DialogueId = 6200306,
          GUID = "0F8595B4",
          NextDialogue = 6200307,
          RougeTalkActorType = 3
        },
        [6200307] = {
          ContentTC = "因為當你下一次撥轉表盤，這一切都會煙消雲散。\n悼念和祈禱並無意義，你也不打算多花費時間。你為逝者闔上雙眼，然後便轉身準備離開。",
          DialogueId = 6200307,
          GUID = "0F8595DE",
          NextDialogue = 6200308,
          RougeTalkActorType = 3
        },
        [6200308] = {
          ContentTC = "「是我必須要找到他們才行……」\n女孩的話語驀然在你腦海中響起，就像是在呼喚你，在提醒你什麼。",
          DialogueId = 6200308,
          GUID = "0F859608",
          NextDialogue = 6200309,
          RougeTalkActorType = 3
        },
        [6200309] = {
          ContentTC = "於是你再次將目光投向那片廢墟，這次你終於察覺到了一絲異樣——儘管那四位年輕騎士的身體都已變得冰冷，但唯有凱希的衣物上沒有沾上黑色的灰燼。\n她的身上只有層層疊疊，乾透了或半乾的穢獸的血跡。",
          DialogueId = 6200309,
          GUID = "0F859632",
          NextOptions = {
            [1] = 6200310
          },
          RougeTalkActorType = 3
        },
        [6200310] = {
          ContentTC = "於是你明白了：她和你一樣來晚了。",
          DialogueId = 6200310,
          GUID = "0F85965C",
          IsKeyOption = true,
          NextDialogue = 6200311,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200311] = {
          ContentTC = "當她找到同伴的時候，他們已然是廢墟中難辨身形的殘骸。",
          DialogueId = 6200311,
          GUID = "0F859686",
          NextDialogue = 6200312,
          RougeTalkActorType = 3
        },
        [6200312] = {
          ContentTC = "所以她留在這裡，不再前進，守著這些一度與她失散的同伴，戰鬥到了最後一刻。\n是為了保護同伴的屍骸嗎？是為了向被她「拋棄」的同伴贖罪嗎？是為了捍衛一位騎士的信條嗎？\n還是漫長的黑暗終於摧毀了她最後的希冀，讓她只能乞求死亡的憐憫？",
          DialogueId = 6200312,
          GUID = "0F8596B0",
          NextDialogue = 6200313,
          RougeTalkActorType = 3
        },
        [6200313] = {
          ContentTC = "她已經不能回答你了。",
          DialogueId = 6200313,
          GUID = "0F8596DA",
          RougeTalkActorType = 3
        },
        [6200401] = {
          ContentTC = "數位年輕人的交談聲從不遠處傳來，你已經很久沒在深淵中聽到這樣的聲音了——熱烈的、鮮活的、尚未被深淵的黑暗侵染的聲音。\n你很確信這聲音的來源並非亡靈，也不是幻影，而是活生生的人類。",
          DialogueId = 6200401,
          GUID = "0F85A54A",
          NextDialogue = 6200402,
          RougeTalkActorType = 3
        },
        [6200402] = {
          ContentTC = "你知道他們是誰。",
          DialogueId = 6200402,
          GUID = "0F85A574",
          NextDialogue = 6200403,
          RougeTalkActorType = 3
        },
        [6200403] = {
          ContentTC = "你循著聲音所在的方向走去。環繞四周的迷霧逐漸散開，你見到了那四位年輕的騎士。\n他們的衣著和裝備尚且未染纖塵，身上的聖鳶尾徽章也光潔鋥亮，反射著不知從哪裡投下的金光。",
          DialogueId = 6200403,
          GUID = "0F85A59E",
          NextDialogue = 6200404,
          RougeTalkActorType = 3
        },
        [6200404] = {
          ContentTC = "「是這個方向沒錯嗎，隊長？」\n年輕的金發女騎士三步並作兩步跨上古舊的台階，又一口氣跳了下來。\n「這看起來只是一座廢墟而已。」",
          DialogueId = 6200404,
          GUID = "0F85A5C8",
          NextDialogue = 6200405,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200405] = {
          ContentTC = "「至少我確定我們沒來過這裡。」\n被稱作隊長的青年騎士邁著沉穩的步伐從她身邊走過。\n「在聖湖裡很難辨別方向，現在也只能走一步算一步了。」",
          DialogueId = 6200405,
          GUID = "0F85A5F2",
          NextDialogue = 6200406,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200406] = {
          ContentTC = "「還有——你這麼上躥下跳的不累嗎，凱希？」\n看著自己那位活潑的同伴，青年無奈地歎了一口氣。\n「這裡的環境凶險，還是謹慎為好，別在戰鬥之外的事情上消耗體力。」",
          DialogueId = 6200406,
          GUID = "0F85A61C",
          NextDialogue = 6200407,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200407] = {
          ContentTC = "「一點也不累！我又不像你——」",
          DialogueId = 6200407,
          GUID = "0F85A646",
          NextOptions = {
            [1] = 6200408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200408] = {
          ContentTC = "他說得沒錯。",
          DialogueId = 6200408,
          GUID = "0F85A670",
          NextDialogue = 6200409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200409] = {
          ContentTC = "女孩被你打斷了話頭，怔怔地轉過頭來。",
          DialogueId = 6200409,
          GUID = "0F85A69A",
          NextDialogue = 6200410,
          RougeTalkActorType = 3
        },
        [6200410] = {
          ContentTC = "「您是……？」",
          DialogueId = 6200410,
          GUID = "0F85A6C4",
          NextOptions = {
            [1] = 6200411
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200411] = {
          ContentTC = "一位旅人。我在這裡待過比你們長的時間，所以，請相信我，這裡遠比你們想象得更可怕。",
          DialogueId = 6200411,
          GUID = "0F85A6EE",
          NextDialogue = 6200412,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200412] = {
          ContentTC = "「旅人……？」青年的臉上掠過一瞬的困惑，和上一次見面時一模一樣。「可此處是艾利西安的聖地……您是怎麼進來的？」",
