            [1] = 6200413
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200413] = {
          ContentTC = "我有自己的理由，以及必須要完成的目標。想必你們也一樣。",
          DialogueId = 6200413,
          GUID = "0F85A742",
          NextDialogue = 6200414,
