        },
        [6200416] = {
          ContentTC = "「聽起來，您似乎知道一些我們不了解的真相——我是指，關於這片深淵的真相。」",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200417] = {
          ContentTC = "「卡莉斯塔……！那是異端者才會使用的不敬之辭！這裡是聖湖——聖湖。」",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04"
        },
        [6200418] = {
          ContentTC = "卡莉斯塔沒有理會他的斥責，依舊直直地看著你，期待著你的答案。",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3
        },
        [6200419] = {
          ContentTC = "你該回答什麼——你能回答什麼？",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3
        },
        [6200420] = {
          ContentTC = "告訴他們立刻回頭？可你明知他們的信仰不會允許他們回頭。\n信仰，一個多麼沉重的詞。它遠比一個陌生的旅人，或者一個面目全非的故人的一句勸告來得有分量。",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3
        },
        [6200421] = {
          ContentTC = "對沐浴在信仰的光輝裡長大的人來說，得知多餘的真相無異於被光灼傷，只留下白晝的刺青——永久的心靈折磨。",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3
        },
        [6200422] = {
          ContentTC = "你搖了搖頭，避開了她的目光。",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3
        },
        [6200423] = {
          ContentTC = "深淵之中容易迷路，要注意別掉隊，凱希。",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200424] = {
          ContentTC = "「嗯？為什麼要特地點我的名字呀？」",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200425] = {
          ContentTC = "「說明你該好好反省一下。連陌生人都能看出來你是最喜歡到處亂竄的那個。」",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200426] = {
          ContentTC = "「哪有——而且就算走散了，我也會很快找到你們的。」女孩撇了撇嘴。",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200427] = {
          ContentTC = "可未必每次都來得及。",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200428] = {
          ContentTC = "凱希愣住了，也許是被你過分認真的語氣嚇到了。",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3
        },
        [6200429] = {
          ContentTC = "這時弗林適時地站了出來，很顯然，他是個合格的艾利西安騎士。對一名優秀的騎士來說，除了純潔的信仰，謹慎也是必要的美德——他知道自己需要把好奇心恰如其分地維持在一個可以獲取情報又不至於招致災禍的尺度。就像當你在聖堂裡發現一扇向來緊鎖的門對你露出了一條誘人的縫隙時，最好的選擇是停下腳步、轉過身、假裝你什麼也沒看見。",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3
        },
        [6200430] = {
          ContentTC = "「雖然不知道閣下的真實身份，但聽起來，您有自己的路要走。我們還有任務在身，就先告辭了。」他鄭重地向你行禮，「願滿月之神護佑您的旅途。」",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200431] = {
          ContentTC = "騎士們結伴離開了，你的眼前又只剩下延綿不絕的迷霧。",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3
        },
        [6200501] = {
          ContentTC = "持續不斷的戰鬥耗盡了你的力氣。\n最後一縷餘燼也從手中流散而去，你徹底迷失了方向。",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3
        },
        [6200502] = {
          ContentTC = "提燈墜落在地，琉璃破碎的聲響如同利刃劃破寂靜的黑暗。\n被切割成碎片的黑暗從四面八方向你湧來，侵蝕你的身體，啃咬你的神經。",
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3
        },
        [6200503] = {
          ContentTC = "當所有的感官都與黑暗融為一體，你忽然不再抗拒，你能感受到它溫柔地包裹著你，接納了你的傷口，撫平了你的疲憊。",
          DialogueId = 6200503,
          GUID = "0F85B606",
          NextDialogue = 6200504,
          RougeTalkActorType = 3
        },
        [6200504] = {
          ContentTC = "也許這才是正確的結局。你似乎聽見那黑暗在對你耳語——\n「堅持到現在，已經足夠了。」",
          DialogueId = 6200504,
          GUID = "0F85B630",
          NextDialogue = 6200505,
          RougeTalkActorType = 3
        },
        [6200505] = {
          ContentTC = "是的……你已經足夠努力了。在一次又一次孤獨的輪回中，你拚命戰鬥過、掙紮過，你品味著無邊無際的痛苦，將絕望當作美酒欣然飲下，卻依舊無法觸及希望的曙光。",
          DialogueId = 6200505,
          GUID = "0F85B65A",
          NextDialogue = 6200506,
          RougeTalkActorType = 3
        },
        [6200506] = {
          ContentTC = "你累了。就到此為止吧。",
          DialogueId = 6200506,
          GUID = "0F85B684",
          NextDialogue = 6200507,
          RougeTalkActorType = 3
        },
        [6200507] = {
          ContentTC = "你覺得自己要在黑暗的搖籃裡沉沉睡去了。可意識中突然浮起一個遙遠的身影——事實上你已經無法記起身影主人確切的樣子，但這縷模糊的思緒卻如同刀鋒切開你逐漸變得遲鈍的血肉，令你清醒。它不斷攪動著思緒的海，卷起潮汐。",
          DialogueId = 6200507,
          GUID = "0F85B6AE",
          NextDialogue = 6200508,
          RougeTalkActorType = 3
        },
        [6200508] = {
          ContentTC = "那是和你約定過一起戰勝黑暗、走出深淵的人，也是，造成你一切痛苦的罪魁禍首。",
          DialogueId = 6200508,
          GUID = "0F85B6D8",
          NextDialogue = 6200509,
          RougeTalkActorType = 3
        },
        [6200509] = {
          ContentTC = "你還沒有找到那個人——沒錯，你想起來了。\n你不能在這裡沉睡。無論黑暗給出的邀約有多麼誘人，那都不是你想要的結局。\n你必須堅持下去，為了抵達終點，為了完成約定——為了斬斷荒謬的輪回。",
          DialogueId = 6200509,
          GUID = "0F85B702",
          NextOptions = {
            [1] = 6200510
          },
          RougeTalkActorType = 3
        },
        [6200510] = {
          ContentTC = "撥動表盤",
          DialogueId = 6200510,
          GUID = "0F85B72C",
          IsKeyOption = true,
          NextDialogue = 6200511,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200511] = {
          ContentTC = "於是你再一次撥動提燈上的表盤，朝向故事的起點。",
          DialogueId = 6200511,
          GUID = "0F85B756",
          RougeTalkActorType = 3
        },
        [6200601] = {
          ContentTC = "深淵中的方向無時無刻不在發生變化，你時常無法分辨自己在前進還是倒退。\n有時你甚至覺得自己被囚禁在首尾相接的螺旋中徒勞地打轉，永遠不可能抵達盡頭。",
          DialogueId = 6200601,
          GUID = "0F85C61A",
          NextDialogue = 6200602,
          RougeTalkActorType = 3
        },
        [6200602] = {
          ContentTC = "但當眼前這個龐然大物出現在視野中的瞬間，你本能地意識到，祂便是這個深淵的「中心」。",
          DialogueId = 6200602,
          GUID = "0F85C644",
          NextDialogue = 6200603,
          RougeTalkActorType = 3
        },
        [6200603] = {
          ContentTC = "你舉起提燈，試圖照亮祂的面龐，但那點可憐的光亮才剛剛觸到祂的邊界便被毫不留情地淹沒。\n四面八方混沌的黑暗如同渾濁的墨水般翻騰流動，湧向同一個目的地。",
          DialogueId = 6200603,
          GUID = "0F85C66E",
          NextDialogue = 6200604,
          RougeTalkActorType = 3
        },
        [6200604] = {
          ContentTC = "地面轟隆隆地震動起來，你失去支撐，跌進了黑暗中。\n恍惚間，你覺得自己的身體似乎也成為了那濁流的一部分，正在潰散、融化，流向那個吞噬一切的存在。",
          DialogueId = 6200604,
          GUID = "0F85C698",
          NextDialogue = 6200605,
          RougeTalkActorType = 3
        },
        [6200605] = {
          ContentTC = "刺耳的寂靜碾壓著鼓膜，求生的本能告訴你現在必須回頭。",
          DialogueId = 6200605,
          GUID = "0F85C6C2",
          NextOptions = {
            [1] = 6200606,
            [2] = 6200615
          },
          RougeTalkActorType = 3
        },
        [6200606] = {
          ContentTC = "繼續直視混沌",
          DialogueId = 6200606,
          GUID = "0F85C6EC",
          IsKeyOption = true,
          NextDialogue = 6200607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200607] = {
          ContentTC = "你沒有退縮。\n你從黑暗中支起身體，抬高頭顱，緊握著手中的提燈，向那不可名狀的存在宣示：你並不畏懼它。",
          DialogueId = 6200607,
          GUID = "0F85C716",
          NextDialogue = 6200608,
          RougeTalkActorType = 3
        },
        [6200608] = {
          ContentTC = "慢慢地，你感覺到有什麼東西撬動了四周的混沌，漏出一絲縫隙，自深不可測的黑暗中，有一些東西反過來鑽進了你的心臟——不可思議的是，你竟然能夠理解它們。",
          DialogueId = 6200608,
          GUID = "0F85C740",
          NextDialogue = 6200609,
          RougeTalkActorType = 3
        },
        [6200609] = {
          ContentTC = "那是屬於人類的感情：疑惑、憤怒、痛苦、絕望，還有……悲傷。壓倒一切的悲傷。\n——仿佛這片深淵本身也在期待著一種終結。",
          DialogueId = 6200609,
          GUID = "0F85C76A",
          NextDialogue = 6200610,
          RougeTalkActorType = 3
        },
        [6200610] = {
          ContentTC = "「我該怎麼幫助你呢？」你不禁在心中問道。",
          DialogueId = 6200610,
          GUID = "0F85C794",
          NextDialogue = 6200611,
          RougeTalkActorType = 3
        },
        [6200611] = {
          ContentTC = "這盞提燈還不夠明亮。繼續你的旅途吧。祂說。在輪回的終點，你將會得到答案。",
          DialogueId = 6200611,
          GUID = "0F85C7BE",
          NextDialogue = 6200612,
          RougeTalkActorType = 3
        },
        [6200612] = {
          ContentTC = "「終點在哪裡？」你又問。",
          DialogueId = 6200612,
          GUID = "0F85C7E8",
          NextDialogue = 6200613,
          RougeTalkActorType = 3
        },
        [6200613] = {
          ContentTC = "祂沒有回答這個問題，只是用黑暗溫柔地包圍了你，你的視野中只剩下提燈的光芒。",
          DialogueId = 6200613,
          GUID = "0F85C812",
          NextDialogue = 6200614,
          RougeTalkActorType = 3
        },
        [6200614] = {
          ContentTC = "於是你撥動提燈上的表盤，讓時間再次倒轉。",
          DialogueId = 6200614,
          GUID = "0F85C83C",
          RougeTalkActorType = 3
        },
        [6200615] = {
          ContentTC = "回頭",
          DialogueId = 6200615,
          GUID = "0F85C866",
          IsKeyOption = true,
          NextDialogue = 6200616,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200616] = {
          ContentTC = "明智的選擇。\n回頭，轉身，邁出步伐。本能驅使你逃離——儘管你知道，你已無法尋回行過的路。",
          DialogueId = 6200616,
          GUID = "0F85C890",
          NextDialogue = 6200617,
          RougeTalkActorType = 3
        },
        [6200617] = {
          ContentTC = "忽然，你感覺到了一道來自背後的視線——祂正無言地注視著你，似是為你的離去感到悲傷。",
          DialogueId = 6200617,
          GUID = "0F85C8BA",
          NextDialogue = 6200618,
          RougeTalkActorType = 3
        },
        [6200618] = {
          ContentTC = "「你希望我回頭嗎？」你不禁在心中問道。",
          DialogueId = 6200618,
          GUID = "0F85C8E4",
          NextDialogue = 6200619,
          RougeTalkActorType = 3
        },
        [6200619] = {
          ContentTC = "不，你要沿著自己的道路前進。祂說。在輪回的終點，我們自會重逢。",
          DialogueId = 6200619,
          GUID = "0F85C90E",
          NextDialogue = 6200620,
          RougeTalkActorType = 3
        },
        [6200620] = {
          ContentTC = "「終點在哪裡？」你又問。",
          DialogueId = 6200620,
          GUID = "0F85C938",
          NextDialogue = 6200621,
          RougeTalkActorType = 3
        },
        [6200621] = {
          ContentTC = "祂沒有回答這個問題，黑暗越過你的肩頭，溫柔地填滿了四周的空間，你的視野中只剩下提燈的光芒。",
          DialogueId = 6200621,
          GUID = "0F85C962",
          NextDialogue = 6200622,
          RougeTalkActorType = 3
        },
        [6200622] = {
          ContentTC = "於是你撥動提燈上的表盤，讓時間再次倒轉。",
          DialogueId = 6200622,
          GUID = "0F85C98C",
          RougeTalkActorType = 3
        },
        [6200701] = {
          ContentTC = "神秘的青年站在篝火邊。事實上你並不確定他的年歲，只是通過聲音如此推斷。\n這不是你第一次見到他。",
          DialogueId = 6200701,
          GUID = "0F85D682",
          NextDialogue = 6200702,
          RougeTalkActorType = 3
        },
        [6200702] = {
          ContentTC = "「又見面了，勇敢的旅人。」",
          DialogueId = 6200702,
          GUID = "0F85D6AC",
          NextDialogue = 6200703,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200703] = {
          ContentTC = "青年禮貌地向你致候。\n你看不到他的眼睛——他戴著一張尖銳的金屬面具，完全覆蓋了臉龐的上半部分。",
          DialogueId = 6200703,
          GUID = "0F85D6D6",
          NextDialogue = 6200704,
          RougeTalkActorType = 3
        },
        [6200704] = {
          ContentTC = "「在深淵中行走太久的人大多會迷失前路，最終成為那些幽影的一部分。」\n「這些物事散發的<H>光</>將會為你指引道路，使你不至於前路盡失。」他說，「你可以將它們放置於提燈之中，作為燭芯。」\n代替他的目光閃爍著的，是金屬反射篝火的光澤。",
          DialogueId = 6200704,
          GUID = "0F85D700",
          NextDialogue = 6200705,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200705] = {
          ContentTC = "「不過，我想你從未遺忘這些。因為你<H>總是</>會抵達這兒。」\n「我照舊準備了補給，就在那從篝火旁，請隨時取用。」",
          DialogueId = 6200705,
          GUID = "0F85D72A",
          NextOptions = {
            [1] = 6200706
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200706] = {
          ContentTC = "你是誰？",
          DialogueId = 6200706,
          GUID = "0F85D754",
          NextDialogue = 6200707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200707] = {
          ContentTC = "「你又問了這個問題。你問過很多很多次。但是請寬恕現在的我無法做出回答。」\n「我並非有意向你隱瞞，只是連我自己也不確定，此時此刻存在於此處的我究竟該以何種身份自居。」\n青年發出了一聲輕笑。",
          DialogueId = 6200707,
          GUID = "0F85D77E",
          NextDialogue = 6200708,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200708] = {
          ContentTC = "「所以，就讓我們輕鬆一些吧——你只要將我當做一介普通的<H>商人</>就好。」\n「正如你總說，你只是一位普通的旅人。」",
          DialogueId = 6200708,
          GUID = "0F85D7A8",
          NextOptions = {
            [1] = 6200709
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200709] = {
          ContentTC = "我該出發了。",
          DialogueId = 6200709,
          GUID = "0F85D7D2",
          IsKeyOption = true,
          NextDialogue = 6200710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200710] = {
          ContentTC = "「再見，勇敢的旅人。」他說，「願你的旅途燈火長明。」\n你依舊看不見他的表情。或許面具之下的瞳孔中，也有搖曳的燈火倒映。",
          DialogueId = 6200710,
          GUID = "0F85D7FC",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200801] = {
          ContentTC = "深淵行商佇立在篝火旁，如此前的每一次。\n這裡沒有幽影的嘯叫，只有寂靜環繞。",
          DialogueId = 6200801,
          GUID = "0F85E6EA",
          NextDialogue = 6200802,
          RougeTalkActorType = 3
        },
        [6200802] = {
          ContentTC = "「又見面了，彷徨的旅人。」\n「你為這些微弱的<H>光</>而來。」\n深淵行商的聲音一如既往沉靜，如無波的湖水。\n「而我靜候於此，為這盞提燈添上一枚新的燭芯。」",
          DialogueId = 6200802,
          GUID = "0F85E714",
          NextOptions = {
            [1] = 6200803
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200803] = {
          ContentTC = "為什麼不能直接送給我呢？",
          DialogueId = 6200803,
          GUID = "0F85E73E",
          NextDialogue = 6200804,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200804] = {
          ContentTC = "「如你所見，我已經不再擁有那般力量。」\n商人搖了搖頭。\n「如今的我能做的，便只有以微末魔法，將你那些小小的餘燼化為微光的燭芯。」",
          DialogueId = 6200804,
          GUID = "0F85E768",
          NextDialogue = 6200805,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200805] = {
          ContentTC = "深淵行商接過提燈。\n在他的手中，餘燼漸漸亮起，如紛飛的螢火，最終凝成明亮的燭芯。",
          DialogueId = 6200805,
          GUID = "0F85E792",
          NextOptions = {
            [1] = 6200806
          },
          RougeTalkActorType = 3
        },
        [6200806] = {
          ContentTC = "那麼，謝謝你。",
          DialogueId = 6200806,
          GUID = "0F85E7BC",
          NextDialogue = 6200807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200807] = {
          ContentTC = "你晃了晃手中的提燈——注入了燭芯，原本微茫的燈光似乎明亮了幾分。\n這盞燈是你唯一的陪伴。在這晦暗、幽邃的深淵中，只有它保護著你不至迷失。",
          DialogueId = 6200807,
          GUID = "0F85E7E6",
          NextOptions = {
            [1] = 6200808
          },
          RougeTalkActorType = 3
        },
        [6200808] = {
          ContentTC = "我該出發了。",
          DialogueId = 6200808,
          GUID = "0F85E810",
          IsKeyOption = true,
          NextDialogue = 6200809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200809] = {
          ContentTC = "「再見，彷徨的旅人。」他說，「願你的旅途燈火長明。」",
          DialogueId = 6200809,
          GUID = "0F85E83A",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200901] = {
          ContentTC = "又一次地，你來到了這裡。\n如果說這片黑暗還有什麼地方能讓你感到短暫的安心，那便是這裡。",
          DialogueId = 6200901,
          GUID = "0F85F752",
          NextOptions = {
            [1] = 6200902
          },
          RougeTalkActorType = 3
        },
        [6200902] = {
          ContentTC = "你還在這兒。",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200903] = {
          ContentTC = "「是的。」\n商人依舊沉靜而溫和。\n「在協助你終結這裡的黑暗之前，我會一直在這裡。」",
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200904] = {
          ContentTC = "可是除了你之外，沒有人會記得我。",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200905] = {
          ContentTC = "「深淵中的那些……幽靈，還有少數人類——當我撥動表盤回到過去，他們便不會再記得我。仿佛我們從未見過、從未說過話。」\n「即使我救下活著的人，下一次他們中的很多人依舊會死去。」\n「即使我遇到很多人，最終還是孑然一身。」",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200906] = {
          ContentTC = "「是的。深淵的一切如潮水般往復，一遍又一遍被推回往昔歲月。」\n「但你是特別的——作為那面表盤現在的主人，你已經立於時間之外。」\n他歎了口氣。",
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200907] = {
          ContentTC = "「在這片深淵裡，你主宰著時間。只有你是<H>永恒的</>。這是神的權柄。」\n「但正是它讓你成為一個神座上的囚徒。它意味著你必須親眼看著一切從你身邊無可避免地失去。」\n行商平靜的聲音中有一絲不易察覺的波動。\n「但它也是你能與深淵本身對抗的唯一方式。」",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200908] = {
          ContentTC = "我該出發了。",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200909] = {
          ContentTC = "「再見，孤獨的旅人。」他說，「願你的旅途燈火長明。」",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201001] = {
          ContentTC = "你再度得到了短暫的喘息。\n沒有幽影的糾纏，沒有靈魂的哀鳴。這裡是安全的。\n你靠著一截斷牆緩緩滑坐下去。",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3
        },
        [6201002] = {
          ContentTC = "我累了。",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201003] = {
          ContentTC = "「一遍又一遍地前進，一遍又一遍地重來。」\n「我知道這是我的戰鬥，但我不知道它還會持續多久。」",
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201004] = {
          ContentTC = "「當神的賜福——<H>純淨琉璃</>再度彙聚，提燈被修復，奇跡便會從中顯露。」\n「你將獲得足以撕裂這片黑暗的光。」",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201005] = {
          ContentTC = "不，我想知道的不是這個。",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201006] = {
          ContentTC = "「我甚至不知道我在這裡度過了多久——十年？二十年？還是更長時間？我唯一知道的就是我撥動了多少次表盤。」\n「可這盞燈的光芒還是如此微弱，仿佛我所做的一切都毫無意義。」\n「會不會直到我死，我還是無法修復它——那麼我經曆的這些又算什麼？」\n「一出愚蠢而荒誕的悲劇？」",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201007] = {
          ContentTC = "「是的。」\n他沒有否認，這讓你有些驚訝。",
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201008] = {
          ContentTC = "「我看到你一遍又一遍地揮動兵刃，驅散幽影，正如我看到萬個工匠日復一日地打磨巨石為神殿築基。」\n「我看到一個女孩周而復始地向火焰裡投下石子，正如我看到萬個農人年復一年地在田地裡播撒種子。」\n「一切辛勞，都只是為了下一次重復同樣的辛勞。不只是你與我，深淵裡的靈魂，以及地上的生者，所有人都在重復著這場悲劇。」\n「若你為此感到痛苦，你隨時可以停下來，這樣便可以結束這一切。」",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201009] = {
          ContentTC = "拒絕。",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201010] = {
          ContentTC = "結束這一切——意味著你將成為和它們一樣的一縷幽魂。\n你將不再有柔軟而敏感的心。你不再懼怕孤獨，也不再因周而復始的荒誕而痛苦。\n但是——這樣，就是幸福麼？",
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3
        },
        [6201011] = {
          ContentTC = "「不。」你重新撿起兵刃。\n「我會繼續戰鬥下去。繼續去尋找那些該死的琉璃。」",
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201012] = {
          ContentTC = "我該出發了。",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201013] = {
          ContentTC = "「再見，志堅的旅人。」他說，「願你的旅途燈火長明。」",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201101] = {
          ContentTC = "深淵行商從你手中接過提燈。未曾言語，你們默契地交換著餘燼與燭芯。\n這一次，你並沒有打算在這裡逗留。",
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3
        },
        [6201102] = {
          ContentTC = "我該出發了。",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201103] = {
          ContentTC = "「請收下這個。」\n青年的聲音在身後響起。他將一件物事交到你手上。\n「它不會發光，所以它不需餘燼交換。」\n那是一枚糖果，晶瑩而透明，靜靜地躺在你沾滿血汙和灰燼的手心裡。",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201104] = {
          ContentTC = "你將它緩緩吞入口中，是野薄荷的味道。它讓你前所未有地清醒，你終於找回了一些人的知覺。\n你的腦海裡不再只有幽影。你開始想起聳入雲端的高塔，想起總是忍不住攀爬的橡子樹，想起餐盤上冰涼的奶油，想起庭院裡擺蕩的秋千。\n那是你活過的證明。",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3
        },
        [6201105] = {
          ContentTC = "那麼，這位神秘的深淵行商呢？你甚至不知道他是一個人，還是一個幽靈——他也會喜歡甜味嗎？他會因困在深淵的囚籠裡痛苦嗎？他也曾在深淵之上——在太陽能照射到的世界真切地活過嗎？\n但你沒有時間思考這些了。\n你必須戰鬥下去，永不停息。",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3
        },
        [6201106] = {
          ContentTC = "「再見，清醒的旅人。」他說，「願你的旅途燈火長明。」",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201201] = {
          ContentTC = "最近你已經開始不那麼疲憊了，甚至可以輕鬆地和那些幽影攀談。\n你不知道是你的心真的開始變得堅硬，麻木，還是這只是一次崩毀的前兆。\n但至少此刻，你心情尚可。",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3
        },
        [6201202] = {
          ContentTC = "「我在一天同時遇到了滿月的信徒和暗月的信徒。」\n「一個說自己信仰光明，一個說自己侍奉黑暗。但好笑的是，當你說你對他們的神不感興趣的時候，他們口中卻吐出同樣的粗鄙之言。」\n「那麼，你呢？你有信奉的神嗎？」",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201203] = {
          ContentTC = "「我是芙薩的侍者。」\n這是行商頭一次回答關於他自己的問題。\n「我尊祂的名，讚頌祂的慈愛，敬奉滿月的光輝。」",
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201204] = {
          ContentTC = "深淵行商的話讓你感到有些意外——你以為他會做出些更有趣的回答。",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3
        },
        [6201205] = {
          ContentTC = "「所以，你相信艾利西安正教的那些教義嘍？」\n「只要向滿月女神虔誠祈禱，祂就會織造幸福的絲線，將我們拯救。」",
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201206] = {
          ContentTC = "「不。我<H>追隨</>芙薩，但我並不<H>相信</>芙薩。」\n「我只是需要一個確定的理由，讓我走上我認為正確的道路。」",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201207] = {
          ContentTC = "我不明白你的意思。",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201208] = {
          ContentTC = "「我們應施與，不應掠奪。」\n「我們應友愛，不應憎恨。」\n「我們應擁抱他人，不應割傷他人。」\n「這是我所認為的『正確』——但如果我相信人是自由的，那我便找不到什麼來證明它們正確。」",
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201209] = {
          ContentTC = "「所以我拋棄了『自由』，選擇超越一切的芙薩。這樣，我所認為的正確就成為了確鑿無瑕、無需證明的真理。」\n他歎了口氣。\n「某種意義上，也許我才是對芙薩最不敬的那個。」",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201210] = {
          ContentTC = "「所以你的意思是……」\n你在腦海中組織著語言。\n「我想說服自己在這片深淵繼續走下去，我就信奉一個……呃，行走之神，來說服自己必須走下去？」",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201211] = {
          ContentTC = "「嗯……你可以這樣理解。」\n他輕笑了一下。",
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201212] = {
          ContentTC = "真是個怪傢伙。不過我該走了，我已經逗留了太久。",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201213] = {
          ContentTC = "「再見，聰慧的旅人。」他說，「願你的旅途燈火長明。」",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201301] = {
          ContentTC = "「我已經很久沒有休息過了。」\n在來到這兒之前，你便在盤算這一次的交易。\n「我能向你買一樣東西麼——買一場夢？」\n「如果你能做到。」",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201302] = {
          ContentTC = "「我不是築夢師，無法保證提供你想要的東西。」\n他緩緩搖了搖頭。\n「但或許我可以嚐試。\n「很久很久之前，當我給我的同胞姊妹講故事時，她總是睡得很香甜。」",
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201303] = {
          ContentTC = "你找了一疊草垛，儘量把它鋪得鬆軟一些。\n你又一次感到疲憊了。你渴望一場夢，一場短暫的休憩。",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3
        },
        [6201304] = {
          ContentTC = "「很久很久以前，有一個少年，他是一名雕金匠；他愛上了月亮。」\n「他悄悄測量了月亮的尺寸，打算用世間最璀璨的寶石，打造一條最美的項鏈送給彎彎的月亮作為禮物。」\n「可當他終於打造出那條項鏈時，卻發現月亮長胖了一些，已經戴不上那條漂亮的項鏈了。」\n「於是他決定重新打造一條項鏈。這一次他把自己收集的所有寶石都鑲上去了。可當他再度見到月亮時，月亮已經更胖了，像一只圓滾滾的盤子。」",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201305] = {
          ContentTC = "這是一個古老的童話。你依稀記得你的母親也曾講過這個故事。\n你腦中泛起稀薄的睡意。",
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3
        },
        [6201306] = {
          ContentTC = "「……那就打造三條不同尺寸的吧，總有一條月亮能戴上。年輕的雕金匠想。」\n「但當他向心愛的月亮奉上三條項鏈時，月亮卻消失了——漆黑的天幕面有點點繁星，仿佛月亮從不曾來過。」",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201307] = {
          ContentTC = "你緩緩沉入銀輝的夢鄉。",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3
        },
        [6201308] = {
          ContentTC = "「……於是，弄丟了月亮的雕金匠日復一日地敲著鐵錘，徒勞無功地做著項鏈。」\n「他的眼淚落在大地上，長出透亮的樹木，結出晶瑩的果實，像他摯愛的月亮一樣。」\n「後來的人們稱它們為『天之樹』和『月石』……」\n「疲憊的旅人，你已經睡了嗎？那就做個好夢吧。」",
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201309] = {
          ContentTC = "第一個夢裡，你看見秋千在庭院的花園裡擺蕩。\n你變得那麼小。年邁的管家站在秋千旁，向你伸出雙臂，等著你撲進他的懷抱。\n「歡迎回來，我的▇▇。」\n……",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3
        },
        [6201310] = {
          ContentTC = "第二個夢裡，你看見年輕的騎士們站在百裡香盛放的山坡上。\n他們高舉著金色鳶尾的旗幟，發絲在風中飛揚。他們笑著，呼喊著你的名字。\n「出發吧，我的▇▇大人。」\n……",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3
        },
        [6201311] = {
          ContentTC = "第三個夢裡，你看見那個和你提著同樣提燈的旅人。你曾見過{性别：他|她}三次。\n{性别：他|她}的身影越來越遠，就要沒入幽邃的黑暗。\n你跑過去，三步並作兩步。",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3
        },
        [6201312] = {
          ContentTC = "「你可以留下來嗎？」\n你喊出聲，嗓音嘶啞，這比任何一次戰鬥都要令你狼狽。",
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201313] = {
          ContentTC = "「對不起，▇▇。」\n{性别：他|她}回過頭，搖曳的燈火照亮了{性别：他|她}的臉，你卻看不真切。\n「我們走在<H>反方向的路</>上。所以，我必須離開了。」",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201314] = {
          ContentTC = "「但是——我已經不想再一個人了！」\n你試圖拉住那個人的衣角——像頑劣的孩童索要最後一粒糖果——但你什麼也沒有抓到。\n你流下眼淚——你已經多久沒有流過淚了？",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201315] = {
          ContentTC = "「別哭，▇▇。」\n{性别：他|她}撫摸著你的臉頰，拭去淚水，溫柔而慈悲。你感受到{性别：他|她}的呼吸，感受到人類的體溫。\n「我們的路是<H>一個圓環</>。所以就算向著反方向行走，我們也一定會再度重逢。」",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201316] = {
          ContentTC = "你看到{性别：他|她}手中的提燈漸漸亮起來，發出銀白色的光輝，越來越亮，像一輪正在傾灑銀縷的滿月——\n{性别：他|她}步入了那灼目的銀白中。\n……\n……\n你在野薄荷的氣息中醒來。",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3
        },
        [6201317] = {
          ContentTC = "「是個好夢嗎？」",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201318] = {
          ContentTC = "「是的……它很長、很長。像過了很多很多年那樣長。」",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201319] = {
          ContentTC = "「這很好。很幸運，你還可以做夢。」",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201320] = {
          ContentTC = "你站起身，握緊提燈。你將繼續奔赴你的戰爭——\n一場看不見盡頭的孤旅。",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3
        },
        [6201321] = {
          ContentTC = "謝謝你，我該走了。",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201322] = {
          ContentTC = "「再見，堅忍的旅人。」他說。\n「願某個未來裡，你的旅途不再是孤身一人。」",
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201401] = {
          ContentTC = "黑暗、黑暗、以及更深的黑暗——\n你感到自己正在寂靜的水底漂遊。\n沿著幽深的河流，一路向下。",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3
        },
        [6201402] = {
          ContentTC = "——而後，由遠及近地，你看到了光。\n那是一盞<H>燈</>。",
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3
        },
        [6201403] = {
          ContentTC = "「你回來了。我知道，你會回來。」\n搖曳的燈火照亮了執燈人的面龐，那是一位蒼老的婦人。",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201404] = {
          ContentTC = "你認識我？",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201405] = {
          ContentTC = "「是的。」\n她蒼老的眼睛泛起光亮，像枯死的朽木綻放出花。\n「我已經等了你很久很久。」",
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201406] = {
          ContentTC = "我好像記不起我是誰。",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201407] = {
          ContentTC = "「我們走過的路是<H>一個圓環</>。」\n她笑了起來。\n「當你再度回到這裡，你便已然記起一切。」",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201408] = {
          ContentTC = "我接下來應當做什麼？",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201409] = {
          ContentTC = "「離開這兒，離開這片<H>深淵</>。這是<H>每一個你</>的夙願。」\n老婦人把提燈交到你手上。她的手指冰涼，像一個幽靈。那盞提燈卻散發著金黃的光，熾烈的，溫暖的。\n你留意到，燈上鑲嵌著一個有<H>刻度</>的表盤。",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201410] = {
          ContentTC = "我如何才能離開這兒？",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201411] = {
          ContentTC = "「這是一盞被神賜福的燈。」\n「當你用足夠多的<H>純淨琉璃</>最終修復它，它便會在這片深淵的海中分開道路。」\n「若你遇到致命的危險，便<H>倒轉</>那個表盤。」",
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201412] = {
          ContentTC = "「踏上旅途前，也許你會想聽些關於這片深淵的故事。」\n她依舊靜默而溫和地微笑著。\n「這些故事是時間河流中漂浮的木片——我說過，我們走過的路是一個圓環——它們於你而言可能是『過去』的故事，也可能是『未來』的故事。」\n「但毫無疑問，<H>它們是關於你的故事</>。」",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201501] = {
          ContentTC = "你聽見一陣腳步聲自黑暗中傳來，沉悶而拖遝，帶著沙沙的尾音。\n你朝著腳步聲所在的方向前進，四個年輕的身影出現在你的眼前——是靜默黃昏小隊的騎士們，你的道路再次與他們交彙了。他們看起來還平安無事，只是神情已與上一次相遇時天差地別。",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3
        },
        [6201502] = {
          ContentTC = "「還要繼續走嗎？我們已經走了多久了？」\n術士的嗓音被疲憊填滿，仿佛她背上披著的並非一件鬥篷，而是一塊厚重的石板。",
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201503] = {
          ContentTC = "「大概……四天？五天……？也可能更久。我的懷表已經失靈了。」\n司祭的聲音像刀片刮過紙張的毛邊；即便虔誠如他，也無法再維持平素那種恭謹的語氣了。",
          DialogueId = 6201503,
          GUID = "0F865A16",
          NextDialogue = 6201504,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201504] = {
          ContentTC = "「既然大家都累了，就在這裡停下休整吧。你們可以睡一會兒，我會留意周圍的動靜。」\n青年體貼地說道，儘管他自己的聲音也透露出分明的倦意。",
          DialogueId = 6201504,
          GUID = "0F865A40",
          NextDialogue = 6201505,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201505] = {
          ContentTC = "「我和你一起吧，這樣萬一我們兩個中有誰不小心睡著了，還能互相叫醒一下！」\n她盡可能地以輕鬆的口吻說出了這個提議，並在弗林一臉自責地想要開口說「抱歉」之前用眼神製止了他。",
          DialogueId = 6201505,
          GUID = "0F865A6A",
          NextDialogue = 6201506,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201506] = {
          ContentTC = "於是，四人找到一片還算平整的地面，將身上的行囊放下，搭建了起簡陋的臨時營地。\n在卡莉斯塔和米爾頓開始休息之後，弗林和凱希稍微走遠了一些。沉默籠罩著他們的背影，畫面仿佛定格了。\n忽然，弗林低下頭，用只有自己和凱希能聽到的音量輕輕地歎了一口氣。",
          DialogueId = 6201506,
          GUID = "0F865A94",
          NextDialogue = 6201507,
          RougeTalkActorType = 3
        },
        [6201507] = {
          ContentTC = "「哎呀，難得聽到你歎氣哦。」女孩笑眯眯地從口袋裡掏出一個小紙包，「要不要吃顆糖？我偷偷帶進來的。只剩兩顆了，我們分掉吧。」",
          DialogueId = 6201507,
          GUID = "0F865ABE",
          NextDialogue = 6201508,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201508] = {
          ContentTC = "「……不用了，謝謝。既然你愛吃，還是自己留著吧。」",
          DialogueId = 6201508,
          GUID = "0F865AE8",
          NextDialogue = 6201509,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201509] = {
          ContentTC = "「糖果要和朋友一起分享才更甜喔。」",
          DialogueId = 6201509,
          GUID = "0F865B12",
          NextDialogue = 6201510,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201510] = {
          ContentTC = "凱希將一顆糖丟進嘴裡，然後執意把剩下的最後一顆連著糖紙一起塞到了弗林手中。然而弗林只是沉默地低著頭，沒有任何反應。\n凱希沒有再說什麼，一邊抿著糖果，一邊靜靜地等待——等待她的友人整理好思緒，再次開啟這段對話。",
          DialogueId = 6201510,
          GUID = "0F865B3C",
          NextDialogue = 6201511,
          RougeTalkActorType = 3
        },
        [6201511] = {
          ContentTC = "「剛才那個……拿著劍的幽影……你看見了嗎？」\n終於，青年低聲開口道。",
          DialogueId = 6201511,
          GUID = "0F865B66",
          NextDialogue = 6201512,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201512] = {
          ContentTC = "「你是指那個敵我不分、連幽影都砍的傢伙嗎？我當然看見了，他那把銀劍發出的白光亮得晃眼，簡直就和傳說中你那位偶像用的武器一樣……呢……」\n說到這裡，女孩似乎意識到了什麼，轉頭看向弗林。\n「難道……他就是那位<H>月升時</>的騎士嗎？」",
          DialogueId = 6201512,
          GUID = "0F865B90",
          NextDialogue = 6201513,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201513] = {
          ContentTC = "「……是的。就是他。我看過無數遍與他有關的影像和畫冊，不會認錯。」\n青年歎了一口氣，用雙手捂住了自己的臉。\n「我……說真的，認出他的那一刻，我感到很害怕。如果連他都輸給了深淵，我們又要怎麼贏呢？我忍不住想，我最後是不是也會變成那樣？我……也會變成向著同胞揮劍的人嗎？」",
          DialogueId = 6201513,
          GUID = "0F865BBA",
          NextDialogue = 6201514,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201514] = {
          ContentTC = "「確實，在進入深淵之前，我們都沒想到這個地方會如此可怕……但我還是相信，即便如此，人類的意志也一定能夠贏過它。」\n女孩輕輕地拍了拍友人的後背。\n「你想啊，那位騎士會攻擊其他幽影，不正說明他沒有認輸嗎？即便變成這副模樣，他也還記得最初的目標，不是嗎？」",
          DialogueId = 6201514,
          GUID = "0F865BE4",
          NextDialogue = 6201515,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201515] = {
          ContentTC = "「嗯……」",
          DialogueId = 6201515,
          GUID = "0F865C0E",
          NextDialogue = 6201516,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201516] = {
          ContentTC = "這似乎不是一個適合加入談話的時機，你也無意打擾這些年輕人的休息。\n但正當你打算離開時，凱希發現了你。",
          DialogueId = 6201516,
          GUID = "0F865C38",
          NextDialogue = 6201517,
          RougeTalkActorType = 3
        },
        [6201517] = {
          ContentTC = "「咦？」女孩激動地向你走過來，「您是之前那位旅人！太好了，您還平安無事呀！」",
          DialogueId = 6201517,
          GUID = "0F865C62",
          NextDialogue = 6201518,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201518] = {
          ContentTC = "青年也跟著走過來，神色頗有些驚訝。\n「閣下果然並非一般人物。您比我們更早進入深淵，究竟是如何做到保持意志堅定的？」",
          DialogueId = 6201518,
          GUID = "0F865C8C",
          NextOptions = {
            [1] = 6201519
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201519] = {
          ContentTC = "我……只是習慣了而已。我也曾經迷茫過、後悔過、絕望過，但現在，我已經接受了。",
          DialogueId = 6201519,
          GUID = "0F865CB6",
          NextDialogue = 6201520,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201520] = {
          ContentTC = "青年臉上的驚訝慢慢轉變為欽佩。\n「那麼……您是如何看待深淵的呢？您認為，人類會戰勝它嗎？」",
          DialogueId = 6201520,
          GUID = "0F865CE0",
          NextOptions = {
            [1] = 6201521,
            [2] = 6201524
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201521] = {
          ContentTC = "一定會的。",
          DialogueId = 6201521,
          GUID = "0F865D0A",
          IsKeyOption = true,
          NextDialogue = 6201522,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201522] = {
          ContentTC = "「你看，旅人閣下也這麼說。我們一定能完成任務的，要打起精神來呀！」",
          DialogueId = 6201522,
          GUID = "0F865D34",
          NextDialogue = 6201523,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201523] = {
          ContentTC = "她似乎誤解了你的意思。你所相信的「勝利」，與傳頌會下達給這些騎士的目標截然不同。\n你很清楚，前方等待著他們的只有痛苦和絕望。他們注定會一遍遍地經曆死亡，卻對自己身處的地獄一無所知。\n但你沒有再開口。如果未來無法改變，那麼無知也是一種幸福。",
          DialogueId = 6201523,
          GUID = "0F865D5E",
          RougeTalkActorType = 3
        },
        [6201524] = {
          ContentTC = "我不知道。",
          DialogueId = 6201524,
          GUID = "0F865D88",
          IsKeyOption = true,
          NextDialogue = 6201525,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201525] = {
          ContentTC = "「連您也沒有信心嗎……」\n青年的目光黯淡下去。但很快，他又重新抬起頭，以一種異常堅定的聲音開口——你不知道他到底是在鼓勵自己，還是在欺騙自己。\n「無論如何，作為艾利西安的騎士，我們不能退縮。哪怕真的沒有希望，我們也一定會戰鬥到最後一刻。」",
          DialogueId = 6201525,
          GUID = "0F865DB2",
          NextDialogue = 6201526,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201526] = {
          ContentTC = "你很清楚，前方等待著他們的只有痛苦和絕望。他們注定會一遍遍地經曆死亡，卻對自己身處的地獄一無所知。\n但看著騎士堅定的目光，你終究不忍心再開口。",
          DialogueId = 6201526,
          GUID = "0F865DDC",
          RougeTalkActorType = 3
        },
        [6201601] = {
          ContentTC = "鋼鐵碰撞的激鳴聲自黑暗中傳來，前方顯然正在發生一場惡戰。\n你看到年輕的騎士奮力舉起長劍，給予面前的幽影最後一擊。",
          DialogueId = 6201601,
          GUID = "0F866A2A",
          NextDialogue = 6201602,
          RougeTalkActorType = 3
        },
        [6201602] = {
          ContentTC = "忽然間，一道纖細的黑影劃過。騎士迅速地舉起盾牌，防住了這次偷襲。但當他看清楚那支插在盾牌裂口裡的細箭時，他愣住了。\n箭羽上裝飾著象征艾利西安的金色聖鳶尾紋，但底色卻被塗成了黑色。只有一個人會這麼",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6201603,
    MaxKey = 10011708,
    Loader = function()
      return {
        [6201603] = {
          ContentTC = "「卡莉斯塔……？」",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201604] = {
          ContentTC = "幽影步步逼近，被黑暗侵蝕的肢體幾乎與身上的鬥篷融為一體。「她」對弗林的呼喚置若罔聞，只是沉默著再一次搭箭引弓。",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3
        },
        [6201605] = {
          ContentTC = "早在最初進入深淵的時候，他們四人就驚訝地發現，那些具有攻擊性的人形幽影中有相當一部分是熟識的身影。那些人都是艾利西安的騎士，為了討伐深淵而來，卻在死後被同化為深淵的一部分，對曾經的同伴拔刀相向。",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3
        },
        [6201606] = {
          ContentTC = "這便是深淵最可怖的詛咒——「活著」本身即是詛咒。若一個人進入深淵沒多久便死去，他尚且可以成為一個最普通不過的亡靈，像他生前的樣子。",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3
        },
        [6201607] = {
          ContentTC = "但倘若他不願輕易死去，而是選擇前進，那麼在深淵中度過的每一分、每一秒，混沌的黑暗都將不斷侵蝕他的意志。到最後，每一場戰鬥都變成一次豪賭：但凡有一個瞬間他動搖了意志，便會被黑暗吞噬思緒，化作沒有理智、只會攻擊的怪物。",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3
        },
        [6201608] = {
          ContentTC = "就像如今站在弗林面前的「她」一樣。",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3
        },
        [6201609] = {
          ContentTC = "「不……不要這樣……我不想傷害你……拜托……」青年握著長劍的手開始顫抖，「米爾頓已經犧牲了，如果連你也……」",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201610] = {
          ContentTC = "可箭還是向他飛了出來，精準地朝著他心髒的方向。他舉起盾牌，擋下這一擊。又一支箭飛過來，在他的臉頰上擦出一道血痕。",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3
        },
        [6201611] = {
          ContentTC = "「啊啊啊……！」",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201612] = {
          ContentTC = "伴隨著痛苦的叫喊聲，青年舉起了手中的長劍。一劍、一劍、又一劍，直到那幽影終於消散。\n面對已經化為灰燼的同伴，他用長劍撐著搖搖欲墜的身體，失聲痛哭。",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3
        },
        [6201613] = {
          ContentTC = "當哭聲終於停下，四周陷入了異樣的寂靜。戰鬥分明已經結束，可是與他並肩作戰的友人，那個喜歡上躥下跳、永遠吵吵鬧鬧的女孩，卻沒有像往常那樣笑著回到他身邊。",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3
        },
        [6201614] = {
          ContentTC = "「凱希……凱希？你還好嗎？」\n他拖著滿是傷痕的身體，朝著友人所在的方向挪動。",
          DialogueId = 6201614,
          GUID = "0F866C4C",
          NextDialogue = 6201615,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201615] = {
          ContentTC = "女孩似乎沒有聽到他的呼喚。她站在原地，雙手無力地低垂。她的呼吸聲很急促，就像是快要窒息那般徒勞地試圖留住空氣。\n不祥的黑色陰影從她的傷口處湧出來，纏繞上她的四肢，染黑了那漂亮的金發，最後終於將她的身影完全吞噬。",
          DialogueId = 6201615,
          GUID = "0F866C76",
          NextDialogue = 6201616,
          RougeTalkActorType = 3
        },
        [6201616] = {
          ContentTC = "長劍墜落在血與淚調和的泥漿中，青年無力地跪倒在地。",
          DialogueId = 6201616,
          GUID = "0F866CA0",
          NextDialogue = 6201617,
          RougeTalkActorType = 3
        },
        [6201617] = {
          ContentTC = "「我……投降了。你聽到了嗎？」\n他閉上眼睛，仰頭朝向天空——如果那深邃的黑暗能夠被稱為天空的話——聲音平靜得像一潭死水。\n「無論你是什麼……無論你為什麼要這樣折磨我們，我已經受夠了。我累了。到此為止吧，把我也帶走吧……」",
          DialogueId = 6201617,
          GUID = "0F866CCA",
          NextDialogue = 6201618,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201618] = {
          ContentTC = "前方傳來窸窸窣窣的聲響，有什麼東西慢慢地靠近了他。他沒有睜開眼睛，只是以一種決絕的姿態等待著死亡。\n一雙手拾起了他的長劍，重新將它交到他的手中。",
          DialogueId = 6201618,
          GUID = "0F866CF4",
          NextDialogue = 6201619,
          RougeTalkActorType = 3
        },
        [6201619] = {
          ContentTC = "「原來你對我這麼沒有信心啊？」\n女孩的聲音透過黑暗傳出來。那溫柔的陰影擦去了青年的淚水，溫柔地擁抱他低垂的頭顱，遮住了他身上的血汙。\n「放心吧，無論發生什麼……我向你保證，至少，我一定不會改變。」",
          DialogueId = 6201619,
          GUID = "0F866D1E",
          NextDialogue = 6201620,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201620] = {
          ContentTC = "「……嗯。我相信你。」\n青年伸出了雙臂，迎接那片黑暗。",
          DialogueId = 6201620,
          GUID = "0F866D48",
          NextDialogue = 6201621,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201621] = {
          ContentTC = "明知這只是無謂的希望，明知這樣做只會讓他們承受更多的痛苦，你終究還是沒有忍住——\n你舉起提燈，快步走到兩人身邊。在琉璃的光輝之下，籠罩他們的黑暗散去了，女孩的長發再次泛起美麗的金色光澤。\n得救的騎士們怔怔地抬起頭，望向你。",
          DialogueId = 6201621,
          GUID = "0F866D72",
          NextDialogue = 6201622,
          RougeTalkActorType = 3
        },
        [6201622] = {
          ContentTC = "「旅人閣下……？您救了我們嗎？」\n女孩檢視著自己恢復正常的雙手，露出不可思議的神情。\n「多謝您……！雖然早就知道您不是一般人，但還是沒想到，您竟然擁有如此強大的力量。」",
          DialogueId = 6201622,
          GUID = "0F866D9C",
          NextDialogue = 6201623,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201623] = {
          ContentTC = "「哈……」\n青年恍惚地舒了一口氣，似乎還沒有反應過來。",
          DialogueId = 6201623,
          GUID = "0F866DC6",
          NextOptions = {
            [1] = 6201624
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201624] = {
          ContentTC = "不用謝。你們……接下來有什麼打算？",
          DialogueId = 6201624,
          GUID = "0F866DF0",
          IsKeyOption = true,
          NextDialogue = 6201625,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201625] = {
          ContentTC = "「既然得救了，當然是要繼續前進啦。啊，不過，得先休整一下，給弗林處理傷口才行。」",
          DialogueId = 6201625,
          GUID = "0F866E1A",
          NextDialogue = 6201626,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201626] = {
          ContentTC = "似是察覺到你的憂慮，女孩對你露出了一個燦爛的笑容。",
          DialogueId = 6201626,
          GUID = "0F866E44",
          NextDialogue = 6201627,
          RougeTalkActorType = 3
        },
        [6201627] = {
          ContentTC = "「閣下，還記得上次見面時弗林問你的那個問題嗎？現在，我終於想明白了。」她用從容而篤定的語氣緩緩說道。「我想啊，真正能戰勝深淵的，不會是某一次戰鬥，或是某一個人，而是我們所有人付出過的、所有的努力。只要一直積累下去，總有一天……總有一天，它一定能改變什麼。所以，我們沒有必要太在意自己的結局如何，只要繼續前進，就算是為那個最後的勝利做出了一點貢獻。」",
          DialogueId = 6201627,
          GUID = "0F866E6E",
          NextDialogue = 6201628,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201628] = {
          ContentTC = "「嗬……凱希，沒想到……你還能說出這麼有道理的話。對比之下，倒是顯得我這個隊長太軟弱了。」\n青年終於恢復了意識，在友人的幫助下站起來，挺直了脊背。\n「深淵每分每秒都在擴張，如果放任不管，艾利西安全境都會被它吞噬。哪怕只是為了拖延時間，我們也必須戰鬥到最後一刻。況且，我們還沒找到莉茲貝爾大人。」",
          DialogueId = 6201628,
          GUID = "0F866E98",
          NextDialogue = 6201629,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201629] = {
          ContentTC = "「對呀，我們還要和她一起回去呢！所以，旅人閣下，您也只管沿著自己道路前進就好。不必顧慮我們，也不必代替我們背負什麼，請僅僅帶走我們的祝福吧。」\n女孩認真地注視著你，將手掌覆在心口位置。\n「<H>願命運之神為您灑下千縷月光，使您的羽翼永遠如滿月一般潔白無瑕。</>」",
          DialogueId = 6201629,
          GUID = "0F866EC2",
          NextDialogue = 6201630,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201630] = {
          ContentTC = "這是一句十分莊重的祝福語。在艾利西安，人們往往只會對一個很可能再也無法相見的人送上這句祝福。\n但，它絕不意味著消極的道別，它所代表的真意，是對命運的坦然——\n「我真誠地祝願你前路順遂，卻也願意接受或許要與你從此生死永別。」",
          DialogueId = 6201630,
          GUID = "0F866EEC",
          NextDialogue = 6201631,
          RougeTalkActorType = 3
        },
        [6201631] = {
          ContentTC = "你向凱希點了點頭，執起提燈，繼續踏上了旅途。",
          DialogueId = 6201631,
          GUID = "0F866F16",
          RougeTalkActorType = 3
        },
        [6201701] = {
          ContentTC = "數位年輕人的交談聲從不遠處傳來，你已經很久沒在深淵中聽到這樣的聲音了——熱烈的、鮮活的、尚未被深淵的黑暗侵染的聲音。\n你很確信這聲音的來源並非亡靈，也不是幻影，而是活生生的人類。",
          DialogueId = 6201701,
          GUID = "0F867A92",
          NextDialogue = 6201702,
          RougeTalkActorType = 3
        },
        [6201702] = {
          ContentTC = "你又一次和他們相遇了。",
          DialogueId = 6201702,
          GUID = "0F867ABC",
          NextDialogue = 6201703,
          RougeTalkActorType = 3
        },
        [6201703] = {
          ContentTC = "和此前的每一次一樣，四位年輕的騎士結伴從迷霧中出現。\n可他們染血的身影仍然曆曆在目。你一時分不清楚這樣的重逢到底對誰而言更殘酷一些——是不得不一次又一次在絕望中死去的他們，還是不得不一次又一次看著他們死去的你？",
          DialogueId = 6201703,
          GUID = "0F867AE6",
          NextDialogue = 6201704,
          RougeTalkActorType = 3
        },
        [6201704] = {
          ContentTC = "「是這個方向沒錯嗎，隊長？」\n年輕的金發女騎士三步並作兩步跨上古舊的台階，又一口氣跳了下來。\n「這看起來只是一座廢墟而已。」",
          DialogueId = 6201704,
          GUID = "0F867B10",
          NextDialogue = 6201705,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201705] = {
          ContentTC = "「至少我確定我們沒來過這裡。」\n被稱作隊長的青年騎士邁著沉穩的步伐從她身邊走過。\n「在聖湖裡很難辨別方向，現在也只能走一步算一步了。」",
          DialogueId = 6201705,
          GUID = "0F867B3A",
          NextOptions = {
            [1] = 6201706,
            [2] = 6201716
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201706] = {
          ContentTC = "回頭吧……趁還來得及。",
          DialogueId = 6201706,
          GUID = "0F867B64",
          IsKeyOption = true,
          NextDialogue = 6201707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201707] = {
          ContentTC = "「嗯？請問您是……？」",
          DialogueId = 6201707,
          GUID = "0F867B8E",
          NextDialogue = 6201708,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201708] = {
          ContentTC = "「你們是莉茲貝爾的朋友，對吧？這是她讓我轉告你們的——深淵的危險程度遠遠超出我們的想象，絕非一個騎士團小隊所能應對。回去吧，不要增加無謂的犧牲。」\n你已經顧不得其他。就算滿口謊言也好，至少，<W>這一次</>，他們能活下去就好。",
          DialogueId = 6201708,
          GUID = "0F867BB8",
          NextDialogue = 6201709,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201709] = {
          ContentTC = "「咦？！您知道莉茲貝爾大人的下落？她還好嗎？她在哪裡？」",
          DialogueId = 6201709,
          GUID = "0F867BE2",
          NextDialogue = 6201710,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201710] = {
          ContentTC = "「等等，凱希。」\n司祭攔住激動的同伴，懷疑地看向你。\n「莉茲貝爾大人絕非懦弱之輩，請您不要借她之名行騙。再者，深淵討伐行動乃是教皇陛下親自下達的諭令，即便前方是地獄，我們也不會退縮。」",
          DialogueId = 6201710,
          GUID = "0F867C0C",
          NextDialogue = 6201711,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201711] = {
          ContentTC = "你在心中發出一聲歎息。\n有時，當人們念出「地獄」這個詞語的時候，他們並不真的知曉它的意義。",
          DialogueId = 6201711,
          GUID = "0F867C36",
          NextDialogue = 6201712,
          RougeTalkActorType = 3
        },
        [6201712] = {
          ContentTC = "「你說讓我們回頭……」\n身著鬥篷的女術士用那幽邃的眼眸注視著你，聲音一如既往地冰涼。\n「其實……就算我們回頭，也毫無意義，不是嗎？」",
          DialogueId = 6201712,
          GUID = "0F867C60",
          NextDialogue = 6201713,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201713] = {
          ContentTC = "你無言以對。\n是啊，她說得沒錯。即使現在立刻回頭，他們也無法找到來時的方向。在這深淵裡，區分「前進」與「後退」的差異只是一種自我欺騙而已。\n要真正救下他們，只有一個辦法。那就是，徹底結束這個絕望的輪回。",
          DialogueId = 6201713,
          GUID = "0F867C8A",
          NextDialogue = 6201714,
          RougeTalkActorType = 3
        },
        [6201714] = {
          ContentTC = "「各位……」\n你注視著年輕的騎士們，鄭重地將手掌覆在心口位置。\n「<H>願命運之神為你們灑下千縷月光，使你們的羽翼永遠如滿月一般潔白無瑕。</>」",
          DialogueId = 6201714,
          GUID = "0F867CB4",
          NextDialogue = 6201715,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201715] = {
          ContentTC = "聽到你的祝福，卡莉斯塔的臉上浮現一抹哀傷的微笑。\n這時你忽然意識到，也許她其實是希望你能反駁她的，即便，是謊言也好。",
          DialogueId = 6201715,
          GUID = "0F867CDE",
          RougeTalkActorType = 3
        },
        [6201716] = {
          ContentTC = "勇敢的騎士們，願滿月之神護佑你們的旅途。",
          DialogueId = 6201716,
          GUID = "0F867D08",
          IsKeyOption = true,
          NextDialogue = 6201717,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201717] = {
          ContentTC = "「嗯？」\n面對你這句唐突的祝福，青年顯得有些不知所措。\n「請問您是……？」",
          DialogueId = 6201717,
          GUID = "0F867D32",
          NextDialogue = 6201718,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201718] = {
          ContentTC = "「你們是莉茲貝爾的朋友，對吧？這是她讓我轉告你們的——深淵的危險程度遠遠超出我們的想象，你們將會面臨前所未有的困難與挑戰，請做好覺悟。」",
          DialogueId = 6201718,
          GUID = "0F867D5C",
          NextDialogue = 6201719,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201719] = {
          ContentTC = "「咦？！您知道莉茲貝爾大人的下落？她還好嗎？她在哪裡？」",
          DialogueId = 6201719,
          GUID = "0F867D86",
          NextDialogue = 6201720,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201720] = {
          ContentTC = "「等等，凱希，不要輕易相信來路不明之人。」\n司祭攔住激動的同伴，懷疑地看向你。\n「莉茲貝爾大人的性格並不成熟，我很難想象她會說出如此嚴肅的話。再者，深淵討伐行動乃是教皇陛下親自下達的諭令，我們自會竭盡全力，不需要您特意提醒。」",
          DialogueId = 6201720,
          GUID = "0F867DB0",
          NextDialogue = 6201721,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201721] = {
          ContentTC = "「我倒覺得這位旅人說的是真話。在這個地方待久了，就算發瘋也不奇怪，區區性格變化又算什麼呢……」\n女術士抬起頭，用那幽邃的眼眸直直地盯著你，像是在嚐試解開一道謎題。\n「閣下，您究竟是什麼人？我總覺得……我曾見過您。」",
          DialogueId = 6201721,
          GUID = "0F867DDA",
          NextDialogue = 6201722,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201722] = {
          ContentTC = "「……我是誰並不重要。」\n你注視著年輕的騎士們，露出坦然的微笑。\n「你們只需要知道，我的祝福是真心的。就算結局已經注定……希望你們仍然能找到旅途的意義。」",
          DialogueId = 6201722,
          GUID = "0F867E04",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201801] = {
          ContentTC = "你遠遠地看到，兩個熟悉的年輕身影被層層疊疊的幽影圍困在中間——是米爾頓和卡莉斯塔。\n儘管他們互相配合著擊退了一波又一波的攻擊，但幽影依舊源源不斷地湧上前。\n於是你舉起提燈，向他們走去。在琉璃的明亮光輝照耀下，那些幽影終於暫時退卻。",
          DialogueId = 6201801,
          GUID = "0F868AFA",
          NextDialogue = 6201802,
          RougeTalkActorType = 3
        },
        [6201802] = {
          ContentTC = "「您是之前的……」\n看到你出現，司祭先是很驚訝，隨即露出些許愧色。\n「先前我對您多有猜忌，您卻還願意不計前嫌伸出援手……請接受我的歉意與感謝，神秘的旅人。」",
          DialogueId = 6201802,
          GUID = "0F868B24",
          NextDialogue = 6201803,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201803] = {
          ContentTC = "「您果然不是一般人。多謝相助。」\n術士掀開了她的兜帽向你致意，只是兜帽下露出的發絲也還是相同的漆黑色。\n「您持有的那盞提燈……難道是某種神器嗎？為何它能夠驅散幽影？」",
          DialogueId = 6201803,
          GUID = "0F868B4E",
          NextOptions = {
            [1] = 6201804
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201804] = {
          ContentTC = "這是別人托付給我的東西。",
          DialogueId = 6201804,
          GUID = "0F868B78",
          NextDialogue = 6201805,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201805] = {
          ContentTC = "「既然是這樣，我就不多問了。但，有這盞提燈，在深淵中的行動會方便許多。或許，您能允許我們與您同行嗎？」",
          DialogueId = 6201805,
          GUID = "0F868BA2",
          NextDialogue = 6201806,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201806] = {
          ContentTC = "「我不介意，只是，我的目標與你們並不相同。我只是為了修復這盞提燈，在收集琉璃碎片而已。」",
          DialogueId = 6201806,
          GUID = "0F868BCC",
          NextDialogue = 6201807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201807] = {
          ContentTC = "「事到如今，我們的目標已經不重要了……直覺告訴我，與您同行更有機會觸及深淵的真相。」",
          DialogueId = 6201807,
          GUID = "0F868BF6",
          NextDialogue = 6201808,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201808] = {
          ContentTC = "「你在說什麼胡話，卡莉斯塔？」\n沒等你做出回應，司祭便急切地開口斥責他的同伴。\n「雖說我們確實和小隊的其他成員走散了……但我們仍然是艾利西安的騎士。即便只剩一人，也不能放棄使命！」",
          DialogueId = 6201808,
          GUID = "0F868C20",
          NextDialogue = 6201809,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201809] = {
          ContentTC = "「嗬……使命、使命，你的腦子裡除了這些冠冕堂皇的東西就什麼都不剩了嗎？」\n術士也激動起來，箭囊裡裝著的數支細箭隨著她的動作簌簌作響。\n「你想想我們在這裡遇到的都是什麼？穢獸、幻象、孤魂野鬼。如果真的像上面那些人說的那樣，進入聖湖的人是蒙受選召升入了眾天之天了，我們見到的這些幽影又是什麼？你不覺得這個地方比起聖湖，更像暗月教派所說的魔王的巢穴——」",
          DialogueId = 6201809,
          GUID = "0F868C4A",
          NextDialogue = 6201810,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201810] = {
          ContentTC = "「你——你瘋了！你現在說話的口氣就像個異端者！」\n他努力維持著體面，可你也能明顯地聽出來，他的聲音中摻雜著一絲猶疑。\n「我們見到的那些幽影……他們可能是信仰不夠堅定，沒有通過最後試煉的人。把這些多餘的阻礙清理乾淨，聖湖也許就會恢復正常。也許這是九神給予我們的考驗，只要我們保持虔誠，九神自會庇護我們不受侵襲……」",
          DialogueId = 6201810,
          GUID = "0F868C74",
          NextDialogue = 6201811,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201811] = {
          ContentTC = "「你嘴裡的那些神明如果真的在乎我們，就應該親自過來解決這個地獄。」\n她輕笑了一聲，又長歎了一口氣。\n「也許我們就是被派來送死的吧。討伐什麼的根本就不重要，重要的是把一批又一批的新鮮祭品送進來，填塞深淵的欲望。我們看到的那些幽影之中，有許多都是先前被派來討伐深淵的騎士……」",
          DialogueId = 6201811,
          GUID = "0F868C9E",
          NextDialogue = 6201812,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201812] = {
          ContentTC = "「他們比我們年長，也比我們經曆過更多的戰爭，無論能力還是心智都比我們強上數百倍，最後卻還是變成了那副陰魂不散的模樣。我們根本不可能走出去，發瘋或死亡就是我們的結局，或早或晚。」",
          DialogueId = 6201812,
          GUID = "0F868CC8",
          NextDialogue = 6201813,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201813] = {
          ContentTC = "司祭抿著嘴唇，面色緊繃。他用力地握緊了手中的長杖，以掩蓋自己身軀的顫抖。\n片刻之後，他重新以平靜的語氣開口。\n「……鑒於情況特殊，剛才你這些話，我就當做沒有聽過。眼下弗林不在，按照等階順序，你應該聽從我的決斷。我要求你立刻停止對教義和聖者的汙蔑，繼續履行騎士的職責。」",
          DialogueId = 6201813,
          GUID = "0F868CF2",
          NextDialogue = 6201814,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201814] = {
          ContentTC = "「……好吧。早些解脫也不是壞事。」\n她認命似的低下頭，又將兜帽拉過頭頂。\n「但作為朋友，我還是想說……如果你所信仰的一切本身就是謊言，還要為它送死，實在太可惜了，不是嗎？」",
          DialogueId = 6201814,
          GUID = "0F868D1C",
          NextDialogue = 6201815,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201815] = {
          ContentTC = "「……」\n司祭微微搖了搖頭，然後向前一步，對你行禮。\n「抱歉，讓您見笑了。我們已經沒事了，稍作休整便會繼續前進。就此別過吧，善良的旅人，願滿月之神護佑您的旅途。」",
          DialogueId = 6201815,
          GUID = "0F868D46",
          NextOptions = {
            [1] = 6201816,
            [2] = 6201818,
            [3] = 6201820
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201816] = {
          ContentTC = "也願滿月之神護佑你們的旅途。",
          DialogueId = 6201816,
          GUID = "0F868D70",
          IsKeyOption = true,
          NextDialogue = 6201817,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201817] = {
          ContentTC = "聽到你的回應，米爾頓露出了滿足的微笑。卡莉斯塔也並未再作反駁，只是沉默地別過頭去，你看不清她的表情。\n你向他們點頭致意，然後便轉身離開了。",
          DialogueId = 6201817,
          GUID = "0F868D9A",
          RougeTalkActorType = 3
        },
        [6201818] = {
          ContentTC = "我想滿月之神可能幫不了我。",
          DialogueId = 6201818,
          GUID = "0F868DC4",
          IsKeyOption = true,
          NextDialogue = 6201819,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201819] = {
          ContentTC = "聽到你的回應，米爾頓有些局促地移開了目光，但沒有多說什麼。卡莉斯塔向你露出一個哀傷的微笑，隨後又疲憊地低下了頭。\n你向他們點頭致意，然後便轉身離開了。",
          DialogueId = 6201819,
          GUID = "0F868DEE",
          RougeTalkActorType = 3
        },
        [6201820] = {
          ContentTC = "我想……也許真正重要的不是信仰，而是我們自身的勇氣。",
          DialogueId = 6201820,
          GUID = "0F868E18",
          IsKeyOption = true,
          NextDialogue = 6201821,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201821] = {
          ContentTC = "聽到你的回應，米爾頓和卡莉斯塔先是有些驚訝，隨後又一同陷入了沉思。\n你沒有再多說什麼，畢竟，這句話其實是別人告訴你的，就連你自己也仍在摸索它真正的含義。\n你向二人點頭致意，然後便轉身離開了。",
          DialogueId = 6201821,
          GUID = "0F868E42",
          RougeTalkActorType = 3
        },
        [6201901] = {
          ContentTC = "前方傳來不祥的、濃烈的血腥味。\n那深邃的黑暗和沉重的寂靜讓你確信前方並沒有你所求之物，可是你又感到一種奇妙的預兆，似乎有誰正希冀你踏入那片黑暗。於是你試探著邁出了腳步——",
          DialogueId = 6201901,
          GUID = "0F869B62",
          NextDialogue = 6201902,
          RougeTalkActorType = 3
        },
        [6201902] = {
          ContentTC = "忽然間，四周出現了白色的亮光——不，不是亮光。你定睛細看，才發覺那只是穢獸煞白的外殼，一塊連著一塊，堆疊在一起像是某位異端藝術家醉後潑灑出的作品。\n你本能地後退一步，兩個熟悉的身影出現在你身邊。",
          DialogueId = 6201902,
          GUID = "0F869B8C",
          NextDialogue = 6201903,
          RougeTalkActorType = 3
        },
        [6201903] = {
          ContentTC = "「咳、咳……沒完沒了……」\n術士抹去嘴角的血跡，將手中的長弓丟棄在地。\n「我的箭都用完了……接下來就只能靠魔法了。嗬，我這也算是為你們的神明大人鞠躬盡瘁了吧？拜托死後別把我丟在亂葬崗，好歹留個全屍吧。」",
          DialogueId = 6201903,
          GUID = "0F869BB6",
          NextDialogue = 6201904,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201904] = {
          ContentTC = "「別再胡說——小心身後！」\n司祭猛然揮動長杖，魔法的光芒亮起。\n「嘖……又有幽影出現了。」",
          DialogueId = 6201904,
          GUID = "0F869BE0",
          NextDialogue = 6201905,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201905] = {
          ContentTC = "你隨卡莉斯塔一同轉過身，發現大片的幽影朝你們湧了過來，越過地上的穢獸屍體，像是那位藝術家又在畫作上打翻了一桶黑色的顏料。\n你連忙舉起提燈，可幽影的動作卻沒有收斂分毫。你忽然注意到，你的提燈穿過了米爾頓的長杖。",
          DialogueId = 6201905,
          GUID = "0F869C0A",
          NextDialogue = 6201906,
          RougeTalkActorType = 3
        },
        [6201906] = {
          ContentTC = "這時你明白了——眼前的一切只是一段記憶的殘像。你明明就站在他們身邊，可你什麼也做不了，除了眼睜睜地看著他們在戰鬥中不斷消耗、負傷累累、力竭倒地。",
          DialogueId = 6201906,
          GUID = "0F869C34",
          NextDialogue = 6201907,
          RougeTalkActorType = 3
        },
        [6201907] = {
          ContentTC = "幽影已經逐漸散去，只剩下最後的四個……三個……兩個……一個。但凡兩位年輕的騎士中還有一個人留有反擊的力氣，但凡他們的隊友能及時出現支援，但凡這裡掉落了一小塊琉璃碎片，他們就能贏得這場戰鬥，活下去。\n可是……沒有。除了你這個遲來的旁觀者，什麼都沒有。",
          DialogueId = 6201907,
          GUID = "0F869C5E",
          NextDialogue = 6201908,
          RougeTalkActorType = 3
        },
        [6201908] = {
          ContentTC = "那個人形的幽影逼近了，那個或許曾是他們的前輩、同伴或是朋友的人，將一柄漆黑的長槍刺向卡莉斯塔的心髒。\n你閉上了眼睛，不願目睹這殘忍的一幕。",
          DialogueId = 6201908,
          GUID = "0F869C88",
          NextDialogue = 6201909,
          RougeTalkActorType = 3
        },
        [6201909] = {
          ContentTC = "「米爾頓……？！你……為什麼……？」",
          DialogueId = 6201909,
          GUID = "0F869CB2",
          NextDialogue = 6201910,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201910] = {
          ContentTC = "你驚訝地睜開眼，發現那長槍最終刺穿的是米爾頓的胸膛。幽影散去，他無力地墜向地面，濺起的鮮血染紅了他那永遠整理得一絲不苟的衣襟。",
          DialogueId = 6201910,
          GUID = "0F869CDC",
          NextDialogue = 6201911,
          RougeTalkActorType = 3
        },
        [6201911] = {
          ContentTC = "「你做了什麼……？你……」\n術士錯愕地跪在隊友身邊，無措地伸手試圖使用治愈魔法，卻只是徒勞。\n「你不是說……你不是說我是異端者嗎？你為什麼要為了救一個異端者搭上自己的性命啊？！你不是還要證明你的信仰嗎……」",
          DialogueId = 6201911,
          GUID = "0F869D06",
          NextDialogue = 6201912,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201912] = {
          ContentTC = "「因為我的信仰告訴我……要保護同伴……無論你再怎麼質疑它……至少這一點，我篤定它是對的。」\n在這個即將迎來死亡的時刻，司祭那永遠正顏厲色的臉上終於露出了一絲活著的人才會擁有的、生動的笑容。\n「我想，我已經為神奉獻了足夠多……那麼，最後，就讓我說一句自己的心裡話吧。卡莉斯塔……忘了那些使命和職責吧。離開這裡，活下去。」",
          DialogueId = 6201912,
          GUID = "0F869D30",
          NextDialogue = 6201913,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201913] = {
          ContentTC = "「哎……？」",
          DialogueId = 6201913,
          GUID = "0F869D5A",
          NextDialogue = 6201914,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201914] = {
          ContentTC = "「我不在之後，你就是自己的指揮官，可以憑自己的意願行動了。就像你一直說的那樣，逃走吧……離開這片深淵，或者，去找那位旅人……只要能活下去，怎樣都好。」",
          DialogueId = 6201914,
          GUID = "0F869D84",
          NextDialogue = 6201915,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201915] = {
          ContentTC = "一滴又一滴的眼淚順著她白皙的臉頰滑落，落在在米爾頓的衣襟，讓那已經開始凝固的血塊再度融化。\n「可我一個人……又能走到哪裡去呢……」",
          DialogueId = 6201915,
          GUID = "0F869DAE",
          NextDialogue = 6201916,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201916] = {
          ContentTC = "「又在……說胡話了。」\n司祭用他那曾經緊握著長杖的手，吃力地將胸前的徽章摘下，放到卡莉斯塔的手中。\n「你的考核成績一直都是我們之中最優秀的。你也是來到這裡之後，第一個看清事實、有勇氣質疑現狀的……你……一定可以……活下去……」",
          DialogueId = 6201916,
          GUID = "0F869DD8",
          NextDialogue = 6201917,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201917] = {
          ContentTC = "幻象散去了，你沒有聽到卡莉斯塔的回答。\n在寂靜的黑暗中，你發現了司祭冰冷的身體。黑色的陰影從他的傷口中湧出，很快，他將會和你看到的許多人一樣，化作無法安息的幽影。",
          DialogueId = 6201917,
          GUID = "0F869E02",
          NextOptions = {
            [1] = 6201918,
            [2] = 6201920
          },
          RougeTalkActorType = 3
        },
        [6201918] = {
          ContentTC = "（替他結束痛苦。）",
          DialogueId = 6201918,
          GUID = "0F869E2C",
          IsKeyOption = true,
          NextDialogue = 6201919,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201919] = {
          ContentTC = "在他徹底異化為幽影之前，你發動提燈的力量，結束了他的生命。\n「謝謝……」\n你似乎聽到了這樣的聲音，又或者，那只是你用來安慰自己的幻覺。",
          DialogueId = 6201919,
          GUID = "0F869E56",
          RougeTalkActorType = 3
        },
        [6201920] = {
          ContentTC = "（你不忍心動手。）",
          DialogueId = 6201920,
          GUID = "0F869E80",
          IsKeyOption = true,
          NextDialogue = 6201921,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201921] = {
          ContentTC = "你退後一步，打算就此離開。\n可幽影站了起來。他那曾從友人手中無力滑落的蒼白的手又一次握緊了長杖，向你發起攻擊。\n你歎息一聲，舉起武器，將那幽影打倒了，一如既往。",
          DialogueId = 6201921,
          GUID = "0F869EAA",
          RougeTalkActorType = 3
        },
        [6202001] = {
          ContentTC = "又一次，你走到了輪回的盡頭。\n你收集的琉璃仍不足以與深淵的核心對抗，你必須再一次倒轉時間。",
          DialogueId = 6202001,
          GUID = "0F86ABCA",
          NextDialogue = 6202002,
          RougeTalkActorType = 3
        },
        [6202002] = {
          ContentTC = "你在混沌的洪流中漫無目的地踱著步子——你已經無數次直面過祂的注視，不再心生恐懼，只是平靜地感受這一輪回最後的幾分鍾。\n忽然，你見到了一個熟悉的身影。",
          DialogueId = 6202002,
          GUID = "0F86ABF4",
          NextDialogue = 6202003,
          RougeTalkActorType = 3
        },
        [6202003] = {
          ContentTC = "「哈……是您……您果然還活著。」\n她斜倚著一面斷牆，殘破的鬥篷遮蓋不住那遍體鱗傷的身軀。\n「您到底是什麼人……？為什麼，看到了那樣的東西，您的眼中卻毫無懼色？」",
          DialogueId = 6202003,
          GUID = "0F86AC1E",
          NextOptions = {
            [1] = 6202004,
            [2] = 6202006
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202004] = {
          ContentTC = "我已經見過祂很多次，在輪回的時間裡。",
          DialogueId = 6202004,
          GUID = "0F86AC48",
          IsKeyOption = true,
          NextDialogue = 6202005,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202005] = {
          ContentTC = "「輪回？」\n她的眼中閃過一瞬的光亮，如同解開了難題的學者。\n「啊……原來如此。我終於明白了。怪不得您看向我們的眼神是那樣的……慈悲……您早就已經無數次見證過我們的結局了，對嗎？輪回……嗬嗬……也就是說，很快，我和他們就能重新團聚了……？這麼一想，死亡似乎也不那麼可怕了。」",
          DialogueId = 6202005,
          GUID = "0F86AC72",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202006] = {
          ContentTC = "有些真相也許不知道更好。",
          DialogueId = 6202006,
          GUID = "0F86AC9C",
          IsKeyOption = true,
          NextDialogue = 6202007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202007] = {
          ContentTC = "「嗬嗬……您說得對。我無法想象您究竟是經曆了什麼，才能擁有這般強大而可怖的……平靜。」\n她那黑色的眼眸此刻溫和地注視著你，如同一位親切的友人。\n「我總覺得，您還有很多話沒有告訴我們。但我想，您一定有自己的理由，就像他們所堅持的信仰一樣。」",
          DialogueId = 6202007,
          GUID = "0F86ACC6",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202008] = {
          ContentTC = "「請收下這個……如果可以，希望您能將它帶在身邊。就當是，我最後的請求吧……」\n她費力地伸出手，將一本筆記遞給你。\n「米爾頓讓我逃走，可我知道，我已經回不去了。那麼至少……讓我最後的生命發揮一些價值吧。」",
          DialogueId = 6202008,
          GUID = "0F86ACF0",
          NextDialogue = 6202009,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202009] = {
          ContentTC = "「在這深淵裡……我花了很多時間去想，到底哪一種信仰才是對的？滿月之神和暗月之神，哪一位才是真的？我一直找不到答案，還為此屢屢和同伴們爭吵。」\n她感慨地歎了一口氣，似是自嘲。\n「到現在我才終於明白…其實信仰本身的真偽根本不重要。真正重要的是，信仰它的人做了什麼。我的同伴們用實際行動貫徹和證明了自己的信仰。我認為他們的所作所為是正確的，所以，在最後，我也願意用他們的信仰——無論它本身到底真實與否——為您送上我的祝福。」",
          DialogueId = 6202009,
          GUID = "0F86AD1A",
          NextDialogue = 6202010,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202010] = {
          ContentTC = "「那麼……旅人啊……」\n她顫抖著將蒼白的右手放在心口，用那已然開始渙散的雙眸努力捕捉你所在的方向。\n「<H>願命運之神為您灑下千縷月光，使您的羽翼永遠如滿月一般潔白無瑕。</>」",
          DialogueId = 6202010,
          GUID = "0F86AD44",
          NextDialogue = 6202011,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202011] = {
          ContentTC = "她停止了呼吸。\n你替她合上了雙眼。她的臉上仍然帶著平和的笑容，仿佛只是睡著了一般。",
          DialogueId = 6202011,
          GUID = "0F86AD6E",
          NextDialogue = 6202012,
          RougeTalkActorType = 3
        },
        [6202012] = {
          ContentTC = "你翻開了她托付給你的那本筆記。筆記的紙張雖然沾上了不少灰塵和血汙，但字跡還算清晰。\n「我，艾利西安傳頌會下屬飛羽騎士團『靜默黃昏』小隊成員卡莉斯塔，於此處記錄下我所觀測到的、關於聖湖的一切。若有人尋得這本筆記，希望這些記錄能為你走出這裡提供微薄助力。」",
          DialogueId = 6202012,
          GUID = "0F86AD98",
          NextDialogue = 6202013,
          RougeTalkActorType = 3
        },
        [6202013] = {
          ContentTC = "借著著提燈的光輝，你翻閱著她的筆記。淩亂的文字似是在昏暗中匆忙寫就，記錄著大量幽影和幻象，從每種幽影的弱點到每個幻象的驅散方式不一而足。\n你翻閱到筆記的其中一頁。\n「可以確定，<H>暗月教派</>的典籍所言之物並非完全虛假……至少，聖湖與神話中的眾天之天毫無關聯，所謂的選召更像是一種獻祭。這是一個滿盈著死者留下的惡意與邪念的場所。」\n「我的家族是暗月教派的信奉者。他們以深淵和暗月女神為信仰，並堅信初代七美德之一的<H>沙利葉</>在兩千年前並未前往眾天之天，而是在這聖湖底成為<H>魔王</>，也就是深淵的核心。他不斷吞噬著靈魂，作為獻給涅法的祭品。」",
          DialogueId = 6202013,
          GUID = "0F86ADC2",
          NextDialogue = 6202014,
          RougeTalkActorType = 3
        },
        [6202014] = {
          ContentTC = "「在過去的生命裡，我不斷以正教的訓導自醒——我不願相信那些可怖的傳說。但是這片深淵的一切無時無刻不在詰問我：如果暗月派的教義才是真相……如果我們世界的盡頭真的是黑暗與虛無——」\n「那麼，深淵是否是不可戰勝的？」\n「只可惜，我殘存的身體已經不可能支撐自己找到答案。」",
          DialogueId = 6202014,
          GUID = "0F86ADEC",
          NextDialogue = 6202015,
          RougeTalkActorType = 3
        },
        [6202015] = {
          ContentTC = "「米爾頓告訴過我，昔日有一柄叫做<H>柯羅涅</>的<H>聖劍</>於聖湖意外損毀。那是傳頌會的聖物，擁有非同尋常的力量……另外，我曾在這片深淵中見過一位旅人，那位旅人持有的提燈似乎也擁有驅散幽影的特殊力量。」\n「如果真的有什麼能戰勝深淵，我想，這二者或許會成為關鍵。」",
          DialogueId = 6202015,
          GUID = "0F86AE16",
          NextDialogue = 6202016,
          RougeTalkActorType = 3
        },
        [6202016] = {
          ContentTC = "你注意到筆記還有很多頁。你迫不及待地往下翻——她到底還知道多少真相？\n但很快你便發現，筆記後面記錄的內容，與深淵無關。",
          DialogueId = 6202016,
          GUID = "0F86AE40",
          NextDialogue = 6202017,
          RougeTalkActorType = 3
        },
        [6202017] = {
          ContentTC = "「正在翻閱這本筆記的人啊，謝謝你看到這裡。希望你能替我記住他們。」",
          DialogueId = 6202017,
          GUID = "0F86AE6A",
          NextDialogue = 6202018,
          RougeTalkActorType = 3
        },
        [6202018] = {
          ContentTC = "在這個短暫的瞬間，你的思緒離開了深淵，被這些文字帶去了另一個世界。\n艾利西安騎士團的營地，一間小小的宿舍，溫暖的黃色燈光下，你翻開一個年輕騎士的日記本，看到她和她的三位朋友的故事。",
          DialogueId = 6202018,
          GUID = "0F86AE94",
          NextDialogue = 6202019,
          RougeTalkActorType = 3
        },
        [6202019] = {
          ContentTC = "他們一同參與訓練——\n「『你們簡直像一個小隊啊』——被教官這麼說了幾次之後，弗林還真的起勁了，說要給我們這個四人小隊起個名字，凱希也跟著附和——這倒是沒什麼，他們倆本來就總在一塊鬧騰。但我沒想到米爾頓也會讚成，難不成這傢伙心裡也有什麼英雄夢嗎？」\n「『靜默黃昏』和『英勇土豆』，是弗林和凱希分別給出的候選隊名。我和米爾頓都毫不猶豫地投票給了第一個。考慮到那天的午飯是土豆燉肉，我充分懷疑凱希是在吃午飯時隨口胡謅了一個名字拿來湊數。」\n「至於弗林起的這個名字，『黃昏』……嗬嗬，別人也許發覺不了，但我們幾個一眼就能看出來，這是在偷偷致敬他最喜歡的那位『月升時』的騎士呢。」",
          DialogueId = 6202019,
          GUID = "0F86AEBE",
          NextDialogue = 6202020,
          RougeTalkActorType = 3
        },
        [6202020] = {
          ContentTC = "他們一同踏上戰場——\n「行軍的時候，凱希總是在不知不覺間就跑得沒影了。剛開始我們還很擔心，但每一次她都會在意想不到的時候忽然出現嚇我們一跳，再後來我們就見怪不怪了。不過，她到底是怎麼做到的呢？她那個腦子，也不可能學得會瞬移之類的高難度魔法啊……」\n「米爾頓那個書呆子，居然把書帶上戰場，說空閑時可以看？！簡直不知道說他什麼好……」\n「後來，米爾頓的書被帝國一支火箭給燒了個精光。他一整天都耷拉著臉……我看他應該感謝那個帝國兵才對，他行囊的重量至少因此減輕了三分之二。」",
          DialogueId = 6202020,
          GUID = "0F86AEE8",
          NextDialogue = 6202021,
          RougeTalkActorType = 3
        },
        [6202021] = {
          ContentTC = "他們一同接受使命——\n「為了避免麻煩，我沒把報名參與深淵討伐的事告訴父母，只告訴了哥哥……沒想到他也和他們一樣，對著我嘮叨個不停，說什麼深淵是傳頌會的陰謀，魔王會把大家都變成祭品……真是煩死了。」\n「其實我對討伐深淵什麼的並沒有興趣，但弗林對此特別積極，我也不好意思反對。在之前參與的那些戰役裡，我們從沒當過主力，總是輸多贏少，他一定很想要一個證明自己的機會……所以，就當是幫他圓這個騎士夢吧。反正，只要大家在一起，去哪裡都差不多。」",
          DialogueId = 6202021,
          GUID = "0F86AF12",
          NextDialogue = 6202022,
          RougeTalkActorType = 3
        },
        [6202022] = {
          ContentTC = "……",
          DialogueId = 6202022,
          GUID = "0F86AF3C",
          NextDialogue = 6202023,
          RougeTalkActorType = 3
        },
        [6202023] = {
          ContentTC = "你翻到了筆記的最後一頁。",
          DialogueId = 6202023,
          GUID = "0F86AF66",
          NextDialogue = 6202024,
          RougeTalkActorType = 3
        },
        [6202024] = {
          ContentTC = "「沉默的神明啊，若你真如米爾頓所說，在時刻注視著我們……我請求你，為我實現最後的願望。」\n「請讓我的靈魂與他們團聚吧。」\n「那樣，我便原諒你的冷漠，原諒你的殘忍；原諒你施加的諸多苦難，原諒你編織的一切謊言。」",
          DialogueId = 6202024,
          GUID = "0F86AF90",
          NextDialogue = 6202025,
          RougeTalkActorType = 3
        },
        [6202025] = {
          ContentTC = "<H>「我的羽翼已不再需要滿月的照耀，只希望有一道清風，帶我飛往同伴們所在的方向。」</>",
          DialogueId = 6202025,
          GUID = "0F86AFBA",
          NextDialogue = 6202026,
          RougeDialogueMainIcon = "Texture2D'/Game/UI/Texture/Dynamic/Image/RougeLike/T_Rouge_Story13.T_Rouge_Story13'",
          RougeTalkActorType = 3
        },
        [6202026] = {
          ContentTC = "合上筆記，你的指尖依然能感受到紙頁上的餘溫。",
          DialogueId = 6202026,
          GUID = "0F86AFE4",
          NextDialogue = 6202027,
          RougeTalkActorType = 3
        },
        [6202027] = {
          ContentTC = "「我……一定會終結輪回，讓你們在明亮的滿月下重逢。」",
          DialogueId = 6202027,
          GUID = "0F86B00E",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [7002001] = {
          ContentTC = "慰問品七七八八地堆放著，似乎是這幾天很多人陸續送來的。\n仔細一看，裡面有不知名的野花，雖然冷掉但依舊聞起來美味的肉湯，帶划痕但精美的八音盒，畫著小鳥的一罐棉花糖……\n除了這些以外，還有一份沒有署名，系著歪扭蝴蝶結的樸素禮盒，打開以後發現裡面是一瓶帝國最頂尖的止痛劑。這份關懷的心雖是好的，但送給一名昏迷人士止痛劑，實在是沒什麼意義了。",
          DialogueId = 7002001,
          GUID = "11875DCA"
        },
        [7003001] = {
          ContentTC = "冰湖城外城近日發生多起惡性傷人事件，手段極其殘忍，現場極為混亂，請廣大市民減少深夜外出，鎖好門窗。\n持有武器許可證的市民如果遭遇行凶者，不要試圖反擊（這很危險！！！），優先保全自身性命。\n如有兇手線索，請立即聯絡衛戍部隊，黎瑟·費西爾。\n皇帝會庇護他忠誠的子民度過難關，榮耀盡歸吾皇。",
          DialogueId = 7003001,
          GUID = "118801DA"
        },
        [10010101] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
          ContentTC = "貝蕾，我……",
          DefaultLookAt = "KeepState",
          DialogueId = 10010101,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "190F2A32",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 408001,
            [4] = 201001
          },
          SpeakNpcId = 100001,
          Subtitle = "Berry, I...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A32"
        },
        [10010102] = {
          ContentTC = "噓。",
          DialogueId = 10010102,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2A5C",
          SpeakNpcId = 100003,
          Subtitle = "Ssh...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A5C"
        },
        [10010103] = {
          ContentTC = "還好嗎？",
          DialogueId = 10010103,
          DisableMouth = 1,
          Duration = 2,
          GUID = "190F2A86",
          SpeakNpcId = 100003,
          Subtitle = "Are you all right?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A86"
        },
        [10010104] = {
          ContentTC = "嗯。",
          DialogueId = 10010104,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190F2AB0",
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2AB0"
        },
        [10010105] = {
          ContentTC = "再歇息一會兒吧。我就在這裡，哪兒都不去。",
          DialogueId = 10010105,
          DisableMouth = 1,
          Duration = 5,
          GUID = "190F2ADA",
          SpeakNpcId = 100003,
          Subtitle = "Get some more sleep. I won't leave — I'll be right here when you wake up.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2ADA"
        },
        [10010106] = {
          ContentTC = "不用了。我們回去吧，下山。",
          DialogueId = 10010106,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F2B04",
          SpeakNpcId = 100001,
          Subtitle = "It's okay. We should get down the mountain and head to the village.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B04"
        },
        [10010107] = {
          ContentTC = "現在就回村子嗎？可這兩天那邊一直傳來吼聲……",
          DialogueId = 10010107,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F2B2E",
          SpeakNpcId = 100003,
          Subtitle = "You wanna go back? There've been roars coming from there for days...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B2E"
        },
        [10010108] = {
          ContentTC = "我是想，如果能回家拿到武器——",
          DialogueId = 10010108,
          DisableMouth = 1,
          Duration = 4.5,
          ExStoryInfo = "Player",
          GUID = "190F2B58",
          SpeakNpcId = 100001,
          Subtitle = "I was thinking, if we could make it home and grab our weapons—",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B58"
        },
        [10010109] = {
          ContentTC = "憑你的力量，一定能找到生路。",
          DialogueId = 10010109,
          DisableMouth = 1,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "190F2B82",
          SpeakNpcId = 100001,
          Subtitle = "And with your strength, you'll find a way out. ",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B82"
        },
        [10010110] = {
          ContentTC = "留在這裡……也不會有人來救我們的，不是麼？",
          DialogueId = 10010110,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "190F2B83",
          SpeakNpcId = 100001,
          Subtitle = "No one's gonna save us no matter how long we stay here anyway.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B83"
        },
        [10010111] = {
          ContentTC = "……走吧。",
          DialogueId = 10010111,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2BAC",
          SpeakNpcId = 100003,
          Subtitle = "...Let's go then.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAC"
        },
        [10010112] = {
          ContentTC = "慢慢來。",
          DialogueId = 10010112,
          GUID = "190F2BAD",
          SpeakNpcId = 100003,
          Subtitle = "Take it easy.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAD"
        },
        [10010113] = {
          ContentTC = "當心腳下，不要踩空。",
          DialogueId = 10010113,
          GUID = "190F2BAE",
          SpeakNpcId = 100003,
          Subtitle = "Watch your step.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAE"
        },
        [10010114] = {
          ContentTC = "你的傷還沒好吧，要不要緊？",
          DialogueId = 10010114,
          GUID = "190F2BAF",
          NextDialogue = 10010115,
          SpeakNpcId = 100003,
          Subtitle = "You're not fully recovered. Are you sure you can do this?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAF"
        },
        [10010115] = {
          ContentTC = "早就沒事了，區區幾道溝而已。",
          DialogueId = 10010115,
          ExStoryInfo = "Player",
          GUID = "190F2BB1",
          NextDialogue = 10010116,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. It's just a few scratches.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB1"
        },
        [10010116] = {
          ContentTC = "別逞強。不要還沒遇到穢獸，先用光了力氣。",
          DialogueId = 10010116,
          GUID = "190F2BB2",
          SpeakNpcId = 100003,
          Subtitle = "Don't push yourself too hard. We still have to save some strength for those Filthoids.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB2"
        },
        [10010201] = {
          ContentTC = "想活命，就如實交代清楚。",
          DialogueId = 10010201,
          Duration = 4,
          GUID = "190F3A9A",
          SpeakNpcId = 100005,
          Subtitle = "Tell me the truth if you want to live.",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3A9A"
        },
        [10010202] = {
          ContentTC = "為什麼在這裡，你的同伴是什麼人。",
          DialogueId = 10010202,
          Duration = 5,
          GUID = "190F3AC4",
          SpeakNpcId = 100005,
          Subtitle = "Why are you here, who's with you,",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AC4"
        },
        [10010203] = {
          ContentTC = "以及，你又是誰。",
          DialogueId = 10010203,
          Duration = 3.5,
          GUID = "190F3AEE",
          SpeakNpcId = 100005,
          Subtitle = "and who on earth are you?",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AEE"
        },
        [10010204] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010204,
          Duration = 2,
          GUID = "190F3AEF",
          NextDialogue = 10010205
        },
        [10010205] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010205,
          Duration = 2,
          GUID = "190F3AF0",
          NextDialogue = 10010206
        },
        [10010206] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010206,
          Duration = 2,
          GUID = "190F3AF1"
        },
        [10010301] = {
          Content = "我们现在赤手空拳，尽可能避开它们吧。",
          DialogueId = 10010301,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F4B02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100103/190F4B02"
        },
        [10010401] = {
          ContentTC = "拿好你手裡那把劍，興許會派上用場。",
          DialogueId = 10010401,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F5B6A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcId = 100003,
          Subtitle = "Take that sword with you. It might be helpful one day.",
          TalkActionId = {
            [1] = "100001:FuXiong_Start"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B6A"
        },
        [10010402] = {
          ContentTC = "保護好自己，穢獸交給我。",
          DialogueId = 10010402,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F5B94",
          SpeakNpcId = 100003,
          Subtitle = "Keep yourself safe. I'll take care of these Filthoids.",
          TalkActionId = {
            [1] = "100001:FuXiong_End"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B94"
        },
        [10010501] = {
          Content = "拿起剑的时候，熟悉而陌生的记忆涌上来……",
          DialogueId = 10010501,
          Duration = 3,
          GUID = "190F6BD2",
          NextDialogue = 10010502,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BD2"
        },
        [10010502] = {
          Content = "……已经很久没有像这样战斗过了。",
          DialogueId = 10010502,
          Duration = 2.5,
          GUID = "190F6BFC",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BFC"
        },
        [10010601] = {
          ContentTC = "走。去碼頭。",
          DialogueId = 10010601,
          Duration = 2,
          GUID = "190F7D0C",
          SpeakNpcId = 100003,
          Subtitle = "Let's head to the wharf.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7D0C"
        },
        [10010701] = {
          ContentTC = "嘖，他們還真是……一條船都沒剩下。",
          DialogueId = 10010701,
          GUID = "190F8CA2",
          NextDialogue = 10010702,
          SpeakNpcId = 100003,
          Subtitle = "Ugh, they didn't leave even one single boat.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CA2"
        },
        [10010702] = {
          ContentTC = "穢獸來的時候，你還在村子裡吧？如果不是折回去找我，你本可以一起逃走的。",
          DialogueId = 10010702,
          ExStoryInfo = "Player",
          GUID = "190F8CCC",
          NextDialogue = 10010703,
          SpeakNpcId = 100001,
          Subtitle = "You were at the village when the Filthoids came, weren't you? If it wasn't for coming back for me, you could have escaped with them.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CCC"
        },
        [10010703] = {
          ContentTC = "別說蠢話，換你在這兒也一樣。我們先沿著海岸找找有沒有舊一些的船。",
          DialogueId = 10010703,
          GUID = "190F8CF6",
          SpeakNpcId = 100003,
          Subtitle = "Don't be silly. You'd have done the same for me. Let's search along the shore and see if there's any old boats or something.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF6"
        },
        [10010704] = {
          Content = "别说傻话。我们先沿着海岸找找有没有废旧的船。",
          DialogueId = 10010704,
          GUID = "190F8CF7",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF7"
        },
        [10010801] = {
          Camera = "233.692749,98.025391,337.437744,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          ContentTC = "這是……大家逃跑時落下的嗎？",
          DefaultLookAt = "KeepState",
          DialogueId = 10010801,
          ExStoryInfo = "Player",
          FinalCamera = "233.692749,98.025391,306.806396,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          GUID = "190F9D0A",
          LookAt = {
            [1] = "100001:p(QuestPoint102)",
            [2] = "100003:p(QuestPoint102)"
          },
          NextDialogue = 10010802,
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001
          },
          SpeakNpcId = 100001,
          Subtitle = "Look... Someone must have lost them when they ran away.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D0A"
        },
        [10010802] = {
          Camera = "45.787476,-42.09668,191.500977,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          ContentTC = "嗯，帶上吧，多做些準備總是好的。",
          DefaultLookAt = "KeepState",
          DialogueId = 10010802,
          FinalCamera = "25.377319,-28.079102,173.898438,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          GUID = "190F9D34",
          SpeakNpcId = 100003,
          Subtitle = "Hmm, let's grab one. It's always good to be well-armed.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D34"
        },
        [10010901] = {
          Content = "这边。",
          DialogueId = 10010901,
          Duration = 2,
          GUID = "190FAD9D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9D"
        },
        [10011001] = {
          ContentTC = "又有穢獸過來了……",
          DialogueId = 10011001,
          GUID = "190FBDDA",
          NextDialogue = 10011002,
          SpeakNpcId = 100003,
          Subtitle = "More Filthoids are coming...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBDDA"
        },
        [10011002] = {
          ContentTC = "{nickname}，等下不要離我太遠。必要的話，就用我們的暗號。",
          DialogueId = 10011002,
          GUID = "190FBE04",
          NextDialogue = 10011003,
          SpeakNpcId = 100003,
          Subtitle = "Stay close, Phoxhunter. If necessary, give out the secret signals.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE04"
        },
        [10011003] = {
          ContentTC = "還記得嗎？之前上山時為了不驚動野獸約定的暗號。",
          DialogueId = 10011003,
          GUID = "190FBE05",
          NextDialogue = 10011004,
          SpeakNpcId = 100003,
          Subtitle = "We made them up earlier so as not to alert the beasts up the mountain, remember?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE05"
        },
        [10011004] = {
          ContentTC = "當然。",
          DialogueId = 10011004,
          ExStoryInfo = "Player",
          GUID = "190FBE06",
          NextDialogue = 10011005,
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE06"
        },
        [10011005] = {
          ContentTC = "嗯，我再確認一遍。輕拍右肩兩下的意思是？",
          DialogueId = 10011005,
          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          ContentTC = "「留意身後。」",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          ContentTC = "輕敲心口兩次的意思是？",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
          ContentTC = "「靠過來。」",
          DialogueId = 10011008,
          ExStoryInfo = "Player",
          GUID = "190FBEA0",
          NextDialogue = 10011009,
          SpeakNpcId = 100001,
          Subtitle = "\"Come closer.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA0"
        },
        [10011009] = {
          ContentTC = "輕輕刮一下鼻樑是？",
          DialogueId = 10011009,
          GUID = "190FBEA1",
          NextDialogue = 10011010,
          SpeakNpcId = 100003,
          Subtitle = "And scraping on the nose?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA1"
        },
        [10011010] = {
          ContentTC = "「已經沒事了。」",
          DialogueId = 10011010,
          ExStoryInfo = "Player",
          GUID = "190FBEA2",
          NextDialogue = 10011011,
          SpeakNpcId = 100001,
          Subtitle = "\"Everything's okay now.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA2"
        },
