          ExStoryInfo = "Player",
          GUID = "19147C14",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "Phoxhunter.",
          VoiceName = "voice/$Locale$/story/1001/100184/19147C14"
        },
