          VoiceName = "voice/$Locale$/story/1001/100195/19153060"
        },
        [10019505] = {
          Content = "？？？：……听着，{NickName}。",
          DialogueId = 10019505,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "19153061.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153061"
        },
        [10019506] = {
          Content = "？？？：“生命是航行在无尽长夜里的孤船。”",
          DialogueId = 10019506,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "19153062.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153062"
        },
        [10019507] = {
          Content = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
          DialogueId = 10019507,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1915308C",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915308C"
        },
        [10019508] = {
          Content = "？？？：“我会一直注视着……”",
          DialogueId = 10019508,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "191530B6",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530B6"
        },
        [10019509] = {
          Content = "？？？：“来自彼岸之人，你将驶向何方。”",
          DialogueId = 10019509,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "191530E0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/191530E0"
        },
        [10019510] = {
          Content = "（是谁……）",
          DialogueId = 10019510,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1915310A",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/1915310A"
        },
        [10025701] = {
          ContentTC = "這場逃亡，是從那場奇異的夢開始的；從小到大，我一直重複著相似的夢。",
          DialogueId = 10025701,
          Duration = 3,
          GUID = "19192992",
          NextDialogue = 10025702,
          Subtitle = [[
This escape was heralded by that odd dream.
I've been plagued by similar ones all my life.]],
          VoiceName = "voice/$Locale$/story/1002/100257/19192992"
        },
        [10025702] = {
          ContentTC = "但不容回想，我知道此刻有更急迫的事——",
          DialogueId = 10025702,
          Duration = 3,
          GUID = "191929BC",
          NextDialogue = 10025703,
          Subtitle = "But now's not the time for reflection...\nThere's something more pressing at the moment—",
          VoiceName = "voice/$Locale$/story/1002/100257/191929BC"
        },
        [10025703] = {
          ContentTC = "必須和貝蕾妮卡一起逃離這座叫做「淨界島」的小島，即使這是我們一起長大的地方。",
          DialogueId = 10025703,
          Duration = 4,
          GUID = "191929E6",
          Subtitle = [[
Berry and I must flee from this isle known as "Purgatorio Island",
where we spent our childhoods together.]],
          VoiceName = "voice/$Locale$/story/1002/100257/191929E6"
        },
        [10025704] = {
          ContentTC = "因為我們平靜的生活，早已被穢獸的利爪撕碎……",
          DialogueId = 10025704,
          Duration = 3,
          GUID = "19192A10",
          Subtitle = "For the peace we once knew has been torn asunder by the vile claws of Filthoids...",
          VoiceName = "voice/$Locale$/story/1002/100257/19192A10"
        },
        [10025801] = {
          ContentTC = "這些穢獸……死了？",
          DialogueId = 10025801,
          ExStoryInfo = "Player",
          GUID = "191939FA",
          NextDialogue = 10025802,
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/191939FA"
        },
        [10025802] = {
          ContentTC = "看來在我們之前，這裡就有人和穢獸戰鬥過。而且，還沒過去太久。",
          DialogueId = 10025802,
          GUID = "19193A24",
          NextDialogue = 10025803,
          SpeakNpcId = 100003,
          Subtitle = "It seems someone had a fight here with these Filthoids just before we came.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A24"
        },
        [10025803] = {
          ContentTC = "難道有村民逃到了這裡……不，那扇門是我們打開的才對。",
          DialogueId = 10025803,
          ExStoryInfo = "Player",
          GUID = "19193A4E",
          NextDialogue = 10025804,
          SpeakNpcId = 100001,
          Subtitle = "Could it be one of the villagers... No, we were the first to open that door.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A4E"
        },
        [10025804] = {
          ContentTC = "不過好在有他幫忙清理，否則穢獸就更難對付了。",
          DialogueId = 10025804,
          ExStoryInfo = "Player",
          GUID = "19193A78",
          NextDialogue = 10025805,
          SpeakNpcId = 100001,
          Subtitle = "Anyway, thanks to that person, we don't have to deal with these Filthoids ourselves.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193A78"
        },
        [10025805] = {
          ContentTC = "無論是誰，他的實力都不容小覷。我們也要留心。",
          DialogueId = 10025805,
          GUID = "19193AA2",
          SpeakNpcId = 100003,
          Subtitle = "Whoever it was, they're not to be underestimated. We must be vigilant.",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA2"
        },
        [10025806] = {
          ContentTC = "這些穢獸……斷氣了？",
          DialogueId = 10025806,
          ExStoryInfo = "Player",
          GUID = "19193AA3",
          SpeakNpcId = 100001,
          Subtitle = "Are these Filthoids... dead?",
          VoiceName = "voice/$Locale$/story/1001/100258/19193AA3"
        },
        [10027501] = {
          ContentTC = "在不遠處",
          DialogueId = 10027501,
          Duration = 2,
          GUID = "191A50E2",
          Subtitle = "A short distance away...",
          VoiceName = "voice/$Locale$/story/1001/100275/191A50E2"
        },
        [10029301] = {
          ContentTC = "無數次，螺旋般往復的夢中，我一遍又一遍地問著。",
          DialogueId = 10029301,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "1914AD4C",
          NextDialogue = 10018401,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "In my dreams that unfold like a double helix, I've asked myself that question countless times.",
          VoiceName = "voice/$Locale$/story/1002/100293/1914AD4C"
        },
        [10029309] = {
          Content = "恭喜你起名完成啦！！！！！",
          DialogueId = 10029309,
          Duration = 3,
          GUID = "1914AD4D",
          VoiceName = "voice/$Locale$/story/1002/100293/"
        },
        [10029401] = {
          ContentTC = "要再休息一會嗎？",
          DialogueId = 10029401,
          GUID = "1914AD4E",
          SpeakNpcId = 100003
        },
        [10030101] = {
          ContentTC = "呼……呼……",
          DialogueId = 10030101,
          Duration = 3,
          GUID = "191BFB72",
