        [10031210] = {
          ContentTC = "這是……一塊布？手感還挺好的。",
          DetectiveQuestionId = 1003,
          DialogueId = 10031210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MainCurtain.T_Guide_Chapter_MainCurtain'}",
