          NextDialogue = 10033603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100336/191E39D4"
        },
        [10033603] = {
          ContentTC = "嘖……接我們的人跟兇手撞上了？這下麻煩了啊。",
