        },
        [10034413] = {
          ContentTC = "警戒線都拉起來，動作快！",
          DialogueId = 10034413,
          GUID = "191EBE3B",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3B"
        },
        [10034414] = {
          ContentTC = "冰湖城這幾日宵禁，沒有許可禁止隨意走動。",
          DialogueId = 10034414,
          GUID = "191EBE3C",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3C"
        },
        [10034415] = {
          ContentTC = "銀燭狂歡之前肯定能結案，這些花花綠綠的裝飾就放著吧。",
          DialogueId = 10034415,
          GUID = "191EBE3D",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3D"
        },
        [10034416] = {
          ContentTC = "通訊測試，一二三一二三，通訊測試，一二三，能聽到嗎？好，我這兒聽著也沒問題。",
          DialogueId = 10034416,
          GUID = "191EBE3E",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3E"
        },
        [10034417] = {
          ContentTC = "說是宵禁，怎麼白天也不讓出去啊？",
          DialogueId = 10034417,
          GUID = "191EBE40",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE40"
        },
        [10034418] = {
          ContentTC = "該死，這批新鮮霜脊魚賣不出去了。",
          DialogueId = 10034418,
          GUID = "191EBE41",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE41"
        },
        [10034419] = {
          ContentTC = "噢，我心愛的女士，這個夜晚我孤枕難眠，明明我們只隔著兩條街的距離卻無法相見……",
          DialogueId = 10034419,
          GUID = "191EBE42",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE42"
        },
        [10034420] = {
          ContentTC = "長官行行好啊，我不過去乾活，全家都要餓死了……",
          DialogueId = 10034420,
          GUID = "191EBE43",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE43"
        },
        [10034421] = {
          ContentTC = "怎麼老是你？當心長官送你全家吃牢飯！",
          DialogueId = 10034421,
          GUID = "191EBE44",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE44"
        },
