        [10034601] = {
          ContentTC = "呵呵……",
          DialogueId = 10034601,
          GUID = "191EDDBA",
          NextDialogue = 10034602,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDBA"
        },
        [10034602] = {
          ContentTC = "你笑什麼？",
          DialogueId = 10034602,
          GUID = "191EDDE4",
          NextDialogue = 10034603,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDE4"
        },
        [10034603] = {
          ContentTC = "我想起上次這樣在湖邊釣魚，還是三年前和布魯斯一起。",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          ContentTC = "那傢伙雖然聰明，但太好動了，根本坐不住。所以他釣一整天，簍子都是空的。",
          DialogueId = 10034604,
          GUID = "191EDE38",
          NextDialogue = 10034605,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE38"
        },
        [10034605] = {
          ContentTC = "……不知道他現在在內城過得怎麼樣了，有沒有學會釣魚。",
          DialogueId = 10034605,
          GUID = "191EDE62",
          NextDialogue = 10034606,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE62"
        },
        [10034606] = {
          ContentTC = "哼哼，你們這些凡人啊，總被這些亂七八糟的感情羈絆，不像本魔王大人。",
          DialogueId = 10034606,
          GUID = "191EDE8C",
          NextDialogue = 10034607,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE8C"
        },
        [10034607] = {
          ContentTC = "沒事的小矮子，我們也是你的家人。只要你開心，讓我管你叫奶奶都行。",
          DialogueId = 10034607,
          GUID = "191EDEB6",
          NextDialogue = 10034608,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEB6"
        },
        [10034608] = {
          ContentTC = "你，你怎麼突然這麼好……",
          DialogueId = 10034608,
          GUID = "191EDEE0",
          NextDialogue = 10034609,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEE0"
        },
        [10034609] = {
          ContentTC = "奶奶，我餓，給點零用錢。",
          DialogueId = 10034609,
          GUID = "191EDF0A",
          NextDialogue = 10034610,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF0A"
        },
        [10034610] = {
          ContentTC = "可惡！",
          DialogueId = 10034610,
          GUID = "191EDF34",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF34"
        },
        [10034611] = {
          ContentTC = "這樣就齊了，把物資送到霧區吧。",
          DialogueId = 10034611,
          GUID = "191EDF5E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF5E"
        },
        [10034612] = {
          ContentTC = "宵禁期間禁止通行，請各位市民配合！",
          DialogueId = 10034612,
          GUID = "191EDF60",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF60"
        },
