          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "191F4906",
          SpeakNpcName = "Cp2CharacterName30",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4906"
        },
        [10035301] = {
          ContentTC = "收集這麼多錄音帶，你弟弟是不是很富有呀！",
          DialogueId = 10035301,
          GUID = "191F5092",
          NextDialogue = 10035302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5092"
        },
        [10035302] = {
          ContentTC = "不是的，那些都是他從朋友那裡翻錄的。",
          DialogueId = 10035302,
          GUID = "191F50BC",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50BC"
        },
        [10035303] = {
          ContentTC = "旋律很像，但不太一樣，兇手的聲音更悲傷一些。",
          DialogueId = 10035303,
          GUID = "191F50E6",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100353/191F50E6"
        },
        [10035304] = {
          ContentTC = "耳朵，我的耳朵！這也能叫歌嗎！布魯斯暗算我！",
