          SpeakNpcId = 100304,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F535C"
        },
        [10035319] = {
          ContentTC = "雖然是新的線索，但很遺憾，這條線索指向的範圍太廣了。《雪國的孩子》在蓋雷亞劇院已經上演了幾十年，曾經是非常熱門的劇，所以這裡很多人都會唱。",
          DialogueId = 10035319,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5386",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035320,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0071_lise_secret\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5386"
        },
        [10035320] = {
          Camera = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          ContentTC = "有一次，我和布魯斯攢了大半年的錢，好不容易才買到那場劇的門票，卻在現場被冤枉成偷了別人的票，被趕了出來。",
          DialogueId = 10035320,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F53B0",
          NextDialogue = 10035321,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53B0"
        },
        [10035321] = {
          ContentTC = "那夜我靠著劇院的牆坐了很久，心情糟透了。布魯斯卻像變魔術一樣掏出口琴，吹起了那首歌的旋律。原來，他自己早就練會了這首曲子……",
          DialogueId = 10035321,
          GUID = "191F53DA",
          NextDialogue = 10035322,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53DA"
        },
        [10035322] = {
          Camera = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "他吹著吹著，在牆的另一邊，突然就有個男孩子跟著唱起來了。他的歌喉好動聽，像雲雀一樣。",
          DialogueId = 10035322,
          FinalCamera = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F5404",
          NextDialogue = 10035323,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5404"
        },
        [10035323] = {
          Camera = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "那一晚，因為有布鲁斯的口琴，還有那個陌生人的跟唱，我好開心，都快忘了自己被趕出來的事。",
          DialogueId = 10035323,
          GUID = "191F542E",
          NextDialogue = 10035324,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F542E"
        },
        [10035324] = {
          Camera = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "抱歉，不好意思，自顧自地說起來了。我的意思是，這首歌會的人太多了，無法成為指向性的證據。",
          DialogueId = 10035324,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5458",
          NextDialogue = 10035325,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5458"
        },
        [10035325] = {
          Camera = "35.425781,210.5625,76.637207,0.000075,18.182783,-57.792496,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "那，這齣戲近期會上演嗎？沒準我們可以蹲點試試。",
          DialogueId = 10035325,
          FinalCamera = "35.425781,210.5625,76.637207,0.000069,11.982678,-57.391754,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F5482",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035326,
          SpeakNpcId = 200021,
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5482"
        },
        [10035326] = {
          Camera = "46.15625,-202.915527,167.463867,0.000052,-11.016801,66.199203,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "近期嗎……我不太清楚。不過據我所知，這齣劇這兩年已經停演了，因為一起發生在蓋雷亞劇院的<H>事故</>。",
          DialogueId = 10035326,
          GUID = "191F54AC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035327,
          SpeakNpcId = 100304,
          TalkActionId = {
            [1] = "100304:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54AC"
        },
        [10035327] = {
          Camera = "109.480469,38.969727,114.763672,0.000073,-0.616664,-141.401657,35.0,100000.0,false,Manual,22.0",
          ContentTC = "事故？",
          DialogueId = 10035327,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191F54D6",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035328,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54D6"
        },
        [10035328] = {
          Camera = "-151.640625,-339.61792,161.115723,0.000086,-9.217005,58.195625,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "嗯，之前整理案卷的時候，在筆錄裡看到的。倒不是什麼大事，只是兩年前演出現場的一起鬥毆。",
          DialogueId = 10035328,
          GUID = "191F5500",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035329,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5500"
        },
        [10035329] = {
          Camera = "24.625,-15.047363,93.071777,0.000097,8.781772,53.395985,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "但普奇劇團長說，因為這起事故中主演受了傷，「魔笛」劇團將暫停《雪國的孩子》的後續演出。",
          DialogueId = 10035329,
          GUID = "191F552A",
          NextDialogue = 10035330,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F552A"
        },
        [10035330] = {
          ContentTC = "我翻翻本子——嗯，還有當時抄的筆記。",
          DialogueId = 10035330,
          GUID = "191F5554",
          NextDialogue = 10035331,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5554"
        },
        [10035331] = {
          ContentTC = "蓋雷亞劇院鬥毆事件\n\n時間：10月9日晚8:30\n\n報案人：萊蒂齊亞·普奇（「魔笛」劇團團長）\n\n參與鬥毆雙方：帕西法爾·斯諾菲爾德（主演）、蘇珊娜·羅西（主演）……\n馬修·伯納德（觀眾）、菲莉·弗蘭西斯科（觀眾）……\n\n事件：疑似劇團成員與前排觀眾就劇目發生衝突？疑似觀眾毆打演員？（部分筆錄內頁被撕掉了）\n\n結論：證據不足，不予立案\n\n備註：《雪國的孩子》暫時停演，演出時間不定。\n很想和布魯斯彌補一下當年看不成劇的遺憾，但似乎短時間內沒有機會了。",
          DialogueId = 10035331,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000049;content:READ_TEXT_2000049}",
          GUID = "191F557E",
          NextDialogue = 10035332,
          VoiceName = "voice/$Locale$/story/1003/100353/191F557E"
        },
        [10035332] = {
          Camera = "-175.097656,-375.326904,138.394531,0.000041,-5.200041,58.387745,35.000011,100000.0,false,Manual,22.0",
          ContentTC = "不過，除了繼續調查下水道之外，眼下也只有這一條新線索了……",
          DialogueId = 10035332,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-159.128906,-349.168457,135.712402,0.000042,-5.000033,59.587662,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F55A8",
