        },
        [10035421] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117",
          ContentTC = "……這麼說來，它在見到黎瑟後，的確<H>一直在留手，沒有傷害我們</>。",
          DialogueId = 10035421,
          GUID = "191F6442",
