        [10035425] = {
          Camera = "53.945312,-48.872559,263.330078,0.000002,-24.832872,18.36636,28.000006,100000.0,false,Manual,22.0",
          DialogueId = 10035425,
          DialoguePanelType = "None",
          Duration = 7,
          GUID = "191F6347",
          NextDialogue = 10035416,
          Scripts = [[

PARA{
PlayAnimation{_delay{0},ActorId{100327},AnimationId{"Tuosi02_Story_Find02_Start"},Duration{5}}
}]]
        },
        [10035501] = {
          ContentTC = "「桂冠卡戎」——我曾視它為一顆最璀璨的金剛石。\n它在夢想的盡頭熠熠生輝，如冰湖城最高處，那盞不滅的明燈。",
          DialogueId = 10035501,
          Duration = 4,
          GUID = "191F7162",
          NextDialogue = 10035502,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7162"
        },
        [10035502] = {
          ContentTC = "後來我才知道，那並非堅硬的金剛石。\n它是玻璃——折射著虛幻的光，美麗，奪目，\n但一顆卵石，一塊泥磚，便將它輕易打碎。",
          DialogueId = 10035502,
          Duration = 4,
          GUID = "191F718C",
          NextDialogue = 10035503,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F718C"
        },
        [10035503] = {
          ContentTC = "通過第六軍團考核的卡戎之民，與任人宰割的困獸沒有任何差別。\n倒不如說我們寧願成為一頭無知麻木的野獸——\n這樣我們便不會為破滅的夢而痛苦，不會因無法完成的約定而慟哭。",
          DialogueId = 10035503,
          Duration = 4,
          GUID = "191F71B6",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71B6"
        },
        [10035504] = {
          ContentTC = "（好刺眼的燈光……這是哪裡？我記得通過考核後，被派到第六軍團煉金院工作，然後……）",
          DialogueId = 10035504,
          GUID = "191F71E0",
          RelatedWikiId = {
            [1] = 407003,
            [2] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71E0"
        },
        [10035505] = {
          ContentTC = "老師，改造體的意識好像提前甦醒了。它看起來很痛苦，我再取一點麻醉劑。",
          DialogueId = 10035505,
          GUID = "191F720A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F720A"
        },
        [10035506] = {
          ContentTC = "無妨，醒了就醒了吧。做好準備，2分鐘後開始採集它的抗性數據。",
          DialogueId = 10035506,
          GUID = "191F7234",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7234"
        },
        [10035507] = {
          DialogueId = 10035507,
          GUID = "191F725E",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F725E"
        },
        [10035508] = {
          ContentTC = "老師，數據出來了。它在這批改造體中的抗性表現優異，電流未能直接擊穿您移植進去的第二心臟，火焰損傷了它的人造皮膚，導致它的體溫遠高於正常值。",
          DialogueId = 10035508,
          GUID = "191F7288",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7288"
        },
        [10035509] = {
          ContentTC = "數據記錄完畢。我先帶它回去休息吧，它的體力恐怕撐不住了。",
          DialogueId = 10035509,
          GUID = "191F72B2",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72B2"
        },
        [10035510] = {
          ContentTC = "不要對這些惡魔報以無謂的憐憫。注射鎮定劑，固定好四肢，接下來要進行強化實驗了。",
          DialogueId = 10035510,
          GUID = "191F72DC",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72DC"
        },
        [10035511] = {
          ContentTC = "（痛……好痛啊……你們到底對我做了什麼，全身每一處毛孔都在哀嚎著疼痛，你們聽不到嗎！）",
          DialogueId = 10035511,
          GUID = "191F7306",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7306"
        },
        [10035512] = {
          ContentTC = "多麼豐富的表情。怎麼？想要吠叫什麼？可惜沒機會了。",
          DialogueId = 10035512,
          GUID = "191F7330",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7330"
        },
        [10035513] = {
          ContentTC = "鎮定劑注射完畢。老師，我還是覺得──",
          DialogueId = 10035513,
          GUID = "191F735A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F735A"
        },
        [10035514] = {
          ContentTC = "聽我吩咐。從它最敏感的尖角開始取樣，這樣我們才能得到更精確的數據。",
          DialogueId = 10035514,
          GUID = "191F7384",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7384"
        },
        [10035515] = {
          ContentTC = "……是，老師……",
          DialogueId = 10035515,
          GUID = "191F73AE",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73AE"
        },
        [10035516] = {
          ContentTC = "（好痛……好痛……這就是身為「惡魔的孩子」，必須經受的懲罰嗎……）",
          DialogueId = 10035516,
          GUID = "191F73D8",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73D8"
        },
        [10035517] = {
          ContentTC = "（但無論是怎樣的罪孽，這樣的痛苦……也早該還清了吧……！）",
          DialogueId = 10035517,
          GUID = "191F7402",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7402"
        },
        [10035518] = {
          ContentTC = "我們不知道這樣的日子過去了多久，只知道自己的身體正一步步變成可怖的怪物。\n心也變得越發冰冷，碎裂在淚湖的冷風之中。",
          DialogueId = 10035518,
          GUID = "191F742C",
          NextDialogue = 10035519,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F742C"
        },
        [10035519] = {
          ContentTC = "生而為人的舊日記憶漸行漸遠。最終，連名字都被遺忘。",
          DialogueId = 10035519,
          GUID = "191F7456",
          NextDialogue = 10035520,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7456"
        },
        [10035520] = {
          ContentTC = "布魯斯·費西爾死了。取而代之的是<W>47號</>——這個新的「稱呼」。",
          DialogueId = 10035520,
          GUID = "191F7480",
          NextDialogue = 10035521,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7480"
        },
        [10035521] = {
          ContentTC = "可即使如此，我們的肉體依舊在苟延殘喘地掙扎著。",
          DialogueId = 10035521,
          GUID = "191F74AA",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F74AA"
        },
        [10035522] = {
          Camera = "-4.90918,-156.237305,105.101868,-0.000091,10.758511,116.110672,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "報告老師，排異反應終止了，各項指標趨於平穩。就是β型抑制劑好像使用太多了，精神狀態不穩定。",
          DialogueId = 10035522,
          FinalCamera = "-9.579102,-158.523438,105.101868,-0.000092,10.758511,114.710289,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "191F74D4",
          NextDialogue = 10035523,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000069,7.559721,84.699837,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000061,11.159675,84.499451,35.0,100000.0,false,DoNotOverride,2.8\"},duration{5}}}",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          TalkActionId = {
            [1] = "100337:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74D4"
        },
        [10035523] = {
          Camera = "-179.390625,29.248047,164.763611,0.000084,-5.841492,-25.696522,35.0,251.812622,false,Manual,2.797869",
          ContentTC = "精神不過是生命代謝的廢料，改造體能回答「是」就足夠了。帶它去試驗場。",
          DialogueId = 10035523,
          FinalCamera = "-182.842773,22.280273,164.763611,0.000086,-5.841492,-21.695681,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F74FE",
          NextDialogue = 10035524,
          SpeakNpcId = 100337,
          SpeakNpcName = "Cp2CharacterName04",
          TalkActionId = {
            [1] = "100337:Explain01_End",
            [2] = "100336:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74FE"
        },
        [10035524] = {
          Camera = "20.333008,-203.238281,111.764038,0.00009,4.758661,116.695335,35.0,251.812622,false,Manual,2.797869",
          ContentTC = "是，老師。",
          DialogueId = 10035524,
          FinalCamera = "20.333008,-203.238281,111.764038,0.000089,7.758616,116.69487,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F7528",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          TalkActionId = {
            [1] = "100337:Agree",
            [2] = "100336:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F7528"
        },
        [10035601] = {
          ContentTC = "有抑制劑在，<H>連違背我們的命令都做不到</>，簡直像是牲畜一樣。",
          DialogueId = 10035601,
          GUID = "191F81CA",
          NextDialogue = 10035602,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81CA"
        },
        [10035602] = {
          ContentTC = "兇惡野蠻，缺乏理性且毫無美感。不過，這才是卡戎之民原初的模樣。",
          DialogueId = 10035602,
          GUID = "191F81F4",
          NextDialogue = 10035603,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81F4"
        },
        [10035603] = {
          ContentTC = "喂，離它遠點，說不定身上有什麼不乾淨的呢。",
          DialogueId = 10035603,
          GUID = "191F821E",
          NextDialogue = 10035604,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F821E"
        },
        [10035604] = {
          ContentTC = "等會兒好好記下它的戰鬥數據，不達標或者有可疑舉動就處理掉。",
          DialogueId = 10035604,
          GUID = "191F8248",
          NextDialogue = 10035605,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8248"
        },
        [10035605] = {
          ContentTC = "這樣真的可以嗎？會不會太殘忍了？",
          DialogueId = 10035605,
          GUID = "191F8272",
          NextDialogue = 10035606,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8272"
        },
        [10035606] = {
          ContentTC = "不，應該說正是吾皇的仁慈和煉金技術的偉大，才能賜予這樣的垃圾獻身於煉金院的價值。",
          DialogueId = 10035606,
          GUID = "191F829C",
          NextDialogue = 10035607,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F829C"
        },
        [10035607] = {
          ContentTC = "不要想著逃跑，電網與機砲可不像我們這般仁慈。也不要想著自毀，我們還有不少藥品可以延續你那一文不值的生命。",
          DialogueId = 10035607,
          GUID = "191F82C6",
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C6"
        },
        [10035608] = {
          ContentTC = "測試開始，投放改造體。",
          DialogueId = 10035608,
          GUID = "191F82F0",
          NextDialogue = 10035609,
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82F0"
        },
        [10035609] = {
          ContentTC = "47號，消滅一切阻攔者。",
          DialogueId = 10035609,
          GUID = "191F831A",
          NextDialogue = 10035610,
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F831A"
        },
        [10035610] = {
          ContentTC = "是。",
          DialogueId = 10035610,
          GUID = "191F8344",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8344"
        },
        [10035611] = {
          ContentTC = "那邊還有敵人，不要停下來喔。",
          DialogueId = 10035611,
          GUID = "191F836E",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F836E"
        },
        [10035612] = {
          ContentTC = "數據落後預期了，去把那邊的敵人也清理掉，快。",
          DialogueId = 10035612,
          GUID = "191F8398",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8398"
        },
        [10035613] = {
          ContentTC = "加油！加油！",
          DialogueId = 10035613,
          GUID = "191F83C2",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83C2"
        },
        [10035614] = {
          ContentTC = "受傷了？這麼脆弱嗎？",
          DialogueId = 10035614,
          GUID = "191F83EC",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83EC"
        },
        [10035615] = {
          ContentTC = "去那邊哦~",
          DialogueId = 10035615,
          GUID = "191F8416",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8416"
        },
        [10035616] = {
          ContentTC = "那邊的敵人還有口氣，這種敵人都處理不好嗎？",
          DialogueId = 10035616,
          GUID = "191F8440",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8440"
        },
        [10035617] = {
          ContentTC = "測試通過，帶回收容處。我們準備迎接下一批改造體了。",
          DialogueId = 10035617,
          GUID = "191F846A",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F846A"
        },
        [10035618] = {
          ContentTC = "數據什麼時候出來？等不及了。",
          DialogueId = 10035618,
          GUID = "191F82C7",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C7"
        },
        [10035619] = {
          ContentTC = "希望這只能成功吧。",
          DialogueId = 10035619,
          GUID = "191F82C8",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C8"
        },
        [10035620] = {
          ContentTC = "三天後開始第五次強化。",
          DialogueId = 10035620,
          GUID = "191F82C9",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C9"
        },
        [10035621] = {
          ContentTC = "可惜報廢率有點高……",
          DialogueId = 10035621,
          GUID = "191F82CA",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82CA"
        },
