        [10037009] = {
          Camera = "-54.876953,-874.34314,116.808594,0.000103,10.605344,-44.881695,50.000008,172.15979,false,Manual,5.0",
          ContentTC = "這是我必須做的事——<H>完成這場演出</>。",
          DialogueId = 10037009,
          FinalCamera = "-54.876953,-874.34314,118.550781,0.000104,10.605344,-45.282009,60.0,172.15979,false,Manual,5.0",
          GUID = "192068CA",
          SpeakNpcId = 100312,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100370/192068CA"
        },
        [10037101] = {
          ContentTC = "很久以前，雪國城堡裡，冰霜的妖精被兩個孩子喚醒",
          DialogueId = 10037101,
          GUID = "192077E2",
          VoiceName = "voice/$Locale$/story/1003/100371/192077E2"
        },
        [10037102] = {
          ContentTC = "孩子們點燃燈火，但火焰也融化不了堅冰的心臟",
          DialogueId = 10037102,
          GUID = "1920780C",
          VoiceName = "voice/$Locale$/story/1003/100371/1920780C"
        },
        [10037103] = {
          ContentTC = "迎著霜雪，日復一日，他們依舊來城堡與妖精嬉戲",
          DialogueId = 10037103,
          GUID = "19207836",
          VoiceName = "voice/$Locale$/story/1003/100371/19207836"
        },
        [10037104] = {
          ContentTC = "漸漸的，妖精習慣了他們的笑語歡歌",
          DialogueId = 10037104,
          GUID = "19207860",
          VoiceName = "voice/$Locale$/story/1003/100371/19207860"
        },
        [10037105] = {
          ContentTC = "「如果我也能像他們一樣笑就好了。」",
          DialogueId = 10037105,
          GUID = "1920788A",
          VoiceName = "voice/$Locale$/story/1003/100371/1920788A"
        },
        [10037106] = {
          ContentTC = "「如果我那顆寒冰的心，也能變暖些就好了。」",
          DialogueId = 10037106,
          GUID = "192078B4",
          VoiceName = "voice/$Locale$/story/1003/100371/192078B4"
        },
        [10037201] = {
          ContentTC = "有一天，野獸的爪牙伸向了雪國",
          DialogueId = 10037201,
          GUID = "1920884A",
          NextDialogue = 10037202,
          VoiceName = "voice/$Locale$/story/1003/100372/1920884A"
        },
        [10037202] = {
          ContentTC = "大地和天空被染成朱紅",
          DialogueId = 10037202,
          GUID = "19208874",
          NextDialogue = 10037203,
          VoiceName = "voice/$Locale$/story/1003/100372/19208874"
        },
        [10037203] = {
          ContentTC = "妖精離開了它的城堡，為了男孩的遺願",
          DialogueId = 10037203,
          GUID = "1920889E",
          NextDialogue = 10037204,
          VoiceName = "voice/$Locale$/story/1003/100372/1920889E"
        },
        [10037204] = {
          ContentTC = "「我答應你，我會到山下，找到你的親人，保護她平安。」",
          DialogueId = 10037204,
          GUID = "192088C8",
          VoiceName = "voice/$Locale$/story/1003/100372/192088C8"
        },
        [10037205] = {
          ContentTC = "鎮上群獸環伺，女孩被巨獸圍困在廢墟中央",
          DialogueId = 10037205,
          GUID = "192088F2",
          VoiceName = "voice/$Locale$/story/1003/100372/192088F2"
        },
        [10037206] = {
          ContentTC = "「該如何讓戰火遠離他的故鄉，讓她不再躲躲藏藏？」",
          DialogueId = 10037206,
          Duration = 10,
          GUID = "1920891C",
          NextDialogue = 10037207,
          VoiceName = "voice/$Locale$/story/1003/100372/1920891C"
        },
        [10037207] = {
          ContentTC = "「該如何驅趕那些巨獸，即使代價是我冰凍的心臟？」",
          DialogueId = 10037207,
          Duration = 10,
          GUID = "19208946",
          VoiceName = "voice/$Locale$/story/1003/100372/19208946"
        },
        [10037208] = {
          ContentTC = "渺小的妖精飛向巨獸，但巨獸稍稍用力，就折斷了它的四肢",
          DialogueId = 10037208,
          GUID = "19208970",
          NextDialogue = 10037209,
          VoiceName = "voice/$Locale$/story/1003/100372/19208970"
        },
        [10037209] = {
          ContentTC = "它聽到心臟的聲音，第一次鼓動著，吶喊著它的命運——",
          DialogueId = 10037209,
          GUID = "1920899A",
          VoiceName = "voice/$Locale$/story/1003/100372/1920899A"
        },
        [10037210] = {
          ContentTC = "「妖精是無法戰勝野獸的，與野獸搏鬥者要先讓自己化身野獸。」",
          DialogueId = 10037210,
          GUID = "192089C4",
          VoiceName = "voice/$Locale$/story/1003/100372/192089C4"
        },
        [10037211] = {
          ContentTC = "「那便捨棄我的身軀吧，讓我的四肢變成撕碎敵人的利爪……」",
          DialogueId = 10037211,
          Duration = 10,
          GUID = "192089EE",
          NextDialogue = 10037212,
          VoiceName = "voice/$Locale$/story/1003/100372/192089EE"
        },
        [10037212] = {
