        },
        [10037802] = {
          ContentTC = "刻痕……刻痕……",
          DialogueId = 10037802,
          GUID = "1920EAE4",
          NextDialogue = 10037803,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EAE4"
        },
        [10037803] = {
          ContentTC = "找到了，那邊墻壁上有刀劃過的痕跡。",
          DialogueId = 10037803,
          GUID = "1920EB0E",
          NextDialogue = 10037804,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB0E"
        },
        [10037804] = {
          ContentTC = "在哪在哪？",
          DialogueId = 10037804,
          GUID = "1920EB38",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB38"
        },
        [10037805] = {
          ContentTC = "快到了，銀色和平廣場下方……嗯，就是前面的區域。",
          DialogueId = 10037805,
          GUID = "1920EB62",
          NextDialogue = 10037806,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB62"
        },
        [10037806] = {
          ContentTC = "前面嗎？可是過道都被淹了誒……對了！垃圾桶公主說過可以用<H>水閥</>！",
          DialogueId = 10037806,
          GUID = "1920EB8C",
          NextDialogue = 10037807,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB8C"
        },
        [10037807] = {
          ContentTC = "嗯，啟動那邊的<H>水閥</>排乾淨水再過去吧。",
          DialogueId = 10037807,
          GUID = "1920EBB6",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBB6"
        },
        [10037808] = {
          ContentTC = "有穢獸，大家小心。",
          DialogueId = 10037808,
          GUID = "1920EBE0",
          NextDialogue = 10037809,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBE0"
        },
        [10037809] = {
          ContentTC = "不是說帝國這些年很注重地下設施，怎麼下水道隨便敲一竿子，都能敲出來穢獸啊。",
          DialogueId = 10037809,
          GUID = "1920EC0A",
          NextDialogue = 10037810,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC0A"
        },
        [10037810] = {
          ContentTC = "抱歉……任務結束後我一定加強下水道的巡邏工作……",
          DialogueId = 10037810,
          GUID = "1920EC34",
          NextDialogue = 10037811,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC34"
        },
        [10037811] = {
          ContentTC = "唉，我不是說你——算了算了，先趕緊解決它們吧。",
          DialogueId = 10037811,
          GUID = "1920EC5E",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC5E"
        },
        [10037812] = {
          ContentTC = "呼，好了。那邊還有另一個水閥。",
          DialogueId = 10037812,
