        [10102502] = {
          Camera = "78.0,-7.4375,131.521484,0.000191,-2.398646,-161.013702,35.000008,175.980392,false,Manual,4.0",
          ContentTC = "沒了那袋銅幣，那群老老少少下個月都要喝西北風了。唉，小賊不知道跑哪兒去了，我得找個人幫我一起堵他。",
          DialogueId = 10102502,
          FacialId = {
            [1] = "200011:Sad01"
          },
          GUID = "194A61BC",
          LookAt = {
            [1] = "200003:n(200011)"
          },
          NextDialogue = 10102503,
          Scripts = "PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Sigh_Start\"},Duration{2}}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Without that bag of coins, all the young and old will have to tighten their belts even more next month. Ugh... I've no idea where the thief has run off to, I need someone to help me nab him.",
          TalkActionId = {
            [1] = "200011:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A61BC"
        },
        [10102503] = {
