        },
        [10102609] = {
          Camera = "291.657104,98.844727,170.599609,0.001316,-5.498842,-164.352921,52.422081,496.264801,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "醜話說在前頭，這不是小孩子玩鬧，更不是什麽輕松活計。這裡是不問來歷、不問出身，但你得到的每一枚回報，都伴隨著相應的危險。",
          DialogueId = 10102609,
          FacialId = {
            [1] = "200011:Unhappy01"
          },
          FinalCamera = "231.961548,82.132812,164.626953,0.001316,-5.498842,-164.352844,52.422081,430.432526,false,Manual,4.0",
          GUID = "194A734A",
          LookAt = {
            [1] = "200011:n(200003)",
            [2] = "200006:n(200003)",
            [3] = "200003:n(100001)"
          },
          NextOptions = {
            [1] = 101026091,
            [2] = 101026092
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Confident_End"},Duration{2}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{2.5}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Let's get one thing straight — this isn't child's play, nor an easy gig. It's false that in this place,\nno one would probe into your past or background, but the rewards always come with risks.",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101026/194A734A"
        },
        [10102610] = {
          Camera = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
          ContentTC = "模樣不算硬朗，想法倒是堅決。",
          DialogueId = 10102610,
          FacialId = {
            [1] = "200006:None",
            [2] = "200011:None"
          },
          GUID = "194A7374",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102611,
          SpeakNpcId = 200003,
          Subtitle = "You don't look tough, though your courage is admirable.",
          TalkActionId = {
            [1] = "200003:Talk03_Start",
            [2] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A7374"
        },
        [10102611] = {
          Camera = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
          ContentTC = "你身手確實比一般的卡戎強些，我見過。但想要成為狩月人的話，只有蠻力是不夠的——你還得證明自己能夠應付突發事件與各式各樣的雇主。",
          DialogueId = 10102611,
          FinalCamera = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
          GUID = "194A739E",
          NextDialogue = 10102612,
          Scripts = "SetLocation{ActorId{200011},TargetPoint{\"P10102601Maer\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200003,
          Subtitle = "You're indeed stronger than the average Charons — I've seen you in a fight. But brute strength isn't enough to\nqualify you to be a Phoxhunter. You need to prove that you're capable of dealing with\nall possible contingencies and a very mixed group of clients.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101026/194A739E"
        },
        [10102612] = {
          Camera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
