}]],
          SpeakNpcId = 200065,
          Subtitle = "Ah, hi Snow! Lending a hand to the Phoxhunters again? What is it this time —\nNabbed a few hundred bandits, thwarted a dozen dastardly schemes?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101038/194B36DA"
        },
        [10103802] = {
          Camera = "297.337158,171.632812,207.998047,0.001337,-21.800159,-149.094604,40.000011,379.447693,false,Manual,2.0",
          ContentTC = "今天我比較低調，只抓了一個小偷。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103802,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "194B3704",
          NextDialogue = 10103803,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Explain02_Start"},Duration{2.4}},
PlayAnimation{ActorId{200002},AnimationId{"Confident_Start"},Duration{0.5}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Today I'm keeping it low-key, just nabbed a petty thief.",
          TalkActionId = {
            [1] = "200065:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B3704"
        },
        [10103803] = {
          Camera = "-15.678711,45.273438,123.974609,0.001306,6.799911,-0.799835,30.000002,169.71138,false,Manual,2.5",
          ContentTC = "抓了一個？這聽起來倒跟真的似的，我得見識見識。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103803,
          GUID = "194B372E",
          NextDialogue = 10103804,
          SpeakNpcId = 200065,
          Subtitle = "Just one? That sounds almost believable, I've got to see this.",
          TalkActionId = {
            [1] = "200065:Think_Start",
            [2] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B372E"
        },
        [10103804] = {
          Camera = "174.522949,141.578125,137.132812,0.001337,-15.600308,-143.896393,35.0,212.370575,false,Manual,2.8",
          ContentTC = "之前也沒說過假話！快來快來，我的小僕從，這是威爾斯大叔，這裡最勤快的狩月人啦。",
          DialogueId = 10103804,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "194B3758",
          NextDialogue = 10103805,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Angry01_Start"},Duration{2}},
PlayAnimation{ActorId{200002},AnimationId{"Angry01_End"},Duration{0.9}},
PARA{
