PlayAnimation{ActorId{200002},AnimationId{"Explain01_Start"},Duration{1}}
}
},
LookAt{_delay{3.3},LookAtDescription{"200065:n(100001)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "I've never fibbed before! Come here, my little minion. This is Mr Wells, the most hard-working Phoxhunter around here.",
          TalkActionId = {
            [1] = "200065:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B3758"
        },
        [10103805] = {
          Camera = "-188.142944,-38.378906,104.90625,0.001338,4.199221,13.510482,25.0,364.620758,false,Manual,1.3",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "你好，威爾斯先生。",
          DialogueId = 10103805,
          Duration = 2,
