          SpeakNpcId = 100001,
          Subtitle = "Hello, Mr Wells.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101038/194B3782"
        },
        [10103806] = {
          Camera = "-220.573608,96.777344,99.291016,0.001347,2.799155,-17.691002,30.000002,397.786072,false,Manual,2.5",
          ContentTC = "就是你？長得白白凈凈，看不出來還真有點「本事」啊？",
          DialogueId = 10103806,
          GUID = "194B37AC",
          LookAt = {
            [1] = "200002:n(200065)",
            [2] = "100001:n(200065)"
          },
          NextDialogue = 10103807,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200065},AnimationId{"Talk03_Start"},Duration{3.4}},
PlayAnimation{ActorId{200065},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{ActorId{200065},AnimationId{"Disagree"},Duration{1}}
}]],
          SpeakNpcId = 200065,
          Subtitle = "So it was you? Looking all neat and tidy, who'd have thought you had it in you?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B37AC"
        },
        [10103807] = {
          Camera = "284.5,160.327148,200.447266,0.001179,-15.600097,-147.194611,35.000011,345.690643,false,Manual,2.25",
          ContentTC = "過獎了，小事而已。",
          DialogueId = 10103807,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "194B37D6",
          NextDialogue = 10103808,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Explain02_End"},Duration{0.9}},
PlayAnimation{ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Thanks, it was just a small thing.",
          VoiceName = "voice/$Locale$/story/1002/101038/194B37D6"
        },
        [10103808] = {
          Camera = "-88.652222,34.671875,132.285156,0.00134,1.999114,2.708378,30.0,289.613831,false,Manual,1.6",
          CameraBlendCurve = "easeOutQuad",
          ContentTC = "小事？我跟你說，就是你們這些幹小事的人太多，冰湖城才是現在這副樣子。要是幹什麽大事，那冰湖城還不得翻了天去。",
          DialogueId = 10103808,
          FinalCamera = "-37.667603,37.084961,137.621094,0.00134,1.999114,2.708446,30.0,210.36618,false,Manual,1.6",
          GUID = "194B3800",
          NextDialogue = 10103809,
          Scripts = [[
