        [10104018] = {
          Camera = "586.407837,263.538086,166.693359,0.001254,-5.098381,-163.341629,60.0,424.533936,false,Manual,3.8",
          ContentTC = "你說過的。如果連這點事都做不到，那我靠什麽去找我……弄丟的寶物。",
          DialogueId = 10104018,
          ExStoryInfo = "Player",
          GUID = "194B5A74",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200006:n(100001)"
