        },
        [10106211] = {
          Camera = "247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876",
          ContentTC = "那位總是放許多糖的小姐一定有著強大的魔法。所以在{性别:大哥哥|大姐姐}眼裡，和她有關的一切都是好的，哪怕是甜到無法下咽的飯菜。",
          DialogueId = 10106211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200020:Happy02"
          },
          GUID = "194CC23E",
