          SpeakNpcId = 200021,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1C18"
        },
        [10108401] = {
          ContentTC = "說起來，你的父母是什麽人？",
          DialogueId = 10108401,
          Duration = 4,
          GUID = "194E298A",
          NextDialogue = 10108402,
          SpeakNpcId = 200021,
          Subtitle = "By the way, what do your parents do?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E298A"
        },
        [10108402] = {
          ContentTC = "怎麽突然問這個？",
          DialogueId = 10108402,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E29B4",
          NextDialogue = 10108403,
          SpeakNpcId = 100001,
          Subtitle = "Why do you ask?",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29B4"
        },
        [10108403] = {
          ContentTC = "當然是因為和鳴之力很特別啊。卡戎之民的魔法，大多與血脈有關。沒準你就大有來頭。",
          DialogueId = 10108403,
          Duration = 4,
          GUID = "194E29DE",
          NextDialogue = 10108404,
          SpeakNpcId = 200021,
          Subtitle = "Well, because the power of Resonance is quite special, isn't it? The magical abilities among Charons often relate to their bloodline. Who knows, you might be from some prestigious background.",
          VoiceName = "voice/$Locale$/story/1002/101084/194E29DE"
        },
        [10108404] = {
          ContentTC = "其實我也不知道……我從記事起就和貝蕾相依為命。其他的，就不太清楚了。",
          DialogueId = 10108404,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194E2A08",
          NextDialogue = 10108405,
          SpeakNpcId = 100001,
          Subtitle = "Truth is, I don't know... It's always been just Berry and me since my earliest memories. I don't remember any other family members.",
