          NextDialogue = 10109011,
          SpeakNpcId = 100001,
          Subtitle = "How do you know...",
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D4A"
        },
        [10109011] = {
          Camera = "27.23291,-17.217773,150.117188,0.000137,-1.001114,-142.583847,20.0,150.644867,false,Manual,1.449662",
          ContentTC = "猜的。你這反應也太大了吧，突然一下子就把所有的權衡啊、顧慮啊，都拋到腦後了。那個小姑娘對你挺重要的？",
          DialogueId = 10109011,
          GUID = "194E8D74",
          NextDialogue = 10109012,
          SpeakNpcId = 200021,
          Subtitle = "I can see it. When it comes to things you truly care about, you toss all caution and reservations to the wind.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D74"
        },
        [10109012] = {
          Camera = "-443.760742,1671.63916,3315.651855,0.000195,-7.202202,93.220032,10.0,150.644867,false,DoNotOverride,1.449662",
          CameraBlendCurve = "easeInQuad",
          ContentTC = "如果你忽然一天被丟到舉目無親的他鄉，你覺得自己就像一只皮球，人人都能踢一腳……而這時，有個人向你伸出手，告訴你，活著就會有好事發生。",
          DialogueId = 10109012,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-443.760742,1671.63916,3818.100098,0.000195,-7.202202,93.220032,10.0,150.644867,false,DoNotOverride,1.449662",
          GUID = "194E8D75",
          NextDialogue = 10109013,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D75"
        },
        [10109013] = {
