        [10109411] = {
          ContentTC = "好。",
          DialogueId = 10109411,
          GUID = "10109411"
        },
        [10109501] = {
          ContentTC = "是淚湖畔，那附近有一截老樹根。小時候，爸爸曾帶我去過那兒。",
          DialogueId = 10109501,
          GUID = "194EDE02",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10109502,
          SpeakNpcId = 200006,
          Subtitle = "It's a cave... My dad once took me there when I was little.",
          VoiceName = "voice/$Locale$/story/1002/101095/194EDE02"
        },
        [10109502] = {
          ContentTC = "……已經過去那麽多年了啊……",
          DialogueId = 10109502,
          GUID = "194EDE2C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's been so long...",
