          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "用你的眼睛，替我繼續看看這個世界吧。",
          DialogueId = 10109716,
          FinalCamera = "-73.710938,92.207031,66.693359,0.000262,3.399228,-0.487854,52.0,93.129883,false,Manual,5.0",
          GUID = "194F0076",
          NextDialogue = 10109717,
          SpeakNpcId = 200006,
          Subtitle = "Please see the world for me with your eyes.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101097/194F0076"
        },
        [10109717] = {
