        [10109718] = {
          Camera = "198.785156,-175.792969,10.463867,-3.000001,7.397299,129.297333,35.0,447.397217,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "難得出來一趟，我們就在湖上隨便走走吧？",
          DialogueId = 10109718,
