        [10110602] = {
          Camera = "-58.66626,184.545898,58.416016,0.000013,9.599646,-71.385262,25.000002,245.13945,false,Manual,22.0",
          ContentTC = "剛才不會是你在鬼叫吧？出什麽事了？",
          DialogueId = 10110602,
