          GUID = "191BDB20",
          NextDialogue = 10111804,
          SpeakNpcId = 200038,
          Subtitle = "...At this point, there's nothing left but to turn to Dr Henrik Ethelred. It's the last thing we can do for her.",
          VoiceName = "voice/$Locale$/story/1002/101118/191BDB20"
        }
      }
