          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Deterioration is irreversible. Even in my destruction, what could you possibly alter?",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA87"
        },
        [10112601] = {
