          Duration = 3,
          GUID = "195481EC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/195481EC"
        },
        [10118303] = {
