          Duration = 3,
          GUID = "1954A292",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10118502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A292"
