          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1954A2E6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2E6"
