        },
        [10119803] = {
          ContentTC = "你拿著就好！可以給自己買點漂亮衣服什麽的，我……沒什麽需要用錢的地方。",
          DialogueId = 10119803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          ContentTC = "這是什麽？",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          ContentTC = "唔……是開門的機關！藏得好嚴實。",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          ContentTC = "怎麽這麽多……呃……呃呃……",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          ContentTC = "從我大腿上下來，白。你這樣我動不了了……你先回冰湖城吧，我不會笑話你的。",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          ContentTC = "不不不不回去，沒沒沒沒有經歷過冒冒冒險的人生一定是不不不不不完整的！",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          ContentTC = "好呀，那我就陪著{nickname}和魔王大人一起，把人生變「完整」一點吧。",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          ContentTC = "剛剛我應該沒有拖後腿……所以接下來，我想也不會有問題的！",
          DialogueId = 10120105,
          Duration = 3,
          GUID = "1955A9BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120106,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9BA"
        },
        [10120106] = {
          ContentTC = "嗯，我們繼續往前走吧。",
          DialogueId = 10120106,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A9E4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10120107,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A9E4"
        },
        [10120107] = {
