        [10125926] = {
          Camera = "710.461914,-429.099609,211.467773,-5.000003,-8.998446,134.579147,18.0,1651574.625,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentTC = "有朝一日，當你獲得了足夠強大的力量——當你能夠直面世界的真相，甚至打破構築它的法則本身……",
