        },
        [10127001] = {
          Camera = "-261.964844,-143.53418,117.835449,0.000286,-8.398476,29.395039,18.0,411.462158,false,DoNotOverride,2.0",
          ContentTC = "懷抱著襁褓的小小搖籃，如今已經落滿塵埃。",
          DialogueId = 10127001,
          GUID = "195A151A",
          VoiceName = "voice/$Locale$/story/1002/101270/195A151A"
        },
        [10127002] = {
          Camera = "-175.474609,0.638672,49.867432,0.0,0.0,0.0,15.0,142.471756,false,DoNotOverride,2.0",
          ContentTC = "散碎一地的積木塊，似乎被什麼人粗暴地推倒了。",
          DialogueId = 10127002,
          GUID = "195A1544",
          VoiceName = "voice/$Locale$/story/1002/101270/195A1544"
        },
        [10127003] = {
          Camera = "-92.993164,-100.354492,108.179443,0.000091,-34.999081,38.198757,20.0,138.826813,false,DoNotOverride,2.0",
          ContentTC = "一張筆錄，潦草地記下了你的「罪行」。",
          DialogueId = 10127003,
          GUID = "195A156E",
          VoiceName = "voice/$Locale$/story/1002/101270/195A156E"
        },
        [10127004] = {
          ContentTC = "兩痕淚靜靜地流淌在她蒼老的雙眼之下。",
          DialogueId = 10127004,
          GUID = "195A1598",
          VoiceName = "voice/$Locale$/story/1002/101270/195A1598"
        },
        [10127005] = {
          Camera = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
          ContentTC = "還帶著朝露的白花被打翻在地，花瓣凌亂不堪。",
          DialogueId = 10127005,
          GUID = "195A15C2",
          VoiceName = "voice/$Locale$/story/1002/101270/195A15C2"
        },
        [10127006] = {
          ContentTC = "拂去灰塵",
          DialogueId = 10127006,
          GUID = "195A15EC"
        },
        [10127007] = {
          ContentTC = "堆起來",
          DialogueId = 10127007,
          GUID = "195A1616"
        },
        [10127008] = {
          ContentTC = "用筆劃掉",
          DialogueId = 10127008,
          GUID = "195A1640"
        },
        [10127009] = {
          ContentTC = "幫她擦掉眼淚",
          DialogueId = 10127009,
          GUID = "195A166A"
        },
        [10127010] = {
          ContentTC = "修復花朵",
          DialogueId = 10127010,
          GUID = "195A1694"
        },
        [10127011] = {
          ContentTC = "就在這裡歇息吧",
          DialogueId = 10127011,
          GUID = "195A16BE"
        },
        [10128001] = {
          Camera = "2092.79834,-850.263184,574.188477,0.000034,-19.801502,119.803421,10.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10128001,
          FinalCamera = "2149.577148,-817.741333,574.188477,0.000037,-19.801476,122.803436,10.0,100000.0,false,Disable,2.8",
          GUID = "195AB92A",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101280/195AB92A"
        },
        [10128002] = {
          Camera = "964.108154,1014.200562,-209.061523,0.000064,-5.201202,-74.993759,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10128002,
          FinalCamera = "876.738525,985.802246,-209.061523,0.000063,-5.201202,-71.993752,15.0,100000.0,false,Disable,2.8",
          GUID = "195AB954",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101280/195AB954"
        },
        [10128101] = {
          ContentTC = "放我們進城吧，我們只是想進城賣點柴火，買點麵包啊……",
          DialogueId = 10128101,
          GUID = "195AC992",
          NextDialogue = 10128102,
          SpeakNpcId = 200089,
          VoiceName = "voice/$Locale$/story/1002/101281/195AC992"
        },
        [10128102] = {
          ContentTC = "之前進城也沒聽過要什麼通行證啊，行行好，長官，家裡的吃的快見底了。",
          DialogueId = 10128102,
          GUID = "195AC9BC",
          NextDialogue = 10128103,
          SpeakNpcId = 200089,
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9BC"
        },
        [10128103] = {
          ContentTC = "抱怨什麼啊，你以為我想查什麼通行證？還不是你們這些卡戎之民總是聚眾鬧事。",
          DialogueId = 10128103,
          GUID = "195AC9E6",
          NextDialogue = 10128104,
          SpeakNpcId = 200071,
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9E6"
        },
        [10128104] = {
          ContentTC = "你也知道那個神棄者同盟吧，啊，專門和帝國對著幹，通行證就是為了篩選這群人的。你啊，要怪就怪你的那些不安分的同族們。",
          DialogueId = 10128104,
          GUID = "195ACA10",
          NextDialogue = 10128105,
          SpeakNpcId = 200071,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA10"
        },
        [10128105] = {
          ContentTC = "我不認識什麼神棄者同盟……那長官你行行好，告訴我哪裡可以辦……辦這個通行證。",
          DialogueId = 10128105,
          GUID = "195ACA3A",
          NextDialogue = 10128106,
          SpeakNpcId = 200089,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA3A"
        },
        [10128106] = {
          ContentTC = "自己到治安署門口，排隊申請去！",
          DialogueId = 10128106,
          GUID = "195ACA64",
          NextDialogue = 10128107,
          SpeakNpcId = 200071,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA64"
        },
        [10128107] = {
          ContentTC = "治安署……在城裡啊……",
          DialogueId = 10128107,
          GUID = "195ACA8E",
          NextDialogue = 10128108,
          SpeakNpcId = 200089,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA8E"
        },
        [10128108] = {
          ContentTC = "那就不是我能管的了，自己回去想辦法。別來煩我了。跟你說，我這都是脾氣好的了，碰上脾氣壞的傢伙，一槍斃了你都沒人敢為你收屍。",
          DialogueId = 10128108,
          GUID = "195ACAB8",
          NextDialogue = 10128109,
          SpeakNpcId = 200071,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAB8"
        },
        [10128109] = {
          ContentTC = "反正現在上頭認定了，所有卡戎都是潛在的神棄者同盟分子。你啊，自己想辦法吧。",
          DialogueId = 10128109,
          GUID = "195ACAE2",
          SpeakNpcId = 200071,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE2"
        },
        [10128110] = {
          ContentTC = "前不久還不要通行證的啊……",
          DialogueId = 10128110,
          GUID = "195ACAE3",
          NextDialogue = 10128111,
          SpeakNpcId = 200089,
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE3"
        },
        [10128111] = {
          ContentTC = "抱怨什麼啊，我還想抱怨呢！這都是上頭的規定！",
          DialogueId = 10128111,
          GUID = "195ACAE4",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE4"
        },
        [10128201] = {
          ContentTC = "今天我也忘了帶通行證……",
          DialogueId = 10128201,
          GUID = "195AD9FA",
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195AD9FA"
        },
        [10128202] = {
          ContentTC = "今天我也忘了帶通行證出門，沒被當場抓去坐牢算我運氣好……",
          DialogueId = 10128202,
          GUID = "195ADA24",
          NextOptions = {
            [1] = 101282021,
            [2] = 101282022,
            [3] = 101282023
          },
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA24"
        },
        [10128204] = {
          ContentTC = "其實我覺得不重要，說是為了防止神棄者同盟混進城裡，但人家想要來搞事情，難道會走正門？",
          DialogueId = 10128204,
          GUID = "195ADA78",
          NextDialogue = 10128205,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA78"
        },
        [10128205] = {
          ContentTC = "到頭來，只是給這些士兵欺壓普通人多了一個藉口：只要沒帶通行證，那就是可疑分子。",
          DialogueId = 10128205,
          GUID = "195ADAA2",
          NextDialogue = 10128206,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADAA2"
        },
        [10128206] = {
          ContentTC = "大部分時候，只要把身上帶的銅幣都交出去，就沒啥事了。但運氣不好的話……就是你剛剛看到的樣子了，哎，真造孽。",
          DialogueId = 10128206,
          GUID = "195ADACC",
          NextOptions = {
            [1] = 101282061
          },
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADACC"
        },
        [10128208] = {
          ContentTC = "也是有的，如果部隊的長官是被帝國認可的桂冠卡戎，那手下的士兵一般都會收斂一些。",
          DialogueId = 10128208,
          GUID = "195ADB20",
          NextDialogue = 10128209,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB20"
        },
        [10128209] = {
          ContentTC = "像是大家都知道的西比爾軍團長啊，新來的黎瑟長官啊，都是會刻意約束手下的卡戎。",
          DialogueId = 10128209,
          GUID = "195ADB4A",
          NextDialogue = 10128210,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB4A"
        },
        [10128210] = {
          ContentTC = "不說了，我得回家拿通行證了。",
          DialogueId = 10128210,
          GUID = "195ADB74",
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB74"
        },
        [10128212] = {
          ContentTC = "懲罰，當然有懲罰啦，關幾天禁閉罰點錢就完事了。",
          DialogueId = 10128212,
          GUID = "195ADBC8",
          NextDialogue = 10128213,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBC8"
        },
        [10128213] = {
          ContentTC = "沒辦法，這是海伯利亞帝國，卡戎就是要低他們索拉之民一等。誰叫我們卡戎沒打得過他們呢。",
          DialogueId = 10128213,
          GUID = "195ADBF2",
          NextDialogue = 10128214,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBF2"
        },
        [10128214] = {
          ContentTC = "聽說在大陸東方的盡頭有一個叫做華胥的國家，那裡好像就不太一樣，卡戎過著好日子。",
          DialogueId = 10128214,
          GUID = "195ADC1C",
          NextOptions = {
            [1] = 101282141
          },
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC1C"
        },
        [10128216] = {
          ContentTC = "唉，還不是因為卡戎幹很多事都要被額外收一筆「卡戎監護金」，去華胥的路費貴的要死……",
          DialogueId = 10128216,
          GUID = "195ADC70",
          NextDialogue = 10128217,
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC70"
        },
        [10128217] = {
          ContentTC = "就算我攢夠了我一個人的路費，但我還有老婆小孩呢……唉，我看你年紀輕輕，應該還有機會，努力攢攢錢吧。",
          DialogueId = 10128217,
          GUID = "195ADC9A",
          SpeakNpcId = 200090,
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC9A"
        },
        [10128301] = {
          ContentTC = "這個月第幾個了……",
          DialogueId = 10128301,
          GUID = "195AEA62",
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA62"
        },
        [10128302] = {
          ContentTC = "這個月第幾個了……第三個了吧……這還做什麼生意啊，我也投奔神棄者同盟算了。",
          DialogueId = 10128302,
          GUID = "195AEA8C",
          NextOptions = {
            [1] = 101283021,
            [2] = 101283022,
            [3] = 101283023
          },
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA8C"
        },
        [10128304] = {
          ContentTC = "是啊，都是沒帶通行證，和這些士兵吵起來，然後就被當作神棄者同盟……",
          DialogueId = 10128304,
          GUID = "195AEAE0",
          NextDialogue = 10128305,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEAE0"
        },
        [10128305] = {
          ContentTC = "你說他們怎麼能這樣……難道就因為我們卡戎天生就低他們索拉之民一等嗎？",
          DialogueId = 10128305,
          GUID = "195AEB0A",
          NextDialogue = 10128306,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB0A"
        },
        [10128306] = {
          ContentTC = "哼，如果之前那場卡戎大反抗是我們卡戎贏了，他們還能這麼耀武揚威？可惜啊可惜……",
          DialogueId = 10128306,
          GUID = "195AEB34",
          NextOptions = {
            [1] = 101283061
          },
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB34"
        },
        [10128308] = {
          ContentTC = "你不知道啊？也是，看你年紀不大，大反抗的時候應該還沒你呢，回去問問你爹媽吧，那時候帝國大部分卡戎都被捲進去了，他們應該也知道。",
          DialogueId = 10128308,
          GUID = "195AEB88",
          NextDialogue = 10128309,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB88"
        },
        [10128309] = {
          ContentTC = "當時最前面的隊伍都攻入了皇都，只是在最後一刻敗了……所以現在帝國才對我們卡戎嚴防死守，拼了命的壓制。",
          DialogueId = 10128309,
          GUID = "195AEBB2",
          NextDialogue = 10128310,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBB2"
        },
        [10128310] = {
          ContentTC = "不過嘛，現在這位陛下這麼亂搞下去，我看距離下次戰爭也就是時間問題。",
          DialogueId = 10128310,
          GUID = "195AEBDC",
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBDC"
        },
        [10128312] = {
          ContentTC = "怎麼？想要同去？還是想要告密？",
          DialogueId = 10128312,
          GUID = "195AEC30",
          NextDialogue = 10128313,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC30"
        },
        [10128313] = {
          ContentTC = "唉，我也就是說說氣話。雖說神棄者同盟是卡戎們組成的反抗組織，但真想要找到他們又是不可能的事情。",
          DialogueId = 10128313,
          GUID = "195AEC5A",
          NextDialogue = 10128314,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC5A"
        },
        [10128314] = {
          ContentTC = "在上次卡戎大起義失敗後，他們的行動就變得極度隱秘，沒人知道他們現在有多少人、有沒有什麼大本營、怎麼找到他們。",
          DialogueId = 10128314,
          GUID = "195AEC84",
          NextDialogue = 10128315,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC84"
        },
        [10128315] = {
          ContentTC = "甚至也有人說，神棄者同盟早就解散了，只是治安署的那些無能之輩遇到破不了的案子，就會和上頭報告說是神棄者同盟糊弄事。",
          DialogueId = 10128315,
          GUID = "195AECAE",
          NextDialogue = 10128316,
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AECAE"
        },
        [10128316] = {
          ContentTC = "但我還是相信他們一定在暗處積蓄著力量，直到哪一天，讓這些索拉血債血償。",
          DialogueId = 10128316,
          GUID = "195AECD8",
          SpeakNpcId = 200091,
          VoiceName = "voice/$Locale$/story/1002/101283/195AECD8"
        },
        [10128401] = {
          ContentTC = "宅子挺大，但鬼氣森森……",
          DialogueId = 10128401,
          GUID = "195AFACA",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFACA"
        },
        [10128402] = {
          ContentTC = "這宅子又高又大，鬼氣森森。買得起的人不願意住，想住的人買不起。",
          DialogueId = 10128402,
          GUID = "195AFAF4",
          NextOptions = {
            [1] = 101284021,
            [2] = 101284022,
            [3] = 101284023,
            [4] = 101284024
          },
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFAF4"
        },
        [10128404] = {
          ContentTC = "是啦，你不知道嗎？這可是冰湖城兩大知名鬼屋之一！據說在這裡待過的住客不是被帝國找麻煩，就是和親人離散。",
          DialogueId = 10128404,
          GUID = "195AFB48",
          NextDialogue = 10128405,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB48"
        },
        [10128405] = {
          ContentTC = "至於城裡的另一個鬼屋，那就是你們剛剛從那裡出來的修普諾斯之家。據說每個夜晚，那裡都會傳出哭聲。",
          DialogueId = 10128405,
          GUID = "195AFB72",
          NextDialogue = 10128406,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB72"
        },
        [10128406] = {
          ContentTC = "嗯……好像都和那個恩里克有關係喔。",
          DialogueId = 10128406,
          GUID = "195AFB9C",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB9C"
        },
        [10128408] = {
          ContentTC = "哎，這怎麼叫窺探呢，這麼大的房子來了新住客能不好奇嗎？",
          DialogueId = 10128408,
          GUID = "195AFBF0",
          NextDialogue = 10128409,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFBF0"
        },
        [10128409] = {
          ContentTC = "冰湖城裡大大小小這麼多戶人家我都知道的一清二楚，都是我挨家挨戶打聽出來的，其他人可沒說過什麼窺探隱私之類的話。",
          DialogueId = 10128409,
          GUID = "195AFC1A",
          NextDialogue = 10128410,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC1A"
        },
        [10128410] = {
          ContentTC = "不過既然你都這麼說了，那我就不在這裡自討沒趣了，再見——我相信我們會再見的。",
          DialogueId = 10128410,
          GUID = "195AFC44",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC44"
        },
        [10128412] = {
          ContentTC = "我？哎呀我就是一個寫點東西掙錢的，管我叫大記者安蘇茲（Ansuz）就好。",
          DialogueId = 10128412,
          GUID = "195AFC98",
          NextDialogue = 10128413,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC98"
        },
        [10128413] = {
          ContentTC = "我一直在冰湖城裡搜羅消息，寫成文章，印製報紙，帶來歡樂。",
          DialogueId = 10128413,
          GUID = "195AFCC2",
          NextDialogue = 10128414,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCC2"
        },
        [10128414] = {
          ContentTC = "怎麼一副不信的樣子，來，拿著，今天的《冰湖城早報》。這份免費，喜歡再買。",
          DialogueId = 10128414,
          GUID = "195AFCEC",
          NextDialogue = 10128415,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCEC"
        },
        [10128415] = {
          ContentTC = "當然，如果你有什麼新聞線索的話，也可以來找我，免費給你換一份。",
          DialogueId = 10128415,
          GUID = "195AFD16",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101284/195AFD16"
        },
        [10128501] = {
          ContentTC = "瑪爾潔姐姐帶來了生活費。",
          DialogueId = 10128501,
          GUID = "195B0B32",
          NextDialogue = 10128502,
          SpeakNpcId = 200093,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B32"
        },
        [10128502] = {
          ContentTC = "不能一直這樣。",
          DialogueId = 10128502,
          GUID = "195B0B5C",
          SpeakNpcId = 200094,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B5C"
        },
        [10128503] = {
          ContentTC = "瑪爾潔姐姐帶回了這個月的生活費哦，這樣一來就不用擔心月底餓肚子了。瑪爾潔姐姐真好！",
          DialogueId = 10128503,
          GUID = "195B0B86",
          NextDialogue = 10128504,
          SpeakNpcId = 200093,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B86"
        },
        [10128504] = {
          ContentTC = "我聽說啊，這些生活費先前都被人偷走了，是瑪爾潔姐姐和一個好心的狩月人好不容易追回來的。",
          DialogueId = 10128504,
          GUID = "195B0BB0",
          NextDialogue = 10128505,
          SpeakNpcId = 200094,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BB0"
        },
        [10128505] = {
          ContentTC = "不能這樣，這樣不行。我們不能總是這麼依靠瑪爾潔姐姐。我說難聽一點，要是她有什麼萬一，難道我們就一直餓著肚子嗎？",
          DialogueId = 10128505,
          GUID = "195B0BDA",
          NextDialogue = 10128506,
          SpeakNpcId = 200094,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BDA"
        },
        [10128506] = {
          ContentTC = "哎，要是我能吃飽，多長點力氣，就也能去做狩月人，去幫瑪爾潔姐姐了。",
          DialogueId = 10128506,
          GUID = "195B0C04",
          NextDialogue = 10128507,
          SpeakNpcId = 200093,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C04"
        },
        [10128507] = {
          ContentTC = "那你多吃一點，這塊餅乾我吃不完，掰一半給你。等你長得比瑪爾潔姐姐的鏟子高了，就代替她給貧民窟的各位攢生活費。",
          DialogueId = 10128507,
          GUID = "195B0C2E",
          NextDialogue = 10128508,
          SpeakNpcId = 200094,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C2E"
        },
        [10128508] = {
          ContentTC = "好呀好呀，不過我相信啊，到那時候啊，住在這裡的各位應該都能吃飽，不會再要人攢錢救濟了。",
          DialogueId = 10128508,
          GUID = "195B0C58",
          NextDialogue = 10128509,
          SpeakNpcId = 200093,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C58"
        },
        [10128509] = {
          ContentTC = "要真有那麼一天就好了，那時候瑪爾潔姐姐，還有大家都不用這辛苦……哎，你吃餅乾的樣子真醜，狼吞虎嚥的。",
          DialogueId = 10128509,
          GUID = "195B0C82",
          NextDialogue = 10128510,
          SpeakNpcId = 200094,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C82"
        },
        [10128510] = {
          ContentTC = "唔，唔唔……",
          DialogueId = 10128510,
          GUID = "195B0CAC",
          SpeakNpcId = 200093,
          VoiceName = "voice/$Locale$/story/1002/101285/195B0CAC"
        },
        [10128601] = {
          ContentTC = "八點要到了吧……",
          DialogueId = 10128601,
          GUID = "195B1B9A",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1B9A"
        },
        [10128602] = {
          ContentTC = "我和朋友約好八點鐘在水仙平原見面，但我又沒帶懷錶。所以我來到了這裡，只要恩里克一出現，我就知道，八點到了。",
          DialogueId = 10128602,
          GUID = "195B1BC4",
          NextOptions = {
            [1] = 101286021,
            [2] = 101286022,
            [3] = 101286023
          },
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1BC4"
        },
        [10128604] = {
          ContentTC = "我就是知道，恩里克這個習慣維持了很久了。像是他這麼死板的人會幹出的事情，固定時間出門，固定時間吃飯之類。",
          DialogueId = 10128604,
          GUID = "195B1C18",
          NextDialogue = 10128605,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C18"
        },
        [10128605] = {
          ContentTC = "你說，他是不是連呼吸都是固定節奏，自己有意識在控制的？啊，有了，我要寫一篇文章，標題就叫《規律生活，把握人生》，怎麼樣？",
          DialogueId = 10128605,
          GUID = "195B1C42",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C42"
        },
        [10128607] = {
          ContentTC = "我？哎呀我就是一個寫點東西掙錢的，管我叫大記者安蘇茲（Ansuz）就好。",
          DialogueId = 10128607,
          GUID = "195B1C96",
          NextDialogue = 10128608,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C96"
        },
        [10128608] = {
          ContentTC = "我一直在冰湖城裡搜羅消息，寫成文章，印製報紙，帶來歡樂。",
          DialogueId = 10128608,
          GUID = "195B1CC0",
          NextDialogue = 10128609,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1CC0"
        },
        [10128609] = {
          ContentTC = "怎麼一副不信的樣子，來，拿著，今天的《冰湖城早報》。這份免費，喜歡再買。",
          DialogueId = 10128609,
          GUID = "195B1CEA",
          NextDialogue = 10128610,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1CEA"
        },
        [10128610] = {
          ContentTC = "當然，如果你有什麼新聞線索的話，也可以來找我，免費給你換一份。",
          DialogueId = 10128610,
          GUID = "195B1D14",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101286/195B1D14"
        },
        [10128701] = {
          ContentTC = "唉……還是不寫報導了。",
          DialogueId = 10128701,
          GUID = "195B2C02",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C02"
        },
        [10128702] = {
          ContentTC = "唉……還是不寫報導了，整版都沒什麼好事，還是不給人添堵了。",
          DialogueId = 10128702,
          GUID = "195B2C2C",
          NextOptions = {
            [1] = 101287021,
            [2] = 101287022,
            [3] = 101287023,
            [4] = 101287024
          },
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C2C"
        },
        [10128704] = {
          ContentTC = "還能是什麼報導……無非是那個小女孩身上發生的那些事。恩里克不在了，沒人攔著我，我進去問明白了個七七八八。",
          DialogueId = 10128704,
          GUID = "195B2C80",
          NextDialogue = 10128705,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C80"
        },
        [10128705] = {
          ContentTC = "我做《冰湖城早報》是想給人帶來快樂，鼓舞人心，但冰湖城裡發生的壞事還是太多了。",
          DialogueId = 10128705,
          GUID = "195B2CAA",
          NextDialogue = 10128706,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CAA"
        },
        [10128706] = {
          ContentTC = "前一天的報導裡提到的工匠父子，第二天就可能橫死街頭。原本預定採訪的卡戎詩人，過一陣就可能徹底發瘋。",
          DialogueId = 10128706,
          GUID = "195B2CD4",
          NextDialogue = 10128707,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CD4"
        },
        [10128707] = {
          ContentTC = "他們就像是淚湖上空落下的雪，落下後成為湖冰，無人在意。但我也相信，當這些堅冰融化之時，整個冰湖城都會倒塌。",
          DialogueId = 10128707,
          GUID = "195B2CFE",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CFE"
        },
        [10128709] = {
          ContentTC = "有吧，雖然現在沒有，但總會有的。",
          DialogueId = 10128709,
          GUID = "195B2D52",
          NextDialogue = 10128710,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2D52"
        },
        [10128710] = {
          ContentTC = "你也別太傷心，我向你保證，我們卡戎開始反抗的日子，不遠了。",
          DialogueId = 10128710,
          GUID = "195B2D7C",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2D7C"
        },
        [10128712] = {
          ContentTC = "《冰湖城早報》的記者，安蘇茲。你現在可以叫我這個。",
          DialogueId = 10128712,
          GUID = "195B2DD0",
          NextDialogue = 10128713,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2DD0"
        },
        [10128713] = {
          ContentTC = "不過實際上，其他城市的報紙多多少少和我也有點關聯。我是想用文字讓我們卡戎一族的處境變好一點。",
          DialogueId = 10128713,
          GUID = "195B2DFA",
          NextDialogue = 10128714,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2DFA"
        },
        [10128714] = {
          ContentTC = "當然了，我也非常明白，只有筆是不夠的，我們要握起劍來，我們要讓他們血債血償。",
          DialogueId = 10128714,
          GUID = "195B2E24",
          NextDialogue = 10128715,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2E24"
        },
        [10128715] = {
          ContentTC = "到那時候，我相信你也會成為我的同伴的。",
          DialogueId = 10128715,
          GUID = "195B2E4E",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101287/195B2E4E"
        },
        [10128801] = {
          ContentTC = "一杯……六杯……十三杯……",
          DialogueId = 10128801,
          GUID = "195B3C6A",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3C6A"
        },
        [10128802] = {
          ContentTC = "一杯酒下肚，卡戎索拉和睦睦，六杯酒下肚，第六軍團一群豬，喝了十三杯……",
          DialogueId = 10128802,
          GUID = "195B3C94",
          NextOptions = {
            [1] = 101288021,
            [2] = 101288022,
            [3] = 101288023
          },
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3C94"
        },
        [10128804] = {
          ContentTC = "我好的很，不好的是冰湖城！所以來一杯酒吧朋友，麻醉思考，調和人生。酒精進入腦袋的那一刻，上司就會變成豬，如果你喜歡的話，狗也可以。",
          DialogueId = 10128804,
          GUID = "195B3CE8",
          NextDialogue = 10128805,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3CE8"
        },
        [10128805] = {
          ContentTC = "不過我還是喜歡豬。狗崇拜人類。貓鄙視人類。豬對我們一視同仁。所以說那群貴族和軍團啊連豬都不如，卡戎們都過成這樣了，他們還在唱唱跳跳。",
          DialogueId = 10128805,
          GUID = "195B3D12",
          NextDialogue = 10128806,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D12"
        },
        [10128806] = {
          ContentTC = "還好有酒，還好有酒，我的靈魂喜歡威士忌的泥土芳香。我可能不是索拉，實際上我的靈魂是七十三升的烈酒，我的身體是束縛的橡木桶！",
          DialogueId = 10128806,
          GUID = "195B3D3C",
          NextDialogue = 10128807,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D3C"
        },
        [10128807] = {
          ContentTC = "對，對，要是卡戎和索拉都是烈酒就好了，大家可以彼此交融調和，世界啊就是一汪浩瀚無邊的雞尾酒或者三分糖橙子果汁！",
          DialogueId = 10128807,
          GUID = "195B3D66",
          NextDialogue = 10128808,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D66"
        },
        [10128808] = {
          ContentTC = "你也喝吧，一醉解百憂，大家是朋友。",
          DialogueId = 10128808,
          GUID = "195B3D90",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D90"
        },
        [10128810] = {
          ContentTC = "哎呀你這新來的卡戎，這不是明擺著的嗎，我在這裡醉酒！",
          DialogueId = 10128810,
          GUID = "195B3DE4",
          NextDialogue = 10128811,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3DE4"
        },
        [10128811] = {
          ContentTC = "如果不醉酒，那就要好好工作，我要好好工作，你們就都不能活，所以我還是要選擇醉酒。你們應該感激我，我在慢性自殺換你們活得長久。",
          DialogueId = 10128811,
          GUID = "195B3E0E",
          NextDialogue = 10128812,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3E0E"
        },
        [10128812] = {
          ContentTC = "敬我一杯酒吧，我是罪人，也是善人，我的初次見面的卡戎朋友。",
          DialogueId = 10128812,
          GUID = "195B3E38",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101288/195B3E38"
        },
        [10128901] = {
          ContentTC = "你又不真的是酒桶，別喝了……",
          DialogueId = 10128901,
          GUID = "195B4CD2",
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4CD2"
        },
        [10128902] = {
          ContentTC = "唉，他又喝了不少，這樣下去遲早會死，如果換一個新的索拉人來監視那就不好辦了。",
          DialogueId = 10128902,
          GUID = "195B4CFC",
          NextOptions = {
            [1] = 101289021,
            [2] = 101289022,
            [3] = 101289023
          },
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4CFC"
        },
        [10128904] = {
          ContentTC = "是啊，唉你是新來的應該不知道，他是第六軍團派來貧民窟的監視員，說是要找出這邊的危險分子，以儆效尤。",
          DialogueId = 10128904,
          GUID = "195B4D50",
          NextDialogue = 10128905,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4D50"
        },
        [10128905] = {
          ContentTC = "他來這邊第一天，記下了三個人有些可疑，第二天那三個人就都被吊死了。這件事給了他不小的刺激，可能一開始他以為就是關幾天了事吧。",
          DialogueId = 10128905,
          GUID = "195B4D7A",
          NextDialogue = 10128906,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4D7A"
        },
        [10128906] = {
          ContentTC = "在那之後他就這樣了，每天泡在酒裡，彷彿真的想要醉死自己一樣，整天說世界是一個大酒桶，自己是一個小酒桶，大家應該都成為一桶酒這樣的話。",
          DialogueId = 10128906,
          GUID = "195B4DA4",
          NextDialogue = 10128907,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DA4"
        },
        [10128907] = {
          ContentTC = "對上司嘛，一直匯報說卡戎們因為他第一天的雷厲風行，都被嚇得和鵪鶉一樣老老實實，就這樣應付過去。",
          DialogueId = 10128907,
          GUID = "195B4DCE",
          NextDialogue = 10128908,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DCE"
        },
        [10128908] = {
          ContentTC = "實際上又怎麼會呢？真要按照他一開始的工作勁頭，這裡所有人都會被吊死十次不止，不過在那之前，恐怕他也會被其他人打死。",
          DialogueId = 10128908,
          GUID = "195B4DF8",
          NextDialogue = 10128909,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DF8"
        },
        [10128909] = {
          ContentTC = "唉，所以說現在這樣，藉著醉酒逃避工作對他來說也是最好的做法了。現在這邊的酒客大部份也不恨他了，軍團裡有良心的人不多，他算是一個。",
          DialogueId = 10128909,
          GUID = "195B4E22",
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4E22"
        },
        [10128911] = {
          ContentTC = "大部分情況下是的，卡戎從一出生就會被帝國教育說卡戎們是邪惡的，會帶來許多災難。",
          DialogueId = 10128911,
          GUID = "195B4E76",
          NextDialogue = 10128912,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4E76"
        },
        [10128912] = {
          ContentTC = "成長途中也會目睹那些沒有角的索拉人是如何手握著武器高高在上，用子彈和列車砲把所有的反抗者轟成碎塊。",
          DialogueId = 10128912,
          GUID = "195B4EA0",
          NextDialogue = 10128913,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4EA0"
        },
        [10128913] = {
          ContentTC = "而卡戎們反抗起來對索拉們也並不客氣就是了，只不過現在恰好是索拉們佔據優勢的時候。",
          DialogueId = 10128913,
          GUID = "195B4ECA",
          NextDialogue = 10128914,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4ECA"
        },
        [10128914] = {
          ContentTC = "矛盾啊就像是一個螺旋，一直在延續著累積著。有時候卡戎居上，有時候索拉居上，只不過索拉居上時候要長得多就是了。",
          DialogueId = 10128914,
          GUID = "195B4EF4",
          NextDialogue = 10128915,
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4EF4"
        },
        [10128915] = {
          ContentTC = "看你一副初來乍到的樣子，奉勸你一句，活著比什麼都重要。留一條命在，說不定就能看到卡戎們的好日子。",
          DialogueId = 10128915,
          GUID = "195B4F1E",
          SpeakNpcId = 200096,
          VoiceName = "voice/$Locale$/story/1002/101289/195B4F1E"
        },
        [10129001] = {
          ContentTC = "抓回來就好，也沒人受傷，走運啊走運。",
          DialogueId = 10129001,
          GUID = "195B5D3A",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5D3A"
        },
        [10129002] = {
          ContentTC = "聽說你抓到的那個小偷是被送去了治安署？太走運了，被提前阻止了就好，幹得好啊年輕人。",
          DialogueId = 10129002,
          GUID = "195B5D64",
          NextOptions = {
            [1] = 101290021,
            [2] = 101290022,
            [3] = 101290023
          },
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5D64"
        },
        [10129004] = {
          ContentTC = "是啊，像他這樣的情況被送去治安署是最好的結局了，否則再由著他胡鬧，搞出更大的亂子，那針對卡戎的各種謠言和恨意都變得更多。",
          DialogueId = 10129004,
          GUID = "195B5DB8",
          NextDialogue = 10129005,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5DB8"
        },
        [10129005] = {
          ContentTC = "雖然對他個人來說非常悲慘，但，又能怎麼樣呢，死亡遲早會擁抱他，現在這樣算是最不壞的結果了。",
          DialogueId = 10129005,
          GUID = "195B5DE2",
          NextDialogue = 10129006,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5DE2"
        },
        [10129006] = {
          ContentTC = "別有壓力，這也不是你的錯，沒有人有錯。",
          DialogueId = 10129006,
          GUID = "195B5E0C",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E0C"
        },
        [10129008] = {
          ContentTC = "你這個問題就和喝了酒會怎麼樣似的，何必多問呢？我給你的答案只能是他會像是喝了一杯烈酒一樣，劇痛之後安眠無憂。",
          DialogueId = 10129008,
          GUID = "195B5E60",
          NextDialogue = 10129009,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E60"
        },
        [10129009] = {
          ContentTC = "哈哈，每次喝了酒我都覺得自己說話像是藝術家而不是帝國的士兵，我喜歡這種能夠面對壞事還自我誇讚的心情。但希望你永遠不要懂這種感覺。",
          DialogueId = 10129009,
          GUID = "195B5E8A",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E8A"
        },
        [10129101] = {
          ContentTC = "原來都是恩里克……",
          DialogueId = 10129101,
          GUID = "195B6DA2",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6DA2"
        },
        [10129102] = {
          ContentTC = "我還以為之前冰湖城的穢蝕者數量變少是奇蹟，結果是恩里克……鑑於他已經死了，軍團不會追究他，但以後怎麼辦呢……",
          DialogueId = 10129102,
          GUID = "195B6DCC",
          NextOptions = {
            [1] = 101291021,
            [2] = 101291022,
            [3] = 101291023
          },
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6DCC"
        },
        [10129104] = {
          ContentTC = "是啊，又能追究什麼呢，修普諾斯之家已經空了，並且也有合法的繼承人，總不能真的把那個宅子一把火燒了。",
          DialogueId = 10129104,
          GUID = "195B6E20",
          NextDialogue = 10129105,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E20"
        },
        [10129105] = {
          ContentTC = "但說實話，我是覺得軍團要感謝他，應該給他發獎。否則那麼多穢蝕者，每個都引發事故的話，我不敢想。",
          DialogueId = 10129105,
          GUID = "195B6E4A",
          NextDialogue = 10129106,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E4A"
        },
        [10129106] = {
          ContentTC = "聽說他是想研究藥物阻止穢蝕，唉，要是真的成功就好了，能夠讓什麼卡戎生來背負著罪孽的說法少上一些。",
          DialogueId = 10129106,
          GUID = "195B6E74",
          NextDialogue = 10129107,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E74"
        },
        [10129107] = {
          ContentTC = "嗯……不少索拉之民之所以能對卡戎們的境遇視而不見，也是靠著這個說法自我催眠吧——生來有罪的種族，吃點苦也是活該的。",
          DialogueId = 10129107,
          GUID = "195B6E9E",
          NextDialogue = 10129108,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E9E"
        },
        [10129108] = {
          ContentTC = "唉，我也沒有立場去說他們，比起同是索拉之民，又為了卡戎喪命的恩里克，我又做了什麼呢……",
          DialogueId = 10129108,
          GUID = "195B6EC8",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6EC8"
        },
        [10129110] = {
          ContentTC = "賽琪……？啊你是說之前和你在一起的那個孩子……軍團沒有太在意她，畢竟每天全國這樣的穢蝕者相關的事件不少。",
          DialogueId = 10129110,
          GUID = "195B6F1C",
          NextDialogue = 10129111,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F1C"
        },
        [10129111] = {
          ContentTC = "第六軍團的黎瑟長官也表示這起穢蝕雖然規模要更大，也牽扯了非法行醫，但不需要深究。",
          DialogueId = 10129111,
          GUID = "195B6F46",
          NextDialogue = 10129112,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F46"
        },
        [10129112] = {
          ContentTC = "否則，在現場的人……有你吧，免不了要被帶去軍團審問，那時候發生什麼就未可知了。",
          DialogueId = 10129112,
          GUID = "195B6F70",
          NextDialogue = 10129113,
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F70"
        },
        [10129113] = {
          ContentTC = "唉，你也節哀，很不好受吧。我這杯酒，敬她。",
          DialogueId = 10129113,
          GUID = "195B6F9A",
          SpeakNpcId = 200095,
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F9A"
        },
        [10129201] = {
          ContentTC = "是去了格雷姆廢礦？身手不錯啊。",
          DialogueId = 10129201,
          GUID = "195B7001",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7001"
        },
        [10129202] = {
          ContentTC = "怎麼回事？去了格雷姆廢礦？那能活下來算你們運氣不錯。話說回來，這恩里克也越來越神經質了。",
          DialogueId = 10129202,
          GUID = "195B7002",
          NextOptions = {
            [1] = 101292021,
            [2] = 101292022,
            [3] = 101292023
          },
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7002"
        },
        [10129204] = {
          ContentTC = "那裡很危險呀，說是廢礦，但裡面還有很多穢獸的吧。我曾經委託人去查過，都被裡面的一個大怪物給堵回來了。",
          DialogueId = 10129204,
          GUID = "195B7004",
          NextDialogue = 10129205,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7004"
        },
        [10129205] = {
          ContentTC = "啊？你說你們打敗它了？這……該說是你們身手好還是命大呢？",
          DialogueId = 10129205,
          GUID = "195B7005",
          NextDialogue = 10129206,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7005"
        },
        [10129206] = {
          ContentTC = "嗯……有空的話，要不要我為你寫一篇專訪？標題就叫《冉冉升起的新興狩月人－－{nickname}》，還能幫你提高知名度呢。",
          DialogueId = 10129206,
          GUID = "195B7006",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7006"
        },
        [10129208] = {
          ContentTC = "該怎麼說呢，他之前也是這樣一板一眼，不和人說笑。我想採訪他寫報道，被他拒絕，想和他的住客搭話，也被他趕走。",
          DialogueId = 10129208,
          GUID = "195B7008",
          NextDialogue = 10129209,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7008"
        }
      }
    end
  },
  {
    MinKey = 10129209,
    MaxKey = 11011017,
    Loader = function()
      return {
        [10129209] = {
          ContentTC = "但他之前說話也不像是這種冷冰冰的，想要殺人一樣。可能他最近也有什麼心事吧，唉，這個年頭，誰又沒點煩心事呢。",
          DialogueId = 10129209,
          GUID = "195B7009",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B7009"
        },
        [10129211] = {
          ContentTC = "我？哎呀我就是一個寫點東西掙錢的，管我叫大記者安蘇茲（Ansuz）就好。",
          DialogueId = 10129211,
          GUID = "195B700B",
          NextDialogue = 10129212,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B700B"
        },
        [10129212] = {
          ContentTC = "我一直在冰湖城裡搜羅消息，寫成文章，印製報紙，帶來歡樂。",
          DialogueId = 10129212,
          GUID = "195B700C",
          NextDialogue = 10129213,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B700C"
        },
        [10129213] = {
          ContentTC = "怎麼一副不信的樣子，來，拿著，今天的《冰湖城早報》。這份免費，喜歡再買。",
          DialogueId = 10129213,
          GUID = "195B700D",
          NextDialogue = 10129214,
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B700D"
        },
        [10129214] = {
          ContentTC = "當然，如果你有什麼新聞線索的話，也可以來找我，免費給你換一份。",
          DialogueId = 10129214,
          GUID = "195B700E",
          SpeakNpcId = 200092,
          VoiceName = "voice/$Locale$/story/1002/101292/195B700E"
        },
        [10129301] = {
