        [10130803] = {
          Camera = "269.530029,368.111084,118.398438,0.000066,-2.199314,-128.599228,30.0,619.991211,false,Manual,1.2",
          ContentTC = "那我們也帶上吧！冒險就是要做足準備嘛！",
          DialogueId = 10130803,
          Duration = 10,
          FinalCamera = "257.802246,377.4729,118.398438,0.000066,-2.199314,-128.599228,30.0,274.965851,false,Manual,1.2",
          GUID = "195BD044",
          LookAt = {
