          },
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD044"
        },
        [10130901] = {
          ContentTC = "啊，路被那些惡心的黃色晶刺堵住啦！",
          DialogueId = 10130901,
          GUID = "195BD045",
          NextDialogue = 10130902,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD045"
        },
        [10130902] = {
          ContentTC = "剛才那些火藥桶應該能派上用場了。",
          DialogueId = 10130902,
          GUID = "195BD046",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD046"
        },
        [10130903] = {
          ContentTC = "（離遠一些，<H>用子彈射擊</>引爆它吧。）",
          DialogueId = 10130903,
          GUID = "195BD047",
          IsBlack = 1,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101309/195BD047"
        },
        [10131001] = {
          ContentTC = "成功了！……啊，你們要不要緊？魔王大人你怎麼蹲在地上，受傷了嗎？",
          DialogueId = 10131001,
          GUID = "195BD048",
          NextDialogue = 10131002,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD048"
        },
        [10131002] = {
          ContentTC = "啊？！沒、沒事，區區區區爆炸而已！我、我是在勘探地形，嘿嘿……",
          DialogueId = 10131002,
          GUID = "195BD049",
          NextDialogue = 10131003,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD049"
        },
        [10131003] = {
          ContentTC = "噓！",
          DialogueId = 10131003,
          GUID = "195BD050",
          NextDialogue = 10131004,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD050"
        },
        [10131004] = {
          ContentTC = "吼——",
          DialogueId = 10131004,
          GUID = "195BD051",
          NextDialogue = 10131005,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD051"
        },
        [10131005] = {
          ContentTC = "……礦坑深處好像有什麼動靜？",
          DialogueId = 10131005,
          GUID = "195BD052",
          NextDialogue = 10131006,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD052"
        },
        [10131006] = {
          ContentTC = "這麼說來，剛剛的筆記還寫到，廢礦裡可能有一種特別的穢獸出沒……大家留意些，不要落單。",
          DialogueId = 10131006,
          GUID = "195BD053",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101310/195BD053"
        },
        [10131101] = {
          ContentTC = "快看，中間那塊大晶石在發光誒！難道裡面有我們要找的群星綺晶？",
          DialogueId = 10131101,
          GUID = "195BD054",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101311/195BD054"
        },
        [10131201] = {
          ContentTC = "吼——",
          DialogueId = 10131201,
          GUID = "195BD055",
          NextDialogue = 10131202,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD055"
        },
        [10131202] = {
          ContentTC = "是剛才那個聲音！",
          DialogueId = 10131202,
          GUID = "195BD056",
          NextDialogue = 10131203,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD056"
        },
        [10131203] = {
          ContentTC = "哇啊——怎麼突然衝上來這麼多穢獸！……呃……呃呃……",
          DialogueId = 10131203,
          GUID = "195BD057",
          NextDialogue = 10131204,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD057"
        },
        [10131204] = {
          ContentTC = "也許是被爆炸聲引過來的？",
          DialogueId = 10131204,
          GUID = "195BD058",
          NextDialogue = 10120102,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101312/195BD058"
        },
        [10131301] = {
          Camera = "942.578125,-142.629272,467.552734,0.00006,-23.399557,174.599045,20.0,100000.0,false,Disable,2.8",
          ContentTC = "亮閃閃魔彈——純白的救贖！轟！！",
          DialogueId = 10131301,
          GUID = "195BD059",
          NextDialogue = 10131302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD059"
        },
        [10131302] = {
          ContentTC = "不用「轟」了，穢獸已經被消滅啦。",
          DialogueId = 10131302,
          GUID = "195BD060",
          NextDialogue = 10131303,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD060"
        },
        [10131303] = {
          ContentTC = "噢，是嗎！快讓我鑒賞一下本大人偉大的戰利品——",
          DialogueId = 10131303,
          GUID = "195BD061",
          NextDialogue = 10131304,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD061"
        },
        [10131304] = {
          ContentTC = "卡米拉說過，群星綺晶是「流轉著星雲的紫色晶體」……這個似乎只是常見的銀輝石而已。",
          DialogueId = 10131304,
          GUID = "195BD062",
          NextDialogue = 10131305,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD062"
        },
        [10131305] = {
          ContentTC = "嗚……沒意思。",
          DialogueId = 10131305,
          GUID = "195BD063",
          NextDialogue = 10131307,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD063"
        },
        [10131306] = {
          ContentTC = "<H>銀輝石</>嗎……我小時候聽隔壁的裁縫叔叔說過，這種礦物可以拿來做顏料或者<H>染料</>。",
          DialogueId = 10131306,
          GUID = "195BD064",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD064"
        },
        [10131307] = {
          ContentTC = "那小仆從有空拿給<H>鐵匠皎皎前輩</>瞧瞧吧！至於現在，讓我繼續帶領你們向礦坑深處進發！",
          DialogueId = 10131307,
          GUID = "195BD065",
          NextDialogue = 10131308,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD065"
        },
        [10131308] = {
          ContentTC = "嗬嗬……遵命，魔王大人。",
          DialogueId = 10131308,
          GUID = "195BD066",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101313/195BD066"
        },
        [10131401] = {
          ContentTC = "這些黃色晶刺裡面，竟然還裹著這麼多亮晶晶的石頭呀！",
          DialogueId = 10131401,
          GUID = "195BD067",
          NextDialogue = 10131402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD067"
        },
        [10131402] = {
          ContentTC = "就像是被誰當成寶貝，小心翼翼地藏起來了一樣……",
          DialogueId = 10131402,
          GUID = "195BD068",
          NextDialogue = 10131403,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD068"
        },
        [10131403] = {
          ContentTC = "哼哼~賽琪該不會也偷藏了什麼寶貝？",
          DialogueId = 10131403,
          GUID = "195BD069",
          NextDialogue = 10131404,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD069"
        },
        [10131404] = {
          ContentTC = "嘿嘿……是秘密哦。",
          DialogueId = 10131404,
          GUID = "195BD070",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101314/195BD070"
        },
