            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110103/1B902BA4"
        },
        [11010315] = {
          ContentTC = "明白了……我聽從您的安排。",
          DialogueId = 11010315,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B902BCE",
          NextDialogue = 11010316,
