        [11011415] = {
          ContentTC = "任務繼續。",
          DialogueId = 11011415,
          Duration = 3,
          GUID = "1B90E046",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11011418,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Continue the mission.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E046"
        },
        [11011416] = {
          ContentTC = "除了獨立供能的中央控製室，整座要塞運轉需要的月髓液都在這裏。",
          DialogueId = 11011416,
          Duration = 3,
          GUID = "1B90E047",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11011417,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Besides the independently powered central control room, this place stores all the Phoxichor that powers the whole fortress.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E047"
        },
        [11011417] = {
          ContentTC = "破壞這裏的動力裝置，要塞中的大部分機關就會停止運轉。",
          DialogueId = 11011417,
          Duration = 3,
          GUID = "1B90E048",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "If we destroy the power unit here, we'll disable most of the facilities in the fortress.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E048"
        },
        [11011418] = {
          ContentTC = "我們必須讓那些機關癱瘓掉……維克不能白白犧牲。",
          DialogueId = 11011418,
          Duration = 3,
          GUID = "1B90E0C4",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "We must shut down the systems... We can't let Vic die in vain.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E0C4"
        },
        [11011419] = {
          Content = "哦？已经处理好一个了吗，小心些，我好像听到秽兽靠过来的声音了。",
          DialogueId = 11011419,
          Duration = 3,
          GUID = "1B90E0EE",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E0EE"
        },
        [11011420] = {
          Content = "好，{nickname2}，动力链接已经断开了，我们得趁现在去把整个动力装置都毁了。",
          DialogueId = 11011420,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E118",
          NextDialogue = 11011421,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E118"
        },
        [11011421] = {
          Content = "核心的动力炉就在下面，小心些……",
          DialogueId = 11011421,
          Duration = 3,
          GUID = "1B90E142",
          NextDialogue = 11011422,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E142"
        },
        [11011422] = {
          Content = "有些脏东西围过来了……事办妥了再上来集合！",
          DialogueId = 11011422,
          Duration = 3,
          GUID = "1B90E16C",
          NextDialogue = 11011423,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E16C"
        },
        [11011423] = {
          Content = "好……",
          DialogueId = 11011423,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E196",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E196"
        },
        [11011424] = {
          ContentTC = "我會逐個解鎖防護屏障，等信號亮起，你就把月髓艙打碎！",
          DialogueId = 11011424,
          Duration = 3,
          GUID = "1B90E1C0",
          NextDialogue = 11011425,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "I'll disable the protective barriers one by one. When the signal light's on, smash the Phoxichor tank as fast as you can!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C0"
        },
        [11011425] = {
          ContentTC = "有些月髓艙可能會配備自毀裝置，如果聽到倒計時響起，就終止行動，馬上離開。",
          DialogueId = 11011425,
          Duration = 3,
          GUID = "1B90E1C1",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Some Phoxichor tanks may be equipped with self-destruct devices; if you hear a timer, evacuate immediately.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C1"
        },
        [11011426] = {
          ContentTC = "就是現在，打碎它！",
          DialogueId = 11011426,
          Duration = 3,
          GUID = "1B90E1C2",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Now! Smash it!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C2"
        },
        [11011427] = {
          ContentTC = "幹得不錯，我們還有兩個要處理。",
          DialogueId = 11011427,
          Duration = 3,
          GUID = "1B90E1C3",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Excellent work. We got two more tanks to go.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C3"
        },
        [11011428] = {
          ContentTC = "2號月髓艙的屏障解鎖了，上吧！",
          DialogueId = 11011428,
          Duration = 3,
          GUID = "1B90E1C4",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "The 2nd one has been disabled. Now!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C4"
        },
        [11011429] = {
          ContentTC = "呼……還有最後一個，你那兒還行嗎？",
          DialogueId = 11011429,
          Duration = 3,
          GUID = "1B90E1C5",
          NextDialogue = 11011430,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Whew... One more left. You okay down there?",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C5"
        },
        [11011430] = {
          ContentTC = "沒問題。",
          DialogueId = 11011430,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E1C6",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 110022,
          Subtitle = "No problems here.",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E1C6"
        },
        [11011432] = {
          ContentTC = "好了，3號，最後一個！",
          DialogueId = 11011432,
          GUID = "1B90E2E7",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "Alright, this is the last one!",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E7"
        },
        [11011433] = {
          ContentTC = "……自毀倒計時？",
          DialogueId = 11011433,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90E2E8",
          NextDialogue = 11011434,
          SpeakNpcId = 110022,
          Subtitle = "...A self-destruct timer?",
          VoiceName = "voice/$Locale$/story/1002/110114/1B90E2E8"
        },
        [11011434] = {
