        },
        [11011509] = {
          ContentTC = "怎麽？連總指揮官的聲音都聽不出了？",
          DialogueId = 11011509,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B90EFB2",
