        [11011527] = {
          ContentTC = "（閉口不言。）",
          DialogueId = 11011527,
          GUID = "1B90F2A6",
          ImprPlusId = 1006,
          NextDialogue = 11011528,
          Subtitle = "(Stay silent)"
        },
        [11011528] = {
          ContentTC = "繼續任務可以，給我們支援。",
          DialogueId = 11011528,
          Duration = 3,
          GUID = "1B90F2D0",
          NextDialogue = 11011535,
          SpeakNpcId = 110010,
          Subtitle = "We can continue the mission, but only with additional support.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F2D0"
        },
        [11011529] = {
          ContentTC = "給我們足夠的支援，我們才有希望取勝，這也是屬於您的勝利。",
          DialogueId = 11011529,
          GUID = "1B90F2FA",
          ImprPlusId = 1008,
          NextDialogue = 11011530,
          Subtitle = "Receiving enough support gives us a better chance of victory. A victory in your name, sir."
        },
        [11011530] = {
          Camera = "-120.756348,-24.742188,128.990662,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
          ContentTC = "富爾維斯指揮官，如果我們全都死在這裡，以你的戰術素養，只怕是更拿不下這座要塞。到時候，你就要為戰役的失利負責。",
          DialogueId = 11011530,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-111.863281,-36.107422,127.6828,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F324",
          NextDialogue = 11011531,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{7},TargetPosition{"-49.350586,-85.533203,128.152405,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-43.35791,-89.382812,127.603882,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0"},duration{15}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Commander Fulvis, if we all fall here, your tactical acumen alone won't stand a chance to take this fortress. And you'll surely have to answer for such a failure.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F324"
        },
        [11011531] = {
          ContentTC = "我們是你榮辱與共的下屬，不是你的敵人。",
          DialogueId = 11011531,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90F34E",
          NextDialogue = 11011532,
          SpeakNpcId = 110022,
          Subtitle = "We are your soldiers who fight for the glory of the Empire, not your enemies.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F34E"
        },
        [11011532] = {
          Camera = "-885.801758,-247.560547,331.117859,-2.0,-16.999998,14.005773,28.0,261.438629,false,DoNotOverride,3.0",
          ContentTC = "這又是哪個？哦，阿瓦爾那個好學生，「獅鷲」分隊的隊長{nickname2}？",
          DialogueId = 11011532,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-782.422363,-221.78125,310.503784,-2.0,-16.999992,14.006827,28.0,261.438629,false,DoNotOverride,3.0",
          GUID = "1B90F378",
          NextDialogue = 11011535,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "And who is this? Oh, it's you, , Avar's favourite protege and the Captain of the Griffins, I presume?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F378"
        },
        [11011533] = {
          ContentTC = "你那麽勇敢，怎麽不自己來前線？",
          DialogueId = 11011533,
          GUID = "1B90F379",
          ImprPlusId = 1010,
          NextDialogue = 11011534,
          Subtitle = "Since you're so full of courage, why don't you come to the front yourself?"
        },
