        [11011546] = {
          Camera = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我也收到了另一隊士兵匯報位置的信號，就在剛結束富爾維斯通訊的時候。{nickname2}，你怎麽打算？",
          DialogueId = 11011546,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B90F5C4",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextOptions = {
            [1] = 11011547,
            [2] = 11011549
          },
          SpeakNpcId = 110010,
          Subtitle = "I also picked up a signal from another squad reporting their position, right after Fulvis ended his call. , what are you gonna do?",
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F5C4"
        },
        [11011547] = {
          ContentTC = "我想先去救援士兵們，現在的情況，只靠我們沒什麽勝算。",
          DialogueId = 11011547,
          GUID = "1B90F5EE",
          ImprPlusId = 1009,
          NextDialogue = 11011548,
          Subtitle = "I intend to get to the soldiers first. We don't stand a chance on our own."
        },
        [11011548] = {
          Camera = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你啊……我果然沒看錯你。",
          DialogueId = 11011548,
          Duration = 3,
          GUID = "1B90F618",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11011550,
          SpeakNpcId = 110010,
          Subtitle = "You kiddo... I knew I was right about you.",
          TalkActionId = {
            [1] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F618"
        },
        [11011549] = {
          ContentTC = "我認為即使勝算不大，也應該執行總指揮官的命令。",
