          Duration = 3,
          GUID = "1B911100",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110005,
          Subtitle = "Please be careful... I'll see you in Dismania.",
          VoiceName = "voice/$Locale$/story/1002/110117/1B911100"
        },
        [11011801] = {
          ContentTC = "隊長！嗨——在這裡！",
          DialogueId = 11011801,
          Duration = 3,
          GUID = "1B911F9A",
          SpeakNpcId = 110015,
          Subtitle = "Captain! Captain, over here!",
          VoiceName = "voice/$Locale$/story/1002/110118/1B911F9A"
        },
        [11011802] = {
          Camera = "-485.80957,430.660156,148.512939,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊，隊長，我親愛的隊長！！終於找到你了！！我們的聯絡頻段突然出現異常，這一路誰也聯系不上，西蒙就跑出去求救了。",
          DialogueId = 11011802,
          FinalCamera = "-485.80957,430.660156,123.858765,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B911FC4",
          LookAt = {
            [1] = "110043:n(110022)",
            [2] = "110022:n(110043)"
          },
          NextDialogue = 11011803,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 408007,
            [5] = 101004
          },
          Scripts = [[
SEQ{
PARA{
MoveTo{ActorId{110022},TargetPoint{"fix11nanzhu"},MoveSpeed{150},Visibility{true}},
MoveTo{ActorId{110016},TargetPoint{"fix1102"},MoveSpeed{150},Visibility{true}},
MoveTo{ActorId{110043},TargetPoint{"fix1101"},MoveSpeed{150},Visibility{true}}
},
PlayAnimation{_click{False},ActorId{110043},AnimationId{"Talk01_Start"},Duration{2}}
}]],
          SpeakNpcId = 110043,
          Subtitle = "Oh, Captain! My dear Captain!! You finally came for us!! Something's gone wrong with our comm channels and we couldn't get in touch with nobody. Simon went out looking for help.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110118/1B911FC4"
        },
        [11011803] = {
          ContentTC = "我剛就一直跟大家鼓勁兒，隊長那麽厲害心眼兒又好，肯定「唰」得一下就跑過來幫咱們了。",
          DialogueId = 11011803,
          GUID = "1B911FEE",
          NextDialogue = 11011804,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110043:n(110016)"}},
LookAt{_delay{0.7},LookAtDescription{"110043:n(110022)"}},
PlayAnimation{_delay{1},_click{False},ActorId{110043},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110043,
          Subtitle = "I was just trying to get everyone to keep it together — told them how good you are and how you're gonna come flying in and get everyone out of this mess.",
          TalkActionId = {
            [1] = "110043:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B911FEE"
        },
        [11011804] = {
          Camera = "-176.421875,-207.507812,133.143555,0.000077,-4.60016,119.190758,40.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "隊長，你是一個人來的？你看到西蒙了嗎？",
          DialogueId = 11011804,
          GUID = "1B912018",
          LookAt = {
            [1] = "110016:n(110022)",
            [2] = "110022:n(110016)"
          },
          NextDialogue = 11011805,
          SpeakNpcId = 110016,
          Subtitle = "Captain, did you come alone? Did you see Simon?",
          TalkActionId = {
            [1] = "110043:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912018"
        },
        [11011805] = {
          ContentTC = "他死了。",
          DialogueId = 11011805,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Sad03"
          },
          GUID = "1B912042",
          NextDialogue = 11011806,
          SpeakNpcId = 110022,
          Subtitle = "He's dead.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
