          VoiceName = "voice/$Locale$/story/1002/110118/1B9124DA"
        },
        [11011834] = {
          Camera = "-400.358398,146.994141,125.597656,0.000137,-4.201385,-66.57859,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
