        },
        [11011837] = {
          Camera = "-313.795898,108.09375,127.78833,0.000089,-2.19943,130.844772,35.000011,125.671875,false,Manual,2.8",
          ContentTC = "她就算了。",
          DialogueId = 11011837,
          ExStoryInfo = "EXPlayer",
          GUID = "1B912582",
          LookAt = {
            [1] = "110022:n(110034)",
            [2] = "110034:n(110022)",
