          GUID = "1B9182DC",
          LookAt = {
            [1] = "110022:n(110015)"
          },
          NextDialogue = 11012407,
          SpeakNpcId = 110022,
          Subtitle = "I'll take it from here.",
          TalkActionId = {
            [1] = "110009:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110124/1B9182DC"
        },
        [11012407] = {
          ContentTC = "找我幹什麽？向我展示海伯利亞軍官老爺不計前嫌的大度？還是假惺惺地惋惜一下我這個「誤入歧途」的可憐小姑娘，想要「拯救」我啊？",
          DialogueId = 11012407,
          FacialId = {
