          GUID = "1B918528",
          NextDialogue = 11012421,
          Scripts = [[
SEQ{	
	PlayAnimation{_delay{3},ActorId{110009},AnimationId{"Talk02_End"},Duration{0}},
	PlayAnimation{_delay{1},ActorId{110009},AnimationId{"Explain02_Start"},Duration{1}}
		}]],
          SpeakNpcId = 110009,
          Subtitle = "Aww, you look like an angry bull. I'm so sorry, sir! I forgot you like it better when I talk like this.",
