        },
        [11012456] = {
          Camera = "-14.494629,-247.046387,127.962891,0.000166,-0.200958,77.201035,35.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "你還記得，在去炮臺的路上，我對你說過的嗎？「你會因為自己的善良得到報答」。",
          DialogueId = 11012456,
          Duration = 3,
          FinalCamera = "-30.220276,-242.865723,127.962891,0.000166,-0.000949,73.200394,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B918B10",
          LookAt = {
            [1] = "110009:n(110022)"
          },
          NextDialogue = 11012457,
          SpeakNpcId = 110009,
          Subtitle = "Remember what I said back on our way to the turret? \"Your kindness will reap a just reward.\"",
          TalkActionId = {
            [1] = "110009:Explain01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918B10"
        },
        [11012457] = {
          Camera = "-1.842346,73.166504,141.122986,-14.000256,-7.600402,-64.015198,15.610332,100000.0,false,Manual,22.0",
          ContentTC = "耳朵湊過來。我還有句悄悄話，只對你一個人講——放心吧，剛才你們搜過我身了，這次真的什麽兇器都沒藏啦。",
          DialogueId = 11012457,
          Duration = 3,
          FinalCamera = "-5.238708,71.569336,140.194946,-14.000041,-6.800389,-63.814953,15.610332,100000.0,false,Manual,22.0",
          GUID = "1B918B3A",
          LookAt = {
            [1] = "110022:n(110009)"
          },
          NextDialogue = 11012458,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{110009},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 110009,
          Subtitle = "Lend me your ear. I've got a secret that's just for you. Rest assured, you've just frisked me. I am really out of weapons.",
          TalkActionId = {
            [1] = "110009:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110124/1B918B3A"
        },
        [11012458] = {
          Camera = "-13.709473,-53.60498,139.083374,0.000239,1.00024,75.184746,35.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "這句話可能對你很重要哦，確定不聽？",
          DialogueId = 11012458,
          Duration = 3,
          FinalCamera = "-27.294617,-48.557129,139.083374,0.000238,0.800252,66.985054,35.0,100000.0,false,DoNotOverride,22.0",
