        },
        [11012467] = {
          ContentTC = "親愛的，你回來了？該不會是突然反悔，想聽悄悄話了？",
          DialogueId = 11012467,
          Duration = 3,
          GUID = "1B918CB4",
          NextDialogue = 11012468,
          SpeakNpcId = 110009,
          Subtitle = "You're back, honey. Changed your mind already? Desperate to hear out the secret?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CB4"
        },
        [11012468] = {
          ContentTC = "但是很遺憾，我現在心情不太好，不想說了。",
          DialogueId = 11012468,
          Duration = 3,
          GUID = "1B918CDE",
          SpeakNpcId = 110009,
          Subtitle = "Sorry to disappoint, but I'm no longer in the mood for sharing.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CDE"
        },
        [11012469] = {
          ContentTC = "親愛的，我知道你想問什麽。",
          DialogueId = 11012469,
          Duration = 3,
          GUID = "1B918D08",
          NextDialogue = 11012470,
          SpeakNpcId = 110009,
          Subtitle = "I know what you want, honey.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D08"
        },
        [11012470] = {
          ContentTC = "但是很遺憾，我這個可憐的階下囚，現在已經沒心情說話了~",
          DialogueId = 11012470,
          Duration = 3,
          GUID = "1B918D32",
          SpeakNpcId = 110009,
          Subtitle = "But I'm just a poor little captive now, not in the mood to talk.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D32"
        },
        [11012501] = {
          ContentTC = "<W>沒錯，就是這樣……把劍柄握得緊緊的。是的，你做得很好。你只需要對準它的喉嚨——</>",
          DialogueId = 11012501,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919272",
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "That's right — you've made the right choice. Grip the hilt tightly. Yes, just like that. Now aim at the creature's throat...",
          VoiceName = "voice/$Locale$/story/1002/110125/1B919272"
        },
        [11012502] = {
          ContentTC = "你……你瘋了？",
          DialogueId = 11012502,
          Duration = 3,
          GUID = "1B91929C",
          SpeakNpcId = 110009,
          Subtitle = "Are... Are you insane?",
          VoiceName = "voice/$Locale$/story/1002/110125/1B91929C"
        },
        [11012503] = {
          ContentTC = "<W>對。刺下去，不要猶豫。</>",
          DialogueId = 11012503,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9192C6",
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Effect/Material/Post/m_blur_003.m_blur_003'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Yes, do it. Do not hesitate.",
          VoiceName = "voice/$Locale$/story/1002/110125/1B9192C6"
        },
        [11012504] = {
          ContentTC = "啊……啊啊啊啊啊！！",
