        },
        [11012725] = {
          Camera = "431.175476,-72.250488,84.118408,0.000063,-1.799133,150.597992,30.0,501.809082,false,DoNotOverride,5.0",
          ContentTC = "嗯。準備好，我們就出發吧。",
          DialogueId = 11012725,
