          ContentTC = "這——不是那個你很得意的學生嗎？你做的？",
          DialogueId = 11013604,
          Duration = 5,
          FacialId = {
            [1] = "110011:Smile01"
          },
          FinalCamera = "165.08638,2264.316406,568.964294,-0.001626,-67.592896,61.591228,39.663486,100000.0,false,Manual,22.0",
          GUID = "1B924768",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013605,
          SpeakNpcId = 110011,
          Subtitle = "Isn't this your favourite protege? You did this?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924768"
        },
        [11013605] = {
          Camera = "151.53949,105.84375,142.877136,-0.001525,-17.594362,56.191444,60.0,100000.0,false,DoNotOverride,4.0",
          ContentTC = "嗬，因為我想和你談筆交易。這裡的事只有我們兩個知道，不需要多餘的耳朵。",
          DialogueId = 11013605,
          Duration = 3,
          GUID = "1B924792",
          NextDialogue = 11013606,
          Scripts = [[
