          VoiceName = "voice/$Locale$/story/1002/110151/1B933EA6"
        },
        [11015112] = {
          ContentTC = "脫掉外衣。",
          DialogueId = 11015112,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933ED0",
          NextDialogue = 11015113,
          SpeakNpcId = 110022,
          Subtitle = "Take off your clothes.",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B933ED0"
        },
        [11015113] = {
          Camera = "-17.943359,-63.457489,146.000702,0.000093,-3.202395,18.475502,35.0,100000.0,false,Manual,22.0",
          ContentTC = "什麽？",
          DialogueId = 11015113,
          Duration = 3,
          FinalCamera = "-0.720703,-57.570724,144.94313,0.000094,-3.00238,17.275826,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933EFA",
          NextDialogue = 11015114,
          SpeakNpcId = 110005,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "110005:Shock04_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933EFA"
        },
        [11015114] = {
          Camera = "489.007812,-334.206299,292.918701,0.000068,-19.202305,139.670319,35.0,100000.0,false,Manual,22.0",
          ContentTC = "脫掉外衣，和我交換。",
          DialogueId = 11015114,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "445.892578,-297.610748,273.224854,0.000065,-19.402313,139.27037,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933F24",
          NextDialogue = 11015115,
          SpeakNpcId = 110022,
          Subtitle = "We're switching outfits.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F24"
        },
        [11015115] = {
          ContentTC = "他們以為我死在了中央控製室，不知道現在和你在一起的人是誰，所以他們能確認的目標只有你。",
          DialogueId = 11015115,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F4E",
          NextDialogue = 11015116,
          SpeakNpcId = 110022,
          Subtitle = "They think I died in the central control room and they have no idea who your accomplice is. You are the only target they can identify.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F4E"
        },
        [11015116] = {
          ContentTC = "我扮成你的樣子往外沖，醫務員的製服很醒目，應該可以引開他們。你就想辦法趁亂逃掉。",
          DialogueId = 11015116,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933F78",
          NextDialogue = 11015117,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "I'll wear your uniform and make a run out there. The medic's uniform is conspicuous enough to draw their attention. You'll make your escape during the chaos.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933F78"
        },
        [11015117] = {
          Camera = "30.167969,-51.420792,112.9972,0.000112,8.79729,16.678789,35.0,100000.0,false,Manual,22.0",
          ContentTC = "您……是在開玩笑嗎？我們的身形根本不一樣，他們很快就會察覺的！",
          DialogueId = 11015117,
          Duration = 3,
          FinalCamera = "49.683594,-45.570618,123.095779,0.000108,7.997291,16.280628,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933FA2",
          NextDialogue = 11015118,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Shock04_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "Are you serious? We're completely different sizes! They'll quickly realise they're chasing the wrong person!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FA2"
        },
        [11015118] = {
          Camera = "174.623047,-31.802631,151.059662,0.000112,-2.002987,168.472702,35.0,100000.0,false,Manual,22.0",
          ContentTC = "能多讓他們慌亂一秒，你就多一秒能逃走的機會。就這樣吧，達芙涅。不要違背老師的遺願。",
          DialogueId = 11015118,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "182.253906,-34.744297,148.60463,0.000112,-1.403016,167.073715,35.0,100000.0,false,Manual,22.0",
          GUID = "1B933FCC",
          SpeakNpcId = 110022,
          Subtitle = "The longer I can distract them, the better your chances. This is the plan, Daphne. Honour Sir Avar's last wishes.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FCC"
        },
        [11015119] = {
          ContentTC = "別猶豫了，快。",
          DialogueId = 11015119,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B933FF6",
          SpeakNpcId = 110022,
          Subtitle = "Don't hesitate, hurry up.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B933FF6"
        },
        [11015120] = {
          ContentTC = "……不。",
          DialogueId = 11015120,
          Duration = 2,
          GUID = "1B934020",
          SpeakNpcId = 110005,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934020"
        },
        [11015121] = {
          ContentTC = "謝謝您能記住父親的願望。",
          DialogueId = 11015121,
          Duration = 3,
          GUID = "1B93404A",
          SpeakNpcId = 110005,
          Subtitle = "Thank you for respecting my father's wish.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93404A"
        },
        [11015122] = {
          ContentTC = "但能請您聽一聽，<H>我的願望</>嗎？",
          DialogueId = 11015122,
          Duration = 3,
          GUID = "1B934074",
          SpeakNpcId = 110005,
          Subtitle = "But could you at least hear my wishes?",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934074"
        },
        [11015123] = {
          ContentTC = "迪斯瑪尼亞常常會下雨。在我很小的時候，我的玩伴們都很討厭下雨，因為雨會打濕漂亮的頭髮，弄臟乾淨的新裙子。",
          DialogueId = 11015123,
          Duration = 3,
          FacialId = {
            [1] = "110005:Sad01"
          },
          GUID = "1B93409E",
          LookAt = {
            [1] = "110005:n(110022)",
            [2] = "110022:n(110005)"
          },
          NextDialogue = 11015124,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201016,
            [6] = 408007,
            [7] = 101004
          },
          SpeakNpcId = 110005,
          Subtitle = "Dismania is a rainy place. When I was a little girl, all my friends hated the rain because it would mess with their hair and soil their pretty dresses.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B93409E"
        },
        [11015124] = {
          ContentTC = "但我不討厭。因為雨從來不會落到我的肩頭。我看到的雨，只是靴子下一圈圈的小水花，傘尖墜落的一串串露滴。",
          DialogueId = 11015124,
          Duration = 3,
          GUID = "1B9340C8",
          NextDialogue = 11015125,
          SpeakNpcId = 110005,
          Subtitle = "But I didn't hate the rain, because it never reached my shoulders. In my eyes, the rain was just little ripples sprouting around my boots and droplets dripping off the brolly.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340C8"
        },
        [11015125] = {
          ContentTC = "但是長大一點之後，我知道了，我並沒有那麽喜歡下雨。只是因為當時爸爸在，所以所有的雨，都落在了他的那一邊。",
          DialogueId = 11015125,
          Duration = 3,
          GUID = "1B9340F2",
          NextDialogue = 11015126,
          SpeakNpcId = 110005,
          Subtitle = "But as I grew older, I realised that rain wasn't that nice. It used to look nice, only because my dad was there to bear it for me.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9340F2"
        },
        [11015126] = {
          ContentTC = "爸爸啊，是一個很好很好的人，也是一個很倔很倔的人。他永遠都在為了別人不顧自己，永遠都是。",
          DialogueId = 11015126,
          Duration = 3,
          GUID = "1B93411C",
          NextDialogue = 11015128,
          SpeakNpcId = 110005,
          Subtitle = "My dad is such a kind man, and such a stubborn one too. He always put others first. Always.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93411C"
        },
        [11015127] = {
          ContentTC = "…………",
          DialogueId = 11015127,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934146",
          NextDialogue = 11015128,
          SpeakNpcId = 110022,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934146"
        },
        [11015128] = {
          ContentTC = "我出生前，他為了能夠「配得上」媽媽而加入軍團，出生入死；我長大後，他又為了「不耽誤我的前程」而離開我和媽媽。",
          DialogueId = 11015128,
          Duration = 3,
          GUID = "1B934170",
          NextDialogue = 11015129,
          SpeakNpcId = 110005,
          Subtitle = "Before I was born, he joined the Legion and fought hard to prove himself worthy of my mom. After I grew up, he left us because he didn't want to \"soil my future.\"",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934170"
        },
        [11015129] = {
          ContentTC = "……在大街上，他板著臉讓我不要喊他爸爸。在深夜的酒館裡，他喊著我和媽媽的名字，一邊喝得酩酊大醉，一邊流淚——多麽偉大的父親，總是一個人抗下一切……",
          DialogueId = 11015129,
          Duration = 3,
          GUID = "1B93419A",
          NextDialogue = 11015130,
          SpeakNpcId = 110005,
          Subtitle = "...In public, he'd scowl and forbid me to call him Dad. But deep in the night, he'd drunkenly shout mine and my mother's name, crying — He was always bearing the weight of everything on his own...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93419A"
        },
        [11015130] = {
          ContentTC = "可是，他從來都沒有問過我，這一切到底是不是我想要的……就像此刻的您，也從來沒有問過我，我是否想要踏著您的生命活下去！",
          DialogueId = 11015130,
          Duration = 3,
          GUID = "1B9341C4",
          SpeakNpcId = 110005,
          Subtitle = "But he never asked if I wanted any of this... Just like you never asked if I wanted to live knowing you sacrificed yourself for me!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341C4"
        },
        [11015131] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Manual,22.0",
          ContentTC = "您與他都不知道……我想要的，從來都不是一個用自己的身軀為我遮擋風雨的人。我真正的願望是……",
          DialogueId = 11015131,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          GUID = "1B9341EE",
          NextDialogue = 11015132,
          SpeakNpcId = 110005,
          Subtitle = "Neither of you know what I actually wanted... I never wished for a hero who'd shield me from the rain. My wish is that...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9341EE"
        },
        [11015132] = {
          Camera = "74.1875,-11.549334,140.752075,0.000139,2.317531,0.270602,35.0,100000.0,false,Manual,22.0",
          ContentTC = "如果遮風擋雨的傘小到只能庇護一人，請讓我和你們一起走進雨裡。",
          DialogueId = 11015132,
          Duration = 3,
          FinalCamera = "54.34375,-11.712122,143.421494,0.000139,-0.282503,0.470605,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934218",
          NextDialogue = 11015133,
          SpeakNpcId = 110005,
          Subtitle = "If there's only room for one under the brolly, I'll brave the rain with you all.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934218"
        },
        [11015133] = {
          ContentTC = "我，想要的是，<H>和您一起</>活下去。",
          DialogueId = 11015133,
          Duration = 3,
          FacialId = {
            [1] = "110005:Smile01"
          },
          GUID = "1B934242",
          NextDialogue = 11015134,
          SpeakNpcId = 110005,
          Subtitle = "I wish that we make it out and live on, together.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934242"
        },
        [11015134] = {
          Camera = "148.310547,4.638587,138.830399,0.000143,6.517544,-170.927872,35.0,100000.0,false,Manual,22.0",
          ContentTC = "達芙涅……",
          DialogueId = 11015134,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "160.496094,6.583258,134.802444,0.000143,6.317535,-170.927872,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93426C",
          NextDialogue = 11015135,
          SpeakNpcId = 110022,
          Subtitle = "Daphne...",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93426C"
        },
        [11015135] = {
          Camera = "54.921875,23.440533,140.073502,0.000153,1.11843,-18.329687,35.0,100000.0,false,Manual,22.0",
          ContentTC = "我們再一起想想吧……一定有辦法，一定還有辦法的！",
          DialogueId = 11015135,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unhappy01"
          },
          FinalCamera = "70.310547,18.636772,139.925446,0.000152,2.918505,-16.931318,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934296",
          NextDialogue = 11015136,
          SpeakNpcId = 110005,
          Subtitle = "Let's think together… There has to be another way!",
          TalkActionId = {
            [1] = "110005:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934296"
        },
        [11015136] = {
          Camera = "-35.435547,164.474655,360.730713,0.000111,20.917017,-153.732254,35.0,100000.0,false,Manual,22.0",
          ContentTC = "現在的情況是，富爾維斯要滅我們的口，他的手段是給我們扣上間諜的帽子，借軍團同僚的手誅殺我們……",
          DialogueId = 11015136,
          Duration = 3,
          FinalCamera = "-35.435547,164.474655,327.571594,0.000111,20.717014,-153.73233,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9342C0",
          NextDialogue = 11015137,
          SpeakNpcId = 110005,
          Subtitle = "Fulvis wants us silenced. That's our situation. He's labelled us as spies so that our fellow soldiers would kill us for him...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342C0"
        },
        [11015137] = {
          ContentTC = "「獅鷲」、「雪狼」兩支先遣小隊僅剩我們二人，整座要塞的士兵全受富爾維斯和他的副官法露茜調遣……整座要塞的士兵……",
          DialogueId = 11015137,
          Duration = 3,
          GUID = "1B9342EA",
          NextDialogue = 11015138,
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We're the only ones left from the Griffins and Snow Wolves. Every soldier here follows Fulvis and his adjutant Falsi... Every soldier in the fortress...",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9342EA"
        },
        [11015138] = {
          Camera = "43.673828,56.272556,139.847488,0.000149,0.117582,-27.726179,35.0,100000.0,false,Manual,22.0",
          ContentTC = "等等，我想到了……！父親和我講過，「以退為進，險中求勝」……",
          DialogueId = 11015138,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "58.037109,42.618416,142.168106,0.000149,1.317605,-24.925119,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934314",
          NextDialogue = 11015139,
          SpeakNpcId = 110005,
          Subtitle = "Wait, I have an idea...! Father once said a strategic retreat could be a cover for an advance. Sometimes the greatest risks lead to victory.",
          TalkActionId = {
            [1] = "110005:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934314"
        },
        [11015139] = {
          Camera = "7.253906,20.019621,143.611893,0.00015,-1.08212,-15.727008,35.0,100000.0,false,Manual,22.0",
          ContentTC = "我們還有一個選擇……「自投羅網」。",
          DialogueId = 11015139,
          Duration = 3,
          GUID = "1B93433E",
          NextOptions = {
            [1] = 11015140,
            [2] = 11015142
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 110005,
          Subtitle = "We still have one option... We can turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93433E"
        },
        [11015140] = {
          ContentTC = "你要去找富爾維斯？",
          DialogueId = 11015140,
          GUID = "1B934368",
          NextDialogue = 11015141,
          Subtitle = "You want to surrender to Fulvis?"
        },
        [11015141] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentTC = "不，不是富爾維斯，而是<H>另一個人</>……",
          DialogueId = 11015141,
          Duration = 3,
          GUID = "1B934392",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "No, not to Fulvis. To someone else...",
          TalkActionId = {
            [1] = "110005:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934392"
        },
        [11015142] = {
          ContentTC = "你要去找……另一個人？",
          DialogueId = 11015142,
          GUID = "1B9343BC",
          NextDialogue = 11015143,
          Subtitle = "Turn ourselves in... to someone else?"
        },
        [11015143] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentTC = "對！",
          DialogueId = 11015143,
          Duration = 3,
          GUID = "1B9343E6",
          NextDialogue = 11015145,
          SpeakNpcId = 110005,
          Subtitle = "Exactly!",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B9343E6"
        },
        [11015145] = {
          Camera = "52.292969,25.010664,127.544891,0.000135,6.718037,-16.930437,35.0,100000.0,false,Manual,22.0",
          ContentTC = "你還記不記得，法露茜說過這樣的話？",
          DialogueId = 11015145,
          Duration = 3,
          FinalCamera = "48.234375,29.943214,125.579117,0.000142,6.717955,-19.329165,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93443A",
          NextDialogue = 11015146,
          SpeakNpcId = 110005,
          Subtitle = "Remember what Falsi said in the broadcast?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93443A"
        },
        [11015146] = {
          ContentTC = "封鎖所有地下出口，等叛徒出來，即刻處決。",
          DialogueId = 11015146,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B934464",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015147,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SpeakNpcId = 110012,
          Subtitle = "Seal all exits. Once they surface, we'll eliminate the traitors.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934464"
        },
        [11015147] = {
          ContentTC = "快點，留給我們的時間不多了！",
          DialogueId = 11015147,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B93448E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
          NextDialogue = 11015148,
          SpeakNpcId = 110012,
          Subtitle = "Hurry up! We're running out of time!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93448E"
        },
        [11015148] = {
          Camera = "-171.576172,354.275269,321.845215,0.000118,-24.091339,-52.323902,35.0,100000.0,false,Manual,22.0",
          ContentTC = "現在龍莎要塞完全在富爾維斯的手裡，抓到我們是遲早的事，法露茜究竟在為什麽而慌張？",
          DialogueId = 11015148,
          Duration = 3,
          FinalCamera = "-196.277344,386.265381,339.917847,0.000119,-24.091339,-52.323936,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9344B8",
          NextDialogue = 11015149,
          SpeakNpcId = 110005,
          Subtitle = "Lonza Fortress is currently under Fulvis's full control. We're little more than rats in a cage. Then why is Falsi in such a hurry?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344B8"
        },
        [11015149] = {
          ContentTC = "而在那之前，您還記不記得我提到過，我偷聽到一位士兵說——",
          DialogueId = 11015149,
          Duration = 3,
          GUID = "1B9344E2",
          NextDialogue = 11015150,
          SpeakNpcId = 110005,
          Subtitle = "Do you remember what I overheard earlier from one of the soldiers—",
          VoiceName = "voice/$Locale$/story/1002/110151/1B9344E2"
        },
        [11015150] = {
          ContentTC = "因為戰局不順，西比爾軍團長也在趕來龍莎要塞的路上。",
          DialogueId = 11015150,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          GUID = "1B93450C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014415.T_Story_Recall_11014415'",
          NextDialogue = 11015151,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Chief Sibylle is en route to Lonza Fortress after hearing the battle has turned.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93450C"
        },
        [11015151] = {
          Camera = "154.445312,44.61274,163.534317,0.000121,-6.890936,-151.527649,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……你的意思是，你想找到西比爾，請求她的庇護。",
          DialogueId = 11015151,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "177.171875,56.903561,166.748993,0.000123,-8.491031,-151.927643,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934536",
          NextDialogue = 11015152,
          SpeakNpcId = 110022,
          Subtitle = "...So you want to seek protection from Sibylle?",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934536"
        },
        [11015152] = {
          Camera = "31.996094,51.468288,139.671326,0.000175,-0.491391,-24.739786,35.0,100000.0,false,Manual,22.0",
          ContentTC = "是的。",
          DialogueId = 11015152,
          Duration = 3,
          GUID = "1B934560",
          NextDialogue = 11015153,
          SpeakNpcId = 110005,
          Subtitle = "Correct.",
          TalkActionId = {
            [1] = "110005:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934560"
        },
        [11015153] = {
          Camera = "179.789062,39.516891,181.891464,0.000178,-14.491817,-158.539825,35.0,100000.0,false,Manual,22.0",
          ContentTC = "但是富爾維斯已經給我們安排了罪名，甚至準備好了偽證……等一下，我明白你的「自投羅網」了。",
          DialogueId = 11015153,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B93458A",
          NextDialogue = 11015154,
          SpeakNpcId = 110022,
          Subtitle = "But Fulvis has already condemned us and even fabricated evidence... Wait, I get why you want to turn ourselves in.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93458A"
        },
        [11015154] = {
          Camera = "42.076172,35.060333,133.820343,0.000195,2.508544,-21.337816,35.0,100000.0,false,Manual,22.0",
          ContentTC = "嗯！西比爾軍團長也是煉金院出身，以我對她的了解，她不會容忍任何叛徒——即使是最親近的人。",
          DialogueId = 11015154,
          Duration = 3,
          FacialId = {
            [1] = "110005:Confident01"
          },
          FinalCamera = "28.144531,40.503914,129.73497,0.000195,2.508482,-21.537373,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9345B4",
          NextDialogue = 11015155,
          SpeakNpcId = 110005,
          Subtitle = "Mm-hmm! Chief Sibylle is also a graduate of the Academy. From what I know of her, she wouldn't tolerate betrayal from anyone, not even those she holds dear.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345B4"
        },
        [11015155] = {
          Camera = "-191.923828,110.773376,292.437317,0.000252,-26.092831,-22.740551,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……但也因此，她一定會慎重審問，不會讓嫌犯輕易沒命，以至斷掉線索。",
          DialogueId = 11015155,
          Duration = 3,
          FinalCamera = "-139.972656,126.843193,222.647064,0.000272,-16.892361,-30.148384,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9345DE",
          NextDialogue = 11015156,
          SpeakNpcId = 110005,
          Subtitle = "...Which is also why Sibylle would carefully review any acts of treason. She would not make any hasty decisions to execute the suspects because she'd want to get to the bottom of it.",
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9345DE"
        },
        [11015156] = {
          ContentTC = "如果我們能見到她，最大的可能，我們會被投入軍事監獄。聽聞那裡壁壘森嚴，連一只鳥兒都飛不出來；但也因此，一切想要對我們滅口的危險，也都進不去。",
          DialogueId = 11015156,
          Duration = 3,
          GUID = "1B934608",
          NextDialogue = 11015157,
          SpeakNpcId = 110005,
          Subtitle = "If we manage to meet her, she's most likely to throw us into the Imperial Prison. The Prison is reputedly so well guarded that even a fly could not escape the place. But it'll also keep out anyone who wishes to silence us.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934608"
        },
        [11015157] = {
          ContentTC = "那裡反而變成了最安全的地方。而在審問中證明自己無罪，是我們唯一活下去的機會。",
          DialogueId = 11015157,
          Duration = 3,
          GUID = "1B934632",
          NextDialogue = 11015158,
          SpeakNpcId = 110005,
          Subtitle = "The Imperial Prison will be our safest refuge. We can prove our innocence during interrogations. This is our only chance to survive.",
          VoiceName = "voice/$Locale$/story/1002/110151/1B934632"
        },
        [11015158] = {
          Camera = "47.939453,49.246361,119.444901,0.000288,8.907598,-26.339521,35.0,100000.0,false,Manual,22.0",
          ContentTC = "只是要委屈一下您，因間諜罪接受審查，必然會有損您的名譽……但是，只要我們挺過審訊，就能還自己清白，讓真正的罪人伏誅。",
          DialogueId = 11015158,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          FinalCamera = "27.193359,59.519375,115.815987,0.000286,7.707581,-26.338728,35.0,100000.0,false,Manual,22.0",
          GUID = "1B93465C",
          NextDialogue = 11015159,
          SpeakNpcId = 110005,
          Subtitle = "Your reputation will suffer though, as you'll be interrogated for espionage... But once we endure the questioning, we will be able to clear our names and bring the real traitors to justice.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B93465C"
        },
        [11015159] = {
          Camera = "243.919922,32.791145,139.274689,0.00031,-0.492122,-160.143555,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……因間諜罪接受審查……這件事有沒有可能傳到軍團外面去，比如皇室？",
          DialogueId = 11015159,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "259.697266,38.494522,139.446808,0.000309,-1.092161,-160.143555,35.0,100000.0,false,Manual,22.0",
          GUID = "1B934686",
          NextDialogue = 11015160,
          SpeakNpcId = 110022,
          Subtitle = "...Being questioned for espionage... Any chance that word gets out beyond the Legion? Perhaps the royal family will hear of this?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B934686"
        },
        [11015160] = {
          Camera = "49.503906,51.240067,154.416092,0.000309,-5.89185,-28.343378,35.0,100000.0,false,Manual,22.0",
          ContentTC = "尤裡烏斯陛下一向極為重視軍事，十三軍團又是他親自建立的，我想會的……",
          DialogueId = 11015160,
          Duration = 3,
          FacialId = {
            [1] = "110005:None"
          },
          FinalCamera = "49.503906,51.240067,138.708191,0.000309,0.108293,-28.74304,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9346B0",
          NextDialogue = 11015161,
          RelatedWikiId = {
            [1] = 201018
          },
          SpeakNpcId = 110005,
          Subtitle = "The army has always been the focus of Emperor Julius. Moreover, His Majesty personally founded the 13th Legion. I believe it will reach his ears...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346B0"
        },
        [11015161] = {
          Camera = "132.001953,71.535721,136.665466,0.000171,6.118688,-133.138336,35.0,100000.0,false,Manual,22.0",
          ContentTC = "……這麽說來，或許<H>那個人</>也能幫上忙。",
          DialogueId = 11015161,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "143.138672,83.421745,135.787506,0.000172,4.518669,-132.938339,35.0,100000.0,false,Manual,22.0",
          GUID = "1B9346DA",
          NextDialogue = 11015162,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 110022,
          Subtitle = "Then perhaps... that person can help us.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110151/1B9346DA"
        },
        [11015162] = {
          ContentTC = "好，按你說的辦吧。我們去找西比爾。",
          DialogueId = 11015162,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934704",
          SpeakNpcId = 110022,
          Subtitle = "Alrigh, let's go with your plan and find Sibylle.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110151/1B934704"
        },
        [11015163] = {
          ContentTC = "沒時間猶豫了，走吧！",
          DialogueId = 11015163,
          Duration = 3,
          GUID = "1B93472E",
          SpeakNpcId = 110005,
          Subtitle = "Time's against us. Let's move!",
          VoiceName = "voice/$Locale$/story/1002/110151/1B93472E"
        },
        [11015201] = {
          ContentTC = "於是，我牽起了她的手，朝著透過門縫的那一隙陽光走去。",
          DialogueId = 11015201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D6A",
          NextDialogue = 11015202,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And thus, I took her hand and we stepped towards that narrow beam of sunlight piercing through the door's gap.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D6A"
        },
        [11015202] = {
          ContentTC = "就像是，正踏入一座光輝璀璨的墳墓——",
          DialogueId = 11015202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934D94",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "It felt as though we were stepping into a shimmering grave of our own making...",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934D94"
        },
        [11015203] = {
          ContentTC = "我們用盡最後的力氣甩開追兵，一路找到剛抵達要塞的西比爾軍團長。",
          DialogueId = 11015203,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DBE",
          NextDialogue = 11015204,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "We expended our last ounces of strength evading our pursuers, in time to meet Chief Sibylle, who had just arrived at the fortress.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DBE"
        },
        [11015204] = {
          ContentTC = "再後來，正如達芙涅猜測的那樣，我們被押送到了這裡。",
          DialogueId = 11015204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B934DE8",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "And just as Daphne had predicted, we were escorted to this very place.",
          VoiceName = "voice/$Locale$/story/1002/110152/1B934DE8"
        },
        [11015301] = {
          Camera = "89.232414,-2.948067,11.488281,0.999996,-1.199982,-0.798315,45.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "精彩的故事，和現場「一角鯨」士兵的證詞完全相反。既然你主張你和阿瓦爾·赫德蘭無罪，那麽——",
          DialogueId = 11015301,
          Duration = 1,
          GUID = "1B935DD2",
          NextDialogue = 11019310,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019
          },
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{2.5},TargetPosition{"-93.449196,-7.990425,2.617188,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-134.447235,-8.27565,1.480469,0.0,1.599883,0.401891,35.000008,100000.0,false,DoNotOverride,2.8"},duration{8}}
},
PlayOrStopBGM{PlayType{"Play"},
SoundType{"SOUND_BGM"},
EventPath{"event:/bgm/cbt02/0043_story_empire"}},
PlayAnimation{ActorId{110039},AnimationId{"Sit_Start"},Duration{1}}
}]],
          SpeakNpcId = 110039,
          Subtitle = "What a riveting story, which completely contradicts the testimonies provided by the Narwhals. Since you claim that you and Avar Hrodland are innocent—",
          TurnTo = {
            [1] = "110022:n(110039)"
          },
          VoiceName = "voice/$Locale$/story/1002/110153/1B935DD2"
        },
        [11015307] = {
          Camera = "175.138626,16.254257,-15.015625,0.000019,25.795355,-21.761339,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……你清楚自己在說什麽嗎？",
          DialogueId = 11015307,
          Duration = 3,
          GUID = "1B935ECE",
          NextDialogue = 11015308,
          SpeakNpcId = 110039,
          Subtitle = "...Do you have any idea what you just said?",
          VoiceName = "voice/$Locale$/story/1002/110153/1B935ECE"
        },
        [11015308] = {
          Camera = "389.865051,85.663879,11.320312,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我清楚。我正式指控安東尼·富爾維斯，他是龍莎要塞一案真正的幕後黑手。",
          DialogueId = 11015308,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          FinalCamera = "378.377686,84.125763,12.214844,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935EF8",
          NextDialogue = 11015309,
          SpeakNpcId = 110022,
          Subtitle = "I absolutely do. I'm formally accusing Antonius Fulvis of orchestrating the events at Lonza Fortress.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110039:Sit_Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935EF8"
        },
        [11015309] = {
          Camera = "138.132721,33.639923,-21.648438,0.000026,20.39575,-25.164968,25.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "那你知不知道，如果你對富爾維斯上校的指控不實，你將面臨什麽刑罰？",
          DialogueId = 11015309,
          Duration = 3,
          FinalCamera = "144.695236,30.554977,-26.570312,0.000028,20.395737,-25.163847,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935F22",
          NextDialogue = 11015310,
          SpeakNpcId = 110039,
          Subtitle = "Then are you aware of the consequences if your accusation against Colonel Fulvis are proven false?",
          TalkActionId = {
            [1] = "110022:Talk02_End",
            [2] = "110039:Sit_Talk03ToTalkR_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935F22"
        },
        [11015310] = {
          Camera = "149.444336,-10.450867,-8.71875,0.000056,9.995599,-179.96492,25.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "……誣陷罪，十年監禁。",
          DialogueId = 11015310,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110039:None",
            [2] = "110022:None"
          },
          FinalCamera = "118.790039,-10.450943,-3.3125,0.000056,9.995599,-179.96492,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935F4C",
          NextDialogue = 11015311,
          SpeakNpcId = 110022,
          Subtitle = "...It's ten years in prison, for making false accusations.",
          TalkActionId = {
            [1] = "110039:Sit_Talk03ToTalkR_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935F4C"
        },
        [11015311] = {
          Camera = "-75.674171,170.735184,471.796875,0.000076,-53.397903,-27.591795,15.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "回答錯誤，是叛國罪、間諜罪和誣陷罪。",
          DialogueId = 11015311,
          Duration = 3,
          FinalCamera = "-56.026688,160.466644,454.570312,0.00008,-53.397835,-27.591671,15.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935F76",
          NextDialogue = 11015312,
          SpeakNpcId = 110021,
          Subtitle = "Incorrect. You'll be charged with treason, espionage, and making false accusations.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935F76"
        },
        [11015312] = {
          Camera = "135.673386,220.094009,-5.660156,-0.99997,17.801788,-36.789379,35.000008,1.5,false,DoNotOverride,1.2",
          ContentTC = "你會被處以帝國的最高極刑——以荊棘藤條倒懸著釘在迪斯瑪尼亞市中心的天之樹上公開行刑，直至咽氣。",
          DialogueId = 11015312,
          Duration = 3,
          FinalCamera = "141.826721,215.4944,-3.203125,-0.99997,17.801788,-36.789379,35.000008,1.5,false,DoNotOverride,1.2",
          GUID = "1B935FA0",
          NextDialogue = 11015313,
          RelatedWikiId = {
            [1] = 407002
          },
          SpeakNpcId = 110021,
          Subtitle = "And the highest penalty in the Empire awaits you: being hung upside down with thorny vines and crucified on the Heaventree in the centre of Dismania, until your very last breath is taken.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935FA0"
        },
        [11015313] = {
          Camera = "-13.288574,747.44519,159.546875,-1.0,-6.197686,-87.991653,15.0,1.5,false,DoNotOverride,1.2",
          ContentTC = "我說的全部都是事實。既然你們選擇對我和達芙涅·塞奧多爾分開審訊，就應該知道，我們的證詞完全可以互證。",
          DialogueId = 11015313,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "24.04541,748.68158,160.195312,-1.0,-6.197686,-87.991653,15.0,1.5,false,DoNotOverride,1.2",
          GUID = "1B935FCA",
          NextDialogue = 11015314,
          SpeakNpcId = 110022,
          Subtitle = "I'm telling the truth. Since you have chosen to interrogate me and Daphne Theodore separately, you must be aware that our testimonies can perfectly corroborate each other.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110153/1B935FCA"
        },
        [11015314] = {
          Camera = "435.769226,121.471558,121.855469,0.000029,-17.19808,-165.965164,20.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你本來就受了不輕的傷，又挨了刑訊，還能硬撐著不改口，勇氣可嘉。",
          DialogueId = 11015314,
          Duration = 3,
          FinalCamera = "435.769226,121.471558,108.164062,0.000029,-17.19808,-165.96492,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B935FF4",
          NextDialogue = 11019005,
          SpeakNpcId = 110039,
          Subtitle = "Despite suffering grievous wounds, you have endured intense interrogation without changing your testimonies. Admirable, I must say.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_Start"
          },
