        [11016502] = {
          Camera = "43.549805,139.308594,128.25798,0.001613,-1.609104,-101.194138,36.903526,100000.0,false,Manual,22.0",
          ContentTC = "……怎麽突然醒了？我正問到最關鍵的部分！",
          DialogueId = 11016502,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "52.8125,137.478516,128.257767,0.001613,-1.209135,-100.994232,36.903526,100000.0,false,Manual,22.0",
          GUID = "1B9422DC",
          LookAt = {
            [1] = "110022:n(110039)"
          },
          NextDialogue = 11016503,
          SpeakNpcId = 110039,
          Subtitle = "...Why did you wake up? My questioning had just reached a pivotal point!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422DC"
        },
        [11016503] = {
          Camera = "67.43457,-649.426758,129.53125,0.001605,-4.809197,104.412491,36.90353,100000.0,false,Manual,22.0",
          ContentTC = "{性别:沒關系，典獄長大人。我還記得我在夢中對你說了什麽。|沒關系，典獄長大人。我還記得我在夢中對你說了什麽。但這件事涉及機密，請你一個人留下來。}",
          DialogueId = 11016503,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942306",
          NextDialogue = 11016504,
          Scripts = "SitOrStand{ActorId{110022},State{\"Sit\"}}",
          SpeakNpcId = 110022,
          Subtitle = "It's alright, ma'am. I remember what I told you in my dreams.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942306"
        },
        [11016504] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,100000.0,false,Manual,22.0",
          ContentTC = "我會將那天的真相原原本本地告訴你，也希望你聽過之後，能憑借你心中的那份「正義」做出選擇。",
          DialogueId = 11016504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942330",
          NextDialogue = 11016505,
          SpeakNpcId = 110022,
          Subtitle = "I'll tell you exactly what happened that day. Once you've heard the truth, I hope the justice within your heart will guide your decision.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942330"
        },
        [11016505] = {
          Camera = "32.214844,139.163086,128.258286,0.001612,-2.00912,-97.193909,36.903526,100000.0,false,Manual,22.0",
          ContentTC = "你說吧。",
          DialogueId = 11016505,
          GUID = "1B94235A",
          NextDialogue = 11016506,
          SpeakNpcId = 110039,
          Subtitle = "Go ahead.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110165/1B94235A"
        },
        [11016506] = {
          Camera = "-1.37793,-810.395508,591.001038,0.001542,-46.808487,89.804596,16.538609,100000.0,false,Manual,22.0",
          ContentTC = "那天……",
          DialogueId = 11016506,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-0.708984,-729.607422,508.35968,0.001516,-44.60828,88.804398,16.538609,100000.0,false,Manual,22.0",
          GUID = "1B942384",
          NextDialogue = 11016601,
          SpeakNpcId = 110022,
          Subtitle = "On that day...",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B942384"
        },
        [11016601] = {
          ContentTC = "讓我們好好談一談吧。",
          DialogueId = 11016601,
          GUID = "1B94331A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016601.T_Story_Recall_11016601‘",
          NextDialogue = 11016602,
          Scripts = [[
PARA{
PlayNormalSound{EventPath{"event:/sfx/common/story/01/flashing"},PlayAs2D{true}},
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"},RelatedRegionId{102104}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We need to have a *serious* discussion about this.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94331A"
        },
        [11016602] = {
          ContentTC = "我長話短說。我們沒有多少時間了，如果接下來還是聯絡不上外面，我就用這把槍向你射擊，而你要做的是——裝死。",
          DialogueId = 11016602,
          GUID = "1B943344",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016603,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll make this short. Later, I'll shoot you with this gun, and you'll have to play dead.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943344"
        },
        [11016603] = {
          ContentTC = "為了把戲做足，我會打得更真一點。雖然不是要害，但可能會很疼。你一定要忍住，別出聲。",
          DialogueId = 11016603,
          GUID = "1B94336E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016602.T_Story_Recall_11016602'",
          NextDialogue = 11016604,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To make it convincing enough, the shot will have to hit. It will miss your vitals but will really hurt. You must endure the pain silently.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94336E"
        },
        [11016604] = {
          ContentTC = "您要做什麽？",
          DialogueId = 11016604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943398",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016604.T_Story_Recall_11016604'",
          NextDialogue = 11016605,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "What are you going to do?",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943398"
        },
        [11016605] = {
          ContentTC = "我們被困在這道門裡，和外面的通訊全被切斷了。富爾維斯就在路上……算算時間，這會兒他應該已經把持了整座要塞。",
          DialogueId = 11016605,
          GUID = "1B9433C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016606,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "We're trapped in here, with all contact to the outside world cut off. Fulvis is already on his way. We are running out of time.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433C2"
        },
        [11016606] = {
          ContentTC = "死人才不會辯解，富爾維斯一定會要我的命。你和我一起行動，又目睹了他構陷的經過，他想必也不會讓你活著回去。",
          DialogueId = 11016606,
          GUID = "1B9433EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016605.T_Story_Recall_11016605'",
          NextDialogue = 11016607,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Only the dead keep silent forever. Fulvis will definitely kill me. We're both on this mission, and you've seen his fabricated evidence, so he surely won't spare you either.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9433EC"
        },
        [11016607] = {
          ContentTC = "…………！！",
          DialogueId = 11016607,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943416",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016607.T_Story_Recall_11016607'",
          NextDialogue = 11016608,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943416"
        },
        [11016608] = {
          ContentTC = "沒關系，有我呢。",
          DialogueId = 11016608,
          GUID = "1B943440",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016609,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "It's okay, I got you.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943440"
        },
        [11016609] = {
          ContentTC = "……如果我「殺了你」，假裝內訌向他投誠，他就有可能放鬆警惕，放過你……這是能讓你活下去的唯一方式了。",
          DialogueId = 11016609,
          GUID = "1B94346A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016608.T_Story_Recall_11016608'",
          NextDialogue = 11016610,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...If I \"kill\" you and feign allegiance to him, it'll lower his guard, allowing you to go unnoticed... It's the only way to ensure your survival.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94346A"
        },
        [11016610] = {
          ContentTC = "不……老師，等他們打開門，我們就一起殺出去！",
          DialogueId = 11016610,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943494",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016610.T_Story_Recall_11016610'",
          NextDialogue = 11016622,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "No, Sir Avar... Let's just fight our way out... There's got to be a way out!",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943494"
        },
        [11016612] = {
          ContentTC = "等會兒我會試著先和富爾維斯談判。當然，多半是談不攏的，所以別抱希望。我去和他談判，只是為了一個重要的東西——",
          DialogueId = 11016612,
          GUID = "1B9434E8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016613,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'll try to negotiate with Fulvis, though I believe it's going to fail in the end, so don't get your hopes up. The negotiation is for a more important purpose—",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9434E8"
        },
        [11016613] = {
          ContentTC = "「證據」。",
          DialogueId = 11016613,
          Duration = 3,
          GUID = "1B943512",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016613.T_Story_Recall_11016613'",
          NextDialogue = 11016614,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "To collect evidence.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943512"
        },
        [11016614] = {
          ContentTC = "這是錄音設備，你貼身帶著。它會成為你日後扳倒富爾維斯的鐵證。",
          DialogueId = 11016614,
          GUID = "1B94353C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016615,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Take this recording device. It'll provide the evidence needed to expose and destroy Fulvis.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94353C"
        },
        [11016615] = {
          ContentTC = "絕不能讓士兵們冤屈的哭號，永遠在龍莎要塞上空徘徊。",
          DialogueId = 11016615,
          GUID = "1B943566",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016614.T_Story_Recall_11016614'",
          NextDialogue = 11016616,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Without it, all you have is your word, which happens to be the most unconvincing evidence. The cries of our fallen comrades will be lost to the winds of Lonza Fortress.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD42"
        },
        [11016616] = {
          ContentTC = "……老師……",
          DialogueId = 11016616,
          Duration = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943590",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016616.T_Story_Recall_11016616'",
          NextDialogue = 11016617,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          Subtitle = "...Sir Avar...",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943590"
        },
        [11016617] = {
          ContentTC = "別苦著臉，笑一個！戰士哪怕面對千萬發炮彈，也要笑著一步步向前啊。",
          DialogueId = 11016617,
          GUID = "1B9435BA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016617.T_Story_Recall_11016617'",
          NextDialogue = 11016618,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "Why the long face? Cheer up, kid! A true soldier laughs at adversity.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B9435BA"
        }
      }
    end
  },
  {
