            [2] = "110040:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B946452"
        },
        [11016902] = {
          Camera = "-208.583008,316.085938,130.757812,0.000093,-1.996942,-93.205887,35.000008,100000.0,false,Manual,22.0",
          ContentTC = "…………？！",
          DialogueId = 11016902,
          Duration = 2,
          FacialId = {
            [1] = "110041:Angry01"
          },
          GUID = "1B94647C",
          NextDialogue = 11016903,
          Scripts = [[
