        [11017112] = {
          Camera = "34.15918,-378.791016,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          ContentTC = "還有一件事……",
          DialogueId = 11017112,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "56.49707,-391.176758,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          GUID = "1B94871B",
          NextDialogue = 11017114,
          SpeakNpcId = 110022,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871B"
        },
        [11017113] = {
          Camera = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0",
          ContentTC = "你短期可能回不了軍團了。你的嫌疑並未真的洗清，現在回軍團只怕身份會尷尬。",
          DialogueId = 11017113,
          Duration = 3,
          GUID = "1B94871A",
          NextDialogue = 11019115,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Think_End"},Duration{3}},
PlayFacial{ActorId{110022},FacialId{"Think01"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "And staying away from the Legion might be wise for now. The stigma of a criminal charge lingers. Going back to the Legion at this point could be awkward.",
          TalkActionId = {
            [1] = "110018:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871A"
        },
        [11017114] = {
          ContentTC = "富爾維斯的副官法露茜。我認為她的失蹤沒那麼簡單——她是這個案子真相的關鍵。如果可以，我想拜托你幫忙調查她的下落，無論生死。",
          DialogueId = 11017114,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94871C",
          NextDialogue = 11017115,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"346.420898,18.442383,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"348.020508,22.321289,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{8}}
},
SEQ{
