          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7A8",
          SpeakNpcId = 110022,
          Subtitle = "(The light is on. Looks like Sir Avar has made it on his side.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7A8"
        },
        [11017605] = {
          ContentTC = "<W>警告：月髓艙負荷過大，已超載50%。請立即停止髓動輪設備使用，不得擅自撤離。</>",
          DialogueId = 11017605,
          GUID = "1B94D7D2",
          NextDialogue = 11017606,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank is overloaded by 50%. Please shut down the Phoxynamo Wheels immediately; unauthorized departure is not permitted.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7D2"
        },
        [11017606] = {
          ContentTC = "（……要盡快了。）",
          DialogueId = 11017606,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
