          VoiceName = "voice/$Locale$/story/1200/120017/1E0B92B0"
        },
        [12001785] = {
          Content = "皎皎气呼呼地跑走了。",
          DialogueId = 12001785,
          GUID = "1E0B8AD1"
        },
        [12001801] = {
          Camera = "26.581055,-95.871094,153.29248,0.000088,-8.170654,-51.38456,12.0,60.0,false,Manual,10.0",
          ContentTC = "好啦，現在可以隨意討論了。不過，注意控製表情，那些士兵還在後頭盡職盡責地跟著走。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001801,
          FinalCamera = "1.03418,-98.566895,152.582031,0.000092,-8.970668,-40.585316,12.0,100.0,false,Manual,10.0",
          GUID = "1E0B957A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B957A",
          bNotRecall = 1
        },
        [12001802] = {
          ContentTC = "呵呵，那是我僱用的狩月人。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001802,
          GUID = "1E0B95A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001803,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95A4"
        },
        [12001803] = {
          ContentTC = "只要一份不算豐厚的報酬，就有人願意為此鋌而走險。而這些錢，甚至買不起財務大臣郊外莊園的一隻獵犬。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001803,
          GUID = "1E0B95CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001804,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95CE"
        },
        [12001804] = {
          ContentTC = "但也多虧於此，我們才能化解今晚的危機。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001804,
          GUID = "1E0B95F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95F8"
        },
        [12001805] = {
          ContentTC = "想聽一件有趣的事情嗎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001805,
          GUID = "1E0B9622",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001806,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9622"
        },
        [12001806] = {
          ContentTC = "《海伯利亞早報》是一份在帝國全境販售的報紙。而海伯利亞所有主要城市的中心廣場上……又恰好都有一座紅色電話亭。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001806,
          GUID = "1E0B964C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001807,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B964C"
        },
        [12001807] = {
          ContentTC = "早上卡蜜拉和我轉述了報紙的前因後果。了解這件事後，我留了一份心，多打了幾個電報。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001807,
          GUID = "1E0B9676",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001808,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9676"
        },
        [12001808] = {
          ContentTC = "可以告訴你一個好消息：今夜，所有城市的電話亭中都站著一位白髮女子，等待著不會到來的「故人」。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001808,
          GUID = "1E0B96A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001809,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96A0"
        },
        [12001809] = {
          ContentTC = "這為什麼是好消息哇？白有點聽不懂……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001809,
          GUID = "1E0B96CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001810,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96CA"
        },
        [12001810] = {
          ContentTC = "我想，止流掌櫃的意思是，他們不確定我具體的位置，甚至不確信我是否還活著，所以大規模灑下誘餌，試圖用這種方式試圖誘我出來……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001810,
          GUID = "1E0B96F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001811,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96F4"
        },
        [12001811] = {
          ContentTC = "答對了，真聰明。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001811,
          GUID = "1E0B971E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001812,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B971E"
        },
        [12001812] = {
          ContentTC = "（知道我的存在，還處心積慮布下這場局的軍團人士，究竟是誰……？）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001812,
          GUID = "1E0B9748",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9748"
        },
        [12001813] = {
          ContentTC = "按目前的形勢，直到飛艇起飛之前，恐怕你都無法下車。抱歉，看來要連累你和我走一趟華胥了。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001813,
          GUID = "1E0B9772",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001814,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9772"
        },
        [12001814] = {
          ContentTC = "止流掌櫃，您幾次為我解圍，我簡直不知要如何報答您。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001814,
          GUID = "1E0B979C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001815,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B979C"
        },
        [12001815] = {
          ContentTC = "嗯……報答嗎？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001815,
          GUID = "1E0B97C6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001816,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97C6"
        },
        [12001816] = {
          ContentTC = "我恰好有樣活計正缺人手。從華胥返回海伯利亞的飛艇會在七日後啟程，這期間，你若是不介意，倒是可以助我一臂之力。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001816,
          GUID = "1E0B97F0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001817,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97F0"
        },
        [12001817] = {
          ContentTC = "怎麼樣？考慮一下吧，聰明的小朋友。報酬自然是不會少了你們的。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001817,
          GUID = "1E0B981A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001818,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B981A"
        },
        [12001818] = {
          ContentTC = "（果然……這一切並非巧合。）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001818,
          GUID = "1E0B9844",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 12001819,
            [2] = 12001820
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9844"
        },
        [12001819] = {
          ContentTC = "上了這輛車，恐怕我也沒有拒絕的機會了吧。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001819,
          GUID = "1E0B986E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          ImprPlusId = 1006,
          NextDialogue = 12001821,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B986E"
        },
        [12001820] = {
          ContentTC = "您幫了我好幾次，我很樂意報答您。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001820,
          GUID = "1E0B9898",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          ImprPlusId = 1007,
          NextDialogue = 12001821,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9898"
        },
        [12001821] = {
          ContentTC = "能去到很遠很遠的國家，品嚐沒見過的好吃食物，還能賺到一大筆報酬……小僕從，聽起來是一次很不錯的大冒險耶！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001821,
          GUID = "1E0B98C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001822,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98C2"
        },
        [12001822] = {
          ContentTC = "對了，在出發之前……我可否再拜託您一件事？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001822,
          GUID = "1E0B98EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001823,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98EC"
        },
        [12001823] = {
          ContentTC = "無須擔心。在別的城市中，我也僱傭了些臨時工。有了這些四處咬鉤的魚兒，海伯利亞士兵今晚的行動，大約是要無功而返了——他們不會知道你在冰湖城。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001823,
          GUID = "1E0B9916",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001824,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9916"
        },
        [12001824] = {
          ContentTC = "（連這個都預判到了嗎……這位來自<H>華胥</>的女士，究竟想要委託我做什麼……）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001824,
          GUID = "1E0B9940",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001825,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9940"
        },
        [12001825] = {
          ContentTC = "（不過事已至此，也沒有其他選擇了。只是七天的話，時間還算充裕……）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001825,
          GUID = "1E0B996A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001826,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B996A"
        },
        [12001826] = {
          ContentTC = "好！這個委託，我們就接下了！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001826,
          GUID = "1E0B9994",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9994"
        },
