        },
        [12004003] = {
          Content = "B",
          DialogueId = 12004003,
          GUID = "1E0CFEBE",
          SpeakNpcId = 200002
        },
        [12004101] = {
          ContentTC = "……哇，好多人哦。大家都是來看劇的嗎？",
          DialogueId = 12004101,
          GUID = "1E0AE102",
          NextDialogue = 12004102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE102"
        },
        [12004102] = {
          ContentTC = "他們好像在聊一些很有意思的事情，小僕從，我們去聽聽看把。",
          DialogueId = 12004102,
          GUID = "1E0D0EFC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120041/1E0D0EFC"
        },
        [12004201] = {
          ContentTC = "止流姐姐，你去水仙平原，莫非是要見什麼人？",
          DialogueId = 12004201,
          GUID = "1E0D1F3A",
          NextDialogue = 12004202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F3A"
        },
        [12004202] = {
          ContentTC = "讓白猜猜……該不會是以為金色大波浪、說起話來兇巴巴的老闆娘吧！",
          DialogueId = 12004202,
          GUID = "1E0D1F64",
          NextDialogue = 12004203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F64"
        },
        [12004203] = {
          ContentTC = "呵呵，這都被你猜中了。",
          DialogueId = 12004203,
          GUID = "1E0D1F8E",
          NextDialogue = 12004204,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F8E"
        },
        [12004204] = {
          ContentTC = "魔王大人當然是料事如神啦！",
          DialogueId = 12004204,
          GUID = "1E0D1FB8",
          NextDialogue = 12004205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FB8"
        },
        [12004205] = {
          ContentTC = "啊。不過，剛剛的話，可千萬別對卡蜜拉說哦……不然今天的零花錢就又要被扣光了。",
          DialogueId = 12004205,
          GUID = "1E0D1FE2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FE2"
        },
        [12004206] = {
          ContentTC = "我們到啦——",
          DialogueId = 12004206,
          GUID = "1E0D200C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D200C"
        },
        [12004301] = {
          Content = "皎皎气呼呼地跑走了。",
          DialogueId = 12004301,
          Duration = 2,
          GUID = "1E0D2FA2",
          VoiceName = "voice/$Locale$/story/1200/120043/1E0D2FA2"
        },
        [12004401] = {
          ContentTC = "那邊的機器奇奇怪怪的……唔，總覺得繞開它們比較好！",
          DialogueId = 12004401,
          GUID = "1E0D400A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D400A"
        },
        [12004402] = {
          ContentTC = "它轉過去啦，就是現在——",
          DialogueId = 12004402,
          GUID = "1E0D4034",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D4034"
        },
        [12004501] = {
          ContentTC = "<W>發現追捕目標，發現追捕目標。</>",
          DialogueId = 12004501,
          GUID = "1E0D5072",
          NextDialogue = 12004502,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D5072"
        },
        [12004502] = {
          ContentTC = "哇啊……我們的行蹤好像暴露了！",
          DialogueId = 12004502,
          GUID = "1E0D509C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D509C"
        },
        [12004503] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 12004503,
          GUID = "1E0D509D",
          SpeakNpcId = 200002
        },
        [12004504] = {
          Content = "被动失败",
          DialogueId = 12004504,
          GUID = "1E0D509E",
          SpeakNpcId = 200002
        },
        [12030001] = {
          ContentTC = "那是不久之前，發生在冰湖城的一段故事——",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          ContentTC = "當一隻小夜鶯，決定勇敢地飛出它溫暖的巢穴。",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
