        [12033501] = {
          ContentTC = "這麼找效率太低了……卡珊德拉，你能猜到塞維歐可能會去哪裡嗎？或者他為什麼要出城？",
          DialogueId = 12033501,
          GUID = "1E1FE642",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033502,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE642"
        },
        [12033502] = {
          ContentTC = "唔……說不定，他是去找蝴蝶了？前幾天上課的時候，老師偶然提到淚湖附近棲息著蝴蝶，他追著問了好久……",
          DialogueId = 12033502,
          GUID = "1E1FE66C",
          NextDialogue = 12033503,
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE66C"
        },
        [12033503] = {
          ContentTC = "他到底為什麼這麼喜歡蝴蝶？是因為什麼童話故事嗎？",
          DialogueId = 12033503,
          GUID = "1E1FE696",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033504,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE696"
        },
        [12033504] = {
          ContentTC = "是因為發生在他小時候的一件事，他對我說過好多次——有一天他的爸爸媽媽忽然都不見了，他怎麼找也找不到，害怕得哭了起來。",
          DialogueId = 12033504,
          GUID = "1E1FE6C0",
          NextDialogue = 12033505,
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6C0"
        },
        [12033505] = {
          ContentTC = "蝴蝶精靈就在這個時候出現了，它們和他一起玩耍，陪著他等待，最後終於等到了他的爸爸媽媽回到家。",
          DialogueId = 12033505,
          GUID = "1E1FE6EA",
          NextDialogue = 12033506,
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6EA"
        },
        [12033506] = {
          ContentTC = "所以，我想，也許他是覺得，找到了蝴蝶精靈，他的爸爸媽媽就會回來吧……",
          DialogueId = 12033506,
          GUID = "1E1FE714",
          NextDialogue = 12033507,
          SpeakNpcId = 211012,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE714"
        },
        [12033507] = {
