          VoiceName = "voice/$Locale$/story/2001/200005/3211B91E"
        },
        [20000531] = {
          Camera = "-7.611328,-33.099121,102.976074,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          ContentTC = "（沒錯，身為皎皎的白就是一個熱心腸的孩子。更何況，對於兩個一無所有的人，一名鐵匠又能圖謀什麼呢？）",
          DialogueId = 20000531,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-15.199463,-23.983398,104.64917,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          GUID = "3211B948",
          NextDialogue = 20000532,
          Subtitle = "(She was right. You could see that trait in Snow. Besides, what could she get from you? You have nothing to offer.)",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B948"
        },
        [20000532] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯，我想多了。那我們一起回去吧。",
          DialogueId = 20000532,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "3211B972",
          NextDialogue = 20000533,
          SpeakNpcId = 100001,
          Subtitle = "Yeah, you're right. Let's head back together then.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B972"
        },
        [20000533] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "看樣子年輕人這是答應啦。好，好！快帶老朽去你的住處吧！",
          DialogueId = 20000533,
          Duration = 3,
          FinalCamera = "-2421.345459,1084.854004,250.907959,0.000098,-4.001944,-26.573236,60.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B99C",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "So you'll have me? Excellent! Then take me to where you live.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B99C"
        },
        [20000601] = {
