        [20001401] = {
          ContentTC = "對了對了，我還有幾件事要問你。",
          DialogueId = 20001401,
          GUID = "321247DA",
          NextDialogue = 20001402,
          SpeakNpcId = 200027,
          VoiceName = "voice/$Locale$/story/2001/200014/321247DA"
        },
        [20001402] = {
          ContentTC = "你有沒有親自到天之樹腳下去過呀，它是不是真的有傳說中那——麽大，大到遮天蔽日？從下往上看，會不會像……滿天都是水晶？",
          DialogueId = 20001402,
          ExStoryInfo = "Player",
          GUID = "32124804",
          NextDialogue = 20001403,
          SpeakNpcId = 200027,
          VoiceName = "voice/$Locale$/story/2001/200014/32124804"
        },
        [20001403] = {
          ContentTC = "還有還有……海邊的沙子是不是都是軟綿綿的，踩上去像面粉一樣，一點兒也不硌腳？",
          DialogueId = 20001403,
          GUID = "3212482E",
          NextDialogue = 20001404,
          SpeakNpcId = 200027,
          VoiceName = "voice/$Locale$/story/2001/200014/3212482E"
        },
        [20001404] = {
          ContentTC = "問題可能會有點多！是幫大家問的……嘿嘿，不要嫌我煩哦！",
          DialogueId = 20001404,
          GUID = "32124858",
          SpeakNpcId = 200027,
          VoiceName = "voice/$Locale$/story/2001/200014/32124858"
        },
        [20001501] = {
          ContentTC = "嗯……有這些應該夠了，回去交給賽琪吧。",
          DialogueId = 20001501,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "32125842",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200015/32125842"
        },
        [20001601] = {
          Camera = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯等。",
          DialogueId = 20001601,
          GUID = "321268AA",
          NextDialogue = 20001602
        },
        [20001602] = {
          Camera = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "等不耐烦了。",
          DialogueId = 20001602,
          FinalCamera = "1700.51709,233.67041,212.238281,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "321268D4",
          NextDialogue = 20001603,
          ToFinalCameraBlendTime = 4
        },
        [20001603] = {
          Content = "赛琪怎么还没出来，我们去瞅瞅吧。",
