          NextDialogue = 20001802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200018/3212897A"
        },
        [20001802] = {
          ContentTC = "白，跟在我們後面，趁著風小一點的時候一起向前。",
          DialogueId = 20001802,
          ExStoryInfo = "Player",
          GUID = "321289A4",
          NextDialogue = 20001803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200018/321289A4"
        },
        [20001803] = {
          ContentTC = "風太大的時候也可以躲在石頭後面，別著急。",
          DialogueId = 20001803,
          GUID = "321289CE",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200018/321289CE"
        },
        [20001901] = {
          Camera = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "遠處的冰湖上刮起了風暴，賽琪應該就在那個方向……",
          DialogueId = 20001901,
          GUID = "321299E2"
        },
        [20002001] = {
          ContentTC = "……蝴蝶？冬天怎麼會有蝴蝶？",
          DialogueId = 20002001,
          ExStoryInfo = "Player",
          GUID = "3212AA4A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA4A"
        },
        [20002002] = {
          ContentTC = "就像是……在為我們引路一樣……",
          DialogueId = 20002002,
          ExStoryInfo = "Player",
          GUID = "3212AA74",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA74"
        },
        [20002101] = {
          ContentTC = "這些穢獸都半死不活的，很可能是和賽琪交過手。",
          DialogueId = 20002101,
          GUID = "3212BAB2",
          NextDialogue = 20002102,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BAB2"
        },
        [20002102] = {
          ContentTC = "看來只要沿著它們的反方向，就能找到賽琪了……",
          DialogueId = 20002102,
          GUID = "3212BADC",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BADC"
        },
        [20002201] = {
          Content = "兄弟，你还好吗。",
          DialogueId = 20002201,
          ExStoryInfo = "Player",
          GUID = "3212CB1A",
          NextDialogue = 20002202,
          SpeakNpcId = 100001
        },
        [20002202] = {
          Content = "不太好。",
          DialogueId = 20002202,
          GUID = "3212CB44",
          NextDialogue = 20002203
        },
        [20002203] = {
          Content = "外面情况怎么样？",
          DialogueId = 20002203,
          GUID = "3212CB6E",
          NextDialogue = 20002204
        },
        [20002204] = {
          Content = "刮了好大的风，秽兽的行为也很反常。",
          DialogueId = 20002204,
          GUID = "3212CB98"
        },
        [20002301] = {
          ContentTC = "（已經失去理智的賽琪正在與穢蝕對抗……應該為她做些什麽……）",
          DialogueId = 20002301,
          DisableMouth = 1,
          GUID = "3212DB82"
        },
        [20002401] = {
          ContentTC = "……賽琪好像往城外去了。",
          DialogueId = 20002401,
          GUID = "3212EBEA",
          NextDialogue = 20002402,
          SpeakNpcId = 700049
        },
        [20002402] = {
          ContentTC = "應該是因為城外人比較少吧，在還有最後一點理智的時候，儘量去人少的地方去。",
          DialogueId = 20002402,
          GUID = "3212EC14",
          SpeakNpcId = 700049
        },
        [20002501] = {
          ContentTC = "你們……要去找賽琪嗎？",
          DialogueId = 20002501,
          GUID = "3212FC52",
          NextDialogue = 20002502,
          SpeakNpcId = 200045
        },
        [20002502] = {
          ContentTC = "找到她的話，不要猶豫，結束她的痛苦吧，我想她也希望你們這麼做……",
          DialogueId = 20002502,
          GUID = "3212FC7C",
          SpeakNpcId = 200045
        },
        [20002601] = {
          ContentTC = "剛剛那個大姐姐怎麼跑那麼快？",
          DialogueId = 20002601,
          GUID = "32130CBA",
          NextDialogue = 20002602,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc1",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CBA"
        },
        [20002602] = {
          ContentTC = "別問了，快走，快到城裡去，那是穢蝕者！",
          DialogueId = 20002602,
          GUID = "32130CE4",
          NextDialogue = 20002603,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc2",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CE4"
        },
        [20002603] = {
          ContentTC = "別……別慌……已經有人去找衛戍部隊了！",
          DialogueId = 20002603,
          GUID = "32130D0E",
          NextDialogue = 20002604,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc3",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D0E"
        },
        [20002604] = {
          ContentTC = "你們不要想趁機溜進城裡，通行證，出示通行證！",
          DialogueId = 20002604,
          GUID = "32130D38",
          NextDialogue = 20002605,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc4",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D38"
        },
        [20002605] = {
          ContentTC = "求求你們讓我們進去吧，通行證真的只是不小心弄丟了！",
          DialogueId = 20002605,
          GUID = "32130D62",
          NextDialogue = 20002606,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc5",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D62"
        },
        [20002606] = {
          ContentTC = "都什麼時候了還通行證，反正在外面也是死，不如直接沖進去！",
          DialogueId = 20002606,
          GUID = "32130D8C",
          NextDialogue = 20002607,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc6",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D8C"
        },
        [20002607] = {
          ContentTC = "停，停，你們再過來我就開槍了！",
          DialogueId = 20002607,
          GUID = "32130DB6",
          NextDialogue = 20002608,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc7",
          VoiceName = "voice/$Locale$/story/2001/200026/32130DB6"
        },
        [20002608] = {
          ContentTC = "開啊！開槍把穢蝕者引過來我們一起死！",
          DialogueId = 20002608,
          GUID = "32130DE0",
          NextDialogue = 20002609,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc8",
          VoiceName = "voice/$Locale$/story/2001/200026/32130DE0"
        },
        [20002609] = {
          ContentTC = "你……算你狠。行吧，先進來，等衛戍部隊處理掉穢蝕者再說。",
          DialogueId = 20002609,
          GUID = "32130E0A",
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc9",
          VoiceName = "voice/$Locale$/story/2001/200026/32130E0A"
        },
        [20002701] = {
          ContentTC = "好大的風……直接跳下去會被吹飛的。",
          DialogueId = 20002701,
          GUID = "32131D22",
          NextDialogue = 20002702,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200027/32131D22"
        },
        [20002702] = {
          ContentTC = "那邊，我們坐升降機下去。",
          DialogueId = 20002702,
          GUID = "32131D4C",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200027/32131D4C"
        },
        [20002801] = {
          ContentTC = "沒事的，我們知道了賽琪去了哪裡，跟上去就是。",
          DialogueId = 20002801,
          Duration = 3,
          GUID = "32132D8A",
          NextDialogue = 20002802,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200028/32132D8A"
        },
        [20002802] = {
          ContentTC = "嗯，沒錯，只要找到賽琪，就一定會有辦法的！",
          DialogueId = 20002802,
          Duration = 3,
          GUID = "32132DB4",
          NextDialogue = 20002803,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200028/32132DB4"
        },
        [20002803] = {
          ContentTC = "謝謝你們……",
          DialogueId = 20002803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "32132DDE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200028/32132DDE"
        },
        [20002901] = {
