          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          ContentTC = "啊，榛子聞到了，在那裡！",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          ContentTC = "是這裡……但沒有魔靈，只有……",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          ContentTC = "這是他們陷阱的痕跡，好可惡，他們應該已經走了。",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          ContentTC = "那接下來我們去人少一點的地方，氣味會明顯一些。",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          ContentTC = "這裡這裡，{性别:大哥哥|大姐姐}別著急，慢點一點走，別滑倒啦。",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          ContentTC = "呃……這裡也是一樣，有人佈設過陷阱。",
