        [20006015] = {
          ContentTC = "啪嘰——",
          DialogueId = 20006015,
          GUID = "32153CD6",
          VoiceName = "voice/$Locale$/story/2001/200060/32153CD6"
        },
        [20006016] = {
          Camera = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
          ContentTC = "欸？怎麼又鑽到陷阱裡去了？這隻魔靈，是不是太害怕我們，所以把陷阱當作是安全的地方了？",
          DialogueId = 20006016,
          FinalCamera = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
          GUID = "32153D00",
          NextDialogue = 20006017,
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D00"
        },
        [20006017] = {
          Camera = "-734.274048,-630.614258,292.918457,0.000099,-3.391544,164.774017,35.000008,1674.542114,false,Manual,8.0",
          ContentTC = "唔，不應該呀，我們明明救過它，並且也沒有表現出敵意。魔靈們雖然不會說話，但是是能分清楚誰對它好，誰對它壞的。",
          DialogueId = 20006017,
          FacialId = {
            [1] = "200074:Sad01"
          },
          FinalCamera = "-798.274292,-613.4375,289.223145,0.000099,-3.191556,164.973953,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153D2A",
          NextDialogue = 20006018,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Think_Start",
            [2] = "200002:SpecialConfident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D2A"
        },
        [20006018] = {
          Camera = "-497.108154,-708.697266,244.088379,0.000021,1.403228,153.786591,35.0,174.116943,false,Manual,12.0",
          ContentTC = "我想想……榛子有沒有像這樣，做的事我一開始完全無法理解的時候……",
          DialogueId = 20006018,
          FinalCamera = "-522.647217,-696.478516,231.824707,0.000021,7.603175,151.787338,35.0,174.116943,false,Manual,12.0",
