          NextDialogue = 20006019,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D54"
        },
        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,174.116943,false,Manual,12.0",
          ContentTC = "一次非得去看起來光禿禿的山谷裡，後來才知道是因為它聞到了山谷深處有許多漿果……一次是停在花店門口不走，等我買了花，它就開心地一口吃掉……",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,174.116943,false,Manual,12.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentTC = "還有一次，是它丟下我，拼命往山坡上跑，是因為附近的草叢裡有蛇……它想把蛇引開……",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
        [20006021] = {
          Camera = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
          ContentTC = "嗯……都是因為有很在意的事情……魔靈會在意什麼呢？食物……還有伙伴！",
          DialogueId = 20006021,
          FinalCamera = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
