          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002108] = {
          Camera = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哈哈，原來我也有這麼口無遮攔的時候……現在想想，那時候我好像也沒有那麼生氣，因為再怎麼說，我的身邊還有貝蕾在。",
          DialogueId = 51002108,
          GUID = "7FADAC8B",
