          SpeakNpcId = 100001
        },
        [51002109] = {
          Camera = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "後來……好像是和好了吧？我記得我們爬到屋頂上……",
          DialogueId = 51002109,
          GUID = "7FADAC8C",
          NextDialogue = 51002110,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Sigh_Start"},Duration{3}},
PlayAnimation{ActorId{100001},AnimationId{"Sigh_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001
        },
        [51002110] = {
          Camera = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊對，就是在這兒，過了幾天他拿著一袋吃的和我道歉。我本來還想罵他來著，但看著那三人份的麵包，最後還是讓饞蟲戰勝了尊嚴。",
          DialogueId = 51002110,
          FinalCamera = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8D",
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 7
        },
        [51002111] = {
          Camera = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯……我們三個就這樣坐在屋頂默默地吃著又硬又焦的麵包，看著日頭漸斜，大人們載著打來的魚回村。",
          DialogueId = 51002111,
          FinalCamera = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8E",
          NextDialogue = 51002112,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002112] = {
          Camera = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "最後那小鬼噎著了，連著打了一串嗝。我們三個一起笑了，那次吵架就這麼過去了。",
          DialogueId = 51002112,
          FinalCamera = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8F",
          NextDialogue = 51002113,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002113] = {
          Camera = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "最後那小鬼噎著了，連著打了一串嗝。我們三個一起笑了，那次吵架就這麼過去了。",
          DialogueId = 51002113,
          FacialId = {
            [1] = "700210:Ahaha02"
          },
          FinalCamera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC90",
          NextDialogue = 51002114,
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002114] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "如果實在什麼都找不到的話，幫我帶點東西回來吧，什麼都行，一片草葉也行。",
          DialogueId = 51002114,
          FacialId = {
            [1] = "700210:Smile02"
          },
          GUID = "7FADAC91",
          NextDialogue = 51002115,
          SpeakNpcId = 700210
        },
        [51002115] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "再給布魯內托帶點特產吧，這個季節的魚我記得都很肥美。",
          DialogueId = 51002115,
          GUID = "7FADAC92",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
          NextDialogue = 51002116,
          SpeakNpcId = 700048
        },
        [51002116] = {
          Camera = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "回去吧，這些應該能夠緩解布魯內托的鄉愁了。",
          DialogueId = 51002116,
          FinalCamera = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC93",
          SpeakNpcId = 700210,
          ToFinalCameraBlendTime = 7
        },
        [51002117] = {
          ContentTC = "孫子透過打架認識，爺爺透過坑騙認識……哈……真是奇怪的緣分……",
          DialogueId = 51002117,
          Duration = 3,
          GUID = "7FADAC94",
          NextDialogue = 51002118,
          SpeakNpcId = 100001
        },
        [51002118] = {
          ContentTC = "孫子透過打架認識，爺爺透過坑騙認識……哈……真是奇怪的緣分……",
          DialogueId = 51002118,
          Duration = 4,
          GUID = "7FADAC95",
          SpeakNpcId = 100001
        },
        [51002201] = {
          ContentTC = "來往的朋友，稍微停一停腳步，給上幾個銅幣，您就能加入冰湖城漁夫互助會，獲得最好最新的——啊！是你……",
          DialogueId = 51002201,
          GUID = "7FADBC9A",
          NextDialogue = 51002202,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you can join the Icelake Fishermen's Mutual Aid Society\nto get the best and latest— Oh! It's you..."
        },
        [51002202] = {
          ContentTC = "這應該是你的東西？",
          DialogueId = 51002202,
          GUID = "7FADBCC4",
          NextDialogue = 51002203,
          SpeakNpcId = 100001,
          Subtitle = "Is this yours?"
        },
        [51002203] = {
          ContentTC = "啊！沒錯，這就是我小時候翻來覆去一直在看的書，那時候就是看著這本書，想離開巴掌大的小島……",
          DialogueId = 51002203,
          GUID = "7FADBCEE",
          NextDialogue = 51002204,
          SpeakNpcId = 700048,
          Subtitle = "Jesus! Yes, this is the book I used to read over and over again when I was a kid. I thought about coming to the land because of it...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002204] = {
          ContentTC = "謝謝，謝謝你，我今天晚上得要好好再翻一遍。不過現在先不說了，唉，掙錢糊口要緊。",
          DialogueId = 51002204,
          GUID = "7FADBD18",
          NextDialogue = 51002205,
          SpeakNpcId = 700048,
          Subtitle = "Thank you. Thank you so much. I need to give it a good read tonight. But for now, *sigh* making a living is more important.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002205] = {
          ContentTC = "再見，不要再騙人了。喔對了，這些魚乾也拿去，淨界島釣上來做的。",
          DialogueId = 51002205,
          GUID = "7FADBD42",
          NextDialogue = 51002206,
          SpeakNpcId = 100001,
          Subtitle = "Take care, and don't be a swindler anymore.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002206] = {
          ContentTC = "這是……謝謝，真的太謝謝你了……",
          DialogueId = 51002206,
          GUID = "7FADBD6C",
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, those who are interested in Icelake Fishermen's Mutual Aid Society can learn more about it. We have decades of fishing experience from veteran fishermen. Fishing is great either serving as a hobby or a job!"
        },
        [51002207] = {
          ContentTC = "冰湖城漁夫互助會，有興趣的朋友瞭解一下，幾十年經驗老漁夫親自指導，作為興趣作為工作都棒極了！",
          DialogueId = 51002207,
          GUID = "7FADBD96",
          NextDialogue = 51002208,
          SpeakNpcId = 700048
        },
        [51002208] = {
          ContentTC = "哎呀，這不是{Nickname}嗎，都是老鄉了，有空我們交流下捕魚的技術？",
          DialogueId = 51002208,
          GUID = "7FADBD97",
          NextDialogue = 51002209,
          SpeakNpcId = 700048
        },
        [51002209] = {
          ContentTC = "下次一定。",
          DialogueId = 51002209,
          GUID = "7FADBDC0",
          SpeakNpcId = 100001
        },
        [51002301] = {
          ContentTC = "年輕人，你有哈默爾·狄金森的消息了嗎？",
          DialogueId = 51002301,
          GUID = "7FADCD02",
          NextOptions = {
            [1] = 510023011
          },
          SpeakNpcId = 700019
        },
        [51002302] = {
          ContentTC = "（是的，格雷姆礦坑的那本無名日記，它的扉頁寫著主人的名字——哈默爾·狄金森。）",
          DialogueId = 51002302,
          GUID = "7FADCD2C",
          NextDialogue = 51002303
        },
        [51002303] = {
          ContentTC = "（如果沒猜錯的話，那只盤踞在礦坑深處的怪物，它的真實身份就是……）",
          DialogueId = 51002303,
          GUID = "7FADCD56",
          NextDialogue = 51002304
        },
        [51002304] = {
          ContentTC = "（從言及那個男人開始，老婦人渾濁的眼睛就有了些光亮，看來哈默爾·狄金森這個名字對她而言並不一般。她在期待著一個答案。）",
          DialogueId = 51002304,
          GUID = "7FADCD80",
          NextOptions = {
            [1] = 510023041,
            [2] = 510023042
          },
          bForbidSkipOptions = true
        },
        [51002305] = {
          ContentTC = "……",
          DialogueId = 51002305,
          GUID = "7FADCDAA",
          NextDialogue = 51002306,
          SpeakNpcId = 700019
        },
        [51002306] = {
          ContentTC = "（老婦人逐字逐句地默念著那本日記。淚水從她滿是皺紋的眼角不斷滾落。）",
          DialogueId = 51002306,
          GUID = "7FADCDD4",
          NextDialogue = 51002307
        },
        [51002307] = {
          ContentTC = "（然後她將日記抱在胸前，像是在擁抱著一位久別重逢的愛人。）",
          DialogueId = 51002307,
          GUID = "7FADCDFE",
          NextDialogue = 51002308
        },
        [51002308] = {
          ContentTC = "……年輕人，謝謝你。謝謝你幫忙找到這個埋藏了四十年的答案。",
          DialogueId = 51002308,
          GUID = "7FADCE28",
          NextDialogue = 51002309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51002309] = {
          ContentTC = "請你去找我的女仆莎莉領取報酬吧。我想一個人待一會兒。",
          DialogueId = 51002309,
          GUID = "7FADCE52",
          NextDialogue = 51002310,
          SpeakNpcId = 700019
        },
        [51002310] = {
          ContentTC = "（老婦人轉過身去，只留下衰老佝僂的背影。）",
          DialogueId = 51002310,
          GUID = "7FADCE7C"
        },
        [51002311] = {
          ContentTC = "……",
          DialogueId = 51002311,
          GUID = "7FADCEA6",
          SpeakNpcId = 700019
        },
        [51002312] = {
          ContentTC = "抱歉,我沒聽過這個名字。如果以後有消息，我會回來找你的。",
          DialogueId = 51002312,
          GUID = "7FADCED0",
          NextDialogue = 51002313,
          SpeakNpcId = 100001
        },
        [51002313] = {
          ContentTC = "好......好，謝謝你，年輕人。",
          DialogueId = 51002313,
          GUID = "7FADCEFA",
          NextDialogue = 51002314,
          SpeakNpcId = 700019
        },
        [51002314] = {
          ContentTC = "我備好了一份薄禮，請你到我家去找我的女仆莎莉吧，就說是希琳夫人讓你來的。",
          DialogueId = 51002314,
          GUID = "7FADCF24",
          NextDialogue = 51002315,
          SpeakNpcId = 700019
        },
        [51002315] = {
          ContentTC = "去吧，願你一路順風......",
          DialogueId = 51002315,
          GUID = "7FADCF4E",
          SpeakNpcId = 700019
        },
        [51002320] = {
          ContentTC = "孩子，你就是那位叫做{nickname}的狩月人吧。希琳夫人讓我將報酬預支給你。",
          DialogueId = 51002320,
          GUID = "7FADD020",
          NextDialogue = 51002321,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002321] = {
          ContentTC = "如果你在哪裡聽說了哈默爾·狄金森的消息，一定要快點跟夫人講。",
          DialogueId = 51002321,
          GUID = "7FADD04A",
          NextDialogue = 51002322,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002322] = {
          ContentTC = "唉！她那身子從去年開始就越來越差，如今恐怕沒有多少日子了。哈默爾的事情，是她的最後的心事……",
          DialogueId = 51002322,
          GUID = "7FADD074",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002401] = {
          ContentTC = "孩子，謝謝你為我和夫人跑前跑後，這是我們的一點心意。",
          DialogueId = 51002401,
          GUID = "7FADDD6A",
          NextDialogue = 51002402,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002402] = {
          ContentTC = "唉！她那身子從去年開始就越來越差，如今恐怕沒有多少日子了。哈默爾的事情，是她的最後一樁心事……",
          DialogueId = 51002402,
          GUID = "7FADDD94",
          NextDialogue = 51002403,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002403] = {
          ContentTC = "雖然不是什麽好消息，但嬸嬸還是要謝謝你！圓了她最後一樁心願。",
          DialogueId = 51002403,
          GUID = "7FADDDBE",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002404] = {
          ContentTC = "唉……到這份上，我們確實不能再瞞著你了。",
          DialogueId = 51002404,
          GUID = "7FADDDE8",
          NextDialogue = 51002405,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002405] = {
          ContentTC = "你可能猜到了，哈默爾是夫人四十年前的心上人。那時夫人……不，應該叫她小姐，還是個熱情活潑的姑娘。哈默爾·狄金森是個和她年齡相仿的礦工，就在她父親管理的格雷姆礦場工作。",
          DialogueId = 51002405,
          GUID = "7FADDE12",
          NextDialogue = 51002406,
          SpeakNpcId = 700020
        },
        [51002406] = {
          ContentTC = "像所有俗套的浪漫故事那樣，他們越是地位懸殊，就越是執拗，非得逆著全世界的意思在一起。",
          DialogueId = 51002406,
          GUID = "7FADDE3C",
          NextDialogue = 51002407,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002407] = {
          ContentTC = "那些故事會告訴你，愛情就像一團火，旁人越想撲滅就越燒得旺。但他們不會告訴你，這團火在決堤的現實面前，是多麽不值一提！",
          DialogueId = 51002407,
          GUID = "7FADDE66",
          NextDialogue = 51002408,
          SpeakNpcId = 700020
        },
        [51002408] = {
          ContentTC = "當這件事傳到當年的老爺——也就是工程煉金院派駐格雷姆礦場的董事耳朵裡的時候，哈默爾得到的不是祝福，而是一頓毒打。",
          DialogueId = 51002408,
          GUID = "7FADDE90",
          NextDialogue = 51002409,
          SpeakNpcId = 700020
        },
        [51002409] = {
          ContentTC = "不只是因為他的身份，更因為老爺已經為小姐安排了一門門當戶對的親事。對方是弗萊格桑行省的貴族——富豪新貴與沒落貴族各取所需的聯姻，沒有比這更合適的婚事了。",
          DialogueId = 51002409,
          GUID = "7FADDEBA",
          NextDialogue = 51002410,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002410] = {
          ContentTC = "但小姐沒有放棄，那時候的她勇敢又果決。她偷偷拜托我轉交哈默爾一封信，約定一個月後，也就是4月26日零點，在銀色和平廣場見面。",
          DialogueId = 51002410,
          GUID = "7FADDEE4",
          NextDialogue = 51002411,
          SpeakNpcId = 700020
        },
        [51002411] = {
          ContentTC = "那天正趕上老爺生日，仆人們都在為宴會忙前忙後。小姐便計劃趁機逃出去，對她來說那是唯一一次逃離的機會。",
          DialogueId = 51002411,
          GUID = "7FADDF0E",
          NextDialogue = 51002412,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002412] = {
          ContentTC = "她下定決心，只要哈默爾來，她就打算和他一起走，無論去哪裡。",
          DialogueId = 51002412,
          GUID = "7FADDF38",
          SpeakNpcId = 700020
        },
        [51002415] = {
          ContentTC = "是。希琳小姐在那裡等到天亮，等來的卻只有氣急敗壞的父親。不久之後，她就像一件貨物那樣，被遠嫁到了弗萊格桑行省。",
          DialogueId = 51002415,
          GUID = "7FADDFB6",
          NextDialogue = 51002416,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002416] = {
          ContentTC = "萬幸！她的丈夫——也就是後來的老爺對她挺和善的，夫人也度過了四十年平靜的時光。她從來不提當年的事情，就像是哈默爾·狄金森從未存在過一樣。",
          DialogueId = 51002416,
          GUID = "7FADDFE0",
          NextDialogue = 51002417,
          SpeakNpcId = 700020
        },
        [51002417] = {
          ContentTC = "一年前老爺去世了，夫人的身體也大不如前。一天，她突然告訴我，她想在人生的最後一段時間回到冰湖城，去找一個她一直未曾得到的答案。那時我才知道，哈默爾這個人，她從來都沒有忘掉，只是變成了一根紮在心裡的刺。",
          DialogueId = 51002417,
          GUID = "7FADE00A",
          NextDialogue = 51002418,
          SpeakNpcId = 700020
        },
        [51002418] = {
          ContentTC = "我們搬來了冰湖城，然而城裡沒有人知道哈默爾的下落。我們找到了幾個還在世的老礦工，但他們回憶了半天，只能想起，最後一次見到哈默爾，已經是四十年前的事了……",
          DialogueId = 51002418,
          GUID = "7FADE034",
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002419] = {
          ContentTC = "唉，不知道夫人有生之年，還能不能了卻最後的心事。",
          DialogueId = 51002419,
          GUID = "7FADE05E",
          NextDialogue = 51002420,
          SpeakNpcId = 700020
        },
        [51002420] = {
          ContentTC = "都是陳年往事……唉，拉著你嘮嘮叨叨了這麼久，看來我也老了啊。",
          DialogueId = 51002420,
          GUID = "7FADE088",
          NextDialogue = 51002421,
          SpeakNpcId = 700020
        },
        [51002421] = {
          ContentTC = "你是狩月人，那肯定挺忙的，嬸嬸就不打擾你啦。",
          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020
        },
        [51002422] = {
          ContentTC = "（她不會得到答案了。）",
          DialogueId = 51002422,
          GUID = "7FADE0DC",
          NextDialogue = 51002423
        },
        [51002423] = {
          ContentTC = "（哈默爾為了希琳而前往礦坑深處，在那裡變成了穢獸，成為了四十年間可怖的傳說，最後被擊殺——這真相對一位時日無多的老婦人來說，實在是太殘酷了。）",
          DialogueId = 51002423,
          GUID = "7FADE106",
          NextDialogue = 51002424
        },
        [51002424] = {
          ContentTC = "（這個殘酷的真相會被永遠埋葬在廢墟深處，而希琳夫人將帶著希望走到生命盡頭。也許這已經是最好的結局了。）",
          DialogueId = 51002424,
          GUID = "7FADE130"
        },
        [51002425] = {
          ContentTC = "……只是萬萬沒想到會是這樣！哈默爾並沒有失約，而是為了和夫人的約定才會去那個礦坑……也不知道這對夫人來說，究竟算是寬慰還是殘忍。",
          DialogueId = 51002425,
          GUID = "7FADE15A",
          NextDialogue = 51002426,
          SpeakNpcId = 700020
        },
        [51002426] = {
          ContentTC = "……現在夫人這樣，我也不知道該怎麽安慰她才好……",
          DialogueId = 51002426,
          GUID = "7FADE184",
          NextDialogue = 51002427,
          SpeakNpcId = 700020
        },
        [51002427] = {
          ContentTC = "真頭疼！只能先去準備晚飯了，至少讓她喝點我煮的濃湯，身體稍微舒服點吧！",
