          NextDialogue = 51002907,
          SpeakNpcId = 700015
        },
        [51002907] = {
          ContentTC = "一個幽靈！！！一個穿門入戶的無聲行者！！！！",
          DialogueId = 51002907,
          GUID = "7FAE306E",
          NextDialogue = 51002908,
          SpeakNpcId = 700015
        },
        [51002908] = {
          ContentTC = "如你所聽，總是有碰上麻煩的人。",
          DialogueId = 51002908,
          GUID = "7FAE3098",
          NextOptions = {
            [1] = 510029081
          },
          SpeakNpcId = 200003
        },
        [51002909] = {
          ContentTC = "巴克先生，因為沾一點酒精就倒，所以平常只點果汁和牛奶。職業嘛……三流的劇作家，一流的不好懂。喏，已經在那裡絮絮叨叨半天了。",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003
        },
        [51002910] = {
          ContentTC = "如你所見，他好像沒辦法明確表達自己的訴求，你要給他翻譯翻譯嗎？",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
          NextOptions = {
