          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51002911] = {
          ContentTC = "別沮喪，整個冰湖城能聽懂他在說什麽的也不超過一個巴掌數。",
          DialogueId = 51002911,
          GUID = "7FAE3116",
          SpeakNpcId = 200003
        },
        [51002912] = {
          ContentTC = "以你的才智，這份工作看來非你莫屬了。",
          DialogueId = 51002912,
          GUID = "7FAE3140",
          SpeakNpcId = 200003
        },
        [51003001] = {
          ContentTC = "（你側耳傾聽劇作家的高談闊論。）",
          DialogueId = 51003001,
          GUID = "7FAE3FDA",
          NextDialogue = 51003002
        },
        [51003002] = {
          ContentTC = "詩人的夜晚總是漫長……劇作家也不例外！我們的筆書寫著人間的脈動，我們的心自然也與潮汐和月亮為伴！",
          DialogueId = 51003002,
          GUID = "7FAE4004",
          NextDialogue = 51003003,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          }
        },
        [51003003] = {
          ContentTC = "拋卻了令人炫目的陽光，拋卻了人間的聲響，拋卻了浮躁的心思，此時才是我與世界促膝長談的時刻！",
          DialogueId = 51003003,
          GUID = "7FAE402E",
          NextOptions = {
            [1] = 510030031,
            [2] = 510030032
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          ContentTC = "啊！要麽是我不自知的怠慢惹惱了掌管靈感的女神，要麽就是睡眠之神在刻意作弄我！否則我怎麽會任由光陰的車輪滾滾而過，卻沒有半分察覺！",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          ContentTC = "我應當用寫滿文辭的紙張去迎接清晨的到來，而不是只留下一個徒有健康的我與空白的稿紙！",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          ContentTC = "在充滿誘惑的睡夢中，我聽到窸窣的足音，它是那麽輕盈，像精靈的旋舞，我聞到飽滿果實的氣味，那上面一定澆著厚厚的蜜糖！",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_Start"
          }
        },
        [51003007] = {
          ContentTC = "或許我曾在夢中迷失，但這聲息與味道引領我回到現實，他們縹緲不定，他們縈繞我身，他們確實存在……",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
