          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          ContentTC = "他們絕不是我的幻覺，但我抓不住痕跡的尾巴，我勘不破這詭秘的行徑，是幽靈？是鬼魅？是幻影？",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          ContentTC = "我那貧瘠的破屋不增不減，他唯獨偷竊了我視為生命的靈感！眼看他就要讓我的夢破碎……",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
            [1] = 510030091,
            [2] = 510030092
          },
          SpeakNpcId = 700015,
          bForbidSkipOptions = true
        },
        [51003010] = {
          ContentTC = "劇作家的夜晚是絕不可以付諸於睡眠的！在座的諸位誰能聽從我的召喚，去為我、去為那即將問世的著作驅散那偷走靈感的竊賊！",
          DialogueId = 51003010,
          GUID = "7FAE4154",
          NextDialogue = 51003011,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_Start"
          }
        },
        [51003011] = {
          ContentTC = "我將給予你榮耀，給予你身為主角的可能，讓我見識你的出色，讓我願意為狩月人作傳吧！",
          DialogueId = 51003011,
          GUID = "7FAE417E",
          NextOptions = {
            [1] = 510030111,
            [2] = 510030112
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51003012] = {
          ContentTC = "雖然沒什麽錢賺，但聽起來很有意思，你想接嗎？",
          DialogueId = 51003012,
          GUID = "7FAE41A8",
          NextOptions = {
            [1] = 510030121,
            [2] = 510030122
          },
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51003013] = {
          ContentTC = "哦！回應我呼喚的勇士出現了，這說不定是一段嶄新冒險的序幕！",
          DialogueId = 51003013,
          GUID = "7FAE41D2",
          NextDialogue = 51003014,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          },
          TurnTo = {
            [1] = "700015:n(0)"
          }
        },
        [51003014] = {
          ContentTC = "我對你們接下來碰到的事情抱以十足的興趣，當你們歸來，請為我講述你們的故事吧！",
          DialogueId = 51003014,
          GUID = "7FAE41FC",
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          }
        },
        [51003101] = {
          ContentTC = "據卡蜜拉所說，巴克先生不勝酒力、從不喝酒，那壺裡的酒難道是其他人加進去的？",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001
        },
        [51003102] = {
          ContentTC = "仔細一看，這牛奶壺上還有個黏糊糊的手印……看起來那隻手很小巧。",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001
        },
        [51003103] = {
          ContentTC = "小小的腳印從屋外延伸至窗台，屋內還有雪化的積水。顯然闖入者沒有處理痕跡的意識，單純就只是一個小孩子而已。",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001
        },
        [51003104] = {
          ContentTC = "看來似乎有個小孩把酒摻在牛奶裡，灌醉了巴克先生。再去找找其他線索吧。",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001
        },
        [51003105] = {
          ContentTC = "你好，請問平常會有小孩子來找巴克先生玩嗎？",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001
        },
        [51003106] = {
          ContentTC = "小孩找巴克玩？不可能不可能，哪有小孩會對那種只在<H>家裡、酒館和劇院</>三點一線，還滿嘴怪話的傢伙感興趣啊。",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213
        },
        [51003107] = {
          ContentTC = "別說小孩了，連我們平常都很少跟他打交道，煩得要死還一句話都聽不懂。他是不是犯什麼事了？我跟你講啊，我早就覺得他不是好東西了。",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213
        },
        [51003108] = {
          ContentTC = "（老婦人滔滔不絕地數落著巴克，諸如這麼大了沒有正經工作，一天到晚不出門，沒老婆沒朋友。一直到她講得口乾舌燥，你才找到機會離開。）",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109
        },
        [51003109] = {
          ContentTC = "（巴克先生深居簡出沒有社交，大部份人都不了解他。所以會想到用酒來灌醉巴克先生的小孩子，一定是從什麼地方知道了這個秘密……）",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001
        },
        [51003110] = {
          ContentTC = "（水仙平原不招攬小孩子，家附近也沒有小孩找巴克先生……那麼就只剩下劇院了，過去看看吧。）",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001
        },
        [51003111] = {
          ContentTC = "（售票廳旁的卡戎小孩哈著冷氣，打著冷顫。不停向來往行人推銷著門票、海報、啤酒和爆米花。）",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112
        },
        [51003112] = {
          ContentTC = "（不停向路人推銷商品的小孩，會是他灌醉的巴克先生嗎？）",
          DialogueId = 51003112,
          GUID = "7FAE5210",
          SpeakNpcId = 100001
        },
        [51003113] = {
          ContentTC = "巴克先生經常出入劇院，一定多次碰到並拒絕過那個小孩推銷啤酒……",
          DialogueId = 51003113,
          Duration = 3,
          GUID = "7FAE523A",
          NextDialogue = 51003114,
          SpeakNpcId = 100001
        },
        [51003114] = {
          ContentTC = "他袖口黏著的那幾枚爆米花，跟我窗戶下撿到的一模一樣。怎麼看他的嫌疑都很大，過去聊聊看吧。",
          DialogueId = 51003114,
          Duration = 4,
          GUID = "7FAE5264",
          SpeakNpcId = 100001
        },
        [51003115] = {
          ContentTC = "喝啊，我還能喝……不就是二十幾瓶啤酒嘛，這才哪到哪啊！來，繼續上酒繼續喝！",
          DialogueId = 51003115,
          GUID = "7FAE528E",
          NextDialogue = 51003116,
          SpeakNpcId = 700214
        },
        [51003116] = {
          ContentTC = "（渾身酒氣的大叔。會是他灌醉的巴克先生嗎？）",
          DialogueId = 51003116,
          GUID = "7FAE52B8",
          SpeakNpcId = 100001
        },
        [51003117] = {
          ContentTC = "那個爆米花……是什麼味道的呀，爸爸，我想嚐嚐看！",
          DialogueId = 51003117,
          GUID = "7FAE52E2",
          LookAt = {
            [1] = "700215:n(700219)",
            [2] = "700219:n(700215)"
          },
          NextDialogue = 51003118,
          SpeakNpcId = 700215
        },
        [51003118] = {
          ContentTC = "孩子，你是個淑女，不應該吃那種垃圾食品，等看完歌劇了，爸爸帶你去銀色和平餐廳吃大餐。",
          DialogueId = 51003118,
          GUID = "7FAE530C",
          NextDialogue = 51003119,
          SpeakNpcId = 700219,
          TalkActionId = {
            [1] = "700219:Talk03_Start"
          }
        },
        [51003119] = {
          ContentTC = "好吧……",
          DialogueId = 51003119,
          GUID = "7FAE5336",
          NextDialogue = 51003120,
          SpeakNpcId = 700215,
          TalkActionId = {
            [1] = "700219:Talk03_End"
          }
        },
        [51003120] = {
          ContentTC = "（出現在劇院附近的小孩，很想嚐一口爆米花的樣子。會是她灌醉的巴克先生嗎？）",
          DialogueId = 51003120,
          GUID = "7FAE5360",
          SpeakNpcId = 100001
        },
        [51003301] = {
          ContentTC = "阿嚏！怎麽好像更冷了……",
          DialogueId = 51003301,
          GUID = "7FAE7112",
          NextDialogue = 51003302,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_Start"
          }
        },
        [51003302] = {
          ContentTC = "就算是卡戎，不怕冷也是有極限的……到了晚上起碼會降溫二十多度，說不定又有孩子要凍死了，唉……",
          DialogueId = 51003302,
          GUID = "7FAE713C",
          NextDialogue = 51003303,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_End"
          }
        },
        [51003303] = {
          ContentTC = "你好。",
          DialogueId = 51003303,
          GUID = "7FAE7166",
          NextDialogue = 51003304,
          SpeakNpcId = 100001
        },
        [51003304] = {
          ContentTC = "您好，尊敬的閣下！看戲辛苦了！坐了三個小時，您一定餓了吧！想來點零食和飲品嗎？",
          DialogueId = 51003304,
          GUID = "7FAE7190",
          NextDialogue = 51003305,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003305] = {
          ContentTC = "或者您感動於精彩的表演，想看一看有演員簽名的海報呢？",
          DialogueId = 51003305,
          GUID = "7FAE71BA",
          NextOptions = {
            [1] = 510033051,
            [2] = 510033052
          },
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003306] = {
          ContentTC = "讓我瞧瞧你都賣些什麽。",
          DialogueId = 51003306,
          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001
        },
        [51003307] = {
          ContentTC = "維蒂的珍藏版簽名海報，《冰湖往事》的紀念手冊，冰山融水，劇院聯名版爆米花，以及清甜的啤酒！",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          ContentTC = "您放心，這度數聊勝於無，喝不醉人的！",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          ContentTC = "那可不一定……你認識劇作家巴克先生嗎？",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001
        },
        [51003310] = {
          ContentTC = "當然認識！他是劇院的常客，也經常光顧我的生意，身為貴族但尊重我這樣的卡戎小孩，是難得一見的大好人！",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          ContentTC = "我知道有人嘲笑他，但比起那些人，巴克先生更值得尊敬。",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080
        },
        [51003312] = {
          ContentTC = "這不是你從窗臺摸進他家，偷偷在他牛奶裡倒酒的理由。",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001
        },
        [51003313] = {
          ContentTC = "你、你是怎麽知道的……",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          ContentTC = "巴克先生總在夜間進行創作，你的行為讓他的劇本一個月都沒有進展，於是他雇傭我去尋找神秘的「靈感飛賊」。",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          ContentTC = "（想說的話突然卡在嘴邊，在腦海裡重新整理一下措辭吧。）",
          DialogueId = 51003315,
          GUID = "7FAE735E"
        },
        [51003316] = {
          ContentTC = "你的生意並不支持你買到足夠的過冬物資，巴克先生雖然沒什麽錢，但好歹是個貴族，他的房子足夠暖和，所以你才想潛入巴克先生家取暖。",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001
        },
        [51003317] = {
          ContentTC = "至於為什麽是巴克先生，那是因為不管度數有多低，只要沾一點點酒他都會睡過去，在這之後你就能安心地睡上一整晚而不必擔心被凍死，對嗎？",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001
        },
        [51003318] = {
          ContentTC = "唉……您可真是名偵探再世，事情就像您說的一樣。",
          DialogueId = 51003318,
          GUID = "7FAE73DC",
          NextDialogue = 51003319,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003319] = {
          ContentTC = "您把我抓起來吧，我感到十分抱歉，但如果不這麽做，我連被您抓起來的機會都沒有……",
          DialogueId = 51003319,
          GUID = "7FAE7406",
          NextDialogue = 51003320,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          }
        },
        [51003320] = {
          ContentTC = "我沒有權利決定怎麽處理你，我會帶你去見我的雇主。",
          DialogueId = 51003320,
          GUID = "7FAE7430",
          SpeakNpcId = 100001
        },
        [51003321] = {
          ContentTC = "（果然如此。）",
          DialogueId = 51003321,
          GUID = "7FAE730B",
          NextDialogue = 51003314,
          SpeakNpcId = 100001
        },
        [51003401] = {
          Camera = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我找到人了。",
          DialogueId = 51003401,
          GUID = "7FAE817A",
          LookAt = {
            [1] = "700102:n(100001)",
            [2] = "100001:n(700102)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51003402] = {
          ContentTC = "（你將事情的來龍去脈告知給了巴克先生。）",
          DialogueId = 51003402,
          Duration = 3,
          GUID = "7FAE81A4"
        },
        [51003403] = {
          Camera = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哦！我的勇士，對您道一萬次的感謝！想必從今夜起，靈感女神的寵愛將重回我身！",
          DialogueId = 51003403,
          GUID = "7FAE81CE",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003404,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          },
          TurnTo = {
            [1] = "700103:n(700102)"
          }
        },
        [51003404] = {
          Camera = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "至於你……我夢中的小飛賊，你可真是給了我一個莫大的意外！",
          DialogueId = 51003404,
          GUID = "7FAE81F8",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003405,
          SpeakNpcId = 700015,
          TurnTo = {
            [1] = "700102:n(700103)"
          }
        },
        [51003405] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "非常抱歉，巴克先生……但請您相信我，我從沒有要傷害你的意思……",
          DialogueId = 51003405,
          GUID = "7FAE8222",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003406,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700103:Explain02_Start"
          }
        },
        [51003406] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "哦，小飛賊，我知道人們在背後是怎麽笑話我的，我是個賣不出作品的廢物劇作家。",
          DialogueId = 51003406,
          GUID = "7FAE824C",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003407,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          }
        },
        [51003407] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "就算用再優美的辭藻裝飾我的言語，也換不來他們對我的欣賞，他們拒絕傾聽，拒絕理解……但依我看，這世上又有幾個能有話直說的人呢？",
          DialogueId = 51003407,
          GUID = "7FAE8276",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003408,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk03_Start"
          }
        },
        [51003408] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "先生，我不明白您的意思。",
          DialogueId = 51003408,
          GUID = "7FAE82A0",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003409,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Talk03_End",
            [2] = "700103:Disagree"
          }
        },
        [51003409] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我是說，你從不把我當成一個只知道癡人說夢的蠢貨，那麽對於你，我也有自己的尊重，如果你無法渡過這個冬天，何不早說呢？",
          DialogueId = 51003409,
          GUID = "7FAE82CA",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003410,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          }
        },
        [51003410] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "我會為你收拾出房間，如果你樂意，還能拿起我的稿紙當睡前故事，只是我不確定那些故事是否足夠助眠。",
          DialogueId = 51003410,
          GUID = "7FAE82F4",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003411,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Explain01_Start"
          }
        },
        [51003411] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "您真的願意收留我嗎……我不值得您這樣做，但我可以幫您做一些瑣事，就當是我耽誤您一個月創作的補償吧……",
          DialogueId = 51003411,
          GUID = "7FAE831E",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003412,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Explain01_End",
            [2] = "700103:Explain02_Start"
          }
        },
        [51003412] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "感謝您所做的一切，尊敬的狩月人閣下！明察秋毫的冰湖城偵探非您莫屬，我收獲了一個溫馨的故事，也收獲了兩個誠摯的朋友。",
          DialogueId = 51003412,
          GUID = "7FAE8348",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003413,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          },
          TurnTo = {
            [1] = "700102:n(100001)"
          }
        },
        [51003413] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "啊！靈感紛至沓來！我得迅速回去把他們記下來，如果我的詩篇能得到傳頌，千百年後人們也依然贊美著您的名字！",
          DialogueId = 51003413,
          GUID = "7FAE8372",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk01_Start"
          }
        },
        [51003414] = {
          ContentTC = "（兩人一起離去了，每個人都得到了他想要的，不知道巴克先生的下一部大作是否能和他說的一樣精彩。）",
          DialogueId = 51003414,
          Duration = 4,
          GUID = "7FAE839C"
        },
        [51003501] = {
          Camera = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "感謝犧牲、感謝慈悲、感謝銀色和平，讓我們遠離瘟疫，讓我們遠離蒙昧，讓我們遠離惡魔的威脅……",
          DialogueId = 51003501,
          GUID = "7FAE91E2",
          NextDialogue = 51003520,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_Start"
          }
        },
        [51003502] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "艾瑪？艾瑪？你在發什麽楞？",
          DialogueId = 51003502,
          GUID = "7FAE920C",
          LookAt = {
            [1] = "700016:n(700086)"
          },
          NextDialogue = 51003503,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_End",
            [2] = "700086:Confident_Start"
          }
        },
        [51003503] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "抱歉老師！我這就來！",
          DialogueId = 51003503,
          GUID = "7FAE9236",
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700086:Confident_End",
            [2] = "700016:Shock_Start"
          }
        },
        [51003504] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你這孩子最近怎麽魂不守舍的，下次可不能這樣了。",
          DialogueId = 51003504,
          GUID = "7FAE9260",
          NextDialogue = 510035041,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Sigh_Start"
          }
        },
        [51003505] = {
          ContentTC = "唉……真無聊……不知道婆婆在做什麽呢？",
          DialogueId = 51003505,
          GUID = "7FAE928A",
          NextOptions = {
            [1] = 510035051,
            [2] = 510035052,
            [3] = 510035053
          },
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003506] = {
          ContentTC = "當然有原因啦，告訴你也不是不行，但你得保證守口如瓶。",
          DialogueId = 51003506,
          GUID = "7FAE92B4",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035061
          },
          RestartTag = 51003506,
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003507] = {
          ContentTC = "像，很像啊！",
          DialogueId = 51003507,
          GUID = "7FAE92DE",
          SpeakNpcId = 700016
        },
        [51003508] = {
          ContentTC = "那我就告訴你吧！",
          DialogueId = 51003508,
          GUID = "7FAE9308",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003509,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [51003509] = {
          ContentTC = "上個月我偷偷溜去貧民窟玩，結果在小巷子裡碰到了一個神秘的老婆婆！",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016
        },
        [51003510] = {
          ContentTC = "她手可巧啦，會給我編各種花式的小辮子，會用鮮花給我染指甲，還知道許許多多我從來沒聽過的小故事！",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          ContentTC = "她從不對我說教，也不把我當小孩糊弄，雖然那是我們頭一回見，但她摟著我的時候就像我奶奶一樣溫暖……",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016
        },
        [51003512] = {
          ContentTC = "那不是很好嗎？為什麽不坦然告訴別人你有新朋友了呢？",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001
        },
        [51003513] = {
          ContentTC = "因為婆婆長了角……如果我告訴父母、同學、老師，一定會讓她受到傷害吧……",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          ContentTC = "我們本來約好了今天見面，可是學校臨時增加了紀念活動，我只能爽約了，如果你有空，可不可以幫我把這個布娃娃帶給她？",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035141,
            [2] = 51000002
          },
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003515] = {
          ContentTC = "集合時間到了，拜托你可千萬要送到哦！謝謝你！",
          DialogueId = 51003515,
          GUID = "7FAE942E",
          SpeakNpcId = 700016
        },
        [51003520] = {
          ContentTC = "下面由艾瑪獻上紀念的花……",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "謝謝你，婆婆，我覺得好多了，如果這是羅伯期望的，我會為了他好好生活。",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "希望你早日走出悲痛，我們與你同在，孩子，如果你需要，貝琳達的小屋永遠為你開放。",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          ContentTC = "你好呀！我從沒見過你，我猜你是剛來冰湖城的朋友？找貝琳達有什麽事呢。",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          ContentTC = "（雖然手藝粗糙，但你能看出娃娃和貝琳達有幾分相似。卡戎婆婆滿是喜悅，將娃娃撫摸了一遍又一遍。）",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          ContentTC = "我從娃娃上感覺到了廣場的氣息……啊，瞧我這記性！紀念周到啦，這時候的活動總是很多……",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          ContentTC = "我很感謝你，孩子。",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081
        },
        [51003608] = {
          ContentTC = "（她仔細地端詳著你，有好幾分鐘都沒有說話。）",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609
        },
        [51003609] = {
          ContentTC = "你好像惹上了大麻煩，我聞到了海風的味道，感受到了潮水的包裹，還有……你手掌上殘留的，他人的溫度，但這份溫暖正逐漸遠去……",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          ContentTC = "來到這裡的每時每刻，你都被困惑與悲傷纏繞，但你努力把這些壓抑在心底，不去表露……",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          ContentTC = "無意冒犯，你是否失去了重要之人？",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          bForbidSkipOptions = true
        },
        [51003612] = {
          ContentTC = "能活到我這麽大年紀的卡戎很稀奇吧？",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003613] = {
          ContentTC = "你在難過，孩子。",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003614] = {
          ContentTC = "不用強撐，我知道的，孩子。",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003615] = {
          ContentTC = "很遺憾，孩子，我沒有幫助你的辦法，但有一句話，我想正適合此時的你……",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081
        },
        [51003616] = {
          ContentTC = "「行人走上一線旅途，命運女神紡錘收束。當千頭萬緒重聚，失物在眼前沈浮。」",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
            [1] = 510036161
          },
          RestartTag = 51003616,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          },
          bForbidSkipOptions = true
        },
        [51003617] = {
          ContentTC = "孩子，你將在旅途中拾得你缺少的一切，去吧，去吧。",
          DialogueId = 51003617,
          GUID = "7FAEA4EA",
          SpeakNpcId = 700081
        },
        [51003618] = {
          ContentTC = "出自《命運女神的紡錘》終幕……無可剝奪者在雙面之境見到了自己失去的一切……你是在告訴我終有一天我們會再次相見？",
          DialogueId = 51003618,
          GUID = "7FAEA514",
          NextDialogue = 51003619,
          SpeakNpcId = 100001
        },
        [51003619] = {
          ContentTC = "請把這句箴言當作送來娃娃的謝禮吧。你很聰明，孩子，就像我所看到的一樣……不需要我告訴你什麽，你會依靠自己的力量探明疑問。",
          DialogueId = 51003619,
          GUID = "7FAEA53E",
          NextDialogue = 51003620,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003620] = {
          ContentTC = "另外，我會送給每個初次來拜訪我的人一件小禮物，只要一件帶有你自身氣息的鐵絲就好，不急於現在，我會一直在這裡等你。",
          DialogueId = 51003620,
          GUID = "7FAEA568",
          NextDialogue = 51003621,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003621] = {
          ContentTC = "氣息……雖然不太明白，但只要是我接觸過的，或是在我身上待過的就可以吧。",
          DialogueId = 51003621,
          GUID = "7FAEA592",
          NextDialogue = 51003622,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003622] = {
          ContentTC = "格雷姆廢礦那裡應該有不少鐵絲，我去那邊看看。",
          DialogueId = 51003622,
          Duration = 3,
          GUID = "7FAEA5BC",
          SpeakNpcId = 100001
        },
        [51003630] = {
          ContentTC = "陌生的卡戎雖然還掛著淚痕，但你能從他的眼中看出，他已經燃起了活下去的勇氣。",
          DialogueId = 51003630,
          Duration = 4,
          GUID = "7FAEA70C",
          NextDialogue = 51003631
        },
        [51003631] = {
          ContentTC = "他與貝琳達擁抱後，依依不舍地離去了。",
          DialogueId = 51003631,
          Duration = 2,
          GUID = "7FAEA736"
        },
        [51003701] = {
          ContentTC = "（貝琳達從你手中接過鐵絲，將其彎成了一枚側臉肖像，你能看出這件小工藝品與貝蕾妮卡有些相似。）",
          DialogueId = 51003701,
          GUID = "7FAEB2B2",
          NextDialogue = 51003702
        },
        [51003702] = {
          ContentTC = "我並不強大，只能看到些朦朧的影子，不知道這與你思念之人是否相像，希望這能讓你好受一些。",
          DialogueId = 51003702,
          GUID = "7FAEB2DC",
          NextDialogue = 51003703,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Disagree"
          }
        },
        [51003703] = {
          ContentTC = "衷心祝願你們再次重逢。",
          DialogueId = 51003703,
          GUID = "7FAEB306",
          NextDialogue = 51003704,
          SpeakNpcId = 700081
        },
        [51003704] = {
          ContentTC = "（你離開了貝琳達的小帳篷，現在你好像理解為什麽艾瑪對這裡如此留戀了，貝琳達的力量並不強大，但她始終在治愈心靈，撫平傷痛。）",
          DialogueId = 51003704,
          GUID = "7FAEB330"
        },
        [51003705] = {
          Camera = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嗯……這樣應該就差不多了！",
          DialogueId = 51003705,
          FinalCamera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEA5BD",
          NextDialogue = 51003706,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51003706] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "打打打打打劫！你懷裡的寶貝是我的啦！",
          DialogueId = 51003706,
          GUID = "7FAEA5BE",
          NextDialogue = 51003707,
          Scripts = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
          SpeakNpcId = 700206
        },
        [51003707] = {
          Camera = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（皎皎之民的身影猛地從一旁竄出，一把搶過你懷中的鐵絲，一邊跑一邊回頭嘲笑著你。）",
          DialogueId = 51003707,
          GUID = "7FAEA5BF",
          NextDialogue = 51003708,
          Scripts = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}"
