        },
        [51004106] = {
          ContentTC = "（學生們一溜煙逃走了。）",
          DialogueId = 51004106,
          GUID = "7FAEF524"
        },
        [51004107] = {
          ContentTC = "你看，他們也就這點本事。",
          DialogueId = 51004107,
          GUID = "7FAEF54E",
          NextDialogue = 51004108,
          SpeakNpcId = 100001
        },
        [51004108] = {
          ContentTC = "……嗯！",
          DialogueId = 51004108,
          GUID = "7FAEF578",
          NextDialogue = 51004109,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004109] = {
          ContentTC = "多虧了有你在……你掄起拳頭的樣子真的很威風呢！",
          DialogueId = 51004109,
          GUID = "7FAEF5A2",
          NextOptions = {
            [1] = 510041091,
            [2] = 510041092
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004110] = {
          ContentTC = "誒，是、是嗎？我只是……把以前偷偷在心裡想的話說出來了。",
          DialogueId = 51004110,
          GUID = "7FAEF5CC",
          NextDialogue = 51004111,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Shock_Start"
          }
        },
        [51004111] = {
          ContentTC = "謝謝你，我長這麽大，還是頭一次心裡這麽暢快呢！",
          DialogueId = 51004111,
          GUID = "7FAEF5F6",
          NextDialogue = 51004112,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Shock_End"
          }
        },
        [51004112] = {
          ContentTC = "不用謝，他們短時間應該不會來找你麻煩了，我送你回家吧。這是我的地址——如果他們再惹你，就來找我。",
          DialogueId = 51004112,
          GUID = "7FAEF620",
          NextDialogue = 51004113,
          SpeakNpcId = 100001
        },
        [51004113] = {
          ContentTC = "我不想回家……！",
          DialogueId = 51004113,
          GUID = "7FAEF64A",
          NextDialogue = 51004114,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Disagree"
          }
        },
        [51004114] = {
          ContentTC = "我是卡戎，我要和卡戎之民待在一起……",
          DialogueId = 51004114,
          GUID = "7FAEF674",
          NextOptions = {
            [1] = 510041141
          },
          RestartTag = 51004114,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          },
          bForbidSkipOptions = true
        },
        [51004115] = {
          ContentTC = "（女孩固執地撅著嘴，並沒有被你說服。）",
          DialogueId = 51004115,
          GUID = "7FAEF69E"
        },
        [51004116] = {
          ContentTC = "還沒看清他們嗎？他們平日裡對著你威風凜凜，但真的有人比他們拳頭更硬的時候，他們就會落荒而逃。",
          DialogueId = 51004116,
          GUID = "7FAEF6C8",
          NextDialogue = 51004117,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004117] = {
          ContentTC = "他們不像自己表現得那麽強大。所以，他們嘴裡說的自然也不是事實。費伊，你是如假包換的人類，不要被他們蹩腳的謊言騙了。",
          DialogueId = 51004117,
          GUID = "7FAEF6F2",
          NextDialogue = 51004118,
          SpeakNpcId = 100001
        },
        [51004118] = {
          ContentTC = "記住，永遠不要因為別人的惡意質疑自己，責備自己……這是我的家人教會我的，我也把它教給你。",
          DialogueId = 51004118,
          GUID = "7FAEF71C",
          NextDialogue = 51004119,
          SpeakNpcId = 100001
        },
        [51004119] = {
          ContentTC = "（女孩略帶困惑地眨了眨眼，似乎還不能完全理解你話語的含義，但是表情卻有所緩和。）",
          DialogueId = 51004119,
          GUID = "7FAEF746",
          NextDialogue = 51004120
        },
        [51004120] = {
          ContentTC = "好吧……既然你這麽說的話，我會努力試試看的！但在那之前，我還有最後一個小小的請求……",
          DialogueId = 51004120,
          GUID = "7FAEF770",
          NextDialogue = 51004121,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004121] = {
          ContentTC = "可以讓我摸一下你的角嗎？",
          DialogueId = 51004121,
          GUID = "7FAEF79A",
          NextOptions = {
            [1] = 510041211,
            [2] = 510041212
          },
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51004122] = {
          ContentTC = "謝謝！",
          DialogueId = 51004122,
          GUID = "7FAEF7C4",
          NextDialogue = 51004123,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004123] = {
          ContentTC = "（女孩小心翼翼地伸出纖瘦的手，摸了摸你頭上的角。）",
