          GUID = "7FAEF7EE",
          NextDialogue = 51004126
        },
        [51004124] = {
          ContentTC = "好吧，那我不摸，就看一看……",
          DialogueId = 51004124,
          GUID = "7FAEF818",
          NextDialogue = 51004125,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004125] = {
          ContentTC = "（女孩小心翼翼地湊上來，仔細地打量著你頭上的角。）",
          DialogueId = 51004125,
          GUID = "7FAEF842",
          NextDialogue = 51004126
        },
        [51004126] = {
          ContentTC = "原來真正的角，是這樣的啊……",
          DialogueId = 51004126,
          GUID = "7FAEF86C",
          NextDialogue = 51004127,
          SpeakNpcId = 700105
        },
        [51004127] = {
          ContentTC = "紅色的，很精巧……還會反射陽光呢。確實比我的辮子要可愛多了。",
          DialogueId = 51004127,
          GUID = "7FAEF896",
          NextOptions = {
            [1] = 510041271
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004128] = {
          ContentTC = "你是第一個這麽說的人。但它們現在都被弄亂了……我要重新梳好才行。",
          DialogueId = 51004128,
          GUID = "7FAEF8C0",
          NextDialogue = 51004129,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004129] = {
          ContentTC = "（女孩從書包裡找出一把梳子，認真地將頭上的兩條辮子重新梳好，然後將它們向上提起來，比劃出角的樣子。）",
          DialogueId = 51004129,
          GUID = "7FAEF8EA",
          NextDialogue = 51004130,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004130] = {
          ContentTC = "這樣像不像惡魔角？",
