          GUID = "7FAEF914",
          NextOptions = {
            [1] = 510041301,
            [2] = 510041302
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004131] = {
          ContentTC = "呵呵。",
