          GUID = "7FAEF9BC",
          NextDialogue = 51004135,
          SpeakNpcId = 700105
        },
        [51004135] = {
          ContentTC = "（女孩不由分說地踮起腳尖，試圖把你按到一個她能夠得到的位置。看來，她已經精神多了。）",
          DialogueId = 51004135,
          GUID = "7FAEF9E6",
          NextDialogue = 51004136
        },
        [51004136] = {
