          DialogueId = 51004140,
          GUID = "7FAEFAB8",
          NextDialogue = 51004141,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004141] = {
          ContentTC = "（女孩打開書包，在筆記本上認真畫著你的樣子。）",
