          GUID = "7FAEFB60",
          NextDialogue = 51004145,
          SpeakNpcId = 100001
        },
        [51004145] = {
          ContentTC = "（女孩正準備離開，忽然又回過頭，認真地看向你。）",
          DialogueId = 51004145,
          GUID = "7FAEFB8A",
          NextDialogue = 51004146
        },
        [51004146] = {
          ContentTC = "對了……剛才給你梳頭的時候，我突然想到一件事。",
          DialogueId = 51004146,
          GUID = "7FAEFBB4",
          NextDialogue = 51004147,
          SpeakNpcId = 700105
        },
        [51004147] = {
          ContentTC = "他們一直都告訴我，卡戎是惡魔的孩子，是腦袋笨笨又一肚子壞水的，總是在做壞事的……",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          ContentTC = "這些話……其實也不是真的吧？",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004149] = {
          ContentTC = "那也是他們用來欺負你們的借口，對不對？",
          DialogueId = 51004149,
          GUID = "7FAEFC32",
          NextOptions = {
            [1] = 510041491,
            [2] = 510041492
          },
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_Start"
          },
          bForbidSkipOptions = true
        },
        [51004150] = {
          ContentTC = "你們一定……承受了比我多得多的痛苦吧。",
          DialogueId = 51004150,
          GUID = "7FAEFC5C",
          NextDialogue = 51004151,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_End"
          }
        },
        [51004151] = {
          ContentTC = "今後，如果有什麽我能幫得上忙的事，請儘管說……不是因為我們是同類，而是因為我們是朋友。",
          DialogueId = 51004151,
          GUID = "7FAEFC86",
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          }
        },
        [51004152] = {
          ContentTC = "同學們還是不喜歡我，但現在我已經不怕他們了！這都是多虧了你！",
          DialogueId = 51004152,
          GUID = "7FAEFCB0",
          SpeakNpcId = 700105
        },
        [51004201] = {
          ContentTC = "嘖，生面孔啊。",
          DialogueId = 51004201,
          GUID = "7FAF04BA",
          NextDialogue = 51004202,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Talk03_Start"
          }
        },
        [51004202] = {
          ContentTC = "（眼前的男人瞇起眼，抿了抿嘴唇上銳利的裂口，吐出幹燥的話語。）",
          DialogueId = 51004202,
          GUID = "7FAF04E4",
          NextDialogue = 51004203
        },
        [51004203] = {
