          GUID = "7FAF058C",
          NextDialogue = 51004207
        },
        [51004207] = {
          ContentTC = "（男人沈默了一陣，擡眼打量起你來。你幾乎能聽見他擡頭時脊椎疲憊地的異響。）",
          DialogueId = 51004207,
          GUID = "7FAF05B6",
          NextDialogue = 51004208
        },
        [51004208] = {
          ContentTC = "碎嘴子。",
          DialogueId = 51004208,
          GUID = "7FAF05E0",
          NextDialogue = 51004209,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004209] = {
          ContentTC = "（他輕哼了一聲，又似乎很滿意你的回答。）",
          DialogueId = 51004209,
          GUID = "7FAF060A",
          NextDialogue = 51004210
        },
        [51004210] = {
          ContentTC = "不管是誰介紹你來的，反正也是為了我口袋裡的貨，對吧？",
          DialogueId = 51004210,
          GUID = "7FAF0634",
          NextDialogue = 51004211,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          }
        },
        [51004211] = {
          ContentTC = "（男人扯開衣領，黯淡的金屬管自懷中閃過。）",
          DialogueId = 51004211,
          GUID = "7FAF065E",
          NextDialogue = 51004212,
          TalkActionId = {
            [1] = "700096:Confident_End"
          }
        },
        [51004212] = {
          ContentTC = "（他立刻收緊了衣領，警惕地望了望四周。）",
          DialogueId = 51004212,
          GUID = "7FAF0688",
          NextDialogue = 51004213
        },
        [51004213] = {
          ContentTC = "4號口徑，雙管單發，不論是卡戎人還是穢獸，在它面前都走不過兩下。",
          DialogueId = 51004213,
          GUID = "7FAF06B2",
          NextDialogue = 51004214,
          SpeakNpcId = 700096
        },
        [51004214] = {
          ContentTC = "（男人撇了撇嘴，像在談論農用殺蟲劑的功效。）",
          DialogueId = 51004214,
          GUID = "7FAF06DC",
          NextDialogue = 51004215
        },
        [51004215] = {
          ContentTC = "這回的貨不要錢，只要你幫我辦件事。",
          DialogueId = 51004215,
          GUID = "7FAF0706",
          NextOptions = {
            [1] = 510042151,
            [2] = 510042152
          },
          SpeakNpcId = 700096,
          bForbidSkipOptions = true
        },
        [51004216] = {
          ContentTC = "哆嗦什麽？你不就是沖著這玩意來的嗎？",
          DialogueId = 51004216,
          GUID = "7FAF0730",
          NextDialogue = 51004217,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_Start"
          }
        },
        [51004217] = {
          ContentTC = "事兒辦利索了，不僅東西歸你，我再追補給你一筆。",
          DialogueId = 51004217,
          GUID = "7FAF075A",
          NextOptions = {
            [1] = 510042171,
            [2] = 510042172
          },
          RestartTag = 51004216,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51004218] = {
          ContentTC = "想快點，我等不了你太久。",
          DialogueId = 51004218,
          GUID = "7FAF0784",
          SpeakNpcId = 700096
        },
        [51004219] = {
          ContentTC = "好吧，你要我做什麽？",
          DialogueId = 51004219,
          GUID = "7FAF07AE",
          NextDialogue = 51004220,
          SpeakNpcId = 100001
        },
        [51004220] = {
          ContentTC = "爽快，一會兒我給你個地方，目標就是那地方除了女人之外的東西都清了。",
          DialogueId = 51004220,
          GUID = "7FAF07D8",
          NextDialogue = 51004221,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          }
        },
        [51004221] = {
          ContentTC = "這……感情問題……？",
          DialogueId = 51004221,
          GUID = "7FAF0802",
          NextDialogue = 51004222,
          SpeakNpcId = 100001
        },
        [51004222] = {
          ContentTC = "別多嘴。",
          DialogueId = 51004222,
          GUID = "7FAF082C",
          NextDialogue = 51004223,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004223] = {
          ContentTC = "（男人緊了緊衣領，抿住幹癟的嘴唇，不願再吐出任何一個字。）",
          DialogueId = 51004223,
          GUID = "7FAF0856"
        },
        [51004301] = {
          ContentTC = "行啊，收了錢就走吧，我不希望在這附近見到你。",
          DialogueId = 51004301,
          GUID = "7FAF1522",
          NextDialogue = 51004302,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004302] = {
          ContentTC = "你只是想找人清理這附近的穢獸？就算不雇傭我，也會有人處理那些穢獸的。",
          DialogueId = 51004302,
          GUID = "7FAF154C",
          NextDialogue = 51004303,
          SpeakNpcId = 100001
        },
        [51004303] = {
          ContentTC = "有人處理？誰？那群把卡戎人當狗的雜碎？",
          DialogueId = 51004303,
          GUID = "7FAF1576",
          NextDialogue = 51004304,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_Start"
          }
        },
        [51004304] = {
          ContentTC = "你猜猜他們到時候打開門，發現這裡住的是一個孱弱的卡戎女人，他們會怎麽辦？",
          DialogueId = 51004304,
          GUID = "7FAF15A0",
          NextDialogue = 51004305,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_End"
          }
        },
        [51004305] = {
          ContentTC = "（男人突然捂緊胸口，渾身戰栗起來，像是傷口被扯痛一般。好一陣，他才止住顫抖，偏過頭，吐出一口唾沫釘在地上。）",
          DialogueId = 51004305,
          GUID = "7FAF15CA",
          NextDialogue = 51004306
        },
        [51004306] = {
          ContentTC = "一個善良的卡戎女人，為了救一個重傷躺在路邊的陌生人，砸傷了內城跑出來的烈犬。",
          DialogueId = 51004306,
          GUID = "7FAF15F4",
          NextDialogue = 51004307,
          SpeakNpcId = 700101
        },
        [51004307] = {
          ContentTC = "就因為這點事，她被毒打一頓，拖出冰湖城的門，丟到這荒地裡。",
          DialogueId = 51004307,
          GUID = "7FAF161E",
          NextDialogue = 51004308,
          SpeakNpcId = 700101
        },
        [51004308] = {
          ContentTC = "這……也許你可以想辦法幫她離開冰湖城，換個地方生活。",
          DialogueId = 51004308,
          GUID = "7FAF1648",
          NextDialogue = 51004309,
          SpeakNpcId = 100001
        },
        [51004309] = {
          ContentTC = "……快了，快攢夠了。",
          DialogueId = 51004309,
          GUID = "7FAF1672",
          NextDialogue = 51004310,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004310] = {
          ContentTC = "（男人轉過身，面向帳篷的方向，僵硬的嘴角罕見地被撬開了一瞬，露出類似笑容的表情。）",
          DialogueId = 51004310,
          GUID = "7FAF169C",
          LookAt = {
            [1] = "700101:n(700100)"
          },
          NextDialogue = 51004311,
          TurnTo = {
            [1] = "700101:n(700100)"
          }
        },
        [51004311] = {
          ContentTC = "（你似乎聽見了朽木舒展時發出的幹燥異響。）",
          DialogueId = 51004311,
          GUID = "7FAF16C6"
        },
        [51004401] = {
          ContentTC = "下水道裡的什麼是不會消失的?",
          DialogueId = 51004401,
          GUID = "7FAF258A",
          NextOptions = {
            [1] = 510044011,
            [2] = 510044012,
            [3] = 510044013
          },
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          bForbidSkipOptions = true
        },
        [51004402] = {
          ContentTC = "進來吧。",
          DialogueId = 51004402,
          GUID = "7FAF25B4",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004403] = {
          ContentTC = "這不是什麼都不知道的蠢貨該來的地方。",
          DialogueId = 51004403,
          GUID = "7FAF25DE",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004501] = {
