        },
        [51004505] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "去這張紙上的位置吧，和之前一樣，除了女人之外的東西全清了。",
          DialogueId = 51004505,
          GUID = "7FAF369A",
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Give"
          }
        },
        [51004901] = {
          Content = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
          DialogueId = 51004901,
          GUID = "7FAF7792",
          LookAt = {
            [1] = "700010:n(0)"
          }
        },
        [51004902] = {
          ContentTC = "你決定向她展示瑪爾潔曾交給你的某樣線索。",
          DialogueId = 51004902,
          FinalDialogueId = 51004905,
          GUID = "7FAF77BC",
          NextOptions = {
            [1] = 510049021,
            [2] = 510049022,
            [3] = 510049023
          },
          bForbidSkipOptions = true
        },
        [51004903] = {
          ContentTC = "（女人一言不發，只是用警惕的目光盯著你，搖了搖頭。看來，這不是她遺落的東西。）",
          DialogueId = 51004903,
          GUID = "7FAF77E6",
          NextOptions = {
            [1] = 510049031,
            [2] = 510049032
          },
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004905] = {
          ContentTC = "露娜……醫生？這份藥方是你寫的嗎。",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001
        },
        [51004906] = {
          ContentTC = "（你將手中的藥方翻到露娜面前，好讓藥方上那些危險的文字能被露娜看到。）",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907
        },
        [51004907] = {
          ContentTC = "「城外的穢獸吃我們的肉，城內的農場主剪我們的毛。獵犬們吃著白面包，卡戎羊兒嚼著地上的草。摸爬滾打、搖尾乞憐，只為博主人芳心一笑。」",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004908] = {
          ContentTC = "啊……哇哇我……",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
          ContentTC = "（露娜看後立馬支支吾吾了起來，焦急地用兩只手胡亂地在空中比劃，無論是字跡還是反應，都證明了你找對了人。）",
          DialogueId = 51004909,
          GUID = "7FAF78E2",
          NextOptions = {
            [1] = 510049091,
            [2] = 510049092
          },
          TalkActionId = {
            [1] = "700010:Shock_Loop"
          }
        },
        [51004910] = {
          ContentTC = "（露娜的情緒稍微平復了一些。）",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004911] = {
          ContentTC = "（她看起來更加焦急了。）",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004912] = {
          ContentTC = "這張紙如果落在其他人手裡，你會惹上不小的麻煩吧？",
          DialogueId = 51004912,
          GUID = "7FAF7960",
          NextDialogue = 51004913,
          SpeakNpcId = 100001
        },
        [51004913] = {
          ContentTC = "（露娜指了指自己的喉嚨，然後拿起一張空白的紙，奮筆疾書。）",
          DialogueId = 51004913,
          GUID = "7FAF798A",
          NextDialogue = 51004914,
          TalkActionId = {
            [1] = "700010:Explain02_Start"
          }
        },
        [51004914] = {
          ContentTC = "「我曾是一個吟遊詩人。幾個仇恨卡戎的人綁架了我。他們嘲弄我，毆打我，割去我的頭髮，劃破我的皮膚。」",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          ContentTC = "那你為什麼還在寫？",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001
        },
        [51004916] = {
          ContentTC = "（露娜低頭在紙上寫著什麽。）",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917
        },
        [51004917] = {
          ContentTC = "「憋在心裡太難受。」",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          ContentTC = "「是啊。什麽都改變不了，我甚至寫了都不敢給別人看，但我還是忍不住想寫點什麽。」",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004919] = {
          ContentTC = "「我已經唱不了歌了，我怕如果有一天我什麽也不寫了，我就會弄丟最後一件珍貴的東西，那時我就真的什麽也沒有了。」",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004920] = {
          ContentTC = "不開心的話就多找點實在的事做吧，會讓自己舒服些。還有，你寫可以，下次記得收好吧，別再不小心弄丟了。",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001
        },
        [51004921] = {
          ContentTC = "（女人思索了良久，點了點頭。）",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          ContentTC = "「謝謝你還給我，好心人。這是給你的報酬。」",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          ContentTC = "「你謬贊了，我只是一個只敢在紙上發牢騷的膽小鬼，我連把這些東西給其他人看的勇氣都沒有。」",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          ContentTC = "你肯寫真心話，已經比大多數人勇敢了。只是下次收好吧，別再不小心弄丟了。",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001
        },
        [51004925] = {
          ContentTC = "（女人嘴唇勾出一絲微笑，她點點頭，你看到她雙眼噙著淚花。）",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926
        },
        [51004926] = {
          ContentTC = "「謝謝你還給我，好心人。這是給你的報酬。」",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
