        },
        [51005019] = {
          ContentTC = "在奉命送他回旅館的路上，他毫不猶豫地救治了一個倒在我們面前的卡戎，並托我照顧那個女孩。",
          DialogueId = 51005019,
          GUID = "7FAF8AEE",
          NextDialogue = 51005020,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain01_Start"
          }
        },
        [51005020] = {
          ContentTC = "他是一個優秀的醫生。不只是因為技藝，更因為……他救治病人的心意，從不因病人的身份有任何改變。",
          DialogueId = 51005020,
          GUID = "7FAF8B18",
          NextOptions = {
            [1] = 510050201,
            [2] = 510050202,
            [3] = 510050203
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51005021] = {
          ContentTC = "恩里克不在乎這些……至少，我對他的評價從沒變過。",
          DialogueId = 51005021,
          GUID = "7FAF8B42",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51005022] = {
          ContentTC = "這正是他光輝熠熠的地方。",
          DialogueId = 51005022,
          GUID = "7FAF8B6C",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Agree"
          },
          bForbidSkipOptions = true
        },
        [51005023] = {
          ContentTC = "我為發生在他身上的事情，感到深切的悲傷與遺憾。",
          DialogueId = 51005023,
          GUID = "7FAF8B96",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005024] = {
          ContentTC = "我只覺得做得不夠多。",
          DialogueId = 51005024,
          GUID = "7FAF8BC0",
          NextDialogue = 51005025,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005025] = {
          ContentTC = "恩里克先生並不希望和我產生太多的聯系，我也不能常常拜訪，否則，我和你也許早就見過了。",
          DialogueId = 51005025,
          GUID = "7FAF8BEA",
          NextDialogue = 51005026,
          SpeakNpcId = 700013
        },
        [51005026] = {
          ContentTC = "他也許同樣不希望我在他離世後頻繁拜訪，所以，這把鑰匙是時候物歸原主了。我會將它妥善放回恩里克先生的辦公桌，請您見證。",
          DialogueId = 51005026,
          GUID = "7FAF8C14",
          NextOptions = {
            [1] = 510050261
          },
          RestartTag = 51005026,
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005027] = {
          ContentTC = "（你什麽也沒想起來，或許只是你的錯覺。）",
          DialogueId = 51005027,
          GUID = "7FAF8C3E"
        },
        [51005028] = {
          ContentTC = "（你在瑪爾潔那裡得到的鑰匙，與萊娜那把可以打開修普諾斯之家的鑰匙非常相似。）",
          DialogueId = 51005028,
          GUID = "7FAF8C68",
          NextDialogue = 51005029
        },
        [51005029] = {
          ContentTC = "（你想起你曾在恩里克身上見過它。它應該是在那夜的混亂中丟失了，然後被瑪爾潔無意間拾得。）",
          DialogueId = 51005029,
          GUID = "7FAF8C92",
          NextOptions = {
            [1] = 510050291
          }
        },
        [51005030] = {
          ContentTC = "恩里克有一個存放重要文件的箱子，我想，用這把鑰匙可以打開它。",
          DialogueId = 51005030,
          GUID = "7FAF8CBC",
          NextDialogue = 51005031,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_Start"
          }
        },
        [51005031] = {
          ContentTC = "恩里克先生曾委托下仆，如果有不幸降臨在他的身上，就打開那個箱子，宣讀他的遺囑。",
          DialogueId = 51005031,
          GUID = "7FAF8CE6",
          NextDialogue = 51005032,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_End"
          }
        },
        [51005032] = {
          ContentTC = "我在宅子裡找不到那把鑰匙，沒想到它在您手上。感謝您幫忙保管它。",
          DialogueId = 51005032,
          GUID = "7FAF8D10",
          NextDialogue = 51005033,
          SpeakNpcId = 700013
        },
        [51005033] = {
          ContentTC = "如果可以，請您作為見證，督促下仆嚴格按照與恩里克先生的約定行事。",
          DialogueId = 51005033,
          GUID = "7FAF8D3A",
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005034] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（箱子打開，女僕取出了恩里克的遺囑，在你的見證之下，她莊重地誦讀著。）",
          DialogueId = 51005034,
          GUID = "7FAF8D64",
          NextDialogue = 51005035
        },
        [51005035] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（恩里克也許早就預料到了今天的悲劇，他的遺囑仍然冷靜，只有對女兒的死亡仍舊遺憾，以及——）",
          DialogueId = 51005035,
          GUID = "7FAF8D8E",
          NextDialogue = 51005036
        },
        [51005036] = {
          Camera = "-3490.197266,-340.706116,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「在我死後，本人名下的所有房屋產權將移交給萊娜·貝爾女士——」",
          DialogueId = 51005036,
          FinalCamera = "-2771.669922,-330.52002,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DB8",
          NextDialogue = 51005037,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005037] = {
          Camera = "-956.953125,124.710449,851.333984,0.000029,-16.600037,26.61047,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「以感謝她多年來對修普諾斯之家及卡戎病人的付出。」",
          DialogueId = 51005037,
          FinalCamera = "-938.859375,88.569275,851.333984,0.000038,-16.600002,26.610426,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DE2",
          NextDialogue = 51005038,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005038] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "「由衷感謝貝爾女士所做的一切，她是一位令人尊敬的女士。」",
          DialogueId = 51005038,
          GUID = "7FAF8E0C",
          NextDialogue = 51005039,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005039] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 51005039,
          GUID = "7FAF8E36",
          NextDialogue = 510050391,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51005040] = {
          ContentTC = "（你獨自走出了恩里克的辦公室。泣不成聲的萊娜女士需要獨處一會，至少在這段時間，不要打斷她的悲傷。）",
          DialogueId = 51005040,
          Duration = 4,
          GUID = "7FAF8E60",
          NextDialogue = 51005041
        },
        [51005041] = {
          ContentTC = "（現在，你有一位新的房東太太了。）",
          DialogueId = 51005041,
          Duration = 2,
          GUID = "7FAF8E8A"
        },
        [51005042] = {
          Camera = "460.455078,-127.329834,335.509766,0.000047,-28.799341,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（萊娜女士熟悉修普諾斯之家的一草一木，你們順利地找到箱子，而在箱子邊，放著一個突兀的木盒。）",
          DialogueId = 51005042,
          FinalCamera = "460.455078,-148.0,335.509766,0.000054,-28.799347,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EB4",
          NextDialogue = 51005043,
          ToFinalCameraBlendTime = 7
        },
        [51005043] = {
          Camera = "-372.582031,8.945923,112.0,0.0,0.0,0.208069,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（你先打開了那奇怪的木盒，一張筆跡娟秀的信出現在你們眼前，你將信拿出，一字一句地念了出來。）",
          DialogueId = 51005043,
          FinalCamera = "-350.582031,9.078125,112.0,0.0,0.0,0.408069,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EDE",
          NextDialogue = 51005044,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "700098:n(100001)"
          }
        },
        [51005044] = {
          ContentTC = "當你看到這封信的時候，我們已經不在「修普諾斯之家」了。\n那晚賽琪的事驚動了衛戍部隊，我們已經無法留在冰湖城。\n所以，在衛戍部隊調查到這裡前，我已經帶著大家離開了。\n請不要為我們悲傷，也無需憂心我們可能會因突然的穢蝕而傷害無辜者。\n我們會去向曠野，朝著誰也不曾知曉的遠方流浪。\n流浪的終點也許是死亡，也許是一個尚未出現的奇蹟——\n我們會懷抱希望，直到最後一刻。\n這是她曾教會我們的。\n以及，謝謝你曾為我們做過的一切。\n——艾莉莎·泰勒",
          DialogueId = 51005044,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_200208;content:Reading_Content_200208}",
          GUID = "7FAF8F08",
          NextDialogue = 51005045
        },
        [51005045] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這樣啊……孩子們都安然……離開了。",
          DialogueId = 51005045,
          GUID = "7FAF8F32",
          NextDialogue = 51005046,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700098:p(140)"
          }
        },
        [51005046] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "（萊娜說完沉默了許久，才吃力地將鑰匙插入鎖孔。你看著她的手顫抖著，一次次從鑰匙上滑落。）",
          DialogueId = 51005046,
          GUID = "7FAF8F5C",
          NextDialogue = 51005047
        },
        [51005047] = {
          ContentTC = "……我們一起來吧。",
          DialogueId = 51005047,
          GUID = "7FAF8F86",
          IsBlack = 1,
          NextDialogue = 51005048,
          SpeakNpcId = 100001
        },
        [51005048] = {
          ContentTC = "抱歉，謝謝。",
          DialogueId = 51005048,
          GUID = "7FAF8FB0",
          IsBlack = 1,
          SpeakNpcId = 700013
        },
        [51005101] = {
          ContentTC = "這不是{nickname}嗎？",
          DialogueId = 51005101,
          GUID = "7FAF9862",
          NextDialogue = 51005102,
          SpeakNpcId = 700115
        },
        [51005102] = {
          ContentTC = "上回的事多謝你了！貧民窟那幾家人拿到生活費以後，也一直托我向你致謝呢！",
          DialogueId = 51005102,
          GUID = "7FAF988C",
          NextOptions = {
            [1] = 51005103
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005103] = {
          ContentTC = "這沒什麽。",
          DialogueId = 51005103,
          GUID = "7FAF98B6",
          NextDialogue = 51005104
        },
        [51005104] = {
          ContentTC = "別謙虛呀，我都好久沒碰上你這種又熱心又能幹又有禮貌的人了！",
          DialogueId = 51005104,
          GUID = "7FAF98E0",
          NextDialogue = 51005105,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005105] = {
          ContentTC = "在冰湖城的這段時間，感覺怎麽樣呀？",
          DialogueId = 51005105,
          GUID = "7FAF990A",
          NextOptions = {
            [1] = 510051051,
            [2] = 510051052,
            [3] = 510051053
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          },
          bForbidSkipOptions = true
        },
        [51005106] = {
          ContentTC = "雖說我也覺得人生就是從始發點奔向目的地，但這麽忽視路邊的風景也很可惜！",
          DialogueId = 51005106,
          GUID = "7FAF9934",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005107] = {
          ContentTC = "我懂！！！剛來冰湖城的時候我也這麽覺得！這兒的規矩莫名其妙，這兒的人也怪怪的！",
          DialogueId = 51005107,
          GUID = "7FAF995E",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005108] = {
          ContentTC = "那看來你老家治安也不怎麽樣……你不會也是逃難來的吧？",
          DialogueId = 51005108,
          GUID = "7FAF9988",
          NextDialogue = 51005109,
          SpeakNpcId = 700115
        },
        [51005109] = {
          ContentTC = "算了，不說這些了。",
          DialogueId = 51005109,
          GUID = "7FAF99B2",
          NextDialogue = 51005110,
          SpeakNpcId = 700115
        },
        [51005110] = {
          ContentTC = "還是來看看我剛進的貨吧！都是些稀奇古怪的小玩意，要是有喜歡的，我就給你打個八折，就當是上次抓賊的謝禮了~",
          DialogueId = 51005110,
          GUID = "7FAF99DC",
          NextDialogue = 51005111,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005111] = {
          ContentTC = "（你俯下身，仔細觀察起瑪爾潔「剛進的貨」。不大的木架上堆滿雜物，大多都有明顯的使用痕跡，但都很幹凈，顯然被精心擦拭過。）",
          DialogueId = 51005111,
          GUID = "7FAF9A06",
          NextOptions = {
            [1] = 510051111,
            [2] = 510051112,
            [3] = 510051113
          },
          TalkActionId = {
            [1] = "700115:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005112] = {
          ContentTC = "重點是樂趣，光算賬多沒意思！",
          DialogueId = 51005112,
          GUID = "7FAF9A30",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005113] = {
          ContentTC = "當然不是！我可是良民！這些都是被主人丟掉的寶貝。任由它們浪費才是真正的犯罪呢，我只是想給它們都找一個家！",
          DialogueId = 51005113,
          GUID = "7FAF9A5A",
          NextDialogue = 51005115,
          SpeakNpcId = 700115
        },
        [51005114] = {
          ContentTC = "嘿嘿，商業機密！",
          DialogueId = 51005114,
          GUID = "7FAF9A84",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005115] = {
          ContentTC = "（盛情難卻。你翻找著瑪爾潔的「貨物攤」，試圖從中找出有價值的東西。）",
          DialogueId = 51005115,
          GUID = "7FAF9AAE",
          NextOptions = {
            [1] = 510051151,
            [2] = 510051152,
            [3] = 510051153
          },
          RestartTag = 51005115,
          bForbidSkipOptions = true
        },
        [51005116] = {
          ContentTC = "實在沒有喜歡的就算啦！等下次進貨了再來看看吧。",
          DialogueId = 51005116,
          GUID = "7FAF9AD8",
          SpeakNpcId = 700115
        },
        [51005117] = {
          ContentTC = "不愧是你，一眼就看出這東西的珍貴之處，看來你也有偵探的靈敏嗅覺！",
          DialogueId = 51005117,
          GUID = "7FAF9B02",
          NextOptions = {
            [1] = 51005118
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005118] = {
          ContentTC = "偵探？這都是哪跟哪啊……",
          DialogueId = 51005118,
          GUID = "7FAF9B2C",
          NextDialogue = 51005119
        },
        [51005119] = {
          ContentTC = "你看中的那幾個，是最不值錢的，但也是最值錢的。最不值錢就是字面意義上的，賣不出幾個銅幣，其他人來了看都不看一眼。",
          DialogueId = 51005119,
          GUID = "7FAF9B56",
          NextDialogue = 51005120,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_Start"
          }
        },
        [51005120] = {
          ContentTC = "最珍貴則是因為……這幾樣貨看起來都很有「故事」！你不就是因為這個才挑中它們的嗎？",
          DialogueId = 51005120,
          GUID = "7FAF9B80",
          NextDialogue = 51005121,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_End"
          }
        },
        [51005121] = {
          ContentTC = "只要你有足夠的耐心和細致入微的觀察能力，就能調查出這些寶貝背後的故事和秘密！",
          DialogueId = 51005121,
          GUID = "7FAF9BAA",
          NextDialogue = 51005122,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005122] = {
          ContentTC = "可別小看垃圾桶，很多案件與傳聞的真相就藏在這些小角落裡！我就是靠著垃圾桶，一點一點了解這座城市的。",
          DialogueId = 51005122,
          GUID = "7FAF9BD4",
          NextDialogue = 51005123,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005123] = {
          ContentTC = "好奇了吧！你也想更了解這座城市吧！那就請這裡付賬！",
          DialogueId = 51005123,
          GUID = "7FAF9BFE",
          NextDialogue = 51005124,
