        },
        [51005213] = {
          Camera = "12.572754,75.52832,130.532715,-0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "外鄉人，歡迎來到冰湖城！",
          DialogueId = 51005213,
          FacialId = {
            [1] = "700127:Happy02"
          },
          GUID = "7FAFAAC2",
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Talk02_Start"
          }
        },
        [51005301] = {
          ContentTC = "只要消毒得當，就能成為一盤好菜！",
          DialogueId = 51005301,
          GUID = "7FAFB932",
          NextDialogue = 51005302,
          SpeakNpcId = 700116
        },
        [51005302] = {
          ContentTC = "……腥味是沒了，但這些水產本身的鮮甜味卻沒有激發出來……",
          DialogueId = 51005302,
          GUID = "7FAFB95C",
          NextDialogue = 51005303,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Think_Start"
          }
        },
        [51005303] = {
          ContentTC = "（面前這位男人語速飛快，布滿血絲的雙眼死死盯著手中的冊子和身旁不知名的魚蝦，用還黏著蔥葉的雙手飛快地寫著什麽。）",
          DialogueId = 51005303,
          GUID = "7FAFB986",
          NextOptions = {
            [1] = 510053031,
            [2] = 510053032
          },
          TalkActionId = {
            [1] = "700116:Think_End"
          },
          bForbidSkipOptions = true
        },
        [51005304] = {
          ContentTC = "（裝訂環上的少量銹跡說明這本老舊冊子近期才經歷過不怎麽細致的清理。）",
          DialogueId = 51005304,
          GUID = "7FAFB9B0",
          NextDialogue = 51005305
        },
        [51005305] = {
          ContentTC = "（湊近觀察，勉強從雜亂的圖形與線條間拼湊出幾個香料與烹調方式的詞組，想來男人手中的大概是一本食譜。）",
          DialogueId = 51005305,
          GUID = "7FAFB9DA",
          NextDialogue = 51005307
        },
        [51005306] = {
          ContentTC = "（現在最好的選擇就是轉身離開，但身體在執行的時候卻踩到了流淌在地面的粘液發出噗呲的悶響。）",
          DialogueId = 51005306,
          GUID = "7FAFBA04",
          NextDialogue = 51005307
        },
        [51005307] = {
          ContentTC = "（現在，這名男人註意到你了。）",
          DialogueId = 51005307,
          GUID = "7FAFBA2E",
          NextDialogue = 51005308
        },
        [51005308] = {
          ContentTC = "……你是？",
          DialogueId = 51005308,
          GUID = "7FAFBA58",
          NextDialogue = 51005309,
          SpeakNpcId = 700116
        },
        [51005309] = {
          ContentTC = "路過的狩月人。",
          DialogueId = 51005309,
          GUID = "7FAFBA82",
          NextDialogue = 51005310,
          SpeakNpcId = 100001
        },
        [51005310] = {
          ContentTC = "既然是狩月人的話，你願不願意接受我的委托，與我一起做出更加美味的菜品？",
          DialogueId = 51005310,
          GUID = "7FAFBAAC",
          NextOptions = {
            [1] = 51000001,
            [2] = 51000002
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51005311] = {
          ContentTC = "萬分感謝。這第一道菜，是在漁民間流傳的腌製活魚活蝦的方法上，進行改良的。我這還有些餌料，麻煩你去釣一些用來腌製的東西吧。",
          DialogueId = 51005311,
          GUID = "7FAFBAD6",
          NextOptions = {
            [1] = 510053111,
            [2] = 510053112
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005312] = {
          ContentTC = "對啊！我會在這期間做好烹飪與消毒的準備。餌料用光了的話就再回來找我吧。",
          DialogueId = 51005312,
          GUID = "7FAFBB00",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005313] = {
          ContentTC = "這裡天然的鹽泉似乎能提供醃制所需的材料，採集一些帶回去吧。",
          DialogueId = 51005313,
          GUID = "7FAFBB2A",
          SpeakNpcId = 100001
        },
        [51005314] = {
          ContentTC = "釣到了，回去找馬庫斯吧。",
          DialogueId = 51005314,
          GUID = "7FAFBB54",
          SpeakNpcId = 100001
        },
        [51005315] = {
          ContentTC = "釣到了，回去找馬庫斯吧。",
          DialogueId = 51005315,
          GUID = "7FAFBB7E",
          SpeakNpcId = 100001
        },
        [51005401] = {
          ContentTC = "滾滾蔥葉切段備用……魚蝦沖凈後加入鹽、醋，考慮到冰湖城人的口味也許應該再加點糖……",
          DialogueId = 51005401,
          GUID = "7FAFC99A",
          NextDialogue = 51005402,
          SpeakNpcId = 700116
        },
        [51005402] = {
          ContentTC = "（馬庫斯木訥地接過原料，一邊念叨著烹調方式一邊拖著它們消失在街角。）",
          DialogueId = 51005402,
          GUID = "7FAFC9C4"
        },
        [51005403] = {
          ContentTC = "（一段時間後，馬庫斯不知從哪裡突然沖出，直到摔倒在雪地裡才意識到自己的失態，尷尬地笑著用手拂去身上的塵土。）",
          DialogueId = 51005403,
          GUID = "7FAFC9EE",
          NextDialogue = 51005404
        },
        [51005404] = {
          ContentTC = "……抱歉。",
          DialogueId = 51005404,
          GUID = "7FAFCA18",
          NextDialogue = 51005405,
          SpeakNpcId = 700116
        },
        [51005405] = {
          ContentTC = "你也嘗嘗味道怎麽樣？能不能感受到冰湖城的特色風味？",
          DialogueId = 51005405,
          GUID = "7FAFCA42",
          NextDialogue = 51005406,
          SpeakNpcId = 700116
        },
        [51005406] = {
          ContentTC = "（他從懷裡掏出一包密封的魚蝦，浸潤在黝黑的醬汁中隱隱散發著晶瑩的光芒。即使隔著密封的薄膜也能聞到濃郁的醬香。）",
          DialogueId = 51005406,
          GUID = "7FAFCA6C",
          NextOptions = {
            [1] = 510054061,
            [2] = 510054062,
            [3] = 510054063
          },
          TalkActionId = {
            [1] = "700116:Give"
          }
        },
        [51005407] = {
          ContentTC = "不要用那麽古板的思維看待菜肴。一個人一生中如果不挑戰一下非常規食材，那麽他人生的樂趣就減少了一半。",
          DialogueId = 51005407,
          GUID = "7FAFCA96",
          NextDialogue = 51005410,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Disagree"
          }
        },
        [51005408] = {
          ContentTC = "哈哈，算了算了，看你都快哭出來了。",
          DialogueId = 51005408,
          GUID = "7FAFCAC0",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005409] = {
          ContentTC = "哼。還好不是所有人都像你一樣，對食材的多樣性心存偏見。",
          DialogueId = 51005409,
          GUID = "7FAFCAEA",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005410] = {
          ContentTC = "嗯……總之，還有些改良空間。",
          DialogueId = 51005410,
          GUID = "7FAFCB14",
          NextDialogue = 51005411,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005411] = {
          ContentTC = "之後第二道菜也拜托你了，我的美食搭檔！",
          DialogueId = 51005411,
          GUID = "7FAFCB3E",
          SpeakNpcId = 700116
        },
        [51005501] = {
          ContentTC = "燉的方式更暖胃，作為開胃菜剛剛好，現在還缺……",
          DialogueId = 51005501,
          GUID = "7FAFDA02",
          NextDialogue = 51005502,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Think_Start"
          }
        },
        [51005502] = {
          ContentTC = "（馬庫斯泛白的臉即使在冰湖的冷風吹拂下也不見一絲血色，不註意觀察甚至會以為這是一尊被人遺棄的冰雕。）",
          DialogueId = 51005502,
          GUID = "7FAFDA2C",
          NextDialogue = 51005503
        },
        [51005503] = {
          ContentTC = "（但他完全沒關註環境的惡劣與身體的哀嚎。）",
          DialogueId = 51005503,
          GUID = "7FAFDA56",
          NextDialogue = 51005504
        },
        [51005504] = {
          ContentTC = "（他只是專註地念出一個個原料、調味與烹飪方式，又快速將其否掉，在腦海中拼湊著通向極致菜肴的道路。）",
          DialogueId = 51005504,
          GUID = "7FAFDA80",
          NextDialogue = 51005505,
          TalkActionId = {
            [1] = "700117:Think_End"
          }
        },
        [51005505] = {
          ContentTC = "搭檔，你來了！",
          DialogueId = 51005505,
          GUID = "7FAFDAAA",
          NextDialogue = 51005506,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005506] = {
          ContentTC = "話不多說，現在還差些肥霜脊魚，這種魚不怎麼常見，但我相信搭檔你可以的，拜託了！",
          DialogueId = 51005506,
          GUID = "7FAFDAD4",
          NextDialogue = 51005507,
          SpeakNpcId = 700117
        },
        [51005507] = {
          ContentTC = "（雖然難度更高，但你反而鬆了一口氣。至少這次應該不會被要求試吃生食了。）",
          DialogueId = 51005507,
          GUID = "7FAFDAFE"
        },
        [51005508] = {
          ContentTC = "垂釣了好一陣子，總算獲得了馬庫斯所需的肥霜脊魚。",
          DialogueId = 51005508,
          Duration = 3,
          GUID = "7FAFDB28"
        },
        [51005601] = {
          ContentTC = "（馬庫斯站在原地剝著北風莓的果皮，一言不發，愈發像是一尊冰雕。但不時抽動的眉頭表明，他正在忍受著某種先前沒有的刺痛。）",
          DialogueId = 51005601,
          GUID = "7FAFEA6A",
          NextOptions = {
            [1] = 510056011,
            [2] = 510056012
          },
          bForbidSkipOptions = true
        },
        [51005602] = {
          ContentTC = "（果皮上有血漬與泥土，其中幾枚還因用力過猛而發生了變形，結合馬庫斯手掌上嶄新的劃痕來看，這些北風莓應是馬庫斯剛才親自攀上附近的山崖采摘的。）",
          DialogueId = 51005602,
          GUID = "7FAFEA94",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005603] = {
          ContentTC = "（鮮血將馬庫斯一側的衣服浸透，應是剛才受過什麽傷。雖已止血，但對他的傷勢來說並沒有太大幫助。）",
          DialogueId = 51005603,
          GUID = "7FAFEABE",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005604] = {
          ContentTC = "這些血……",
          DialogueId = 51005604,
          GUID = "7FAFEAE8",
          NextDialogue = 51005605,
          SpeakNpcId = 100001
        },
        [51005605] = {
          ContentTC = "小事，摘北風莓的時候摔傷了而已。看你的樣子，肥霜脊魚到手了啊，我就知道你能做到，謝了。",
          DialogueId = 51005605,
          GUID = "7FAFEB12",
          NextDialogue = 51005606,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005606] = {
          ContentTC = "（馬庫斯不願過多討論自己的傷勢，擡手將北風莓丟進鍋裡，攪拌均勻後舀出一勺湯汁輕抿了一口。）",
          DialogueId = 51005606,
          GUID = "7FAFEB3C",
          NextDialogue = 51005607
        },
        [51005607] = {
          ContentTC = "新鮮的北風莓，加入湯汁的話果然讓香氣更濃了。",
          DialogueId = 51005607,
          GUID = "7FAFEB66",
          NextDialogue = 51005608,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Agree"
          }
        },
        [51005608] = {
          ContentTC = "那肥霜脊魚也得換種處理方式……",
          DialogueId = 51005608,
          GUID = "7FAFEB90",
          NextDialogue = 51005609,
          SpeakNpcId = 700117
        },
        [51005609] = {
          ContentTC = "（馬庫斯拖著受傷的身體完成剔油、翻焯、煨燉等一道道復雜又漫長的處理工序。）",
          DialogueId = 51005609,
          GUID = "7FAFEBBA",
          NextDialogue = 51005610
        },
        [51005610] = {
          ContentTC = "（隨著食物的香味在一點一滴的積累中迸發，他才從篝火旁起身，乘起滿滿一碗料理，期待著食客的評價。）",
          DialogueId = 51005610,
          GUID = "7FAFEBE4",
          NextDialogue = 51005611
        },
        [51005611] = {
          ContentTC = "咳咳……完成了，你嘗嘗夠好吃、夠有特色嗎？",
          DialogueId = 51005611,
          GUID = "7FAFEC0E",
          NextOptions = {
            [1] = 51005612
          },
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Give"
          }
        },
        [51005612] = {
          ContentTC = "好吃，很暖和。",
          DialogueId = 51005612,
          GUID = "7FAFEC38",
          NextDialogue = 51005613
        },
        [51005613] = {
          ContentTC = "太好了，我回趟內城，給老板看看我們的成果！",
          DialogueId = 51005613,
          GUID = "7FAFEC62",
          NextDialogue = 51005614,
          SpeakNpcId = 700117
        },
        [51005614] = {
          ContentTC = "多謝啦，搭檔！這可是我們一起完成的菜品。大伙兒一定會喜歡的！老板也一定會贊不絕口！",
          DialogueId = 51005614,
          GUID = "7FAFEC8C",
          SpeakNpcId = 700117
        },
        [51005701] = {
          ContentTC = "…………",
          DialogueId = 51005701,
          GUID = "7FAFFAD2",
          NextDialogue = 51005702
        },
        [51005702] = {
          ContentTC = "（第三次遇到馬庫斯時，他就靜靜地坐在那裡，腿上放著一份飯盒。他的神情憔悴，皮膚幹癟，似是很久未曾入睡。）",
          DialogueId = 51005702,
          GUID = "7FAFFAFC",
          NextDialogue = 51005703
        },
        [51005703] = {
          ContentTC = "（身上的傷口依然沒有得到妥善處置，若是在炎熱的城市說不定那些傷口都會開始散發出腐臭的氣息。）",
          DialogueId = 51005703,
          GUID = "7FAFFB26",
          NextOptions = {
            [1] = 51005704
          }
        },
        [51005704] = {
          ContentTC = "……你還好嗎，老板怎麽說？",
          DialogueId = 51005704,
          GUID = "7FAFFB50",
          NextDialogue = 51005705
        },
        [51005705] = {
          ContentTC = "…………",
          DialogueId = 51005705,
          GUID = "7FAFFB7A",
          LookAt = {
            [1] = "700121:n(0)"
          },
          NextDialogue = 51005706,
          SpeakNpcId = 700121
        },
        [51005706] = {
          ContentTC = "……哈哈，他看都沒看，說我之前做的菜一直賺不了大錢，也不準備再雇傭我了。",
          DialogueId = 51005706,
          GUID = "7FAFFBA4",
          NextOptions = {
            [1] = 51005707
          },
          SpeakNpcId = 700121
        },
        [51005707] = {
          ContentTC = "…………",
          DialogueId = 51005707,
          GUID = "7FAFFBCE",
          NextDialogue = 51005708
        },
        [51005708] = {
          ContentTC = "不重要，最後一道菜我也完成了，要不要嘗嘗看？",
          DialogueId = 51005708,
          GUID = "7FAFFBF8",
          NextDialogue = 51005709,
          SpeakNpcId = 700121
        },
        [51005709] = {
          ContentTC = "（馬庫斯顫抖著舉起雙手，將便當打開，燉菜與碎肉餅的香味便混在一起衝出飯盒，挑逗著食慾。）",
          DialogueId = 51005709,
          GUID = "7FAFFC22",
          NextDialogue = 51005710
        },
        [51005710] = {
          ContentTC = "（雖然不是大人物們常吃的肉排，卻也能支持人們一整天的勞作。幾枚被雕刻成星星形狀的薯餅點綴其間，為菜餚注入了別樣的心意。）",
          DialogueId = 51005710,
          GUID = "7FAFFC4C",
          NextDialogue = 51005711
        },
        [51005711] = {
          ContentTC = "（品嘗一口，這些食物平凡的外表下綻放出無法言喻的美味，讓全身都充滿活力，精神也為之振奮，甚至不再畏懼冰湖的寒冬。）",
          DialogueId = 51005711,
          GUID = "7FAFFC76",
          NextDialogue = 51005712
        },
        [51005712] = {
          ContentTC = "（而在飯盒的下方，整齊地疊放著一張布滿塗改痕跡的食譜。他點了點頭，示意食譜現在起有了新的主人，並微笑等待著食客的評價。）",
          DialogueId = 51005712,
          GUID = "7FAFFCA0",
          NextOptions = {
            [1] = 510057121,
            [2] = 510057122
          },
          bForbidSkipOptions = true
        },
        [51005713] = {
          ContentTC = "謝謝你願意吃我做的菜……",
          DialogueId = 51005713,
          GUID = "7FAFFCCA",
          NextDialogue = 51005714,
          SpeakNpcId = 700121
        },
        [51005714] = {
          ContentTC = "（他長呼一口氣，手臂無力地垂下，緩緩閉上了雙眼。）",
          DialogueId = 51005714,
          GUID = "7FAFFCF4",
          NextDialogue = 51005715
        },
        [51005715] = {
          ContentTC = "這段時間辛苦你陪我到處收集食材了，好好休息一下吧……我也是……",
          DialogueId = 51005715,
          GUID = "7FAFFD1E",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005716] = {
          ContentTC = "即使失敗這麽多次，你也願意相信我能做出美味的食物啊……謝謝……你願意吃我做的菜。",
          DialogueId = 51005716,
          GUID = "7FAFFD48",
          NextDialogue = 51005717,
          SpeakNpcId = 700121
        },
        [51005717] = {
          ContentTC = "（他長呼一口氣，手臂無力地垂下，緩緩閉上了雙眼。）",
          DialogueId = 51005717,
          GUID = "7FAFFD72",
          NextDialogue = 51005718
        },
        [51005718] = {
          ContentTC = "為了搭檔，我自然要再努力一把才是。但現在，就讓我稍微休息一下吧……",
          DialogueId = 51005718,
          GUID = "7FAFFD9C",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005719] = {
          ContentTC = "（從馬庫斯滿足的笑容來看，他應該是找到了心中最想要的評價吧。）",
          DialogueId = 51005719,
          GUID = "7FAFFDC6"
        },
