          ContentTC = "但是，那個靈魂的聲音非常溫柔。沒有哀嘆，也沒有憤怒與不甘，而是在訴說感謝以及……祝福。",
          DialogueId = 51006817,
          GUID = "7FB0B1EA",
          NextDialogue = 51006818,
          SpeakNpcId = 700133,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          TalkActionId = {
            [1] = "700133:Talk02_Start"
          }
        },
        [51006818] = {
