        },
        [51006827] = {
          Camera = "-108.535156,-156.035156,123.041016,0.000277,-1.200986,70.850563,50.0,262.367676,false,Manual,11.670671",
          ContentTC = "我想，去往了霧海的那個靈魂，也一定會希望……當你回憶起與她共同經歷的時日，你是面帶笑意的，而非哀憐和悲泣。",
          DialogueId = 51006827,
          GUID = "7FB0B38E",
          NextOptions = {
