          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007624] = {
          ContentTC = "你知道嗎，雖然大家都說老鼠是討人厭的生物，不過據我觀察，他們其實很有意思喔！",
          DialogueId = 51007624,
          GUID = "7FB13650",
          NextDialogue = 51007625,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007625] = {
          ContentTC = "我曾經在這裡見到過一隻非常威風的大老鼠，很像故事裡說的「老鼠戰士」。",
          DialogueId = 51007625,
          GUID = "7FB1367A",
          NextDialogue = 51007626,
          SpeakNpcId = 700204
        },
        [51007626] = {
          ContentTC = "「老鼠戰士」本來只是一隻天生瘦弱的小老鼠，但它不斷克服困難，勇敢戰鬥，最終成為保護族群的大英雄！",
          DialogueId = 51007626,
          GUID = "7FB136A4",
          NextDialogue = 51007627,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007627] = {
          ContentTC = "我見到的那隻大老鼠身上有很多傷疤，那一定就是它英勇戰鬥的證明。說起來，它還背著一個奇怪的小瓶子呢，也許那是什麼特別的道具吧……",
          DialogueId = 51007627,
          GUID = "7FB136CE",
          NextOptions = {
            [1] = 51007628,
            [2] = 51007631,
            [3] = 51007636
          },
          SpeakNpcId = 700204
        },
        [51007628] = {
          ContentTC = "那也許是實驗道具。",
          DialogueId = 51007628,
          GUID = "7FB136F8",
          ImprPlusId = 1003,
          NextDialogue = 51007629
        },
        [51007629] = {
          ContentTC = "有道理，也許是什麼人在用老鼠做實驗……這麼一想有點可怕……",
          DialogueId = 51007629,
          GUID = "7FB13722",
          NextDialogue = 51007630,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007630] = {
          ContentTC = "不過，它勇敢地接受了自己的命運，這正是英雄氣概的體現吧！只可惜……",
          DialogueId = 51007630,
          GUID = "7FB1374C",
          NextDialogue = 51007638,
          SpeakNpcId = 700204
        },
        [51007631] = {
          ContentTC = "就像是故事照進了現實一樣，很有趣。",
          DialogueId = 51007631,
          GUID = "7FB13776",
          ImprPlusId = 1004,
          NextDialogue = 51007632
        },
        [51007632] = {
          ContentTC = "嘿嘿，我也這麼覺得！",
          DialogueId = 51007632,
          GUID = "7FB137A0",
          NextDialogue = 51007633,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007633] = {
          ContentTC = "哎，只可惜……你再也沒機會見到它了。",
          DialogueId = 51007633,
          GUID = "7FB137CA",
          NextOptions = {
            [1] = 51007634,
            [2] = 51007635
          },
          SpeakNpcId = 700204
        },
        [51007634] = {
          ContentTC = "為什麼？",
          DialogueId = 51007634,
          GUID = "7FB137F4",
          NextDialogue = 51007638
        },
        [51007635] = {
          ContentTC = "這話聽起來怎麼像是你要把我滅口……",
          DialogueId = 51007635,
          GUID = "7FB1381E",
          NextDialogue = 51007638
        },
        [51007636] = {
          ContentTC = "聽上去感覺它能把你吃了。",
          DialogueId = 51007636,
          GUID = "7FB13848",
          ImprPlusId = 1005,
          NextDialogue = 51007637
        },
        [51007637] = {
          ContentTC = "什麼嘛，它可是一隻好老鼠，從來沒有攻擊過我！而且，它也已經不在了……",
          DialogueId = 51007637,
          GUID = "7FB13872",
          NextDialogue = 51007638,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007638] = {
          ContentTC = "幾天前，我親眼看見老鼠戰士被一個乞丐大叔抓走做成了烤肉串……嗚嗚……",
          DialogueId = 51007638,
          GUID = "7FB1389C",
          NextDialogue = 51007639,
          SpeakNpcId = 700204
        },
        [51007639] = {
          ContentTC = "唉……雖然很難過，但研究出現意外也是常有的事。我現在想看看那些它曾經關照過的小老鼠過得怎麼樣。",
          DialogueId = 51007639,
          GUID = "7FB138C6",
          NextDialogue = 51007640,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007640] = {
          ContentTC = "我們走吧，只要聽聲音應該就能找到老鼠窩的位置了！",
          DialogueId = 51007640,
          GUID = "7FB138F0",
          NextOptions = {
            [1] = 51007641,
            [2] = 51007643
          },
          SpeakNpcId = 700204
        },
        [51007641] = {
          ContentTC = "好。跟在我身後吧，我會保護你的。",
          DialogueId = 51007641,
          GUID = "7FB1391A",
          NextDialogue = 51007642
        },
        [51007642] = {
          ContentTC = "謝謝，你真可靠！",
          DialogueId = 51007642,
          GUID = "7FB13944",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007643] = {
          ContentTC = "我害怕，你來帶路吧。",
          DialogueId = 51007643,
          GUID = "7FB1396E",
          NextDialogue = 51007644
        },
        [51007644] = {
          ContentTC = "不會吧，你剛剛不是還很威風嗎……",
          DialogueId = 51007644,
          GUID = "7FB13998",
          NextDialogue = 51007645,
          SpeakNpcId = 700204
        },
        [51007645] = {
          ContentTC = "唉，沒辦法，那你就跟著我。",
          DialogueId = 51007645,
          GUID = "7FB139C2",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Sigh_Start"
          }
        },
        [51007646] = {
          ContentTC = "原來下水道裡面這麼寬闊……",
          DialogueId = 51007646,
          GUID = "7FB139EC",
          NextDialogue = 51007647,
          SpeakNpcId = 700204
        },
        [51007647] = {
          ContentTC = "（一團灰色的影子從角落裡閃現，似乎是隻小老鼠。）",
          DialogueId = 51007647,
          GUID = "7FB13A16",
          NextDialogue = 51007648
        },
        [51007648] = {
          ContentTC = "啊，你看到了嗎？那隻斷了一截尾巴的小老鼠我見過，它是老鼠戰士的同伴！",
          DialogueId = 51007648,
          GUID = "7FB13A40",
          NextDialogue = 51007649,
          SpeakNpcId = 700204
        },
        [51007649] = {
          ContentTC = "哎呀！怎麼溜走了？",
          DialogueId = 51007649,
          GUID = "7FB13A6A",
          NextDialogue = 51007650,
          SpeakNpcId = 700204
        },
        [51007650] = {
          ContentTC = "它好像不記得我啊……",
          DialogueId = 51007650,
          GUID = "7FB13A94",
          NextDialogue = 51007651,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007651] = {
          ContentTC = "（男孩皺起了小小的眉頭，似乎陷入了思考。）",
          DialogueId = 51007651,
          GUID = "7FB13ABE",
          NextDialogue = 51007652
        },
        [51007652] = {
          ContentTC = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，你覺得動物有情感嗎？我很想弄明白，可是我聽不懂它們的語言……",
          DialogueId = 51007652,
          GUID = "7FB13AE8",
          NextOptions = {
            [1] = 51007653,
            [2] = 51007656
          },
          SpeakNpcId = 700204
        },
        [51007653] = {
          ContentTC = "只要你相信它們是有情感的，那就是有。",
          DialogueId = 51007653,
          GUID = "7FB13B12",
          ImprPlusId = 1004,
          NextDialogue = 51007654
        },
        [51007654] = {
          ContentTC = "不行不行，這說法也太主觀了，研究是要講證據的！",
          DialogueId = 51007654,
          GUID = "7FB13B3C",
          NextDialogue = 51007655,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007655] = {
          ContentTC = "或許我們可以通過觀察它們的行動來確認。",
          DialogueId = 51007655,
          GUID = "7FB13B66",
          NextDialogue = 51007658,
          SpeakNpcId = 700204
        },
        [51007656] = {
          ContentTC = "情感並不是只通過語言傳達，你可以通過觀察它們的行為來探究這個問題。",
          DialogueId = 51007656,
          GUID = "7FB13B90",
          ImprPlusId = 1003,
          NextDialogue = 51007657
        },
        [51007657] = {
          ContentTC = "噢噢，你說得很對！",
          DialogueId = 51007657,
          GUID = "7FB13BBA",
          NextDialogue = 51007658,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007658] = {
          ContentTC = "讓我想想……假設這些小老鼠對老鼠戰士抱持尊敬之情，那麼它們應該也會像它一樣，非常勇敢、對人友好、愛護同伴吧？",
          DialogueId = 51007658,
          GUID = "7FB13BE4",
          NextDialogue = 51007659,
          SpeakNpcId = 700204
        },
        [51007659] = {
          ContentTC = "好，就讓我們去親眼驗證一下！剛才的小老鼠往拐角方向去了，我們快追上它吧。",
          DialogueId = 51007659,
          GUID = "7FB13C0E",
          SpeakNpcId = 700204
        },
        [51007660] = {
          ContentTC = "看，那就是老鼠們的家！",
          DialogueId = 51007660,
          GUID = "7FB13C38",
          NextDialogue = 51007661,
          SpeakNpcId = 700204
        },
        [51007661] = {
          ContentTC = "（老鼠窩中傳來「吱——吱——」的尖銳叫聲，伴隨著一陣微妙的臭氣，但西奧並沒有退縮。他睜大了眼睛，認真地觀察著老鼠們的行動。）",
          DialogueId = 51007661,
          GUID = "7FB13C62",
          NextDialogue = 51007662
        },
        [51007662] = {
          ContentTC = "（小老鼠們正在為了爭奪半塊餅而互相撕咬。）",
          DialogueId = 51007662,
          GUID = "7FB13C8C",
          NextDialogue = 51007663
        },
        [51007663] = {
          ContentTC = "啊……他們好像……不是太愛護同伴。",
          DialogueId = 51007663,
          GUID = "7FB13CB6",
          NextDialogue = 51007664,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007664] = {
          ContentTC = "（注意到有人接近，一部份小老鼠受到了驚嚇，慌張地逃走了。）",
          DialogueId = 51007664,
          GUID = "7FB13CE0",
          NextDialogue = 51007665
        },
        [51007665] = {
          ContentTC = "呃……他們好像……也不太勇敢。",
          DialogueId = 51007665,
          GUID = "7FB13D0A",
          NextDialogue = 51007666,
          SpeakNpcId = 700204
        },
        [51007666] = {
          ContentTC = "（剩下的幾隻老鼠忽然眼露凶光，朝你們發動了攻擊！）",
          DialogueId = 51007666,
          GUID = "7FB13D34",
          NextDialogue = 51007667
        },
        [51007667] = {
          ContentTC = "啊啊啊——怎麼平白無故地襲擊人呀，太沒有禮貌了吧？！",
          DialogueId = 51007667,
          GUID = "7FB13D5E",
          NextDialogue = 51007668,
          SpeakNpcId = 700204
        },
        [51007668] = {
          ContentTC = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，我們快逃！",
          DialogueId = 51007668,
          GUID = "7FB13D88",
          NextDialogue = 51007669,
          SpeakNpcId = 700204
        },
        [51007669] = {
          ContentTC = "你先逃，我來對付它們。",
          DialogueId = 51007669,
          GUID = "7FB13DB2",
          SpeakNpcId = 100001
        },
        [51007670] = {
          ContentTC = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，你回來啦！我剛才遠遠地觀察了你戰鬥的情況，你好厲害呀！",
          DialogueId = 51007670,
          GUID = "7FB13DDC",
          NextDialogue = 51007671,
          SpeakNpcId = 700204
        },
        [51007671] = {
          ContentTC = "「{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}擁有強大的戰鬥能力」……嗯，我記下了。",
          DialogueId = 51007671,
          GUID = "7FB13E06",
          NextDialogue = 51007672,
          SpeakNpcId = 700204
        },
        [51007672] = {
          ContentTC = "不過……唉，看來那些小老鼠並沒有情感吧……",
          DialogueId = 51007672,
          GUID = "7FB13E30",
          NextOptions = {
            [1] = 51007673,
            [2] = 51007675
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007673] = {
          ContentTC = "也許它們只是還在成長。",
          DialogueId = 51007673,
          GUID = "7FB13E5A",
          NextDialogue = 51007674
        },
        [51007674] = {
          ContentTC = "嗯……！你說得對，也許等它們長大之後，就會成為像老鼠戰士一樣優秀的大老鼠了。",
          DialogueId = 51007674,
          GUID = "7FB13E84",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007675] = {
          ContentTC = "也許是因為能教導它們的前輩已經不在了。",
          DialogueId = 51007675,
          GUID = "7FB13EAE",
          NextDialogue = 51007676
        },
        [51007676] = {
          ContentTC = "嗯……你說得對。真是讓人難過啊……希望就算失去了前輩的保護，它們也能堅強地長大。",
          DialogueId = 51007676,
          GUID = "7FB13ED8",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007677] = {
          ContentTC = "我已經做好記錄了，今天的調查就到這裡為止吧。",
          DialogueId = 51007677,
          GUID = "7FB13F02",
          NextDialogue = 51007678,
          SpeakNpcId = 700204
        },
        [51007678] = {
          ContentTC = "謝謝你陪我，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，你真是個聰明又可靠的人呀！看來他們說的那些關於狩月人的壞話並不是真的。",
          DialogueId = 51007678,
          GUID = "7FB13F2C",
          NextDialogue = 51007679,
          SpeakNpcId = 700204
        },
        [51007679] = {
          ContentTC = "要是所有卡戎都像你一樣友善就好啦……比如說，之前我在城北一家旅館門口看到了一個綠衣服姐姐，我和她打招呼，但她完全不理我。",
          DialogueId = 51007679,
          GUID = "7FB13F56",
          NextDialogue = 51007680,
          SpeakNpcId = 700204
        },
        [51007680] = {
          ContentTC = "她可能只是剛好沒看到吧。",
          DialogueId = 51007680,
          GUID = "7FB13F80",
          NextDialogue = 51007681,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007681] = {
          ContentTC = "嗯？你這麼說……難道是你認識那個姐姐嗎？",
          DialogueId = 51007681,
          GUID = "7FB13FAA",
          NextDialogue = 51007682,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007682] = {
          ContentTC = "是的。",
          DialogueId = 51007682,
          GUID = "7FB13FD4",
          NextDialogue = 51007683,
          SpeakNpcId = 100001
        },
        [51007683] = {
          ContentTC = "真了不起，你居然認識這麼多人……你是怎麼和他們溝通的，也教教我吧？",
          DialogueId = 51007683,
          GUID = "7FB13FFE",
          NextOptions = {
            [1] = 51007684,
            [2] = 51007686
          },
          SpeakNpcId = 700204
        },
        [51007684] = {
          ContentTC = "多和不同的人對話，累積技巧。",
          DialogueId = 51007684,
          GUID = "7FB14028",
          NextDialogue = 51007685
        },
        [51007685] = {
          ContentTC = "（西奧在本子上寫下：「{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}與人溝通的秘訣是：多和不同的人對話，累積技巧。」）",
          DialogueId = 51007685,
          GUID = "7FB14052",
          NextDialogue = 51007688
        },
        [51007686] = {
          ContentTC = "遇事不決武力威脅。",
          DialogueId = 51007686,
          GUID = "7FB1407C",
          NextDialogue = 51007687
        },
        [51007687] = {
          ContentTC = "（西奧在本子上寫下：「{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}與人溝通的秘訣是：遇事不決武力威脅。備註：這個方法似乎不適合我。」）",
          DialogueId = 51007687,
          GUID = "7FB140A6",
          NextDialogue = 51007688
        },
        [51007688] = {
          ContentTC = "嗯嗯……我記下了。",
          DialogueId = 51007688,
          GUID = "7FB140D0",
          NextDialogue = 51007689,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007689] = {
          ContentTC = "（不遠處忽然傳來了一陣急促的腳步聲，一位打扮得體的女士怒氣沖沖地朝你們走來。）",
          DialogueId = 51007689,
          GUID = "7FB140FA",
          IsBlack = 1
        },
        [51007690] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentTC = "西奧，你又跑到哪裡去了？天啊，瞧瞧你，怎麼把衣服弄得這麼髒！",
          DefaultLookAt = "1.0",
          DialogueId = 51007690,
          GUID = "7FB14124",
          NextDialogue = 51007691,
          SpeakNpcId = 700205,
          SpeakNpcName = "UI_CMNpc_Name_DeTiWoman",
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007691] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentTC = "媽媽……！我們剛才去下水道裡觀察老鼠了。",
          DefaultLookAt = "1.0",
          DialogueId = 51007691,
          GUID = "7FB1414E",
