            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007701] = {
          ContentTC = "（男孩被母親強行拽走了。在離開之前，他悄悄地回過頭，用口型對你說了一句「下次見」，並輕輕將一個小包裹扔給了你。）",
          DialogueId = 51007701,
          GUID = "7FB142F2",
          IsBlack = 1
        },
        [51007702] = {
          ContentTC = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比爾}{性别:哥哥|姐姐}，我在這裡！",
          DialogueId = 51007702,
          GUID = "7FB1431C",
          NextDialogue = 51007703,
          SpeakNpcId = 700204
        },
        [51007703] = {
          ContentTC = "（男孩躲在建築的陰影中，激動地向你揮手。）",
          DialogueId = 51007703,
          GUID = "7FB14346",
          NextDialogue = 51007704
        },
        [51007704] = {
          ContentTC = "又見面啦！",
          DialogueId = 51007704,
          GUID = "7FB14370",
          NextDialogue = 51007705,
          SpeakNpcId = 700204
        },
        [51007705] = {
          ContentTC = "我後來去打聽了哦，你的真名叫{nickname}對吧！真是的，怎麼能騙小孩呢？",
          DialogueId = 51007705,
          GUID = "7FB1439A",
          NextDialogue = 51007706,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Talk03_Start"
          }
        },
        [51007706] = {
          ContentTC = "上次真是對不起，我媽媽好像很怕卡戎。",
          DialogueId = 51007706,
          GUID = "7FB143C4",
          NextDialogue = 51007707,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007707] = {
          ContentTC = "那天回去以後，媽媽拉著我說了一大堆話，什麼「卡戎人都是好吃懶做的傢伙，是天生的罪犯，非常危險」之類的。",
          DialogueId = 51007707,
          GUID = "7FB143EE",
          NextDialogue = 51007708,
          SpeakNpcId = 700204
        },
        [51007708] = {
          ContentTC = "其他大人說的也都差不多。但是我越想越覺得奇怪呀！",
          DialogueId = 51007708,
          GUID = "7FB14418",
          NextDialogue = 51007709,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007709] = {
          ContentTC = "我想去了解卡戎人，但要麼是我不敢跟他們說話，要麼是他們不願意和我聊天，所以你能給我講講他們的生活嗎？",
          DialogueId = 51007709,
          GUID = "7FB14442",
          NextDialogue = 51007710,
          SpeakNpcId = 700204
        },
        [51007710] = {
          ContentTC = "比起說，不如直接帶你去看看吧。我這裡還有相機，你可以拍點照片帶回去好好想一想。",
          DialogueId = 51007710,
          GUID = "7FB1446C",
          NextDialogue = 51007711,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007711] = {
          ContentTC = "真的嗎？謝謝你！",
          DialogueId = 51007711,
          GUID = "7FB14496",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007712] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentTC = "你看這些破舊的小攤，每天天不亮的時候便會支起來，很多卡戎之民就是這樣謀生的。跟他們熟起來的話，說不定會給你打點折扣呢。",
          DialogueId = 51007712,
          GUID = "7FB144C0",
          NextDialogue = 51007713,
          SpeakNpcId = 100001
        },
        [51007713] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentTC = "大家……很累很辛苦呢。",
          DialogueId = 51007713,
          GUID = "7FB144EA",
          SpeakNpcId = 700204
        },
        [51007714] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "這裡就是大部分卡戎生活的地方了。",
          DialogueId = 51007714,
          GUID = "7FB14514",
          NextDialogue = 51007715,
          SpeakNpcId = 100001
        },
        [51007715] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "唔嗯……房子破破的，啊，這是那個很兇的大叔在幫鄰居修房頂呢。還有這些小朋友在玩的遊戲，我在內城也和朋友們玩過。",
          DialogueId = 51007715,
          GUID = "7FB1453E",
          NextDialogue = 51007716,
          SpeakNpcId = 700204
        },
        [51007716] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "我懂你的意思了，事實並不像媽媽說的那樣，雖然有些卡戎人說話很兇、行為古怪……但我們人類裡也有這種人啊。",
          DialogueId = 51007716,
          GUID = "7FB14568",
          NextDialogue = 51007717,
          SpeakNpcId = 700204
        },
        [51007717] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "除了頭上的角以外，我覺得你們和我們沒有什麼不同。",
          DialogueId = 51007717,
          GUID = "7FB14592",
          NextDialogue = 51007718,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007718] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "這麼明顯的事實，只要稍微觀察一下就明白了，為什麼大家還是堅持那些錯誤的說法呢？",
          DialogueId = 51007718,
          GUID = "7FB145BC",
          NextOptions = {
            [1] = 51007719,
            [2] = 51007720
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007719] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "因為偏見的力量往往會勝過眼前的真相。",
          DialogueId = 51007719,
          GUID = "7FB145E6",
          NextDialogue = 51007721
        },
        [51007720] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "也許他們是刻意對此視而不見的。",
          DialogueId = 51007720,
          GUID = "7FB14610",
          NextDialogue = 51007721
        },
        [51007721] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "是嗎……？好複雜哦……看來世界上也有研究解決不了的問題啊……",
          DialogueId = 51007721,
          GUID = "7FB1463A",
          NextDialogue = 51007722,
          SpeakNpcId = 700204
        },
        [51007722] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentTC = "不想這些了，正好你帶著相機，我們再一起去拍一下城北邊的那個叫，修，修普諾斯之家的漂亮房子吧！我在那裡等你哦~",
          DialogueId = 51007722,
          GUID = "7FB14664",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007723] = {
          ContentTC = "你來啦~嘿嘿，我以前就偷偷觀察過，那裡面住著的都是年紀不大的卡戎哥哥姐姐，經過今天的了解，我……我想和他們聊聊天！",
          DialogueId = 51007723,
          GUID = "7FB1468E",
          NextDialogue = 51007724,
          SpeakNpcId = 700204
        },
        [51007724] = {
          ContentTC = "{nickname}，你可以和我一起去嗎？",
          DialogueId = 51007724,
          GUID = "7FB146B8",
          NextDialogue = 51007725,
          SpeakNpcId = 700204
        },
        [51007725] = {
          ContentTC = "…………",
          DialogueId = 51007725,
          GUID = "7FB146E2",
          NextOptions = {
            [1] = 51007726,
            [2] = 51007727
          },
          SpeakNpcId = 100001
        },
        [51007726] = {
          ContentTC = "（說出真相。）",
          DialogueId = 51007726,
          GUID = "7FB1470C",
          ImprPlusId = 1002,
          NextDialogue = 51007728
        },
        [51007727] = {
          ContentTC = "（猶豫是否說出真相。）",
          DialogueId = 51007727,
          GUID = "7FB14736",
          ImprPlusId = 1004,
          NextDialogue = 51007728
        },
        [51007728] = {
          ContentTC = "他們這會兒……不一定方便……",
          DialogueId = 51007728,
          GUID = "7FB14760",
          NextDialogue = 51007729,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007729] = {
          ContentTC = "嗯……？這樣嗎……",
          DialogueId = 51007729,
          GUID = "7FB1478A",
          NextDialogue = 51007730,
          SpeakNpcId = 700204
        },
        [51007730] = {
          ContentTC = "那……我可以敲門問問嗎？就問問，說不定他們剛好有空呢！",
          DialogueId = 51007730,
          GUID = "7FB147B4",
          NextDialogue = 51007731,
          SpeakNpcId = 700204
        },
        [51007731] = {
          ContentTC = "……其實，那裡已經沒有人了。所以，已經不用敲門了。",
          DialogueId = 51007731,
          GUID = "7FB147DE",
          NextDialogue = 51007732,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007732] = {
          ContentTC = "誒？為什麼，明明我上次偷看的時候看到好幾個哥哥姐姐呢。",
          DialogueId = 51007732,
          GUID = "7FB14808",
          NextDialogue = 51007733,
          SpeakNpcId = 700204
        },
        [51007733] = {
          ContentTC = "他們……搬家了……",
          DialogueId = 51007733,
          GUID = "7FB14832",
          NextDialogue = 51007734,
          SpeakNpcId = 100001
        },
        [51007734] = {
          ContentTC = "那他們什麼時候回來呢？",
          DialogueId = 51007734,
          GUID = "7FB1485C",
          NextDialogue = 51007735,
          SpeakNpcId = 700204
        },
        [51007735] = {
          ContentTC = "正好讓我整理一下問題，我想問問那個穿綠衣服的姐姐！至於那個兇巴巴的嚇人大叔……就算、算了吧。",
          DialogueId = 51007735,
          GUID = "7FB14886",
          NextDialogue = 51007736,
          SpeakNpcId = 700204
        },
        [51007736] = {
          ContentTC = "他們……不會回來了。",
          DialogueId = 51007736,
          GUID = "7FB148B0",
          NextDialogue = 51007737,
          SpeakNpcId = 100001
        },
        [51007737] = {
          ContentTC = "為什麼呀？那些軍人叔叔把他們趕走了嗎，還是說他們搬到別的城市去了？真好呀，其他地方比冰湖城暖和多了，應該還有很多值得研究的──",
          DialogueId = 51007737,
          GUID = "7FB148DA",
          NextDialogue = 51007738,
          SpeakNpcId = 700204
        },
        [51007738] = {
          ContentTC = "咦？！{性别:大哥哥丨大姐姐}你怎麼哭了？摸摸你，不哭不哭！",
          DialogueId = 51007738,
          GUID = "7FB14904",
          NextDialogue = 51007739,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007739] = {
          ContentTC = "沒、沒事。旅館的主人恩里克呢，是一個很好很好的醫生。他帶著他的小助手們去了南方，去研究一種疾病的治療方式，因為他想救很多很多人。",
          DialogueId = 51007739,
          GUID = "7FB1492E",
          NextDialogue = 51007740,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007740] = {
          ContentTC = "疾病？唔，是一種怎樣的疾病呢？",
          DialogueId = 51007740,
          GUID = "7FB14958",
          NextDialogue = 51007741,
          SpeakNpcId = 700204
        },
        [51007741] = {
          ContentTC = "……「穢蝕」，一種只有卡戎之民會得的病，現在還治不好，很多很多卡戎之民在受它折磨。",
          DialogueId = 51007741,
          GUID = "7FB14982",
          NextDialogue = 51007742,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007742] = {
          ContentTC = "咦？治不好嗎？我認識的醫生姐姐告訴我，煉金院裡有一群聰明的煉金術師，他們會研究消除人類各種疑難雜症的方法……",
          DialogueId = 51007742,
          GUID = "7FB149AC",
          NextDialogue = 51007743,
          SpeakNpcId = 700204
        },
        [51007743] = {
          ContentTC = "（男孩提到「人類」之後愣了一下，似乎明白了什麼。）",
          DialogueId = 51007743,
          GUID = "7FB149D6",
          NextDialogue = 51007744
        },
        [51007744] = {
          ContentTC = "所以，那些大人們……不會幫卡戎研究治療那種病的辦法？",
          DialogueId = 51007744,
          GUID = "7FB14A00",
          NextDialogue = 51007745,
          SpeakNpcId = 700204
        },
        [51007745] = {
          ContentTC = "那可怎麼行……明明大家都是一樣的，怎麼能因為是卡戎就不去救治呢！",
          DialogueId = 51007745,
          GUID = "7FB14A2A",
          NextOptions = {
            [1] = 51007746
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007746] = {
          ContentTC = "這裡或許沒有……但是我相信，在世界的某處，一定有人正在為此努力著。",
          DialogueId = 51007746,
          GUID = "7FB14A54",
          ImprPlusId = 1004,
          NextDialogue = 51007747
        },
        [51007747] = {
          ContentTC = "……我決定了！大家的看法或許不是單靠研究就能改變的，但疾病的話，還是可以靠研究解決的吧？",
          DialogueId = 51007747,
          GUID = "7FB14A7E",
          NextDialogue = 51007748,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007748] = {
          ContentTC = "我也要研究那種病！我也想像你說的那個醫生一樣，好好努力，去救很多很多人。",
          DialogueId = 51007748,
          GUID = "7FB14AA8",
          NextDialogue = 51007749,
          SpeakNpcId = 700204
        },
        [51007749] = {
          ContentTC = "我們的煉金院有很多很多幫助人類的煉金術師，但我西奧想要成為第一個幫助卡戎的煉金術師！",
          DialogueId = 51007749,
          GUID = "7FB14AD2",
          NextDialogue = 51007750,
          SpeakNpcId = 700204
        },
        [51007750] = {
          ContentTC = "你可以把那種病的名字寫在這裡嗎？我要記住它。",
          DialogueId = 51007750,
          GUID = "7FB14AFC",
          NextDialogue = 51007751,
          SpeakNpcId = 700204,
