          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007810] = {
          Content = "唉，年轻人，你听说过冰湖城的红角鹿吗？",
          DialogueId = 51007810,
          GUID = "7FB154D4",
          NextDialogue = 51007811,
          SpeakNpcId = 700018
        },
        [51007811] = {
          Content = "那是非常古老的物种，已经存在了三亿多年，至今保留着其原始而古老的相貌。",
          DialogueId = 51007811,
          GUID = "7FB154FE",
          NextDialogue = 51007812,
          SpeakNpcId = 700018
        },
        [51007812] = {
          Content = "这不只是一对红角，这是整片大陆诞生时的......脐血。",
          DialogueId = 51007812,
          GUID = "7FB15528",
          NextDialogue = 51007813,
          SpeakNpcId = 700018
        },
        [51007813] = {
          Content = "（阿尔加尔说话时，原本苍白的脸上浮现出了激动的红晕。可随后他似乎又想起了什么，露出焦虑悲戚的神色。）",
          DialogueId = 51007813,
          GUID = "7FB15552",
          NextDialogue = 51007814
        },
        [51007814] = {
          Content = "所以我一定要阻止那些贪得无厌的猎人，不能再任由他们无节制地狩猎红角鹿了......",
          DialogueId = 51007814,
          GUID = "7FB1557C",
          NextDialogue = 51007815,
          SpeakNpcId = 700018
        },
        [51007815] = {
          Content = "红角鹿的鹿角具有极高的药用价值，内城的贵族们开了高价收购。",
          DialogueId = 51007815,
          GUID = "7FB155A6",
          NextDialogue = 51007816,
          SpeakNpcId = 700018
        },
        [51007816] = {
          Content = "那群贵族们的拥趸像一群见了血肉的苍蝇一样蜂拥而上。他们握着枪杆杀红了眼，射向红角鹿的子弹越多，他们腰间的钱袋越重。",
          DialogueId = 51007816,
          GUID = "7FB155D0",
          NextDialogue = 51007817,
          SpeakNpcId = 700018
        },
        [51007817] = {
          Content = "仅仅十年，冰湖城郊区的红角鹿就从随处可见变成如今濒临灭绝的境地。",
          DialogueId = 51007817,
          GUID = "7FB155FA",
          NextOptions = {
            [1] = 51007818
          },
          RestartTag = 51007817,
          SpeakNpcId = 700018
        },
        [51007818] = {
          Content = "红角鹿活了三亿年，不该被人们的贪婪一朝逼入绝境。",
          DialogueId = 51007818,
          GUID = "7FB15624",
          ImprCheckId = 1063,
          NextDialogue = 51007819
        },
        [51007819] = {
          Content = "算了，多说无益......",
          DialogueId = 51007819,
          GUID = "7FB1564E",
          NextDialogue = 51007820,
          SpeakNpcId = 700018
        },
        [51007820] = {
          Content = "（阿尔加尔叹了口气，瘦弱的身体在转身时踉跄了一下，离开的背影如同一位殉道者。）",
          DialogueId = 51007820,
          GUID = "7FB15678",
          NextDialogue = 51007821,
          SpeakNpcId = 700018
        },
        [51007821] = {
          Content = "正如你所说，它们珍贵的鹿角不该成了猎人的摇钱树。",
          DialogueId = 51007821,
          GUID = "7FB156A2",
          NextDialogue = 51007822,
          SpeakNpcId = 700018
        },
        [51007822] = {
          Content = "红角鹿的繁殖期马上就要到了，我们必须为自然真的做些什么。",
