          GUID = "7FB156CC",
          NextDialogue = 51007823,
          SpeakNpcId = 700018
        },
        [51007823] = {
          Content = "咳，年轻人，可以拜托你帮我阻止那些滥杀红角鹿的猎人吗？",
          DialogueId = 51007823,
          GUID = "7FB156F6",
          NextDialogue = 51007824,
          SpeakNpcId = 700018
        },
        [51007824] = {
