        },
        [51007918] = {
          ContentTC = "（咯吱作響的管道將附近的穢獸吸引了過來，待你清理完這些小麻煩後，達頓的聲音從身旁的管道傳來。）",
          DialogueId = 51007918,
          GUID = "7FB1668C",
          IsBlack = 1,
          NextDialogue = 51007919
        },
        [51007919] = {
          ContentTC = "太——好——玩——啦——我——們——終——點——見——",
          DialogueId = 51007919,
          GUID = "7FB166B6",
          SpeakNpcId = 700191
        },
        [51007920] = {
          ContentTC = "（終點除了一灘水什麼也沒有。趴在管道上仔細聆聽，你能聽到咯吱聲還在不斷地從終點前方傳來。你知道，達頓滑過頭了。）",
          DialogueId = 51007920,
          GUID = "7FB166E0"
        },
        [51007921] = {
          ContentTC = "（一隻又一隻的穢獸被噴出了管道，攔住了你的去路。）",
          DialogueId = 51007921,
          GUID = "7FB1670A",
          IsBlack = 1
        },
        [51007922] = {
          Camera = "-143.335342,-546.682495,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          ContentTC = "嗯——呃——嘔——",
          DialogueId = 51007922,
          FinalCamera = "-60.066826,-542.436035,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          GUID = "7FB16734",
          NextDialogue = 51007923,
          SpeakNpcId = 700191,
          TalkActionId = {
            [1] = "700191:Hurt01"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100001:n(700191)"
          }
        },
        [51007923] = {
          ContentTC = "（從錯誤出口噴出來的達頓面色蒼白，趴在地上狂吐不止，顯然「滑梯」頗為顛簸——這個「下水道滑梯」並沒有他所說的那麼安全有趣。）",
          DialogueId = 51007923,
          GUID = "7FB1675E",
          NextOptions = {
            [1] = 51007924,
            [2] = 51007925
          }
        },
        [51007924] = {
          ContentTC = "你沒事吧？",
          DialogueId = 51007924,
          GUID = "7FB16788",
          ImprPlusId = 1002,
          NextDialogue = 51007926
        },
        [51007925] = {
          ContentTC = "我沒看清，你能再滑一次嗎？",
          DialogueId = 51007925,
          GUID = "7FB167B2",
          ImprPlusId = 1005,
          NextDialogue = 51007926
        },
        [51007926] = {
          Camera = "-310.433411,-170.472031,157.965942,0.000161,-12.197788,12.9158,15.353726,100000.0,false,Manual,22.0",
          ContentTC = "呼……呼……",
          DialogueId = 51007926,
          GUID = "7FB167DC",
          NextDialogue = 51007927,
          SpeakNpcId = 700191
        },
        [51007927] = {
          ContentTC = "不行了，我得，休息一下……答應你的獎勵，給……我先走了……",
          DialogueId = 51007927,
          GUID = "7FB16806",
          NextDialogue = 51007928,
          SpeakNpcId = 700191,
          TalkActionId = {
            [1] = "700191:Sigh_Start"
          }
        },
        [51007928] = {
          Camera = "-125.646004,-486.612549,465.015015,-0.001072,-47.41058,90.325813,15.353726,100000.0,false,Manual,22.0",
          ContentTC = "唉……到底怎麼才能搞出便宜好玩，霧區人也能玩得起的遊樂設施呢……",
          DialogueId = 51007928,
          GUID = "7FB16830",
          NextDialogue = 51007929,
          SpeakNpcId = 700191
        },
        [51007929] = {
          ContentTC = "（達頓遞給你一個小包裹，然後摀著胸口頭也不回地離開了下水道——顯然，他不會再回到這個令他傷心的地方了。）",
          DialogueId = 51007929,
          GUID = "7FB1685A",
          IsBlack = 1
        },
        [51007930] = {
          ContentTC = "霧區什麼娛樂項目都沒有，肯定還有潛在的商機，讓我再好好想想……",
          DialogueId = 51007930,
          GUID = "7FB16884",
          SpeakNpcId = 700191
        },
        [51008001] = {
          ContentTC = "走，走開……不買月石的話就趕緊走……別把那群當兵的引來了……",
          DialogueId = 51008001,
          GUID = "7FB1742A",
          NextDialogue = 51008002,
          SpeakNpcId = 700113
        },
        [51008002] = {
          ContentTC = "（男人瑟縮在角落，與他健碩的體格所給人的印象相去甚遠。他的眼神躲閃，渴望將身旁的月石脫手，卻遲疑著要不要向他人尋求幫助。）",
          DialogueId = 51008002,
          GUID = "7FB17454",
          NextOptions = {
            [1] = 51008003,
            [2] = 51008004,
            [3] = 51008005,
            [4] = 51008007
          }
        },
        [51008003] = {
          ContentTC = "我雖然不買，但分我一半報酬的話，可以幫你找找買家。",
          DialogueId = 51008003,
          GUID = "7FB1747E",
          ImprPlusId = 1001,
          NextDialogue = 51008009
        },
        [51008004] = {
          ContentTC = "你需要什麽幫助嗎？",
          DialogueId = 51008004,
          GUID = "7FB174A8",
          ImprPlusId = 1004,
          NextDialogue = 51008009
        },
        [51008005] = {
          ContentTC = "帝國肯定不會允許你幹這種事，不想惹麻煩的話就快走吧。",
          DialogueId = 51008005,
          GUID = "7FB174D2",
          ImprPlusId = 1002,
          NextDialogue = 51008006
        },
        [51008006] = {
          ContentTC = "您高擡貴手，把我當個屁放了吧，我只要把這批月石賣掉就立馬離開冰湖城，絕不回來。",
          DialogueId = 51008006,
          GUID = "7FB174FC",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008007] = {
          ContentTC = "咳！軍團的士兵委托我盤查你，趕緊把通行證拿出來！",
          DialogueId = 51008007,
          GUID = "7FB17526",
          ImprPlusId = 1005,
          NextDialogue = 51008008
        },
        [51008008] = {
          ContentTC = "（男人聽罷提起袋子就要跑，好不容易向他說明玩笑並解釋身份後，他才悄聲說明了自己的難處。）",
          DialogueId = 51008008,
          GUID = "7FB17550",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008009] = {
          ContentTC = "只要你幫我找個買家，報酬分你七成，不，八成！拜托了，拜托！",
          DialogueId = 51008009,
          GUID = "7FB1757A",
          SpeakNpcId = 700113
        },
        [51008010] = {
          ContentTC = "（雖說答應了男人的委託，但他的神色和袋子上乾涸的暗紅色痕跡都宣告著這批月石的來路並不單純。）",
          DialogueId = 51008010,
          GUID = "7FB175A4",
          NextDialogue = 51008011
        },
        [51008011] = {
          ContentTC = "（貿然尋找買主也許會招來麻煩，也許，先確認一下這批月石的來歷會更好？）",
          DialogueId = 51008011,
          GUID = "7FB175CE"
        },
        [51008012] = {
          ContentTC = "(這片草叢剛剛是不是有什麼東西閃了一下？)",
          DialogueId = 51008012,
          GUID = "7FB175F8",
          NextOptions = {
            [1] = 51008053
          }
        },
        [51008013] = {
          ContentTC = "（你翻了翻草叢，什麼都沒找到。也許剛才只是眼花了吧。）",
          DialogueId = 51008013,
          GUID = "7FB17622"
        },
        [51008014] = {
          ContentTC = "（你翻了翻草叢，果然找到了一顆散發著微弱光亮的石頭——月石。只是，月石上同樣沾著暗紅色的血跡，和男人袋子上的暗紅痕跡一模一樣。）",
          DialogueId = 51008014,
          GUID = "7FB1764C",
          NextDialogue = 51008015
        },
        [51008015] = {
          ContentTC = "我可不覺得今天是什麼運氣好到足夠隨地撿月石的日子。更何況這種帶著一抹血跡的月石可不常見……",
          DialogueId = 51008015,
          GUID = "7FB17676",
          NextDialogue = 51008016,
          SpeakNpcId = 100001
        },
        [51008016] = {
          ContentTC = "吼——",
          DialogueId = 51008016,
          GUID = "7FB176A0",
          NextDialogue = 51008017
        },
        [51008017] = {
          ContentTC = "先清理掉礙事的穢獸吧……",
          DialogueId = 51008017,
          GUID = "7FB176CA",
          SpeakNpcId = 100001
        },
        [51008018] = {
          ContentTC = "（一片凌亂的殘渣碎屑，是冰湖的碎石、折斷的樹枝、些許瓦礫碎片。看這個凌亂程度，這裡想必經歷過一場打鬥。）",
          DialogueId = 51008018,
          GUID = "7FB176F4",
          NextDialogue = 51008019
        },
        [51008019] = {
          ContentTC = "（殘渣中夾雜著撕下來的劣質布料和棉絮，這些布料似乎和那個尋找買主的男人身上穿的衣物類似。）",
          DialogueId = 51008019,
          GUID = "7FB1771E"
        },
        [51008020] = {
          ContentTC = "（翻開那些碎屑，你又發現了一小塊染血的月石。）",
          DialogueId = 51008020,
          GUID = "7FB17748"
        },
        [51008021] = {
          ContentTC = "（周圍的腳印雜亂無章，但卻並沒有穢獸或野獸的蹄印，只有人類的腳印。）",
          DialogueId = 51008021,
          GUID = "7FB17772"
        },
        [51008022] = {
          ContentTC = "（一道重物被拖行的痕跡綿延至遠處。）",
          DialogueId = 51008022,
          GUID = "7FB1779C",
          NextDialogue = 51008023
        },
        [51008023] = {
          ContentTC = "嗯……我想，我大概能猜到這裡發生過什麼了。月石上血跡的來源是：",
          DialogueId = 51008023,
          GUID = "7FB177C6",
          NextOptions = {
            [1] = 51008024,
            [2] = 51008026,
            [3] = 51008028
          },
          SpeakNpcId = 100001
        },
        [51008024] = {
          ContentTC = "人類",
          DialogueId = 51008024,
          GUID = "7FB177F0",
          NextDialogue = 51008025
        },
        [51008025] = {
          ContentTC = "（是的，這裡並沒有穢獸和野獸來過。）",
          DialogueId = 51008025,
          GUID = "7FB1781A",
          NextDialogue = 51008030
        },
        [51008026] = {
          ContentTC = "野獸",
          DialogueId = 51008026,
          GUID = "7FB17844",
          NextDialogue = 51008027
        },
        [51008027] = {
          ContentTC = "（不對，如果有野獸來過，這裡應該會留有野獸的蹄印。）",
          DialogueId = 51008027,
          GUID = "7FB1786E",
          NextDialogue = 51008030
        },
        [51008028] = {
          ContentTC = "穢獸",
          DialogueId = 51008028,
          GUID = "7FB17898",
          NextDialogue = 51008029
        },
        [51008029] = {
          ContentTC = "（不對，如果有穢獸來過，這裡應該會留有穢獸的蹄印。）",
          DialogueId = 51008029,
          GUID = "7FB178C2",
          NextDialogue = 51008030
        },
        [51008030] = {
          ContentTC = "（是有人在這裡襲擊了其他人，也許就是為了……搶走那一小袋月石。接下來怎麼辦呢……）",
          DialogueId = 51008030,
          GUID = "7FB178EC",
          SpeakNpcId = 100001,
          TalkOptions = {
            [1] = 51008031,
            [2] = 51008032
          }
        },
        [51008031] = {
          ContentTC = "那個人的月石來路不正，不如吞下這筆不義之財。",
          DialogueId = 51008031,
          GUID = "7FB17916",
          ImprPlusId = 1005
        },
        [51008032] = {
          ContentTC = "那個人做了惡事，去找衛戍部隊舉報他吧。",
          DialogueId = 51008032,
          GUID = "7FB17940",
          ImprPlusId = 1002
        },
        [51008033] = {
          ContentTC = "你做了什麼見不得人的事吧？",
          DialogueId = 51008033,
          GUID = "7FB1796A",
          NextDialogue = 51008034,
          SpeakNpcId = 100001
        },
        [51008034] = {
          ContentTC = "這枚月石你可能未必會有印象，但它一定記得你。它上面沾染的血跡的主人也永遠不會忘了你的。",
          DialogueId = 51008034,
          GUID = "7FB17994",
          NextDialogue = 51008035,
          SpeakNpcId = 100001
        },
        [51008035] = {
          ContentTC = "我……我聽不懂你在說什麼！",
          DialogueId = 51008035,
          GUID = "7FB179BE",
          NextDialogue = 51008036,
          SpeakNpcId = 700113
        },
        [51008036] = {
          ContentTC = "不用你幫忙了，什麼月石，我聽不懂！",
          DialogueId = 51008036,
          GUID = "7FB179E8",
          NextDialogue = 51008037,
          SpeakNpcId = 700113
        },
        [51008037] = {
          ContentTC = "沒必要這樣，衛戍部隊馬上就要到了。不過，我倒是有個法子可以幫你──前提是，這袋月石歸我。",
          DialogueId = 51008037,
          GUID = "7FB17A12",
          NextDialogue = 51008038,
          SpeakNpcId = 100001
        },
        [51008038] = {
          ContentTC = "我……你……",
          DialogueId = 51008038,
          GUID = "7FB17A3C",
          NextDialogue = 51008039,
          SpeakNpcId = 700113
        },
        [51008039] = {
          ContentTC = "當然，你也可以選擇跟他們走，這完全是你的自由。",
          DialogueId = 51008039,
          GUID = "7FB17A66",
          NextDialogue = 51008040,
          SpeakNpcId = 100001
        },
        [51008040] = {
          ContentTC = "我可以在這裡等你做選擇， 但衛戍部隊大概不會等你。在你猶豫這會兒的時間裡，他們大概就要到囉。",
          DialogueId = 51008040,
          GUID = "7FB17A90",
          NextDialogue = 51008041,
          SpeakNpcId = 100001
        },
        [51008041] = {
          ContentTC = "我給你！我全都給你還不行麼！",
          DialogueId = 51008041,
          GUID = "7FB17ABA",
          NextDialogue = 51008042,
          SpeakNpcId = 700113
        },
        [51008042] = {
          ContentTC = "就是這袋該死的月石！如果不是偶然發現它，我的兄弟們應該都還活著的！我們現在應該已經快要休息了……",
          DialogueId = 51008042,
          GUID = "7FB17AE4",
          NextDialogue = 51008043,
          SpeakNpcId = 700113
        },
        [51008043] = {
          ContentTC = "不不……我們今天的收穫比往常還要好一點，沒準今晚還能一起去一次水仙平原，每個人都能來上一杯滿滿的麥芽酒！",
          DialogueId = 51008043,
          GUID = "7FB17B0E",
          NextDialogue = 51008044,
          SpeakNpcId = 700113
        },
        [51008044] = {
          ContentTC = "我們可以一醉方休，可以吹牛到半夜，明早再一起……",
          DialogueId = 51008044,
          GUID = "7FB17B38",
          NextDialogue = 51008045,
          SpeakNpcId = 700113
        },
        [51008045] = {
          ContentTC = "我……我不能给你！",
          DialogueId = 51008045,
          GUID = "7FB17B62",
          SpeakNpcId = 700113
        },
        [51008046] = {
          Camera = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "你騙我！根本就沒有什麼衛戍部隊，你就是想吞掉我這月石罷了！",
          DialogueId = 51008046,
          GUID = "7FB17B8C",
          NextDialogue = 51008047,
          SpeakNpcId = 700113
        },
        [51008047] = {
          ContentTC = "你就是用它砸死了你的朋友──像剛才襲擊我那樣？",
          DialogueId = 51008047,
          GUID = "7FB17BB6",
          NextDialogue = 51008048,
          SpeakNpcId = 100001
        },
        [51008048] = {
          ContentTC = "是他們先動手的……我，我這都是正當防衛！",
          DialogueId = 51008048,
          GUID = "7FB17BE0",
          NextDialogue = 51008049,
          SpeakNpcId = 700113
        },
        [51008049] = {
          ContentTC = "還有你……你想貪下這包月石，你、又是什麼好東西？還教訓起我來了？",
          DialogueId = 51008049,
          GUID = "7FB17C0A",
          NextOptions = {
            [1] = 51008050,
            [2] = 51008051
          },
          SpeakNpcId = 700113
        },
        [51008050] = {
          ContentTC = "成年人應該為犯下的錯付出代價，這包月石給你長點記性。",
          DialogueId = 51008050,
          GUID = "7FB17C34",
          ImprPlusId = 1001,
          NextDialogue = 51008052
        },
        [51008051] = {
          ContentTC = "我不是什麼好人，你自然也不是。但我至少願意給你留一條命，滾吧。",
          DialogueId = 51008051,
          GUID = "7FB17C5E",
          ImprPlusId = 1005,
          NextDialogue = 51008052
        },
        [51008052] = {
          ContentTC = "（手裡染血的月石沉甸甸的。它是如此沉重，彷彿要變成一個怪物，把所有的「拉里」都吃掉。）",
          DialogueId = 51008052,
          GUID = "7FB17C88",
          IsBlack = 1
        },
        [51008053] = {
          ContentTC = "低頭翻找一下看看",
          DialogueId = 51008053,
          GUID = "7FB17CB2",
          ImprCheckId = 1070
        },
        [51008054] = {
          ContentTC = "（清理掉這群礙眼的穢獸後，附近的地面上某些似乎被掩埋過的痕跡暴露了出來。你決定去檢查一下這些新的線索。）",
          DialogueId = 51008054,
          GUID = "7FB17CDC"
        },
        [51009001] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "新劇上映，新劇上映！那邊的年輕人，要不要來體驗一下？",
          DialogueId = 51009001,
          GUID = "7FB2183A",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          NextDialogue = 51009002,
          SpeakNpcId = 700240
        },
        [51009002] = {
          ContentTC = "叫我嗎？",
          DialogueId = 51009002,
          GUID = "7FB21864",
          NextDialogue = 51009003,
          SpeakNpcId = 100001
        },
        [51009003] = {
          ContentTC = "是的是的，蓋雷亞劇院正在試演一種全新的戲劇——沉浸式戲劇！",
          DialogueId = 51009003,
          GUID = "7FB2188E",
          NextDialogue = 51009004,
          SpeakNpcId = 700240
        },
        [51009004] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這是來自盧卡的全新演繹形式！你不會再像過去一樣被按在觀眾席上，而是可以自己選擇去哪兒，甚至自己成為故事的一部份……",
          DialogueId = 51009004,
          GUID = "7FB218B8",
          NextDialogue = 51009005,
          SpeakNpcId = 700240,
          TalkActionId = {
            [1] = "700240:Explain02_Start"
          }
        },
        [51009005] = {
