          NextDialogue = 51009660
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "維爾莉特，為什麼你會回來？",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "維爾莉特……是誰？",
          DialogueId = 51009661,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28482",
          NextDialogue = 51009662,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "唉……年輕人，你願意聽我講一些陳年舊事嗎？",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "好，不過我們先回去好嗎，拉斯應該已經等急了。",
          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "好，好……回去吧。",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "多納特大叔，你可算回來了！",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "抱歉，孩子，讓你擔心了——咳……咳咳……",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "大叔，你又發病了！我帶你去找醫生。",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "不，不用了……這是我的報應，治不了的。",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "大叔，你怎麼又在說這種話了——",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentTC = "你忘了嗎？有個冬天特別特別冷，我只能去工廠排廢氣的管道那裡蹲著，這樣就能暖和一些。大叔你也凍得打哆嗦，卻把唯一一件厚棉衣給了我。",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303
        },
        [51009671] = {
          ContentTC = "整條街都知道大叔是多好的人！為什麼你總是把「報應」這種難聽話掛在嘴邊呢？",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "……難道和你說的「往事」有關？",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "嗯，那是十六年前……",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "就和我的每一段無聊至極的人生經曆一樣，當礦工的那些年算不上好，但也不算太壞。每天有恰好做到精疲力盡的工作，也能換取讓一家人吃飽的麵包。",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301
        },
        [51009675] = {
          ContentTC = "現在想想，雖然那些大人物從來沒有給予我們公正的對待，但那時候反而是我這一生最無憂無慮的日子……",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "可我的朋友西格，他就沒有那麼幸運了。病痛無端地降臨到他唯一的家人——他的妹妹，維爾莉特身上，可憐那女孩才只有十八歲。",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301
        },
        [51009677] = {
          ContentTC = "而當你覺得遇到很糟糕的事時，情況往往會變得更糟。",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301
        },
        [51009678] = {
          ContentTC = "格雷姆礦場運出來的月石變得一天比一天少，拿在手裡的薪水也越來越微薄。漸漸地，麵包從白麵包變成黑麵包，到後來連黑麵包都混著麩皮和木屑。",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301
        },
        [51009679] = {
          ContentTC = "維爾莉特的病，對於報酬只能勉強活命的西格來說，無異於親耳聽到對親人宣告死刑。",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentTC = "我還記得那個淩晨，西格向工友討了很多暖身的廉價烈酒，我們就這樣坐在格雷姆礦場前的石頭上，一瓶一瓶地往身子裡灌。",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentTC = "他一邊不像樣地哭，一邊回憶和妹妹相依為命的往事。他時而學著維爾莉特的樣子唱起歌，時而低低咒罵著法布瑞斯·魯斯福德。",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "法布瑞斯·魯斯福德是誰？",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "工程煉金院的長官，當時格雷姆礦場的負責人。",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentTC = "我拍著西格的肩膀和他說，「罵他有什麼用，還不是咱們沒本事。你要是真有能耐，怎麼不綁了他，乾票大的？」",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentTC = "……這十六年裡，我無時無刻不在質問自己，如果那天我沒有喝多酒，沒有說出那些輕佻的昏話，一切悲劇是不是都不會發生。",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "難道，那位西格叔叔真的……",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "是的。某一天，西格突然辭去了礦場的工作，我去他家找他，卻發現他和維爾莉特都已經不在那裡了。",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentTC = "起初我以為他是帶著維爾莉特離開了冰湖城，去其他地方求醫……可一周後，我卻收到了維爾莉特的來信。",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301
        },
        [51009689] = {
          ContentTC = "雖然我和西格是好兄弟，但從我認識西格起，維爾莉特就常常臥病在床，所以我和她也沒見過幾面。信是她用僅剩的銅幣拜托一位過路的狩月人送到礦場的。",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "信上說，西格綁架了長官的女兒，希望討要一筆贖金。維爾莉特請求我阻止他，不要讓他一錯再錯。",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301
        },
        [51009691] = {
          ContentTC = "他把那個女孩關在了城郊的一棟老房子裡，當我找到那裡時他非常震驚，但還是承認了自己的所作所為。",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我意識到正是我那晚的胡話打開了罪惡的匣子，我後悔極了。我本想勸阻他，但看到虛弱到已經說不出來話的維爾莉特，我還是猶豫了……",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301
        },
        [51009693] = {
          ContentTC = "西格讓我就當這件事情沒有發生過，但隨著排查越來越嚴格，我一想到這件事就會害怕到顫抖不止。",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301
        },
        [51009694] = {
          ContentTC = "最後……最後……",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "你……揭發了他們？",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我不該這麼做，我不該這麼做啊！",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "後來呢，後來他們怎麼樣了？",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "軍團的長官親自帶人來抓捕西格，西格在抵抗的時候不慎點燃了屋子。",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentTC = "我衝進去想要救人，但最後卻只在混亂中救出了維爾莉特。她是那樣害怕，整張臉都被熏成煤黑，只有眼窩被止不住的淚水衝出兩道淚痕。",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301
        },
        [51009700] = {
          ContentTC = "我怕維爾莉特被她哥哥牽連，就把她藏在運水的桶裡，瞞過了軍團的視線。",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301
        },
        [51009701] = {
          ContentTC = "最後，西格被軍團的人抓到，而那位長官的女兒……大家只在廢墟中找到她燒成焦炭的遺體。",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301
        },
        [51009702] = {
          ContentTC = "在那之後，憤怒的長官直接繞過審判流程，親自將西格處決。而維爾莉特……我把檢舉的賞金都給了她，趁亂把她送出了冰湖城，希望她不要被牽連……",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我至今還能想起我送她離開時，她那副憔悴但又憤怒的表情，她當時戴著的，就是這條紫羅蘭色的緞帶……",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301
        },
        [51009704] = {
          ContentTC = "她說她會永遠離開冰湖城，永遠不想再見到我。",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301
        },
        [51009705] = {
