        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我曾經聽到很多人這麼說……但這無法改變有兩個原本無辜的生命因我而死。",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          ContentTC = "我生了一場大病，從那之後我開始不停地做好事，不停地幫助他人。我覺得只要做一件好事，就能彌補一分當年的罪過。",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "可我總是夢見西格憤怒地盯著我，還有艾諾拉，那可憐女孩在火場裡無助的哀嚎。他們說，你為活人做再多，死去的人也不會原諒你。",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301
        },
        [51009711] = {
          ContentTC = "啊……維爾莉特，你就是因此回到冰湖城的嗎？你也和我一樣，終究是無法原諒罪人多納特嗎？",
