          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009725] = {
          ContentTC = "（你聽到街角的歌聲。環顧四望，卻並未發現唱歌的人。要繼續在周圍看看嗎？）",
          DialogueId = 51009725,
