          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009730] = {
          ContentTC = "當然不是你的錯覺，你正在和我說話。",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009731] = {
          ContentTC = "為什麼一定要有人躲在這裡，不能單純是一只會說話的箱子呢？",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009732] = {
          ContentTC = "抱歉，我只是一只普通的箱子，沒有那種力量。",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "可為什麼箱子會說話？",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentTC = "要問為什麼……你覺得，唱歌和說話哪個更困難一些？",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309
        },
        [51009735] = {
          ContentTC = "唱歌吧。",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001
        },
        [51009736] = {
          ContentTC = "可有一種會唱歌的小盒子，只要擰幾圈發條就可以歌唱。說話比唱歌更加簡單，而我比八音盒更大，也更好——",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309
        },
        [51009737] = {
          ContentTC = "所以我可以像這樣對你說話，就像你現在正對我說話一樣。",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentTC = "可是……",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentTC = "我明白，你在疑惑。",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309
        },
        [51009740] = {
          ContentTC = "每個人都認為一隻木箱不應該說話，就像他們記憶中那個只會響起回音的樹洞一樣。但是捫心自問，誰不想要一個會說話的木箱呢？",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309
        },
        [51009741] = {
          ContentTC = "既然你沒有第一時間掀開我，說明你還是希望會有一隻木箱陪你說說話不是嗎？",
          DialogueId = 51009741,
          FacialId = {
