        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentTC = "沒關係，沒人會因此責怪你。或許你應該找個機會去看一看，那是一出好戲。那個叫普蒂妮的主角，她美麗、善良。還有著……追逐自由的勇氣。",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309
        },
        [51009750] = {
          ContentTC = "我也想成為她那樣的人，可我卻只是一隻木箱。",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309
        },
        [51009751] = {
          ContentTC = "所以我做出了一個決定。",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309
        },
        [51009752] = {
          ContentTC = "什麼樣的決定？",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我想去遠航，沒人規定木箱只能堆放在街道的角落，它也可以被做成船，隨著洋流漂泊——我想感受混著海水與砂礫的風。",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentTC = "可離開這裡，就意味著我同樣會失去現有的一切。",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309
        },
        [51009755] = {
          ContentTC = "失去了囚籠，也代表著失去了容身之所。擁有了自由，也代表擁有了未知的風險。",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我的朋友，你覺得，我應該怎麼選呢？",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309
        },
        [51009757] = {
          ContentTC = "……說的也是。",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309
        },
        [51009758] = {
          ContentTC = "謝謝你願意陪一隻箱子聊天，善良的人啊。天快亮了，屬於朽木的魔法要消失了。",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309
        },
        [51009759] = {
          ContentTC = "祝願你在未來的每一個無眠的夜晚，都有……不，祝願你每個夜晚都能安享美夢。",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309
        },
        [51009760] = {
          ContentTC = "（你聽到了一陣微小的震顫聲，如同躲藏在箱子背後的小精靈趕在天亮前離開了孩子的床頭。）\n（當回過神來的時候，你意識到那位箱子小姐似乎已經離開了。）",
          DialogueId = 51009760,
          GUID = "7FB294C0"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,true,DoNotOverride,2.8",
          ContentTC = "（躲在箱子裡的那個聲音……不知道為什麼就順著她的想法聊下去了。）",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentTC = "（可能是誰家的小孩子在亂跑，不能就這麼放著不管，還是找周圍的人問問吧。）",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001
        },
        [51009763] = {
          ContentTC = "請問……你是誰？從剛才開始似乎就一直在我家附近轉悠。",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009764] = {
          ContentTC = "是有委托找我嗎，找人？還是收集素材？其他的委托也不是不接，但必須合法。",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009765] = {
          ContentTC = "委托？",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001
        },
        [51009766] = {
          ContentTC = "嗯？原來你不是來找我發委托的？",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009767] = {
          ContentTC = "好吧，看來「狩月人吉賽爾」的名氣沒有卡蜜拉說的那麼響。",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302
        },
        [51009768] = {
          ContentTC = "狩月人吉賽爾……這麼一說我好像聽到過——",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001
        },
        [51009769] = {
          ContentTC = "倒也不用為了照顧我的心情這麼說。",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302
        },
        [51009770] = {
          ContentTC = "不……其實……",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001
        },
        [51009771] = {
          ContentTC = "（向吉賽爾說明了她家屋後那個箱子的事。）",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772
        },
        [51009772] = {
          ContentTC = "你是說，我家房後的木箱說話了，還推薦你去聽一場歌劇。嗯，我了解了。",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302
        },
        [51009773] = {
          ContentTC = "……",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001
        },
        [51009774] = {
          ContentTC = "你好像，反應和我想象中有點不一樣？",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001
        },
        [51009775] = {
          ContentTC = "是嗎？可能是我性格如此。無論是有小孩子淘氣鑽進去和你說話，還是箱子本身就會說話，對我來說都是可以接受的現實。",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302
        },
        [51009776] = {
          ContentTC = "謝謝你把這件事告訴我，我會在這一帶問一問的。",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302
        },
        [51009777] = {
          ContentTC = "哦對了，我想起來了。你是{nickname}對嗎？最近在狩月人圈子裡評價很高的新星。",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302
        },
        [51009778] = {
          ContentTC = "果然是你，看來我的眼光還沒退步。",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009779] = {
          ContentTC = "不用那麼警惕，像你這樣的有能力的新人出名很快的。",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009780] = {
          ContentTC = "品味稍微差了點……不過確實是個辨識度很高的稱號。",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009781] = {
          ContentTC = "既然你看起來有空，可以幫我一個忙嗎？",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302
        },
        [51009782] = {
          ContentTC = "幫我找些草藥來，種類和數量我會列一個清單給你，收集好之後直接送到水仙平原就好，報酬我也會提前留給卡蜜拉。",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302
        },
        [51009783] = {
          ContentTC = "不用送到這裡？",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001
        },
        [51009784] = {
          ContentTC = "沒事，放到水仙平原就可以。",
          DialogueId = 51009784,
          GUID = "7FB298B0",
          SpeakNpcId = 700302
        },
        [51009785] = {
          Camera = "777.87793,290.900391,409.416016,0.000004,-23.199877,-161.79744,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "（差不多應該夠了。）",
          DialogueId = 51009785,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB298DA",
          NextDialogue = 51009786,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51009786] = {
          Camera = "104.59375,60.244141,114.90918,0.000007,-13.199702,-164.194138,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "（這些草藥……都是些隨處可見的品種，如果吉賽爾也是狩月人為什麼要專門拜托我？）",
          DialogueId = 51009786,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29904",
          NextDialogue = 51009787,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          ContentTC = "（現在回想起來，她的態度也有些奇怪……）",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001
        },
        [51009788] = {
          ContentTC = "（先把這些草藥帶回水仙平原吧，順便向卡蜜拉打聽一下。）",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "下午好，今天是想喝上一杯，還是在看委托？",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003
        },
        [51009790] = {
          ContentTC = "我是來送東西的，是吉賽爾的委托，說讓我把東西送到水仙平原就好。",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001
        },
        [51009791] = {
          ContentTC = "吉賽爾？她的確不久前來過一趟，說讓我幫忙把一個包裹轉交給你。不過總感覺有些不對勁……委托的內容是什麼？",
          DialogueId = 51009791,
          GUID = "7FB299D6",
          NextDialogue = 51009792,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009792] = {
          ContentTC = "（向卡蜜拉說明了吉賽爾委托自己采集草藥的事。）",
          DialogueId = 51009792,
          GUID = "7FB29A00",
          NextDialogue = 51009793
        },
        [51009793] = {
          ContentTC = "…………",
          DialogueId = 51009793,
          GUID = "7FB29A2A",
          NextDialogue = 51009794,
          SpeakNpcId = 200003
        },
        [51009794] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "有什麼不對嗎？",
          DialogueId = 51009794,
          GUID = "7FB29A54",
          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009795] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "委托本身倒是沒什麼，不過為什麼她會發出這種委托？",
          DialogueId = 51009795,
          GUID = "7FB29A7E",
          NextDialogue = 51009796,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009796] = {
          ContentTC = "需求都是些很常見的風寒草藥，她自己去收集的話一早上就能回來，沒有必要專門請人去做。",
          DialogueId = 51009796,
          GUID = "7FB29AA8",
          NextDialogue = 51009797,
          SpeakNpcId = 200003
        },
        [51009797] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "說起來我的確聽她提到過，她自己就是個狩月人。",
          DialogueId = 51009797,
          GUID = "7FB29AD2",
          NextDialogue = 51009798,
          SpeakNpcId = 100001
        },
        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "嗯，她以前做過衛戍官，十六年前因為某個案子的判決和上級起了矛盾離開衛戍部隊做了狩月人。思維敏捷身手也不錯，在圈子裡名氣不小。",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003
        },
        [51009799] = {
          ContentTC = "算了，不提那些了。既然委托沒什麼問題，她也提前留過了口信，我就沒什麼好多說的。",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          ContentTC = "這是她留給你的東西，拿好。",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "這是……委托的報酬，還有一封信？",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29B7A",
          SpeakNpcId = 100001
        },
        [51009802] = {
          ContentTC = "你好，親愛的朋友。\n謝謝你願意陪一個荒唐的箱子聊到深夜，也謝謝你給我踏上旅途的勇氣。\n也許這麼做有些對不起我的朋友和老師，但她們一定會理解我的選擇。世界那麼大，我會在其他的舞台和她們再見。\n還有，請不要責怪吉賽爾，這是我自己的意願。希望我的任性不會連累到其他人。\n啊，突然想起來我還沒有對你說過我的名字。\n不過那個名字以後不會再用啦，讓我想想……\n如果你以後遇到了一個叫普蒂妮的女孩，請一定要認出我，我也一定會認出你的。",
          DialogueId = 51009802,
          Duration = 10,
          GUID = "7FB29BA4"
        },
        [51009803] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "看來你認識了一個奇怪的朋友，這應該是一段有趣的故事。",
          DialogueId = 51009803,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "不……其實我也不知道具體發生了什麼。",
          DialogueId = 51009804,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB29BF8",
          NextDialogue = 51009805,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "200003:Talk02_End",
            [2] = "100001:ScratchHead_Start"
          }
        },
        [51009805] = {
          ContentTC = "（和卡蜜拉講述了最近兩天發生的事。）",
          DialogueId = 51009805,
          GUID = "7FB29C22",
          IsBlack = 1,
          NextDialogue = 51009806
        },
        [51009806] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "普蒂妮……",
          DialogueId = 51009806,
          GUID = "7FB29C4C",
          NextDialogue = 51009807,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51009807] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "這個名字怎麼了？",
