        },
        [51009868] = {
          ContentTC = "在混亂的火災現場，那位知情人救出了當時也在屋子裡的維爾莉特……或者說，他<H>以為</>自己救出了維爾莉特。",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302
        },
        [51009869] = {
          ContentTC = "到此為止，我說的沒錯吧？十六年前殺害了維爾莉特，又假扮成她，利用她的身份蒙騙多納特逃出了冰湖城的你，艾諾拉·魯斯福德！",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "……嗬，有趣的劇本，是不多見的懸疑題材呢。",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentTC = "說下去，我喜歡聽。",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          ContentTC = "這些年我一直在調查那樁案件，燒焦的屍體，幸存的維爾莉特，這一切都太過巧合。",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentTC = "這一切似乎都有著某種關聯，但破碎的關鍵詞之間缺少一條能將這一切連起來的線。",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302
        },
        [51009874] = {
          ContentTC = "如果不是我在衛戍部隊期間給法布瑞斯那個傢伙當過幾天護衛，並且湊巧聽到了她女兒的歌聲——",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "恐怕我永遠都不會把這些和你聯係起來，「千面的薇奧萊塔」。",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302
        },
        [51009876] = {
          ContentTC = "我用各種方法試圖調查你的生活習慣，比如……找一些人以送信的名義觀察你。",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentTC = "原來那個衛兵是你派來的。",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentTC = "不，他的確是你的劇迷，我也只是稍稍煽動了一下罷了。多虧了他，我才最終確定了你的身份。",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,true,DoNotOverride,2.8",
          ContentTC = "即便如此，我還是有一件事沒有搞清楚。",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302
        },
        [51009880] = {
          ContentTC = "在火災中和維爾莉特調換身份，這種方法沒有西格和維爾莉特的配合難以實施，你到底是怎麼說服他們的？",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我還以為你要問什麼呢……這種事不是很簡單嗎？",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentTC = "我可是那個法布瑞斯的女兒，既然你曾經在父親的手下工作過，就應該知道觸碰他逆鱗的後果。",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentTC = "可憐的西格早就做好了犧牲自己的準備，但按父親的作風，維爾莉特也無法幸免。",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300
        },
        [51009884] = {
          ContentTC = "而我則告訴他們：唯一的辦法，就是在拿到贖金後盡可能拖延時間，同時想辦法製造混亂讓維爾莉特逃跑。",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300
        },
        [51009885] = {
          ContentTC = "真是可笑，驚慌失措的他居然真的獨自去拖延衛戍部隊，期待一個重病的小姑娘在火災中逃出生天……",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentTC = "我抓住了這個機會，殺死了那個礙事的小可憐，用她的身份擺脫了那棟破房子，也擺脫了我的父親，擺脫了所有阻止我踏上舞台的一切。",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,true,DoNotOverride,2.8",
          ContentTC = "……",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302
        },
        [51009888] = {
          ContentTC = "啊呀，得到了自己十幾年來日思夜想的真相，你看起來並不開心，吉賽爾女士。",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300
        },
        [51009889] = {
          ContentTC = "不可理喻……就為了這種理由？就為了這種理由害死了兩個人？！你把人命當成什麼了！",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentTC = "那麼你打算怎麼做？去滿世界宣揚薇奧萊塔的惡毒手段讓我身敗名裂？又或者……現在就為他們兩人報仇？",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentTC = "……我原本只是想揭露這一切，然後把你交給衛戍部隊。",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302
        },
        [51009892] = {
          ContentTC = "（吉賽爾從腰間拔出短劍，她憤怒的神情，讓你似乎感覺自己聽到了攥緊劍柄柄，又或者是幾乎要把牙齒咬碎的碾磨聲。）",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentTC = "（如果再不阻止她，那柄利刃毫無疑問會在下一刻劃開這冰湖城最美妙的歌喉。無論如何，一場命案是你不願看到的。）",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1
        },
        [51009894] = {
          ContentTC = "{nickname}？你為什麼會在這裡？",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300
        },
        [51009895] = {
          ContentTC = "閃開，我無法容忍這樣的敗類繼續活在世上！",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentTC = "（吉賽爾似乎因憤怒失去了理智，得想辦法讓她冷靜下來。）",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "冷靜下來，吉賽爾，或許事情並不是你想的那樣。",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentTC = "你聽到她剛才說的那些話了嗎？這讓我怎麼冷靜？！",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentTC = "有我們兩個在這裡，她跑不掉的。所以，至少先冷靜下來讓我問她幾個問題！",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,true,DoNotOverride,2.8",
          ContentTC = "…………",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentTC = "你問吧。",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "在那之前，薇奧萊塔女士，這個東西你有印象嗎？",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentTC = "那是……",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentTC = "（薇奧萊塔下意識地將手伸向自己腦後，在確認到熟悉的觸感後愣在了原地。）",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}"
        },
        [51009905] = {
          ContentTC = "看你的反應，我想的果然沒錯……這條緞帶，是你放在西格墓前的吧？",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001
        },
        [51009906] = {
          ContentTC = "你曾經告訴過我，這條緞帶來自你的一位摯友，你是為了她的夢想才站上舞台的。",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentTC = "你還真是個天真的傻瓜，居然連那麼肉麻的謊言也會相信。",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "或許吧，所以我去找多納特借來了這條緞帶，並且確認了它的來曆。",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentTC = "多納特告訴了我維爾莉特的事。他說那是個才華橫溢的姑娘，如果不是貧窮和罹患重病，她也許會成為一名優秀的劇作家。",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001
        },
        [51009910] = {
          ContentTC = "雖然命運沒能眷顧那個女孩，但她從未放棄。即便幾乎不能下床行動，她也還是用另外的方式追尋著自己的夢想。",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001
        },
        [51009911] = {
          ContentTC = "她希望能讓世界上最好的演員表演她創作的作品，把她在生命的最後寫下的她最滿意的故事傳遍整個阿特拉西亞。",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001
        },
        [51009912] = {
          ContentTC = "那部作品的名字是——",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "……三幕劇《普蒂妮》。後來被改編為同名歌劇。",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "嗯，你已經意識到了，繼續說謊只會讓你的處境更危險。所以……",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "說的也是，劇本總該有結局的。",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "在這種時候說懸疑劇的經典台詞嗎……",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentTC = "如果每一部懸疑劇的觀眾都如你一樣敏銳，那些劇作家也無需絞盡腦汁思考如何把劇本再改簡單些了。",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentTC = "你們在說什麼？這是什麼意思？",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "很簡單，吉賽爾。如果薇奧萊塔真的只把維爾莉特當做隨意丟棄的工具，她怎麼會給自己取一個和維爾莉特如此相似的名字呢？",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          ContentTC = "我繼續說我的猜測吧：十六年前，西格為了籌到錢給維爾莉特治病，綁架了艾諾拉·魯斯福德……也就是如今的薇奧萊塔。",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentTC = "在被綁架的期間，艾諾拉結識了生病臥床的維爾莉特。你們就是在那時成為了摯友。",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001
        },
        [51009922] = {
          ContentTC = "但好景不長……",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001
        },
        [51009923] = {
          ContentTC = "維爾莉特察覺到了自己已經時日無多，她不希望哥哥為了虛無縹緲的可能性一錯再錯，於是寫信給哥哥的好友多納特，希望他阻止西格。",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001
        },
        [51009924] = {
          ContentTC = "如她所想，多納特最終還是找到了吉賽爾，向你舉報了西格綁架了艾諾拉的事。不過我猜，那個時候恐怕維爾莉特已經……",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "啊……說來好笑，明明是被人綁架，但那段時光卻是我出生以來最快樂的回憶。",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentTC = "雖然把我綁在了房間裡，但西格並沒有打算傷害我，甚至並未對我有過多的關注，只是在屋子裡匆忙地走來走去。",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300
        },
        [51009927] = {
          ContentTC = "當時的我清楚地知道屋子裡還有第三個人，那是個女孩子，總會在心情好的時候哼著歌……",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300
        },
        [51009928] = {
          ContentTC = "或許是因為西格實在無法同時照顧兩個無法自理的人，所以幾天後，他給我解了綁，允許我在一樓自由行動。",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我總是在他外出的時候去二樓和維爾莉特偷偷見面，我們會一起聊她寫的故事。她會把她的想法告訴我，而我則把存在於她想象中的畫面表演出來。",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300
        },
        [51009930] = {
          ContentTC = "「親愛的人兒，請不要為我悲傷！在這個無眠之夜，我將遠航——」",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009931] = {
          ContentTC = "「風兒鼓起船帆，我撐起木槳——燈塔映在海裡啊，月光多明亮！」",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009932] = {
          ContentTC = "謝謝你，艾諾拉……你演得很好，很好。嗬嗬……我想象中的普蒂妮啊，她就是你的樣子……熱烈，勇敢，心兒永遠向著自由……",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009933] = {
          ContentTC = "謝謝！這個是我自己瞎唱的……不過我認識一位很優秀的作曲家！他叫卡瓦拉多西。我們可以拜托他把《普蒂妮》改編成歌劇——",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009934] = {
          ContentTC = "……不過我應該沒有機會演唱了。",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009935] = {
          ContentTC = "我已經十八歲了。父親已經給我安排好了婚事，就在兩個月後。對方也是煉金院的年輕長官。",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009936] = {
          ContentTC = "我想我接下來的一生，不是要待在小房間裡做個瓷娃娃一樣的漂亮擺件，就是要和那些該死的月髓液罐子打一輩子交道了。",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009937] = {
          ContentTC = "不，不……艾諾拉，不應該是這樣的——你有著雲雀一樣的歌喉……你不屬於小房間……而是更大的，更大的舞台……",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009938] = {
          ContentTC = "每一個熱愛歌唱的人……都有資格在舞台上熠熠發光……無論是索拉還是卡戎，是富有還是貧窮……",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009939] = {
          ContentTC = "我會想辦法讓哥哥放你離開。我的身體已經沒有辦法了，我不知道還有沒有機會把《普蒂妮》的最後一幕寫完……",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009940] = {
          ContentTC = "但艾諾拉，請你答應我，一定要走上舞台，把我們的《普蒂妮》唱給所有人……",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009941] = {
          ContentTC = "「每一個熱愛歌唱的人，都有資格在舞台上熠熠發光。無論他們是索拉還是卡戎，是富有還是貧窮。」這是維爾莉特的遺願，也是我一生的箴言。",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300
        },
        [51009942] = {
          ContentTC = "……後來，當我在維爾莉特病逝後，在頹廢的西格面前唱出終於完稿的《普蒂妮》最後一幕時，他的眼裡充滿驚訝，卻又像是在一片死灰中稍稍燃起了火星。",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300
        },
        [51009943] = {
          ContentTC = "我們仍有彌補維爾莉特的機會，她的快樂、她的憂傷、她的希望、她的思念全都寄存在這部作品裡。我想讓這部作品聞名世界——我可以做到，我也必須做到。",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300
        },
        [51009944] = {
          ContentTC = "她和我都是為舞台而生的，即便病魔就這樣讓一位天才陨落，我也要帶著她的靈魂踏上舞台。",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300
        },
        [51009945] = {
          ContentTC = "所以為了讓你能夠擺脫你父親的控製，以及實現維爾莉特的遺願，西格決定配合你演一出戲。",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentTC = "不……不可能，如果真的是這樣，那她剛剛又為什麼……",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentTC = "你帶著預設好的答案而來，吉賽爾。如果薇奧萊塔女士沒有順著你的意思說下去，她害怕她的學生羅莎琳會遭遇不測。",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001
        },
        [51009948] = {
          ContentTC = "什……",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "我有個請求……我不會逃跑的，所以陪我去一個地方走走，可以嗎？",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentTC = "可以，但最好不要想耍什麼花樣。",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          ContentTC = "這裡已經重建了，但在我眼裡，它的每一寸磚石都還是當年的樣子。",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentTC = "維爾莉特，我又來看你了……和我們的作品一起。",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentTC = "已經有聰明的傢伙知道了我們的故事，但不知道為什麼，我並不害怕，反而有些輕鬆。也許是因為我終於可以堂堂正正對你說……西格的事，對不起。",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300
        },
        [51009954] = {
          ContentTC = "（薇奧萊塔的指尖在牆壁上輕輕拂過，像是在和多年不見老友訴說著過往的經曆。或許是發覺已經到了應當離別的時候，她才會選擇在此刻回到這裡。）",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "謝謝你們縱容我的任性……",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentTC = "所以，薇奧萊塔，你主動擔下罪行還有另一個原因——西格的死並不在你的預料之中，對嗎？",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentTC = "……法布瑞斯·魯斯福德，那是個冷酷無情的男人。那些礦工因為他幾乎食不果腹，手下的衛戍部隊也因為他的殘暴管理苦不堪言。",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "就連自己的親生女兒，那個男人也不留情面地否定她的一切，踐踏她的夢想，禁錮她的自由，強迫那個可憐的孩子按照他規劃好的無趣的人生去成長。",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentTC = "可就是這樣一個冷酷無情的人，卻因為親生女兒的死，越過了所有的審判流程親自將綁架犯處決——即使那會讓他被名利場上的敵人抓住把柄，最終被解職。",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300
        },
        [51009960] = {
          ContentTC = "我設想過無數種方案，要怎麼在逃出他的掌控之後，再想辦法悄悄把書信送到法庭上去，這樣就能把西格救出來。但我唯獨沒想到……",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300
        },
        [51009961] = {
          ContentTC = "你的父親比你想象中愛你……",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentTC = "……後來，我無數次想要說出實情，但海伯利亞只是起點，她的作品還需要我傳遍整個世界——我必須遵守我的承諾，至少我必須要這麼想。",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentTC = "所以當你找上我的時候，我反而感到有些輕鬆……我已經有了很多學生，他們都是擁有天賦的孩子，他們可以代替我把《普蒂妮》帶上更多更廣闊的舞台。",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentTC = "而你，只需要在這裡承認吉賽爾的指控，就可以洗去西格身上本不屬於他的罪名。",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001
        },
        [51009965] = {
          ContentTC = "……我會跟你走的，吉賽爾。但必須在你放了羅莎琳·馬格努斯之後。",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300
        },
        [51009966] = {
          ContentTC = "不管是為了我自己，還是為了西格和維爾莉特，她都絕對不能有事。",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300
        },
