        },
        [51010021] = {
          ContentTC = "你能將三件看似毫無關聯的事件聯係在一起，並書寫這場皆大歡喜的結局，你的聰慧和行動力令我驚歎。",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300
        },
        [51010022] = {
          ContentTC = "所以，我有另一個重要的委托，希望你可以接下。事關我的另一位學生，報酬不是問題，等你得空了，來劇院找我就好。",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300
        },
        [51010023] = {
          ContentTC = "不過無需在今夜——今夜屬於歌曲和遠航。願二位拋卻煩惱，度過一個美妙的假日。",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300
        },
        [51010024] = {
          ContentTC = "你找到了薇奧萊塔為你安排的座位，在觀眾席等待著演出開場。",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025
        },
        [51010025] = {
          ContentTC = "隨著看台的燈光逐漸熄滅，洪亮的女聲唱白帶著你的期待與好奇從幕布後侵染到整個演出廳。",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026
        },
        [51010026] = {
          ContentTC = "看台下異常安靜，尚未習慣這種環境的你稍稍有些不安。",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027
