          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentTC = "你只是做出了每一個堅守底線的人會做出的選擇，不要為此有負擔。就當是幫忙抓到了一個離家出走的孩子，好嗎？",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300
        },
        [51010072] = {
