          ContentTC = "看來人都到齊了？",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302
        },
        [51010073] = {
          ContentTC = "吉賽爾女士也來了，給，這是二位的門票。",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentTC = "那我就不客氣了。已經和衛戍部隊的朋友們打過招呼了，直到演出結束前他們都不會有動作。",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentTC = "非常感謝。演出快要開始了，我先失陪去後台了。",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentTC = "那我們也進去吧，雖然好像是我導致的，不過薇奧萊塔的告別演出的確讓人期待。",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302
        },
        [51010077] = {
          ContentTC = "好。",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001
        },
        [51010078] = {
          ContentTC = "你找到了薇奧萊塔為你安排的座位，在觀眾席等待著演出開場。",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079
        },
        [51010079] = {
          ContentTC = "隨著看台的燈光逐漸熄滅，洪亮的女聲唱白帶著你的期待與好奇從幕布後侵染到整個演出廳。",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080
        },
        [51010080] = {
          ContentTC = "看台下異常安靜，尚未習慣這種環境的你稍稍有些不安。",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081
        },
        [51010081] = {
          ContentTC = "控製住對精彩橋段的讚美並非易事，你害怕自己無意識的感歎擾了他人雅興。",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082
        },
        [51010082] = {
          ContentTC = "不過這種擔憂是多餘的——",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083
        },
        [51010083] = {
          ContentTC = "為劇中人所牽動的你甚至忘記了鼓掌，直至演出結束……",
          DialogueId = 51010083,
          GUID = "7FB2C9BE"
        },
        [51010084] = {
