          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302
        },
        [51010088] = {
          ContentTC = "別跟我陰陽怪氣！我命令你，馬上帶我找到艾諾拉！",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304
        },
        [51010089] = {
          ContentTC = "您似乎忘了一件事，我現在已經不是衛戍部隊的人了，您也不是。我只是作為一介平民向衛戍部隊提供了一些線索而已。",
