        [51010121] = {
          ContentTC = "如果你以後遇到了一個叫普蒂妮的女孩，請一定要認出我，我也一定會認出你的。",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122
        },
        [51010122] = {
          ContentTC = "原來是這樣啊，看來箱子小姐她平安踏上自己的旅途了。這麼說來你是——",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "噓——雖然我認可你們的揭發，但還是會保守秘密的孩子更可愛哦。",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          ContentTC = "就這麼暴露身份，你不怕我再找麻煩？",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302
        },
        [51010125] = {
          ContentTC = "「薇奧萊塔」不會再登台，可我短期內並不打算離開這裡。當然，就算你再次揭發，我也不會有怨言。只是事關我的另一位學生，我無法棄之不顧。",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010126] = {
          ContentTC = "……",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302
        },
        [51010127] = {
          ContentTC = "……感謝你的沉默。",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          ContentTC = "那麼失陪了，願二位度過一個美妙的假日。",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentTC = "哈，我就知道，那樣的女人怎麼可能乖乖束手就擒。",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          ContentTC = "你看起來好像有點高興？",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          ContentTC = "這樣嗎？說實話，我也糾結過到底要不要犧牲活人的生活去換死者的清白……",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          ContentTC = "如你所見，我做出了選擇，這是吉賽爾的執著。",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302
        },
        [51010133] = {
          ContentTC = "不過既然能在二選一的局面被打破後而感到開心，說明我這十六年來也有了成長不是嗎？",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302
        },
        [51010134] = {
          ContentTC = "要是十六年前的我也能像現在一樣，或許就不會有人因此逝去了。",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302
        },
        [51010135] = {
          ContentTC = "這不是你的錯，吉賽爾。",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          ContentTC = "放心，我沒有難過，我只是在想「狩月人吉賽爾」歇業後要去做點什麼。",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302
        },
        [51010137] = {
          ContentTC = "我放棄當演員了，看過薇奧萊塔的演出之後很難再誇下這種海口啊……",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302
        },
        [51010138] = {
          ContentTC = "因為感覺很賺錢。",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010139] = {
          ContentTC = "就別挖苦我了，真正的神探。",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010140] = {
          ContentTC = "那現在呢，你打算做什麼？",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          ContentTC = "嗯……不知道。不過反正時間還有很多，我會慢慢想。",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302
        },
        [51010142] = {
          ContentTC = "畢竟舞台那麼大，總會找到適合自己的那個角色的。",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentTC = "請等一下！",
          DialogueId = 51010143,
          FacialId = {
            [1] = "700300:CM_Smile01",
            [2] = "700302:CM_Angry01",
            [3] = "100001:Angry01"
          },
          GUID = "7FB2AA92",
          NextDialogue = 51009894,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010201] = {
          ContentTC = "♪熔爐焚燒黎明 傾倒出白雪與鐵的城塞……",
          DialogueId = 51010201,
          GUID = "7FB2DD1A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2DD1A"
        },
        [51010202] = {
          ContentTC = "♪熔爐焚燒黎明 傾倒出白雪與鐵的城塞\n齒輪高歌 吞沒晨星 讚頌北地的偉大時代——",
          DialogueId = 51010202,
          GUID = "7FB2DD44",
          NextDialogue = 51010203,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD44"
        },
        [51010203] = {
          ContentTC = "嗯？你叫我……",
          DialogueId = 51010203,
          GUID = "7FB2DD6E",
          LookAt = {
            [1] = "700342:n(0)"
          },
          NextOptions = {
            [1] = 510102031,
            [2] = 510102032
          },
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_End"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD6E"
        },
        [51010204] = {
          ContentTC = "謝謝你，陌生的旅人！不過這首歌還沒有完成，或許你可以和我一起來創作它。",
          DialogueId = 51010204,
          GUID = "7FB2DD98",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD98"
        },
        [51010205] = {
          ContentTC = "很抱歉打擾到你！不過我問過那邊的士兵，這座城市的廣場並沒有張貼律令，禁止一位吟遊詩人在這裡唱歌。",
          DialogueId = 51010205,
          GUID = "7FB2DDC2",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDC2"
        },
        [51010206] = {
          ContentTC = "後一句應該是什麼呢……",
          DialogueId = 51010206,
          GUID = "7FB2DDEC",
          NextDialogue = 51010207,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDEC"
        },
        [51010207] = {
          ContentTC = "我想我應該寫「風」……每個地方的風都是不同的……",
          DialogueId = 51010207,
          GUID = "7FB2DE16",
          NextDialogue = 51010208,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE16"
        },
        [51010208] = {
          ContentTC = "艾利西安的風是融化在晚禱裡的乳香，盧卡的風是畫室的鬆節油和咖啡店的焦糖，伊瑟爾的風是混著野薄荷的油墨……",
          DialogueId = 51010208,
          GUID = "7FB2DE40",
          NextDialogue = 51010209,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE40"
        },
        [51010209] = {
          ContentTC = "那麼海伯利亞的「風」是什麼呢？",
          DialogueId = 51010209,
          GUID = "7FB2DE6A",
          NextOptions = {
            [1] = 510102091,
            [2] = 510102092,
            [3] = 510102093
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE6A"
        },
        [51010210] = {
          ContentTC = "嗯……你說的有道理。這裡有很多鋼鐵的森林，就像這座城市一樣。",
          DialogueId = 51010210,
          GUID = "7FB2DE94",
          NextDialogue = 51010211,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE94"
        },
        [51010211] = {
          ContentTC = "雖然吹起來有些冷，但風會捎來那些齒輪和引擎的聲音，它們摸起來總是滾燙的。",
          DialogueId = 51010211,
          GUID = "7FB2DEBE",
          NextDialogue = 51010212,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEBE"
        },
        [51010212] = {
          ContentTC = "士兵的槍管或許也是滾燙的，雖然他們的表情是冷的……",
          DialogueId = 51010212,
          GUID = "7FB2DEE8",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEE8"
        },
        [51010213] = {
          ContentTC = "嗯！這座城市的四分之三是由雪組成的。因為這裡的人說，冰湖城總是在下雪，融雪季只有短短的三個月~",
          DialogueId = 51010213,
          GUID = "7FB2DF12",
          NextDialogue = 51010214,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF12"
        },
        [51010214] = {
          ContentTC = "而且風和雪總是在一起的，這是大自然給我們的經典搭配！",
          DialogueId = 51010214,
          GUID = "7FB2DF3C",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF3C"
        },
        [51010215] = {
          ContentTC = "「眼淚」嗎……是這首歌前面沒有用過的意象呢……",
          DialogueId = 51010215,
          GUID = "7FB2DF66",
          NextDialogue = 51010216,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF66"
        },
        [51010216] = {
          ContentTC = "…………",
          DialogueId = 51010216,
          GUID = "7FB2DF90",
          NextDialogue = 51010217,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF90"
        },
        [51010217] = {
          ContentTC = "第一天來到這座廣場時，我看到一位目盲的小醜在廣場表演，他說他的眼是多年前被鍋爐熏壞的。一個孩子被表演逗得狂笑不止，他的仆人便拋下銀幣。",
          DialogueId = 51010217,
          GUID = "7FB2DFBA",
          NextDialogue = 51010218,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFBA"
        },
        [51010218] = {
          ContentTC = "我現在坐的這條長椅上，一個退伍老兵叫喊著，兜售自己最後一枚勳章。旁邊的長椅上，一個消瘦的母親擠出乾癟的奶水喂給她重病的孩子。",
          DialogueId = 51010218,
          GUID = "7FB2DFE4",
          NextDialogue = 51010219,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFE4"
        },
        [51010219] = {
          ContentTC = "……我想那時，吹過這座廣場的風，捎來的就是「眼淚」吧。",
          DialogueId = 51010219,
          GUID = "7FB2E00E",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E00E"
        },
        [51010220] = {
          ContentTC = "謝謝你的建議，如冰原上玫瑰一般的{性别:先生|小姐}……我想，我很快就可以完成這首歌了。",
          DialogueId = 51010220,
          GUID = "7FB2E038",
          SpeakNpcId = 700342,
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E038"
        },
        [51010221] = {
          ContentTC = "謝謝你的建議，如冰原上玫瑰一般的{性别:先生|小姐}。",
          DialogueId = 51010221,
          GUID = "7FB2E062",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E062"
        },
        [51010301] = {
          ContentTC = "卡戎之民的霧海神話……",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          ContentTC = "……最有趣的就是這一篇，它說霧海中的萬物都在生和死的循環中，你覺得呢？伊——",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          ContentTC = "啊，是你！我記得你的，我們上次就在這兒說過話。",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          ContentTC = "你有看到我的朋友嗎？一個紅發的女孩子，剛才應該就在這兒……",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          ContentTC = "沒有見過。",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306
        },
        [51010306] = {
          ContentTC = "謝謝！那我繼續等一會兒。她常常突然離開，又突然回來。",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          ContentTC = "這幾天，我們在這兒收集了許多卡戎之民的古老神話。我很驚訝，這裡的人竟然不避諱講這些。",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          ContentTC = "在我們的故鄉艾利西安，那裡的卡戎之民地位比這裡崇高得多。他們坐在高台上，與神問答，執掌權柄。但在那兒，討論古老的神話是一件危險的事。",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          ContentTC = "對了，你知道卡戎之民的神話嗎？",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          ContentTC = "知道一點。",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312
        },
        [51010311] = {
          ContentTC = "不知道。",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312
        },
        [51010312] = {
          ContentTC = "「卡戎」，這個詞的意思是「來自霧海之人」……",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          ContentTC = "霧海是一切的原點。聖樹自霧海生長，天之樹是它龐大的枝葉，世界則立於聖樹之上。",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          ContentTC = "聖樹綻放純白的花，從中走出母神茵布拉。她創造萬物，其中就有父神埃斯刻。母神與父神誕育出卡戎之民共同的先祖。",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          ContentTC = "但執掌<W>死之權能</>的埃斯刻卻成為災厄的化身，並最終帶來叫做「日蝕」的末日。",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          ContentTC = "在末日中，執掌<H>生之權能</>的母神庇護了她的子民，她散碎的靈魂飄向海洋，最終歸於霧海——",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          ContentTC = "父神的身軀則化為大地，他高高舉起的手臂化為山嶽，永遠伸向不知何時歸來的神明。",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          ContentTC = "是個有些傷感的故事。",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319
        },
        [51010319] = {
          ContentTC = "嗯，不過在這些古老的神話裡，還有另一個有趣的故事。",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          ContentTC = "有個故事說，埃斯刻和茵布拉已經在末日後的新世界，以新生的樣貌出現。",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          ContentTC = "而新生的他們則會帶來新的一輪末日，以及再一度毀滅，再一度新生。",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          ContentTC = "世界在無盡的循環之中，萬物都在新生與死亡間輪回往復。",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          ContentTC = "看來古人也不喜歡悲劇的結局。",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324
        },
        [51010324] = {
          ContentTC = "不過……我有些在意的是，為什麼這個故事的作者堅信父神和母神得到了新生？或者說，是什麼「定義」了茵布拉和埃斯刻的本質呢？",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          ContentTC = "是他們的肉體，他們的靈魂？……還是其他？",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          ContentTC = "假設——我是說假設，一位偉大的魔法師把我們腳下的大地重新變成了埃斯刻的模樣——那麼這個埃斯刻，和新生的埃斯刻，哪個才是我們的父神大人呢？",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          ContentTC = "原來你是這樣認為的……謝謝！你的觀點啟發了我很多。",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          ContentTC = "很多創作都是從一個無聊的問題開始的，不是嗎？",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          ContentTC = "謝謝你，如蠟燭上火焰一般的{性别:先生|小姐}。我很喜歡這些神話，現在我已經有了關於它們的歌。",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          ContentTC = "是什麼讓我們得以成為「我們」？",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          ContentTC = "蓋雷亞劇院……",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          ContentTC = "又見面了，如白沙上石榴石一般的{性别:先生|小姐}。你很喜歡到這兒來呢，我也是。",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          ContentTC = "你去過蓋雷亞劇院嗎？",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          ContentTC = "噢！真讓人羨慕，你一定很富有。",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          ContentTC = "嗯……你也是嗎。",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          ContentTC = "和軍團？不可思議。看來你身上也有很多很多故事。",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          ContentTC = "我在盧卡去過大大小小的歌劇院，但總被海伯利亞的劇院關在門外。",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          ContentTC = "雖然知道卡戎之民在這兒過得不算好，但公共設施收的監護金比我想象中還要昂貴。",
          DialogueId = 51010408,
          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          ContentTC = "雖然幸運地趕上這座城市一年一度不需要門票的狂歡日，但又不幸地聽說那兒發生了械戰……簡直糟透了。",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          ContentTC = "不過還好——我收集了很多樂譜！書店的價格還算公道，很多人也同意讓我用歌聲交換樂譜，還有一位神秘的好心朋友教過我一首有名的歌！",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          ContentTC = "前陣子的一個晚上，我靠著一堵牆，就著月光，隨意彈唱一首從淘來的樂譜裡學的歌。那首歌的旋律並不複雜，很容易便能記住。",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        },
        [51010412] = {
          ContentTC = "但我唱完後，牆的那邊突然傳來奇怪的敲擊聲……我能聽出來，那些敲擊聲遵循著某種規律。你知道的，吟遊詩人總是對節奏格外敏感。",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          ContentTC = "我試著拆解了那些節奏。那是一種很常見的古老密碼，用兩種不同的敲擊聲就可以傳遞訊號。",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          ContentTC = "牆那邊的人告訴我，我唱錯了。那是一首歌劇的唱段，在這兒很有名——因為沒讀過劇本的緣故，我未能準確理解那首歌所傳遞給觀眾的情感。",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          ContentTC = "他則是因為某種原因沒有辦法開口說話和演唱。但他可以用這種訊號教給我如何演唱。",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          ContentTC = "但當我終於在他的教導下學會了那首歌，跑到對面那條街打算當面道謝時，那位好心人已經不在那裡了。",
          DialogueId = 51010416,
          GUID = "7FB30060",
          NextOptions = {
            [1] = 510104161,
            [2] = 510104162
          },
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30060"
        },
        [51010417] = {
          ContentTC = "噢，真是太巧了！",
          DialogueId = 51010417,
          GUID = "7FB3008A",
          NextDialogue = 51010418,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3008A"
        },
        [51010418] = {
          ContentTC = "如果方便，還請你代我向那位先生或女士致謝——還有祝福！雖然不知道他為什麼無法開口，但還是祝願他早日好起來。我能感受到，他喜歡唱歌，非常喜歡。",
          DialogueId = 51010418,
          GUID = "7FB300B4",
          NextDialogue = 51010419,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300B4"
        },
        [51010419] = {
          ContentTC = "……好，我會的。",
          DialogueId = 51010419,
          GUID = "7FB300DE",
          NextDialogue = 51010421,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300DE"
        },
        [51010420] = {
          ContentTC = "是呢……也藏著很多故事。",
          DialogueId = 51010420,
          GUID = "7FB30108",
          NextDialogue = 51010421,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30108"
        },
        [51010421] = {
          ContentTC = "說來，這裡的歌劇和盧卡的很不一樣……",
          DialogueId = 51010421,
          GUID = "7FB30132",
          NextDialogue = 51010422,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30132"
        },
        [51010422] = {
          ContentTC = "盧卡的歌劇是焰火，伊瑟爾的歌劇是風。",
          DialogueId = 51010422,
          GUID = "7FB3015C",
          NextDialogue = 51010423,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3015C"
        },
        [51010423] = {
          ContentTC = "而這裡的歌劇是大地。廣闊的，苦痛的大地……",
          DialogueId = 51010423,
          GUID = "7FB30186",
          NextDialogue = 51010424,
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30186"
        },
        [51010424] = {
          ContentTC = "我和朋友就快要離開這兒了，在那之前，我還想為這裡寫一首歌。",
          DialogueId = 51010424,
          GUID = "7FB301B0",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB301B0"
        },
        [51010425] = {
          ContentTC = "♪白雪是她的羊水 晨昏線是她的臍帶……",
          DialogueId = 51010425,
          GUID = "7FB301DA",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/env/700342/7FB301DA"
        },
        [51010426] = {
          ContentTC = "♪白雪是她的羊水 晨昏線是她的臍帶\n  她娩出偉大與苦難 彙入白山下的黑鐵搖籃……",
          DialogueId = 51010426,
          GUID = "7FB30204",
          SpeakNpcId = 700342,
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30204"
        },
        [51010501] = {
          ContentTC = "通行證——喂，說你呢，通行證帶了嗎？",
          DialogueId = 51010501,
          GUID = "7FB30E52",
          NextOptions = {
            [1] = 51010502,
            [2] = 51010504,
            [3] = 51010506
          },
          SpeakNpcId = 700111
        },
        [51010502] = {
          ContentTC = "（聲淚俱下地哭訴你是一個遵紀守法的人，只是碰巧又忘帶通行證了。）",
          DialogueId = 51010502,
          GUID = "7FB30E7C",
          ImprPlusId = 1004,
          NextDialogue = 51010503
        },
        [51010503] = {
          ContentTC = "算了吧，你這話聽得我耳朵都快起繭子了。去去，快過去，別搞得那麼顯眼。",
          DialogueId = 51010503,
          GUID = "7FB30EA6",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        },
        [51010504] = {
          ContentTC = "（掏出卡蜜拉幫忙偽造的通行證。）",
          DialogueId = 51010504,
          GUID = "7FB30ED0",
          ImprPlusId = 1003,
          NextDialogue = 51010505
        },
        [51010505] = {
          ContentTC = "通行證核驗無誤，準許放行。",
          DialogueId = 51010505,
          GUID = "7FB30EFA",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        },
        [51010506] = {
          ContentTC = "凱文先生，你也不想你在淚湖邊上那件事被上級知……",
          DialogueId = 51010506,
          GUID = "7FB30F24",
          ImprPlusId = 1005,
          NextDialogue = 51010507
        },
        [51010507] = {
          ContentTC = "別念了！！！讓你過還不行嗎！！",
          DialogueId = 51010507,
          GUID = "7FB30F4E",
          NextDialogue = 51010508,
          SpeakNpcId = 700111
        }
      }
    end
  },
