          DialogueId = 51010513,
          GUID = "7FB3104A",
          NextDialogue = 51010514
        },
        [51010514] = {
          ContentTC = "沒事的話就趕緊回去吧，我今天又沒法安穩下班了。",
          DialogueId = 51010514,
          GUID = "7FB31074",
          NextDialogue = 51010515,
