        },
        [51010515] = {
          ContentTC = "唉……怎麼一遇到你就出意外……",
          DialogueId = 51010515,
          GUID = "7FB3109E",
          SpeakNpcId = 700111
        },
        [51010516] = {
          ContentTC = "喂！通行證……啊，是你啊，過去吧過去吧。",
          DialogueId = 51010516,
          GUID = "7FB310C8",
          SpeakNpcId = 700111
        },
        [51010601] = {
          ContentTC = "好心人，求你幫幫我……給多少都可以……救救身無分文的老人家吧……",
          DialogueId = 51010601,
