          DialogueId = 51010606,
          GUID = "7FB31F8C",
          ImprPlusId = 1005,
          NextDialogue = 51010607
        },
        [51010607] = {
          ContentTC = "你……唉。",
          DialogueId = 51010607,
          GUID = "7FB31FB6",
          NextDialogue = 51010608,
          SpeakNpcId = 700338
        },
        [51010608] = {
