          DialogueId = 51010609,
          GUID = "7FB3200A",
          SpeakNpcId = 700338
        },
        [51010610] = {
          ContentTC = "身體健全的你應該去工作。",
          DialogueId = 51010610,
          GUID = "7FB32034",
          ImprPlusId = 1001,
          NextDialogue = 51010611
        },
        [51010611] = {
