          DialogueId = 51010611,
          GUID = "7FB3205E",
          NextDialogue = 51010612,
          SpeakNpcId = 700338
        },
        [51010612] = {
          ContentTC = "可那又有什麼用？有時候啊，他們奪走你的工作，就和奪走這破碗中的硬幣一樣簡單。",
          DialogueId = 51010612,
          GUID = "7FB32088",
          NextDialogue = 51010613,
          SpeakNpcId = 700338
        },
        [51010613] = {
          ContentTC = "在漂亮屋子裡乞討，在大街上乞討，都一樣的。",
          DialogueId = 51010613,
          GUID = "7FB320B2",
          SpeakNpcId = 700338
        },
        [51010614] = {
          ContentTC = "好好活著吧……唉，這世道，越是好人越難立足啊。",
          DialogueId = 51010614,
          GUID = "7FB320DC",
          SpeakNpcId = 700338
        },
        [51010701] = {
