          GUID = "7FB32FCA",
          NextDialogue = 51010706
        },
        [51010706] = {
          ContentTC = "末日……末日要來了，沒人能夠逃掉。",
          DialogueId = 51010706,
          GUID = "7FB32FF4",
          NextDialogue = 51010707,
          SpeakNpcId = 700337
        },
        [51010707] = {
          ContentTC = "花店裡的花朵不再鮮豔，褪色成純白的石楠……",
          DialogueId = 51010707,
          GUID = "7FB3301E",
          NextDialogue = 51010708,
          SpeakNpcId = 700337
        },
        [51010708] = {
          ContentTC = "廣場上的貓貓不再毛絨絨，而是像石膏雕像一樣又硬又滑……",
          DialogueId = 51010708,
          GUID = "7FB33048",
          NextDialogue = 51010709,
          SpeakNpcId = 700337
        },
        [51010709] = {
          ContentTC = "麵包房再也做不出蓬鬆的麵包，無論怎麼烘焙都會變成黑漆漆的爛泥……",
          DialogueId = 51010709,
          GUID = "7FB33072",
          NextDialogue = 51010710,
          SpeakNpcId = 700337
        },
        [51010710] = {
          ContentTC = "我最愛吃的冰棍也不再冰冰涼涼，放到嘴裡只會黏糊糊粘住嗓子……",
          DialogueId = 51010710,
          GUID = "7FB3309C",
          NextDialogue = 51010711,
          SpeakNpcId = 700337
        },
        [51010711] = {
          ContentTC = "大家也開始慢慢變得和皎皎一樣高，和皎皎一樣白……",
          DialogueId = 51010711,
          GUID = "7FB330C6",
          NextDialogue = 51010712,
          SpeakNpcId = 700337
        },
        [51010712] = {
          ContentTC = "到最後……",
          DialogueId = 51010712,
          GUID = "7FB330F0",
          NextDialogue = 51010713,
          SpeakNpcId = 700337
        },
        [51010713] = {
          ContentTC = "花店的阿姨，麵包房的大嬸，賣冰棍的爺爺……大家都會變成皎皎！",
          DialogueId = 51010713,
          GUID = "7FB3311A",
          NextOptions = {
            [1] = 51010714,
            [2] = 51010715
          },
          SpeakNpcId = 700337
        },
        [51010714] = {
          ContentTC = "皎皎好，我也想變成皎皎。",
          DialogueId = 51010714,
          GUID = "7FB33144",
          ImprPlusId = 1005,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010715] = {
          ContentTC = "好可怕的末日……",
          DialogueId = 51010715,
          GUID = "7FB3316E",
          ImprPlusId = 1004,
          NextDialogue = 51010716,
          SpeakNpcId = 700337
        },
        [51010716] = {
          ContentTC = "你……你的頭發、你的衣服、你的身高……你已經開始變成皎皎了嗎！",
          DialogueId = 51010716,
          GUID = "7FB33198",
          NextDialogue = 51010717,
          SpeakNpcId = 700337
        },
        [51010717] = {
          ContentTC = "末日……末日果然來了，一切都完了。",
          DialogueId = 51010717,
          GUID = "7FB331C2",
          NextDialogue = 51010718,
          SpeakNpcId = 700337
        },
        [51010718] = {
          ContentTC = "（悲觀皎皎無力地垂下雙手，看向你的視線透過你的身軀，透過層疊的建築，失神地望向昏暗的天空。仿佛她口中的末日馬上就要變為現實。）",
          DialogueId = 51010718,
          GUID = "7FB331EC",
          NextDialogue = 51010719
        },
        [51010719] = {
          ContentTC = "（幾分鍾過去，理所當然的什麼都未發生，悲觀皎皎的視線再也沒有落到你的身上，不斷呢喃著末日將至。）",
          DialogueId = 51010719,
          GUID = "7FB33216",
          NextDialogue = 51010720
        },
        [51010720] = {
          ContentTC = "（你有些好奇變成皎皎會是怎麼樣的感覺，但現在你能做的，也只有轉身離開了。）",
          DialogueId = 51010720,
          GUID = "7FB33240"
        },
        [51010721] = {
          ContentTC = "末日，末日已經開始了……",
          DialogueId = 51010721,
          GUID = "7FB3326A",
          SpeakNpcId = 700337
        },
        [51010801] = {
          ContentTC = "您好，這朵花與您今天的裝扮很相稱……如果那孩子還在的話，一定也會這麼說吧。",
          DialogueId = 51010801,
          GUID = "7FB33F8A",
          NextOptions = {
            [1] = 51010802,
            [2] = 51010803
          },
          SpeakNpcId = 700203
        },
        [51010802] = {
          ContentTC = "你認識我？",
          DialogueId = 51010802,
          GUID = "7FB33FB4",
          NextDialogue = 51010804
        },
        [51010803] = {
          ContentTC = "「那孩子」難道指的是……",
          DialogueId = 51010803,
          GUID = "7FB33FDE",
          NextDialogue = 51010804
        },
        [51010804] = {
          ContentTC = "我的女兒。她的名字是賽琪。",
          DialogueId = 51010804,
          GUID = "7FB34008",
          NextDialogue = 51010805,
          SpeakNpcId = 700203
        },
        [51010805] = {
          ContentTC = "她曾在給我的信裡提到過「一個新交的朋友」。您的模樣與那封書信中的描述很相似……如果我認錯了人，還請您諒解。",
          DialogueId = 51010805,
          GUID = "7FB34032",
          NextOptions = {
            [1] = 51010806,
            [2] = 51010807
          },
          SpeakNpcId = 700203,
          bForbidSkipOptions = true
        },
        [51010806] = {
          ContentTC = "……她是怎麼說我的？",
          DialogueId = 51010806,
          GUID = "7FB3405C",
          NextDialogue = 51010809
        },
        [51010807] = {
          ContentTC = "……是的，你認錯人了。",
          DialogueId = 51010807,
          GUID = "7FB34086",
          NextDialogue = 51010808
        },
        [51010808] = {
          ContentTC = "（你像逃跑一樣轉身離開。那是你們心中共同的隱痛，你不願再觸及它。）",
          DialogueId = 51010808,
          GUID = "7FB340B0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51010809] = {
          ContentTC = "你很聰明，又很勇敢。聽說你到冰湖城的第一天就深入格雷姆廢礦，在她見過的所有同齡人裡，你是最強大的一個。更重要的是……",
          DialogueId = 51010809,
          GUID = "7FB340DA",
          NextDialogue = 51010810,
          SpeakNpcId = 700203
        },
        [51010810] = {
          ContentTC = "「{性别:他|她}和冰湖城的大多數人不一樣，{性别:他|她}還有著我們早就丟失了的東西——對正義和自由的渴望。」",
          DialogueId = 51010810,
          GUID = "7FB34104",
          NextDialogue = 51010811,
          SpeakNpcId = 700203
        },
        [51010811] = {
          ContentTC = "「從{性别:他|她}身上，我看到了另一種不一樣的生活。」",
          DialogueId = 51010811,
          GUID = "7FB3412E",
          NextDialogue = 51010812,
          SpeakNpcId = 700203
        },
        [51010812] = {
          ContentTC = "這是她信裡寫的。",
          DialogueId = 51010812,
          GUID = "7FB34158",
          NextDialogue = 51010813,
          SpeakNpcId = 700203
        },
        [51010813] = {
          ContentTC = "（女人熟練地複述著——顯然，那封信她不知看了多少遍。）",
          DialogueId = 51010813,
          GUID = "7FB34182",
          NextDialogue = 51010814
        },
        [51010814] = {
          ContentTC = "對不起，我沒能……",
          DialogueId = 51010814,
          GUID = "7FB341AC",
          NextDialogue = 51010815,
          SpeakNpcId = 100001
        },
        [51010815] = {
          ContentTC = "不要說抱歉，孩子。我看得到，有你最後的陪伴，她是快樂的。這就夠了。是我們應該感謝你。",
          DialogueId = 51010815,
          GUID = "7FB341D6",
          NextDialogue = 51010816,
          SpeakNpcId = 700203
        },
        [51010816] = {
          ContentTC = "請帶上這束花吧，我們的祝福與你同在。",
          DialogueId = 51010816,
          GUID = "7FB34200",
          SpeakNpcId = 700203
        },
        [51010817] = {
