        [60030501] = {
          ContentTC = "我們可以走啦，但再探一會險的話，應該能獲得更多報酬吧！要繼續嗎？",
          DialogueId = 60030501,
          Duration = 4,
          GUID = "9647B212",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600305/9647B212"
        },
        [60030601] = {
          ContentTC = "不行不行，敵人被打倒的位置離藥劑台太遠的話，它就回收不到了！",
          DialogueId = 60030601,
          Duration = 4,
          GUID = "9647C27A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600306/9647C27A"
        },
        [60030701] = {
          ContentTC = "你看起來好虛弱，是不是血清已經不多了……",
          DialogueId = 60030701,
          Duration = 4,
          GUID = "9647D2E2",
          NextDialogue = 60030702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600307/9647D2E2"
        },
        [60030702] = {
          ContentTC = "不要硬撐，快去把藥劑台裡做好的血清用掉吧！",
          DialogueId = 60030702,
          Duration = 4,
          GUID = "9647D2E3",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600307/9647D2E3"
        },
        [60030801] = {
          ContentTC = "我啟動了一個新的藥劑台！",
          DialogueId = 60030801,
          Duration = 4,
          GUID = "9647E34A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600308/9647E34A"
        },
        [60030901] = {
          ContentTC = "嗚哇，藥劑台裡一點血清都沒了，我們也快走吧！",
          DialogueId = 60030901,
          Duration = 4,
          GUID = "9647F3B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600309/9647F3B2"
        },
        [60031001] = {
          ContentTC = "快把做好的血清用掉吧。",
          DialogueId = 60031001,
          Duration = 4,
          GUID = "9648041A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600310/9648041A"
        },
        [60031101] = {
          ContentTC = "嗷……毒物……增加……死亡……加速……嗷嗷……",
          DialogueId = 60031101,
          Duration = 4,
          GUID = "96481482",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600311/96481482"
        },
        [60031201] = {
          ContentTC = "敵人來啦！還好這個藥劑台開始工作了,在它附近作戰吧！",
          DialogueId = 60031201,
          Duration = 4,
          GUID = "964824EA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600312/964824EA"
        },
        [60040101] = {
          ContentTC = "哎，我們真是什麽奇怪的委托都能接到呢，快點去找到委托人說的車子吧。",
          DialogueId = 60040101,
          Duration = 4,
          GUID = "964DD912",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600401/964DD912"
        },
        [60040201] = {
          ContentTC = "哇哦，靠近發個信號以後車子真的動了，我們靠近車子時要註意自己的狀態哦。可別在車子到目標點前就倒下了。",
          DialogueId = 60040201,
          Duration = 4,
          GUID = "964DE97A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600402/964DE97A"
        },
        [60040301] = {
          ContentTC = "可惡，檢查站的門又被關上了！把他們打倒然後衝過去吧！",
          DialogueId = 60040301,
          Duration = 4,
          GUID = "964DF9E2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600403/964DF9E2"
        },
        [60040401] = {
          ContentTC = "檢查站的門可以開啦，繼續出發！滴滴滴~",
          DialogueId = 60040401,
          Duration = 4,
          GUID = "964E0A4A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600404/964E0A4A"
        },
        [60040501] = {
          ContentTC = "車子被前面的障礙物攔住了，破壞掉它吧！",
          DialogueId = 60040501,
          Duration = 4,
          GUID = "964E1AB2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600405/964E1AB2"
        },
        [60040601] = {
          ContentTC = "不行呀，障礙物還是沒碎，全力破壞它然後沖過去吧！",
          DialogueId = 60040601,
          Duration = 4,
          GUID = "964E2B1A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600406/964E2B1A"
        },
        [60040701] = {
          ContentTC = "哼哼，小小障礙物怎麽可能攔得住我們嘛，去車子邊繼續發信號讓委托人把車子開起來吧！",
          DialogueId = 60040701,
          Duration = 4,
          GUID = "964E3B82",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600407/964E3B82"
        },
        [60040801] = {
          ContentTC = "可惡，檢查站的門被關上了！打倒那個軍官然後衝過去吧！",
          DialogueId = 60040801,
          Duration = 4,
          GUID = "964E3B86",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600408/964E3B86"
        },
        [60050101] = {
          ContentTC = "這次委托是讓我們把這片區域的敵人都驅逐出去嗎？真是簡單易懂呀，讓我們放開手腳大幹一場吧！",
          DialogueId = 60050101,
          Duration = 4,
          GUID = "965441B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600501/965441B2"
        },
        [60050201] = {
          ContentTC = "驅逐了這麽多敵人，他們總該吸取教訓了吧！收工收工，回去領報酬嘍。",
          DialogueId = 60050201,
          Duration = 4,
          GUID = "9654521A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600502/9654521A"
        },
        [60060101] = {
          ContentTC = "目標已倒下，委托失敗",
          DialogueId = 60060101,
          Duration = 1,
          GUID = "965AAA52",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600601/965AAA52"
        },
        [60060201] = {
          ContentTC = "這次的委托有點復雜，我們得先解救被困的目標，再護送目標安全撤離。",
          DialogueId = 60060201,
          Duration = 4,
          GUID = "965ABABA",
          NextDialogue = 60060202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABABA"
        },
        [60060202] = {
          ContentTC = "先按照委托人給的標記，找到敵人據點裡的<H>密室區域</>吧。",
          DialogueId = 60060202,
          Duration = 4,
          GUID = "965ABAE4",
          NextDialogue = 60060203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABAE4"
        },
        [60060203] = {
          ContentTC = "說起來，這個目標到底是什麽人啊……值這麽多錢又神神秘秘的，該不會是什麽大人物吧？",
          DialogueId = 60060203,
          Duration = 4,
          GUID = "965ABB0E",
          NextDialogue = 60060204,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB0E"
        },
        [60060204] = {
          ContentTC = "又或者，是和委托人有什麽不可告人的關系……哼哼……",
          DialogueId = 60060204,
          Duration = 4,
          GUID = "965ABB38",
          NextDialogue = 60060205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB38"
        },
        [60060205] = {
          ContentTC = "你別忘了，委托人說過不要多問，否則我們就拿不到錢了。",
          DialogueId = 60060205,
          Duration = 4,
          GUID = "965ABB62",
          NextDialogue = 60060206,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB62"
        },
        [60060206] = {
          ContentTC = "呃——好吧，那我就忍一忍，不好奇了。",
          DialogueId = 60060206,
          Duration = 3,
          GUID = "965ABB8C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600602/965ABB8C"
        },
        [60060301] = {
          ContentTC = "根據事先調查到的情報，密室區域是由很多獨立的小房間組成的，其中一間關著我們要找的目標。",
          DialogueId = 60060301,
          Duration = 4,
          GUID = "965ACB22",
          NextDialogue = 60060302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB22"
        },
        [60060302] = {
          ContentTC = "看來敵人很謹慎啊！萬一發現有人來營救，他們搞不好會破罐破摔，把目標滅口……",
          DialogueId = 60060302,
          Duration = 4,
          GUID = "965ACB4C",
          NextDialogue = 60060303,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB4C"
        },
        [60060303] = {
          ContentTC = "盡量小心一些吧！",
          DialogueId = 60060303,
          Duration = 2.5,
          GUID = "965ACB76",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600603/965ACB76"
        },
        [60060401] = {
          ContentTC = "快看，前面就是密室區域了！要註意避開敵人中的<H>巡邏單位</>哦！",
          DialogueId = 60060401,
          Duration = 4,
          GUID = "965ADB8A",
          NextDialogue = 60060402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADB8A"
        },
        [60060402] = {
          ContentTC = "如果他們發出了警報，目標可就危險啦！",
          DialogueId = 60060402,
          Duration = 3,
          GUID = "965ADBB4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600604/965ADBB4"
        },
        [60060501] = {
          ContentTC = "嗚哇，這些密室還真是長得一模一樣啊……不過，以小僕從的聰明才智，解開這些機關綽綽有余",
          DialogueId = 60060501,
          Duration = 4,
          GUID = "965AEBF2",
          NextDialogue = 60060502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEBF2"
        },
        [60060502] = {
          ContentTC = "抓緊時間找到目標所在的密室吧！本魔王會在旁邊幫你註意動靜的。",
          DialogueId = 60060502,
          Duration = 4,
          GUID = "965AEC1C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600605/965AEC1C"
        },
        [60060601] = {
          ContentTC = "不、不要靠近我……！",
          DialogueId = 60060601,
          Duration = 2.5,
          GUID = "965AFC5A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060602,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC5A"
        },
        [60060602] = {
          ContentTC = "別怕，我們是狩月人，來救你的！",
          DialogueId = 60060602,
          Duration = 3,
          GUID = "965AFC84",
          NextDialogue = 60060603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600606/965AFC84"
        },
        [60060603] = {
          ContentTC = "咦……？啊，我知道了，是那個人讓你們來的，一定是的……",
          DialogueId = 60060603,
          Duration = 4,
          GUID = "965AFCAE",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 60060604,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCAE"
        },
        [60060604] = {
          ContentTC = "謝謝！我們快走吧，我等不及要見到……",
          DialogueId = 60060604,
          Duration = 4,
          GUID = "965AFCD8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600606/965AFCD8"
        },
        [60060701] = {
          ContentTC = "不好啦，那個巡邏的傢伙發出了警報！",
          DialogueId = 60060701,
          Duration = 3,
          GUID = "965B0CC2",
          NextDialogue = 60060702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CC2"
        },
        [60060702] = {
          ContentTC = "和我想的一樣，他們果然狗急跳墻，打算把目標處理掉了！",
          DialogueId = 60060702,
          Duration = 4,
          GUID = "965B0CEC",
          NextDialogue = 60060703,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0CEC"
        },
        [60060703] = {
          ContentTC = "得趕在他們之前救出目標才行。",
          DialogueId = 60060703,
          Duration = 2,
          GUID = "965B0D16",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600607/965B0D16"
        },
        [60060801] = {
          ContentTC = "哎，我好像聽見目標的呼救聲了！",
          DialogueId = 60060801,
          Duration = 2,
          GUID = "965B1D2A",
          NextDialogue = 60060802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D2A"
        },
        [60060802] = {
          ContentTC = "就是那間密室，快去救人吧！",
          DialogueId = 60060802,
          Duration = 2,
          GUID = "965B1D54",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/600608/965B1D54"
        },
        [60060901] = {
          ContentTC = "我……好像動不了了……拜托，請救救我……！",
          DialogueId = 60060901,
          Duration = 3,
          GUID = "965B2D92",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 60060902,
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B2D92"
        },
        [60060902] = {
          ContentTC = "我不能……在這裡……倒下……我還沒有……",
          DialogueId = 60060902,
          Duration = 3,
          GUID = "965B3DFA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 930001,
          VoiceName = "voice/$Locale$/story/0/600609/965B3DFA"
        },
        [60110101] = {
          ContentTC = "這次的任務是追捕目標，如果他要反抗的話，就只好先打倒他了。",
          DialogueId = 60110101,
          Duration = 4,
          GUID = "967AB572",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601101/967AB572"
        },
        [60110201] = {
          ContentTC = "目標被打倒啦，趕緊在他恢復體力逃跑前抓住目標吧。",
          DialogueId = 60110201,
          Duration = 4,
          GUID = "967AC5DA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601102/967AC5DA"
        },
        [60110301] = {
          ContentTC = "任務完成啦，我們也準備離開吧。",
          DialogueId = 60110301,
          Duration = 4,
          GUID = "967AD642",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601103/967AD642"
        },
        [60110501] = {
          ContentTC = "這次的目標擅長【潛匿】，不僅可以隱藏自己……",
          DialogueId = 60110501,
          Duration = 4,
          GUID = "967AF712",
          NextDialogue = 60110502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF712"
        },
        [60110502] = {
          ContentTC = "還能用模樣相同的替身迷惑對手！不要被他騙啦！",
          DialogueId = 60110502,
          Duration = 4,
          GUID = "967AF73C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601105/967AF73C"
        },
        [60110601] = {
          ContentTC = "這次的目標十分【善戰】，還隨身攜帶著機器人提升自己的戰鬥能力！",
          DialogueId = 60110601,
          Duration = 4,
          GUID = "967B077A",
          NextDialogue = 60110602,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B077A"
        },
        [60110602] = {
          ContentTC = "爆破機器人會自爆造成傷害，務必小心！",
          DialogueId = 60110602,
          Duration = 4,
          GUID = "967B07A4",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601106/967B07A4"
        },
        [60110701] = {
          ContentTC = "這次的目標有著豐富的【武裝】，小心他的地雷和槍托！",
          DialogueId = 60110701,
          Duration = 4,
          GUID = "967B180C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601107/967B180C"
        },
        [60120101] = {
          ContentTC = "這就是我們要勘察的區域啦，讓我找找哪裡適合放下我寶貴的勘探器。",
          DialogueId = 60120101,
          Duration = 4,
          GUID = "96811E12",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601201/96811E12"
        },
        [60120201] = {
          ContentTC = "勘探器裝好啦，記得要保護好它哦，如果它不動了，那就從敵人身上找點勘探模組帶回來吧。",
          DialogueId = 60120201,
          Duration = 4,
          GUID = "96812E7A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601202/96812E7A"
        },
        [60120301] = {
          ContentTC = "勘察完成，這是謝禮，你要陪我繼續勘察還是回去休息呢？",
          DialogueId = 60120301,
          Duration = 4,
          GUID = "96813EE2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601203/96813EE2"
        },
        [60120401] = {
          ContentTC = "勘探器不動啦，去找點勘探模組回來吧。",
          DialogueId = 60120401,
          Duration = 4,
          GUID = "96814F4A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601204/96814F4A"
        },
        [60120501] = {
          ContentTC = "那邊有個地方也需要勘探一下，我幫你標注出來了，等你過去了我就裝一下勘探器。",
          DialogueId = 60120501,
          Duration = 4,
          GUID = "96815FB2",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601205/96815FB2"
        },
        [60120601] = {
          ContentTC = "沒錯沒錯，你拿的這些就是勘探模組了，去把它們裝到我寶貴的勘探器裡吧！",
          DialogueId = 60120601,
          Duration = 4,
          GUID = "9681701A",
          SpeakNpcId = 900005,
          VoiceName = "voice/$Locale$/story/0/601206/9681701A"
        },
        [60130101] = {
          ContentTC = "神棄者同盟在這裡安裝了很危險的炸彈！不破壞掉它的話所有人都危險了。",
          DialogueId = 60130101,
          Duration = 4,
          GUID = "968786B2",
          NextDialogue = 60130102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786B2"
        },
        [60130102] = {
          ContentTC = "委託人說有三名神棄者同盟策劃了這起爆炸，找到他們的話我會告訴你。",
          DialogueId = 60130102,
          Duration = 4,
          GUID = "968786DC",
          NextDialogue = 60130103,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968786DC"
        },
        [60130103] = {
          ContentTC = "要是先擊敗他們再去破壞「大煙花」的引信，應該能讓委託變輕鬆很多的吧！",
          DialogueId = 60130103,
          Duration = 4,
          GUID = "968787DE",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601301/968787DE"
        },
        [60130201] = {
          ContentTC = "打倒一個！從他身上的信件來看……找到了，另外兩名神棄者同盟大概就在我標的這片區域。",
          DialogueId = 60130201,
          Duration = 4,
          GUID = "9687971A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601302/9687971A"
        },
        [60130301] = {
          ContentTC = "「大煙花」的引信暴露出來了，破壞掉它吧！",
          DialogueId = 60130301,
          Duration = 4,
          GUID = "9687A782",
          NextDialogue = 60130302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A782"
        },
        [60130302] = {
          ContentTC = "真是的，這炸彈明明不是我們裝的，周圍的敵人怎麼都衝著我們來啦……",
          DialogueId = 60130302,
          Duration = 4,
          GUID = "9687A784",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601303/9687A784"
        },
        [60130401] = {
          ContentTC = "拆掉「大煙花」了，我們也快跑吧。",
          DialogueId = 60130401,
          Duration = 4,
          GUID = "9687B7EA",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601304/9687B7EA"
        },
        [60130501] = {
          ContentTC = "發現神棄者同盟的首領了！",
          DialogueId = 60130501,
          Duration = 4,
          GUID = "9687C852",
          NextDialogue = 60130502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C852"
        },
        [60130502] = {
          ContentTC = "既然委託讓我們阻止「大煙花」爆炸，那打倒這些首領也會對我們的計畫更有利吧，我們上！",
          DialogueId = 60130502,
          Duration = 4,
          GUID = "9687C87C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/601305/9687C87C"
        },
        [60130601] = {
          ContentTC = "我的傑作……還沒完成……",
          DialogueId = 60130601,
          Duration = 4,
          GUID = "9687C880",
          SpeakNpcId = 200034,
          VoiceName = "voice/$Locale$/story/0/601305/9687C880"
        },
        [60130701] = {
          ContentTC = "傲慢而盲目的傢伙們，一起加入這場混戰吧！",
          DialogueId = 60130701,
          Duration = 4,
          GUID = "9687C884",
          SpeakNpcId = 200035,
          VoiceName = "voice/$Locale$/story/0/601305/9687C884"
        },
        [60130801] = {
          ContentTC = "原來，我才是玩具……有趣。那就讓我看看，你要如何逃離死亡。",
          DialogueId = 60130801,
          Duration = 4,
          GUID = "9687C888",
          SpeakNpcId = 200036,
          VoiceName = "voice/$Locale$/story/0/601305/9687C888"
        },
        [60140001] = {
          ContentTC = "……呵，困獸之鬥。",
          DialogueId = 60140001,
          Duration = 4,
          GUID = "968DDEEA",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleStart"
        },
        [60140002] = {
          ContentTC = "讓我看看你的極限。",
          DialogueId = 60140002,
          Duration = 4,
          GUID = "968DDF14",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_battleEnd"
        },
        [60140003] = {
          ContentTC = "勇氣可嘉，繼續。",
          DialogueId = 60140003,
          Duration = 4,
          GUID = "968DDF3E",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_condemn"
        },
        [60140004] = {
          ContentTC = "鬧劇，該結束了。",
          DialogueId = 60140004,
          Duration = 4,
          GUID = "968DDF68",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill06"
        },
        [60140005] = {
          ContentTC = "顫栗吧。",
          DialogueId = 60140005,
          Duration = 4,
          GUID = "968DDF92",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_01"
        },
        [60140006] = {
          ContentTC = "螻蟻，無處可藏。",
          DialogueId = 60140006,
          Duration = 4,
          GUID = "968DDFBC",
          VoiceName = "sfx/boss/Xibi/vo_$Locale$_skill07_02"
        },
        [60140201] = {
          ContentTC = "……不要……過來……！",
          DialogueId = 60140201,
          Duration = 4,
          GUID = "968DFFBA",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleStart"
        },
        [60140202] = {
          ContentTC = "是的。我沒有……活下去的……資格……",
          DialogueId = 60140202,
          Duration = 6,
          GUID = "968DFFE4",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageStart"
        },
        [60140203] = {
          ContentTC = "啊啊——",
          DialogueId = 60140203,
          Duration = 4,
          GUID = "968E000E",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_flyingStageEnd"
        },
        [60140204] = {
          ContentTC = "呃啊啊啊啊——",
          DialogueId = 60140204,
          Duration = 4,
          GUID = "968E0038",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_Condemn"
        },
        [60140205] = {
          ContentTC = "……謝謝……你……",
          DialogueId = 60140205,
          Duration = 5,
          GUID = "968E0062",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_battleEnd"
        },
        [60140206] = {
          ContentTC = "……啊啊……",
          DialogueId = 60140206,
          Duration = 2,
          GUID = "968E008C",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill03"
        },
        [60140207] = {
          ContentTC = "……快……逃……！",
          DialogueId = 60140207,
          Duration = 4,
          GUID = "968E00B6",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill10"
        },
        [60140401] = {
          ContentTC = "我最親愛的孩子，謝謝你來到世界上。",
          DialogueId = 60140401,
          Duration = 4,
          GUID = "968E208A",
          VoiceName = "voice/$Locale$/story/1002/101125/968E208A"
        },
        [60140402] = {
          ContentTC = "你是我們一生的驕傲。",
          DialogueId = 60140402,
          Duration = 3,
          GUID = "968E20B4",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20B4"
        },
        [60140403] = {
          ContentTC = "賽琪，來拉鉤，我們要做一輩子的好朋友！",
          DialogueId = 60140403,
          Duration = 4,
          GUID = "968E20DE",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20DE"
        },
        [60140404] = {
          ContentTC = "我會記住你曾經活過。",
          DialogueId = 60140404,
          Duration = 3,
          GUID = "968E2108",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2108"
        },
        [60140405] = {
          ContentTC = "我們等你回來。",
          DialogueId = 60140405,
          Duration = 2.5,
          GUID = "968E2132",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2132"
        },
        [60140406] = {
          ContentTC = "命運啊，求你憐憫我唯一一次，讓我幫她實現這個願望吧。",
          DialogueId = 60140406,
          Duration = 6,
          GUID = "968E215C",
          VoiceName = "voice/$Locale$/story/1002/101125/968E215C"
        },
        [60140407] = {
          ContentTC = "帶上這朵花吧，它會給你帶來好運。",
          DialogueId = 60140407,
          Duration = 3,
          GUID = "968E2186",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2186"
        },
        [60140408] = {
          ContentTC = "你可以去一座小島，在那裡蓋幾間房子，在房子邊種滿白色的花。",
          DialogueId = 60140408,
          Duration = 6,
          GUID = "968E21B0",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21B0"
        },
        [60140409] = {
          ContentTC = "賽琪，我來帶你回家。",
          DialogueId = 60140409,
          Duration = 3,
          GUID = "968E21DA",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21DA"
        },
        [60140501] = {
          ContentTC = "所有審判，皆為正義。",
          DialogueId = 60140501,
          Duration = 5,
          GUID = "968E30F2",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleStart"
        },
        [60140502] = {
          ContentTC = "竟敢反抗律法……",
          DialogueId = 60140502,
          Duration = 5,
          GUID = "968E311C",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_condemn"
        },
        [60140503] = {
          ContentTC = "你……在怒火面前證明了自己。",
          DialogueId = 60140503,
          Duration = 5,
          GUID = "968E3146",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd"
        },
        [60140504] = {
          ContentTC = "開始你最後的狡辯。",
          DialogueId = 60140504,
          Duration = 5,
          GUID = "968E3170",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01"
        },
        [60140505] = {
          ContentTC = "在宣判前，醜陋地掙紮吧。",
          DialogueId = 60140505,
          Duration = 5,
          GUID = "968E319A",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02"
        },
        [60140506] = {
          ContentTC = "在枷鎖中迎接死亡。",
          DialogueId = 60140506,
          Duration = 5,
          GUID = "968E31C4",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01"
        },
        [60140507] = {
          ContentTC = "律法會歷數你的罪狀。",
          DialogueId = 60140507,
          Duration = 5,
          GUID = "968E31EE",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02"
        },
        [60140508] = {
          ContentTC = "休想逃脫火焰的囚籠。",
          DialogueId = 60140508,
          Duration = 5,
          GUID = "968E3218",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill03"
        },
        [60149001] = {
          ContentTC = "打打打打打劫，唔……這傢伙看起來好猛，溜了溜了。",
          DialogueId = 60149001,
          Duration = 5,
          GUID = "9693A37A",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r01"
        },
        [60149002] = {
          ContentTC = "可惡！怎麽是你，再再再見。",
          DialogueId = 60149002,
          Duration = 3.8,
          GUID = "9693A3A4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r02"
        },
        [60149003] = {
          ContentTC = "留留留下買路財！嘖，怎麽今天一上來就碰到硬茬子，告辭。",
          DialogueId = 60149003,
          Duration = 6.7,
          GUID = "9693A3CE",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r03"
        },
        [60149004] = {
          ContentTC = "除了打劫，逃跑我也是專業的！",
          DialogueId = 60149004,
          Duration = 3.5,
          GUID = "9693A3F8",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill01"
        },
        [60149005] = {
          ContentTC = "舍不得孩子套不著狼，這些都給你，別再追啦！",
          DialogueId = 60149005,
          Duration = 5.1,
          GUID = "9693A422",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill02"
        },
        [60149006] = {
          ContentTC = "咋還在追我啊，這個給你行了吧。",
          DialogueId = 60149006,
          Duration = 3.5,
          GUID = "9693A44C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          ContentTC = "你使那麽大勁幹啥呢！",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          ContentTC = "可惡，以後走夜路小心點！",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          ContentTC = "啊啊啊啊啊，我要生氣了！",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          ContentTC = "笨笨笨蛋，追不上我吧，桀桀桀桀桀桀~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          ContentTC = "這次是我大意了，下次我一定要把你打得抱頭大哭，嗚……",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          ContentTC = "東西南北四條街，打聽打聽誰是爹，道上誰不知道我打劫皎皎的名號！",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          ContentTC = "跟我鬥，你還是太年輕了呀~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          ContentTC = "哼，我打打打劫皎皎可不是好惹的。",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          ContentTC = "呼，呼……你咋還不累呢，吃啥玩意長大的啊。",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          ContentTC = "離我遠點！",
