        [60170001] = {
          ContentTC = "死……死！",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          ContentTC = "吼……呃……啊啊啊啊……",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          ContentTC = "嘎嗷嗷嗷……吼……吼！！",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60200101] = {
          ContentTC = "不好，我們被敵人發現了！",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602001/96B46312"
        },
        [60200201] = {
          ContentTC = "發現敵人，在他們呼叫同伴前阻止他們吧。",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A"
        },
        [60200301] = {
          ContentTC = "當心，敵人要去呼叫同伴了！再這樣下去就麻煩啦。",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2"
        },
        [60200401] = {
          ContentTC = "他們要去呼叫同伴，快想想辦法阻止一下呀！",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A"
        },
        [60200501] = {
          ContentTC = "真是的，我們躲藏得這麼好居然都被發現了，沒辦法，快點解決掉他們吧。",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2"
        },
        [60210101] = {
          ContentTC = "委託人只能幫我們爭取到一點點時間，我們趁現在快把那三台奇奇怪怪的裝置拆掉吧！",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C"
        },
        [60210201] = {
          ContentTC = "好耶，全都拆掉了，委託圓滿完成！",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602102/9687C892"
        },
        [60210301] = {
          ContentTC = "委託人說沒時間了，我們也快撤吧！",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/0/602103/9687C896"
        },
        [60220101] = {
          ContentTC = "什麼什麼，第一場比賽這就開始了嗎？",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
