        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          ContentTC = "近日島上穢獸日漸活躍，所有居民準備好船隻與物資，隨時準備出海避險。",
          DialogueId = 70010101,
