        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          ContentTC = "居民謹記，為了避免海伯利亞官員發現我們，出海捕魚時遠離不明船隻。\n祖輩為了避免捲入無謂的戰爭逃到這裡，相信他們的智慧，嚴守告誡。",
          DialogueId = 70010201,
