        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          ContentTC = "彩繪的神像，雖然保持完好，但是周圍的斷壁殘垣顯示著很久以前，這裡曾經發生過一次徹底的劫掠。",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
