        },
        [71000220] = {
          ContentTC = "（擺下貓糧）",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001
        },
        [71000300] = {
          ContentTC = "（野貓蹦跳著跑開幾步以後駐足看向了你，似乎想讓你跟上牠的步伐。）",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006
        },
        [71000310] = {
          ContentTC = "（野貓蹦跳著跑開幾步以後駐足看向了你，似乎想讓你跟上牠的步伐。）",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006
        },
        [71000320] = {
          ContentTC = "（野貓蹦跳著跑開幾步以後駐足看向了你，似乎想讓你跟上牠的步伐。）",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006
        },
        [71000330] = {
          ContentTC = "（野貓圍著你的腳邊開心地轉了兩圈。看著牠滿足的表情，你的內心也得到了極大的治癒。）",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006
        },
        [71000501] = {
          ContentTC = "別打啦，再打我就要使出絕招了……好，我要用了哦……救命啊啊啊啊啊！！！",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005
        },
        [71000502] = {
          ContentTC = "嗚哇哇哇……",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005
        },
        [71000503] = {
          ContentTC = "最後一個，搞定。",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014
        },
        [71000504] = {
          ContentTC = "我去看看附近還有沒有敵人，你自己小心。",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014
        },
        [71000505] = {
          ContentTC = "收到收到，我會注意的！",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015
        },
        [71000506] = {
          ContentTC = "誒，你也來啦。嗚嗚……原來有這麼多人願意幫助我……這是給大家準備的謝禮，以後也請多多關照了。",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "謝謝，探險家大危機解除！繼續冒險囉。",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "謝謝，探險家大危機解除！繼續冒險囉。",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentTC = "（被海浪沖上岸的木桶堆積在沙灘上，找找看的話，也許能發現一些有用的東西。）",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006
        },
        [71000612] = {
          ContentTC = "（木桶底部破了個大洞，不管它曾裝過什麼金銀財寶，現在都是件無用的垃圾。去看看其他木桶吧。）",
          DialogueId = 71000612,
          GUID = "B1BE19E8"
        },
        [71000613] = {
          ContentTC = "（木桶裡除了腐爛的魚蝦以外什麼也沒有，去看看其他木桶吧。）",
          DialogueId = 71000613,
          GUID = "B1BE1A12"
        },
        [71000615] = {
          ContentTC = "（功夫不負有心人，仔細翻找之後，你終於在木桶的夾層裡找到了一些能用的物資。）",
          DialogueId = 71000615,
          GUID = "B1BE1A66"
        },
        [71000701] = {
          ContentTC = "真是頭疼啊，就剩幾條管道了。",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007
        },
        [71000710] = {
          ContentTC = "發生什麼了？",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001
        },
        [71000711] = {
          ContentTC = "哎呀，我得檢查一下城裡這些月髓管有沒有壞。",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007
        },
        [71000721] = {
          ContentTC = "但我的作業繩在上條管子那裡弄斷了，你能幫我上去看一看剩下的幾條管子嗎？",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007
        },
        [71000741] = {
          ContentTC = "剩下的幾條管道我幫你標出來了，真是麻煩你了！",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007
        },
        [71000751] = {
          ContentTC = "（這條管道沒有破損，去看看下一條管道吧。）",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006
        },
        [71000761] = {
          ContentTC = "（最後一條管道也沒有破損，去告訴那名工人吧。）",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006
        },
        [71000771] = {
          ContentTC = "都沒問題？太好了！萬分感謝！",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007
        },
        [71000780] = {
          ContentTC = "（這條管道出現了輕微破損，去告訴那名工人吧。）",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006
        },
        [71000781] = {
          ContentTC = "唉……看來又得加班了，我回去拿點工具，你拿上我的鑰匙，先去幫我關一下月髓管的總閥吧。",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007
        },
        [71000782] = {
          ContentTC = "謝謝，剩下的就交給我吧。",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007
        },
        [71000801] = {
          ContentTC = "{nickname}，{nickname}，快來，我找到新的研究主題了。",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011
        },
        [71000802] = {
          ContentTC = "這次的研究素材在湖對面，你能幫幫我嗎？",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011
        },
        [71000803] = {
          ContentTC = "這就是西奧要研究的東西了，拿點回去給他吧。",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001
        },
        [71000804] = {
          ContentTC = "謝謝你！想要成為偉大的煉金術師，要學習的東西真的好多好多呢……",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011
        },
        [71000805] = {
          ContentTC = "……好吧，我明白了，你的意思是，成為偉大的煉金術師的第一步，就是靠自己的力量尋找研究素材！",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011
        },
        [71000901] = {
          ContentTC = "捉迷藏，捉迷藏，一起來玩捉迷藏！",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008
        },
        [71000902] = {
          ContentTC = "捉迷藏，捉迷藏，一起來玩捉迷藏！",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentTC = "好呀好呀！但是我不想找人，我想藏。",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentTC = "我也是，我發現一個超級隱蔽的地方，躲在那一定能贏！",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentTC = "那怎麼辦？還有人願意和我們一起捉迷藏嗎……",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009
        },
        [71000906] = {
          ContentTC = "（孩子們注意到了路過的你，滿眼期待地等待著你的回應。）",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006
        },
        [71000907] = {
          ContentTC = "（孩子們興奮地跳了起來，一眨眼就消失在了街角。現在該好好想想去哪裡尋找這些孩子了。）",
          DialogueId = 71000907,
          GUID = "B1BE4A4E"
        },
        [71000908] = {
          ContentTC = "哇，這麼快就被你找到了。",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008
        },
        [71000909] = {
          ContentTC = "你好厲害呀。",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009
        },
        [71000910] = {
          ContentTC = "可惡，我居然輸了……",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010
        },
        [71000911] = {
          ContentTC = "好吧好吧，願賭服輸，這是給你的謝禮，下次還要和我們一起玩哦！",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008
        },
        [71001001] = {
          ContentTC = "（一輛嶄新的車輛，這或許是一個……發財的機會？）",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006
        },
        [71001002] = {
          ContentTC = "（車裡的月髓能源裝置裝得滿滿當當，果然是一個發財的機會！）",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006
        },
        [71001003] = {
          ContentTC = "你在幹什麼！快來人啊！",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010
        },
        [71001004] = {
          ContentTC = "（現在不會再有人來阻攔你的腳步了。撬開車鎖，帶走裝滿月髓液的能源裝置，賣個好價錢。一切都在按你的計畫進行，又是令人心情愉悅的一天。）",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006
        },
        [71001005] = {
          ContentTC = "（良知最終戰勝了誘惑，你決定向城門守衛匯報車輛安保的疏漏。）",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006
        },
        [71001006] = {
          ContentTC = "感謝您的通知，我這就派人加強巡邏，這是一點謝禮，還望不要嫌棄。",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010
        },
        [71001101] = {
          ContentTC = "（穢獸來襲，擊退它們！）",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006
        },
        [71001201] = {
          ContentTC = "（雜草淹沒了你與貝蕾曾經留在此處的痕跡，也許應該清理一下神像附近的雜草了。）",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006
        },
        [71001202] = {
          ContentTC = "（在你的努力下，神像附近恢復了整潔，一如你回憶中的景色。）",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006
        },
        [71001301] = {
          ContentTC = "依貝蕾所說，這裡就是我們曾經的家，可我卻一點印象都沒有……",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001
        },
        [71001302] = {
          ContentTC = "也許我該在這附近轉轉，興許能想起些什麼。",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001
        },
        [71001303] = {
