        [71002114] = {
          ContentTC = "來了來了——",
          DialogueId = 71002114,
          GUID = "B1BF1054",
          NextDialogue = 71002115,
          SpeakNpcId = 818007
        },
        [71002115] = {
          ContentTC = "啊？物資少了？哦！2條彈匣和1把步槍是吧。在我這兒呢，剛剛我把自己那份直接拿走了。",
          DialogueId = 71002115,
          GUID = "B1BF107E",
          NextDialogue = 71002116,
          SpeakNpcId = 818007
        },
        [71002116] = {
          ContentTC = "你也太不謹慎了——軍團的物資隨手丟給路人？萬一是同盟的傢伙怎麼交差？",
          DialogueId = 71002116,
          GUID = "B1BF10A8",
          NextDialogue = 71002117,
          SpeakNpcId = 818008
        },
        [71002117] = {
          ContentTC = "啊哈，抱歉抱歉，下次注意，下次注意。",
          DialogueId = 71002117,
          GUID = "B1BF10D2",
          NextDialogue = 71002118,
          SpeakNpcId = 818007
        },
        [71002118] = {
          ContentTC = "{nickname}，這點東西你收下當賠禮吧，連累了你，怪不好意思的。",
          DialogueId = 71002118,
          GUID = "B1BF10FC",
          Scripts = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
          SpeakNpcId = 818007
        },
        [71002201] = {
          ContentTC = "咱不想……不想……不想上工啊……",
          DialogueId = 71002201,
          GUID = "B1BF1E9A",
          SpeakNpcId = 818019
        },
        [71002202] = {
          ContentTC = "唉，老闆非要搞什麼什麼——「讓銀色和平飯店的飯菜走進千家萬戶」，但他完全沒考慮過咱們這些跑腿的苦哇！",
          DialogueId = 71002202,
          GUID = "B1BF1EC4",
          NextDialogue = 71002203,
          SpeakNpcId = 818019
        },
        [71002203] = {
          ContentTC = "需要幫忙嗎？",
          DialogueId = 71002203,
          GUID = "B1BF1EEE",
          NextDialogue = 71002204,
          SpeakNpcId = 100001
        },
        [71002204] = {
          ContentTC = "需要，我非常需要一個人替我上工，不花錢的那種！唉……可惜根本沒有這種好事！",
          DialogueId = 71002204,
          GUID = "B1BF1F18",
          NextDialogue = 71002205,
          SpeakNpcId = 818019
        },
        [71002205] = {
          ContentTC = "你如果非要幫我拎點東西的話，那我除了謝謝，最多只能請你去淚湖邊喝水喝到飽了。",
          DialogueId = 71002205,
          GUID = "B1BF1F42",
          SpeakNpcId = 818019
        },
        [71002206] = {
          ContentTC = "這皎皎身上帶了不少吃的？哥幾個今天看來有口福了呀。",
          DialogueId = 71002206,
          GUID = "B1BF1F6C",
          NextDialogue = 71002207,
          SpeakNpcId = 818057
        },
        [71002207] = {
          ContentTC = "不能給你們！這些菜送不到客人那的話我工錢就要被扣光了……",
          DialogueId = 71002207,
          GUID = "B1BF1F96",
          NextDialogue = 71002208,
          SpeakNpcId = 818019
        },
        [71002208] = {
          ContentTC = "關我們啥事，拿來吧你！",
          DialogueId = 71002208,
          GUID = "B1BF1F97",
          NextDialogue = 71002209,
          SpeakNpcId = 818057
        },
        [71002209] = {
          ContentTC = "住手！",
          DialogueId = 71002209,
          GUID = "B1BF1F98",
          SpeakNpcId = 100001
        },
        [71002210] = {
          ContentTC = "呼……還好湯沒灑，我們快送過去吧……",
          DialogueId = 71002210,
          GUID = "B1BF1FC0",
          SpeakNpcId = 818019
        },
        [71002211] = {
          ContentTC = "搞定搞定，還差最後一份！真是的，老闆能不能少點奇思妙想哇……",
          DialogueId = 71002211,
          GUID = "B1BF20BC",
          SpeakNpcId = 818019
        },
        [71002212] = {
          ContentTC = "這種雜物是怎麼堆到大路上的啊……可惡！怎麼今天所有東西都在跟我作對！",
          DialogueId = 71002212,
          GUID = "B1BF1FEA",
          NextDialogue = 71002218,
          SpeakNpcId = 818019
        },
        [71002213] = {
          ContentTC = "你把吃的拿好，我來清理這些東西吧。",
          DialogueId = 71002213,
          GUID = "B1BF2014",
          SpeakNpcId = 100001
        },
        [71002214] = {
          ContentTC = "居然都清完了！那這時間還來得及！衝衝衝衝衝！",
          DialogueId = 71002214,
          GUID = "B1BF2015",
          SpeakNpcId = 818019
        },
        [71002215] = {
          ContentTC = "總算都送到了……要不是有你，我一點工錢都拿不到了。呼……休息好了，咱也該回去繼續工作了。",
          DialogueId = 71002215,
          GUID = "B1BF203E",
          NextDialogue = 71002216,
          SpeakNpcId = 818019
        },
        [71002216] = {
          ContentTC = "說好的辭職呢？",
          DialogueId = 71002216,
          GUID = "B1BF2068",
          NextDialogue = 71002217,
          SpeakNpcId = 100001
        },
        [71002217] = {
          ContentTC = "（外送皎皎拍了拍身上的灰塵便轉身離開了。回答你問題的答案，也被藏在了她轉身時的那一聲嘆息之中。）",
          DialogueId = 71002217,
          GUID = "B1BF2092",
          SpeakNpcId = 800006
        },
        [71002218] = {
          ContentTC = "不幹了不幹了！我要和老闆說，這破活我不干啦！",
          DialogueId = 71002218,
          GUID = "B1BF1FEB",
          NextDialogue = 71002213,
          SpeakNpcId = 818019
        },
        [71002301] = {
          ContentTC = "嘶……剛剛那下沒摔壞吧……",
          DialogueId = 71002301,
          GUID = "B1BF2F02",
          SpeakNpcId = 818020
        },
        [71002302] = {
          ContentTC = "誰？！",
          DialogueId = 71002302,
          GUID = "B1BF2F2C",
          NextDialogue = 71002303,
          SpeakNpcId = 818020
        },
        [71002303] = {
          ContentTC = "嗯……咳，只是路過的狩月人啊。欸，我說，要不要來幫我個忙？就測下這玩意兒好不好用，很容易的！我會付你報酬。",
          DialogueId = 71002303,
          GUID = "B1BF2F56",
          SpeakNpcId = 818020
        },
        [71002304] = {
          ContentTC = "堅持15秒就差不多了，加油！",
          DialogueId = 71002304,
          GUID = "B1BF2F80",
          SpeakNpcId = 818020
        },
        [71002305] = {
          ContentTC = "居然全都躲過去了……不是說這是從艾利西安繳獲的寶貝嗎，我看跟破銅爛鐵也沒啥區別——啊沒沒，沒什麼，這些錢給你，別到處亂說啊。",
          DialogueId = 71002305,
          GUID = "B1BF2FAA",
          SpeakNpcId = 818020
        },
        [71002306] = {
          ContentTC = "這人被打到怎麼還活蹦亂跳的……不是說這是艾利西安繳獲的寶貝嗎，到底行不行啊——啊沒沒，沒什麼，這些錢給你，別到處亂說啊。",
          DialogueId = 71002306,
          GUID = "B1BF2FD4",
          SpeakNpcId = 818020
        },
        [71002401] = {
          ContentTC = "怎麼勘探器還沒幹活就壞了，我的修理工具呢……",
          DialogueId = 71002401,
          GUID = "B1BF3F6A",
          SpeakNpcId = 818015
        },
        [71002402] = {
          ContentTC = "我們在這種地方都能遇到，太有緣了吧！既然你來了，那要不要幫忙照看下我的寶貝探勘器？",
          DialogueId = 71002402,
          GUID = "B1BF3F94",
          SpeakNpcId = 818015
        },
        [71002403] = {
          ContentTC = "好耶，你就在它邊上不要走動哦，我找到工具了就回來！",
          DialogueId = 71002403,
          GUID = "B1BF3FBE",
          NextDialogue = 71002404,
          SpeakNpcId = 818015
        },
        [71002404] = {
          ContentTC = "看起來是有幾個零件卡住了，把它們弄開的話應該會更好修一些。",
          DialogueId = 71002404,
          GUID = "B1BF3FE8",
          SpeakNpcId = 100001
        },
        [71002405] = {
          ContentTC = "（勘探器的響動將周圍的穢獸吸引了過來，擊退它們吧。）",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006
        },
        [71002406] = {
          ContentTC = "欸，你還幫我把卡住的零件掰開了嗎，好感動！",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015
        },
        [71002407] = {
          ContentTC = "久等啦！我就知道交給你照看肯定沒問題！",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015
        },
        [71002501] = {
          ContentTC = "唉……這破下水道怎麼又堵了……",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021
        },
        [71002502] = {
          ContentTC = "發生什麼事了？",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001
        },
        [71002503] = {
          ContentTC = "這片下水道堵住了，長官給了我個說明書，但我根本看不懂啊……你能幫幫我嗎？",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021
        },
        [71002505] = {
          ContentTC = "說明書上說，遇到下水道堵塞只要開啟三道閘門放水強沖即可。",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001
        },
        [71002507] = {
          ContentTC = "好嘞，接下來第二個在那邊。",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021
        },
        [71002508] = {
          ContentTC = "第三個我看看啊……找到了，就在那！",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021
        },
        [71002509] = {
          ContentTC = "好，我已經完全掌握了！這是我的一點心意，辛苦你啦！",
          DialogueId = 71002509,
          GUID = "B1BF5122",
          SpeakNpcId = 818021
        },
        [71002510] = {
          ContentTC = "嘿，你這法子也不賴嘛，來來，這是給你的報酬。",
          DialogueId = 71002510,
          GUID = "B1BF514C",
          SpeakNpcId = 818021
        },
        [71002511] = {
          ContentTC = "原來是這樣啊，那你能示範一下怎麼操作嗎，我看著學一下。",
          DialogueId = 71002511,
          GUID = "B1BF507B",
          SpeakNpcId = 818021
        },
        [71002601] = {
          ContentTC = "可惡，這鎬子也太不耐用了，剩下這些石頭咋辦呢，總不能讓我用手挖吧……",
          DialogueId = 71002601,
          GUID = "B1BF603A",
          SpeakNpcId = 818023
        },
        [71002602] = {
          ContentTC = "看你的打扮，也是狩月人吧。我接的這個挖石頭委託一個人做不完了，你要不要跟我一起？報酬直接分你一半。",
          DialogueId = 71002602,
          GUID = "B1BF6064",
          NextOptions = {
            [1] = 710026021,
            [2] = 710026022
          },
          SpeakNpcId = 818023,
          bForbidSkipOptions = true
        },
        [71002603] = {
          ContentTC = "好，剩下的這些就交給你了，我來整理下之前挖好的。",
          DialogueId = 71002603,
          GUID = "B1BF608E",
          SpeakNpcId = 818023
        },
        [71002604] = {
          ContentTC = "原來還有這種辦法，太厲害了！",
          DialogueId = 71002604,
          GUID = "B1BF60B8",
          NextDialogue = 71002605,
          SpeakNpcId = 818023
        },
        [71002605] = {
          ContentTC = "辛苦你了，這是說好的報酬。",
          DialogueId = 71002605,
          GUID = "B1BF60E2",
          SpeakNpcId = 818023
        },
        [71002701] = {
          ContentTC = "（一些木桶順著水道漂來，有的還發出著詭異的聲響，謹慎打開的話，也許能發現一些有用的東西。）",
          DialogueId = 71002701,
          GUID = "B1BF70A2",
          SpeakNpcId = 800006
        },
        [71002702] = {
          ContentTC = "（木桶底部破了個大洞，除了風聲穿過的嘶吼，你找不到任何有用的東西，去看看其他木桶吧。）",
          DialogueId = 71002702,
          GUID = "B1BF70CC",
          SpeakNpcId = 800006
        },
        [71002703] = {
          ContentTC = "（木桶裡裝滿了生活垃圾，散發著咕嘟咕嘟的悶響和刺鼻的氣味，去看看其他木桶吧。）",
          DialogueId = 71002703,
          GUID = "B1BF70F6",
          SpeakNpcId = 800006
        },
        [71002704] = {
          ContentTC = "（付出必然要有回報，仔細翻找之後，你果然在木桶的夾層裡找到了一些能用的物資。）",
          DialogueId = 71002704,
          GUID = "B1BF7120",
          SpeakNpcId = 800006
        },
        [71002705] = {
          ContentTC = "（破舊的木桶轟然散架，巨大的噪音將周圍的穢獸吸引了過來，擊敗它們，拿到你應得的戰利品吧。）",
          DialogueId = 71002705,
          GUID = "B1BF714A",
          SpeakNpcId = 800006
        },
        [71002801] = {
          ContentTC = "（坍塌的碎石擋住了前路，將它們清理掉吧。）",
          DialogueId = 71002801,
          GUID = "B1BF810A",
          SpeakNpcId = 800006
        },
        [71002802] = {
          ContentTC = "（你在清理碎石的過程中找到了些能用的物資，將它們收好吧。）",
          DialogueId = 71002802,
          GUID = "B1BF8134",
          SpeakNpcId = 800006
        },
        [71002803] = {
          ContentTC = "（清理碎石的響動將周圍的穢獸吸引了過來，借助洞頂的落石擊退它們吧。）",
          DialogueId = 71002803,
          GUID = "B1BF815E",
          SpeakNpcId = 800006
        },
        [71002804] = {
          ContentTC = "（一番戰鬥後，你在周圍找到了些能用的物資，將它們收好吧。）",
          DialogueId = 71002804,
          GUID = "B1BF8188",
          SpeakNpcId = 800006
        },
        [71002901] = {
          ContentTC = "（敵人在士官的指揮下穩步向你推進，儘快擊敗士官，打亂對方的指揮吧。）",
          DialogueId = 71002901,
          GUID = "B1BF9172",
          SpeakNpcId = 800006
        },
        [71002902] = {
          ContentTC = "（敵人在你冷靜而正確的應對中潰敗。）",
          DialogueId = 71002902,
          GUID = "B1BF919C",
          SpeakNpcId = 800006
        },
        [71002903] = {
          ContentTC = "（士官呼叫了新的援軍，更多的敵人向你襲來了。）",
          DialogueId = 71002903,
          GUID = "B1BF91C6",
          SpeakNpcId = 800006
        },
        [71003001] = {
          ContentTC = "（遊蕩的穢獸不安地嘶吼著，為附近籠罩起一絲不詳的氣息。儘快擊退它們吧。）",
          DialogueId = 71003001,
          GUID = "B1BFA1DA",
          SpeakNpcId = 800006
        },
        [71003002] = {
          ContentTC = "（籠罩于此的不詳氣息越發凝重，你知道，有什麼東西就要降臨了。）",
          DialogueId = 71003002,
          GUID = "B1BFA204",
          SpeakNpcId = 800006
        },
        [71003003] = {
          ContentTC = "（爭鬥的聲響引來了不屈的災厄，不詳的化身終於降臨於此。擊敗它吧，就像過去的無數次一樣。）",
          DialogueId = 71003003,
          GUID = "B1BFA22E",
          SpeakNpcId = 800006
        },
        [71003004] = {
          ContentTC = "（不祥的氣息隨著這些穢獸一同消失了，你知道，這附近暫時安全了。）",
          DialogueId = 71003004,
          GUID = "B1BFA258",
          SpeakNpcId = 800006
        },
        [71003101] = {
          ContentTC = "（最近多了好些覬覦魔靈的傢伙，擊退他們，救下眼前這只可憐的魔靈吧。）",
          DialogueId = 71003101,
          GUID = "B1BFB242",
          SpeakNpcId = 800006
        },
        [71003102] = {
          ContentTC = "（更多敵人從遠處衝了過來。）",
          DialogueId = 71003102,
          GUID = "B1BFB26C",
          SpeakNpcId = 800006
        },
        [71003103] = {
          ContentTC = "（現在，這隻魔靈安全了。）",
          DialogueId = 71003103,
          GUID = "B1BFB296",
          SpeakNpcId = 800006
        },
        [71003201] = {
          ContentTC = "（坍塌的碎石擋住了前路，四周遺落的爆炸物也許能幫你更快地清理這些碎石。）",
          DialogueId = 71003201,
          GUID = "B1BFC2AA",
          SpeakNpcId = 800006
        },
        [71003202] = {
          ContentTC = "（你找到了礦工們的簡易爆破手冊，勉強還能分辨出上面寫的內容。）",
          DialogueId = 71003202,
          GUID = "B1BFC2D4",
          SpeakNpcId = 800006
        },
        [71003203] = {
          ContentTC = "（你找到了一些爆炸物，稍微處理下應該還能用。）",
          DialogueId = 71003203,
          GUID = "B1BFC2FE",
          SpeakNpcId = 800006
        },
        [71003204] = {
          ContentTC = "（你找到了一些引線，稍微處理下應該還能用。）",
          DialogueId = 71003204,
          GUID = "B1BFC328",
          SpeakNpcId = 800006
        },
        [71003206] = {
          ContentTC = "（你依照曠工手冊上的指示安裝好了爆炸物，用它們清空前方區域吧。）",
          DialogueId = 71003206,
          Duration = 3,
          GUID = "B1BFC37C",
          SpeakNpcId = 800006
        },
        [71003207] = {
          ContentTC = "（你在清理碎石的過程中找到了些能用的物資，將它們收好吧。）",
          DialogueId = 71003207,
          GUID = "B1BFC3A6",
          SpeakNpcId = 800006
        },
        [71003501] = {
          ContentTC = "（遠處閃閃發光的東西吸引了你的注意，靠近看看到底是什麼吧。）",
          DialogueId = 71003501,
          GUID = "B1BFF3E2",
          SpeakNpcId = 800006
        },
        [71003502] = {
          ContentTC = "我就說這亮閃閃的破鏡子能引來狩月人吧，動手！",
          DialogueId = 71003502,
          GUID = "B1BFF40C",
          SpeakNpcId = 818028
        },
        [71003504] = {
          ContentTC = "別打了別打了，我們再也不敢了……",
          DialogueId = 71003504,
          GUID = "B1BFF460",
          SpeakNpcId = 818028
        },
        [71003601] = {
