          GUID = "B1C014DE",
          NextOptions = {
            [1] = 710037041,
            [2] = 710037042
          },
          SpeakNpcId = 818019,
          bForbidSkipOptions = true
        },
        [71003705] = {
          ContentTC = "唉……也就只能嘴上過過癮了，你來了就陪咱一起去吧，多個人路上還能解解悶。上工上工……",
          DialogueId = 71003705,
          GUID = "B1C01506",
          SpeakNpcId = 818019
        },
        [71003706] = {
