          NextDialogue = 71005603,
          SpeakNpcId = 100001
        },
        [71005603] = {
          ContentTC = "狩月人是你啊，我的魚線被下面幾塊垃圾纏住了，你能幫幫我嗎？",
          DialogueId = 71005603,
          GUID = "B1C14CBE",
