          GUID = "B1C14CE8",
          SpeakNpcId = 818050
        },
        [71005605] = {
          ContentTC = "呼……拉起來了，謝謝你哈。",
          DialogueId = 71005605,
          GUID = "B1C14D12",
          SpeakNpcId = 818050
        },
        [71005701] = {
