          GUID = "B1C1AF82",
          NextDialogue = 71006206,
          SpeakNpcId = 818055
        },
        [71006206] = {
          ContentTC = "謝謝你幫我驗證了一下哈，我自己再在這裡試試看。今天絕對不能再提著空桶回去了！",
          DialogueId = 71006206,
          GUID = "B1C1AFAC",
          SpeakNpcId = 818055
        },
        [71006301] = {
          ContentTC = "救命啊，有沒有人來救救我。",
          DialogueId = 71006301,
          GUID = "B1C1BF42",
          SpeakNpcId = 818056
        },
        [71006302] = {
