        [72999999] = {
          DialogueId = 72999999,
          DialoguePanelType = "AllHide",
          Duration = 1.4,
          GUID = "B6BF7256"
        },
        [73000201] = {
          ContentTC = "我改進了這個裝置，你繼續來試試，幫我測試一下改進效果。花大價錢從艾利西安搞來的東西，我就不信了，這次你還能躲得開。",
          DialogueId = 73000201,
          GUID = "B6BF937A",
          SpeakNpcId = 818022
        },
        [73000202] = {
          ContentTC = "還想試試？行啊。哎，你們這些身手好的家伙就喜歡這麼上躥下跳的。",
          DialogueId = 73000202,
          GUID = "B6BF93A4",
          SpeakNpcId = 818022
        },
        [73000203] = {
          ContentTC = "啊？怎麼你又成功了？至少失敗一次啊……不行，我得再優化一下。",
          DialogueId = 73000203,
          GUID = "B6BF93CE",
          SpeakNpcId = 818022
        },
        [73000204] = {
          ContentTC = "嗯，對，這就是我想要的效果！雖然不知道它到底能做什麼……但一定能派上用場的。",
          DialogueId = 73000204,
          GUID = "B6BF93F8",
          SpeakNpcId = 818022
        },
        [73000301] = {
          ContentTC = "你又來了，而我也又一次改進了這個裝置，上次的難度還是太簡單了，這次一定可以絆倒你。",
          DialogueId = 73000301,
          GUID = "B6BFA3E2",
          SpeakNpcId = 818022
        },
        [73000302] = {
          ContentTC = "還想試試？行啊。哎，你們這些身手好的傢伙就喜歡這麼上躥下跳的。",
          DialogueId = 73000302,
          GUID = "B6BFA40C",
          SpeakNpcId = 818022
        },
        [73000303] = {
          ContentTC = "怎麼回事！你又通過了！不行，我已經花了好多銅幣改進它，不能就這麼放棄，你等著，你等著。",
          DialogueId = 73000303,
          GUID = "B6BFA436",
          SpeakNpcId = 818022
        },
        [73000304] = {
          ContentTC = "好好好，看到你手忙腳亂的樣子，我想到了，我可以和長官說把它裝到冰湖城門口，用來防止有人強行闖進去……",
          DialogueId = 73000304,
          GUID = "B6BFA460",
          SpeakNpcId = 818022
        },
        [73000401] = {
          ContentTC = "你終於來了，就等著你呢，這次我花費了全部家當把這個機關改造地毀天滅地，它已經完美，你是不可能通過的。",
          DialogueId = 73000401,
          GUID = "B6BFB44A",
          SpeakNpcId = 818022
        },
        [73000402] = {
          ContentTC = "還想試試？行啊。哎，你們這些身手好的家伙就喜歡這麼上躥下跳的。",
          DialogueId = 73000402,
          GUID = "B6BFB474",
          SpeakNpcId = 818022
        },
        [73000403] = {
          ContentTC = "又……又失敗了。算了……我就不應該對傳頌會的東西有任何期待，這一定是我對皇帝陛下不忠的下場。",
          DialogueId = 73000403,
          GUID = "B6BFB49E",
          SpeakNpcId = 818022
        },
        [73000404] = {
          ContentTC = "這堆東西我就放這兒了，你愛怎麼玩兒怎麼玩兒吧……我看你好像還挺樂在其中的。",
          DialogueId = 73000404,
          GUID = "B6BFB4C8",
          SpeakNpcId = 818022
        },
        [73000405] = {
          ContentTC = "怎麼樣，嚐到厲害了吧。而我也想到了，我可以把它獻給皇帝陛下，和他說用它來訓練和篩選士兵，一定能夠獲得許多賞錢。這樣我就能還上為了改進它欠下的錢了。",
          DialogueId = 73000405,
          GUID = "B6BFB4F2",
          SpeakNpcId = 818022
        },
        [73000502] = {
          ContentTC = "（這台裝置沉默不語，上面有一個簡陋的旋鈕，以及簡單，不簡單和燃盡了三個檔位，顯然是出自那位喋喋不休的士兵的手筆。）",
          DialogueId = 73000502,
          GUID = "B6BFC4DC",
          SpeakNpcId = 818022
        },
        [73000601] = {
          ContentTC = "（是運輸用升降機，興許可以得到補給。不過，也要小心留意是否有埋伏的敵人。）",
          DialogueId = 73000601,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFD51A",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [73000701] = {
          ContentTC = "這個房間暫時安全，可以操作控制台了。",
          DialogueId = 73000701,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFE582",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [73000801] = {
          ContentTC = "取得控制權限中，請稍等。",
          DialogueId = 73000801,
          GUID = "B6BFF5EA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [73000901] = {
          ContentTC = "（中央控制室是獨立供能……這裡的髓動輪並未收到動力室爆炸的影響。）",
          DialogueId = 73000901,
          ExStoryInfo = "EXPlayer",
          GUID = "B6C00652",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [73001001] = {
          ContentTC = "線路錯誤，控制台處於保護狀態。請關閉髓動輪以解除保護狀態。",
          DialogueId = 73001001,
          GUID = "B6C016BA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [80001001] = {
          ContentTC = "哇，我來到大魔法師的家門口了！咚咚咚——大魔法師，你在家嗎？",
          DialogueId = 80001001,
          GUID = "C8462C3A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C3A"
        },
        [80001002] = {
          ContentTC = "唔……沒有回應，看來大魔法師出門了。去外面找找看吧！",
          DialogueId = 80001002,
          GUID = "C8462C64",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C64"
        },
        [80001003] = {
          ContentTC = "哎呀，前面的故事還沒有顏色……不過沒關係，菲娜有魔法的畫筆，可以一邊前進，一邊給故事填上色彩。",
          DialogueId = 80001003,
          GUID = "C8462C8E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C8E"
        },
        [80001004] = {
          ContentTC = "沿著這條路出發，尋找大魔法師的蹤跡吧。",
          DialogueId = 80001004,
          GUID = "C8462CB8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CB8"
        },
        [80001005] = {
          ContentTC = "咦，花園裡怎麼一朵花也沒有……",
          DialogueId = 80001005,
          GUID = "C8462CE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80001006,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CE2"
        },
        [80001006] = {
          ContentTC = "讓菲娜來給這裡添上漂亮的花朵吧！",
          DialogueId = 80001006,
          GUID = "C8462D0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D0C"
        },
        [80001007] = {
          ContentTC = "這樣一來，花園就變得漂亮多啦。繼續前進吧！",
          DialogueId = 80001007,
          GUID = "C8462D36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D36"
        },
        [80001008] = {
          ContentTC = "這是……小夜鶯留下的羽毛！",
          DialogueId = 80001008,
          GUID = "C8462D60",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001009,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D60"
        },
        [80001009] = {
          ContentTC = "把它收集起來吧，一定會帶來好運的。",
          DialogueId = 80001009,
          GUID = "C8462D8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D8A"
        },
        [80001010] = {
          ContentTC = "前面的路被擋住了……該怎麼做才能請藤蔓讓路呢？",
          DialogueId = 80001010,
          GUID = "C8462DB4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DB4"
        },
        [80001011] = {
          ContentTC = "太好啦，可以前進了！",
          DialogueId = 80001011,
          GUID = "C8462DDE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DDE"
        },
        [80001012] = {
          ContentTC = "大魔法師會在那裡嗎？",
          DialogueId = 80001012,
          GUID = "C8462E08",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E08"
        },
        [80001013] = {
          ContentTC = "咦，篝火還在燃燒，看來大魔法師才剛離開不久。",
          DialogueId = 80001013,
          GUID = "C8462E32",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E32"
        },
        [80001014] = {
          ContentTC = "哇，螢火蟲飛散開來，好像星星長出了翅膀！",
          DialogueId = 80001014,
          GUID = "C8462E5C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E5C"
        },
        [80001015] = {
          ContentTC = "這裡也開出漂亮的花了。",
          DialogueId = 80001015,
          GUID = "C8462E86",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001016,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E86"
        },
        [80001016] = {
          ContentTC = "看，還有圓圓的蘑菇！如果踩在上面，一定能跳得很高吧？",
          DialogueId = 80001016,
          GUID = "C8462EB0",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EB0"
        },
        [80001017] = {
          ContentTC = "這裡竟然會有寶物，難道是大魔法師的珍藏？",
          DialogueId = 80001017,
          GUID = "C8462EDA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EDA"
        },
        [80001018] = {
          ContentTC = "前面沒有路了，該怎麼過去呢？",
          DialogueId = 80001018,
          GUID = "C8462F04",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F04"
        },
        [80001019] = {
          ContentTC = "哇……！可愛的蘑菇們，你們是來幫我的嗎？",
          DialogueId = 80001019,
          GUID = "C8462F2E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80001020,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F2E"
        },
        [80001020] = {
          ContentTC = "謝謝你們，這樣我就可以跳到對岸去啦。",
          DialogueId = 80001020,
