        },
        [80030127] = {
          ContentTC = "哎，難得我一片好心了，真是令人悲痛欲絕，甚至明天無法正常休息……",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202
        },
        [80030128] = {
          ContentTC = "對哦，我應該試試能不能休假中插入病假：因為生病，沒有得到休息，所以延長休假，想想也是很正常的邏輯！",
          DialogueId = 80030128,
