          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202
        },
        [80030130] = {
          ContentTC = "原因就寫成在做民意調查時發生了衝突，經私下調節已解決。也許還能領到工傷撫恤……嗯，今天算來對了。",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202
        },
        [80030131] = {
          ContentTC = "你一杯茶的功夫，就多了這麼多假期，你可真是我的好朋友！",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
