          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "來了來了，我不會失約的。",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202
        },
        [80030402] = {
          ContentTC = "喏，這是改進好的「軍用合金控溫容器」，我提前試過，不會有問題的……哈欠……",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          }
        },
        [80030403] = {
          ContentTC = "不過我現在困得不行，得要先找一個地方睡上一覺。假期額度快用完了，明天可不能黑著眼圈去給西比爾長官彙報工作。",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          }
        },
        [80030404] = {
          ContentTC = "你感覺還挺敏銳的嘛，確實有一些煩惱。",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202
        },
        [80030405] = {
          ContentTC = "既然被你察覺了，那我也不瞞著了，其實是做了噩夢。",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030406] = {
          ContentTC = "怎麼會，像我這麼怕麻煩的人，是會回絕掉大部分邀請的。",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030407] = {
          ContentTC = "實話說，是因為昨天做了噩夢，心情有些糟糕。",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202
        },
        [80030408] = {
          ContentTC = "唉，和之前許多次噩夢一樣，是關於我那個麻煩老爹的……",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202
        },
        [80030409] = {
          ContentTC = "嗯，他曾經也是帝國的軍人。不過現在嘛……已經在床上躺了有些年頭了。",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030410] = {
          ContentTC = "在我被姐姐們欺騙著，想要成為紳士的年紀，老爹就已經是軍團裡的士官了。那時他在前線的時間多，在家的時間少，和我現在差不多吧。",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030411] = {
          ContentTC = "不過和我現在不一樣的是，他非常看重自己身上的軍裝。似乎對於他來說，軍隊才是自己的家，而我和姐姐們在的地方，不過是可以任意挑剔的旅店罷了。",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202
        },
        [80030412] = {
          ContentTC = "每次他回到家，總是要發上一些牢騷，有時候是皇帝的畫像沒有掛正，有時候是姐姐們回家太晚。",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202
        },
        [80030413] = {
          ContentTC = "但是每一次都會有一個保留節目，就是發起一場對我的檢閱。",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202
        },
        [80030414] = {
          ContentTC = "又長高了幾釐米，又看了幾本書，又記住了幾座要塞的名字，又學會了幾種求生技能，他會一一問一遍。",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202
        },
        [80030415] = {
          ContentTC = "我也試過和他討論其他話題，但是他對於「成為軍人」以外的所有事情都毫無興趣。",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202
        },
        [80030416] = {
          ContentTC = "有一次，我為了迎合他，像現在製造小工具那樣，小心用木頭刻了一把手槍，滿心歡喜等著他的誇獎。",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          }
        },
        [80030417] = {
          ContentTC = "但他只是把手槍「梆」地一下砸在桌子上，板起臉來：「少做這些浪費時間的閒事，多把心思放在如何成為一個優秀的軍人上。」",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202
        },
        [80030418] = {
          ContentTC = "那時候我的心裡突然多了一種東西，像是屋子外面的風一樣，冷，刀割一樣，又摸不到，還無法停止。",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202
        },
        [80030419] = {
          ContentTC = "後來我才逐漸意識到，那也許是恨意，雖然沒有十分強烈，但是已經足夠讓我覺得面前的這個人討厭，陌生。",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202
        },
        [80030420] = {
          ContentTC = "在那過後，我就不再試圖迎合他了，也不管他的檢閱，也不管他罵我是「廢物」或者什麼更難聽的話。",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202
        },
        [80030421] = {
          ContentTC = "直到有一天，他突然被送了回來——在戰鬥中為了保護下屬，被彈片擊中了腦袋，雖然活著，但是沒了意識。",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202
        },
        [80030422] = {
          ContentTC = "他沒什麼額外的積蓄，所有的薪水都寄回了家裡，和他一起被送回來的，除了鋥亮的勳章以外，就只有一把斷成兩截的木槍。",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202
        },
        [80030423] = {
          ContentTC = "我原來以為這是因為他對我失望透頂，但是他的那些下屬告訴我，這把木槍他隨身帶著，是他在戰場上倒下時折斷的。",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202
        },
        [80030424] = {
          ContentTC = "他似乎在心底裡認可我。但是我無法接受這樣的認可。",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          }
        },
        [80030425] = {
          ContentTC = "如果真的為我感到驕傲，我更希望他能夠親口說出來，哪怕最簡單的一句鼓勵也好，而不是一直在逼迫著我幹著不想幹的事情。",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202
        },
        [80030426] = {
          ContentTC = "雖然老爹已經不會再爬起來敲我的腦殼，我還是按照他一直以來的要求，加入了軍團。",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202
        },
        [80030427] = {
          ContentTC = "我好奇那到底是一個怎樣的地方，能讓老爹變成一個沉默寡言的傢伙，也想證明，哪怕沒有按照他的呵斥，我也能混出一個不錯的日子。",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202
        },
        [80030428] = {
          ContentTC = "不過對他和對我來說都很不幸的是，當我加入軍團後，才發現他說得其實沒錯。",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202
        },
        [80030429] = {
          ContentTC = "我們和軍團的大多數人不一樣。我們從戰場的屍骸堆中爬出來，跪著接過他們施捨的勳章。",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202
        },
        [80030430] = {
          ContentTC = "體面的工作，優渥的生活，甚至生存本身——我們的一切都維繫在那些小小的勳章上。父親為了我們的家，奉上了自己的一切。",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202
        },
        [80030431] = {
          ContentTC = "他去服從，去忍耐，去壓抑感情，讓自己習慣哀嚎和哭泣，讓自己成為這匹巨獸口中的一枚獠牙。",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202
        },
        [80030432] = {
          ContentTC = "我做不到這些，但又要一筆錢養活自己，維持家庭現有的體面，所以就只能這樣懸在半空，做一個廢物。",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202
        },
        [80030433] = {
          ContentTC = "……",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202
        },
        [80030434] = {
          ContentTC = "你確實很敏銳。說實話，我到底在幹什麼，也是在消沉了很久之後才想明白。",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030435] = {
          ContentTC = "雖然我的選擇和老爹的期望有一些差距，但是我並不覺得這是一件壞事。",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202
        },
        [80030436] = {
          ContentTC = "希望如此吧，這樣一來，這場噩夢應該就能結束了。",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030437] = {
          ContentTC = "真是好飲料啊，喝完了後，一定不會再做噩夢的。",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202
        },
        [80030438] = {
          ContentTC = "謝了，我的請假之交，只不過現在為了明天不請假，必須得回去補上一覺了。",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030439] = {
          ContentTC = "別擔心，下次見面的時候，我還是你熟悉的那個蘭迪。萬一我又做噩夢了，就勞煩你再給我調製一杯飲料吧。",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "一杯熱飲，多加點糖。另外，我還從帝都帶了一些甜點來，我趁著休假排隊買的，你可以嚐嚐。",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202
        },
        [80030502] = {
          ContentTC = "是啊，所以想喝點甜的，作為接下來邀請的鋪墊。",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030503] = {
          ContentTC = "絕無此事！雖然我確實想要向你發出一則邀請，但是這並不能被稱作企圖！",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030504] = {
          ContentTC = "咳咳……嗯，雖然有點突然，但是要不要和我跳一支舞？",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202
        },
        [80030505] = {
          ContentTC = "就是，軍團總要和一些地方勢力打好關係，比如之前和你說過的，去內城參加一些必要但是很煩人的社交儀式。",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          }
        },
        [80030506] = {
          ContentTC = "我好不想去啊，就算是給我算因公出差，應付那些老爺夫人也是怪麻煩的。",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202
        },
        [80030507] = {
          ContentTC = "所以呢，我想了一個一勞永逸的方法，那就是帶著一位足夠美麗的女士一同入場，和我共舞一曲。",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202
        },
        [80030508] = {
          ContentTC = "這樣一來，就不會有人湊上來，向我介紹那些他們自己可能也沒見過幾面的遠方女性親眷了吧。",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202
        },
        [80030509] = {
          ContentTC = "就……我覺得……你也許可以嘗試一下男扮……",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          }
        },
        [80030510] = {
          ContentTC = "哎呀，這不是因為邀請的是我嘛。",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030511] = {
          ContentTC = "哎呀，我也是實在沒有辦法，才想出了這個主意。",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030512] = {
          ContentTC = "我們都喝了這麼多頓酒了，你在我心裡早就是比姐姐們還要親近的兄弟了，否則我也不會想到你。",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202
        },
        [80030513] = {
          ContentTC = "所以在這種關頭，幫我一把，我接下來半年月俸都分你一半！",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202
        },
        [80030514] = {
          ContentTC = "你要是實在不樂意，等舞會回來，換我穿舞裙給你看好不好。",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202
        },
        [80030515] = {
          ContentTC = "別……別誤會，不不不不是這樣的，我沒有那樣的興趣，你怎麼會往那個方向去想？",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          }
        },
        [80030516] = {
          ContentTC = "好兄弟一起吃飯，一起玩耍，一起上廁所，一起穿裙子之類的，很正常吧。",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202
        },
        [80030517] = {
          ContentTC = "唉，你別笑啊，我可是很認真地在發愁呢，給個答覆吧。要是不答應的話，我得想想其他辦法了……",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030518] = {
          ContentTC = "你可以再考慮考慮，實在不行……",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202
        },
        [80030519] = {
          ContentTC = "等等？你答應了？太好了！你簡直就是我異父異母的親兄弟！",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202
        },
        [80030520] = {
          ContentTC = "這次是我欠了你一個天大的人情，我得要想請假理由那樣，想各種方法還掉才是。",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202
        },
        [80030521] = {
          ContentTC = "不過，那也得等舞會結束再說了。現在呀，我得趁著你還沒反悔，先回去準備衣服啦。",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202
        },
        [80030522] = {
          ContentTC = "回頭見，我的請假之交，休息之友。",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202
        },
        [80030523] = {
          ContentTC = "嗚，你要不要再考慮考慮，舞會結束後，我會像編造請假理由那樣，想出各種方法來報答你的！",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202
        },
        [80030524] = {
          ContentTC = "不過，我覺得現在得安靜下來，留出一些空間讓你思考才是。不過，我還是希望你能答應，也相信你一定會答應的！",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202
        },
        [80030525] = {
          ContentTC = "那麼，我先回去了，等你的好消息，我的請假之交，休息之友。",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202
        },
        [80030526] = {
          ContentTC = "沒錯，你顯然也意識到了，沒有比你更適合的舞伴了……所以，你能不能幫幫我，解開這個困境。",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202
        },
        [80030527] = {
          ContentTC = "嗯……？",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202
        },
        [80030528] = {
          ContentTC = "啊？！怎麼可能，你怎麼能這麼想？我真想要幫你綁了立功的話，第一次坐在這裡的時候就可以動手了！",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          }
        },
        [80030529] = {
          ContentTC = "根本不用專門請假到這裡這麼多次後，再編造出一個舞會來誘捕你。",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202
        },
        [80030530] = {
          ContentTC = "更何況，即便想要引誘你也不會選擇用邀請你跳舞這種方式吧，萬一被拒絕了怎麼辦？",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202
        },
        [80030531] = {
          ContentTC = "啊啊，你是在開玩笑吧，不然我只能理解為，在你眼裡，我是一個又壞又蠢的煩人傢伙。",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202
        },
        [80030532] = {
          ContentTC = "還好還好，如果真的被誤會成打算背叛重要的朋友，換取前途的無恥之徒的話，我會因為太過心痛而請一個月的病假的。",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030533] = {
          ContentTC = "喂喂喂，至少否定一下後半句吧！要是我當真了怎麼辦！",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          }
        },
        [80030534] = {
          ContentTC = "不過我現在有一點可以肯定，那麼就是，你其實從一開始，就根本沒有擔心有什麼危險。",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          }
        },
        [80030535] = {
          ContentTC = "而是單純地惡作劇，設想了一個最壞的可能，想看我的反應。",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202
        },
        [80030536] = {
          ContentTC = "我原來以為只有我會有這種捉弄人不正經的習慣，怎麼你也這麼惡趣味。也不知道和誰學來的。",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202
        },
        [80030537] = {
          ContentTC = "我確實有那麼一瞬間慌了幾秒，雖然理智上知道不可能，但是感性上還是在擔心，萬一你是真的這麼覺得呢？",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202
        },
        [80030538] = {
          ContentTC = "所以，作為惡作劇的補償，你必須答應我的邀請。",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030539] = {
          ContentTC = "哈？",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202
        },
        [80030540] = {
          ContentTC = "好吧，你說得沒錯！我一直想要逮捕你，白天，夜裡，只要是大腦沒有在休假，就在謀劃逮捕你的計畫。只是因為我一直都是偷懶耍滑，遲遲都沒有實踐。",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          }
        },
        [80030541] = {
          ContentTC = "難得這次想認真幹活，卻被識破了，怎麼辦呀——",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202
        },
        [80030542] = {
          ContentTC = "看來我遲早會被軍團掃地出門，流落在冰湖城的嚴寒街道上，又冷，又餓，無家可歸……",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202
        },
        [80030543] = {
          ContentTC = "你真的能夠眼睜睜看著我成為街頭的雪雕嗎？",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          }
        },
        [80030544] = {
          ContentTC = "你可以再考慮考慮，實在不行……",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202
        },
        [80030545] = {
          ContentTC = "等等？你答應了？太好了！你簡直……簡直……簡直是我異父異母的親姐妹！",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202
        },
        [80030546] = {
          ContentTC = "這次是我欠了你一個天大的人情，我得要想請假理由那樣，想各種方法還掉才是。",
          DialogueId = 80030546,
          GUID = "C8591B9E",
          NextDialogue = 80030547,
          SpeakNpcId = 94202
        },
        [80030547] = {
