        [80050121] = {
          ContentTC = "嗯……讓我想想……",
          DialogueId = 80050121,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A6FA",
          NextDialogue = 80050122,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A6FA"
        },
        [80050122] = {
          ContentTC = "獨角獸{性别:先生|小姐}，你可以幫菲娜實現四個願望嗎？傳說中長有一只角的獨角獸可以實現人的任何心願，所以你也一定可以的！",
          DialogueId = 80050122,
          GUID = "C865A724",
          NextOptions = {
            [1] = 80050123,
            [2] = 80050124,
            [3] = 80050125
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A724"
        },
        [80050123] = {
          ContentTC = "當然，只要我能辦到。",
          DialogueId = 80050123,
          GUID = "C865A74E",
          NextDialogue = 80050126
        },
        [80050124] = {
          ContentTC = "總感覺自己被訛了……",
          DialogueId = 80050124,
          GUID = "C865A778",
          NextDialogue = 80050126
        },
        [80050125] = {
          ContentTC = "人家不都是三個願望嗎！你怎麽還多了一個啊！",
          DialogueId = 80050125,
          GUID = "C865A7A2",
          NextDialogue = 80050126
        },
        [80050126] = {
          ContentTC = "嘿嘿……",
          DialogueId = 80050126,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865A7CC",
          NextOptions = {
            [1] = 80050127
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A7CC"
        },
        [80050127] = {
          ContentTC = "好吧，那第一個願望是什麽？",
          DialogueId = 80050127,
          GUID = "C865A7F6",
          NextDialogue = 80050128
        },
        [80050128] = {
          ContentTC = "菲娜想練習魔法！我雖然會一丁點魔法，但是總也不知道到底怎麽用……獨角獸{性别:先生|小姐}，你能不能教教我？",
          DialogueId = 80050128,
          FacialId = {
            [1] = "790017:Smile02"
          },
          GUID = "C865A820",
          NextOptions = {
            [1] = 80050129,
            [2] = 80050132
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A820"
        },
        [80050129] = {
          ContentTC = "為什麽不讓奧特賽德教你？",
          DialogueId = 80050129,
          GUID = "C865A84A",
          NextDialogue = 80050130
        },
        [80050130] = {
          ContentTC = "他不肯教我，也不給我看那些魔法學書本，他把那些書都放在了很高很高的櫃子上，我使勁踮起腳尖也夠不到。",
          DialogueId = 80050130,
          GUID = "C865A874",
          NextDialogue = 80050131,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A874"
        },
        [80050131] = {
          ContentTC = "我就只能趁他不在的時候，把凳子堆起來，偷偷去拿——對了對了，這個你千萬別和其他人說！",
          DialogueId = 80050131,
          GUID = "C865A89E",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A89E"
        },
        [80050132] = {
          ContentTC = "我要收費的。",
          DialogueId = 80050132,
          GUID = "C865A8C8",
          NextDialogue = 80050133
        },
        [80050133] = {
          ContentTC = "咦……？我、我想想……一大罐棉花糖夠嗎？",
          DialogueId = 80050133,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865A8F2",
          NextDialogue = 80050134,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A8F2"
        },
        [80050134] = {
          ContentTC = "但既然是幫菲娜實現願望，就免費吧。",
          DialogueId = 80050134,
          GUID = "C865A91C",
          NextDialogue = 80050135,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A91C"
        },
        [80050135] = {
          ContentTC = "好耶！",
          DialogueId = 80050135,
          FacialId = {
            [1] = "790017:Happy01"
          },
          GUID = "C865A946",
          NextDialogue = 80050136,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A946"
        },
        [80050136] = {
          ContentTC = "謝謝你願意教我。奧特賽德就不肯教我，也不給我看那些魔法學書本，他把那些書都放在了很高很高的櫃子上，我使勁踮起腳尖也夠不到。",
          DialogueId = 80050136,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865A970",
          NextDialogue = 80050137,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A970"
        },
        [80050137] = {
          ContentTC = "我就只能趁他不在的時候，把凳子堆起來，偷偷去拿——對了對了，這個你千萬別和其他人說！",
          DialogueId = 80050137,
          GUID = "C865A99A",
          NextDialogue = 80050138,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A99A"
        },
        [80050138] = {
          ContentTC = "他總說，學魔法的人得走出安穩的房間，離開暖和的火爐，去一片荒原——荒蕪的、嚴酷的荒原……",
          DialogueId = 80050138,
          GUID = "C865A9C4",
          NextDialogue = 80050139,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9C4"
        },
        [80050139] = {
          ContentTC = "那裡有很多很多雪狼，眼睛放著可怕的綠光，還有騎著掃把、渾身上下塗滿毒藥的沼澤女巫。",
          DialogueId = 80050139,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865A9EE",
          NextOptions = {
            [1] = 80050140,
            [2] = 80050143
          },
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865A9EE"
        },
        [80050140] = {
          ContentTC = "沒那麽誇張，他是嚇唬你的。",
          DialogueId = 80050140,
          GUID = "C865AA18",
          NextDialogue = 80050141
        },
        [80050141] = {
          ContentTC = "啊……我就知道！他只是害怕我會生病、會受傷。但是，如果我的身體一直不能好起來……我也不想就這樣一直一直躺在家裡，當小拖油瓶。",
          DialogueId = 80050141,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865AA42",
          NextDialogue = 80050142,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA42"
        },
        [80050142] = {
          ContentTC = "……我想變成一個有用的孩子，我不想再被討厭了。",
          DialogueId = 80050142,
          GUID = "C865AA6C",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AA6C"
        },
        [80050143] = {
          ContentTC = "有比雪狼和沼澤女巫更可怕的東西。",
          DialogueId = 80050143,
          GUID = "C865AA96",
          NextDialogue = 80050144
        },
        [80050144] = {
          ContentTC = "可是這樣的話……我就更不能讓你們自己去那裡了。我得好好學魔法，幫上你們的忙才行。",
          DialogueId = 80050144,
          GUID = "C865AAC0",
          NextDialogue = 80050145,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAC0"
        },
        [80050145] = {
          ContentTC = "所以——拜托了，教教我吧！我一定會好好保密的。",
          DialogueId = 80050145,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865AAEA",
          NextOptions = {
            [1] = 80050146
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AAEA"
        },
        [80050146] = {
          ContentTC = "好吧，那我們現在就開始練習吧。",
          DialogueId = 80050146,
          GUID = "C865AB14",
          NextDialogue = 80050147
        },
        [80050147] = {
          ContentTC = "太好了——你是全天下最好最好的獨角獸{性别:先生|小姐}！",
          DialogueId = 80050147,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865AB3E",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/001/C865AB3E"
        },
        [80050201] = {
          Camera = "364.267578,-629.911316,141.387695,0.0,0.0,123.199776,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "菲娜的第二個願望是，想要獨角獸{性别:先生|小姐}偷偷帶我去城外，看看真正的星星。",
          DialogueId = 80050201,
          Duration = 5,
          GUID = "C865B41A",
          IsBlack = 1,
          NextDialogue = 80050202,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790017},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B41A"
        },
        [80050202] = {
