          NextDialogue = 80050203,
          SpeakNpcId = 790017,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B444"
        },
        [80050203] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "城裡的晚上，就算不下雪，天空也總是被房子和城墻關起來，只有很小很小的一塊，怎麽也不夠看的。",
          DialogueId = 80050203,
          GUID = "C865B46E",
          NextDialogue = 80050204,
          SpeakNpcId = 790017,
          TurnTo = {
            [1] = "790017:n(100001)",
            [2] = "100001:n(790017)"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B46E"
        },
        [80050204] = {
          ContentTC = "奧特賽德送給我的星空燈很美……但果然，還是真正的星空更——阿嚏！",
          DialogueId = 80050204,
          GUID = "C865B498",
          NextOptions = {
            [1] = 80050205,
            [2] = 80050206
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B498"
        },
        [80050205] = {
          ContentTC = "小心著涼。",
          DialogueId = 80050205,
          GUID = "C865B4C2",
          NextDialogue = 80050207
        },
        [80050206] = {
          ContentTC = "你站我後面吧，我幫你擋著風。",
          DialogueId = 80050206,
          GUID = "C865B4EC",
          NextDialogue = 80050207
        },
        [80050207] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "沒事沒事，菲娜一點也不冷。不信你摸摸我的手心，很暖和的！我想再多待一會兒……",
          DialogueId = 80050207,
          GUID = "C865B516",
          NextDialogue = 80050208,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}},PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"Talk02_Start\"},Duration{1}}}",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B516"
        },
        [80050208] = {
          Camera = "-370.169922,731.447144,106.094727,0.000026,35.394604,129.986496,18.0,100000.0,false,DoNotOverride,22.0",
          ContentTC = "快看快看，那幾顆星星連起來，像不像一只小兔子？",
          DialogueId = 80050208,
          GUID = "C865B540",
          NextOptions = {
            [1] = 80050209,
            [2] = 80050211,
            [3] = 80050214
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B540"
        },
        [80050209] = {
          ContentTC = "像。",
          DialogueId = 80050209,
          GUID = "C865B56A",
          NextDialogue = 80050210
        },
        [80050210] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "嘿嘿~那麽，我今晚就來給它編故事，小兔子在星星上的故事。",
          DialogueId = 80050210,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865B594",
          NextOptions = {
            [1] = 80050217
          },
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Confident_Start\"},Duration{2}},PlayAnimation{_delay{3},ActorId{790017},AnimationId{\"Confident_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B594"
        },
        [80050211] = {
          ContentTC = "像大雞腿。",
          DialogueId = 80050211,
          GUID = "C865B5BE",
          NextDialogue = 80050212
        },
        [80050212] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "咦？……我好像看不出來。你是不是肚子餓了？",
          DialogueId = 80050212,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B5E8",
          NextDialogue = 80050213,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B5E8"
        },
        [80050213] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "開個玩笑。說來……",
          DialogueId = 80050213,
          GUID = "C865B612",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B612"
        },
        [80050214] = {
          ContentTC = "像一只頭頂褲衩的海豚。",
          DialogueId = 80050214,
          GUID = "C865B63C",
          NextDialogue = 80050215
        },
        [80050215] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "咦？那、那是什麽？！我好像想象不出來……",
          DialogueId = 80050215,
          FacialId = {
            [1] = "790017:Shock01"
          },
          GUID = "C865B666",
          NextDialogue = 80050216,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B666"
        },
        [80050216] = {
          Camera = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "開個玩笑。說來……",
          DialogueId = 80050216,
          GUID = "C865B690",
          NextOptions = {
            [1] = 80050217
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B690"
        },
        [80050217] = {
          ContentTC = "菲娜為什麽這麽喜歡星空？",
          DialogueId = 80050217,
          GUID = "C865B6BA",
          NextDialogue = 80050218
        },
        [80050218] = {
          Camera = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "很久很久以前啊，媽媽給我講過一個故事。一只小鳥兒變成了星星的故事……這是我最喜歡的故事，我也來講給你聽吧。",
          DialogueId = 80050218,
          GUID = "C865B6E4",
          NextDialogue = 80050219,
          Scripts = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B6E4"
        },
        [80050219] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這只鳥兒和其他鳥兒不一樣，它羽毛生得醜陋，歌聲也難聽；沒有尖尖的爪子，也沒有鋒利的喙。其他鳥兒們都討厭它，每天都在欺負它，想要趕它走。",
          DialogueId = 80050219,
          GUID = "C865B70E",
          NextDialogue = 80050220,
          Scripts = "PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B70E"
        },
        [80050220] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "但是，這只小小的鳥兒卻向往著星空。它向滿天繁星祈求，求星星把自己帶到它們那兒，哪怕是被熾熱的光芒灼燒而死，也心甘情願。",
          DialogueId = 80050220,
          GUID = "C865B738",
          NextOptions = {
            [1] = 80050221
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/002/C865B738"
        },
        [80050221] = {
          ContentTC = "星星回應了它的願望？",
          DialogueId = 80050221,
          GUID = "C865B762",
          NextDialogue = 80050222
        },
        [80050222] = {
          Camera = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "沒有哦……星星們要麽不理睬它，要麽嘲笑它的不自量力：一只醜陋的鳥兒，竟然也妄想和星星一起飛翔在漂亮的夜空之上。",
          DialogueId = 80050222,
          GUID = "C865B78C",
          NextOptions = {
            [1] = 80050223
          },
