          TalkActionId = {
            [1] = "790017:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DB7A"
        },
        [80050442] = {
          ContentTC = "…………",
          DialogueId = 80050442,
          GUID = "C865DBA4",
          NextDialogue = 80050443,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBA4"
        },
        [80050443] = {
          ContentTC = "我們明明寫了一個很完美的故事……所有人都那麽快樂，那麽幸福……到底還缺什麽呢？",
          DialogueId = 80050443,
          GUID = "C865DBCE",
          NextDialogue = 80050444,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBCE"
        },
        [80050444] = {
          ContentTC = "…………",
          DialogueId = 80050444,
          GUID = "C865DBF8",
          NextDialogue = 80050445,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBF8"
        },
        [80050445] = {
          ContentTC = "……我大概知道了。",
          DialogueId = 80050445,
          GUID = "C865DC22",
          NextOptions = {
            [1] = 80050446,
            [2] = 80050447
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DC22"
        },
        [80050446] = {
          ContentTC = "因為這個故事過於「完美」了。",
          DialogueId = 80050446,
          GUID = "C865DC4C",
          NextDialogue = 80050448
        },
        [80050447] = {
          ContentTC = "缺了的東西是「遺憾」。",
          DialogueId = 80050447,
          GUID = "C865DC76",
          NextDialogue = 80050448
        },
        [80050448] = {
          ContentTC = "這個故事太順利、太完美了不是嗎？沒有經歷過一絲風浪，也沒有一點遺憾，反而看上去有點不太真實。",
          DialogueId = 80050448,
          GUID = "C865DCA0",
          NextDialogue = 80050449,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCA0"
        },
        [80050449] = {
          ContentTC = "…………",
          DialogueId = 80050449,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DCCA",
          NextDialogue = 80050450,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCCA"
        },
        [80050450] = {
          ContentTC = "好像……是這樣？媽媽給菲娜講的故事裡，並不只是快樂的東西。也會有……不好的變故發生。",
          DialogueId = 80050450,
          GUID = "C865DCF4",
          NextDialogue = 80050451,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCF4"
        },
        [80050451] = {
          ContentTC = "美麗的公主陷入沈睡，勇敢的王子變成野獸，可愛的孩子被巫師抓走，笨拙的鳥兒在夜空中凍僵……",
          DialogueId = 80050451,
          FacialId = {
            [1] = "790017:Sad01"
          },
          GUID = "C865DD1E",
          NextDialogue = 80050452,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD1E"
        },
        [80050452] = {
          ContentTC = "雖然結局常常是好的……但為什麽一定要讓他們經歷悲傷呢？為什麽不能讓大家永遠永遠幸福快樂呢？",
          DialogueId = 80050452,
          GUID = "C865DD48",
          NextOptions = {
            [1] = 80050453
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD48"
        },
        [80050453] = {
          ContentTC = "因為生活本就如此。",
          DialogueId = 80050453,
          GUID = "C865DD72",
          NextDialogue = 80050454
        },
        [80050454] = {
          ContentTC = "就像菲娜喜歡的棉花糖一樣。那麽大一罐，每一顆糖的味道都不一樣。有甜甜的，有酸酸的，還有的有些苦。",
          DialogueId = 80050454,
          GUID = "C865DD9C",
          NextDialogue = 80050455,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD9C"
        },
        [80050455] = {
          ContentTC = "嗯！菲娜最喜歡吃甜甜的，最討厭苦的……不對，最討厭芥末味的。為什麽做棉花糖的廚師要往棉花糖裡放芥末呀！",
          DialogueId = 80050455,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DDC6",
          NextDialogue = 80050456,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDC6"
        },
        [80050456] = {
          ContentTC = "我每次不小心吃到芥末味，被辣出眼淚的時候，都要挑一塊甜甜的。這個時候，甜味的棉花糖會更加甜——",
          DialogueId = 80050456,
          FacialId = {
            [1] = "790017:Syouganai01"
          },
          GUID = "C865DDF0",
          NextDialogue = 80050457,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDF0"
        },
        [80050457] = {
          ContentTC = "啊……我懂了……正是因為有苦苦的，還有芥末味的，甜味的糖才變得格外好吃。",
          DialogueId = 80050457,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DE1A",
          NextDialogue = 80050458,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE1A"
        },
        [80050458] = {
          ContentTC = "…………",
          DialogueId = 80050458,
          GUID = "C865DE44",
          NextDialogue = 80050459,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE44"
        },
        [80050459] = {
          ContentTC = "故事也是這樣……嗎？如果沒有悲傷和遺憾，那快樂也就變得不那麽寶貴了……",
          DialogueId = 80050459,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865DE6E",
          NextDialogue = 80050460,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE6E"
        },
        [80050460] = {
          ContentTC = "原來……是這樣啊……菲娜全都明白了。",
          DialogueId = 80050460,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DE98",
          NextDialogue = 80050461,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE98"
        },
        [80050461] = {
          ContentTC = "我們剛剛寫的故事，是我們最美好的願望……但真正的故事，是笑容和淚水交織的……我們的生活本身。",
          DialogueId = 80050461,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865DEC2",
          NextDialogue = 80050462,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEC2"
        },
        [80050462] = {
          ContentTC = "謝謝你，獨角獸{性别:先生|小姐}。我想，我需要更久的時間——",
          DialogueId = 80050462,
          GUID = "C865DEEC",
          NextDialogue = 80050463,
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEEC"
        },
        [80050463] = {
          ContentTC = "等我再多長大一些、懂得更多、走過更多的路之後，我才能把這本空白的故事寫完。",
          DialogueId = 80050463,
          GUID = "C865DF16",
          NextDialogue = 80050464,
          SpeakNpcId = 790017,
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF16"
        },
        [80050464] = {
          ContentTC = "所以，獨角獸{性别:先生|小姐}，你還欠著菲娜這個願望哦！",
          DialogueId = 80050464,
          FacialId = {
            [1] = "790017:Confident01"
          },
          GUID = "C865DF40",
          NextOptions = {
            [1] = 80050465,
            [2] = 80050466
          },
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF40"
        },
        [80050465] = {
          ContentTC = "好好好，答應你。",
          DialogueId = 80050465,
          GUID = "C865DF6A",
          NextDialogue = 80050467
        },
        [80050466] = {
          ContentTC = "感覺被套牢了……",
          DialogueId = 80050466,
          GUID = "C865DF94",
          NextDialogue = 80050467
        },
        [80050467] = {
          ContentTC = "嘿嘿……那就讓我們在以後的日子，一起把這個故事寫完吧。",
          DialogueId = 80050467,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865DFBE",
          SpeakNpcId = 790017,
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DFBE"
        },
        [80060100] = {
          ContentTC = "天大地大，吃飯最大！讓我看看你有沒有吃得飽飽的呢？",
          DialogueId = 80060100,
          GUID = "C86C0C28",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C28"
        },
        [80060101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "嗯——好香的麵包飲料，這是你做的嗎？真厲害！",
          DialogueId = 80060101,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C0C52",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060102,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C52"
        },
        [80060102] = {
          ContentTC = "在傳頌會佈施的時候，有位好心腸的太太就帶來過她親自調製的麵包飲料。她說做這個可麻煩了呢！",
          DialogueId = 80060102,
          GUID = "C86C0C7C",
          NextDialogue = 80060103,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C7C"
        },
        [80060103] = {
          ContentTC = "嗯，得先把麵包切成小塊，撒上甜絲絲的麥芽糖，再放在烤箱裡烘得熱乎乎，最後還要泡在水裡，咕嘟嘟發酵……",
          DialogueId = 80060103,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0CA6",
          NextDialogue = 80060104,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CA6"
        },
        [80060104] = {
          ContentTC = "唔……你做的和那位太太做的一樣好喝！",
          DialogueId = 80060104,
          GUID = "C86C0CD0",
          NextOptions = {
            [1] = 80060105
          },
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CD0"
        },
        [80060105] = {
          ContentTC = "你連這個都知道？",
          DialogueId = 80060105,
          GUID = "C86C0CFA",
          NextDialogue = 80060106
        },
        [80060106] = {
          ContentTC = "哼哼，能讓大家吃飽喝好的東西我全都知道！",
          DialogueId = 80060106,
          GUID = "C86C0D24",
          NextDialogue = 80060107,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D24"
        },
        [80060107] = {
          ContentTC = "可不是吹牛哦，我可是艾利西安的食物百科全書，沒有糧秣專員松露不知道的食物！",
          DialogueId = 80060107,
          FacialId = {
            [1] = "95101:Confident02"
          },
          GUID = "C86C0D4E",
          NextDialogue = 80060108,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D4E"
        },
        [80060108] = {
          ContentTC = "所以，你在「吃」上有任何問題都可以來問我！這個季節最好吃的蔬菜在哪裡呀，這道菜是用什麼做的呀……我通通都知道！",
          DialogueId = 80060108,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0D78",
          NextOptions = {
            [1] = 80060109
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D78"
        },
        [80060109] = {
          ContentTC = "真的這麼厲害？你能猜出來你剛才喝的飲料裡放了什麼水果嗎？",
          DialogueId = 80060109,
          GUID = "C86C0DA2",
          NextDialogue = 80060110
        },
        [80060110] = {
          ContentTC = "好呀，讓我再嚐一嚐！……是北風莓！不過你用的莓子還有些澀，要是過幾天再摘，莓子會更大更甜的！",
          DialogueId = 80060110,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C0DCC",
          NextOptions = {
            [1] = 80060111
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0DCC"
        },
        [80060111] = {
          ContentTC = "還有一種漿果沒猜出來。",
          DialogueId = 80060111,
          GUID = "C86C0DF6",
          NextDialogue = 80060112
        },
        [80060112] = {
          ContentTC = "確實還有另外的味道，好熟悉……讓我想想.....讓我想想…….",
          DialogueId = 80060112,
          GUID = "C86C0E20",
          NextOptions = {
            [1] = 80060113
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E20"
        },
        [80060113] = {
          ContentTC = "猜不出來就讓我告訴你吧，是——",
          DialogueId = 80060113,
          GUID = "C86C0E4A",
          NextDialogue = 80060114
        },
        [80060114] = {
          ContentTC = "——是朱紅淚滴！今天早晨從野外剛剛採集的朱紅淚滴，對吧？",
          DialogueId = 80060114,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0E74",
          NextOptions = {
            [1] = 80060115
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E74"
        },
        [80060115] = {
          ContentTC = "你說對了……",
          DialogueId = 80060115,
          GUID = "C86C0E9E",
          NextDialogue = 80060116
        },
        [80060116] = {
          ContentTC = "嘿嘿，不用這麼驚訝，可別小瞧我松露的舌頭哦！我和榛子一起找了這——麼久吃的，別說是朱紅淚滴，什麼稀奇古怪的東西我都嚐過啦。",
          DialogueId = 80060116,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0EC8",
          NextDialogue = 80060117,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EC8"
        },
        [80060117] = {
          ContentTC = "朱紅淚滴的味道有點酸，像梅子，最適合和甜甜的漿果放在一起；巨松果的皮特別厚實，但是裡面的果仁又白又嫩，脆脆的、甜甜的！",
          DialogueId = 80060117,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C0EF2",
          NextDialogue = 80060118,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EF2"
        },
        [80060118] = {
          ContentTC = "匍地枝黑黢黢的，看著就難吃，吃到嘴裡果然又苦又澀；罐子裡裝著的隔熱塗膠看著像牛奶，聞著像果子，但吃下去會肚子疼，你記著千萬別吃！",
          DialogueId = 80060118,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C0F1C",
          NextOptions = {
            [1] = 80060119,
            [2] = 80060122
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F1C"
        },
        [80060119] = {
          ContentTC = "你該不會連穢獸觸手什麼的都嚐過吧……",
          DialogueId = 80060119,
          GUID = "C86C0F46",
          NextDialogue = 80060120
        },
        [80060120] = {
          ContentTC = "這個倒是沒有。會是什麼味道呢？我猜應該會很滑，彈性很好……要不下次和榛子一起試看看……",
          DialogueId = 80060120,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0F70",
          NextDialogue = 80060121,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F70"
        },
        [80060121] = {
          ContentTC = "啊……不行不行！雖然榛子能撞飛小個兒的穢獸，但大穢獸很可怕，不能讓榛子冒這個險！",
          DialogueId = 80060121,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0F9A",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F9A"
        },
        [80060122] = {
          ContentTC = "你能健康活到現在，真不容易……",
          DialogueId = 80060122,
          GUID = "C86C0FC4",
          NextDialogue = 80060123
        },
        [80060123] = {
          ContentTC = "嗯，小時候和榛子流浪的時候確實偶爾會吃到有毒的果子，吃壞肚子。",
          DialogueId = 80060123,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0FEE",
          NextDialogue = 80060124,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0FEE"
        },
        [80060124] = {
          ContentTC = "不過放心吧，現在路邊的野花野果，我已經可以看一眼，聞一聞，就知道有沒有毒，能不能吃啦。",
          DialogueId = 80060124,
          GUID = "C86C1018",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1018"
        },
        [80060125] = {
          ContentTC = "你怎麼嚐過這麼多食物？",
          DialogueId = 80060125,
          GUID = "C86C1042",
          NextDialogue = 80060126
        },
        [80060126] = {
          ContentTC = "因為沒有東西吃呀。很小很小的時候，我就在外面一個人流浪了。",
          DialogueId = 80060126,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C106C",
          NextDialogue = 80060127,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C106C"
        },
        [80060127] = {
          ContentTC = "我從小就比別人吃得多一些，所以就算偶爾遇到好心人掰給我幾塊點心，我還是吃不飽，每天都覺得好餓好餓……",
          DialogueId = 80060127,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1096",
          NextDialogue = 80060128,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1096"
        },
        [80060128] = {
          ContentTC = "哎呀，你不要這個表情嘛，我早就不難過了，因為我很快就遇到榛子啦。",
          DialogueId = 80060128,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C10C0",
          NextDialogue = 80060129,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10C0"
        },
        [80060129] = {
          ContentTC = "那天我很餓，榛子也很餓，可是榛子明明也是個小不點兒，卻把它從垃圾桶裡翻出來的唯一一塊麵包給了我。",
          DialogueId = 80060129,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C10EA",
          NextDialogue = 80060130,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10EA"
        },
        [80060130] = {
          ContentTC = "我也忘了那時候我怎麼想的，我只記得自己趴在它耳朵邊，對它說，「我們一起離開這座城市，到外面去找食物吧！」",
          DialogueId = 80060130,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C1114",
          NextOptions = {
            [1] = 80060131
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1114"
        },
        [80060131] = {
          ContentTC = "豬竟然能聽懂人話……",
          DialogueId = 80060131,
          GUID = "C86C113E",
          NextDialogue = 80060132
        },
        [80060132] = {
          ContentTC = "嗯，很神奇，對吧！榛子一定是神明大人賜給我的朋友。",
          DialogueId = 80060132,
          GUID = "C86C1168",
          NextDialogue = 80060133,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1168"
        },
        [80060133] = {
          ContentTC = "從那天之後，榛子馱著我，去田野，去山林……我們再也沒有餓肚子，甚至還能存下食物，分給和我們一樣饑餓的人。",
          DialogueId = 80060133,
          GUID = "C86C1192",
          NextDialogue = 80060134,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1192"
        },
        [80060134] = {
          ContentTC = "啊……榛子，不知道它一個在外頭會不會餓。那個那個，請問我可以把你送給我的飲料打包半份帶給榛子嗎？",
          DialogueId = 80060134,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C11BC",
          NextOptions = {
            [1] = 80060135,
            [2] = 80060138
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C11BC"
        },
        [80060135] = {
          ContentTC = "當然可以。",
          DialogueId = 80060135,
          GUID = "C86C11E6",
          NextDialogue = 80060136
        },
        [80060136] = {
          ContentTC = "哇……你真是好心腸！之前總有人看不慣榛子長得像小豬，看到我分給它好吃的就嘮叨個沒完。可是對我來說，榛子是很好很好的同伴……",
          DialogueId = 80060136,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C1210",
          NextDialogue = 80060137,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1210"
        },
        [80060137] = {
          ContentTC = "總之真的謝謝你不嫌棄它！",
          DialogueId = 80060137,
          GUID = "C86C123A",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C123A"
        },
        [80060138] = {
          ContentTC = "不想給豬喝……",
          DialogueId = 80060138,
          GUID = "C86C1264",
          NextDialogue = 80060139
        },
        [80060139] = {
          ContentTC = "好吧，那、那我也不喝了。",
          DialogueId = 80060139,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C128E",
          NextDialogue = 80060140,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C128E"
        },
        [80060140] = {
          ContentTC = "榛子是我最好的同伴，你嫌棄它和嫌棄我是一樣的……榛子會傷心的，我也會。不過，還是要謝謝你的麵包飲料。",
          DialogueId = 80060140,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C12B8",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12B8"
        },
        [80060141] = {
          ContentTC = "我已經喝飽啦。改天見！",
          DialogueId = 80060141,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C12E2",
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12E2"
        },
        [80060201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "嗯……唔唔……",
          DialogueId = 80060201,
          GUID = "C86C1CBA",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060202,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CBA"
        },
        [80060202] = {
          ContentTC = "唉……",
          DialogueId = 80060202,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1CE4",
          NextOptions = {
            [1] = 80060203
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CE4"
        },
        [80060203] = {
          ContentTC = "嗯？怎麼這麼不開心？",
          DialogueId = 80060203,
          GUID = "C86C1D0E",
          NextDialogue = 80060204
        },
        [80060204] = {
          ContentTC = "咦？沒，沒有啊……沒有不開心。嘿嘿，嘿嘿嘿！",
          DialogueId = 80060204,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C1D38",
          NextOptions = {
            [1] = 80060205
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D38"
        },
        [80060205] = {
          ContentTC = "別強撐了，剛剛你臉蛋鼓得像塞了麵包。",
          DialogueId = 80060205,
          GUID = "C86C1D62",
          NextDialogue = 80060206
        },
        [80060206] = {
          ContentTC = "唉，你都看出來了呀……好吧，雖然分給人麵包好，分給人煩惱不好，但既然你問了，那你就來幫我評評理吧！",
          DialogueId = 80060206,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1D8C",
          NextDialogue = 80060207,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D8C"
        },
        [80060207] = {
          ContentTC = "我前兩天遇到了一個很討厭的傢伙……他好像是哪個貴族家裡的管家，跑來找我們糧秣專員說要收購堅果。",
          DialogueId = 80060207,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1DB6",
          NextDialogue = 80060208,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DB6"
        },
        [80060208] = {
          ContentTC = "他讓僕人帶了整整七個麻袋，訂單上的酬勞也有好多好多零！",
          DialogueId = 80060208,
          GUID = "C86C1DE0",
          NextDialogue = 80060209,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DE0"
        },
        [80060209] = {
          ContentTC = "司祭姐姐說啦：「有錢不賺，公雞下蛋！」 所以我和榛子為了這個單子忙活了整整一天。",
          DialogueId = 80060209,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1E0A",
          NextOptions = {
            [1] = 80060210
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E0A"
        },
        [80060210] = {
          ContentTC = "難道他收了東西卻不給錢？",
          DialogueId = 80060210,
          GUID = "C86C1E34",
          NextDialogue = 80060211
        },
        [80060211] = {
          ContentTC = "正好相反，他不僅給足了錢，還因為我們幹活快，給了額外的報酬。本來是件好得不能再好的事啦——",
          DialogueId = 80060211,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1E5E",
          NextDialogue = 80060212,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E5E"
        },
        [80060212] = {
          ContentTC = "但偏偏我眼尖，他們臨走的時候，我看見管家從麻袋裡挑出了好幾個新鮮的扭扭果扔掉了。",
          DialogueId = 80060212,
          GUID = "C86C1E88",
          NextDialogue = 80060213,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E88"
        },
        [80060213] = {
          ContentTC = "我趕緊攔住他，告訴他，這都是很好吃很好吃的堅果，扭扭果天生就長了一層白絨絨，並不是發黴！",
          DialogueId = 80060213,
          GUID = "C86C1EB2",
          NextDialogue = 80060214,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EB2"
        },
        [80060214] = {
          ContentTC = "結果你猜猜他說什麼——他說他知道這些不是壞掉的堅果，只是榨不出什麼油水，所以才扔掉了！",
          DialogueId = 80060214,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1EDC",
          NextOptions = {
            [1] = 80060215
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EDC"
        },
        [80060215] = {
          ContentTC = "榨油水……？",
          DialogueId = 80060215,
          GUID = "C86C1F06",
          NextDialogue = 80060216
        },
        [80060216] = {
          ContentTC = "是呀，他們要這——麼多堅果根本不是用來吃的！說出來氣死你！",
          DialogueId = 80060216,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1F30",
          NextDialogue = 80060217,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F30"
        },
        [80060217] = {
          ContentTC = "他說他的雇主這家人，每天都要用煮好的牛奶泡澡，牛奶要挑牧場裡最壯實的奶牛產的！",
          DialogueId = 80060217,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1F5A",
          NextDialogue = 80060218,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F5A"
        },
        [80060218] = {
          ContentTC = "不僅如此，他們還要在泡澡的牛奶里加新鮮的香料，之前用的是花圃的鬱金香花瓣製成的香薰，現在又要用堅果做精油啦！",
          DialogueId = 80060218,
          GUID = "C86C1F84",
          NextDialogue = 80060219,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F84"
        },
        [80060219] = {
          ContentTC = "至於那些不能用來榨油的堅果，他們竟然全都要扔進垃圾桶。",
          DialogueId = 80060219,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1FAE",
          NextOptions = {
            [1] = 80060220,
            [2] = 80060222
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1FAE"
        },
        [80060220] = {
          ContentTC = "好浪費啊……",
          DialogueId = 80060220,
          GUID = "C86C1FD8",
          NextDialogue = 80060221
        },
        [80060221] = {
          ContentTC = "就是嘛，就算我看得下去，榛子也肯定不會同意的！",
          DialogueId = 80060221,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2002",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2002"
        },
        [80060222] = {
          ContentTC = "好羡慕啊……",
          DialogueId = 80060222,
          GUID = "C86C202C",
          NextDialogue = 80060223
        },
        [80060223] = {
          ContentTC = "啊，不可以羡慕他！教典裡說過，浪費糧食是很大的罪惡！他一定會倒大楣的！",
          DialogueId = 80060223,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2056",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2056"
        },
        [80060224] = {
          ContentTC = "我把那傢伙給的銀幣丟還給了他，搶回了我的堅果。我才不能看著他們把堅果浪費掉！在神明大人的種種教誨中，最不可饒恕的罪過就是浪費！",
          DialogueId = 80060224,
          GUID = "C86C2080",
          NextOptions = {
            [1] = 80060225,
            [2] = 80060227
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2080"
        },
        [80060225] = {
          ContentTC = "松露說得對，揮霍食物確實很不應該。",
          DialogueId = 80060225,
          GUID = "C86C20AA",
          NextDialogue = 80060226
        },
        [80060226] = {
          ContentTC = "對吧對吧！浪費一份食物，那就多一個吃不飽的人。哪怕多一個也不行！",
          DialogueId = 80060226,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C20D4",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C20D4"
        },
        [80060227] = {
          ContentTC = "既然是付了錢的，怎麼處置也是他們的自由……",
          DialogueId = 80060227,
          GUID = "C86C20FE",
          NextDialogue = 80060228
        },
        [80060228] = {
          ContentTC = "啊……？神明不是這麼說的……唔，可是你說的好像也有道理……但我還是覺得好像哪兒不對勁——",
          DialogueId = 80060228,
          GUID = "C86C2128",
          NextDialogue = 80060229,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2128"
        },
        [80060229] = {
          ContentTC = "嗚，好麻煩，不想了。既然他有處置食物的自由，那我也有不賣給他的自由吧！",
          DialogueId = 80060229,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2152",
          NextDialogue = 80060230,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2152"
        },
        [80060230] = {
          ContentTC = "要是這些不為食物發愁的傢伙們也能知道，在他們看不到的地方有好些人還餓著肚子就好了。",
          DialogueId = 80060230,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C217C",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C217C"
        },
        [80060231] = {
          ContentTC = "最後，雖然到手的銀幣丟了，被司祭姐姐嘮叨了好久，但我還是把那些堅果都分給了窮人。",
          DialogueId = 80060231,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C21A6",
          NextDialogue = 80060232,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21A6"
        },
        [80060232] = {
          ContentTC = "我知道餓肚子是什麼感覺，一點也不好受！……我再也不要餓肚子了，也不想看其他人餓肚子。",
          DialogueId = 80060232,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C21D0",
          NextOptions = {
            [1] = 80060233
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21D0"
        },
        [80060233] = {
          ContentTC = "松露是個善良的孩子。",
          DialogueId = 80060233,
          GUID = "C86C21FA",
          NextDialogue = 80060234
        },
        [80060234] = {
          ContentTC = "唉……總感覺距離完成我和榛子——」讓世界上所有人都吃飽」的夢想還有好遠、好遠的路啊。",
          DialogueId = 80060234,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C2224",
          NextDialogue = 80060235,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2224"
        },
        [80060235] = {
          ContentTC = "嗯——不能再等啦！我和榛子現在就要去籌備糧食！改天再來找你玩，你也記得要多吃飯！",
          DialogueId = 80060235,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C224E",
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C224E"
        },
        [80060301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "嘿嘿，這個季節的北風莓汁果然是最香的，一點也不酸，甜滋滋的，真好喝！",
          DialogueId = 80060301,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2D22",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060302
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D22"
        },
        [80060302] = {
          ContentTC = "你喜歡就好。",
          DialogueId = 80060302,
          GUID = "C86C2D4C",
          NextDialogue = 80060303
        },
        [80060303] = {
          ContentTC = "可以把配方也分我一份嗎？榛子要是能嚐到一定會開心地跳起來！",
          DialogueId = 80060303,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C2D76",
          NextOptions = {
            [1] = 80060304
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D76"
        },
        [80060304] = {
          ContentTC = "當然可以。",
          DialogueId = 80060304,
          GUID = "C86C2DA0",
          NextDialogue = 80060305
        },
        [80060305] = {
          ContentTC = "謝謝你！你真是個至誠至善、親厚什麼良什麼——反正就是經文裡說的大大大好人！",
          DialogueId = 80060305,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C2DCA",
          NextDialogue = 80060306,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DCA"
        },
        [80060306] = {
          ContentTC = "我們以前也經常去摘北風莓，只要輕輕扭一扭，莓子就落到手心啦。我每次都會摘滿滿幾大籃，榛子馱回去的時候也好開心。",
          DialogueId = 80060306,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2DF4",
          NextDialogue = 80060307,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DF4"
        },
        [80060307] = {
          ContentTC = "有一次吃了太多莓子，我和榛子的舌頭和嘴巴都被染成紫色的了，在小河邊怎麼洗都洗不乾淨。",
          DialogueId = 80060307,
          GUID = "C86C2E1E",
          NextDialogue = 80060308,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E1E"
        },
        [80060308] = {
          ContentTC = "榛子一著急就跳進河裡洗，結果被石頭下的溪蟹夾住了腳，痛得直哼哼。我當然想也不想地沖進河裡救榛子啦，沒想到石頭下面還有一隻大溪蟹……",
          DialogueId = 80060308,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2E48",
          NextDialogue = 80060309,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E48"
        },
        [80060309] = {
          ContentTC = "最後我們兩個身上都溼答答的，只能一瘸一拐地花著臉回去。麥格芬司祭一邊給我們包紮，一邊板起臉來教訓我們。",
          DialogueId = 80060309,
          GUID = "C86C2E72",
          NextDialogue = 80060310,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E72"
        },
        [80060310] = {
          ContentTC = "從那以後榛子每次路過漿果叢的時候，都會眼巴巴地看著，但再也不敢吃北風莓了。",
          DialogueId = 80060310,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2E9C",
          NextOptions = {
            [1] = 80060311
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E9C"
        },
        [80060311] = {
          ContentTC = "那位麥格芬司祭……你們很怕她？",
          DialogueId = 80060311,
          GUID = "C86C2EC6",
          NextDialogue = 80060312
        },
        [80060312] = {
          ContentTC = "我還好！但是榛子每次看到她都會瑟瑟發抖，大概是她一開始總是嚇唬榛子，說要趕它出門吧。",
          DialogueId = 80060312,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C2EF0",
          NextDialogue = 80060313,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2EF0"
        },
        [80060313] = {
          ContentTC = "麥格芬司祭剛收養我的時候，總是擔心榛子飯量太大，會吃掉很多很多口糧，害得大家沒飯吃。",
          DialogueId = 80060313,
          GUID = "C86C2F1A",
          NextDialogue = 80060340,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1A"
        },
        [80060314] = {
          ContentTC = "後來麥格芬司祭雖然答應留下榛子，但還是經常抱怨榛子不夠酷，像這樣——",
          DialogueId = 80060314,
          GUID = "C86C2F44",
          NextDialogue = 80060315,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F44"
        },
        [80060315] = {
          ContentTC = "「小松露啊，你看這本小說，海伯利亞人寫的，講的是勇者和龍交朋友的故事。怎麼人家的動物伙伴都那麼帥氣，咱們卻只能帶著頭豬？」",
          DialogueId = 80060315,
          GUID = "C86C2F6E",
          NextDialogue = 80060316,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F6E"
        },
        [80060316] = {
          ContentTC = "「還有這本，華胥人寫的，雖然人家也帶了豬……但人家的豬好歹是個天堂來的將軍，還能幫忙打打怪物，咱們這個……真就沒點兒特異功能什麼的？」",
          DialogueId = 80060316,
          GUID = "C86C2F98",
          NextOptions = {
            [1] = 80060317,
            [2] = 80060319,
            [3] = 80060320
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F98"
        },
        [80060317] = {
          ContentTC = "她說得對，你應該找個更酷的同伴。",
          DialogueId = 80060317,
          GUID = "C86C2FC2",
          NextDialogue = 80060318
        },
        [80060318] = {
          ContentTC = "不行，不行！我怎麼可以拋下榛子呢！",
          DialogueId = 80060318,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C2FEC",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2FEC"
        },
        [80060319] = {
          ContentTC = "不，榛子是無可取代的。",
          DialogueId = 80060319,
          GUID = "C86C3016",
          NextDialogue = 80060321
        },
        [80060320] = {
          ContentTC = "真沒品位！騎豬多酷啊！",
          DialogueId = 80060320,
          GUID = "C86C3040",
          NextDialogue = 80060321
        },
        [80060321] = {
          ContentTC = "哇，你也這麼覺得呀——你真好，生命之神，豐饒之神，北風莓之神，遁地土豆之神……總之什麼神都會祝福你的！",
          DialogueId = 80060321,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C306A",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C306A"
        },
        [80060322] = {
          ContentTC = "松露真的很喜歡榛子呢，它一定是一隻很特別的魔靈。",
          DialogueId = 80060322,
          GUID = "C86C3094",
          NextDialogue = 80060323
        },
        [80060323] = {
          ContentTC = "特別？是這樣沒錯啦，不過我想知道，{nickname}為什麼也這麼覺得呢？",
          DialogueId = 80060323,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C30BE",
          NextOptions = {
            [1] = 80060324,
            [2] = 80060326
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C30BE"
        },
        [80060324] = {
          ContentTC = "榛子跑得很快。",
          DialogueId = 80060324,
          GUID = "C86C30E8",
          NextDialogue = 80060325
        },
        [80060325] = {
          ContentTC = "其實很多魔靈都可以跑得很快的，好多真正的豬也能做到，榛子的速度還遠遠排不上號呢。",
          DialogueId = 80060325,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3112",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3112"
        },
        [80060326] = {
          ContentTC = "榛子會尋找食物。",
          DialogueId = 80060326,
          GUID = "C86C313C",
          NextDialogue = 80060327
        },
        [80060327] = {
          ContentTC = "榛子是依靠它的鼻子去找紅蕈，其實呢，很多魔靈的鼻子都很好用，好好拜託它們的話，它們也可以幫你找食物的。",
          DialogueId = 80060327,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3166",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3166"
        },
        [80060328] = {
          ContentTC = "其實，這個問題我認真想過的，從麥格芬司祭問我的時候，我就開始問自己了。",
          DialogueId = 80060328,
          GUID = "C86C3190",
          NextDialogue = 80060329,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3190"
        },
        [80060329] = {
          ContentTC = "世界上有那麼多魔靈，帥氣的，可愛的……為什麼我的同伴非榛子不可呢？",
          DialogueId = 80060329,
          GUID = "C86C31BA",
          NextDialogue = 80060330,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31BA"
        },
        [80060330] = {
          ContentTC = "不過我只想了一晚上。等第二天榛子用鼻子蹭我的臉叫我起床的時候，我就想明白啦。",
          DialogueId = 80060330,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C31E4",
          NextDialogue = 80060331,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31E4"
        },
        [80060331] = {
          ContentTC = "因為只有榛子……是我的榛子呀！一直以來，從厚厚的泥裡挖紅蕈、幫我馱著發給大家的沉甸甸的食物、陪我一起教訓壞蛋的是榛子……",
          DialogueId = 80060331,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C320E",
          NextDialogue = 80060332,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C320E"
        },
        [80060332] = {
          ContentTC = "和我一起背根本記不住的教典、在我生病時安慰我、和我在清晨或者傍晚飛奔的也是榛子。",
          DialogueId = 80060332,
          GUID = "C86C3238",
          NextOptions = {
            [1] = 80060333
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3238"
        },
        [80060333] = {
          ContentTC = "因為一起經歷過許許多多的小事，所以才是最特別的？",
          DialogueId = 80060333,
          GUID = "C86C3262",
          NextDialogue = 80060334
        },
        [80060334] = {
          ContentTC = "嗯！雖然很多人都覺得榛子不酷，雖然這個世界上還有很多魔靈比榛子跑得更快、長得更漂亮、挖的紅蕈更多……哪怕榛子真的只是一只平平無奇的小豬……",
          DialogueId = 80060334,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C328C",
          NextDialogue = 80060335,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C328C"
        },
        [80060335] = {
          ContentTC = "榛子依然是全世界只有一個的榛子，是糧秣專員松露最好的伙伴！",
          DialogueId = 80060335,
          GUID = "C86C32B6",
          NextOptions = {
            [1] = 80060336
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C32B6"
        },
        [80060336] = {
          ContentTC = "嗯，我記得。是「糧秣特別專員」。",
          DialogueId = 80060336,
          GUID = "C86C32E0",
          NextDialogue = 80060337
        },
        [80060337] = {
          ContentTC = "對！松露和榛子一起，趕跑饑餓——",
          DialogueId = 80060337,
          GUID = "C86C330A",
          NextDialogue = 80060338,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C330A"
        },
        [80060338] = {
          ContentTC = "啊！我差點忘了，我今天還沒把募集的糧食分發給大家……",
          DialogueId = 80060338,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C3334",
          NextDialogue = 80060339,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3334"
        },
        [80060339] = {
          ContentTC = "我得先走了，{nickname}，我們下次再見吧！",
          DialogueId = 80060339,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C335E",
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C335E"
        },
        [80060340] = {
          ContentTC = "但大家很快就發現了，榛子雖然長得像豬，但並沒有豬豬那麼大的食量，不會吃掉很多口糧的。",
          DialogueId = 80060340,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2F1B",
          NextDialogue = 80060314,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1B"
        },
        [80060401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "{nickname}！那個……我有個很急很急的問題！你可以現在就回答我嗎？",
          DialogueId = 80060401,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3D8A",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060402
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3D8A"
        },
        [80060402] = {
          ContentTC = "什麼問題？",
          DialogueId = 80060402,
          GUID = "C86C3DB4",
          NextDialogue = 80060403
        },
        [80060403] = {
          ContentTC = "我想問——如果你天天都能把肚子填飽的話！是不是就會很開心呀？",
          DialogueId = 80060403,
          GUID = "C86C3DDE",
          NextOptions = {
            [1] = 80060404,
            [2] = 80060405
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3DDE"
        },
        [80060404] = {
          ContentTC = "當然啦。",
          DialogueId = 80060404,
          GUID = "C86C3E08",
          NextDialogue = 80060406
        },
        [80060405] = {
          ContentTC = "不好說。",
          DialogueId = 80060405,
          GUID = "C86C3E32",
          NextDialogue = 80060406
        },
        [80060406] = {
          ContentTC = "那下一個問題……對你來說，是不是只要能天天都把肚子填飽，就會很開心呀？",
          DialogueId = 80060406,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C3E5C",
          NextOptions = {
            [1] = 80060407,
            [2] = 80060409
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3E5C"
        },
        [80060407] = {
          ContentTC = "是啊，都能吃飽了還能有什麼不高興？",
          DialogueId = 80060407,
          GUID = "C86C3E86",
          NextDialogue = 80060408
        },
        [80060408] = {
          ContentTC = "對嘛對嘛，吃飽是最最最重要的事啦。",
          DialogueId = 80060408,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3EB0",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3EB0"
        },
        [80060409] = {
          ContentTC = "也不是，讓人煩心的事還有一大堆呢。",
          DialogueId = 80060409,
          GUID = "C86C3EDA",
          NextDialogue = 80060410
        },
        [80060410] = {
          ContentTC = "嗯？是這樣嗎？那我們好像有些不同喔。",
          DialogueId = 80060410,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3F04",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F04"
        },
        [80060411] = {
          ContentTC = "對我來說，只要能每天吃得飽飽的就很開心啦。可我有兩個朋友，他們和我完全不一樣，把我搞得有點兒糊塗了。",
          DialogueId = 80060411,
          GUID = "C86C3F2E",
          NextDialogue = 80060412,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F2E"
        },
        [80060412] = {
          ContentTC = "一個是住在郊外的、富商家的姐姐，她家有好多亮晶晶的寶石，可以換好多好多銀幣，請很多厲害的廚師大叔給她做數不清的好吃的。",
          DialogueId = 80060412,
          FacialId = {
            [1] = "95101:Doubt01"
          },
          GUID = "C86C3F58",
          NextDialogue = 80060413,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F58"
        },
        [80060413] = {
          ContentTC = "可是富商姐姐還是悶悶不樂的，司祭姐姐說，是因為她要去很遠的地方，去一個她不喜歡的城市，和一個陌生人一起生活。",
          DialogueId = 80060413,
          GUID = "C86C3F82",
          NextDialogue = 80060414,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F82"
        },
        [80060414] = {
          ContentTC = "還、還有另外一個朋友！他是傳頌會裡最最最虔誠的信徒啦，但是他卻用一個月攢下的所有吃的，到聖堂交換一套新版的經卷。",
          DialogueId = 80060414,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C3FAC",
          NextDialogue = 80060415,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FAC"
        },
        [80060415] = {
          ContentTC = "唉，這難道不會餓肚子嗎，他一直瘦瘦小小的，都快變成一片葉子被風吹走了！可他說，只要閱讀著經卷，就能做到什麼什麼——」讓靈魂吃飽」！",
          DialogueId = 80060415,
          GUID = "C86C3FD6",
          NextDialogue = 80060416,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FD6"
        },
        [80060416] = {
          ContentTC = "唔，我實在想不明白……為什麼大家和我不一樣呢？",
          DialogueId = 80060416,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C4000",
          NextDialogue = 80060417,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4000"
        },
        [80060417] = {
          ContentTC = "為什麼有的人就算吃的飽飽的也不會快樂，為什麼有的人就算吃都吃不飽也能感到幸福呢。",
          DialogueId = 80060417,
          GUID = "C86C402A",
          NextDialogue = 80060418,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C402A"
        },
        [80060418] = {
          ContentTC = "經文裡神明大人說過，我們每個人都要努力給他人幸福……可是，到底要怎麼做才能讓大家都開開心心呢？",
          DialogueId = 80060418,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4054",
          NextOptions = {
            [1] = 80060419,
            [2] = 80060420
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4054"
        },
        [80060419] = {
          ContentTC = "人心是最複雜的東西，沒有兩個人的想法完全一樣。",
          DialogueId = 80060419,
          GUID = "C86C407E",
          NextDialogue = 80060421
        },
        [80060420] = {
          ContentTC = "你無法讓所有人快樂，神是瞎說的，別信。",
          DialogueId = 80060420,
          GUID = "C86C40A8",
          NextDialogue = 80060421
        },
        [80060421] = {
          ContentTC = "這是什麼意思？我不太明白……",
          DialogueId = 80060421,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C40D2",
          NextDialogue = 80060422,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40D2"
        },
        [80060422] = {
          ContentTC = "大家難過了會哭鼻子，開心了會大聲笑，生氣了會發脾氣，餓肚子了要吃東西，這不是很簡單的道理嘛。",
          DialogueId = 80060422,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C40FC",
          NextOptions = {
            [1] = 80060423
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40FC"
        },
        [80060423] = {
          ContentTC = "榛子很喜歡喝鹽須菜汁，對吧？",
          DialogueId = 80060423,
          GUID = "C86C4126",
          NextDialogue = 80060424
        },
        [80060424] = {
          ContentTC = "是呀，司祭姐姐每天都會給榛子做新鮮的鹽須菜汁！",
          DialogueId = 80060424,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4150",
          NextOptions = {
            [1] = 80060425
          },
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4150"
        },
        [80060425] = {
          ContentTC = "那你喜歡鹽須菜嗎？",
          DialogueId = 80060425,
          GUID = "C86C417A",
          NextDialogue = 80060426
        },
        [80060426] = {
          ContentTC = "鹽須菜的味道怪怪的，一進到嘴裡舌根都苦了但又有股怪怪的香味，捏著鼻子吃的話也不是不行……哦，原來是這樣！",
          DialogueId = 80060426,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C41A4",
          NextDialogue = 80060427,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41A4"
        },
        [80060427] = {
          ContentTC = "有的人喜歡榛仁露的味道，也有的人聞到榛仁露就要躲得遠遠的，榛子喜歡鹽須菜，但我不喜歡……也就是說，讓大家感到幸福的事情也是不一樣的……",
          DialogueId = 80060427,
          GUID = "C86C41CE",
          NextDialogue = 80060428,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41CE"
        },
        [80060428] = {
          ContentTC = "我知道了，富商姐姐他們應該也是這樣，或許有些東西要比吃的飽飽更令他們感到幸福快樂，所以連肚子餓都可以忍受啦。",
          DialogueId = 80060428,
          FacialId = {
            [1] = "95101:Unhappy01"
          },
          GUID = "C86C41F8",
          NextDialogue = 80060429,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41F8"
        },
        [80060429] = {
          ContentTC = "那……我還能做什麼呢？",
          DialogueId = 80060429,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4222",
          NextOptions = {
            [1] = 80060430,
            [2] = 80060434
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4222"
        },
        [80060430] = {
          ContentTC = "你讓很多人填飽肚子，已經很了不起了。",
          DialogueId = 80060430,
          GUID = "C86C424C",
          NextDialogue = 80060431
        },
        [80060431] = {
          ContentTC = "真的嗎？我已經讓很多人感到幸福了嗎？",
          DialogueId = 80060431,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4276",
          NextDialogue = 80060432,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4276"
        },
        [80060432] = {
          ContentTC = "是的。對很多人來說，吃飽不一定幸福，但如果吃不飽一定會不幸。",
          DialogueId = 80060432,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C42A0",
          NextDialogue = 80060433,
          SpeakNpcId = 10001,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42A0"
        },
        [80060433] = {
          ContentTC = "謝謝你！你說話真好聽！雖然今天摘果子的時候從樹上掉下來摔了好大一跤，但聽你這麼說，我一點都不疼了！",
          DialogueId = 80060433,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C42CA",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42CA"
        },
        [80060434] = {
          ContentTC = "你無法滿足每個人，讓自己開心就足夠了。",
          DialogueId = 80060434,
          GUID = "C86C42F4",
          NextDialogue = 80060435
        },
        [80060435] = {
          ContentTC = "我會開心的事？嗯，我想想……！",
          DialogueId = 80060435,
          GUID = "C86C431E",
          NextDialogue = 80060436,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C431E"
        },
        [80060436] = {
          ContentTC = "看大家吃飽飯會開心，司祭姐姐誇獎我、摸我頭的時候會開心，榛子用鼻子蹭我的時候會開心，還有還有……和你坐在這裡閒聊也很開心！",
          DialogueId = 80060436,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C4348",
          NextDialogue = 80060437,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4348"
        },
        [80060437] = {
          ContentTC = "這麼說的話……好像我只要像現在這樣不變，就可以了？",
          DialogueId = 80060437,
          GUID = "C86C4372",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4372"
        },
        [80060438] = {
          ContentTC = "…………",
          DialogueId = 80060438,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C439C",
          NextDialogue = 80060439,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C439C"
        },
        [80060439] = {
          ContentTC = "唉，你是個聰明人，松露是個笨蛋。如果連你也不知道讓所有人開心的方式，那我肯定也找不到了。",
          DialogueId = 80060439,
          FacialId = {
            [1] = "95101:Sad02"
          },
          GUID = "C86C43C6",
          NextDialogue = 80060440,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43C6"
        },
        [80060440] = {
          ContentTC = "不過我已經決定了，繼續當好糧秣專員！",
          DialogueId = 80060440,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C43F0",
          NextDialogue = 80060441,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43F0"
        },
        [80060441] = {
          ContentTC = "也許我不能讓所有人都開心。但如果填飽肚子能讓大家比現在開心一點點……只要一點點，我應該就沒有辜負神明大人的教誨吧？",
          DialogueId = 80060441,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C441A",
          NextOptions = {
            [1] = 80060442
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C441A"
        },
        [80060442] = {
          ContentTC = "嗯，是很偉大的事業。",
          DialogueId = 80060442,
          GUID = "C86C4444",
          NextDialogue = 80060443
        },
        [80060443] = {
          ContentTC = "嘿嘿……謝謝你！這個世界上有好多好多我搞不明白的事情哦。以後我有什麼搞不懂的，就來找你，你還是會幫我解答吧？",
          DialogueId = 80060443,
          GUID = "C86C446E",
          NextOptions = {
            [1] = 80060444,
            [2] = 80060446
          },
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C446E"
        },
        [80060444] = {
          ContentTC = "沒問題。",
          DialogueId = 80060444,
          GUID = "C86C4498",
          NextDialogue = 80060445
        },
        [80060445] = {
          ContentTC = "好耶！",
          DialogueId = 80060445,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C44C2",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C44C2"
        },
        [80060446] = {
          ContentTC = "一個問題一顆榛子。",
          DialogueId = 80060446,
          GUID = "C86C44EC",
          NextDialogue = 80060447
        },
        [80060447] = {
          ContentTC = "啊，這個不行，榛子如果離開了我，會害怕的……",
          DialogueId = 80060447,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4516",
          NextDialogue = 80060448,
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4516"
        },
        [80060448] = {
          ContentTC = "哦，原來你說的是吃的榛子啊——那沒問題，我會給你帶好多好多榛子，把你的肚皮塞得鼓鼓的！",
          DialogueId = 80060448,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4540",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4540"
        },
        [80060449] = {
          ContentTC = "那麼我們就說好啦。你也一起來見證松露和榛子的偉大事業——小拇指伸出來，我們拉鉤！",
          DialogueId = 80060449,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C456A",
          SpeakNpcId = 95101,
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C456A"
        },
        [80070101] = {
          Camera = "-108.692429,383.760162,74.947266,0.000002,8.799756,-69.59346,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "西比爾軍團長，你用過的那間辦公室我收拾出來了。",
          DialogueId = 80070101,
          GUID = "C87274F2",
          NextDialogue = 80070102,
          SpeakNpcId = 790014,
          TalkActionId = {
            [1] = "790014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87274F2"
        },
        [80070102] = {
          ContentTC = "嗯，那是你晉升少校的獎勵之一，之後就搬進那裡辦公吧。",
          DialogueId = 80070102,
          GUID = "C872751C",
          NextDialogue = 80070103,
          SpeakNpcId = 790013,
          TalkActionId = {
            [1] = "790014:Explain01_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872751C"
        },
        [80070103] = {
          ContentTC = "這也是陛下的意思。你抓捕傳頌會間諜、剿滅神棄者武裝、殲滅大型穢獸的功績他都看在眼裡。",
          DialogueId = 80070103,
          GUID = "C8727546",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070104,
          SpeakNpcId = 790013,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727546"
        },
        [80070104] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentTC = "……全靠軍團長的栽培。",
          DialogueId = 80070104,
          GUID = "C8727570",
          LookAt = {
            [1] = "790013:n(790013)"
          },
          NextDialogue = 80070105,
          SpeakNpcId = 790014,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727570"
        },
        [80070105] = {
          ContentTC = "省省吧，十三軍團不需要阿諛奉承那一套，蘭迪教你的東西你得思考著學，取舍著用。",
          DialogueId = 80070105,
