          NextDialogue = 80090108
        },
        [80090108] = {
          ContentTC = "噫，你也太自作多情了，我只是想嚇唬你！嚇——唬！",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301
        },
        [80090109] = {
          ContentTC = "……嘁，這次算我失手了，下次我一定變成你想不到的東西！",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301
        },
        [80090110] = {
          ContentTC = "變什麼好呢……酒桶？吊燈？大錘？",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090111] = {
          ContentTC = "哇哦，你好有本領。",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008
        },
        [80090112] = {
          ContentTC = "那當然！聽說我這本事叫做……泥，泥什麼來著……泥台？……擬態！對對，「擬態」！",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090113] = {
          ContentTC = "所以你什麼都能變？",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008
        },
        [80090114] = {
          ContentTC = "嘻嘻，可不是！看好了——",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          ContentTC = "我會提出一個你無法拒絕的條件，你最好深思熟慮之後再回答我。",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090116] = {
          ContentTC = "叫醒我的是生意，叫醒你的是什麼？",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090117] = {
          ContentTC = "噗嗤——叫醒我的是惡魔大盜的萬丈光芒！",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118
        },
        [80090118] = {
          ContentTC = "嘻嘻，嘴真甜，比你調的飲料還甜！",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          }
        },
        [80090119] = {
          ContentTC = "噗嗤——我告卡蜜拉了！",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120
        },
        [80090120] = {
          ContentTC = "我才不怕她嘞！沒人能抓到惡魔大盜！",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          }
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "不過我也不是什麼都會變，太大和太小的東西都不行。貓咪可以，老鼠就不可以。木桶可以，路燈架子就不可以。",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090122] = {
          ContentTC = "但這就足夠了，大部分人根本發現不了我的完美偽裝！我隨便變個罐子箱子垃圾桶什麼的，那些壞小偷啊，就只能乖乖地被我收拾了！",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301
        },
        [80090123] = {
          ContentTC = "……完了，以後可有得頭疼了。",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124
        },
        [80090124] = {
          ContentTC = "你嘀嘀咕咕什麼呢？",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090125] = {
          ContentTC = "沒什麼，誇你很厲害的意思。",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008
        },
        [80090126] = {
          ContentTC = "但之後還是別變箱子罐子垃圾桶了，萬一被人路過隨手打爛了然後翻翻找找有用的東西可怎麼辦……",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008
        },
        [80090127] = {
          ContentTC = "誰手這麼欠啊？",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301
        },
        [80090128] = {
          ContentTC = "呃……一些特別富有好奇心的路過市民？",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008
        },
        [80090129] = {
          ContentTC = "有用的就收起來，沒用的就利用完丟掉，壞大人都一個樣！",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301
        },
        [80090130] = {
          ContentTC = "路過市民可沒想傷害任何人！不過，你一直掛在嘴上的「壞大人」是什麼？",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090131] = {
          ContentTC = "聽起來很厲害，還好你沒什麼壞心思。",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132
        },
        [80090132] = {
          ContentTC = "什麼意思？",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090133] = {
          ContentTC = "我是說，要是那些有點小聰明但心思很壞的傢伙有這種本事，那整座城都要雞飛狗跳了。",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008
        },
        [80090134] = {
          ContentTC = "哼哼，我也這麼覺得！我和那些壞大人可不是一路人。等等，你難道是想說本「惡魔大盜」不夠聰明？",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090135] = {
          ContentTC = "沒有沒有，塔比瑟是很聰明的好惡魔。不過這些不重要，我更好奇，「那些壞大人」是什麼？",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090136] = {
          ContentTC = "就是欺負弱小的壞蛋大人！我最先碰到的壞大人就是孤兒院那些照顧小孩的……嘖，說是照顧，其實和看犯人沒啥兩樣。",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301
        },
        [80090137] = {
          ContentTC = "小時候我餓著肚子去廚房找東西吃，被那些壞大人們發現了的話，就會挨打。壞死了！明明是他們不給我東西吃在先！",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301
        },
        [80090138] = {
          ContentTC = "要是現在再讓我遇到他們，我就把他們一個個倒立著捆起來掛在房頂，讓他們瞪大眼看著我把廚房的東西吃光光！",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301
        },
        [80090139] = {
          ContentTC = "都過去了。現在的塔比瑟已經不會被壞大人打了。",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141
        },
        [80090140] = {
          ContentTC = "對，這些壞傢伙就該給點顏色瞧瞧。",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141
        },
        [80090141] = {
          ContentTC = "哼！就是就是！",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090142] = {
          ContentTC = "飲料喝完了，「壞大人」的事下次再講，現在快陪我出去玩！",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090143] = {
          ContentTC = "嘻嘻嘻，我們來玩捉迷藏吧，這次我可不會再被你輕鬆找到了！",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "嗯~喝起來有點鹹鹹的，不過好好喝喔，就像海風味的棉花糖一樣！",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301
        },
        [80090202] = {
          ContentTC = "總感覺在很久很久以前我好像喝過類似的飲料，那時候我和爸爸媽媽一起乘上的船還沒有沉，我也還沒有漂到鎮上被孤兒院收養……",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090203] = {
          ContentTC = "但如果再讓我選，還不如自己一個人流浪呢！壞大人們連吃的都不願多給，更別說飲料了。",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301
        },
        [80090204] = {
          ContentTC = "就算是流浪好歹也能在垃圾桶裡撿點吃的，總比在壞大人魔爪下餓肚子強多了！",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301
        },
        [80090205] = {
          ContentTC = "等到長大點了，就會有群貴客時不時帶走一些和我一樣沒人要的長角小孩，說是被有錢人領養了。",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301
        },
        [80090206] = {
          ContentTC = "我不想要別的爸爸媽媽，但有錢人家一定不缺吃的，我想去，但壞大人說我調皮搗蛋又不老實，貴客才不會看上我咧！",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301
        },
        [80090207] = {
          ContentTC = "哼！那又怎麼樣，要是乖乖聽話我就不是塔比瑟了！反正這鬼地方我是一天也待不下去了，於是我就趁著貴客不注意，變成了他的手提箱。",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090208] = {
          ContentTC = "看來所謂的有錢人也不怎麼聰明嘛！貴客把我拎起來就走，什麼也沒發現，就是苦了我的耳朵，被當成提手拎了一路，差點就掉在地上啦！",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301
        },
        [80090209] = {
          ContentTC = "噫，聽著就痛！以後我一定好好保護你的耳朵！",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210
        },
        [80090210] = {
          ContentTC = "……這話怎麼好像聽著怪怪的……算了，這個不是重點！",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090211] = {
          ContentTC = "塔比瑟居然能從那種地方逃出來，未來的「惡魔大盜」的人非同一般！",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212
        },
        [80090212] = {
          ContentTC = "嘻嘻，那當然！可惜那時候我還不太熟練，否則我才不會把耳朵變成臉對著提手呢。",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090213] = {
          ContentTC = "其實我本來是想悄悄混在那幾個被領養的孩子裡的，想著如果能被有錢人領養，我就再也不用餓肚子了吧。",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301
        },
        [80090214] = {
          ContentTC = "但是貴客渾身上下都是奇怪的消毒水味兒，嗆得我鼻子痛！而且，不知道為什麼，我總覺得……他看孩子們的眼神，有點瘮人……",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301
        },
        [80090215] = {
          ContentTC = "就像是……廚師大叔看魚，看鴨子的那種眼神！",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          }
        },
        [80090216] = {
          ContentTC = "好大人少見，壞大人我可見太多啦！與其去相信他們，還不如靠我自己呢。所以我最後沒有混進孩子的隊伍裡，一個人悄悄逃掉了。",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090217] = {
          ContentTC = "這就是塔比瑟成為惡魔大盜的第一步！",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301
        },
        [80090218] = {
          ContentTC = "我想塔比瑟並不是壞孩子，你只是……很特別。",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219
        },
        [80090219] = {
          ContentTC = "我不是壞，而是很特別嗎？還沒人這麼說過我……特別的孩子，特別的孩子……嘻嘻！",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301
        },
        [80090220] = {
          ContentTC = "「貴客」聽起來就很可疑，塔比瑟做出了冷靜的判斷。",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221
        },
        [80090221] = {
          ContentTC = "就是就是！你也這麼覺得吧！",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090222] = {
          ContentTC = "不過那時候我光顧著自己逃了。要是我有現在的本事，一定悄悄跟在他們屁股後面，看看他們是不是在做壞事！",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090223] = {
          ContentTC = "能安全逃出來，塔比瑟已經做得很好了，恭喜你獲得了自由。",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008
        },
        [80090224] = {
          ContentTC = "是呀，恭喜我自己！好不容易又呼吸到新鮮空氣，第一次發現夜空並不一直都是黑黢黢的，那些透過髒玻璃看起來沒精打采的星星，原來也可以這麼明亮。",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090225] = {
          ContentTC = "我躺在草地上，伴著星星睡了一大覺，轉天醒來，是個大晴天！之後我就一直住在那個海邊小鎮，再也沒有「壞大人」打我了！",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301
        },
        [80090226] = {
          ContentTC = "我還在那裡遇到了一個人……",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301
        },
        [80090227] = {
          ContentTC = "塔比瑟終於碰到好人了嗎？",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008
        },
        [80090228] = {
          ContentTC = "大好人！但我今天有點累了……「惡魔大盜」也會累的！",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090229] = {
          ContentTC = "等你下次準備好新飲料了，我再講給你聽！",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "這次的飲料也很美味！嘻嘻嘻，你可真瞭解我的口味！",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301
        },
        [80090302] = {
          ContentTC = "本大盜昨天晚上是躺著草地看著夜空睡著的，天空從湛藍色逐漸變深，星星一顆顆掛在上面，和撒著糖霜的藍莓奶蓋一模一樣！",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090303] = {
          ContentTC = "除了逃出孤兒院的那晚，我其實很少在草地上睡得這麼安穩。",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301
        },
        [80090304] = {
          ContentTC = "……因為，剛到小鎮的時候，我做了很多不好的事……",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          }
        },
        [80090305] = {
          ContentTC = "所以大人們不喜歡我，叫我「惡魔」……",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301
        },
        [80090306] = {
          ContentTC = "是不是惡作劇沒掌握好分寸？",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307
        },
        [80090307] = {
          ContentTC = "是他們太笨了！唔……好吧，你說的對。",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090308] = {
          ContentTC = "是不是偷吃了小鎮上所有的海魚？",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309
        },
        [80090309] = {
          ContentTC = "我哪有那麼能吃！唔，不過你也說對了一部分……",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090310] = {
          ContentTC = "我一直靠偷吃小攤上的食物過活。小販們氣得想打我，我就學他們氣急敗壞的樣子，還對他們做鬼臉，也沒覺得有什麼不對。",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090311] = {
          ContentTC = "「分我一點你們又餓不死，小氣鬼！」",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301
        },
        [80090312] = {
          ContentTC = "直到遇見了她……",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090313] = {
          ContentTC = "她是魚攤攤主的女兒，看見我偷她家東西，不僅不打我，分海魚給我吃，還問我家人在哪，如果走丟了可以在她家先住一晚，我第一次遇到這麼好的人。",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301
        },
        [80090314] = {
          ContentTC = "後來發生了許多事……她沒有家了，只能去孤兒院，那可不行！我受過的罪，才不會讓她也受一遍！我要帶著她一起生活！",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301
        },
        [80090315] = {
          ContentTC = "我們一起在大太陽下傻笑，在海邊撩起水花濺到對方身上，在泥濘的小路上跑來跑去，我會變成各種小動物逗她開心。",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301
        },
        [80090316] = {
          ContentTC = "她還叫我「塔比瑟姐姐」！雖然和我一起饑一頓飽一頓地過日子，她卻一直說自己很幸福。",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301
        },
        [80090317] = {
          ContentTC = "也是因為她，我才決定不再拿好大人的東西了，我要做個「惡魔大盜」，專門去懲罰那些壞大人！",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
            [1] = 80090318,
            [2] = 80090320
          },
          SpeakNpcId = 92301
        },
        [80090318] = {
          ContentTC = "是因為很在意她的想法嗎？",
          DialogueId = 80090318,
          GUID = "C87F69CC",
          NextDialogue = 80090319
        },
        [80090319] = {
          ContentTC = "嗯，我不想她傷心。",
          DialogueId = 80090319,
          GUID = "C87F69F6",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090320] = {
          ContentTC = "塔比瑟姐姐！",
          DialogueId = 80090320,
          GUID = "C87F6A20",
          NextDialogue = 80090321
        },
        [80090321] = {
          ContentTC = "怎麼突然……救命，住口啊，尷尬死了！",
          DialogueId = 80090321,
          FacialId = {
            [1] = "92301:Unacceptable01"
          },
          GUID = "C87F6A4A",
          NextDialogue = 80090322,
          SpeakNpcId = 92301
        },
        [80090322] = {
          ContentTC = "我就想試試如果我也喊一下，你會不會也帶我過日子……",
          DialogueId = 80090322,
          GUID = "C87F6A74",
          NextDialogue = 80090323,
          SpeakNpcId = 790008
        },
        [80090323] = {
          ContentTC = "噫！你怎麼拿自己跟八歲小孩比呢！我還以為你已經是個成熟的大人了。",
          DialogueId = 80090323,
          GUID = "C87F6A9E",
          NextDialogue = 80090324,
          SpeakNpcId = 92301
        },
        [80090324] = {
          ContentTC = "開玩笑的。所以，塔比瑟是很在意她的想法嗎？",
          DialogueId = 80090324,
          GUID = "C87F6AC8",
          NextDialogue = 80090325,
          SpeakNpcId = 790008
        },
        [80090325] = {
          ContentTC = "因為她問我：「偷善良人的東西，是對的嗎？」",
          DialogueId = 80090325,
          GUID = "C87F6AF2",
          NextDialogue = 80090326,
          SpeakNpcId = 92301
        },
        [80090326] = {
          ContentTC = "我一開始想，那些小販哪裡善良了，看我餓的肚皮都貼一起了，也不給我點吃的，就知道對我發脾氣。",
          DialogueId = 80090326,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6B1C",
          NextDialogue = 80090327,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_Start"
          }
        },
        [80090327] = {
          ContentTC = "後來我才發現，有的小販明明看見我拿東西吃，卻沒管我。",
          DialogueId = 80090327,
          GUID = "C87F6B46",
          NextDialogue = 80090328,
          SpeakNpcId = 92301
        },
        [80090328] = {
          ContentTC = "追著我打的小販們，好像也只是追幾步就算了……當然了，也是因為本大盜逃得夠快！",
          DialogueId = 80090328,
          GUID = "C87F6B70",
          NextDialogue = 80090329,
          SpeakNpcId = 92301
        },
        [80090329] = {
          ContentTC = "有些攤主還會主動把沒賣完的食物留給我，但我只當他們怕了我，那些食物通通是上貢給本大盜的保護費！",
          DialogueId = 80090329,
          GUID = "C87F6B9A",
          NextDialogue = 80090330,
          SpeakNpcId = 92301
        },
        [80090330] = {
          ContentTC = "我只記得別人對我有多壞，卻假裝沒看見這些好人。",
          DialogueId = 80090330,
          GUID = "C87F6BC4",
          NextDialogue = 80090331,
          SpeakNpcId = 92301
        },
        [80090331] = {
          ContentTC = "……想來想去，就覺得心裡堵堵的，吃到嘴裡的食物也不是滋味了。",
          DialogueId = 80090331,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6BEE",
          NextDialogue = 80090332,
          SpeakNpcId = 92301
        },
        [80090332] = {
          ContentTC = "我好像把對「壞大人」的恨，都報復到了這些小販身上。",
          DialogueId = 80090332,
          GUID = "C87F6C18",
          NextDialogue = 80090333,
          SpeakNpcId = 92301
        },
        [80090333] = {
          ContentTC = "我真是個「惡魔」……",
          DialogueId = 80090333,
          GUID = "C87F6C42",
          NextOptions = {
            [1] = 80090334,
            [2] = 80090336
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090334] = {
          ContentTC = "塔比瑟已經做得很好了，很多人用一生都未必能正視自己的錯誤。",
          DialogueId = 80090334,
          GUID = "C87F6C6C",
          NextDialogue = 80090335
        },
        [80090335] = {
          ContentTC = "謝謝你……唉，其實你不用安慰我的，錯了就是錯了。",
          DialogueId = 80090335,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6C96",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090336] = {
          ContentTC = "塔比瑟總有一天也會長大，如果一直欺負好人，不也成了壞大人的一員了嗎？",
          DialogueId = 80090336,
          GUID = "C87F6CC0",
          NextDialogue = 80090337
        },
        [80090337] = {
          ContentTC = "你說的沒錯……唉，你罵吧，多罵幾句，我會乖乖聽著，不還嘴的。",
          DialogueId = 80090337,
          GUID = "C87F6CEA",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090338] = {
          ContentTC = "之後我就一直拿壞小偷和壞大人的東西了，又威風，還不會傷害那些好人。",
          DialogueId = 80090338,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301
        },
        [80090339] = {
          ContentTC = "你還真別說，那些壞人可有錢了！我已經很少餓肚子了，偶爾再逗逗他們，看他們惱羞成怒的樣子，嘻嘻嘻，日子過得可有趣了！",
          DialogueId = 80090339,
          GUID = "C87F6D3E",
          NextOptions = {
            [1] = 80090340
          },
          SpeakNpcId = 92301
        },
        [80090340] = {
          ContentTC = "想捉弄他們才是重點吧。",
          DialogueId = 80090340,
          GUID = "C87F6D68",
          NextDialogue = 80090341
        },
        [80090341] = {
          ContentTC = "沒錯！咳咳咳，才不是！這叫「為民除害」，他們長記性了，就知道欺負好人是不對的了。",
          DialogueId = 80090341,
          GUID = "C87F6D92",
          NextDialogue = 80090342,
          SpeakNpcId = 92301
        },
        [80090342] = {
          ContentTC = "今天說了好多話，嗓子都冒煙了！",
          DialogueId = 80090342,
          GUID = "C87F6DBC",
          NextDialogue = 80090343,
          SpeakNpcId = 92301
        },
        [80090343] = {
          ContentTC = "嘻嘻嘻，剛才的藍莓飲料，再來一杯嘛！",
          DialogueId = 80090343,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F6DE6",
          SpeakNpcId = 92301
        },
        [80090401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentTC = "真好喝！不管喝多少次都不會膩呢！本大盜可不經常誇人的，不過，還是謝謝你總是為我準備食物啦。",
          DialogueId = 80090401,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F776A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090402,
          SpeakNpcId = 92301
        },
        [80090402] = {
          ContentTC = "嘻嘻嘻，白喝了你這麼多次飲料，難得讓你也嚐嚐本大盜的手藝吧！",
          DialogueId = 80090402,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F7794",
          NextDialogue = 80090403,
          SpeakNpcId = 92301
        },
        [80090403] = {
          ContentTC = "你的面前放了一杯可疑的黑色液體，不斷有小氣泡湧上來，散發著一股詭異的味道，仔細看裡面的沉澱物五花八門，能辨認出來的就有各種果乾與糖果。",
          DialogueId = 80090403,
          GUID = "C87F77BE",
          NextDialogue = 80090404
        },
        [80090404] = {
          ContentTC = "噹噹噹！這就是塔比瑟的獨家特調——和我共用同一個稱號的「惡魔大盜」！嘻嘻嘻，我可是把我所有的感激之情都放在裡面咯！",
          DialogueId = 80090404,
          GUID = "C87F77E8",
          NextOptions = {
            [1] = 80090405,
            [2] = 80090410
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090405] = {
          ContentTC = "不喝",
          DialogueId = 80090405,
          GUID = "C87F7812",
          NextDialogue = 80090406
        },
        [80090406] = {
          ContentTC = "真沒品味！這可是世界上僅此一杯的「惡魔大盜」！",
          DialogueId = 80090406,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F783C",
          NextDialogue = 80090407,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090407] = {
          ContentTC = "裡面的材料全都是好大人分享我的好東西，本大盜自己都捨不得吃，才一點點存到現在的，我都不敢想把他們放在一起有多美味！",
          DialogueId = 80090407,
          GUID = "C87F7866",
          NextDialogue = 80090408,
          SpeakNpcId = 92301
        },
        [80090408] = {
          ContentTC = "這樣吧！本大盜和你一人一半怎麼樣？咳咳，才不是我也想嚐嚐，只是為了給膽小鬼做個榜樣！",
          DialogueId = 80090408,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F7890",
          NextDialogue = 80090409,
          SpeakNpcId = 92301
        },
        [80090409] = {
          ContentTC = "來，乾杯！",
          DialogueId = 80090409,
          GUID = "C87F78BA",
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090410] = {
          ContentTC = "喝",
          DialogueId = 80090410,
          GUID = "C87F78E4",
          NextDialogue = 80090411
        },
        [80090411] = {
          ContentTC = "真有眼光！",
          DialogueId = 80090411,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F790E",
          NextDialogue = 80090412,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090412] = {
          ContentTC = "裡面的材料全都是好大人分享我的好東西，本大盜自己都捨不得吃，才一點點存到現在的，我都不敢想把他們放在一起有多美味！",
          DialogueId = 80090412,
          GUID = "C87F7938",
          NextDialogue = 80090413,
          SpeakNpcId = 92301
        },
        [80090413] = {
