          SpeakNpcName = "UI_Npc_Name_Wanzu1"
        },
        [80090439] = {
          ContentTC = "我我我甦醒在孤兒院裡，那段時間塔比瑟剛到了新地方，大人都對她很不好，她又害怕又要強，不願在任何人面前示弱，到了晚上才會抱著我一直發抖……",
          DialogueId = 80090439,
