  {
    MinKey = 80110304,
    MaxKey = 80120439,
    Loader = function()
      return {
        [80110304] = {
          ContentTC = "行吧，也有道理。那就告訴你吧，裡面是一把槍，還有一張面具。",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentTC = "別那麽緊張，是玩具槍。不放心的話，你可以拿它打我。",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C38EA",
          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentTC = "（砰——）",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentTC = "哎呦哎呦，疼疼疼！假子彈也會疼的，你別對著額頭打啊！你給我過來，讓我彈一下腦殼！*的，下手真重。",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentTC = "唉，你這麽一來倒是讓我想起來了，小時候我和裡奧拉打架的時候，也是拿著彈弓瞄著對方腦袋打，現在想來，沒死也是運氣好。這槍……就是送給她的。",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentTC = "嗯，算是吧……這次出任務要來冰湖城，就想著還是得帶點什麽。",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentTC = "啰啰嗦嗦問這麽多，到底幹還是不幹啊？不幹我找其他狩月人了。",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentTC = "我去？算了吧，要不是長官派我來，我才不會回冰湖城這地方。",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentTC = "嘁，少挖苦我。",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentTC = "之前也不是沒回來過，想著能找那些小時候一起掏過鳥窩偷過土豆的朋友喝上幾杯。只聊聊過去的那些傻事，把自己從軍團裡拽出來一些。",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentTC = "結果呢，那些傢伙也不知道從哪兒聽說了我要回來，早就列好了隊，等我回來的時候遠遠敬起了禮，一起叫著「琳恩長官」，連屋頂的鳥都被嚇飛了。",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentTC = "本來我還想著，即便和他們生疏了一點，但聊聊過去一起在大街上撒歡跑的日子，總會拉近距離的。",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentTC = "結果我那幾個朋友啊，根本沒給我說這些話的機會，一個個點頭哈腰，頭都快低到腳尖去了，連個正眼都不給我。",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentTC = "正常啊。我從小到大見多了這些事，太明白他們為什麽怕我了。要不是我幹了這一行，看到士兵就打哆嗦的就得是我了。",
          DialogueId = 80110317,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3AE2",
          NextDialogue = 80110318,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentTC = "冰湖城……不，海伯利亞一直如此。拳頭大的欺負拳頭小的，富有的作踐貧窮的……從我小的時候就是這樣，到現在也沒有變過。",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentTC = "哎，你知道這把槍和這個面具是幹什麽用的嗎？",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentTC = "我和裡奧拉小時候一起看了一本連環畫，講的是一個叫「盧布朗」的俠盜的故事。盧布朗從壞心腸的富人宅子裡偷來寶貝，分給窮人。人們都叫他「面具英雄」。",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentTC = "那時我和裡奧拉用廢紙板做成面具戴在臉上，用彈弓當手槍，跑到冰湖城的城墻上，大聲喊盧布朗在連環畫裡的臺詞，一點也不覺得臉紅。",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentTC = "因為那時候我們兩個覺得我們……遲早有一天……也能成為「英雄」。",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentTC = "很多年後，迪斯瑪尼亞的一家商店裡，我見到了更精美的盧布朗面具和玩具手槍，和真的一樣。我就掏錢買了下來。",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentTC = "「雖然我已經變成了一個只會對卡戎開槍的壞人，但至少裡奧拉還有成為『英雄』的機會」……那時，我是這樣想的。",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentTC = "……直到她在冰湖城看到我時抖得像條畏畏縮縮的鵝，她喊我也從「琳恩」變成了「琳恩長官」，我就知道，她和我一樣，都回不去了。",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentTC = "……唉，頭疼，再來一杯！",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentTC = "就是因為這些破事，我一點也不想回冰湖城。甚至連自己的親弟弟親妹妹，我都不想見。遠遠看一眼，知道他們活著，又長高了，過得還不錯，就夠了。",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentTC = "不，相反。他們總是在信裡寫，他們很想我，希望我多來看看他們。",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentTC = "但是就算看到他們，我又能對他們說什麽？說我又看見了煉金院的什麽實驗？還是說我又俘虜了幾個卡戎人？",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentTC = "……算了算了，每個人都有自己苦惱的破事，這太他*正常了。",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentTC = "這本應該是一個你想回家就回家的世界……或者說，我們這代人應該讓它變成一個你想回家就回家的世界。",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentTC = "也只有像你這樣的外來人會覺得這些不正常，覺得這些是可以改變的。",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentTC = "你是不是還想著有一天，卡戎之民能夠和索拉之民友好相處，不再會因為奇怪的角，奇怪的脊椎，奇怪的法術而受到不同的對待？",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentTC = "說不定呢？",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentTC = "而且，就算你沒法讓冰湖城不下雪，但把雪鏟走，堆個雪人，總做得到的。",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentTC = "至少，你可以走到你的朋友面前，告訴她，你還記得當年的夢想，即使那夢破碎了；你可以敲開家人的門，告訴他們，無論你是什麽身份，你都牽掛著他們，這點永遠不會改變。",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentTC = "……哈哈，老實說，我真的挺喜歡你的想法的。雖然還是覺得有點不切實際，但比那些「世界本就如此，誰也改變不了」的垃圾話好聽多了。",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentTC = "至少，聽了讓我覺得這冰湖城的風都變暖了點。嗯……再給我來一杯。",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentTC = "也讓我看看你能走到哪一步吧。既然你說，你還有改變世界這種白日夢，那我就等著瞧瞧，這個世界會不會因為一個天真的傢伙，變得有那麽一點不一樣。",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentTC = "如果有什麽需要幫忙的，我無事的時候，也可以找我——當然，和軍團對著幹的事除外。不過今天不行，我剛剛改變了主意，待會兒有其他事要忙了。",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentTC = "委托你的單子取消，把面具和玩具槍還給我吧。",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          TalkActionId = {
