        [80120224] = {
          Camera = "-255.582703,344.383789,69.178757,0.000035,7.599951,-112.388451,35.000008,264.602783,false,Manual,2.8",
          ContentTC = "不管這首歌是可薩克先生是忘記了還是故意留下來的，但他既然讓我來處理他餘下的東西，我就要認真對待。",
          DialogueId = 80120224,
          GUID = "C8929440",
          NextDialogue = 80120225,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929440"
        },
        [80120225] = {
          Camera = "-501.36084,57.133301,131.599701,0.000011,-4.399932,31.404215,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "來，{nickname}，和一起去卡蜜拉姐那邊，她好像是認識樂譜的，我要讓她教我怎麼唱。",
          DialogueId = 80120225,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892946A",
          NextDialogue = 80120226,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_End",
            [2] = [[

790008:AgreeHead]]
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892946A"
        },
        [80120226] = {
          Camera = "-302.98645,187.943359,114.158592,0.000014,3.400027,-133.7966,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "等我學會了，就教給冰湖城裡的卡戎們，和他們說，這是一位值得尊敬的音樂家專門為我們卡戎之民寫的曲子。",
          DialogueId = 80120226,
          FacialId = {
            [1] = "790019:Happy01"
          },
          FinalCamera = "-302.98645,187.943359,114.158592,0.000026,3.400027,-133.7966,36.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929494",
          NextDialogue = 80120227,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929494"
        },
        [80120227] = {
          Camera = "193.657837,-330.853027,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          ContentTC = "這樣一來，這首歌就不會像他的廢稿一樣，被扔進烤火的爐子，燒個一乾二淨了。",
          DialogueId = 80120227,
          FinalCamera = "153.661621,-330.320312,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89294BE",
          NextDialogue = 80120228,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294BE"
        },
        [80120228] = {
          Camera = "79.69873,985.43457,55.531265,0.000044,12.80017,92.181931,55.0,490.84668,false,Manual,1.2",
          ContentTC = "說不定有一天這首歌會傳到皇都去，讓他真的聽到卡戎們在唱這首歌，不過聽不到無所謂，反正，我做了我應該做的——",
          DialogueId = 80120228,
          FinalCamera = "103.997955,961.556152,69.737282,0.000067,10.600037,97.981682,55.0,490.84668,false,Manual,1.2",
          GUID = "C89294E8",
          NextDialogue = 80120229,
          SpeakNpcId = 790019,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294E8"
        },
        [80120229] = {
          Camera = "-312.233704,183.148438,116.782532,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentTC = "讓那些不應該被視為垃圾的事物重見天日，變廢為寶，就是我的責任！",
          DialogueId = 80120229,
          FacialId = {
            [1] = "790019:Happy02"
          },
          FinalCamera = "-316.72876,177.902344,117.07206,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929512",
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-285.357117,180.728271,121.084183,0.0,0.0,-143.597351,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929512"
        },
        [80120230] = {
          ContentTC = "後來，據卡蜜拉說，這首《惡魔掙脫了鎖鏈》確實是非常精妙的曲目，並且難度很高。",
          DialogueId = 80120230,
          Duration = 4,
          GUID = "C892953C",
          NextDialogue = 80120231,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892953C"
        },
        [80120231] = {
          ContentTC = "最終，瑪爾潔花了三天，並降了一個八度，才學會了這首歌。而在那之後不久，在冰湖城，就能時不時聽到有人唱起那首歌。",
          DialogueId = 80120231,
          Duration = 5,
          GUID = "C8929566",
          NextDialogue = 80120232,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929566"
        },
        [80120232] = {
          ContentTC = "這就是瑪爾潔所謂的「變廢為寶」吧。",
          DialogueId = 80120232,
          Duration = 3,
          GUID = "C8929590",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929590"
        },
        [80120290] = {
          DialogueId = 80120290,
          GUID = "C89291CB",
          IsBlack = 1,
          NextDialogue = 80120210,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_woodbrk\"},PlayAs2D{true}}"
        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "嗯……",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentTC = "又苦又甜……呃，感覺像是我家臭老頭會喜歡的味道！至於我，大概還要再過十年，不，二十年才能理解這種口味吧。",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentTC = "一點也不理解！人為什麼要自討苦吃呢！",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentTC = "沒錯！幹完活來幾杯，感覺能從腦殼通透到腳後跟！",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentTC = "是我爸爸啦！大家都叫他老馬丁，在我能獨當一面之前，冰湖城的垃圾桶都是他在管。",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentTC = "要不是大家都稱他為「垃圾桶之王」，我怎麼會有「垃圾桶公主」這種又土又俗的稱號……嗚嗚嗚，那個花裡胡哨的臭老頭可把我害慘了！",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentTC = "明明人家想要的是更帥氣、更有智慧、更可靠的……",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentTC = "沒錯沒錯~嘿嘿嘿，還是你懂我！",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentTC = "嗚哇——住口住口！再說就吃我一鏟！",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentTC = "唉……那個臭老頭，自從把工作甩給我就整天不見蹤影，也不知道他在做什麼。最好不要給我和卡蜜拉姐惹事！",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentTC = "呃，要不是這個苦苦的味道……我似乎，好像，其實……也好久沒想起臭老頭的事了……",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentTC = "我工作很忙啊！而且說到底，這些活兒不都是他丟給我的嘛！",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentTC = "咳咳……小動物長大了不都要離開家獨自生存，正常正常。",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentTC = "再說了，在我人生的前十幾年，臭老頭幾乎一直圍著我轉。特別是從老家來冰湖城的時候，我們一整年都是在雪原上過的，就我們倆面面相覷，都沒見過第三個活人。",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentTC = "我早就聽夠了他說的話，唱的歌，耍的賴皮，所以，我就沒那麼想他啦……大概吧。",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentTC = "而且到了冰湖城沒多久，臭老頭就開始「劃分地盤」，「收編地頭蛇」，「確定收保護費的辦法」，「和原有勢力聯手」，「成為話事人」……我看他一個人也挺樂呵的。",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentTC = "哦，就是摸清了垃圾桶分佈，收編原來的環衛工人，確定垃圾桶進貨的標準，通過卡蜜拉姐尋找願意回收貨物的商家，最後成為「垃圾桶之王」。",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentTC = "哎呀，臭老爹就是喜歡說一些花裡胡哨的話，像劇院的小本本上寫的臺詞！大概是他在老家那個到處都在鬥毆的破地方留下了壞習氣，現在也改不掉，呃啊——",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentTC = "難說！臭老頭最喜歡把自己從前的「豐功偉績」當成故事講給我聽了！什麼……",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentTC = "「『清道夫』接受的每一份命令都事關個人榮耀與家族利益，從制定計劃到當日的儀容儀錶，一切都要籌備完全。而你父親我，就是最優秀的『清道夫』。」",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentTC = "都怪他的影響太糟糕，我剛到冰湖城的那陣子，說起話來活脫脫就是一個「小馬丁」。最後還是卡蜜拉姐討厭這種腔調，花了好長一陣子才給我糾正過來……",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentTC = "我才不要！羞死人了！",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentTC = "僅此一次，下不為例啊！",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentTC = "啊！！！！我招，我招還不行嗎？！別念了——",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentTC = "呃……老馬丁把我寄放在卡蜜拉姐店裡，他自己出去辦事的時候，我會說……",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentTC = "「牢記你的使命，父親，我與你的未來取決於你接下來的每個步驟，所以，我希望你能確保自己已經洗完臉、刷完牙、做好了完全的計畫。」",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentTC = "然後老馬丁會摘下帽子對我說：「照您的意思做，女士！若你我中有誰任務失敗，就把對方的名字加上『笨蛋』一詞，寫在水仙平原的大門上示眾。」",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        },
        [80120328] = {
          ContentTC = "我會說：「哦，鑒於我們共用一個姓氏，還是寫在鍋底上吧，既免於丟我的人，也能讓灶火灼燒你的恥辱！」",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentTC = "哈哈哈哈哈哈哈哈哈哈哈！",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentTC = "現在我覺得你被叫「垃圾桶公主」，也不全是老馬丁的錯了。",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentTC = "我不管！就是他的錯！一想起差點就成為和他一樣裝腔作勢的傢伙，我就渾身起雞皮疙瘩。",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentTC = "而且你聽出來沒有，臭老頭對自己的過去明明充滿了懷念與自得，我總覺得他並不完全是討厭老家的混亂才離開那裡的。",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentTC = "但到底發生了什麼事情，讓他不惜帶著我穿越雪原，也要離開老家呢？",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentTC = "他肯定有個天大的秘密瞞著我！但我每次問，他都說什麼「不告訴你，想知道的話就動動自己的腦子想辦法。」",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        },
        [80120335] = {
          ContentTC = "所以去年，我偷偷調查了他很久，但臭老頭神出鬼沒，老家帶來的行李也不知藏到哪兒去了。",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentTC = "我調查了好幾個月，還是一無所獲。最後，還被他狠狠地嘲諷了一通——",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentTC = "對，嘲諷！後來有一天，神出鬼沒的老爹破天荒回來了，陪我玩了一整天，最後甚至還忘了帶走行李箱——就是他從老家帶來的那一隻！",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentTC = "我就想著，臭老頭百密一疏，終於被我抓到了！於是我打開箱子，可是裡面只有一口鍋……",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentTC = "（瑪爾潔憤怒地敲了敲自己蓋在頭頂的東西，發出了咚咚的響聲。）",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentTC = "就是這個！他還在行李箱裡留了一張字條……",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentTC = "「瑪爾潔女士，我預判到您一定會打開這隻行李箱，探尋我的秘密，因此我早已將秘密轉移至您意想不到之處。",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentTC = "「為了彌補您的不悅，特地將此物留給您——這只多功能頭盔正著用可有效防護頭部，倒過來用可生火自炊，前面的礦燈還可用於照明，實乃居家外出的不二之選。」",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentTC = "「以及，生日快樂。——馬丁。」",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentTC = "……我看他明明是在嘲諷我才對！",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentTC = "總之在那之後，我就懶得管他的秘密了。",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentTC = "說起來，我突然有一種預感……",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentTC = "什麼預感？",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentTC = "他的秘密……會不會就藏在這隻「多功能頭盔」裡？",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentTC = "既然他說「秘密在意想不到之處」，那麼有沒有一種可能……最危險的地方反而最安全？",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentTC = "啊……！！這麼說來，那次我都洩氣了，就沒仔細研究這只頭盔！現在想來，這隻頭盔既然是改裝過的，說不定裡面還藏著什麼！讓我拆開看看！",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentTC = "真的！減震層下面是有夾層的！我果然沒看錯你，真有做偵探的潛質！",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentTC = "臭老頭！這下你的秘密被我逮到了吧！",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentTC = "（瑪爾潔熟練地擺弄著鍋子做的頭盔——想必是多次改裝過廢品，瑪爾潔手指靈巧，很快便完成了拆解。）",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentTC = "這、這是……",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentTC = "（瑪爾潔瞪圓了眼睛，看著鍋子說不出話來。你從她手中接過鍋子，只見底層刻著一行小字——）",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentTC = "「致我的笨蛋女兒瑪爾潔：",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentTC = "「恭喜你在『尋找老馬丁的秘密』遊戲中再次失敗。因此，我將在你的名字前加上『笨蛋』一詞。",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentTC = "「鑒於我們共用一個姓氏，我將你的名字刻於鍋底，既免於丟我的人，也能讓灶火灼燒你的恥辱。」",
          DialogueId = 80120358,
          GUID = "C892AA3C",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA3C"
        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "嗚嗚！嗚嗚嗚……偵探小姐又破獲一件爆炸性案件……",
          DialogueId = 80120401,
          GUID = "C892B14A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204011
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B14A"
        },
        [80120402] = {
          ContentTC = "這是、這是喜悅的眼淚！",
          DialogueId = 80120402,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892B174",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204021
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B174"
        },
        [80120403] = {
          ContentTC = "（瑪爾潔灌下滿滿一杯水，把口袋裡的東西小心地捧到你面前，那是一把小動物身上掉下來的毛髮，看顏色有點眼熟……）",
          DialogueId = 80120403,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B19E",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120404,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentTC = "我找到「胖尾巴」！",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentTC = "是以前和我一起在雪原流浪的小貓！",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentTC = "後來我來了冰湖城，它不肯跟著，自己留在了外頭。我還專門縫了一個和它一模一樣的布偶紀念它！",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentTC = "今天我本來打算去城門附近的垃圾桶進貨來著，但意外撿到了這些浮毛，你看！",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentTC = "這個灰濛濛帶黑點的毛色，軟中帶硬的手感，再加上撿到的時候還有點濕漉漉的……絕對是胖尾巴來找我了，錯不了！",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentTC = "以前，我和胖尾巴玩「嫌犯追蹤」的時候，把舔下來的毛放在不同的方向迷惑我就是它的招牌伎倆。",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentTC = "那時本偵探經驗不足，經常被它耍得找不著北，等我白忙活半天，累得氣喘吁吁的時候，它就昂著腦袋，翹著尾巴，趾高氣昂地在我面前走來走去！",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentTC = "想起來了……都想起來了……被「嫌疑貓」戲弄的怒火、丟失追蹤方向的苦惱、不慎在雪原迷路的驚恐……還有握著一把濕乎乎的貓毛時的不知所措！",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentTC = "哼！時隔多年，我已經不是當年的新人偵探了！況且，冰湖城可是本偵探的主場，這一次說什麼我也要把「嫌疑貓」捉拿歸案。",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentTC = "除了根據每條小巷的地形來推測胖尾巴的藏身之地，我還用小魚幹賄賂了本地的「小流浪」們，能提供外來貓線索者，重重有賞！",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentTC = "捉到謊報軍情的白毛大貓一隻！懲罰你半個月不許吃小魚乾！",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentTC = "嘿嘿，就算這麼誇我，嘿嘿，我也不會高興的，嘿嘿！",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentTC = "咳咳，言歸正傳……根據精密的推理，最終我在一個堆滿紙盒子的小巷裡找到了胖尾巴——對於生活在野外的貓來說，一堆紙盒，那是多麼大的誘惑啊！",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentTC = "果然，嫌犯被逮捕時還躺在紙盒裡曬太陽，還優哉遊哉地沖我搖尾巴呢！",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentTC = "這麼久沒見，胖尾巴還是那個胖尾巴，但它看起來和以前有點不一樣了……",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentTC = "我們分別的時候，胖尾巴剛剛長大，不太喜歡別人摸它，一不高興就跑得無影無蹤，這次見面，總感覺它成熟多了，甚至有點老態龍鍾的。",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentTC = "難道「年紀大了脾氣就會變好」也適用於動物嗎？就算我沒帶它最喜歡吃的肉乾。它也眯著眼睛隨便我摸來摸去，肚子也給揉，爪子也給捏，尾巴也給摸。",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentTC = "這次胖尾巴還帶了幾隻小貓來找我，只不過它們和小時候的胖尾巴一樣膽小，只敢在箱子裡伸出小腦袋偷看。但光看毛色就知道，胖尾巴一定把它們照顧得很好！",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentTC = "真令人感慨啊……那隻連雪原鼠都抓不到的笨貓，居然已經能罩著小小貓平安長大了！",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentTC = "這麼一說，我們都比相遇的時候更加成長了。嘿嘿……怪不好意思的……",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentTC = "不瞞你說，剛來冰湖城的時候，我還不像現在這樣。那時候我經常哭鼻子——哎呀，你可千萬別笑話！",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentTC = "有好幾次，我都想離開冰湖城，就假裝當初沒有來過。我想找到胖尾巴，和它一起四處遊蕩，好像也很不錯。",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentTC = "老馬丁總說城市是個好地方，我就也這麼以為。我總想著，「城市」應該是一個一群拿著火把的人湊在一起，互相依賴、彼此守護的避難所——",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentTC = "結果——唉！避難所裡的荒唐事可真不少。卡戎會被毫無道理地區別對待，貴人老爺們一個人就有幾輩子都穿不完的獸皮，貧民窟的窮人卻可能熬不過這個冬天……",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentTC = "而且我實在是太想胖尾巴了！反正每個地方都有好壞，我幹嗎不選擇和我最喜歡的胖尾巴在一起呢！",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentTC = "他？他才不會——也、也不一定……總之，我不還好好在冰湖城嘛！",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentTC = "現在回想一下，只是小孩子遇到難事想逃避罷了。",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentTC = "那時我真的這樣做了。有次被索拉之民的小孩扔了石子，我就氣昏了頭，直沖著城門跑出去了。我喊著胖尾巴的名字，一直、一直向前跑。",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B636"
        },
        [80120432] = {
          ContentTC = "然後……我真的見到了它。胖尾巴正在和一隻雪狼打架……為了一隻銀貝鼠，那是它們共同的獵物。",
          DialogueId = 80120432,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B660",
          NextDialogue = 80120433,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B660"
        },
        [80120433] = {
          ContentTC = "我想胖尾巴可能餓壞了，就丟了一塊肉乾給它。但它看都不看一眼，眼裡只有自己的獵物，和眼前的敵人。",
          DialogueId = 80120433,
          GUID = "C892B68A",
          NextDialogue = 80120434,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B68A"
        },
        [80120434] = {
          ContentTC = "最後，它打贏了雪狼，邁著高傲的步子到我腳邊「嗷嗚」、「嗷嗚」地叫著，不知道是在炫耀，還是很多天沒見了，想來蹭蹭我。",
          DialogueId = 80120434,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B6B4",
          NextDialogue = 80120435,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6B4"
        },
        [80120435] = {
          ContentTC = "我就摸著它毛茸茸的腦袋，對它說，「胖尾巴，我跟你走，我們以後一起生活吧。」",
          DialogueId = 80120435,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B6DE",
          NextDialogue = 80120436,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6DE"
        },
        [80120436] = {
          ContentTC = "但胖尾巴並沒有帶我去它的家。它從我懷裡一溜煙竄下去，朝著一個方向嗷嗚嗷嗚叫個不停。那是冰湖城的方向……",
          DialogueId = 80120436,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B708",
          NextDialogue = 80120437,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B708"
        },
        [80120437] = {
          ContentTC = "我想，它大概是在告訴我，雪原不是我的家，冰湖城才是。",
          DialogueId = 80120437,
          GUID = "C892B732",
          NextDialogue = 80120438,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B732"
        },
        [80120438] = {
          ContentTC = "那個時候我突然就明白了。即使有我在投餵，胖尾巴也還是會努力地捕獵……因為，那是它生存的方式。",
          DialogueId = 80120438,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B75C",
          NextDialogue = 80120439,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B75C"
        },
        [80120439] = {
          ContentTC = "我也有我的生存方式，但我卻不敢面對城裡的生活，非得躲到胖尾巴那邊去——嗚嗚，好丟人啊！",
          DialogueId = 80120439,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B786",
          NextOptions = {
            [1] = 801204391,
            [2] = 801204401
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B786"
        }
      }
    end
  },
  {
