        },
        [80130104] = {
          ContentTC = "這是我們店的產品清單，感興趣的話請來信，我們會送貨上門。",
          DialogueId = 80130104,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E930",
          NextDialogue = 80130105,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E930"
        },
        [80130105] = {
          ContentTC = "好了，太晚的話外面會……會有危險，所以我這就回去了。",
          DialogueId = 80130105,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898E95A",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801301051,
            [2] = 801301052
          },
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E95A"
        },
        [80130106] = {
          ContentTC = "那我再在這裡待一會兒……",
          DialogueId = 80130106,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E984",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E984"
        },
        [80130107] = {
          ContentTC = "你……看起來有點不高興的樣子，是因為我太沒禮貌了嗎，對不起，我不是有意的……",
          DialogueId = 80130107,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E9AE",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9AE"
        },
        [80130108] = {
          ContentTC = "啊，算了，還是我來吧，來之前還說一定不會害怕，一定要把「劈里啪啦」的小玩具賣到冰湖城來。",
          DialogueId = 80130108,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898E9D8",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130109,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9D8"
        },
        [80130109] = {
          ContentTC = "結果就這幅樣子，看來還得是我來救場才行。",
          DialogueId = 80130109,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA02",
          NextDialogue = 80130110,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA02"
        },
        [80130110] = {
          ContentTC = "對……對不起，我一想到{性别:他|她}是冰湖城有名的狩月人就有些害怕，不知道怎麼開口……",
          DialogueId = 80130110,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA2C",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130111,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA2C"
        },
        [80130111] = {
          ContentTC = "怕什麼，你看{性别:他|她}又不吃人，像正常對待小朋友那樣說話就好了。",
          DialogueId = 80130111,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA56",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801301111,
            [2] = 801301112
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA56"
        },
        [80130112] = {
          ContentTC = "……",
          DialogueId = 80130112,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA80",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130113,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA80"
        },
        [80130113] = {
          ContentTC = "你說這話的時候一點都不嚇人，是想要讓我放鬆下來吧，謝謝你。",
          DialogueId = 80130113,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EAAA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAAA"
        },
        [80130114] = {
          ContentTC = "治……治癒系狩月人？雖然沒有聽說這個稱號，但你確實和我想像中那種個子巨大，說話聲音比炸彈還要大的狩月人不太一樣。",
          DialogueId = 80130114,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898EAD4",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAD4"
        },
        [80130115] = {
          ContentTC = "那麼，讓我來介紹一下吧，他是奥利弗，我的朋友。被一個煉金術師給關在了這顆炸彈裡。",
          DialogueId = 80130115,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EAFE",
          NextDialogue = 80130116,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAFE"
        },
        [80130116] = {
          ContentTC = "剛剛我說到的「劈里啪啦」，實際上是我和他一起開的，我負責招待客人，他負責思考新產品。",
          DialogueId = 80130116,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EB28",
          NextDialogue = 80130117,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB28"
        },
        [80130117] = {
          ContentTC = "不過實際上很多時候耶爾會說到一半會卡住，所以我也會代勞向客人介紹──就跟今天一樣。",
          DialogueId = 80130117,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB52",
          NextDialogue = 80130118,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB52"
        },
        [80130118] = {
          ContentTC = "剛剛耶爾說了，「劈里啪啦」會販賣會爆炸的小玩具，具體而言呢，上個月我們的熱銷前三分別是爆炸小飛艇、飛高高煙火和炸裂陀螺。",
          DialogueId = 80130118,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB7C",
          NextOptions = {
            [1] = 801301181,
            [2] = 801301182
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB7C"
        },
        [80130119] = {
          ContentTC = "別心急別心急，更爆炸性的貨物馬上就說。",
          DialogueId = 80130119,
          GUID = "C898EBA6",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBA6"
        },
        [80130120] = {
          ContentTC = "唔……你對這些感興趣嗎？這些其實只是鋪墊，我們真正想賣給你的是這個：",
          DialogueId = 80130120,
          GUID = "C898EBD0",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBD0"
        },
        [80130121] = {
          ContentTC = "看起來是無害的鬧鐘，但實際上威力驚人，只需要一發能夠炸平所有你看不慣的東西的超高能炸彈——群星破碎。",
          DialogueId = 80130121,
          GUID = "C898EBFA",
          NextDialogue = 80130122,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentTC = "我在紅溪城就聽說你是這裡嶄露頭角的狩月人，想必你需要這些。",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentTC = "如果你覺得名字不好記的話，也可以叫這些炸彈小可愛，這是我取的名字，能夠讓帝國士兵放鬆警惕，以為是普通玩具。",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentTC = "然後上面的圖案，也是我畫的，嗯，可以讓這些冷冰冰的炸彈不那麼嚇人。",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentTC = "唉，我之前都和你說過很多次了，願意買炸彈的主顧，那都是想要看它們炸開的時候，這樣的主顧是不會在意炸彈表面圖案的。",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentTC = "可是，我覺得這會讓我們的產品顯得不一樣，再說了，我在畫圖案的時候，你不也興致勃勃地建議我怎麼畫會更討客戶喜歡一些嘛。",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentTC = "那……那是因為既然畫了，那就要畫好一點，如果畫得太難看了就賣不出去了！",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentTC = "咳咳，總之，該說的我們都已經說完了，如果你有需要的話，就給我們來信，說想買群星破碎就行。",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentTC = "不過記得信上要寫「小可愛」，否則會被發現的。",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentTC = "我們店的位置在我給你的產品清單上，等待你的訂購。",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentTC = "來自紅溪城的耶爾和奥利弗，讓人印象深刻的奇怪組合，有空的話買一些小玩具吧，炸裂陀螺和飛高高煙花聽起來都很有趣……",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentTC = "你好……",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentTC = "還記得我嗎，「劈里啪啦」的店主，耶爾。",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentTC = "那……那時候我們還不認識，現在已經沒關係了。",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentTC = "唔……確實一直他都比我更喜歡說話。",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentTC = "今天有一些事，我沒有帶奥利弗一起。",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentTC = "不過不要誤會，倒不是吵架了，平常我們兩個關係很好，但就是因為這樣，我才總有一些話不知道該和誰說好。",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentTC = "所以我才會很冒昧地來找你了，我並不需要你給我一個答案，只需要聽一聽我說話就行。畢竟你看起來就很擅長聽人說話……",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentTC = "是這樣的，其實「劈里啪啦」的第一任店主並不是我，也不是奥利弗，而是一位脾氣很壞很壞的老爺爺。",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentTC = "他沒什麼耐心，總是逼著我幹這幹那，可我總是這也幹不好那也幹不好。就這樣，在他指來喝去下，我勉強學會了怎麼經營店鋪。",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentTC = "突然有一天，他告訴我說他要去很遠的地方，「劈里啪啦」就交給我了。",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentTC = "在那之後我就一個人開店，沒有那位老爺爺的指導，我也不知道怎麼做新的玩具，只能勉勉強強靠舊存貨支撐。",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentTC = "嗯……我也覺得很奇怪，他就這麼突然消失了。",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentTC = "謝謝你，那一段時間我確實每天都在想方設法學各種東西。",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentTC = "總之，就這麼過了幾個月，開始有之前沒見過的大人帶著孩子來買玩具，「劈里啪啦」的生意逐漸好了起來。",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentTC = "但就在這時候，突然來了一個年紀和我差不多大的男孩子，我一開始以為他也是普通的客人，想和他推薦玩具。",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentTC = "但是他卻冷冷的和我說，「劈里啪啦」也並不是那個老爺爺的店，而是搶的他的店。",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentTC = "我一開始肯定是不相信，但是他卻對店裡店外表現的非常熟悉，直接進了店裡的工作台，拿起了各種工具。",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentTC = "我本來想跟他說這些爆炸物很危險，結果他三下兩下就做出了一枚炸彈來，手法看起來比離開的老爺爺還要嫻熟。",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentTC = "然後他也語氣非常不好，說老爺爺是小偷，連帶著我也是小偷。",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentTC = "雖然我不想承認，但是看他對這家店熟悉的熟悉程度，怎麼看他確實是「劈里啪啦」本來的主人。",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentTC = "所以……所以我……",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentTC = "嗯，是的，我想要搞明白這些事情是真是假。然後再決定要不要把「劈里啪啦」還給他。",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentTC = "如果他說的是真的話……我是有這個打算的。",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentTC = "但其實我也很害怕，如果他確實是「劈里啪啦」真正的主人，那又該怎麼辦。",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentTC = "我其實很捨不得這家店……好不容易習慣了去和小朋友們打招呼，和他們推銷新的玩具，那個本來的主人能做到這些嗎？",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentTC = "以及，我又該怎麼去補償他呢……雖然我不知道他是為什麼離開「劈里啪啦」的，但是，我總是想要彌補他……",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentTC = "失去自己的店，回來過後還發現自己的店已經有了其他主人，這種感覺……應該很不好受。",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentTC = "我很了解他，他一定會先狠狠罵我一頓，他大罵我傻，說我既然已經是店主了，就應該好好經營，而不是想著白白送給別人。",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentTC = "他一定會阻止我的……雖然他說話不客氣，但實際上也是一個善良的傢伙。",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentTC = "嗯……那個本來的主人也是一個善良的人，好人不應該總是遇見壞事，應該有人用善意對待他才是。",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentTC = "謝謝你的茶，我搞清了自己的想法……謝謝，我這就回紅溪城。",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentTC = "喔對了，如果你還想買「劈里啪啦」的玩具，依舊寫信就好，這家店是會繼續開下去的。",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE5A"
        },
        [80130234] = {
          ContentTC = "耶爾急匆匆地跑開了，看來他下定決心想要把「「劈里啪啦」還給那個突然出現的老店主。",
          DialogueId = 80130234,
          GUID = "C898FE84",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE84"
        },
        [80130301] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentTC = "哟，你好啊。",
          DialogueId = 80130301,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990982",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130302,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990982"
        },
        [80130302] = {
          ContentTC = "有空嗎？聊幾句？",
          DialogueId = 80130302,
          GUID = "C89909AC",
          NextOptions = {
            [1] = 801303021,
            [2] = 801303022
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909AC"
        },
        [80130303] = {
          ContentTC = "呵，我不是那個傻子。",
          DialogueId = 80130303,
          GUID = "C89909D6",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909D6"
        },
        [80130304] = {
          ContentTC = "我當然不是他，我已經演膩了炸彈遊戲了。",
          DialogueId = 80130304,
          GUID = "C8990A00",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A00"
        },
        [80130305] = {
          ContentTC = "我是奥利弗，奥利弗·庫茲卡，不是什麼被關在炸彈裡的奇妙小畜生。",
          DialogueId = 80130305,
          GUID = "C8990A2A",
          NextDialogue = 80130306,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A2A"
        },
        [80130306] = {
          ContentTC = "也許這個名字你沒聽過，不過沒關係，記好，等哪一天你去皇都迪斯瑪尼亞的時候留心，在北門外十五公里有一處荒廢的堡壘，是我炸塌的。",
          DialogueId = 80130306,
          GUID = "C8990A54",
          NextDialogue = 80130307,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A54"
        },
        [80130307] = {
          ContentTC = "至於我來這裡是幹什麼的，那要取決於你的態度：告訴我，耶爾上次來和你聊了什麼。",
          DialogueId = 80130307,
          GUID = "C8990A7E",
          NextOptions = {
            [1] = 801303071,
            [2] = 801303072
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A7E"
        },
        [80130308] = {
          ContentTC = "比看上去要強硬啊，有意思。看來你也是吃軟不吃硬的傢伙。",
          DialogueId = 80130308,
          GUID = "C8990AA8",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AA8"
        },
        [80130309] = {
          ContentTC = "也行，我喜歡你這樣說話直來直去的。",
          DialogueId = 80130309,
          GUID = "C8990AD2",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AD2"
        },
        [80130310] = {
          ContentTC = "那我就實話實說吧，從最開始講起。",
          DialogueId = 80130310,
          GUID = "C8990AFC",
          NextDialogue = 80130311,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AFC"
        },
        [80130311] = {
          ContentTC = "剛剛我也跟你說了，這副身體，本是我一個人的，炸彈天才，奥利弗·庫茲卡。",
          DialogueId = 80130311,
          GUID = "C8990B26",
          NextDialogue = 80130312,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B26"
        },
        [80130312] = {
          ContentTC = "那時後我年紀也不大，以為能一個人靠著自己搓的小玩意兒把整個海伯利亞炸翻。沒想過被抓了後會怎麼樣，或者說根本沒想會被抓。",
          DialogueId = 80130312,
          GUID = "C8990B50",
          NextDialogue = 80130313,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B50"
        },
        [80130313] = {
          ContentTC = "所以等落到軍團的手裡的時候，我根本不知道我會面臨什麼。",
          DialogueId = 80130313,
          GUID = "C8990B7A",
          NextDialogue = 80130314,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B7A"
        },
        [80130314] = {
          ContentTC = "我被帶到佩劍煉金院的一個研究室裡，一個叫瓊斯的慈眉善目的老頭面前。",
          DialogueId = 80130314,
          GUID = "C8990BA4",
          NextDialogue = 80130315,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BA4"
        },
        [80130315] = {
          ContentTC = "他說話和和氣氣，總和我說什麼犯罪只是心理問題，吃藥就會好起來之類的鬼話。",
          DialogueId = 80130315,
          GUID = "C8990BCE",
          NextDialogue = 80130316,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BCE"
        },
        [80130316] = {
          ContentTC = "每天也給我正常吃喝，只是還強迫我喝藥和做身體檢查。藥倒是不苦，但每次喝完，我都會覺得腦袋的轉速越來越慢……逐漸忘記許多事情。",
          DialogueId = 80130316,
          GUID = "C8990BF8",
          NextDialogue = 80130317,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BF8"
        },
        [80130317] = {
          ContentTC = "一開始我還能用髒話罵這個一看就不安好心的老頭，但他的藥喝著喝著，我逐漸記不清該怎麼罵人了。",
          DialogueId = 80130317,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990C22",
          NextDialogue = 80130318,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C22"
        },
        [80130318] = {
          ContentTC = "忘記是誰說過的了，如果一個人不會說髒話，那他一定不會說話。",
          DialogueId = 80130318,
          GUID = "C8990C4C",
          NextDialogue = 80130319,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C4C"
        },
        [80130319] = {
          ContentTC = "但這對我來說只是一個開始，漸漸的，我發現我忘記怎麼走路……怎麼讓手動起來，就連怎麼呼吸都忘了。",
          DialogueId = 80130319,
          GUID = "C8990C76",
          NextDialogue = 80130320,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C76"
        },
        [80130320] = {
          ContentTC = "我知道他給我喝的藥有問題，可是在喝藥的時候卻記不起來怎麼把它們吐出來，只能等著自己的記憶慢慢融化——我寧願被炸個粉碎。",
          DialogueId = 80130320,
          GUID = "C8990CA0",
          NextDialogue = 80130321,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CA0"
        },
        [80130321] = {
          ContentTC = "到最後，我就像一個旁觀者一樣，在鏡子裡看著奥利弗·庫茲卡的身體，卻不知道這是誰。",
          DialogueId = 80130321,
          GUID = "C8990CCA",
          NextDialogue = 80130322,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CCA"
        },
        [80130322] = {
          ContentTC = "直到有一天，瓊斯這個老頭進門的時候，他對著這副身體說：你的名字叫做耶爾。",
          DialogueId = 80130322,
          GUID = "C8990CF4",
          NextDialogue = 80130323,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CF4"
        },
        [80130323] = {
          ContentTC = "……原來，他是耶爾啊，那我是誰？",
          DialogueId = 80130323,
          GUID = "C8990D1E",
          NextOptions = {
            [1] = 801303231,
            [2] = 801303232
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D1E"
        },
        [80130324] = {
          ContentTC = "你聽不明白也是正常的，我也是過了好一段時間才明白過來，瓊斯……培育出了一個新的人格。",
          DialogueId = 80130324,
          GUID = "C8990D48",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D48"
        },
        [80130325] = {
          ContentTC = "是的，他培育了一個新的人格，好徹底取代奥利弗這個卡戎罪犯。",
          DialogueId = 80130325,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990D72",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D72"
        },
        [80130326] = {
          ContentTC = "不過耶爾的出現對我來說倒是好事。在那之前，我已經完全失去了這具身體，怎麼想讓它動起來都沒用。",
          DialogueId = 80130326,
          GUID = "C8990D9C",
          NextDialogue = 80130327,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D9C"
        },
        [80130327] = {
          ContentTC = "但是我的想法，卻能直接傳達給耶爾。只要我想：「你是一個假貨」的時候，他就會如同受到驚嚇的鵪鶉一般，左右張望，縮起腦袋。",
          DialogueId = 80130327,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990DC6",
          NextDialogue = 80130328,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DC6"
        },
        [80130328] = {
          ContentTC = "你應該能夠想像，我那時候有多厭惡他，日復一日用還能回憶起來的惡毒句子去咒罵他。",
          DialogueId = 80130328,
          GUID = "C8990DF0",
          NextDialogue = 80130329,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DF0"
        },
        [80130329] = {
          ContentTC = "在他看來，我大概就是腦袋裡憑空出現的奇怪聲音吧。",
          DialogueId = 80130329,
          GUID = "C8990E1A",
          NextDialogue = 80130330,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E1A"
        },
        [80130330] = {
          ContentTC = "他也曾經想要把我趕出腦袋過，但是我又怎麼會輸給他呢，我本來就是這副軀體的主人。",
          DialogueId = 80130330,
          GUID = "C8990E44",
          NextDialogue = 80130331,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E44"
        },
        [80130331] = {
          ContentTC = "可恨的是，瓊斯這個老東西發現了他的異常，問耶爾認不認識奥利弗。",
          DialogueId = 80130331,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990E6E",
          NextDialogue = 80130332,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E6E"
        },
        [80130332] = {
          ContentTC = "耶爾嘴上說著不認識，但是瓊斯的眼神卻一直一直死死盯著他的眼睛，好像能看到我一樣。",
          DialogueId = 80130332,
          GUID = "C8990E98",
          NextDialogue = 80130333,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E98"
        },
        [80130333] = {
          ContentTC = "在那過後，瓊斯就為耶爾帶來了一台唱片機。而一旦那台唱片機開始播放音樂，我就會徹底失去知覺，像在黑暗中的燭火被人吹滅一樣。",
          DialogueId = 80130333,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990EC2",
          NextDialogue = 80130334,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EC2"
        },
        [80130334] = {
          ContentTC = "我知道，這台唱片機和音樂就是瓊斯對付我的新藥，他想要讓耶爾徹底取代我。",
          DialogueId = 80130334,
          GUID = "C8990EEC",
          NextDialogue = 80130335,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EEC"
        },
        [80130335] = {
          ContentTC = "我本以為我會在這樣的沉睡和清醒交替之間徹底失去一切記憶，但突然有一天，耶爾告訴我，他不願意再聽那些音樂了。",
          DialogueId = 80130335,
          GUID = "C8990F16",
          NextDialogue = 80130336,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F16"
        },
        [80130336] = {
          ContentTC = "那一刻開始，我突然意識到，這個一直以來我稱之為「假貨」的傢伙，確實是一個單獨的個體。於是我和他一起想了一個計劃，成功從瓊斯老頭身上脫逃。",
          DialogueId = 80130336,
          GUID = "C8990F40",
          NextDialogue = 80130337,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F40"
        },
        [80130337] = {
          ContentTC = "最後，我們到了紅溪城，一起開了一家玩具店，耶爾給它起了「劈里啪啦」這個沒品味的名字。我們都沒有再提起過研究所裡的一切。",
          DialogueId = 80130337,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990F6A",
          NextDialogue = 80130338,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F6A"
        },
        [80130338] = {
          ContentTC = "直到前幾天，我又經歷了一次熟悉的失去意識的感覺，猜到是他又喝了藥，但是不知道他去了哪裡……問來問去，才知道他來了一次冰湖城。",
          DialogueId = 80130338,
          GUID = "C8990F94",
          NextDialogue = 80130339,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F94"
        },
        [80130339] = {
          ContentTC = "老實說，我應該是最了解他的人，他雖然膽小，怕生，但是也足夠善良，他……應該不會有什麼事情想要瞞著我才是。",
          DialogueId = 80130339,
          GUID = "C8990FBE",
          NextDialogue = 80130340,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FBE"
        },
        [80130340] = {
          ContentTC = "所以，我也吞下了能夠讓另外的人格沉睡藥劑，到這裡來搞明白，他到底說了些什麼。",
          DialogueId = 80130340,
          GUID = "C8990FE8",
          NextOptions = {
            [1] = 801303401
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FE8"
        },
        [80130341] = {
          ContentTC = "（複述了耶爾關於「劈里啪啦」與老店主——實際上是自己的身體和奥利弗——的煩惱。）",
          DialogueId = 80130341,
          GUID = "C8991012",
          IsBlack = 1,
          NextDialogue = 80130342,
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991012"
        },
        [80130342] = {
          ContentTC = "所以說……他其實是吃了讓我沉睡的藥，到這邊下定了決心想要把身體還給我？",
          DialogueId = 80130342,
          GUID = "C899103C",
          NextDialogue = 80130343,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899103C"
        },
        [80130343] = {
          ContentTC = "這個……這個……無可救藥的傻東西！",
          DialogueId = 80130343,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8991066",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801303431,
            [2] = 801303432
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991066"
        },
        [80130344] = {
          ContentTC = "……別說風涼話，現在我要做的是在這裡等他醒來，和他把過去的事都說清楚。",
          DialogueId = 80130344,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8991090",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991090"
        },
        [80130345] = {
          ContentTC = "我不知道，我需要在這裡等他醒來，和他把過去的事都說清楚。",
          DialogueId = 80130345,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C89910BA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910BA"
        },
        [80130346] = {
          ContentTC = "也謝謝你了，能夠願意聽我說這麼些過去的事情，等到待會兒耶爾醒過來，怕是還得麻煩你在邊上勸他幾句了。",
          DialogueId = 80130346,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C89910E4",
          NextDialogue = 80130347,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910E4"
        },
        [80130347] = {
          ContentTC = "奥利弗非常焦慮地坐在椅子上抖著腿，看來等到耶爾甦醒，還需要一段時間……",
          DialogueId = 80130347,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C899110E",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899110E"
        },
        [80130401] = {
