          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F763C"
        },
        [80140327] = {
          ContentTC = "抱、抱歉，老師，我這就追加！",
          DialogueId = 80140327,
          GUID = "C89F7666",
          NextDialogue = 80140328,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7666"
        },
        [80140328] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000414,41.996418,18.421019,14.951323,125.0,false,DoNotOverride,2.8",
          ContentTC = "我還能……",
          DialogueId = 80140328,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
          GUID = "C89F7690",
          NextDialogue = 80140329,
          SpeakNpcId = 790036,
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7690"
        },
        [80140329] = {
          ContentTC = "嗯？這東西在嘀咕什麼？",
          DialogueId = 80140329,
          GUID = "C89F76BA",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
          },
          NextDialogue = 80140330,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76BA"
        },
        [80140330] = {
          ContentTC = "我還能變回原本的模樣嗎？",
          DialogueId = 80140330,
          GUID = "C89F76E4",
          NextDialogue = 80140331,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F76E4"
        },
        [80140331] = {
          ContentTC = "哈哈……哈哈哈哈！做什麼白日夢呢？我們也沒動你的腦子啊？是它被火焰燒壞了，還是你本來就這麼蠢？",
          DialogueId = 80140331,
          GUID = "C89F770E",
          NextDialogue = 80140332,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F770E"
        },
        [80140332] = {
          ContentTC = "我們要的是一隻怪物，一具容器，一把趁手的刀，唯獨不是你自己。我們怎麼會把你變回去？",
          DialogueId = 80140332,
          GUID = "C89F7738",
          NextDialogue = 80140333,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7738"
        },
        [80140333] = {
          ContentTC = "為什麼——為什麼？！",
          DialogueId = 80140333,
          GUID = "C89F7762",
          NextDialogue = 80140334,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7762"
        },
        [80140334] = {
          ContentTC = "「為什麼」？",
          DialogueId = 80140334,
          GUID = "C89F778C",
          NextDialogue = 80140335,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F778C"
        },
        [80140335] = {
          ContentTC = "你會對腳下的螞蟻解釋你為什麼要踩扁它嗎？你會對嘴裡的櫻桃解釋你為什麼要嚼碎它嗎？",
          DialogueId = 80140335,
          GUID = "C89F77B6",
          NextDialogue = 80140336,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77B6"
        },
        [80140336] = {
          ContentTC = "哦，抱歉，我忘了——像你這樣卑賤的東西應該​​一輩子都沒嚐過櫻桃的味道吧。",
          DialogueId = 80140336,
          GUID = "C89F77E0",
          NextDialogue = 80140337,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77E0"
        },
        [80140337] = {
          ContentTC = "還沒注射好嗎？手腳利索點，別浪費時間。",
          DialogueId = 80140337,
          GUID = "C89F780A",
          LookAt = {
            [1] = "100337:n(100336)",
            [2] = "100336:n(100337)"
          },
          NextDialogue = 80140338,
          SpeakNpcId = 100337,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F780A"
        },
        [80140338] = {
          ContentTC = "好了，老師。",
          DialogueId = 80140338,
          GUID = "C89F7834",
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7834"
        },
        [80140339] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
          ContentTC = "……我知道。",
          DialogueId = 80140339,
          GUID = "C89F785E",
          NextDialogue = 80140340,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F785E"
        },
        [80140340] = {
          ContentTC = "嗯？知道什麼？",
          DialogueId = 80140340,
          GUID = "C89F7888",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
          },
          NextDialogue = 80140341,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7888"
        },
        [80140341] = {
          ContentTC = "我知道櫻桃是什麼味道。我和母親第一次被劇院收留的時候，團長請我們吃了一頓豐盛的晚餐，餐後甜點就是櫻桃派。",
          DialogueId = 80140341,
          GUID = "C89F78B2",
          NextDialogue = 80140342,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78B2"
        },
        [80140342] = {
          ContentTC = "我還記得它被切開的時候，深紅色的果醬從金黃色的酥皮裡溢出來，一股劣質糖果遠遠無法比擬的香甜氣息在一瞬間填滿了整個餐廳。",
          DialogueId = 80140342,
          GUID = "C89F78DC",
          NextDialogue = 80140343,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78DC"
        },
        [80140343] = {
          ContentTC = "團長說自己年紀大不能吃甜食，讓出了她那份，其實她只是看我嘴饞。",
          DialogueId = 80140343,
          GUID = "C89F7906",
          NextDialogue = 80140344,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7906"
        },
        [80140344] = {
          ContentTC = "老師那時還是個年輕又有活力的姑娘，一邊小口咬著派，一邊偷偷照鏡子確認有沒有碎屑沾在臉上。",
          DialogueId = 80140344,
          GUID = "C89F7930",
          NextDialogue = 80140345,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7930"
        },
        [80140345] = {
          ContentTC = "為了搶奪剩下的最後一塊，小小的蘇珊娜和丹尼斯提出用比賽背台詞的方式決出勝負，結果兩個人都背錯了很多，把老師氣得差點噎著。",
          DialogueId = 80140345,
          GUID = "C89F795A",
          NextDialogue = 80140346,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F795A"
        },
        [80140346] = {
          ContentTC = "哈哈……也不知道大家現在過得怎麼樣。沒了我這個「騙子」，他們應該能正常舉辦演出了吧。",
          DialogueId = 80140346,
          GUID = "C89F7984",
          NextDialogue = 80140347,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7984"
        },
        [80140347] = {
          ContentTC = "……",
          DialogueId = 80140347,
          GUID = "C89F79AE",
          NextDialogue = 80140348,
          SpeakNpcId = 100336,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F79AE"
        },
        [80140348] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
          ContentTC = "怎麼，有什麼異常嗎？",
          DialogueId = 80140348,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
          GUID = "C89F79D8",
          NextDialogue = 80140349,
          Scripts = "MoveTo{ActorId{100337},MoveSpeed{60},TargetPoint{\"Move\"}}",
          SpeakNpcId = 100337,
          ToFinalCameraBlendTime = 3,
