          IsBlack = 1,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B28"
        },
        [80140357] = {
          ContentTC = "我是兇殘的野獸，奉命撕碎所有的獵物。",
          DialogueId = 80140357,
          Duration = 4,
          GUID = "C89F7B52",
          NextDialogue = 80140358,
