          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8404"
        },
        [80140411] = {
          ContentTC = "團長說是《雨日》。",
          DialogueId = 80140411,
          GUID = "C89F842E",
          NextDialogue = 80140412,
          SpeakNpcId = 790027,
          TalkActionId = {
            [1] = "790027:Explain01_Start",
            [2] = "790026:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F842E"
        },
        [80140412] = {
          ContentTC = "《雨日》的人氣也就一般般吧？靠它出人頭地可不容易。唉，要是能再演《雪國的孩子》就好了。那部劇在冰湖城可受歡迎了……",
          DialogueId = 80140412,
          GUID = "C89F8458",
          NextDialogue = 80140413,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8458"
        },
        [80140413] = {
          ContentTC = "就是啊！我也好想再演一次無名的妖精，那可是我最得意的角色，雖然唱段又多又難，但完整演下來的感覺真是太棒了。",
          DialogueId = 80140413,
          GUID = "C89F8482",
          NextDialogue = 80140414,
          Scripts = [[
