        [80150323] = {
          ContentTC = "節奏對不上也沒關係，這不是考試。音樂本來就是自由的。",
          DialogueId = 80150323,
          GUID = "C8A5DE5E",
          NextDialogue = 80150324,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Think_Start"
