          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DFD8"
        },
        [80160001] = {
          ContentTC = "希望你能讓我滿意。",
          DialogueId = 80160001,
          GUID = "C8AC122A",
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC122A"
        },
        [80160101] = {
          Camera = "151.585999,-190.824707,95.898872,0.000003,1.80011,-153.390167,39.474983,223.616684,false,Manual,2.8",
          ContentTC = "確實是個安靜的地方。",
          DialogueId = 80160101,
          Duration = 1,
          GUID = "C8AC2292",
          NextDialogue = 80160102,
          Scripts = "MoveTo{ActorId{790055},TargetPoint{\"Move_320101\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2292"
        },
        [80160102] = {
          Camera = "-31.074158,-13.146484,130.436157,0.000003,0.199305,-130.376617,28.875509,223.616684,false,Manual,2.8",
          ContentTC = "老闆，請給我上一杯酒。",
          DialogueId = 80160102,
          Duration = 3,
          GUID = "C8AC22BC",
          LookAt = {
            [1] = "790055:n(790008)"
          },
          NextOptions = {
            [1] = 801601021,
            [2] = 801601022
          },
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22BC"
        },
        [80160103] = {
          ContentTC = "冰湖城北邊的宅子，擺放著鋼琴、鐵砧、沙漏，裡面有著一位會用自製飲料招待朋友的住客。{性别:他|她}也樂於結識沒有惡意的陌生人。",
          DialogueId = 80160103,
          Duration = 3,
          GUID = "C8AC22E6",
          NextDialogue = 80160104,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22E6"
        },
        [80160104] = {
          ContentTC = "「在那裡，我可以安安靜靜、無人打擾地喝上一杯。」",
          DialogueId = 80160104,
          Duration = 3,
          GUID = "C8AC2310",
          NextDialogue = 80160105,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2310"
        },
        [80160105] = {
          ContentTC = "水仙平原的老闆，卡蜜拉·斯卡雷特是如此告知我的，難道她說謊了？",
          DialogueId = 80160105,
          Duration = 3,
          GUID = "C8AC233A",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC233A"
        },
        [80160106] = {
          ContentTC = "你是指卡蜜拉·斯卡雷特的水仙平原。其實，就是她介紹我來這裡的。",
          DialogueId = 80160106,
          Duration = 3,
          GUID = "C8AC2364",
          NextDialogue = 80160107,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2364"
        },
        [80160107] = {
          ContentTC = "她那裡的酒水幾乎能與皇都媲美，酒客們趨之若鶩。但今天，我只想要一個清靜的地方，再毫無顧忌地喝上兩杯。",
          DialogueId = 80160107,
          Duration = 3,
          GUID = "C8AC238E",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC238E"
        },
        [80160108] = {
          ContentTC = "怎麼，是我的膚色，還是這把武器讓你這麼警惕？輕鬆點，卡蜜拉給我寫了個便條，讓我交給你。",
          DialogueId = 80160108,
          Duration = 3,
          GUID = "C8AC23B8",
          NextDialogue = 80160109,
          Scripts = "PlayAnimation{_delay{2},ActorId{790055},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23B8"
        },
        [80160109] = {
          ContentTC = "「好好招待這位客人，酬勞明天來水仙平原取。」",
          DialogueId = 80160109,
          Duration = 3,
          GUID = "C8AC23E2",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23E2"
        },
        [80160110] = {
          Camera = "-147.684692,-116.645508,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "唉……老實說，我一點都不想拒絕您，畢竟，觸怒您這樣的大人物，對我可一點好處都沒有。",
          DialogueId = 80160110,
          Duration = 5,
          GUID = "C8AC240C",
          NextDialogue = 80160111,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC240C"
        },
        [80160111] = {
          Camera = "359.205933,-102.777344,311.273438,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          ContentTC = "我沒有帶多餘的隨從，也沒有聲張自己的行蹤。女士，哪怕單純因為你認出了我，我都應該在這裡喝上一杯。",
          DialogueId = 80160111,
          Duration = 5,
          FinalCamera = "359.205933,-102.777344,276.765625,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          GUID = "C8AC2436",
          NextDialogue = 80160112,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk03_Start",
            [2] = "790052:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2436"
        },
        [80160112] = {
          Camera = "-310.237366,-391.768555,153.707031,0.000077,-1.999442,56.994724,43.855331,203.023346,false,Manual,5.70148",
          ContentTC = "從帝國最南端與艾利西安接壤的邊境線，到帝國最北端的維德弗尼爾山脈，您的大名無人不知無人不曉——",
          DialogueId = 80160112,
          Duration = 5,
          GUID = "C8AC2460",
          NextDialogue = 80160113,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2460"
        },
        [80160113] = {
          Camera = "14.798828,-154.951172,149.396484,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          ContentTC = "況且有關您的傳聞，每一件都會提及您火一般的膚色。",
          DialogueId = 80160113,
          Duration = 3,
          FinalCamera = "14.798828,-154.951172,177.433594,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          GUID = "C8AC248A",
          NextDialogue = 80160114,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC248A"
        },
        [80160114] = {
          ContentTC = "冰湖城雖然衰落，但好歹是北方最大的城市……再怎麼說我也是在這裡開了很久的店，相信我，認出您並不是一件難事。",
          DialogueId = 80160114,
          Duration = 5,
          GUID = "C8AC24B4",
          NextDialogue = 80160115,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24B4"
        },
        [80160115] = {
          Camera = "263.591919,95.413086,166.505859,0.000114,-4.198818,-154.60791,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "真令人頭疼，我本來以為最多會引起一些人的側目，沒想到在這麼一個冷清的酒館裡還是被人立刻認了出來。",
          DialogueId = 80160115,
          Duration = 3,
          GUID = "C8AC24DE",
          NextDialogue = 80160116,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24DE"
        },
        [80160116] = {
          Camera = "-318.082764,-391.271484,146.335938,0.000113,-0.998813,54.392494,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "典獄長大人，也許您與犯人打交道的時間太多，以致於您沒有意識到，如果一家開酒館在這個時間點只有一位客人，那麼應該早就倒閉了。",
          DialogueId = 80160116,
          Duration = 3,
          GUID = "C8AC2508",
          NextDialogue = 80160117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"-46.92395,-890.245117,476.808594,0.000107,-12.998778,134.186493,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{0}},
CameraMoveTo{TargetPosition{"-46.92395,-890.245117,476.808594,0.000113,-11.398554,-178.21524,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{40}}
}]],
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2508"
        },
        [80160117] = {
          ContentTC = "喏，好幾個人在門口探頭探腦不敢進來──顯然，認出您的可不止我一個。我倒是很願意在這裡為您單獨服務，但帝都官僚強行包場這樣的閒話，我可沒法管。",
          DialogueId = 80160117,
          Duration = 5,
          GUID = "C8AC2532",
          NextDialogue = 80160118,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2532"
        },
        [80160118] = {
          Camera = "393.698364,122.831055,270.308594,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "你說得沒錯，在這裡揭露行蹤並非我的本意，謝謝你的提醒──雖然你的目的也不僅僅是幫我掩飾行蹤。",
          DialogueId = 80160118,
          Duration = 3,
          FinalCamera = "378.453979,117.220703,266.197266,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC255C",
          NextDialogue = 80160119,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC255C"
        },
        [80160119] = {
          Camera = "-65.366943,-360.875,145.677734,0.000188,-1.99826,138.407349,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "（海爾法意味深長地看了一眼酒吧大廳裡的機械齒輪，很顯然，她能夠察覺到機械結構的另一端聯結著被精心隱藏的秘密。）",
          DialogueId = 80160119,
          Duration = 3,
          GUID = "C8AC2586",
          LookAt = {
            [1] = "790055:p(Look_H)"
          },
          NextDialogue = 80160120,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2586"
        },
        [80160120] = {
          Camera = "-75.942627,-56.601562,151.488281,0.000211,-2.598238,-139.994705,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "那裡藏著一個秘密。將謎面放在一個如此明顯的地方，我佩服你的膽量。",
          DialogueId = 80160120,
          Duration = 3,
          GUID = "C8AC25B0",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160121,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25B0"
        },
        [80160121] = {
          ContentTC = "又或者你比我想的更有手腕，為了還能在這裡討一杯酒喝，又或者為了能在這個城市裡平安度日，人們總會為你守口如瓶。",
          DialogueId = 80160121,
          Duration = 3,
          GUID = "C8AC25DA",
          NextDialogue = 80160122,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25DA"
        },
        [80160122] = {
          Camera = "-59.147827,-133.68457,134.808594,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "呵呵……感謝您的謬贊，可惜我只是個連拖欠稅款都萬萬不敢的酒館老闆。至於秘密，誰沒有幾個秘密呢？",
          DialogueId = 80160122,
          Duration = 5,
          FacialId = {
            [1] = "790052:Smile01"
          },
          FinalCamera = "-46.137329,-99.043945,142.054688,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC2604",
          NextDialogue = 80160123,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2604"
        },
        [80160123] = {
          ContentTC = "況且「秘密」也不總是一把鋒利的刀子，它也可能是一張傳承了三代人的火腿秘方。到現在沒有把它端上來，只是因為我不確定是否合您的口味。",
          DialogueId = 80160123,
          Duration = 5,
          GUID = "C8AC262E",
          NextDialogue = 80160124,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC262E"
        },
        [80160124] = {
          Camera = "-86.051514,-78.273438,146.841797,0.000205,-1.598749,-143.392212,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "呵，有趣……我在精於搜查的下屬那裡聽過類似的笑話。",
          DialogueId = 80160124,
          Duration = 3,
          GUID = "C8AC2658",
          NextDialogue = 80160125,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Confident_Start",
            [2] = "790052:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2658"
        },
        [80160125] = {
          ContentTC = "別緊張，女士。",
          DialogueId = 80160125,
          Duration = 3,
          GUID = "C8AC2682",
          NextDialogue = 80160126,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2682"
        },
        [80160126] = {
          Camera = "279.85791,105.764648,170.447266,0.000227,-3.998898,-152.592499,68.94529,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "這裡是你的「水仙平原」，不是法庭，也不是皇家監獄，沒有人會把吐真劑扎進你的脖子，逼你坦白從寬。",
          DialogueId = 80160126,
          Duration = 3,
          GUID = "C8AC26AC",
          NextDialogue = 80160127,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26AC"
        },
        [80160127] = {
          ContentTC = "我到冰湖城有自己的目的，而你也有自己的生存方式，我們沒有在這張「火腿秘方」上消耗太多時間的必要。",
          DialogueId = 80160127,
          Duration = 3,
          GUID = "C8AC26D6",
          NextDialogue = 80160128,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26D6"
        },
        [80160128] = {
          ContentTC = "既然話已經說開，那麼我也不在這裡阻礙你的生意了。",
          DialogueId = 80160128,
          GUID = "C8AC2700",
          NextDialogue = 80160129,
          Scripts = [[
SEQ{
LookAt{_delay{1},LookAtDescription{"790055:n(790055)"}},
TurnTo{TurnToDescription{"790055:p(-180)"}},
MoveTo{ActorId{790055},TargetPoint{"Move_H"},MoveSpeed{80},Visibility{"Show"}}
}]],
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2700"
        },
        [80160129] = {
          Camera = "-105.736328,-382.012695,149.125,0.000248,-3.398559,147.008057,39.565411,252.247864,false,Manual,2.892425",
          ContentTC = "也許你會想知道，我為什麼要特意指出你的秘密。",
          DialogueId = 80160129,
          Duration = 3,
          GUID = "C8AC272A",
          NextDialogue = 80160130,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC272A"
        },
        [80160130] = {
          ContentTC = "我並沒有惡意，請當做是我的職業病在發作——我總是無法放過在我面前遊走的謊言與隱瞞。",
          DialogueId = 80160130,
          Duration = 5,
          GUID = "C8AC2754",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160131,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2754"
        },
        [80160131] = {
          ContentTC = "無法在冰湖城中最好的酒館喝上一杯，我深表遺憾。告辭。",
          DialogueId = 80160131,
          Duration = 3,
          GUID = "C8AC277E",
          LookAt = {
            [1] = "790055:n(790055)"
          },
          NextDialogue = 80160132,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC277E"
        },
        [80160132] = {
          Camera = "-141.847046,-192.130859,169.498047,0.000235,-3.798828,56.604771,47.597221,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "請您留步。",
          DialogueId = 80160132,
          Duration = 3,
          FacialId = {
            [1] = "790052:None"
          },
          GUID = "C8AC27A8",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160133,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27A8"
        },
        [80160133] = {
          Camera = "204.932251,65.897461,166.253906,0.000237,-5.198696,-153.398605,35.000008,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "還有事？",
          DialogueId = 80160133,
          Duration = 3,
          GUID = "C8AC27D2",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160134,
          SpeakNpcId = 790055,
          TurnTo = {
            [1] = "790055:p(75)"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27D2"
        },
        [80160134] = {
          Camera = "-146.874878,-117.574219,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "冰湖城北邊的宅子，擺放著鋼琴、鐵砧、沙漏，那裡有一位會用自製飲料招待朋友的住客。{性别:他|她}也樂於結識沒有惡意的陌生人。",
          DialogueId = 80160134,
          Duration = 5,
          FinalCamera = "-117.245117,-91.633789,163.6875,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC27FC",
          NextDialogue = 80160135,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27FC"
        },
        [80160135] = {
          ContentTC = "如果您需要傾訴，{性别:他|她}會是個不錯的人選，帶著我的委託，{性别:他|她}不會拒絕您。",
          DialogueId = 80160135,
          Duration = 3,
          GUID = "C8AC2826",
          NextDialogue = 80160136,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2826"
        },
        [80160136] = {
          Camera = "209.813721,89.859375,159.263672,0.000217,-2.798328,-149.798874,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "謝謝。以你的洞察力，不應該只滿足於做一個邊陲城市的店主才是。",
          DialogueId = 80160136,
          Duration = 3,
          GUID = "C8AC2850",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160137,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2850"
        },
        [80160137] = {
          Camera = "-246.633789,-309.449219,143.691406,0.00022,0.201757,52.802853,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentTC = "然而，現實總是與人們的想法背道而馳。就像……我也沒想過典獄長大人會是如此講道理的客人。",
          DialogueId = 80160137,
          Duration = 3,
          GUID = "C8AC287A",
          NextDialogue = 80160138,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC287A"
        },
        [80160138] = {
          ContentTC = "因為一些原因，我不會奉上自我介紹。你可以把我當作一個風塵僕僕的過路人，此刻瑣事纏身，需要一杯能暫忘憂愁的飲料。",
          DialogueId = 80160138,
          Duration = 5,
          GUID = "C8AC28A4",
          IsBlack = 1,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC28A4"
        },
        [80160201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "……",
          DialogueId = 80160201,
          GUID = "C8AC32FA",
          NextOptions = {
            [1] = 801602011
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC32FA"
        },
        [80160202] = {
          ContentTC = "無妨。今天我有一個晚上的空閒。",
          DialogueId = 80160202,
          GUID = "C8AC3324",
          NextDialogue = 80160203,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3324"
        },
        [80160203] = {
          ContentTC = "看這裡的居住痕跡，我猜你已經在這裡停駐了很長的時間，但你對物品的擺放卻如此陌生。",
          DialogueId = 80160203,
          GUID = "C8AC334E",
          NextDialogue = 80160204,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC334E"
        },
        [80160204] = {
          ContentTC = "雖然只是客居此地，但我仍然建議你在空閒的時候將房子徹底清理一遍，最好能弄清楚這裡的一點一滴。",
          DialogueId = 80160204,
          GUID = "C8AC3378",
          NextOptions = {
            [1] = 801602041,
            [2] = 801602042
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3378"
        },
        [80160205] = {
          ContentTC = "經驗之談罷了。曾經，我和我最可靠的同僚一起走訪過很多地方，搜查過許多「溫馨的家」，誰能想到呢？",
          DialogueId = 80160205,
          GUID = "C8AC33A2",
          NextDialogue = 80160206,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33A2"
        },
        [80160206] = {
          ContentTC = "栽著名貴品種的花盆裡，埋著精心製作的爆炸物；放著孩子兒時日記的抽屜下面，貼著走私集團的名冊；作為伴手禮隨手收下的酒，卻藏著致命的毒藥……",
          DialogueId = 80160206,
          GUID = "C8AC33CC",
          NextOptions = {
            [1] = 801602061,
            [2] = 801602062
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33CC"
        },
        [80160207] = {
          ContentTC = "不用一臉震驚地看著我，我只是和你分享一下人生經驗。一些被便宜出租的房子，特別是租給你這樣外鄉人的房子，需要格外留心。",
          DialogueId = 80160207,
          GUID = "C8AC33F6",
          NextDialogue = 80160208,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33F6"
        },
        [80160208] = {
          ContentTC = "房東的花言巧語會盡可能從你的口袋裡掏走錢幣，但這房子裡曾發生過什麼，又為什麼便宜了對此一無所知的外鄉人，誰能說得清呢。",
          DialogueId = 80160208,
          GUID = "C8AC3420",
          NextOptions = {
            [1] = 801602081,
            [2] = 801602082
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3420"
        },
        [80160209] = {
          ContentTC = "給你一句忠告吧——「盡可能留神身邊的一切，以免變化發生得猝不及防。」",
          DialogueId = 80160209,
          GUID = "C8AC344A",
          NextDialogue = 80160210,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC344A"
        },
        [80160210] = {
          ContentTC = "呵……說著容易，我卻不算一個合格的踐行者。",
          DialogueId = 80160210,
          GUID = "C8AC3474",
          NextDialogue = 80160211,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3474"
        },
        [80160211] = {
          ContentTC = "我的同僚比我更擅長發現蛛絲馬跡，她有一雙明察秋毫的眼睛，一雙靈巧過人的手——爆炸物，人員名單，毒酒，以及種種千奇百怪的罪案痕跡……",
          DialogueId = 80160211,
          GUID = "C8AC349E",
          NextDialogue = 80160212,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC349E"
        },
        [80160212] = {
          ContentTC = "沒有什麼能逃過她的搜查。",
          DialogueId = 80160212,
          GUID = "C8AC34C8",
          NextDialogue = 80160213,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34C8"
        },
        [80160213] = {
          ContentTC = "她是我的左膀右臂，這並不只是個形容詞，我的雙手能融化玻璃，點燃書本。與此相對，我無法親手檢查每一處疑點，也無法觸碰那些脆弱的證物。",
          DialogueId = 80160213,
          GUID = "C8AC34F2",
          NextDialogue = 80160214,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34F2"
        },
        [80160214] = {
          ContentTC = "此時，她就是我的第二雙手。",
          DialogueId = 80160214,
          GUID = "C8AC351C",
          NextOptions = {
            [1] = 801602141
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC351C"
        },
        [80160215] = {
          ContentTC = "離開？喔……怎麼不算？",
          DialogueId = 80160215,
          GUID = "C8AC3546",
          NextDialogue = 80160216,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3546"
        },
        [80160216] = {
          ContentTC = "我們也曾親密無間，在槍林彈雨中彼此依靠，在繁雜的電碼中尋找線索，在探查真相的死胡同裡徹夜掙扎。",
          DialogueId = 80160216,
          GUID = "C8AC3570",
          NextDialogue = 80160217,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3570"
        },
        [80160217] = {
          ContentTC = "為了至關重要的情報，她不惜以自己的生命犯險，堪堪保住了一條命，卻永遠失去了左耳的聽力。只是為了能讓我能將一個罪犯明正典刑。",
          DialogueId = 80160217,
          GUID = "C8AC359A",
          NextDialogue = 80160218,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC359A"
        },
        [80160218] = {
          ContentTC = "我以為我們會一直是最好的同僚與伙伴，但變化總是發生得猝不及防。",
          DialogueId = 80160218,
          GUID = "C8AC35C4",
          NextDialogue = 80160219,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35C4"
        },
        [80160219] = {
          ContentTC = "不妨告訴你一個小秘密，我來這裡，是為了接收一個勾連神棄者同盟的內鬼。她害死了很多本不該失去生命的士兵，其中包括幾個跟隨我多年的下屬。",
          DialogueId = 80160219,
          GUID = "C8AC35EE",
          NextDialogue = 80160220,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35EE"
        },
        [80160220] = {
          ContentTC = "我本來打算親手將她掛上絞刑架，看著她對所有死去的人懺悔……",
          DialogueId = 80160220,
          GUID = "C8AC3618",
          NextOptions = {
            [1] = 801602201,
            [2] = 801602202
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3618"
        },
        [80160221] = {
          ContentTC = "我寧願她是為了海伯利亞而死，可惜，她成為了叛徒。",
          DialogueId = 80160221,
          GUID = "C8AC3642",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3642"
        },
        [80160222] = {
          ContentTC = "是的，她背叛了我",
          DialogueId = 80160222,
          GUID = "C8AC366C",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC366C"
        },
        [80160223] = {
          ContentTC = "不等你動手，這位不速之客就自己滿斟一杯，一飲而盡。",
          DialogueId = 80160223,
          GUID = "C8AC3696",
          IsBlack = 1,
          NextDialogue = 80160224,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3696"
        },
        [80160224] = {
          ContentTC = "呼……這酒比我想得更烈、更苦。苦到連即將到來的審判，都不那麼苦澀了。",
          DialogueId = 80160224,
          GUID = "C8AC36C0",
          NextOptions = {
            [1] = 801602241,
            [2] = 801602242
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36C0"
        },
        [80160225] = {
          ContentTC = "……不。我要做的事情沒有一絲一毫地改變，我只是……沒想好再次與她相見時，應該如何反駁她的「謬論」——",
          DialogueId = 80160225,
          GUID = "C8AC36EA",
          NextDialogue = 80160226,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36EA"
        },
        [80160226] = {
          ContentTC = "「長官，我早就對你，對這份工作深惡痛絕，喜歡在陰溝裡過著不見天日的生活是你的自由，而我，已經受夠這攤汙泥。向陽是人的本能，你這種怪物除外。」",
          DialogueId = 80160226,
          GUID = "C8AC3714",
          NextDialogue = 80160227,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3714"
        },
        [80160227] = {
          ContentTC = "當我回過神，這樣的爭吵已經發生過不只一次。今天的結局也許早就有所端倪，是我，被信任蒙住了眼睛。",
          DialogueId = 80160227,
          GUID = "C8AC373E",
          NextDialogue = 80160228,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC373E"
        },
        [80160228] = {
          ContentTC = "屆時，我應該對她報以指責，還是痛惜？我是站在什麼樣的立場上去審判她的，朋友，同僚，上司還是法官？",
          DialogueId = 80160228,
          GUID = "C8AC3768",
          NextDialogue = 80160229,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3768"
        },
        [80160229] = {
          ContentTC = "我只有一個晚上得出答案……",
          DialogueId = 80160229,
          GUID = "C8AC3792",
          NextDialogue = 80160230,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3792"
        },
        [80160230] = {
          ContentTC = "在此之前……先把你手上的酒再倒一杯給我。",
          DialogueId = 80160230,
          GUID = "C8AC37BC",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC37BC"
        },
        [80160301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "再来一杯。",
          DialogueId = 80160301,
          GUID = "C8AC4362",
          NextOptions = {
            [1] = 801603051,
            [2] = 801603052
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4362"
        },
        [80160306] = {
          ContentTC = "不要小看我，大部分酒精都會被我蒸發，能讓我喝醉的酒恐怕還沒有釀造出來。",
          DialogueId = 80160306,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC4434",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4434"
        },
        [80160307] = {
          ContentTC = "我付給你的報酬足夠你再買十瓶這樣的酒。",
          DialogueId = 80160307,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC445E",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC445E"
        },
        [80160308] = {
          ContentTC = "也許吧。",
          DialogueId = 80160308,
          FacialId = {
            [1] = "93201:Doubt01"
          },
          GUID = "C8AC4488",
          NextDialogue = 80160309,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4488"
        },
        [80160309] = {
          ContentTC = "你拿出了休憩之所所有的糖擺放在海爾法面前。",
          DialogueId = 80160309,
          GUID = "C8AC44B2",
          IsBlack = 1,
          NextOptions = {
            [1] = 801603091
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44B2"
        },
        [80160310] = {
          ContentTC = "我選這種。",
          DialogueId = 80160310,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC44DC",
          NextOptions = {
            [1] = 801603101
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44DC"
        },
        [80160311] = {
          ContentTC = "好事？呵……",
          DialogueId = 80160311,
          GUID = "C8AC4506",
          NextDialogue = 80160312,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4506"
        },
        [80160312] = {
          ContentTC = "紫露花蜜只會讓我想到一個調香的行家──也是不折不扣的罪犯。她會以紫露花為原料製作出讓人沉醉到永眠的香水，「命定之人」。",
          DialogueId = 80160312,
          GUID = "C8AC4530",
          NextOptions = {
            [1] = 801603121
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4530"
        },
        [80160313] = {
          ContentTC = "……不。",
          DialogueId = 80160313,
          GUID = "C8AC455A",
          NextDialogue = 80160314,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC455A"
        },
        [80160314] = {
          ContentTC = "她是個油嘴滑舌、詭計多端的小人，漂亮的腦袋裡只有她所謂的「愛情」，但如果把她當成傻瓜，就會變成一具身染劇毒的屍體。",
          DialogueId = 80160314,
          GUID = "C8AC4584",
          NextDialogue = 80160315,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4584"
        },
        [80160315] = {
          ContentTC = "「調香師麗蓓卡」－－在盧卡聲名遠揚，在帝國查無此人。",
          DialogueId = 80160315,
          GUID = "C8AC45AE",
          NextDialogue = 80160316,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45AE"
        },
        [80160316] = {
          ContentTC = "沒有人知道她為何離開故土，也沒有人知道她在何時混進了迪斯瑪尼亞，好像只是一夜之間，她就憑空出現了。",
          DialogueId = 80160316,
          GUID = "C8AC45D8",
          NextDialogue = 80160317,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45D8"
        },
        [80160317] = {
          ContentTC = "任何有可能威脅到帝都安全的因素都該被予以剷除，特別對方可能是一位強大的「骸」，於是，我思考她的來歷，猜測她到訪此地的目的——",
          DialogueId = 80160317,
          GUID = "C8AC4602",
          NextDialogue = 80160318,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4602"
        },
        [80160318] = {
          ContentTC = "超乎想像的是，我高估了她的野心，卻低估了她有多麼麻煩。",
          DialogueId = 80160318,
          GUID = "C8AC462C",
          NextDialogue = 80160319,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC462C"
        },
        [80160319] = {
          ContentTC = "她不想偷走帝都銀行裡的所有錢，也不想在遊行時暗殺皇帝。至於要塞的城防圖，密探九死一生傳遞出的絕密信件，在她眼裡都只是計算香料比例時要用到的草稿紙。",
          DialogueId = 80160319,
          GUID = "C8AC4656",
          NextDialogue = 80160320,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4656"
        },
        [80160320] = {
          ContentTC = "「調香師麗蓓卡」只有一個簡單得可笑的目的，找到最適合她的戀人——但她會為實現願望不擇手段，竭盡全力。",
          DialogueId = 80160320,
          GUID = "C8AC4680",
          NextDialogue = 80160321,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4680"
        }
      }
    end
  },
  {
    MinKey = 80160321,
    MaxKey = 80170322,
    Loader = function()
      return {
        [80160321] = {
          ContentTC = "對於潛藏於迪斯瑪尼亞暗處的蟲豸來說，這是一枚多麼好用的棋子啊——一個來自異鄉，用毒手段高明，最重要的是，還很好「哄騙」的骸。",
          DialogueId = 80160321,
          GUID = "C8AC46AA",
          NextDialogue = 80160322,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46AA"
        },
        [80160322] = {
          ContentTC = "理所當然的，她被捲進了陰謀的漩渦，在被利用著殺死了幾個滿嘴輕佻言語的權貴後，又替幕後主使做了替罪羊，被投入了監獄。",
          DialogueId = 80160322,
          GUID = "C8AC46D4",
          NextDialogue = 80160323,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46D4"
        },
        [80160323] = {
          ContentTC = "而我，則領命調查出這一切的真相。",
          DialogueId = 80160323,
          GUID = "C8AC46FE",
          NextDialogue = 80160324,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46FE"
        },
        [80160324] = {
          ContentTC = "我在審問時告訴她，根據海伯利亞法典，她將被處以長達五十年的監禁。如果她願意配合我，我將為她申請十年減刑。",
          DialogueId = 80160324,
          GUID = "C8AC4728",
          NextOptions = {
            [1] = 801603241
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4728"
        },
        [80160325] = {
          ContentTC = "我甚至沒來得及把這句畫說完，她就迫不及待地答應了我。",
          DialogueId = 80160325,
          GUID = "C8AC4752",
          NextOptions = {
            [1] = 801603251,
            [2] = 801603252
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4752"
        },
        [80160326] = {
          ContentTC = "幾乎沒有罪徒和她一樣，為了案件的調查如此配合，就像她是在實現自己的願望一樣……不擇手段，竭盡全力。",
          DialogueId = 80160326,
          GUID = "C8AC477C",
          NextDialogue = 80160327,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC477C"
        },
        [80160327] = {
          ContentTC = "我只能認為這是被人利用後的報復行為，但她卻否定了這一點。",
          DialogueId = 80160327,
          GUID = "C8AC47A6",
          NextDialogue = 80160328,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47A6"
        },
        [80160328] = {
          ContentTC = "她說，「調香師的嗅覺可是很靈敏的，而我在你身上……聞到了同類的味道。」",
          DialogueId = 80160328,
          GUID = "C8AC47D0",
          NextOptions = {
            [1] = 801603281,
            [2] = 801603282
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47D0"
        },
        [80160329] = {
          ContentTC = "如你所說，查清真相後，我們遭遇了幕後主使的攻擊，重傷後，我失去了行動能力。",
          DialogueId = 80160329,
          GUID = "C8AC47FA",
          NextDialogue = 80160330,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47FA"
        },
        [80160330] = {
          ContentTC = "她沒有逃跑，也沒有趁機殺死我，反而為我做了急救。但在我不肯失去意識時，對我噴了一泵香水，那正是她的成名之作——「命定之人」。",
          DialogueId = 80160330,
          GUID = "C8AC4824",
          NextDialogue = 80160331,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4824"
        },
        [80160331] = {
          ContentTC = "那個由紫露花香氣建構的夢，自此找上了我。",
          DialogueId = 80160331,
          GUID = "C8AC484E",
          NextDialogue = 80160332,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC484E"
        },
        [80160332] = {
          ContentTC = "……",
          DialogueId = 80160332,
          GUID = "C8AC4878",
          NextDialogue = 80160333,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4878"
        },
        [80160333] = {
          ContentTC = "你是否想過，如果某個特定的「意外」沒有發生，你的生活會是什麼樣子？",
          DialogueId = 80160333,
          GUID = "C8AC48A2",
          NextDialogue = 80160334,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48A2"
        },
        [80160334] = {
          ContentTC = "在那場夢裡……我沒有變成紅皮膚的骸，血親也沒有把我當作聖人膜拜，母親的手指依然能撫過我的臉頰。",
          DialogueId = 80160334,
          GUID = "C8AC48CC",
          NextDialogue = 80160335,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48CC"
        },
        [80160335] = {
          ContentTC = "我久違地回憶起──啊，原來我擁有過如此白皙的雙手。",
          DialogueId = 80160335,
          GUID = "C8AC48F6",
          NextDialogue = 80160336,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48F6"
        },
        [80160336] = {
          ContentTC = "我是個普通的卡戎，沒有斷角，沒有人被我灼傷，不必因為熾熱的體溫而終年睡在地板上，無數罪證與文件自然的從我手中流過，絕無焚毀之虞……",
          DialogueId = 80160336,
          GUID = "C8AC4920",
          NextDialogue = 80160337,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4920"
        },
        [80160337] = {
          ContentTC = "我和我的父輩一樣，繼續履行著家族賦予的使命，這依然是一份行走在黑暗中的營生，但失去與先祖同樣天賦的我，反而被許多人圍繞著。",
          DialogueId = 80160337,
          GUID = "C8AC494A",
          NextDialogue = 80160338,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC494A"
        },
        [80160338] = {
          ContentTC = "起初，我仍能清醒面對這個過於「善良」的世界，這樣的生活只是一枚甜蜜的誘餌，心懷叵測的罪人正不知在打著什麼算盤。",
          DialogueId = 80160338,
          GUID = "C8AC4974",
          NextDialogue = 80160339,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4974"
        },
        [80160339] = {
          ContentTC = "然而平靜充實的日子循環往復……一年、兩年、三年……十年過去了，我所擔心的事情從未發生，這場夢境卻長得看不到終點。",
          DialogueId = 80160339,
          GUID = "C8AC499E",
          NextDialogue = 80160340,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC499E"
        },
        [80160340] = {
          ContentTC = "是的，這樣「幸福」的日子長得看不見終點。",
          DialogueId = 80160340,
          GUID = "C8AC49C8",
          NextDialogue = 80160341,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49C8"
        },
        [80160341] = {
          ContentTC = "這稱得上是一場漫長的拷問……忍受酷刑固然是一種苦痛，但拒絕已經到手的幸福更是一種剜心一般的折磨。",
          DialogueId = 80160341,
          GUID = "C8AC49F2",
          NextDialogue = 80160342,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49F2"
        },
        [80160342] = {
          ContentTC = "很不幸，我終究還是逐漸忘卻了這只是一個狡猾調香師為我調配的幻覺，我習慣並且接受了——這就是我本來的生活。",
          DialogueId = 80160342,
          GUID = "C8AC4A1C",
          NextDialogue = 80160343,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A1C"
        },
        [80160343] = {
          ContentTC = "是從什麼時候徹底屈服的呢？也許是在慶祝我生日的聚會上，我挨個打開了所有人的生日卡片——",
          DialogueId = 80160343,
          GUID = "C8AC4A46",
          NextDialogue = 80160344,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A46"
        },
        [80160344] = {
          ContentTC = "沒錯，直至今日，我仍清晰地記著每一張的內容……",
          DialogueId = 80160344,
          GUID = "C8AC4A70",
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A70"
        },
        [80160345] = {
          ContentTC = "「親愛的小雪球，真高興你長這麼大了！\n陛下的榮耀在上，\n長久以來，我一直擔心你過得並不快樂！\n小雪球，你總是日以繼夜的工作，\n生怕有一分鐘渡過得沒有意義，\n好像休息被寫入犯罪條例似的！\n可是身為你的母親，我只希望你能盡可能的去享受自己的人生。\n人生苦短，我們都只能活一次。\n對自己好一些，好嗎？ 」",
          DialogueId = 80160345,
          Duration = 30,
          GUID = "C8AC4A9A",
          IsBlack = 1,
          NextDialogue = 80160346,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A9A"
        },
        [80160346] = {
          ContentTC = "「長官，今年也辛苦您了，祝您生日快樂——\n好了，場面話就說到這裡。\n之後別再像陀螺一樣轉個不停了，\n以及，工作不是你逃避的理由與手段。\n說實話，我們認識快十年了，\n然而擅長搜證如我至今也沒弄清楚，\n你整天到底在擔憂什麼。\n記住，生活還沒有不幸到那個份上！\n別再患得患失，去享受下業餘生活，好嗎？\n——因為你也許不需要休息，但我，很需要！」",
          DialogueId = 80160346,
          Duration = 30,
          GUID = "C8AC4AC4",
          IsBlack = 1,
          NextDialogue = 80160347,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AC4"
        },
        [80160347] = {
          ContentTC = "「尊敬的典獄長女士，感謝您多年以來為海伯利亞的辛勤付出，\n對您報以真誠的敬意。\n祝您生日快樂，請盡情享受這值得紀念的每一分鐘吧，\n願您未來的每一天都充斥著如今日一般的喜悅。\n\n隨信附上您本年度的用餐補貼，加班補貼與體檢邀請函，請確認後簽收。」",
          DialogueId = 80160347,
          Duration = 30,
          GUID = "C8AC4AEE",
          IsBlack = 1,
          NextDialogue = 80160348,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AEE"
        },
        [80160348] = {
          ContentTC = "「親愛的典獄長女士：\n原諒我不能署上自己的名字，\n您只要知道我是個悄悄注視著您的仰慕者罷了~\n也許您已經不記得我了，但我一直記得您與壞人惡鬥的模樣……\n為了自己的理想、他人的期待，也許還有渺小的我（嘻嘻），\n燃燒一切的您簡直與您的名字一樣滾燙。\n祝您生日快樂！\n願您知曉，您非常值得你現在所擁有的一切。\n所以，請更心安理得地享受這份嘉獎與祝福吧。」",
          DialogueId = 80160348,
          Duration = 30,
          GUID = "C8AC4B18",
          IsBlack = 1,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B18"
        },
        [80160349] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "從那個晚上開始，我放棄去記得我原本的人生。",
          DialogueId = 80160349,
          GUID = "C8AC4B42",
          NextOptions = {
            [1] = 801603491,
            [2] = 801603492
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B42"
        },
        [80160350] = {
          ContentTC = "我在這場夢中渡過了一生，最後在親人、朋友、同僚的簇擁中死去──沒有比這更好的結局了。",
          DialogueId = 80160350,
          GUID = "C8AC4B6C",
          NextDialogue = 80160351,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B6C"
        },
        [80160351] = {
          ContentTC = "終其一生，沒有背叛，沒有意外，沒有死別，沒有遺憾。",
          DialogueId = 80160351,
          GUID = "C8AC4B96",
          NextDialogue = 80160352,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B96"
        },
        [80160352] = {
          ContentTC = "當我睜開眼睛，從夢裡的死亡中復生，等待我的只有火焚後的餘燼，身體的疼痛，以及充斥著腦海的茫然與混亂。",
          DialogueId = 80160352,
          GUID = "C8AC4BC0",
          NextDialogue = 80160353,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BC0"
        },
        [80160353] = {
          ContentTC = "我僅剩的力氣只夠舉起我的一隻手——",
          DialogueId = 80160353,
          GUID = "C8AC4BEA",
          NextDialogue = 80160354,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BEA"
        },
        [80160354] = {
          ContentTC = "我看到了沾滿灰燼與血漬的，不停發抖的，鮮紅的手，在那一瞬，我或許流了淚——她就是在那時毫不猶豫地握住了我的手。",
          DialogueId = 80160354,
          GUID = "C8AC4C14",
          NextDialogue = 80160355,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C14"
        },
        [80160355] = {
          ContentTC = "即使她的皮膚根本無法承受這樣的高溫，而我以為她早就逃之夭夭。",
          DialogueId = 80160355,
          GUID = "C8AC4C3E",
          NextDialogue = 80160356,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C3E"
        },
        [80160356] = {
          ContentTC = "是麗蓓卡。",
          DialogueId = 80160356,
          GUID = "C8AC4C68",
          NextOptions = {
            [1] = 801603561,
            [2] = 801603562
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C68"
        },
        [80160357] = {
          ContentTC = "她對甦醒的我說：「我們都是他人眼中的怪物，可即使是怪物，也有做美夢和實現美夢的權力。」",
          DialogueId = 80160357,
          GUID = "C8AC4C92",
          NextDialogue = 80160358,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C92"
        },
        [80160358] = {
          ContentTC = "我不想否定這句話。或許正因如此，我放走了她。",
          DialogueId = 80160358,
          GUID = "C8AC4CBC",
          NextDialogue = 80160359,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CBC"
        },
        [80160359] = {
          ContentTC = "我肩負著更重要的責任，如果放棄它，殘酷的命運將降臨在更多人的頭上。所以，我願意將我做夢的權力轉讓給她，僅此一次。",
          DialogueId = 80160359,
          GUID = "C8AC4CE6",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CE6"
        },
        [80160360] = {
          ContentTC = "她對甦醒的我說：「我們都是他人眼中的怪物，可即使是怪物，也有做美夢和實現美夢的權力。」",
          DialogueId = 80160360,
          GUID = "C8AC4D10",
          NextDialogue = 80160361,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D10"
        },
        [80160361] = {
          ContentTC = "現在的我，已經能夠辨出夢終究是一種空洞的滿足，可那時的我，卻沉浸在了「互為同類」的惺惺相惜中──最終，犯下了無法挽回的錯誤。",
          DialogueId = 80160361,
          GUID = "C8AC4D3A",
          NextDialogue = 80160362,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D3A"
        },
        [80160362] = {
          ContentTC = "但我不想用這樣的說辭欺騙自己，我承認自己心中的渴望，正視它正是為了永遠不再觸及它。",
          DialogueId = 80160362,
          GUID = "C8AC4D64",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D64"
        },
        [80160363] = {
          ContentTC = "我不會為我的罪行申辯，錯誤不會重複，下一次，我發誓要讓她為自己的罪行付出代價。",
          DialogueId = 80160363,
          GUID = "C8AC4D8E",
          NextDialogue = 80160364,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D8E"
        },
        [80160364] = {
          ContentTC = "但直至今日，紫露花的香氣依然能讓我在心浮氣躁時重歸平靜。",
          DialogueId = 80160364,
          GUID = "C8AC4DB8",
          NextDialogue = 80160365,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DB8"
        },
        [80160365] = {
          ContentTC = "也許我會在某一天徹底遺忘那個夢境，擺脫這座由「命定之人」鑄成的假象的監牢，但至少今天，我確實需要這份安寧。",
          DialogueId = 80160365,
          GUID = "C8AC4DE2",
          NextDialogue = 80160366,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DE2"
        },
        [80160366] = {
          ContentTC = "最後……",
          DialogueId = 80160366,
          GUID = "C8AC4E0C",
          NextDialogue = 80160367,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E0C"
        },
        [80160367] = {
          ContentTC = "這是她的通緝令，如果發現她的蹤跡，請立刻上報當地治安局。",
          DialogueId = 80160367,
          GUID = "C8AC4E36",
          NextOptions = {
            [1] = 801603671,
            [2] = 801603672
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E36"
        },
        [80160368] = {
          ContentTC = "請為我再調一杯酒吧，這次可以試著將紫露花蜜加進去嗎？",
          DialogueId = 80160368,
          GUID = "C8AC4E60",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E60"
        },
        [80160401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "謝謝你的招待。",
          DialogueId = 80160401,
          GUID = "C8AC53CA",
          NextDialogue = 80160402,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53CA"
        },
        [80160402] = {
          ContentTC = "我明白卡蜜拉對你的評價了，你是個很容易讓人對你放下戒備的人。耐心，洞察，理解……作為酒保，這都是最值得被讚譽的品德。",
          DialogueId = 80160402,
          GUID = "C8AC53F4",
          NextDialogue = 80160403,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53F4"
        },
        [80160403] = {
          ContentTC = "如果哪天你願意開個酒館，也許我會常來光顧。",
          DialogueId = 80160403,
          GUID = "C8AC541E",
          NextOptions = {
            [1] = 801604031
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC541E"
        },
        [80160404] = {
          ContentTC = "呵……朋友嗎。",
          DialogueId = 80160404,
          FacialId = {
            [1] = "93201:Smile01"
          },
          GUID = "C8AC5448",
          NextDialogue = 80160405,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5448"
        },
        [80160405] = {
          ContentTC = "也是，我不能這麼無止境地休息下去。喝完最後一杯酒，我也應該去見見老朋友了。",
          DialogueId = 80160405,
          GUID = "C8AC5472",
          NextOptions = {
            [1] = 801604051
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5472"
        },
        [80160406] = {
          ContentTC = "不需要，簡單一點就好。",
          DialogueId = 80160406,
          GUID = "C8AC549C",
          NextDialogue = 80160407,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC549C"
        },
        [80160407] = {
          ContentTC = "「不屈者」，口感尖銳，咽下去的時候像是吞了一把刀子，沖進胃裡的時候像是要在那裡點火——現在看來，這真是一瓶適合雪原與凍土的酒。",
          DialogueId = 80160407,
          GUID = "C8AC54C6",
          NextDialogue = 80160408,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54C6"
        },
        [80160408] = {
          ContentTC = "就是它了，不過得麻煩你再等一下。",
          DialogueId = 80160408,
          GUID = "C8AC54F0",
          NextDialogue = 80160409,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54F0"
        },
        [80160409] = {
          ContentTC = "海爾法小心翼翼的在盡可能不直接和酒杯接觸的情況下，裝滿了從簷上敲下的冰，然後讓你將「不屈者」倒滿。",
          DialogueId = 80160409,
          GUID = "C8AC551A",
          IsBlack = 1,
          NextDialogue = 80160410,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC551A"
        },
        [80160410] = {
          ContentTC = "冰塊很快開始融化，她迅速地一飲而盡，接著就是下一杯，下一杯，再下一杯……",
          DialogueId = 80160410,
          GUID = "C8AC5544",
          IsBlack = 1,
          NextDialogue = 80160411,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5544"
        },
        [80160411] = {
          ContentTC = "……",
          DialogueId = 80160411,
          FacialId = {
            [1] = "93201:Pain01"
          },
          GUID = "C8AC556E",
          NextDialogue = 80160412,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC556E"
        },
        [80160412] = {
          ContentTC = "…………",
          DialogueId = 80160412,
          GUID = "C8AC5598",
          NextOptions = {
            [1] = 801604121,
            [2] = 801604122
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5598"
        },
        [80160413] = {
          ContentTC = "不要大驚小怪，裝滿冰塊的杯子裡能有多少酒。",
          DialogueId = 80160413,
          FacialId = {
            [1] = "93201:Confident01"
          },
          GUID = "C8AC55C2",
          NextDialogue = 80160414,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55C2"
        },
        [80160414] = {
          ContentTC = "我只是遺憾冰塊在我手上化的太快，即使盡量挽留，也會變成蒸氣和酒精一起揮發。",
          DialogueId = 80160414,
          GUID = "C8AC55EC",
          NextDialogue = 80160415,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55EC"
        },
        [80160415] = {
          ContentTC = "我不喜歡冗長精緻的修辭，但堅冰融水與理想的消亡實在是太過相似。",
          DialogueId = 80160415,
          GUID = "C8AC5616",
          NextDialogue = 80160416,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5616"
        },
        [80160416] = {
          ContentTC = "讓我想起很多年以前……當我還沒有覺醒，角也沒有被折斷，我的朋友也沒有背叛我的時候——我們一群年輕人剛剛走出學校，憧憬著未來與理想。",
          DialogueId = 80160416,
          GUID = "C8AC5640",
          NextDialogue = 80160417,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5640"
        },
        [80160417] = {
          ContentTC = "我們喝著最便宜的烈酒，同僚們吶喊的祝酒詞，比杯子與杯子的碰撞聲更加震耳欲聾。",
          DialogueId = 80160417,
          GUID = "C8AC566A",
          NextDialogue = 80160418,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC566A"
        },
        [80160418] = {
          ContentTC = "所有人的臉龐漲成了同樣的紅色，入職時熾熱的宣誓被重複了一遍又一遍。",
          DialogueId = 80160418,
          GUID = "C8AC5694",
          NextDialogue = 80160419,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5694"
        },
        [80160419] = {
          ContentTC = "「為海伯利亞的正義而戰鬥，為海伯利亞的光明而燃燒，為海伯利亞的屹立而堅守。」",
          DialogueId = 80160419,
          GUID = "C8AC56BE",
          NextDialogue = 80160420,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56BE"
        },
        [80160420] = {
          ContentTC = "「以『不屈者』向不屈者致敬」。",
          DialogueId = 80160420,
          GUID = "C8AC56E8",
          NextDialogue = 80160421,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56E8"
        },
        [80160421] = {
          ContentTC = "當時的同僚們已經不剩幾個，我和那位名為艾爾汀的友人，是唯二活到今天的人。",
          DialogueId = 80160421,
          FacialId = {
            [1] = "93201:Sad01"
          },
          GUID = "C8AC5712",
          NextDialogue = 80160422,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5712"
        },
        [80160422] = {
          ContentTC = "但過不了多久，她也許就會離開這個世界。",
          DialogueId = 80160422,
          GUID = "C8AC573C",
          NextOptions = {
            [1] = 801604221
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC573C"
        },
        [80160423] = {
          ContentTC = "……",
          DialogueId = 80160423,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC5766",
          NextDialogue = 80160424,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5766"
        },
        [80160424] = {
          ContentTC = "同樣的錯誤我不會犯第二次。",
          DialogueId = 80160424,
          GUID = "C8AC5790",
          NextDialogue = 80160425,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5790"
        },
        [80160425] = {
          ContentTC = "我們從同僚變成上下級，又變成了判官和罪人，或許我們都被歲月改變，但我將竭盡所能地遵守我當初許下的誓言。",
          DialogueId = 80160425,
          GUID = "C8AC57BA",
          NextDialogue = 80160426,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57BA"
        },
        [80160426] = {
          ContentTC = "就算這條路上只剩下我一個人。",
          DialogueId = 80160426,
          GUID = "C8AC57E4",
          NextOptions = {
            [1] = 801604261
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57E4"
        },
        [80160427] = {
          ContentTC = "什麼都不用說。",
          DialogueId = 80160427,
          GUID = "C8AC580E",
          NextDialogue = 80160428,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC580E"
        },
        [80160428] = {
          ContentTC = "值得我尊敬的同僚是當年的「不屈者」，而我對罪人的態度永遠只有一個。",
          DialogueId = 80160428,
          GUID = "C8AC5838",
          NextDialogue = 80160429,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5838"
        },
        [80160429] = {
          ContentTC = "海爾法將杯子裡的冰塊融水一飲而盡。",
          DialogueId = 80160429,
          GUID = "C8AC5862",
          IsBlack = 1,
          NextDialogue = 80160430,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5862"
        },
        [80160430] = {
          ContentTC = "不管面對的罪犯來自煉金院還是什麼皇家軍事學院，是敵人還是朋友，我都會一視同仁。",
          DialogueId = 80160430,
          GUID = "C8AC588C",
          NextDialogue = 80160431,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC588C"
        },
        [80160431] = {
          ContentTC = "這才是一名皇家監獄典獄長所應有的，也是唯一的做法。",
          DialogueId = 80160431,
          GUID = "C8AC58B6",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC58B6"
        },
        [80170001] = {
          ContentTC = "孩子，如果累了，就坐下休息一會吧。",
          DialogueId = 80170001,
          GUID = "C8B27ACA",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B27ACA"
        },
        [80170101] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "多謝你邀請我，孩子。我已經很久沒有像這樣和朋友坐在一起聊天了，甚是懷念。",
          DialogueId = 80170101,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28B32",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextDialogue = 80170102,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B32"
        },
        [80170102] = {
          ContentTC = "「很久」？有多久？",
          DialogueId = 80170102,
          GUID = "C8B28B5C",
          NextDialogue = 80170103,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B5C"
        },
        [80170103] = {
          ContentTC = "嗯。大概有十多年了吧。再往前……可能有幾百年了？",
          DialogueId = 80170103,
          GUID = "C8B28B86",
          NextDialogue = 80170104,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B86"
        },
        [80170104] = {
          ContentTC = "啊……?",
          DialogueId = 80170104,
          GUID = "C8B28BB0",
          NextDialogue = 80170105,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BB0"
        },
        [80170105] = {
          ContentTC = "呵呵，嚇到你了嗎？其實，我的歲數比你我腳下的這片土地——海伯利亞帝國還要長一些。",
          DialogueId = 80170105,
          GUID = "C8B28BDA",
          NextOptions = {
            [1] = 801701051,
            [2] = 801701052
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BDA"
        },
        [80170106] = {
          ContentTC = "「骸」的魔法千差萬別，多是先天異能或經由血脈傳承，只怕無法傳授於人。",
          DialogueId = 80170106,
          GUID = "C8B28C04",
          NextDialogue = 80170107,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C04"
        },
        [80170107] = {
          ContentTC = "沒關係，隨口一說。認真來說……",
          DialogueId = 80170107,
          GUID = "C8B28C2E",
          NextDialogue = 80170108,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C2E"
        },
        [80170108] = {
          ContentTC = "沒想到妮弗爾夫人是這麼年長的長輩……非常榮幸能和您交談。",
          DialogueId = 80170108,
          GUID = "C8B28C58",
          NextDialogue = 80170109,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C58"
        },
        [80170109] = {
          ContentTC = "不必如此鄭重，你就當是在和普通朋友聊天便好。",
          DialogueId = 80170109,
          GUID = "C8B28C82",
          NextDialogue = 80170110,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C82"
        },
        [80170110] = {
          ContentTC = "不過，你想和我聊些什麼呢？我早已遠離俗世，怕是沒法接上當下時髦的話題，但你若是對遠方、對過去有幾分興趣，我倒是有不少故事可講。",
          DialogueId = 80170110,
          GUID = "C8B28CAC",
          NextOptions = {
            [1] = 801701101
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CAC"
        },
        [80170111] = {
          ContentTC = "我記得您說過，你是一位「霧海引渡人」。不過，我還沒搞太清楚那究竟是什麼。",
          DialogueId = 80170111,
          GUID = "C8B28CD6",
          NextDialogue = 80170112,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CD6"
        },
        [80170112] = {
          ContentTC = "嗯……興許你聽說過卡戎之民的神話。",
          DialogueId = 80170112,
          GUID = "C8B28D00",
          NextDialogue = 80170113,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D00"
        },
        [80170113] = {
          ContentTC = "最初，天地是混沌的霧海，自那霧海中誕生聖樹，聖樹綻放純白的花。白花孕育了我們的祖先－－最初的生命女神茵布拉，女神又創造萬物。",
          DialogueId = 80170113,
          GUID = "C8B28D2A",
          NextDialogue = 80170114,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D2A"
        },
        [80170114] = {
          ContentTC = "一切有生之物都來自霧海，在喚作「塵世」的河流中漂泊一遭後，又將歸於霧海。",
          DialogueId = 80170114,
          GUID = "C8B28D54",
          NextDialogue = 80170115,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D54"
        },
        [80170115] = {
          ContentTC = "而引渡人的職責則是指引迷失方向的亡魂回歸霧海。所以，大多數時候，我都在傾聽亡者的聲音，與它們耳語。",
          DialogueId = 80170115,
          GUID = "C8B28D7E",
          NextDialogue = 80170116,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D7E"
        },
        [80170116] = {
          ContentTC = "聽來有些可怕。",
          DialogueId = 80170116,
          GUID = "C8B28DA8",
          NextDialogue = 80170117,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DA8"
        },
        [80170117] = {
          ContentTC = "呵呵，的確。在大多數人看來，死亡是一件極其可怕的事。",
          DialogueId = 80170117,
          GUID = "C8B28DD2",
          NextOptions = {
            [1] = 801701171
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DD2"
        },
        [80170118] = {
          ContentTC = "嗯……正好，既然說到了這個話題，我就跟你講一個關於「死亡」的故事吧。這是一個少女和她重病的妹妹的故事。",
          DialogueId = 80170118,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B28DFC",
          NextDialogue = 80170119,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DFC"
        },
        [80170119] = {
          ContentTC = "少女和妹妹是生在艾利西安的窮人，從小失去雙親，兩人相依為命，頑強地熬過了飢餓和寒冷。不幸的是，妹妹在某年的寒冬染上了不治之症。",
          DialogueId = 80170119,
          GUID = "C8B28E26",
          NextDialogue = 80170120,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E26"
        },
        [80170120] = {
          ContentTC = "那位少女為了救自己的妹妹四處求醫問藥，遍尋無果的絕望之際，卻從一個老人那裡打聽到了有關「黃金之血」的傳說。",
          DialogueId = 80170120,
          GUID = "C8B28E50",
          NextDialogue = 80170121,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E50"
        },
        [80170121] = {
          ContentTC = "相傳艾利西安貴族曾經供奉過一位受神賜福的女人，她的血液能夠治癒頑疾，永葆青春，因而珍貴異常，如同流動的黃金。",
          DialogueId = 80170121,
          GUID = "C8B28E7A",
          NextDialogue = 80170122,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E7A"
        },
        [80170122] = {
          ContentTC = "無數貴人獻上數不清的真正黃金，來換一小瓶救命的血液。但是，戰爭很快就降臨了艾利西安。在「大遷徙」中，女人被反抗軍擄走，從此下落不明。",
          DialogueId = 80170122,
          GUID = "C8B28EA4",
          NextDialogue = 80170123,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EA4"
        },
        [80170123] = {
          ContentTC = "為了拯救妹妹，少女憑著超乎常人的耐心四處尋訪，她驚喜地發現，當年的那個女人竟然還活著，如今已年逾百歲的她如今就住在深林之國——伊瑟爾。",
          DialogueId = 80170123,
          GUID = "C8B28ECE",
          NextDialogue = 80170124,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28ECE"
        },
        [80170124] = {
          ContentTC = "於是，她帶著重病的妹妹跋山涉水，找到了那個被賜福的女人。抱著已然奄奄一息的妹妹，少女流著淚求女人分給他一點奇蹟。",
          DialogueId = 80170124,
          GUID = "C8B28EF8",
          NextDialogue = 80170125,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EF8"
        },
        [80170125] = {
          ContentTC = "然而，「受神賜福的黃金之血」不過是貪婪的貴族粉飾惡行的謊言。事實上，女人當年是因為療癒的魔法而遭到囚禁，歷盡千辛萬苦才終於逃離艾利西安。",
          DialogueId = 80170125,
          GUID = "C8B28F22",
          NextDialogue = 80170126,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F22"
        },
        [80170126] = {
          ContentTC = "她早就決定此生不再動用自己的療癒能力，以免再生事端。",
          DialogueId = 80170126,
          GUID = "C8B28F4C",
          NextDialogue = 80170127,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F4C"
        },
        [80170127] = {
          ContentTC = "女孩的努力落得了一場空嗎……",
          DialogueId = 80170127,
          GUID = "C8B28F76",
          NextDialogue = 80170128,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F76"
        },
        [80170128] = {
          ContentTC = "不，不對。既然你特地講出來，這個故事肯定還沒結束吧？",
          DialogueId = 80170128,
          GUID = "C8B28FA0",
          NextDialogue = 80170129,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FA0"
        },
        [80170129] = {
          ContentTC = "呵呵，你猜得沒錯──女人最後答應了少女的請求。",
          DialogueId = 80170129,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28FCA",
          NextDialogue = 80170130,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FCA"
        },
        [80170130] = {
          ContentTC = "為什麼？",
          DialogueId = 80170130,
          GUID = "C8B28FF4",
          NextDialogue = 80170131,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FF4"
        },
        [80170131] = {
          ContentTC = "因為，女人其實並不是完全沒動過治癒別人的心思——她曾經兩度試圖用自己的血延續別人的生命，一次是她最好的朋友，一次是她的女兒。",
          DialogueId = 80170131,
          GUID = "C8B2901E",
          NextDialogue = 80170132,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2901E"
        },
        [80170132] = {
          ContentTC = "她的朋友是一位英勇的戰士，在戰場上受了致命傷。她的女兒是一位德高望重的學者，安然地迎來了壽命的重點。",
          DialogueId = 80170132,
          GUID = "C8B29048",
          NextDialogue = 80170133,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29048"
        },
        [80170133] = {
          ContentTC = "雖然臨終的情形大不相同，但相同的是，兩人都堅定地拒絕了用女人的血延續生命，表示不願意這種方式活下去。",
          DialogueId = 80170133,
          GUID = "C8B29072",
          NextDialogue = 80170134,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29072"
        },
        [80170134] = {
          ContentTC = "那位姊姊悲痛而不甘的神情讓女人想起了過去的自己，於是她的內心動搖了。她想起了橫亙在自己心頭多年的疑惑與遺憾——",
          DialogueId = 80170134,
          GUID = "C8B2909C",
          NextDialogue = 80170135,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2909C"
        },
        [80170135] = {
          ContentTC = "如果自己救下了朋友和女兒，會怎麼樣？自己沒能選擇的那條道路，究竟通往怎樣的終點？",
          DialogueId = 80170135,
          GUID = "C8B290C6",
          NextDialogue = 80170136,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290C6"
        },
        [80170136] = {
          ContentTC = "她想知道答案。於是，她割開手臂，將自己的血液贈予了那對姊妹。",
          DialogueId = 80170136,
          GUID = "C8B290F0",
          NextDialogue = 80170137,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290F0"
        },
        [80170137] = {
          ContentTC = "重病的妹妹喝下「黃金之血」後，很快便恢復了意識。",
          DialogueId = 80170137,
          GUID = "C8B2911A",
          NextOptions = {
            [1] = 801701371,
            [2] = 801701372
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2911A"
        },
        [80170138] = {
          ContentTC = "你是個善良的孩子……可是，所謂「黃金之血」的奇蹟只是人們一廂情願的幻想而已。",
          DialogueId = 80170138,
          GUID = "C8B29144",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29144"
        },
        [80170139] = {
          ContentTC = "是啊。所謂「黃金之血」的奇蹟只是人們一廂情願的幻想而已。",
          DialogueId = 80170139,
          GUID = "C8B2916E",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2916E"
        },
        [80170140] = {
          ContentTC = "女人的血液確實擁有特殊的力量，但喝下它並不能真正治癒疾病或延緩衰老，只能將生命維持在「存活」的狀態。",
          DialogueId = 80170140,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29198",
          NextDialogue = 80170141,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29198"
        },
        [80170141] = {
          ContentTC = "像是被琥珀封存的昆蟲－－不會腐朽，卻也很難說是「活著」。",
          DialogueId = 80170141,
          GUID = "C8B291C2",
          NextDialogue = 80170142,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291C2"
        },
        [80170142] = {
          ContentTC = "所以，喝下血液之後，妹妹雖然沒有死去，身體卻依舊病入膏肓。",
          DialogueId = 80170142,
          GUID = "C8B291EC",
          NextDialogue = 80170143,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291EC"
        },
        [80170143] = {
          ContentTC = "她只能終日臥於病榻之上，連喝水都要費盡力氣。她嘗不出食物的味道、看不清書上的文字、聽不清姐姐呼喚她的聲音。",
          DialogueId = 80170143,
          GUID = "C8B29216",
          NextDialogue = 80170144,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29216"
        },
        [80170144] = {
          ContentTC = "姐姐為了能隨時照顧妹妹，只能找些工時靈活的零工。但為了賺到足夠維持兩人生活的錢，他又必須選擇那些最苦、最累，別人不願意幹的活。",
          DialogueId = 80170144,
          GUID = "C8B29240",
          NextDialogue = 80170145,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29240"
        },
        [80170145] = {
          ContentTC = "她確實有著堅強的意志，苦心竭力地守護著這份來之不易的「奇蹟」，但她孱弱的身體還是承受不住這樣持續的辛勞，幾乎每天都在倒下的邊緣掙扎。",
          DialogueId = 80170145,
          GUID = "C8B2926A",
          NextOptions = {
            [1] = 801701451
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2926A"
        },
        [80170146] = {
          ContentTC = "後來，那位妹妹自己結束了生命。她用僅剩的力氣，把姐姐又一次求來的那一小瓶「奇蹟」推到地上，打碎了。",
          DialogueId = 80170146,
          GUID = "C8B29294",
          NextDialogue = 80170147,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29294"
        },
        [80170147] = {
          ContentTC = "大概她終於意識到，這所謂的「奇蹟」，無論對姐姐，還是對她自己而言，都只是一具沉重的枷鎖。",
          DialogueId = 80170147,
          GUID = "C8B292BE",
          NextDialogue = 80170148,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292BE"
        },
        [80170148] = {
          ContentTC = "那時，是我將那個女孩送往了霧海。你猜猜她的靈魂對我說了什麼?",
          DialogueId = 80170148,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B292E8",
          NextDialogue = 80170149,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292E8"
        },
        [80170149] = {
          ContentTC = "看你的表情，她應該說了很溫柔的話吧，例如「謝謝」？",
          DialogueId = 80170149,
          GUID = "C8B29312",
          NextDialogue = 80170150,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29312"
        },
        [80170150] = {
          ContentTC = "……你這麼聰明，倒顯得我故弄玄虛了。你猜得沒錯。",
          DialogueId = 80170150,
          GUID = "C8B2933C",
          NextDialogue = 80170151,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2933C"
        },
        [80170151] = {
          ContentTC = "她說，她很感謝姐姐，也很感謝那個女人。雖然經歷了痛苦的末路，但也正因如此，她能夠坦然接受自己的離去。",
          DialogueId = 80170151,
          GUID = "C8B29366",
          NextDialogue = 80170152,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29366"
        },
        [80170152] = {
          ContentTC = "聽到這些，少女先是哭著說了許多的「對不起」，但最後，她也對著妹妹漂流而去的骨灰匣，說了一句「謝謝」。",
          DialogueId = 80170152,
          GUID = "C8B29390",
          NextDialogue = 80170153,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29390"
        },
        [80170153] = {
          ContentTC = "少女後來在伊瑟爾定居，成了一位優秀的醫生。在組建了自己的家庭之後，她還去拜訪了那個女人，告訴她自己現在已經過上了幸福的生活。",
          DialogueId = 80170153,
          GUID = "C8B293BA",
          NextDialogue = 80170154,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293BA"
        },
        [80170154] = {
          ContentTC = "這時，女人終於明白，為何當年她的友人和女兒不願意讓她「救」自己——",
          DialogueId = 80170154,
          GUID = "C8B293E4",
          NextDialogue = 80170155,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293E4"
        },
        [80170155] = {
          ContentTC = "死亡對於生命而言，並不總是一位惡客。有時，它也是溫柔的。就像植物開始結果時凋零的花瓣一般，終點是為了新的開始。",
          DialogueId = 80170155,
          GUID = "C8B2940E",
          NextDialogue = 80170156,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2940E"
        },
        [80170156] = {
          ContentTC = "如果執意與死亡對抗，反而會讓人止步不前，錯過生的美好。",
          DialogueId = 80170156,
          GUID = "C8B29438",
          NextOptions = {
            [1] = 801701561,
            [2] = 801701562
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29438"
        },
        [80170157] = {
          ContentTC = "這是個堅韌的回答。",
          DialogueId = 80170157,
          GUID = "C8B29462",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29462"
        },
        [80170158] = {
          ContentTC = "這是個勇敢的回答。",
          DialogueId = 80170158,
          GUID = "C8B2948C",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2948C"
        },
        [80170159] = {
          ContentTC = "不過，這個故事所傳達的，終究只是那個女人的一己之見而已，不必太過在意。你大可以去尋找自己的答案。",
          DialogueId = 80170159,
          GUID = "C8B294B6",
          NextDialogue = 80170160,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294B6"
        },
        [80170160] = {
          ContentTC = "我相信，無論你的選擇為何，只要能夠保持清醒、不被虛假之物羈絆，便終會找到正確的道路。",
          DialogueId = 80170160,
          GUID = "C8B294E0",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294E0"
        },
        [80170201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "你好，孩子。你看上去似乎有些疲憊？",
          DialogueId = 80170201,
          GUID = "C8B29B9A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801702011,
            [2] = 801702012
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29B9A"
        },
        [80170202] = {
          ContentTC = "自從離開家鄉以後，我經歷過很多事，其中許多充滿遺憾。有時我會覺得很無力，似乎很多努力都是徒勞。",
          DialogueId = 80170202,
          GUID = "C8B29BC4",
          NextDialogue = 80170203,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BC4"
        },
        [80170203] = {
          ContentTC = "妮弗爾夫人身為長輩，有什麼建議嗎？",
          DialogueId = 80170203,
          GUID = "C8B29BEE",
          NextDialogue = 80170204,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BEE"
        },
        [80170204] = {
          ContentTC = "是嗎……那麼，就讓我再給你講個故事吧。",
          DialogueId = 80170204,
          GUID = "C8B29C18",
          NextDialogue = 80170205,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C18"
        },
        [80170205] = {
          ContentTC = "這是一位青年和一位少女的故事，一個關於希望、勇氣和未來的故事。",
          DialogueId = 80170205,
          GUID = "C8B29C42",
          NextDialogue = 80170206,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C42"
        },
        [80170206] = {
          ContentTC = "故事發生在千年之前，那時這片大陸上只有艾利西安一個國家。他們兩人一個是平民，一個是貴族。",
          DialogueId = 80170206,
          GUID = "C8B29C6C",
          NextDialogue = 80170207,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C6C"
        },
        [80170207] = {
          ContentTC = "出身平民的青年從小就喜歡讀書，尤其喜愛研究歷史和神話，年紀輕輕便擁有了淵博的學識，人人都期待他能成長為一位優秀的學者。",
          DialogueId = 80170207,
          GUID = "C8B29C96",
          NextDialogue = 80170208,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C96"
        },
        [80170208] = {
          ContentTC = "但青年讀得越多、懂得越多、思考得越多，就越是意識到，他目之所及的土地上，播種著太多錯誤。那些人們習以為常的東西，卻不都是對的。",
          DialogueId = 80170208,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29CC0",
          NextDialogue = 80170209,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CC0"
        },
        [80170209] = {
          ContentTC = "平民們辛勤勞作也難得溫飽，修士的桌上卻永遠擺著吃不完的美酒佳餚。祝福的讚美詩中，充斥著被當成異端處決的無辜者在絞刑架下的哭號。",
          DialogueId = 80170209,
          GUID = "C8B29CEA",
          NextDialogue = 80170210,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CEA"
        },
        [80170210] = {
          ContentTC = "——當然，哭泣的，還有一位據說擁有「黃金之血」的少女。",
          DialogueId = 80170210,
          GUID = "C8B29D14",
          NextDialogue = 80170211,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D14"
        },
        [80170211] = {
          ContentTC = "白天，她顫抖著割開手臂，向前來頂禮膜拜的人賜予自己的血；晚上，她蜷縮在囚牢裡，一邊因疼痛而哭泣，一邊向神明祈禱著垂憐。",
          DialogueId = 80170211,
          GUID = "C8B29D3E",
          NextDialogue = 80170212,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D3E"
        },
        [80170212] = {
          ContentTC = "有一天，年輕的學者冒險闖入聖堂，對著前來求取「黃金之血」的人們發表了一番激昂的演說。然而，回應他的卻只有衛兵的長槍。",
          DialogueId = 80170212,
          GUID = "C8B29D68",
          NextDialogue = 80170213,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D68"
        },
        [80170213] = {
          ContentTC = "他被關進了陰冷的監牢，並在偶然的機緣巧合下，遇見了故事的另一位主角——陪同父親前來視察的貴族少女。",
          DialogueId = 80170213,
          GUID = "C8B29D92",
          NextDialogue = 80170214,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D92"
        },
        [80170214] = {
          ContentTC = "少女喜歡騎馬、練武，英姿颯爽。她有一顆善良的心，對與自己同齡卻誤入歧途的青年感到憐惜，便私下前去勸說對方認罪以減輕刑罰。",
          DialogueId = 80170214,
          GUID = "C8B29DBC",
          NextDialogue = 80170215,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DBC"
        },
        [80170215] = {
          ContentTC = "可是青年不僅宣稱自己無罪，還反過來勸貴族少女儘早醒悟。",
          DialogueId = 80170215,
          GUID = "C8B29DE6",
          NextDialogue = 80170216,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DE6"
        },
        [80170216] = {
          ContentTC = "他告訴少女，人們膜拜的，擁有「黃金之血」的女孩，實際上只是被一位大貴族──也就是貴族少女的父親，囚禁起來斂財的可憐人。",
          DialogueId = 80170216,
          GUID = "C8B29E10",
          NextDialogue = 80170217,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E10"
        },
        [80170217] = {
          ContentTC = "聽了青年的話，貴族少女最初的反應當然是不信，甚至覺得荒謬。但青年慷慨陳詞時那雙熠熠生輝的眼眸，卻始終在她的腦海中盤旋不去。",
          DialogueId = 80170217,
          GUID = "C8B29E3A",
          NextDialogue = 80170218,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E3A"
        },
        [80170218] = {
          ContentTC = "那目光不像是在說謊。於是，貴族少女踏出了探求的第一步。她從父親那裡偷來鑰匙，打開聖堂深處的房間，找到了那個蒼白瘦弱、鎖鏈纏身的女孩。",
          DialogueId = 80170218,
          GUID = "C8B29E64",
          NextDialogue = 80170219,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E64"
        },
        [80170219] = {
          ContentTC = "發現真相之後，少女回到監牢，再次站在青年面前。看到她與先前判若兩人的沉重神情，青年明白她已經做好了準備，便向她講述了貴族的更多罪行。",
          DialogueId = 80170219,
          GUID = "C8B29E8E",
          NextDialogue = 80170220,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E8E"
        },
        [80170220] = {
          ContentTC = "青年的話像一把利刃割開了少女生活其中的精美畫布，暴露出背後血淋淋的真實。在那之後，少女終於開始看見那些她不曾看過的暗角。",
          DialogueId = 80170220,
          GUID = "C8B29EB8",
          NextDialogue = 80170221,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EB8"
        },
        [80170221] = {
          ContentTC = "她將自己的發現告訴了父親，希望父親能夠釋放青年，可等待她的卻是軟禁和監視——她這才明白，自己的父親從頭到尾都是苦難的幫兇。",
          DialogueId = 80170221,
          GUID = "C8B29EE2",
          NextOptions = {
            [1] = 801702211,
            [2] = 801702212
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EE2"
        },
        [80170222] = {
          ContentTC = "是啊──他們也曾哀嘆過自身的無力，也曾如你一般疲憊不堪，懷疑抗爭究竟有何意義。但是，他們還是選擇了堅持下去。",
          DialogueId = 80170222,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B29F0C",
          NextDialogue = 80170223,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F0C"
        },
        [80170223] = {
          ContentTC = "即便在牢獄中，青年依舊日夜推演著自己的學說，試圖描繪一幅正義與自由的新世界圖景。",
          DialogueId = 80170223,
          GUID = "C8B29F36",
          NextDialogue = 80170224,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F36"
        },
        [80170224] = {
          ContentTC = "即便孤立無援，少女依然拒絕紙醉金迷的誘惑，想方設法地接濟下層民眾，並從中尋找志同道合的伙伴。",
          DialogueId = 80170224,
          GUID = "C8B29F60",
          NextDialogue = 80170225,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F60"
        },
        [80170225] = {
          ContentTC = "他們的努力最初看上去只是蝴蝶振翅，最終卻掀起了一道颶風，在艾利西安堅不可摧的外殼上撕開一道裂痕。",
          DialogueId = 80170225,
          GUID = "C8B29F8A",
          NextDialogue = 80170226,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F8A"
        },
        [80170226] = {
          ContentTC = "他們兩人便是那場永垂青史的「大遷徙」事件的領導者。他們建立起一支反抗軍，帶領被壓迫的底層人民離開了艾利西安。",
          DialogueId = 80170226,
          GUID = "C8B29FB4",
          NextDialogue = 80170227,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FB4"
        },
        [80170227] = {
          ContentTC = "艾利西安的反抗軍……「大遷徙」的人們……",
          DialogueId = 80170227,
          GUID = "C8B29FDE",
          NextDialogue = 80170228,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FDE"
        },
        [80170228] = {
          ContentTC = "我在書裡讀到過。這些人最終並沒有真正實現平等的理想，對吧？",
          DialogueId = 80170228,
          GUID = "C8B2A008",
          NextDialogue = 80170229,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A008"
        },
        [80170229] = {
          ContentTC = "……沒錯，命運就是如此殘酷的東西，它能在平靜中掀起颶風，亦能驅使狂瀾澆滅火焰。正如你所說，很多時候，努力的結局是「徒勞」。",
          DialogueId = 80170229,
          GUID = "C8B2A032",
          NextDialogue = 80170230,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A032"
        },
        [80170230] = {
          ContentTC = "但是，那些曾經閃耀過的瞬間是真實存在的，也會因「記憶」而永遠被銘刻。",
          DialogueId = 80170230,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2A05C",
          NextDialogue = 80170231,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A05C"
        },
        [80170231] = {
          ContentTC = "那場大遷徙將勇敢和自由的光輝播撒到阿特拉西亞大陸上，也戳穿了神的謊言，讓人們第一次開始正視自身的情感與渴望。",
          DialogueId = 80170231,
          GUID = "C8B2A086",
          NextDialogue = 80170232,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A086"
        },
        [80170232] = {
          ContentTC = "即便歷經數百年，仍然有許多人從厚重的史書中尋到這縷光輝，為了實現青年和少女理想中的世界而努力奮鬥著。",
          DialogueId = 80170232,
          GUID = "C8B2A0B0",
          NextDialogue = 80170233,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0B0"
        },
        [80170233] = {
          ContentTC = "嗯……",
          DialogueId = 80170233,
          GUID = "C8B2A0DA",
          NextDialogue = 80170234,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0DA"
        },
        [80170234] = {
          ContentTC = "你方才說，想要聽取我的建議。但我多年避世離俗，很難給予什麼具體的指導。",
          DialogueId = 80170234,
          GUID = "C8B2A104",
          NextDialogue = 80170235,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A104"
        },
        [80170235] = {
          ContentTC = "我想我只能告訴你：越是經歷長生，越是接近永恆，我就越是發覺，真正珍貴的東西，其實是瞬間。一切你抗爭過的瞬間，都不會因抗爭的結果而改變。",
          DialogueId = 80170235,
          GUID = "C8B2A12E",
          NextDialogue = 80170236,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A12E"
        },
        [80170236] = {
          ContentTC = "{nickname}，不必畏懼，不必猶疑－－你擁有非同尋常的力量，你一定會在時間中，留下自己的光輝。",
          DialogueId = 80170236,
          GUID = "C8B2A158",
          NextOptions = {
            [1] = 801702361,
            [2] = 801702362
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A158"
        },
        [80170237] = {
          ContentTC = "我相信你將來一定能做到。",
          DialogueId = 80170237,
          FacialId = {
            [1] = "91502:Satisfy01"
          },
          GUID = "C8B2A182",
          NextDialogue = 80170238,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A182"
        },
        [80170238] = {
          ContentTC = "至於現在……就讓我們放下那些沉重的東西，一起將這壺茶飲盡，好好享受這來之不易的片刻安寧吧。",
          DialogueId = 80170238,
          GUID = "C8B2A1AC",
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A1AC"
        },
        [80170301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "你好，孩子。你的神色看起來比上次好多了。",
          DialogueId = 80170301,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2AC02",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801703011,
            [2] = 801703012
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC02"
        },
        [80170302] = {
          ContentTC = "很高興我的故事能對你有所幫助。那麼，這次你有什麼想要探討的話題嗎？",
          DialogueId = 80170302,
          FacialId = {
            [1] = "91502:Happy01"
          },
          GUID = "C8B2AC2C",
          NextDialogue = 80170303,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC2C"
        },
        [80170303] = {
          ContentTC = "我想知道，妮弗爾怎麼看待「錯誤」？",
          DialogueId = 80170303,
          GUID = "C8B2AC56",
          NextDialogue = 80170304,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC56"
        },
        [80170304] = {
          ContentTC = "我……這一路上經歷了很多，也失去了很多。我總是會想，自己是不是做錯了什麼？如果當初做了不同的選擇，一切是不是會變得更好？",
          DialogueId = 80170304,
          GUID = "C8B2AC80",
          NextDialogue = 80170305,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC80"
        },
        [80170305] = {
          ContentTC = "可是，我無法回到過去，永遠也不可能知道答案了。",
          DialogueId = 80170305,
          GUID = "C8B2ACAA",
          NextDialogue = 80170306,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACAA"
        },
        [80170306] = {
          ContentTC = "嗯……我明白你的困惑了。那麼，今天我就講一個關於「錯誤」的故事吧。這是一對夫婦的故事。",
          DialogueId = 80170306,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2ACD4",
          NextDialogue = 80170307,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACD4"
        },
        [80170307] = {
          ContentTC = "他們住在艾利西安的郊外，丈夫是個獵人，妻子在城裡當女傭。夫妻倆人很想要一個孩子，但多年來未能如願。",
          DialogueId = 80170307,
          GUID = "C8B2ACFE",
          NextDialogue = 80170308,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACFE"
        },
        [80170308] = {
          ContentTC = "某一天，丈夫在森林中打獵時遇到了一個流浪的孩子，見她渾身血汙、瑟瑟發抖，實在可憐，便將她帶回了自己家。",
          DialogueId = 80170308,
          GUID = "C8B2AD28",
          NextDialogue = 80170309,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD28"
        },
        [80170309] = {
          ContentTC = "他的妻子給那女孩洗了澡，發現她並未受傷，只是似乎受到了嚴重的驚嚇，不管對她說什麼，她都是只是呆呆地睜著眼睛，什麼也不回答。",
          DialogueId = 80170309,
          GUID = "C8B2AD52",
          NextDialogue = 80170310,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD52"
        },
        [80170310] = {
          ContentTC = "於是，夫妻倆便暫時收留了這個孩子。在他們日復一日的悉心照料下，女孩慢慢有了知覺，開始對外界的刺激做出反應，最後終於開口說話了。",
          DialogueId = 80170310,
          GUID = "C8B2AD7C",
          NextDialogue = 80170311,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD7C"
        },
        [80170311] = {
          ContentTC = "女孩告訴夫妻倆，自己失去了親生父母。夫妻倆商量之後，決定將女孩收養。二人對養女視如己出，養女也非常乖巧懂事，一家人其樂融融。",
          DialogueId = 80170311,
          GUID = "C8B2ADA6",
          NextOptions = {
            [1] = 801703111
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADA6"
        },
        [80170312] = {
          ContentTC = "表面看來是這樣，但，這個女孩身上藏著一個可怕的秘密。",
          DialogueId = 80170312,
          FacialId = {
            [1] = "91502:Unhappy01"
          },
          GUID = "C8B2ADD0",
          NextDialogue = 80170313,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADD0"
        },
        [80170313] = {
          ContentTC = "她出身於異端者的家庭，一家人都信奉卡戎之民的古老神話。正因如此，她的父母遭到處決，但她卻因為奇特的自愈能力撿回一條命。",
          DialogueId = 80170313,
          GUID = "C8B2ADFA",
          NextDialogue = 80170314,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADFA"
        },
        [80170314] = {
          ContentTC = "她用血肉模糊的手指一寸寸挖開墳墓，從曠野奔逃進林地。",
          DialogueId = 80170314,
          GUID = "C8B2AE24",
          NextDialogue = 80170315,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE24"
        },
        [80170315] = {
          ContentTC = "在艾利西安，沒有比信仰異教更加嚴重的罪行。一旦這個秘密揭露，養父母就算不將她交給處刑人，也一定會立刻拋棄她。",
          DialogueId = 80170315,
          GUID = "C8B2AE4E",
          NextDialogue = 80170316,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE4E"
        },
        [80170316] = {
          ContentTC = "好不容易重新擁有了「家」的女孩不願意失去這份溫暖，於是便抱著小小的僥倖，對自己真正的身份緘口不言。",
          DialogueId = 80170316,
          GUID = "C8B2AE78",
          NextDialogue = 80170317,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE78"
        },
        [80170317] = {
          ContentTC = "時間一天天過去，女孩在養父母的呵護下健康長大，沒有任何人發現她的秘密。慢慢的，她自己也忘記了這件事，一心相信可以就這樣幸福地活下去。",
          DialogueId = 80170317,
          GUID = "C8B2AEA2",
          NextDialogue = 80170318,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEA2"
        },
        [80170318] = {
          ContentTC = "當養母提出帶她進城做工見見世面的時候，她也沒有多想。畢竟她們只是去貴族的宅邸做掃地搓衣的低級女傭，不會引人注目。",
          DialogueId = 80170318,
          GUID = "C8B2AECC",
          NextDialogue = 80170319,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AECC"
        },
        [80170319] = {
          ContentTC = "可是有一天，她的養母在打掃時失手打碎了一件收藏品。按照宅邸中的規定，這樣的過失需要用鞭刑來懲罰。她不忍心養母受苦，替養母認下了錯。",
          DialogueId = 80170319,
          GUID = "C8B2AEF6",
          NextDialogue = 80170320,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEF6"
        },
        [80170320] = {
          ContentTC = "她的皮膚在一瞬間被抽出了觸目驚心的傷口，卻又在短短幾分鐘後迅速癒合。",
          DialogueId = 80170320,
          GUID = "C8B2AF20",
          NextDialogue = 80170321,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF20"
        },
        [80170321] = {
          ContentTC = "這樣的「神蹟」很快傳到了宅邸的主人——「慷慨」大人——的耳中。他聞訊趕到現場，對準女孩的心臟刺下一刀，女孩痛苦掙扎了數十分鐘後，活了過來。",
          DialogueId = 80170321,
          GUID = "C8B2AF4A",
          NextDialogue = 80170322,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF4A"
        },
        [80170322] = {
          ContentTC = "於是「慷慨」大人將這個女孩帶走，並調查了她的身份，發現她正是當年那兩個異端者的女兒。",
          DialogueId = 80170322,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2AF74",
          NextDialogue = 80170323,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF74"
        }
      }
    end
  },
  {
    MinKey = 80170323,
    MaxKey = 80180335,
    Loader = function()
      return {
        [80170323] = {
          ContentTC = "看著這個殺不死的女孩，他最初是憤怒，但又突然想到一個絕佳的主意——艾利西安未出現過這樣的異能，如果能當做「神蹟」好好利用，他便可名利雙收。",
          DialogueId = 80170323,
          GUID = "C8B2AF9E",
          NextDialogue = 80170324,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF9E"
        },
        [80170324] = {
          ContentTC = "但要這麼做，就必須隱瞞女孩的真實身分。為此，他將女孩關押起來，給她編造了新的身份，又將女孩的養母秘密處決。",
          DialogueId = 80170324,
          GUID = "C8B2AFC8",
          NextOptions = {
            [1] = 801703241
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFC8"
        },
        [80170325] = {
          ContentTC = "女孩感到非常後悔。若不是因為她貪戀親情的溫暖，隱瞞了自己的身份，便不會讓善良的養父母經受如此慘劇。",
          DialogueId = 80170325,
          GUID = "C8B2AFF2",
          NextDialogue = 80170326,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFF2"
        },
        [80170326] = {
          ContentTC = "所以，儘管女孩在「大遷徙」發生之時被反抗軍救走，卻沒有再去見自己的養父。這場相遇從一開始就是錯誤的，她不想再給養父帶去麻煩。",
          DialogueId = 80170326,
          GUID = "C8B2B01C",
          NextDialogue = 80170327,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B01C"
        },
        [80170327] = {
          ContentTC = "此後數十年，她一直對往事耿耿於懷，放心不下養父。後來，我在途徑艾利西安的時候，替她前去拜訪了她的養父。",
          DialogueId = 80170327,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2B046",
          NextDialogue = 80170328,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B046"
        },
        [80170328] = {
          ContentTC = "那時她的養父已經是個鬢髮斑斑的老人。他已經隱姓埋名多年，見到我時，他很驚訝居然還有人知道他曾經的名字。",
          DialogueId = 80170328,
          GUID = "C8B2B070",
          NextDialogue = 80170329,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B070"
        },
        [80170329] = {
          ContentTC = "按照女孩的意願，我沒有告知自己的真正來意，只是以引渡人的身分和他聊了聊天，說起了當年的事。",
          DialogueId = 80170329,
          GUID = "C8B2B09A",
          NextDialogue = 80170330,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B09A"
        },
        [80170330] = {
          ContentTC = "老人還清楚地記得當年發生的一切，記得自己在一夜之間失去了妻女，又變成了通緝犯，輾轉流亡數年。",
          DialogueId = 80170330,
          GUID = "C8B2B0C4",
          NextDialogue = 80170331,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0C4"
        },
        [80170331] = {
          ContentTC = "但出乎意料的是，他告訴我，自己並不後悔收養了那個孩子。",
          DialogueId = 80170331,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2B0EE",
          NextDialogue = 80170332,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0EE"
        },
        [80170332] = {
          ContentTC = "他還拿出了一個匣子交給我──那是他妻子的骨灰。他說自己一直在等一位引渡人，好讓妻子的靈魂能安然離去。",
          DialogueId = 80170332,
          GUID = "C8B2B118",
          NextDialogue = 80170333,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B118"
        },
        [80170333] = {
          ContentTC = "我在驚訝中完成了這場遲來幾十年的送別儀式。不可思議的是，我竟然還能聽見那個靈魂的低語——",
          DialogueId = 80170333,
          GUID = "C8B2B142",
          NextDialogue = 80170334,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B142"
        },
        [80170334] = {
          ContentTC = "她和丈夫說了同樣的話：「謝謝你成為我們的女兒。」",
          DialogueId = 80170334,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B16C",
          NextDialogue = 80170335,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B16C"
        },
        [80170335] = {
          ContentTC = "老人告訴我，其實他們從一開始就知道那女孩的身份。女孩父母被殺害的那一天，他們親眼見到了手執火把的處刑人闖入密林。",
          DialogueId = 80170335,
          GUID = "C8B2B196",
          NextDialogue = 80170336,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B196"
        },
        [80170336] = {
          ContentTC = "因此，第二天，在看到那個流浪的女孩的瞬間，他就猜到了她的身份。他們夫妻倆是在知道真相的前提下，決定收養女孩的。",
          DialogueId = 80170336,
          GUID = "C8B2B1C0",
          NextDialogue = 80170337,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1C0"
        },
        [80170337] = {
          ContentTC = "對他們來說，能夠遇見女孩，保護她、養育她，是莫大的幸福。即便這份幸福建立在危險之上，他們也甘願接受。",
          DialogueId = 80170337,
          GUID = "C8B2B1EA",
          NextDialogue = 80170338,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1EA"
        },
        [80170338] = {
          ContentTC = "老人還說，他當年唯一後悔的事情，是自己不夠勇敢。如果他早點帶著妻女逃離艾利西安，也許一家人現在依然能幸福的生活。",
          DialogueId = 80170338,
          GUID = "C8B2B214",
          NextDialogue = 80170339,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B214"
        },
        [80170339] = {
          ContentTC = "所以，在那之後，他也從一個被捏造罪名的普通獵戶，變成了真正的「異端者」——幾十年來，他一直在暗中幫助艾利西安平民逃離邊境。",
          DialogueId = 80170339,
          GUID = "C8B2B23E",
          NextOptions = {
            [1] = 801703391
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B23E"
        },
        [80170340] = {
          ContentTC = "……雖然我沒有明說，但看他釋然的神情，我想他應該猜到了吧。",
          DialogueId = 80170340,
          GUID = "C8B2B268",
          NextDialogue = 80170341,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B268"
        },
        [80170341] = {
          ContentTC = "雖然不能再相見，但知道彼此都還安好，也足以成為安慰吧。",
          DialogueId = 80170341,
          GUID = "C8B2B292",
          NextDialogue = 80170342,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B292"
        },
        [80170342] = {
          ContentTC = "這個故事的結局不算太糟。",
          DialogueId = 80170342,
          GUID = "C8B2B2BC",
          NextDialogue = 80170343,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2BC"
        },
        [80170343] = {
          ContentTC = "嗯。聽了他的這些話，我不禁這麼想——",
          DialogueId = 80170343,
          GUID = "C8B2B2E6",
          NextDialogue = 80170344,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2E6"
        },
        [80170344] = {
          ContentTC = "我們人類啊，只要活著，就總是會做出一些錯誤的選擇。有時是因為目光短淺，有時是因為心存僥倖，有時則是明知故犯。",
          DialogueId = 80170344,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2B310",
          NextDialogue = 80170345,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B310"
        },
        [80170345] = {
          ContentTC = "但是，錯誤的選擇帶來的未必總是錯誤的結果。其中酸甜苦澀，只有當事人自己才完全知曉。",
          DialogueId = 80170345,
          GUID = "C8B2B33A",
          NextDialogue = 80170346,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B33A"
        },
        [80170346] = {
          ContentTC = "比起錯誤本身，更重要的是，我們還有未來。",
          DialogueId = 80170346,
          GUID = "C8B2B364",
          NextDialogue = 80170347,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B364"
        },
        [80170347] = {
          ContentTC = "我們可以彌補它，改變它，賦予它更多的意義。",
          DialogueId = 80170347,
          GUID = "C8B2B38E",
          NextDialogue = 80170348,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B38E"
        },
        [80170348] = {
          ContentTC = "至少，當那個老人和我講起往事的時候，我從他的臉上看到的不是懊悔或痛苦，而是平靜與幸福。",
          DialogueId = 80170348,
          GUID = "C8B2B3B8",
          NextOptions = {
            [1] = 801703481
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3B8"
        },
        [80170349] = {
          ContentTC = "謝謝你的故事，今天我也受益匪淺。",
          DialogueId = 80170349,
          GUID = "C8B2B3E2",
          NextDialogue = 80170350,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3E2"
        },
        [80170350] = {
          ContentTC = "呵呵， 是我要謝謝你才對。",
          DialogueId = 80170350,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B40C",
          NextDialogue = 80170351,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B40C"
        },
        [80170351] = {
          ContentTC = "許是因為上了年紀，我說話總是有些囉嗦，多謝你願意陪著我這個老人家，聽我絮絮叨叨地講這些往事。",
          DialogueId = 80170351,
          GUID = "C8B2B436",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B436"
        },
        [80170401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentTC = "你來了，孩子。今天想聊些什麼？",
          DialogueId = 80170401,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2BC6A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801704011
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC6A"
        },
        [80170402] = {
          ContentTC = "今天我想聽妮弗爾自己的故事。",
          DialogueId = 80170402,
          GUID = "C8B2BC94",
          NextDialogue = 80170403,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC94"
        },
        [80170403] = {
          ContentTC = "我的故事啊……你這麼聰明，應該已經猜到了吧？",
          DialogueId = 80170403,
          GUID = "C8B2BCBE",
          NextOptions = {
            [1] = 801704031,
            [2] = 801704032
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCBE"
        },
        [80170404] = {
          ContentTC = "其實，你之前講的那些故事，都是你親身經歷的事情，對吧？",
          DialogueId = 80170404,
          GUID = "C8B2BCE8",
          NextDialogue = 80170405,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCE8"
        },
        [80170405] = {
          ContentTC = "沒錯。",
          DialogueId = 80170405,
          GUID = "C8B2BD12",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD12"
        },
        [80170406] = {
          ContentTC = "其實我自己的故事，就藏在之前那些故事中間。",
          DialogueId = 80170406,
          GUID = "C8B2BD3C",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD3C"
        },
        [80170407] = {
          ContentTC = "它們既是別人的故事，也都是我的故事。",
          DialogueId = 80170407,
          GUID = "C8B2BD66",
          NextDialogue = 80170408,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD66"
        },
        [80170408] = {
          ContentTC = "我是那個擁有異能卻不能消解他人苦難的女人，是那個被囚禁在聖堂中無力反抗的少女，也是那個害得養父母家破人亡的孩子。",
          DialogueId = 80170408,
          GUID = "C8B2BD90",
          NextDialogue = 80170409,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD90"
        },
        [80170409] = {
          ContentTC = "嗯……可是，我還是想聽你完完整整地說一遍──不再以旁觀的視角，而是以你自己，妮弗爾，作為主角。",
          DialogueId = 80170409,
          GUID = "C8B2BDBA",
          NextDialogue = 80170410,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDBA"
        },
        [80170410] = {
          ContentTC = "是嗎……好，既然你有興趣，我便難得地回憶一下往事吧。",
          DialogueId = 80170410,
          GUID = "C8B2BDE4",
          NextDialogue = 80170411,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDE4"
        },
        [80170411] = {
          ContentTC = "我本來是艾利西安人，出生在一個信奉卡戎神話的家庭。",
          DialogueId = 80170411,
          GUID = "C8B2BE0E",
          NextDialogue = 80170412,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE0E"
        },
        [80170412] = {
          ContentTC = "在我十歲的時候，我的父母因異端者罪被處刑，我本該和他們一同死去，卻在那時意外覺醒為「骸」，獲得了不老不死的異能，活了下來。",
          DialogueId = 80170412,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2BE38",
          NextDialogue = 80170413,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE38"
        },
        [80170413] = {
          ContentTC = "失去了親生父母的我獨自在森林中游盪，被路過的獵戶救下，從此擁有了第二個家。",
          DialogueId = 80170413,
          GUID = "C8B2BE62",
          NextDialogue = 80170414,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE62"
        },
        [80170414] = {
          ContentTC = "十八歲時，我無意中暴露了自己的真實身份，被「慷慨」大人發現，從此戴上了「被賜福者」這頂荊棘之冠。",
          DialogueId = 80170414,
          GUID = "C8B2BE8C",
          NextDialogue = 80170415,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE8C"
        },
        [80170415] = {
          ContentTC = "此後數年間，我的世界就只剩下了那間小小的聖堂，而「慷慨」大人則靠販賣我的血液斂財無數。",
          DialogueId = 80170415,
          GUID = "C8B2BEB6",
          NextDialogue = 80170416,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEB6"
        },
        [80170416] = {
          ContentTC = "直到，兩位勇敢的反抗者將我從這個惡夢中救了出來──第二個故事中的青年和少女是我的恩人，是我最好的朋友，也是為我指引前進方向的人。",
          DialogueId = 80170416,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2BEE0",
          NextDialogue = 80170417,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEE0"
        },
        [80170417] = {
          ContentTC = "後來，艾瑞卡死於北上途中的一場戰役；萊克西斯雖然平安逃離，卻始終沒有找到理想國度的答案，最後在成堆的書稿之中鬱鬱而終。",
          DialogueId = 80170417,
          GUID = "C8B2BF0A",
          NextDialogue = 80170418,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF0A"
        },
        [80170418] = {
          ContentTC = "在伊瑟爾生活的時候，我收養了一個孩子。那是我第一次站在養育者的立場上，去見證一個人完整的生命。",
          DialogueId = 80170418,
          GUID = "C8B2BF34",
          NextDialogue = 80170419,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF34"
        },
        [80170419] = {
          ContentTC = "我看著她從襁褓中的小小嬰兒，出落成明媚動人的少女，再蛻變為沉靜睿智的女人；我記得她的啼哭，記得她牙牙學語，記得她第一次背起古老的詩文……",
          DialogueId = 80170419,
          GUID = "C8B2BF5E",
          NextDialogue = 80170420,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF5E"
        },
        [80170420] = {
          ContentTC = "記得她與萊克西斯滔滔不絕的辯論，也記得她悲痛而鄭重地在萊克西斯的病榻前收下他圖書館的鑰匙。",
          DialogueId = 80170420,
          GUID = "C8B2BF88",
          NextDialogue = 80170421,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF88"
        },
        [80170421] = {
          ContentTC = "我為她的點滴變化而驚喜和欣慰，但也清楚地意識到，她終究也是有限的生命。像艾瑞卡和萊克西斯一樣，她也無法永遠與我同行。",
          DialogueId = 80170421,
          GUID = "C8B2BFB2",
          NextDialogue = 80170422,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFB2"
        },
        [80170422] = {
          ContentTC = "最終，他們都離開了我。我曾經為他們的離去感到悲傷，但在遇到那對求血的姊妹、見證更多的生離死別之後，我終於徹底接受了這無常的世間。",
          DialogueId = 80170422,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2BFDC",
          NextDialogue = 80170423,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFDC"
        },
        [80170423] = {
          ContentTC = "我放下了悲喜，也拋卻了慾念，不會為人世間的諸多苦難而哀痛或憤懣。在那之後的九百年，我一直輾轉阿特拉西亞各地引渡亡魂。",
          DialogueId = 80170423,
          GUID = "C8B2C006",
          NextDialogue = 80170424,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C006"
        },
        [80170424] = {
          ContentTC = "如今我在海伯利亞暫時停留，是為了一個面容熟悉的孩子。但我也無意參與紛爭或改變什麼，只是想見證她的故事而已。",
          DialogueId = 80170424,
          GUID = "C8B2C030",
          NextDialogue = 80170425,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C030"
        },
        [80170425] = {
          ContentTC = "不久之後，我大概又會踏上旅途吧……這世上再也不會有什麼東西能真正讓我結束飄零，除非，「死亡」終於願意為我敞開懷抱。",
          DialogueId = 80170425,
          GUID = "C8B2C05A",
          NextDialogue = 80170426,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C05A"
        },
        [80170426] = {
          ContentTC = "——這就是我的故事，不知你是否滿意？",
          DialogueId = 80170426,
          GUID = "C8B2C084",
          NextOptions = {
            [1] = 801704261
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C084"
        },
        [80170427] = {
          ContentTC = "我還想知道，在擁有這些身份之前，在還沒有獲得長生的能力之前——那時的「妮弗爾」，是怎樣的人？",
          DialogueId = 80170427,
          GUID = "C8B2C0AE",
          NextDialogue = 80170428,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0AE"
        },
        [80170428] = {
          ContentTC = "……",
          DialogueId = 80170428,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2C0D8",
          NextDialogue = 80170429,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0D8"
        },
        [80170429] = {
          ContentTC = "很多人都對我的過去抱有好奇，但問起我童年時期的，你還是第一個。相比於我後來的人生，那段回憶實在太過平淡和普通。",
          DialogueId = 80170429,
          GUID = "C8B2C102",
          NextDialogue = 80170430,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C102"
        },
        [80170430] = {
          ContentTC = "讓我想想……",
          DialogueId = 80170430,
          FacialId = {
            [1] = "91502:Think01"
          },
          GUID = "C8B2C12C",
          NextDialogue = 80170431,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C12C"
        },
        [80170431] = {
          ContentTC = "我的家──我最初的那個家，在艾利西安北方一片鬱鬱蔥蔥的森林中。那裡沒有傳頌會，沒有貴族，只有可愛的野兔和美味的漿果。",
          DialogueId = 80170431,
          GUID = "C8B2C156",
          NextDialogue = 80170432,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C156"
        },
        [80170432] = {
          ContentTC = "我對童年的記憶，是樹葉間灑下的斑駁陽光，是溪水潺潺悅耳的聲響。",
          DialogueId = 80170432,
          GUID = "C8B2C180",
          NextDialogue = 80170433,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C180"
        },
        [80170433] = {
          ContentTC = "那時的我，就和一個普通的女孩一樣，會吵著要父親帶我去森林裡玩耍，會不顧母親的叮囑在小溪邊肆意玩水。",
          DialogueId = 80170433,
          GUID = "C8B2C1AA",
          NextDialogue = 80170434,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1AA"
        },
        [80170434] = {
          ContentTC = "我的母親也是一位引渡人。我常常見到陌生人穿越森林，將一個小匣子交給母親。母親會在月下起舞，讓那個匣子順著水流漂走。",
          DialogueId = 80170434,
          GUID = "C8B2C1D4",
          NextDialogue = 80170435,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1D4"
        },
        [80170435] = {
          ContentTC = "我問母親，匣子裡裝的是什麼？母親回答說，是人們的思念。",
          DialogueId = 80170435,
          GUID = "C8B2C1FE",
          NextDialogue = 80170436,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1FE"
        },
        [80170436] = {
          ContentTC = "我又問母親，為什麼要把思念丟進水裡？母親回答說，因為人們還要向前走。",
          DialogueId = 80170436,
          GUID = "C8B2C228",
          NextDialogue = 80170437,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C228"
        },
        [80170437] = {
          ContentTC = "我完全聽不明白。看到我一臉困惑的樣子，父親笑著摸了摸我的頭頂，說等我長大就會懂了。",
          DialogueId = 80170437,
          GUID = "C8B2C252",
          NextDialogue = 80170438,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C252"
        },
        [80170438] = {
          ContentTC = "只可惜，他們沒能看到我長大的模樣。在他們被處刑人殺死的那一刻，屬於那個無憂無慮的妮弗爾的人生也就結束了。",
          DialogueId = 80170438,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2C27C",
          NextOptions = {
            [1] = 801704381
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C27C"
        },
        [80170439] = {
          ContentTC = "我偶爾會憶起往事，但並不像人們通常所做的那樣，帶著懷念和追思去摩挲這些回憶，只是任由它們從思緒中浮起、飄過。",
          DialogueId = 80170439,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2C2A6",
          NextDialogue = 80170440,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2A6"
        },
        [80170440] = {
          ContentTC = "與我而言，那段往事，連同其他所有的回憶一樣，都是我生命的一部分，本沒有什麼特別。",
          DialogueId = 80170440,
          GUID = "C8B2C2D0",
          NextDialogue = 80170441,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2D0"
        },
        [80170441] = {
          ContentTC = "不過，也許是因為今天有你這個聽眾在，說起這些往事的時候，我的心中似乎也起了些許波瀾……",
          DialogueId = 80170441,
          GUID = "C8B2C2FA",
          NextDialogue = 80170442,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2FA"
        },
        [80170442] = {
          ContentTC = "……我有些累了。請允許我休息片刻吧。",
          DialogueId = 80170442,
          FacialId = {
            [1] = "91502:Close"
          },
          GUID = "C8B2C324",
          NextDialogue = 80170443,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C324"
        },
        [80170443] = {
          ContentTC = "（妮弗爾夫人說著閉上了眼睛，輕輕的將腦袋靠在你的肩膀上。）",
          DialogueId = 80170443,
          GUID = "C8B2C34E",
          IsBlack = 1,
          NextDialogue = 80170444,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C34E"
        },
        [80170444] = {
          ContentTC = "（從她安穩的呼吸和略帶笑意的表情來看，她一定是做了一個好夢吧。）",
          DialogueId = 80170444,
          GUID = "C8B2C378",
          IsBlack = 1,
          NextDialogue = 80170445,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C378"
        },
        [80170445] = {
          ContentTC = "（一個充滿著漿果的香氣和陽光的暖意——或許還有一隻調皮的野兔飛奔而過——的好夢。）",
          DialogueId = 80170445,
          GUID = "C8B2C3A2",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C3A2"
        },
        [80180001] = {
          DialogueId = 80180001,
          GUID = "C8B8E36A",
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8E36A"
        },
        [80180101] = {
          Camera = "452.71582,-120.713928,293.808594,0.000068,-25.999489,160.803513,30.000002,125.0,false,DoNotOverride,2.8",
          ContentTC = "（那是半年前，我去醫院探望一位在南方戰線對傳頌會戰爭中負傷的老兵羅傑·加斯頓的事。）",
          DialogueId = 80180101,
          FacialId = {
            [1] = "790045:Unhappy01"
          },
          FinalCamera = "452.71582,-120.713928,293.808594,0.000071,-23.999413,157.603546,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B8F3D2",
          NextDialogue = 80180102,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3D2"
        },
        [80180102] = {
          Camera = "-17.312012,189.65033,156.878906,0.000039,-12.39904,-60.39682,30.000002,247.327988,false,Manual,3.162369",
          ContentTC = "艾米莉亞……你來了……",
          DialogueId = 80180102,
          FinalCamera = "-15.135742,190.885254,156.878906,0.00004,-12.399033,-61.39677,30.000002,247.327988,false,Manual,3.162369",
          GUID = "C8B8F3FC",
          NextDialogue = 80180103,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3FC"
        },
        [80180103] = {
          Camera = "93.808105,84.920227,124.542969,0.000044,9.600609,157.202698,30.000008,107.300728,false,Manual,3.162369",
          ContentTC = "…………",
          DialogueId = 80180103,
          GUID = "C8B8F426",
