          ContentTC = "……加斯頓先生！",
          DialogueId = 80180121,
          GUID = "C8B8F71A",
          NextDialogue = 80180122,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk02_Start"
