          Camera = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
          ContentTC = "她們都曾這樣期許過我，但我卻未能如她們所願。",
          DialogueId = 80180338,
          GUID = "C8B91AB4",
          NextDialogue = 80180339,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91AB4"
        },
        [80180339] = {
          Camera = "-4.738281,-90.714844,105.755493,0.000144,6.801099,61.380829,40.0,784.897949,false,DoNotOverride,1.422013",
          ContentTC = "世界上有許許多多理性的人，他們善於權衡利弊，做出「最不壞」的那個選擇。他們是天生的優秀領導者，決定著每一個時代的前路。",
          DialogueId = 80180339,
          FinalCamera = "-4.738281,-90.714844,105.755493,0.00014,8.801094,61.180855,40.0,784.897949,false,DoNotOverride,1.422013",
          GUID = "C8B91ADE",
          NextDialogue = 80180340,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91ADE"
        },
        [80180340] = {
          Camera = "997.089844,-499.308594,-19.915771,0.000057,6.20341,151.968689,40.0,1144.406128,false,Manual,1.422013",
          ContentTC = "但我不是。我始終沒有辦法讓自己冷靜下來，去計算更長遠的得失。我能聽到的，就只有眼前的哭泣而已。",
          DialogueId = 80180340,
          FinalCamera = "993.359375,-506.820312,-19.915771,0.000057,6.20341,150.768692,40.0,1144.406128,false,Manual,1.422013",
          GUID = "C8B91B08",
          NextDialogue = 80180341,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B08"
        },
        [80180341] = {
          Camera = "32.263672,-32.617188,205.199585,0.00012,-27.195707,64.570541,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentTC = "但……我想，一個好的時代，應該容得下我這樣短視的傢伙存在。",
          DialogueId = 80180341,
          FinalCamera = "37.583984,-35.265625,205.105835,0.000127,-27.195707,67.17112,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B32",
          NextDialogue = 80180342,
