          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
          Camera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          ContentTC = "（<H>達芙涅·塞奧多爾理想仍存。</>）",
          DialogueId = 80180355,
          GUID = "C8B91D7E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D7E"
        },
        [80190001] = {
          ContentTC = "白吃白喝那我就不客氣啦，有便宜不佔純傻瓜嘛。",
          DialogueId = 80190001,
          GUID = "C8BF4C0A"
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentTC = "你一個人住這麼大宅子？看著還有模有樣，居然還整理出了一個調酒台。",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentTC = "挺好的，多請一些朋友來吧，這樣一來，你也能在冰湖城擁有自己的人脈。",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102
        },
        [80190104] = {
          ContentTC = "那麼，說吧，又有啥事要我幫忙。太麻煩就算了啊，我這幾天手上還有個大活呢。",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentTC = "噫……我雞皮疙瘩都起來了。這話我勉強能受得了，要是你請其他人來喝酒也是這個說辭，人家不一定吃得消啊。",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentTC = "行，那麼我就不客氣了，讓我來嚐一嚐你的手藝怎麼樣。",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentTC = "{空格}",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentTC = "嘖嘖，嗯，甜中帶酸，特意做成了溫酒，和「水仙平原」的水準差不多，但是也有自己的風格。",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentTC = "這一杯挺麻煩的吧。說實話水準超過我的預期了，實話說煮杯熱水我都能樂呵地喝下去，沒必要費這麼大勁。",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102
        },
        [80190110] = {
          ContentTC = "不過，看你這麼興致勃勃，啊……我懂了，攢了點錢就得揮霍一下，請客喝酒，添置新物。用最近流行的話說，就叫「花錢買樂子」？",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102
        },
        [80190111] = {
          ContentTC = "你請人來喝上一杯不就是為了說話？這說明我比其他人都要了解你在想什麼，比其他人都要賞臉。",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentTC = "別別別，我錯了我錯了，你花錢你是老大，要不你打我一拳消消氣。",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentTC = "不過說笑歸說笑，身為半個過來人，我也得提醒你一下，並不是每個人都值得你視為「朋友」請客喝酒的。",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentTC = "尤其在冰湖城這個地界，總有那麼些心術不正的人，會盯上你現在擁有的東西，主動來做你的酒肉之交。",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102
        },
        [80190115] = {
          ContentTC = "他們表面上掛著笑，變著法哄你開心，恨不得把你捧到天上去。但真遇到事兒的時候啊，指望他們還不如指望路邊的一條狗。",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentTC = "啊對的對的對的，我奧特賽德就是你身邊最大的那一號狐朋狗友，有好處的時候不管多遠我聞著味兒都能找過來。",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentTC = "其他人要跟我搶這個名號，也得先掂量掂量自己的斤兩。他們要想從你這吃到好處，那也得等本大爺「吃飽喝足」先。",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102
        },
        [80190118] = {
          ContentTC = "哎，別啊，我還沒待夠呢。",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentTC = "哦？是怎麼回事呢？我可不知道呀。",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentTC = "酒味道不錯，再給我來一杯。喝完這口我就去接著忙活了。",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "嗨呀，遲到了半個鐘頭。為表歉意，哪怕你今天的酒味道像鯡魚罐頭，我也會一口喝下！",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102
        },
        [80190202] = {
          ContentTC = "哈哈，怎麼一下就看穿了。",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102
        },
        [80190203] = {
          ContentTC = "前幾天跟你說的那個大活，記得吧？今天跟威爾斯剛弄完，所以多花了點時間。",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102
        },
        [80190204] = {
          ContentTC = "委託內容本身不麻煩，委託牽連到的傢伙很麻煩。",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102
        },
        [80190205] = {
          ContentTC = "不是他們。只要你符合規矩，會察言觀色，不違背帝國利益，總有很多辦法可以規避軍團的麻煩。",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentTC = "他們就像一把劍，危險致命卻有跡可循。",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102
        },
        [80190207] = {
          ContentTC = "但有一群人比他們更加暴力且毫無章法，就像一顆藏在暗處的炸彈——",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentTC = "神棄者同盟，那個不要命的組織。跟他們扯上關係的事都會變得無比麻煩。",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102
        },
        [80190209] = {
          ContentTC = "比如這次，本來只是個普普通通的送貨委託，但威爾斯覺得貨的重量不對，偷偷鑿了個洞一看，裡面裝滿了神棄者同盟的違規武器。",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102
        },
        [80190210] = {
          ContentTC = "這要是光明正大走大門，怕不是被門口的衛兵當場給斃了。",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102
        },
        [80190211] = {
          ContentTC = "但這應該正是他們想要的。有可能是他們想要幾具狩月人的屍體，也可能是他們想要一場騷亂，趁亂進入冰湖城。",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102
        },
        [80190212] = {
          ContentTC = "也有可能只是他們想要透過這種方式，向他們的追隨者宣揚索拉是如何殘忍對待卡戎的。",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentTC = "完全不可理喻，對吧？總之，一般人根本無法想像他們的行事手段和目的。",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentTC = "最後我們只能想辦法把這批武器弄到下水道裡，順著排水口運進城，完成了他們表面上的送貨委託。",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102
        },
        [80190215] = {
          ContentTC = "聽我說可能覺得還挺輕鬆，實際上為了這事，我跟威爾斯幾天都沒合眼了。",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102
        },
        [80190216] = {
          ContentTC = "兩碼事兩碼事，威爾斯那邊再忙，這邊也確實是遲到了。",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentTC = "兩碼事兩碼事，酒肉朋友就是這樣，有酒喝，那躺在棺材裡也要爬出來喝一口。",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentTC = "{空格}",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentTC = "但我現在確實得回去睡覺了。不過臨走之前還是得和你說一句：為了你和關心你的人著想，少跟現在的神棄者同盟接觸。",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentTC = "……就跟大多數人一樣，看到危險，離遠一點，僅此而已。",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102
        },
        [80190221] = {
          ContentTC = "這是我掙扎在暴力機器相互撕咬的夾縫中這麼久，總結出的寶貴經驗——絕對，絕對，絕對不要靠近神棄者同盟。",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102
        },
        [80190222] = {
          ContentTC = "這不是酒局上的胡話……而是關乎性命的建議。",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "奧特塞德如期赴約，但是喝了一口酒後便一直沒有了聲響。",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          ContentTC = "……",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          ContentTC = "…………",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102
        },
        [80190304] = {
          ContentTC = "……",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102
        },
        [80190305] = {
          ContentTC = "啊……嗯，我沒事，沒事，酒不錯，和之前一樣，高水準。",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102
        },
        [80190306] = {
          ContentTC = "……",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102
        },
        [80190307] = {
          ContentTC = "哈？想多了，我怎麼會在人前掉眼淚，多愁善感和「狐朋狗友」這幾個字可不怎麼搭。",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          ContentTC = "不過，最近確實老想起過去的一些事……哎呀，沒準是歲數大了。",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102
        },
        [80190309] = {
          ContentTC = "別這樣一臉凝重地看著我，我可沒打算繼續說下去，你不會以為幾頓酒就能換來我過去的一切吧。",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102
        },
        [80190310] = {
          ContentTC = "每個人身上都有幾件需要獨自帶入墳墓的秘密。它們不會出現在墓穴，卻是墓主最重要的陪葬。",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102
        },
        [80190311] = {
          ContentTC = "這些秘密可大可小，小到一些奇怪經歷，比如喜歡聞月髓液的味道、喜歡啃硬硬的薑餅結果硌掉了門牙，大到不為人知的過去。",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102
        },
        [80190312] = {
          ContentTC = "但毫無疑問，這些你看不見的秘密才是一個人會做出什麼事的最重要依據。唔，說是最重要可能也過了，但你明白意思就好。",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102
        },
        [80190313] = {
          ContentTC = "隨便把秘密和過去講給你聽的人只有幾種可能，要麼是那段過去對他們來說不夠重要……",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102
        },
        [80190314] = {
          ContentTC = "要麼是期望從你這得到什麼安慰，而隨意捏造了一段不存在的過往。",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102
        },
        [80190315] = {
          ContentTC = "總之，隨意向其他人吐露自己的秘密，是很輕率的。既是把自己的把柄交了出去，也很容易被別人認為當做是行為輕佻。",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          ContentTC = "是是是，通常來說確實如此，你說得這些我也明白。我也時不時在水仙平原和人說我又偷偷接了幾件大活這樣的秘密。",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          ContentTC = "但……有點狡辯地說，秘密也是有大有小的。",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          ContentTC = "說什麼呢，別瞎想！",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          ContentTC = "……正因為是你，才不能讓你知道我的過去。這不是故弄玄虛吊你胃口，而是希望你能夠理解的忠告吧：",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102
        },
        [80190320] = {
          ContentTC = "挖開過去的墳塚，發現的可能不是寶藏，而是死亡。為了不給大家添麻煩，這些事就讓我一個人爛在肚子裡吧。",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102
        },
        [80190321] = {
          ContentTC = "放心，這些年我不都成功的把過去遠遠甩在身後了嘛。就算真追上來了，也還有我扛著。你擔心明天不如過好當下。",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102
        },
        [80190322] = {
          ContentTC = "我要再來一杯！剛才那杯喝得太快了沒嚐出個鹹淡來。",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102
        },
        [80190323] = {
          ContentTC = "哈哈哈哈哈。就著好酒，和好朋友有一茬沒一茬地嘮嘮，多好的一天啊。",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102
        },
        [80190324] = {
          ContentTC = "你剛才是不是罵人了？",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentTC = "{空格}",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          ContentTC = "嗯？你剛剛叫我嗎？",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102
        },
        [80190403] = {
          ContentTC = "啊……是嗎？最近我有點疑神疑鬼的，抱歉。",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          ContentTC = "實際上從很久之前開始，我就會幻聽有人叫我本來的名字。這些聲音有的溫柔，有的堅毅。",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          ContentTC = "就跟耳鳴差不多吧，聽久了也就習慣了。我無聊的時候還會回她們一聲解解悶呢，反正知道是假的。",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102
        },
        [80190406] = {
          ContentTC = "但最近嚇人的事發生了，昨天我習慣性地欸了一聲，結果居然真有人「回應」了。",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102
        },
        [80190407] = {
          ContentTC = "街角的垃圾桶突然翻了過來，蹦出來一個黑黢黢的人影，跟我打招呼。",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102
        },
        [80190408] = {
          ContentTC = "我多希望那是哪個倒霉孩子的惡作劇。但可惜的是我聽到了那個只有神棄者同盟的人才會叫的名字，而不是你所知的「奧特賽德」。",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102
        },
        [80190409] = {
          ContentTC = "我趕緊裝聽錯的路人搪塞過去了，也不知道那人信了沒……唉，早知道前幾天那個神棄者同盟的活就全甩給威爾斯了。",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          ContentTC = "……",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102
        },
        [80190411] = {
          ContentTC = "{空格}",
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          ContentTC = "好吧，也該告訴你一些的。不然你走在路上莫名其妙被神棄者同盟的瘋子捅了一刀，都不知道該怨誰了。",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          ContentTC = "我以前跟神棄者同盟有點……小過節，所以他們一直在找我。然後前幾天那個委託<H>可能</>暴露了我的行蹤。",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102
        },
        [80190414] = {
          ContentTC = "所以我得費點功夫，消掉在冰湖城的一些痕跡，免得他們真的順著線索找到我。",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102
        },
        [80190415] = {
          ContentTC = "真要被他們找到了啊，我的朋友們都得遭殃，挨個拷打，不吐出我的下落不罷休。連你也跑不掉。",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102
        },
        [80190416] = {
          ContentTC = "不過嘛，你也大可以說，我是你的酒肉朋友，和我相關的事情一概不知——",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          ContentTC = "哎，別急著打斷我，這不還沒發生嘛。不過……萬一真的有那麼一天……",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          ContentTC = "到時候我得離開你們，離開這座城市。菲娜就拜託你照顧了。",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102
        },
        [80190419] = {
          ContentTC = "她要是問起來你就說我接了個大活。我這裡寫了些信，你到時候每個月給她一封，應該能穩住她一段時間。",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102
        },
        [80190420] = {
          ContentTC = "對了還有，我家暖爐右手第三塊磚後面藏了一筆錢，你直接拿去用吧。我想想還有什麼……",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          ContentTC = "奧特賽德你先冷靜點。",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008
        },
        [80190422] = {
          ContentTC = "我很冷靜。你跟我複述一遍我剛才說的，我到時候不在了一切都得靠你了。",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102
        },
        [80190423] = {
          ContentTC = "這可不是你平常的樣子，就因為神棄者同盟嗎？",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008
        },
        [80190424] = {
          ContentTC = "平時？平常可應付不了毫無底線的瘋子。",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          ContentTC = "舉個例子，為了一條情報，他們會一枚一枚地拔掉你的指甲。",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102
        },
        [80190426] = {
          ContentTC = "而這一切只是那群瘋子折磨的開始罷了……我不想看到這種事……發生在朋友身上……",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102
        },
        [80190427] = {
          ContentTC = "但這些都還沒發生，而且你也說了自己的行蹤只是<H>可能</>暴露了而已，不是嗎？",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008
        },
        [80190428] = {
          ContentTC = "即使是「可能」，也得做好萬全準備。",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102
        },
        [80190429] = {
          ContentTC = "過去沒有類似的「可能」嗎？現在比過去更危險嗎？",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008
        },
        [80190430] = {
          ContentTC = "要說最危險的時候，這次好像還真不算什麼……",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          ContentTC = "這不就對了，過去你是怎麼解決的。",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008
        },
        [80190432] = {
          ContentTC = "……有些只是虛驚一場，有些被我用恐嚇、欺騙，把軍團引來，或者在其他城市拋頭露面之類的把戲解決掉了。",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102
        },
        [80190433] = {
          ContentTC = "{空格}",
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          ContentTC = "是啊……你說的對。剛才我好像是有點……不太對勁。更危險的時候我都撐過來了，這次卻早早把「後事」交代給了你。",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentTC = "是最近跟你聊得太多還是我下意識地想要依賴你這個隊長了，亦或是我變軟弱了嗎……",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102
        },
        [80190436] = {
          ContentTC = "不對不對，怎麼可能嘛！肯定是今天的酒有問題！剛才我說過什麼很噁心的話嗎？沒有吧，絕對沒有，對吧！",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentTC = "所以說回來，比起擔心還未發生的「可能」，不如還是等一切發生的時候再來拜託我吧，也許那時候我們還能找到更好的辦法。",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008
        },
        [80190438] = {
          ContentTC = "咳咳，說得好。拜託了，未來的我！來來喝酒喝酒，敬未來的我們。",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102
        },
        [80190439] = {
          ContentTC = "{空格}",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentTC = "哦，但我還得道個歉，關於未來的擔心是解決了，但關於我的過去，還是沒辦法全部告訴你。",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentTC = "不過我向你保證，一定會有一天，我會帶你看我來到冰湖城之前的路。雖然它會讓我痛苦，也可能讓你對我有所懷疑。",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102
        },
        [80190442] = {
          ContentTC = "但我相信，到那時候，你依舊不會介意為我調上一杯和今日一樣的酒的，我的朋友。",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102
        },
        [80200001] = {
          Camera = "371.189178,358.122345,166.996094,0.000053,-4.198886,-152.598816,30.0,1011.382263,false,Manual,2.8",
