          },
          ToFinalCameraBlendTime = 8
        },
        [80200004] = {
          ContentTC = "的確如此，方才提及的皆可入藥，有的也可以食用。",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200006] = {
          ContentTC = "嗬嗬，沒想到你涉獵如此之廣，正是出自《草木精要》。",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200008] = {
          ContentTC = "無礙，你我之間不必如此小心。你願來拜訪，我自是歡迎。",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200009] = {
          Camera = "-299.287354,935.059692,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          ContentTC = "正巧，我已讀了半晌書，是該休息的時候了。",
          DialogueId = 80200009,
          FinalCamera = "-309.453308,979.785645,645.397461,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B5FA",
