        },
        [80200010] = {
          Camera = "-232.469772,-43.903526,169.408203,0.000064,-9.39922,29.805199,35.0,1011.382263,false,DoNotOverride,1.2",
          ContentTC = "只是如今的枯榮閣早已人去樓空，並無好茶款待，倒是失禮。",
          DialogueId = 80200010,
          FinalCamera = "-235.925156,-37.86274,169.408203,0.000064,-9.39922,29.80522,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B624",
          NextOptions = {
            [1] = 802000101,
            [2] = 802000102,
            [3] = 802000103
          },
          Scripts = "LookAt{_delay{5.1},LookAtDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200012] = {
          ContentTC = "起初確實不大習慣，但我實在留戀故地，因此不慣也慣了。",
          DialogueId = 80200012,
          GUID = "C8C5B678",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200014] = {
          ContentTC = "謝你海涵，這就是所謂的「君子之交淡若水」吧。",
          DialogueId = 80200014,
          GUID = "C8C5B6CC",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200016] = {
          ContentTC = "餓了嗎？但此刻天色尚早，並不是正經用餐的時候，再過些時候吧。",
          DialogueId = 80200016,
          GUID = "C8C5B720",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200017] = {
          Camera = "8.049835,364.447235,138.173828,0.000069,-1.798737,-95.393364,35.0,1011.382263,false,DoNotOverride,1.2",
          ContentTC = "難得今日有緣相見，那我也不再遮掩，其實……扶疏有一事相求。",
          DialogueId = 80200017,
          FinalCamera = "6.295837,345.858063,137.587891,0.000069,-1.798737,-96.993561,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B74A",
          NextDialogue = 80200018,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790053:n(790008)"
          }
        },
        [80200018] = {
          Camera = "-151.623276,12.392727,139.394531,0.000081,-2.999197,33.605621,35.0,194.999741,false,Manual,7.870067",
          ContentTC = "可以說來聽聽。",
          DialogueId = 80200018,
          GUID = "C8C5B774",
          NextDialogue = 80200019,
          SpeakNpcId = 790008,
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          }
        },
        [80200019] = {
          Camera = "13.768398,198.582336,145.302734,0.000078,-2.199123,-112.991898,35.0,194.999741,false,Manual,7.870067",
          ContentTC = "上次憑筆記中尋來的方子治好了那位被玄色狴犴所傷的姑娘，使我對藥理生出幾分興趣。",
          DialogueId = 80200019,
          GUID = "C8C5B79E",
          NextDialogue = 80200020,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start",
            [2] = "790008:Talk02_End"
          }
        },
        [80200020] = {
          Camera = "-151.623276,12.392727,139.394531,0.000081,-2.999197,33.605621,35.0,194.999741,false,Manual,7.870067",
          ContentTC = "扶氏世代以枯榮之術救人，藥理則是近百年才出現的學問。家姐生前精於此道，我所知卻是微末。",
          DialogueId = 80200020,
          GUID = "C8C5B7C8",
          NextDialogue = 80200021,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_End",
            [2] = "790008:Think_Start"
          }
        },
        [80200021] = {
          Camera = "3.627094,154.315002,128.976562,0.000067,6.000922,-123.393097,35.0,1011.382263,false,DoNotOverride,1.2",
          ContentTC = "我……我想貫徹家傳使命的願望自然未改，但從棺中蘇醒的因緣，是家姐與她的弟子耗盡心血得來，我也不願輕易辜負他們。",
          DialogueId = 80200021,
          FinalCamera = "-4.169064,142.494461,130.460938,0.000067,6.000922,-123.393059,35.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B7F2",
          NextDialogue = 80200022,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [80200022] = {
          Camera = "-92.099129,54.970886,136.441406,0.000081,0.000908,39.804794,35.0,194.999741,false,Manual,7.870067",
          ContentTC = "因此我才試著去研習如今的醫藥學問，但這樣的事終究是紙上得來終覺淺。",
          DialogueId = 80200022,
          GUID = "C8C5B81C",
          NextDialogue = 80200023,
          SpeakNpcId = 790053
        },
        [80200023] = {
          Camera = "-998.92572,807.125,118.349609,0.000104,2.800753,-34.992069,35.0,12772.838867,false,Manual,1.460963",
          ContentTC = "我一直很想找人實踐一番，看看要如何去望聞問切，所謂病理，在人身上究竟是何等境況。",
          DialogueId = 80200023,
          FinalCamera = "-998.92572,807.125,61.935547,0.000104,2.800753,-34.992069,35.0,12772.838867,false,Manual,1.460963",
          GUID = "C8C5B846",
          NextDialogue = 80200024,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 15
        },
        [80200024] = {
          ContentTC = "只是百年光陰轉瞬即逝，我在此地早已是無親無友。",
          DialogueId = 80200024,
          GUID = "C8C5B870",
          NextDialogue = 80200025,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200025] = {
          ContentTC = "若隨意為人診治，要是出了差錯，豈不成了醫德不修之人？",
          DialogueId = 80200025,
          GUID = "C8C5B89A",
          NextDialogue = 80200026,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Think_End"
          }
        },
        [80200026] = {
          Camera = "37.140533,321.639557,117.170898,0.00008,4.200812,-104.992432,35.0,194.999741,false,Manual,7.870067",
          ContentTC = "若要尋找有些交情，也願擔待扶疏一二的……思來想去，你竟是唯一的人選。",
          DialogueId = 80200026,
          FinalCamera = "22.796768,325.479004,117.170898,0.000079,4.200812,-101.992058,35.0,194.999741,false,Manual,7.870067",
          GUID = "C8C5B8C4",
          NextDialogue = 80200027,
          Scripts = [[
