          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200027] = {
          Camera = "-371.388824,918.673523,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          ContentTC = "然而身體狀況乃是私隱，你若不願，我定不會勉強你。",
          DialogueId = 80200027,
          FinalCamera = "-298.00293,935.355347,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B8EE",
          NextOptions = {
            [1] = 802000271,
            [2] = 802000272,
            [3] = 802000273
          },
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200029] = {
          ContentTC = "多謝……對你來說雖是舉手小事，但扶疏銘記在心。",
          DialogueId = 80200029,
          GUID = "C8C5B942",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200031] = {
          ContentTC = "誒？竟、竟如此信任我嗎？等一下，倒也不用這麼急著脫下鬥篷……",
          DialogueId = 80200031,
          GUID = "C8C5B996",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200033] = {
          ContentTC = "我自然不會提如此危險之事！不過……這是答應的意思嗎？",
          DialogueId = 80200033,
          GUID = "C8C5B9EA",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200034] = {
          Camera = "-12.930632,116.6409,137.194336,0.000094,6.600558,-127.588852,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentTC = "承蒙不棄，扶疏一定盡力而為。",
          DialogueId = 80200034,
          GUID = "C8C5BA14",
          NextDialogue = 80200035,
          SpeakNpcId = 790053
        },
        [80200035] = {
          ContentTC = "扶疏仔仔細細地為你診治一番。",
          DialogueId = 80200035,
          GUID = "C8C5BA3E",
          IsBlack = 1
        },
        [80200036] = {
          Camera = "-40.848995,85.709183,149.865234,0.000094,1.200781,-124.785934,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentTC = "嗯……你的身體十分健康，至少在我看來沒有什麼大的不妥，只是……",
          DialogueId = 80200036,
          FinalCamera = "-27.404249,104.783081,149.896484,0.000094,0.000697,-124.58551,45.000023,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BA68",
          NextDialogue = 80200037,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 4
        },
        [80200037] = {
          Camera = "-77.972321,4.005304,157.167969,0.000114,-5.999071,62.412296,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "從面色上看不出來，但您應該很久、很久沒有睡覺了吧？",
          DialogueId = 80200037,
          GUID = "C8C5BA92",
          NextOptions = {
            [1] = 802000371,
            [2] = 802000372,
            [3] = 802000373
          },
          SpeakNpcId = 790053
        },
        [80200039] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "長此以往，可能會落下病根，可要千萬注意。若是沒有安枕的地方，這枯榮閣也可做你暫時落腳的地方。",
          DialogueId = 80200039,
          GUID = "C8C5BAE6",
          NextDialogue = 80200049,
          SpeakNpcId = 790053
        },
        [80200041] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "求財雖是人之常情，但連軸轉並不可取。如果不加改善，下次就沒有免費診治的機會了，或許……我還會考慮向你收取高額診金喔。",
          DialogueId = 80200041,
          GUID = "C8C5BB3A",
          NextDialogue = 80200042,
          SpeakNpcId = 790053
        },
        [80200042] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "不——要——啊——我——要——撤——回——這——個——診——療——",
          DialogueId = 80200042,
          GUID = "C8C5BB64",
          NextDialogue = 80200049,
          SpeakNpcId = 790008
        },
        [80200044] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "嗯……如果病人的態度非常不配合的話，我只能把藥方換成別的了。",
          DialogueId = 80200044,
          GUID = "C8C5BBB8",
          NextDialogue = 80200045,
          SpeakNpcId = 790053
        },
        [80200045] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "比如？",
          DialogueId = 80200045,
          GUID = "C8C5BBE2",
          NextDialogue = 80200046,
          SpeakNpcId = 790008
        },
        [80200046] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "我自幼練武，只是尋常傷筋動骨的話，不用枯榮之術我也能醫治。",
          DialogueId = 80200046,
          GUID = "C8C5BC0C",
          NextDialogue = 80200047,
          SpeakNpcId = 790053
        },
        [80200047] = {
          ContentTC = "不過有時病人疼得厲害，亂動起來可能會加重病情，這時候只要擊打這裡，就可以讓人暫時失去意識，來，我指給你看……",
          DialogueId = 80200047,
          GUID = "C8C5BC36",
          NextDialogue = 80200048,
          SpeakNpcId = 790053
        },
        [80200048] = {
          Camera = "-77.972321,4.005304,152.584961,0.000114,-5.999071,62.41214,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "不不不用了醫生，我選擇保守治療！",
          DialogueId = 80200048,
          GUID = "C8C5BC60",
          NextDialogue = 80200049,
          SpeakNpcId = 790008
        },
        [80200049] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentTC = "確實能察覺到，你的睡眠時間少到了誇張的地步……是有失眠，或者入睡困難之類的問題嗎？",
          DialogueId = 80200049,
          GUID = "C8C5BC8A",
          NextDialogue = 80200050,
          SpeakNpcId = 790053
        },
        [80200050] = {
          Camera = "-56.48967,56.785522,140.112305,0.000036,-0.399088,56.015965,35.0,194.999756,false,DoNotOverride,7.870067",
          ContentTC = "我可能是天生覺少……不過我有多夢的症狀。有時從夢中突然驚醒，就再也睡不著了。",
          DialogueId = 80200050,
          GUID = "C8C5BCB4",
          NextDialogue = 80200051,
          SpeakNpcId = 790008
        },
        [80200051] = {
          Camera = "21.420506,52.709782,178.382812,0.00004,-17.199427,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          ContentTC = "竟是如此。我還以為你是自入華胥以來無暇休息所致，原來是老症候了。",
          DialogueId = 80200051,
          GUID = "C8C5BCDE",
          NextDialogue = 80200052,
          SpeakNpcId = 790053
        },
        [80200052] = {
          ContentTC = "不過我已經想好了一劑藥方，不敢保證藥到病除，但堅持服用也會有所裨益。",
          DialogueId = 80200052,
          GUID = "C8C5BD08",
          NextDialogue = 80200053,
          SpeakNpcId = 790053
        },
        [80200053] = {
          Camera = "1945.186279,141.809723,246.677734,0.000132,-2.999115,-178.399689,35.0,912.188171,false,Manual,2.349894",
          ContentTC = "只是……其中最關鍵的一味「懷夢草」，是枯榮閣中沒有的。要去百年春求購，又需好些時日。",
          DialogueId = 80200053,
          FinalCamera = "2107.597168,146.344818,255.18457,0.000132,-2.999115,-178.399689,35.0,912.188171,false,Manual,2.349894",
          GUID = "C8C5BD32",
          NextDialogue = 80200054,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200054] = {
          ContentTC = "最好便是枯榮閣附近尋上一尋，若是幸運，今晚你便能好好休息了。不知你意下如何呢？",
          DialogueId = 80200054,
          GUID = "C8C5BD5C",
          NextDialogue = 80200055,
          SpeakNpcId = 790053
        },
        [80200055] = {
          Camera = "-138.100891,-376.441467,153.882812,0.000078,-5.798817,78.616974,35.0,194.999756,false,DoNotOverride,7.870067",
          ContentTC = "那就多謝你了！",
          DialogueId = 80200055,
          FinalCamera = "-148.366501,-427.434601,159.165039,0.000079,-5.798817,78.617157,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BD86",
          NextDialogue = 80200056,
          SpeakNpcId = 790008,
          ToFinalCameraBlendTime = 15
        },
        [80200056] = {
          ContentTC = "時間不等人，即刻出發吧。",
          DialogueId = 80200056,
          GUID = "C8C5BDB0",
          SpeakNpcId = 790053
        },
        [80200101] = {
          Camera = "1057.966797,3364.197266,1836.991211,0.000101,-23.599348,-116.380623,25.0,3742.911621,false,Manual,1.2",
          ContentTC = "潺潺水底伏流荇，靜靜池上開蓮草。樹下菌鄰懷夢草，難分彼此是音容……",
          DialogueId = 80200101,
          Duration = 10,
          FinalCamera = "1077.720703,3354.39209,1836.991211,0.000102,-23.599367,-116.380653,25.0,3742.911621,false,Manual,1.2",
