          ContentTC = "這是《草木精要》附錄中的一首歌謠，簡單介紹了一些藥草的生長環境，方便有需要的人尋找它們。",
          DialogueId = 80200103,
          Duration = 8,
          FinalCamera = "183.388687,302.15509,-62.86084,0.000161,16.596128,-128.566315,25.000002,3742.911621,false,Manual,2.8",
          GUID = "C8C5C566",
          NextDialogue = 80200104,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 15
        },
        [80200104] = {
          ContentTC = "在如今的華胥，基本人人都能背上幾句，也算是耳熟能詳了。",
          DialogueId = 80200104,
          Duration = 6,
          GUID = "C8C5C590",
          NextDialogue = 80200105,
          SpeakNpcId = 790053,
          TurnTo = {
            [1] = "790053:p(-170)"
          }
        },
        [80200105] = {
          ContentTC = "了解過後，若是碰上被蟲蛇咬傷，或是突發疾病，便知道在哪裡尋藥救急。",
          DialogueId = 80200105,
          Duration = 6,
          GUID = "C8C5C5BA",
          NextDialogue = 80200106,
          SpeakNpcId = 790053,
          TalkActionId = {
