        [80200210] = {
          Camera = "10.083984,-16.130859,124.486328,0.000127,5.801269,142.400635,25.000006,523.327209,false,DoNotOverride,1.2",
          ContentTC = "啊！",
          DialogueId = 80200210,
          GUID = "C8C5D0B8",
          NextDialogue = 80200211,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          }
        },
        [80200211] = {
          ContentTC = "你怎麼……等等不是說這個的時候……",
          DialogueId = 80200211,
          GUID = "C8C5D0E2",
          NextDialogue = 80200212,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.01},TargetPosition{"-54.814453,90.382812,175.259277,0.000145,-23.597721,3.001867,35.0,111.63089,false,Manual,20.07291"},duration{0}},
MoveTo{_delay{3.01},ActorId{790053},TargetPoint{"BP_200301a_fushu01"},MoveSpeed{100},Visibility{"Show"}}
}]],
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200212] = {
          ContentTC = "你感覺如何？",
          DialogueId = 80200212,
          GUID = "C8C5D10C",
          NextDialogue = 80200213,
          SpeakNpcId = 790053
        },
        [80200213] = {
          Camera = "37.232422,103.78125,138.741211,0.000152,7.400476,169.987396,35.0,111.63089,false,Manual,20.07291",
          ContentTC = "嗯……還不錯，味道像薄荷，吃著很清樂依昂——",
          DialogueId = 80200213,
          GUID = "C8C5D136",
          NextDialogue = 80200214,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"37.232422,103.78125,138.741211,0.000152,7.400476,169.987396,35.0,111.63089,false,Manual,20.07291"},duration{0}},
CameraMoveTo{TargetPosition{"25.619141,105.791016,140.636719,0.000142,55.800377,168.787918,35.0,111.63089,false,Manual,20.07291"},Blend{"easeInOutQuad"},duration{1}}
}]],
          SpeakNpcId = 790008
        },
        [80200214] = {
          ContentTC = "（扶疏的臉逐漸模糊，你確認了一件事：你不屬於音容草耐受人群。）",
          DialogueId = 80200214,
          GUID = "C8C5D160",
          IsBlack = 1
        },
        [80200215] = {
          ContentTC = "進入幻境，主角在枯榮閣中刷出，NPC扶風刷出，背對主角。",
          DialogueId = 80200215,
          GUID = "C8C5D18A"
        },
        [80200216] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "頭、頭好暈……這裡是枯榮閣？",
          DialogueId = 80200216,
          GUID = "C8C5D1B4",
          NextDialogue = 80200217,
          SpeakNpcId = 790008
        },
        [80200217] = {
          ContentTC = "那是……扶疏？",
          DialogueId = 80200217,
          GUID = "C8C5D1DE",
          NextDialogue = 80200218,
          SpeakNpcId = 790008
        },
        [80200218] = {
          ContentTC = "麻煩。麻煩。麻煩。麻煩！",
          DialogueId = 80200218,
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200219] = {
          ContentTC = "唉，早上起來的時候，還再三告誡自己別去惹她別去惹她，怎麼早飯還沒吃完，就破戒了！",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200220] = {
          ContentTC = "扶風啊扶風！你怎能如此沉不住氣呢！那小妮子脾氣再臭，也是你親妹子！你又不可能扔下她不管，乾嘛總是氣她呢！",
          DialogueId = 80200220,
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200221] = {
          ContentTC = "沒辦法啊沒辦法，扶疏那一本正經的樣子，實在是很好氣……笑容沒有消失，只是從扶疏妹妹的臉上，移到了我的臉上……",
          DialogueId = 80200221,
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          SpeakNpcId = 790054
        },
        [80200222] = {
          ContentTC = "人之常情，人之常情嘛！",
          DialogueId = 80200222,
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          SpeakNpcId = 790054
        },
        [80200223] = {
          ContentTC = "扶、扶疏？是你嗎？",
          DialogueId = 80200223,
          GUID = "C8C5D2DA",
          NextDialogue = 80200224,
          SpeakNpcId = 790008
        },
        [80200224] = {
          ContentTC = "不是哦。我是扶疏的雙胞胎姐姐，扶風。將我倆弄混的人，你不是第一個。",
          DialogueId = 80200224,
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          SpeakNpcId = 790054
        },
        [80200225] = {
          ContentTC = "你找扶疏？怪了，她素來不和人來往，是個小悶葫蘆，原來也有熟人？",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          SpeakNpcId = 790054
        },
        [80200226] = {
          ContentTC = "哇……你這個年紀的人，竟不覺得她悶，還這樣誇獎她，不錯不錯，扶疏的朋友，就是我扶風的朋友！",
          DialogueId = 80200226,
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200227] = {
          ContentTC = "訛錢訛到我枯榮閣來了？！你去這十裡八鄉問問，這小悶葫蘆的肚子裡連點銅錢響都聽不到，你要誣賴人，好歹也誣賴給我吧！",
          DialogueId = 80200227,
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200228] = {
          ContentTC = "噫，油嘴滑舌，要是沒病沒痛就回家自己玩兒吧，乖。",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200229] = {
          ContentTC = "所以，你造訪枯榮閣所為何事？",
          DialogueId = 80200229,
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054
        },
        [80200230] = {
          ContentTC = "我誤食了音容草，頭腦發昏，還看見奇奇怪怪的東西，我想扶疏一定能治，就尋醫問藥來了。",
          DialogueId = 80200230,
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          SpeakNpcId = 790008
        },
        [80200231] = {
          ContentTC = "你來得不巧，扶疏正生著悶氣呢，還是別在這時候打擾她了。不過我是一名醫師，讓我看病也是一樣的。",
          DialogueId = 80200231,
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          SpeakNpcId = 790054
        },
        [80200232] = {
          ContentTC = "讓我仔細看看……",
          DialogueId = 80200232,
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          SpeakNpcId = 790054
        },
        [80200233] = {
          ContentTC = "嗯……步履還算穩健，雙目也有焦點，口齒利索，舌頭不打架，誤食的量應該不大。大約是半片左右？",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          SpeakNpcId = 790054
        },
        [80200234] = {
          ContentTC = "你症狀不重，沒等解藥熬完，就全好了。再耐心等等吧，很快就會清醒的，別怕。",
          DialogueId = 80200234,
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          SpeakNpcId = 790054
        },
        [80200235] = {
          ContentTC = "要是實在難受，我隨身帶了些橘枳丸，你嚼兩個，會好些。",
          DialogueId = 80200235,
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054
        },
        [80200236] = {
          ContentTC = "我猜，你還有少眠多夢的毛病，於是你想去找懷夢草醫治，但卻不小心誤食了極其類似的音容草。",
          DialogueId = 80200236,
          GUID = "C8C5D57A",
          NextDialogue = 80200237,
          SpeakNpcId = 790054
        },
        [80200237] = {
          ContentTC = "不過想治這個毛病，還是匍地枝與隙中花一同煎來服下更合適，懷夢草雖能助眠，但會在夢中看到難以忘懷之事，徒惹傷懷。",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          NextDialogue = 80200238,
          SpeakNpcId = 790054
        },
        [80200238] = {
          ContentTC = "……不提外貌，你和扶疏確實相像。",
          DialogueId = 80200238,
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008
        },
        [80200239] = {
          ContentTC = "這話倒是鮮少聽到，我和扶疏雖是雙生胎，但都說我性格跳脫，頗有「離經叛道」的嫌疑，與大風九章第九條很不相宜。",
          DialogueId = 80200239,
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054
        },
        [80200240] = {
          ContentTC = "扶疏瞧著冷淡疏離，你瞧著風風火火，但只要涉及問診的時候，那份一本正經，溫和耐心簡直如出一轍。",
          DialogueId = 80200240,
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008
        },
        [80200241] = {
          ContentTC = "你這人……現在我相信你和扶疏很熟了。",
          DialogueId = 80200241,
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054
        },
        [80200242] = {
          ContentTC = "那孩子性格執拗，許多話憋在心裡不肯說，一張嘴也不怎麼靈巧，有時明明是這個意思，說出來卻離題萬裡。",
          DialogueId = 80200242,
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054
        },
        [80200243] = {
          ContentTC = "大概……只有你這樣細心的人才能和她玩到一起吧！",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054
        },
        [80200244] = {
          ContentTC = "我這個做姐姐的慣愛嘴欠，先甘拜下風啦。",
          DialogueId = 80200244,
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054
        },
        [80200245] = {
          ContentTC = "那麼，扶疏的熟人！姐姐有件事情拜托，看在扶疏的面子上，你一定會答應我的吧！",
          DialogueId = 80200245,
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054
        },
        [80200246] = {
          ContentTC = "願聞其詳。",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008
        },
        [80200247] = {
          ContentTC = "可不可以幫我找一下送給扶疏的道歉禮物？",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054
        },
        [80200248] = {
          ContentTC = "離這裡不遠的水域中，常有壽星烏賊出沒，幫我釣些來，不難的吧！",
          DialogueId = 80200248,
          GUID = "C8C5D772",
          SpeakNpcId = 790054
        },
        [80200301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "哇……真的釣到了，好厲害。全能如我，坐在那裡一天也未必能釣上來一條……",
          DialogueId = 80200301,
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          SpeakNpcId = 790054
        },
        [80200302] = {
          ContentTC = "並非全能。",
          DialogueId = 80200302,
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008
        },
        [80200303] = {
          ContentTC = "扶疏給我看過你的畫，很抽象。",
          DialogueId = 80200303,
          GUID = "C8C5E636",
          NextDialogue = 80200304,
          SpeakNpcId = 790008
        },
        [80200304] = {
          ContentTC = "……你們是不是有點太熟了，她怎麼把此等家醜也告訴你？",
          DialogueId = 80200304,
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          SpeakNpcId = 790054
        },
        [80200305] = {
          ContentTC = "咳……但我從來不知道扶疏喜歡壽星烏賊。",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          NextDialogue = 80200306,
          SpeakNpcId = 790008
        },
        [80200306] = {
          ContentTC = "並非喜歡。",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054
        },
        [80200307] = {
          ContentTC = "扶疏最討厭壽星烏賊，小時候被嚇哭過呢！",
          DialogueId = 80200307,
          GUID = "C8C5E6DE",
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054
        },
        [80200311] = {
          ContentTC = "其實我最近已經和她吵架好幾次了，你應該知道我們吵架的緣由吧？",
          DialogueId = 80200311,
          GUID = "C8C5E786",
          NextDialogue = 80200312,
          SpeakNpcId = 790054
        },
        [80200312] = {
          ContentTC = "無非就是我想要鑽研新的治病救人的辦法，而她認為要堅守枯榮之術。",
          DialogueId = 80200312,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054
        },
        [80200313] = {
          ContentTC = "老實說，她有她的道理，我的方法一是前途未卜，不知成效，二是背離了大風九章……",
          DialogueId = 80200313,
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          SpeakNpcId = 790054
        },
        [80200314] = {
          ContentTC = "我與我的研究最後究竟是怎樣的結局，誰也不知道。",
          DialogueId = 80200314,
          GUID = "C8C5E804",
          NextDialogue = 80200315,
          SpeakNpcId = 790054
        },
        [80200315] = {
          ContentTC = "但有一件事我可以確定，那就是濫用枯榮之術，扶疏妹妹一定會英年早逝吧。",
          DialogueId = 80200315,
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          SpeakNpcId = 790054
        },
        [80200316] = {
          ContentTC = "而我……不想看到這個局面，所以我絕不會讓步，我們的架也只能一直吵下去了。",
          DialogueId = 80200316,
          GUID = "C8C5E858",
          NextDialogue = 80200317,
          SpeakNpcId = 790054
        },
        [80200317] = {
          ContentTC = "唉，攤上這麼一個不知姐姐苦心的妹妹，就算是得由我來道歉，我也不會讓她好過的！",
          DialogueId = 80200317,
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          SpeakNpcId = 790054
        },
        [80200318] = {
          ContentTC = "但我已經不被允許靠近她了，這些小可愛就交由你來轉贈吧！她那麼信任你，肯定毫無防備，說不定還會像小時候一樣被嚇哭哦。",
          DialogueId = 80200318,
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          SpeakNpcId = 790054
        },
        [80200319] = {
          ContentTC = "壽星烏賊……",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320
        },
        [80200320] = {
          ContentTC = "你只是想拐彎抹角地告訴她，「希望你能長命百歲」吧？",
          DialogueId = 80200320,
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          SpeakNpcId = 790008
        },
        [80200321] = {
          ContentTC = "呃……看破不說破嘛，這種小心思說出來就沒勁兒了。我還想看扶疏生氣的樣子呢！",
          DialogueId = 80200321,
          GUID = "C8C5E92A",
          NextDialogue = 80200322,
          SpeakNpcId = 790054
        },
        [80200322] = {
          ContentTC = "快去！快去！",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054
        },
        [80200323] = {
          ContentTC = "出幻境，回到采藥任務點1，和扶疏站樁。",
          DialogueId = 80200323,
          GUID = "C8C5E97E"
        },
        [80200324] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "你醒了！",
          DialogueId = 80200324,
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053
        },
        [80200325] = {
          ContentTC = "才過去三四分鍾，但實在牽腸掛肚……我都懷疑是否記錯了書上的內容，莫非毒性比我想象中大？",
          DialogueId = 80200325,
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          SpeakNpcId = 790053
        },
        [80200326] = {
          ContentTC = "我想給你用枯榮之術，但又怕沒等我施術完畢，你就又好了……",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          SpeakNpcId = 790053
        },
        [80200327] = {
          ContentTC = "噗嗤……你們姐妹倆還真是像……",
          DialogueId = 80200327,
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008
        },
        [80200328] = {
          ContentTC = "你也……見到家姐了？",
          DialogueId = 80200328,
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053
        },
        [80200329] = {
          ContentTC = "沒錯，你記得嗎，她同你吵架，送了你最討厭的壽星烏賊做道歉禮物。",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008
        },
        [80200330] = {
          ContentTC = "……我都已經忘記了。那真是，很久很久以前的往事了。",
          DialogueId = 80200330,
          GUID = "C8C5EAA4",
          NextDialogue = 80200331,
          SpeakNpcId = 790053
        },
        [80200331] = {
          ContentTC = "你接受她的道歉了嗎？",
          DialogueId = 80200331,
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008
        },
        [80200332] = {
          ContentTC = "嗬嗬……沒有，我和她又吵了一架。我雖然不後悔……",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053
        },
        [80200333] = {
          ContentTC = "但或許，現在的我會願意接受那條壽星烏賊。",
          DialogueId = 80200333,
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053
        },
        [80200334] = {
          ContentTC = "……但也只是或許，我不喜歡多足生物，這點千真萬確。",
          DialogueId = 80200334,
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053
        },
        [80200335] = {
          ContentTC = "其實……不應該讓你看到這些往事，過去的人都已經作古，看到這些徒惹傷懷，也是無益。",
          DialogueId = 80200335,
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053
        },
        [80200336] = {
          ContentTC = "只是這枯榮閣是我們從小生長的地方，恐怕所有的音容草裡，都存放著我們的過往。",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053
        },
        [80200337] = {
          ContentTC = "所以下一次，還是由我來嚐試吧，好嗎？",
          DialogueId = 80200337,
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053
        },
        [80200339] = {
          ContentTC = "謝謝。",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200341] = {
          ContentTC = "嗬嗬，下次相約之時，我再講給你聽吧。",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200342] = {
          ContentTC = "好，那去尋找下一個地方吧。",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053
        },
        [80200343] = {
          ContentTC = "轉場，枯榮閣野外",
          DialogueId = 80200343,
          GUID = "C8C5ECC6"
        },
        [80200344] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentTC = "找到了。",
          DialogueId = 80200344,
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053
        },
        [80200345] = {
          ContentTC = "要不要猜一猜，這是音容草，還是懷夢草呢？",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053
        },
        [80200348] = {
          ContentTC = "看著沒什麼殊異之處，但摸在手裡，確實有些極其微妙的差別……我猜這就是我們要找的懷夢草。",
          DialogueId = 80200348,
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          SpeakNpcId = 790053
        },
        [80200349] = {
          ContentTC = "如果不是連續失敗兩次，我恐怕永遠不會有這樣的發現。",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053
        },
        [80200350] = {
          ContentTC = "第一個發現這兩種植物的人是怎麼做到的？難道她也像我們一樣，一點一點試出來的？",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          SpeakNpcId = 790008
        },
        [80200351] = {
          ContentTC = "嗬……是呀，她是怎麼做到的呢？",
          DialogueId = 80200351,
          GUID = "C8C5EE16",
          NextDialogue = 80200352,
          SpeakNpcId = 790053
        },
        [80200352] = {
          ContentTC = "想必，一定經過無數次危險，與無數次不眠不休的鑽研吧，即使不被理解，即使曆經傷痛，她也從來沒有放棄過。",
          DialogueId = 80200352,
          GUID = "C8C5EE40",
          NextDialogue = 80200353,
          SpeakNpcId = 790053
        },
        [80200353] = {
          ContentTC = "一切都是為了從無數個一百年前，一直流傳到今天的那個懸壺濟世的理想。",
          DialogueId = 80200353,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053
        },
        [80200354] = {
          ContentTC = "其實，還有一件事忘了告訴你。我剛才遇見的扶風說，匍地枝與隙中花更合適治療多夢少眠。",
          DialogueId = 80200354,
          GUID = "C8C5EE94",
          NextDialogue = 80200355,
          SpeakNpcId = 790008
        },
        [80200355] = {
          ContentTC = "懷夢草雖能助眠，但會在夢中看到無法忘懷之事。",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          SpeakNpcId = 790008
        },
        [80200356] = {
          ContentTC = "也就是說，我不需要懷夢草了，但即使如此，你也要嚐試嗎？",
          DialogueId = 80200356,
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008
        },
        [80200357] = {
          ContentTC = "扶疏沒有說話，只是照舊將那葉尖放入口中。這一次，沒有不安與責難，你聽到了均勻的呼吸聲，以及一句淺淺的夢囈——",
          DialogueId = 80200357,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358
        },
        [80200358] = {
          ContentTC = "唉……下一次，換個道歉禮物吧。",
          DialogueId = 80200358,
          GUID = "C8C5EF3C",
          SpeakNpcId = 790053
        },
        [88888801] = {
