          DialogueId = 90000022,
          GUID = "E14E3C9C"
        },
        [90000031] = {
          ContentTC = "隨機獲得兩個低稀有度的寶物",
          DialogueId = 90000031,
          GUID = "E14E3E16"
        },
        [90000032] = {
          ContentTC = "隨機獲得一個任意稀有度的寶物",
          DialogueId = 90000032,
          GUID = "E14E3E40"
        },
        [90000041] = {
          ContentTC = "你什麼也沒有得到",
