        },
        [90000062] = {
          ContentTC = "隨機獲得一個低稀有度的寶物",
          DialogueId = 90000062,
          GUID = "E14E432C"
        },
        [90010101] = {
          ContentTC = "嘿咻、嘿咻……",
          DialogueId = 90010101,
          Duration = 3,
          GUID = "E154B232",
          SpeakNpcId = 900001,
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_05"
        },
        [90010201] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentTC = "最近有沒有找到什麼好東西？給老朽看看，說不定能鍛造出一把很特別的武器！",
          DialogueId = 90010201,
          GUID = "E154C29A",
          SpeakNpcId = 900001,
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_02"
        },
        [90010301] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentTC = "是老朽的好友，雖然看起來個子小，但是力氣可不小，老朽便讓它幫忙給爐火鼓風。",
          DialogueId = 90010301,
          GUID = "E154D302",
          SpeakNpcId = 900001
        },
        [90020101] = {
          ContentTC = "早上好……",
          DialogueId = 90020101,
          Duration = 3,
          GUID = "E15B1AD2",
          SpeakNpcId = 900002,
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_03"
        },
        [90020201] = {
          ContentTC = "啊！我、我才沒有偷懶……咳！有什麼想買的嗎？",
          DialogueId = 90020201,
          GUID = "E15B2B3A",
          SpeakNpcId = 900002,
          TalkActionId = {
            [1] = "900002:Shangdian_Write_Start"
          },
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_01"
        },
        [90020301] = {
          ContentTC = "聊點別的",
          DialogueId = 90020301,
          GUID = "E15B3BA2"
        },
        [90020302] = {
          ContentTC = "再見",
          DialogueId = 90020302,
          GUID = "E15B3BCC"
        },
        [90030000] = {
          ContentTC = "{性别:他|她}從來都不是一隻甘願困在籠中的鳥。我知道的，總有一天{性别:他|她}會離開那座島，飛向更遠的天空。但我不知道的是，這對我們來說究竟是幸運還是不幸。",
          DialogueId = 90030000,
          GUID = "E15B3BCB",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_idle"
        },
        [90030001] = {
          ContentTC = "你回來了。今天打算做什麼？還是在家休息？",
          DialogueId = 90030001,
          GUID = "E161730A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 900300011,
            [2] = 900300013,
            [3] = 900300014,
            [4] = 900300015,
            [5] = 900300016,
            [6] = 900300018
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_welcome",
          bForbidSkipOptions = true
        },
        [90030002] = {
          ContentTC = "聊點別的",
          DialogueId = 90030002,
          GUID = "90030002.0",
          NextDialogue = 90030001
        },
        [90030003] = {
          ContentTC = "再見",
          DialogueId = 90030003,
          GUID = "90030003.0"
        },
        [90030101] = {
          ContentTC = "願望？我……沒有什麼特別的願望。每個早上都看見你笑著，就足夠了。",
          DialogueId = 90030101,
          GUID = "E1618372",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030103,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_1"
        },
        [90030103] = {
          ContentTC = "好，我會做到。",
          DialogueId = 90030103,
          GUID = "E16183C6",
          NextDialogue = 90030104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Explain02_End"
          }
        },
        [90030104] = {
          ContentTC = "也不用勉強自己。如果你覺得不開心，就來靠著我說會兒話吧。或者，如果你不想説話的話，我們就一起安靜地待一會兒。",
          DialogueId = 90030104,
          GUID = "E16183F0",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90030301] = {
          ContentTC = "和淨界島不一樣，這座城的每一天都在下雪。不過，還好你有這麼一個溫暖的住處。和我們在淨界島上的破房子相比，這個地方算得上奢侈了。",
          DialogueId = 90030301,
          GUID = "E161A442",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030303,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_1"
        },
        [90030303] = {
          ContentTC = "可我還是覺得有點冷。",
          DialogueId = 90030303,
          GUID = "E161A443",
          NextDialogue = 90030304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Think_End"
          }
        },
        [90030304] = {
          ContentTC = "嗯，以前每到冬天，你的手都會變得很涼……來，手給我，我幫你暖一暖。",
          DialogueId = 90030304,
          GUID = "E161A46C",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90030401] = {
          ContentTC = "為什麼呢……我也不知道。不妨就認為這是一個美好的夢吧——就當作我還在你身邊，像從前一樣。",
          DialogueId = 90030401,
          GUID = "E161B4AA",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030403,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_1"
        },
        [90030403] = {
          ContentTC = "我想再次見到你。",
          DialogueId = 90030403,
          GUID = "E161B4FE",
          NextDialogue = 90030404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81101:Talk02_End"
          }
        },
        [90030404] = {
          ContentTC = "嗯，我也想，非常想……但願有一天，我們能夠真正重逢。",
          DialogueId = 90030404,
          GUID = "E161B528",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90030501] = {
          ContentTC = "應該怎麼說呢，那個地方像一座鋼鐵做的城市……不對，應該說更像是牢獄吧。很小的時候，我是在那兒度過的。",
          DialogueId = 90030501,
          GUID = "E161C512",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030503,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_1"
        },
        [90030503] = {
          ContentTC = "後來一個人帶著我逃走了。被她一同帶到淨界島的，還有你。只是關於她的事，我不能說更多了……抱歉。我答應過她不說。",
          DialogueId = 90030503,
          GUID = "E161C566",
          NextDialogue = 90030504,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_2"
        },
        [90030504] = {
          ContentTC = "……在淨界島的日子是那麼平靜，我差點以為我們會一輩子這樣生活下去。但那天，他們再次出現的時候，我才發覺我從未真正逃離那個牢獄。",
          DialogueId = 90030504,
          GUID = "E161C590",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90030601] = {
          ContentTC = "是有些吵鬧，不過，我並不討厭。你結識了許多新的朋友，這是好事，我為你高興。",
          DialogueId = 90030601,
          GUID = "E161D57A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030603,
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_1"
        },
        [90030603] = {
          ContentTC = "這樣一來，就算我不在你身邊，你也不會覺得孤單了。",
          DialogueId = 90030603,
          GUID = "E161D5A4",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90030801] = {
          ContentTC = "那就枕在我身上歇息一會兒吧，像從前那樣。",
          DialogueId = 90030801,
          GUID = "E161F64A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_06_1",
          bForbidSkipOptions = true
        },
        [90030901] = {
          ContentTC = "這些年來，我有好好照顧{性别:他|她}，也有好好保重自己，就像我答應你的……你可以像我小時候那樣，摸摸我的頭，誇誇我嗎？還有，這一次，再也不要離開我們了……好嗎？",
          DialogueId = 90030901,
          GUID = "E16206B2",
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_01"
        },
        [90031001] = {
          ContentTC = "松露小姐，你的……豬，我可以摸一摸嗎？摸一下就好。請你幫我按住它，我怕它跑遠了，小動物看到我總會跑得遠遠的。",
          DialogueId = 90031001,
          GUID = "E162171A",
          NextDialogue = 90031002,
          SpeakNpcId = 81101,
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_1"
        },
        [90031002] = {
          ContentTC = "謝謝你……啊，暖暖的，真好啊……",
          DialogueId = 90031002,
          GUID = "E1621744",
