          VoiceName = "voice/$Locale$/char/Shuimu/vo_idle"
        },
        [90040001] = {
          ContentTC = "我從睡醒就一直在這裡等著，體內的毒液都快乾涸了……不過還好你來了，現在它們又開始因為興奮而跳動。你……可以再靠近一些嗎？",
          DialogueId = 90040001,
          GUID = "E167DBAA",
          LookAt = {
