          GUID = "90040003.0"
        },
        [90040101] = {
          ContentTC = "是的，我喜歡雨天，我讀了許多遍的小說裡，愛的邂逅總是在下雨天自然發生。",
          DialogueId = 90040101,
          GUID = "E167EC12",
          LookAt = {
            [1] = "82101:n(0)",
