          NextDialogue = 90040103,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_1"
        },
        [90040103] = {
          ContentTC = "下雨天應該更適合家裡睡覺吧，為什麼會有邂逅？",
          DialogueId = 90040103,
          GUID = "E167EC13",
          NextDialogue = 90040104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "82101:Explain02_End"
          }
        },
        [90040104] = {
          ContentTC = "你留心觀察過那些躲雨的人嗎？他們在屋簷下不期而遇，潮濕的氣息讓草木的芳香更加馥郁，小心的試探使愛意緩緩流動……",
          DialogueId = 90040104,
          GUID = "E167EC3C",
          NextDialogue = 90040105,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_2"
        },
        [90040105] = {
          ContentTC = "呵呵……等到下個雨天，您同我一起出去瞧瞧，就會明白的。",
          DialogueId = 90040105,
          GUID = "E167EC3B",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90040201] = {
          ContentTC = "啊呀，難得你居然會和我主動談論「愛」。",
          DialogueId = 90040201,
          GUID = "E167FC7A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040203,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Shock_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_1"
        },
        [90040203] = {
          ContentTC = "應該如何描述呢……嗯，就像這香薰中的水：親吻擁抱每一劑原料，吞噬汲取它們的氣味，並最終在長久的馥郁中合為一體。",
          DialogueId = 90040203,
          GUID = "E167FCA4",
          NextDialogue = 90040204,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Shock_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_2"
        },
        [90040204] = {
          ContentTC = "聽起來是兩個人每天膩在一起？",
          DialogueId = 90040204,
          GUID = "E167FCA5",
          NextDialogue = 90040205,
          SpeakNpcId = 100001
        },
        [90040205] = {
          ContentTC = "不止哦。我想要的愛情，是徹底的交融，沒有彼此之分……即使一方生命終結了，也會成為香料園中的花泥；從中綻放的花朵將變成香薰，永遠縈繞著另一個。",
          DialogueId = 90040205,
          GUID = "E167FCA6",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90040301] = {
          ContentTC = "特別？啊，是的……從小到大，身邊可有不少人視我為「怪物」呢。",
          DialogueId = 90040301,
          GUID = "E1680CE2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040303,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_1"
        },
        [90040303] = {
          ContentTC = "他們每次看到我都會露出厭惡的表情，不過那樣的表情可不好看，得想辦法糾正一下呢……",
          DialogueId = 90040303,
          GUID = "E1680D36",
          NextDialogue = 90040304,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_2"
        },
        [90040304] = {
          ContentTC = "若是刺痛他們的臉，讓毒素滲透進他們的肌膚，那張嫌惡的臉，也一定會變得溫柔起來吧……呵呵。",
          DialogueId = 90040304,
          GUID = "E1680D60",
          NextDialogue = 90040305,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_3"
        },
        [90040305] = {
          ContentTC = "那麼話說回來，你說的「特別」指的又是哪種「特別」？「特別」像個怪物……還是，「特別」令人傾心？",
          DialogueId = 90040305,
          GUID = "E1680D8A",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90040401] = {
          ContentTC = "不，不會的，這份毒與生俱來，像是愛之神賜給我的禮物，不會傷害我，只會幫助我找到命定的戀人。",
          DialogueId = 90040401,
          GUID = "E1681D4A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040403,
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_1"
        },
        [90040403] = {
          ContentTC = "聽起來你還挺喜歡這份禮物的？",
          DialogueId = 90040403,
          GUID = "E1681D4B",
          NextDialogue = 90040404,
          SpeakNpcId = 100001
        },
        [90040404] = {
          ContentTC = "是啊，雖然容易失控的毒液總讓我被當做怪物，但也讓我和其他人不同。所以我堅信，一個怪物的命定之人，也一定很特別，你說對嗎？",
          DialogueId = 90040404,
          GUID = "E1681D74",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90040501] = {
          ContentTC = "是我自製的香薰哦，前調如同初遇一般濃烈，中調則是用來定香的甜言蜜語，最後的尾調，是散不去的回味再加一點苦澀。",
          DialogueId = 90040501,
          GUID = "E1682DB2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040503,
          SpeakNpcId = 82101,
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_1"
        },
        [90040503] = {
          ContentTC = "那，具體成分是什麼呢？",
          DialogueId = 90040503,
          GUID = "E1682E06",
          NextDialogue = 90040504,
          SpeakNpcId = 100001
        },
        [90040504] = {
          ContentTC = "秘密喲，當然，我也可以親手教你如何調製，從始至終，一步一步。",
          DialogueId = 90040504,
          GUID = "E1682E30",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90040601] = {
          ContentTC = "……這個乾燥的氣息，原來是你啊。好久不見，你還是想把我拷走嗎？嗯！可以哦。\n畢竟，即使重來一遍，重來多少遍，我依舊能夠從你掌心逃脫……你、相、信、嗎？海爾法大人。",
          DialogueId = 90040601,
          GUID = "E1683E1A",
          SpeakNpcId = 82101,
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_01"
        },
        [90040701] = {
          ContentTC = "你害怕我嗎？那我會讓你喜歡上我的，來聞一聞我調配的香薰吧，很甜的，保證你能體會到前所未有的幸福。",
          DialogueId = 90040701,
          GUID = "E1684E82",
          SpeakNpcId = 82101,
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_02"
        },
        [90040801] = {
          ContentTC = "你也是個怪人呢，感受彼此帶來的傷害，品味甜蜜的痛感，再果斷地殺掉對方？呵呵(輕笑)，我知道你為什麼這麼做，這一定也是你表達愛的方式。",
          DialogueId = 90040801,
          GUID = "E1685EEA",
          SpeakNpcId = 82101,
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_03"
        },
        [90050000] = {
          ContentTC = "……喂……喂，放我出去玩啦！閒得我觸手都要僵了！",
