        },
        [90050405] = {
          ContentTC = "遲早有一天，人們提到「惡魔」，就只會想到厲害的我，怎麼樣，是很偉大的夢想吧！",
          DialogueId = 90050405,
          GUID = "E16E85ED",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90050501] = {
          ContentTC = "要抓我？我又不是壞人！不就是順了點東西嗎，還是小偷的東西……哇，你不要過來啊！好熱！",
          DialogueId = 90050501,
          GUID = "E16E9652",
          SpeakNpcId = 82301,
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_01"
        },
        [90050601] = {
          ContentTC = "送我香薰？唔，你看起來就好危險，我不要我不要！等等……這個香薰聞起來，怎麼讓人感覺飄飄的……我的觸手怎麼麻麻的……你果然很危險！",
          DialogueId = 90050601,
          GUID = "E16EA6BA",
          SpeakNpcId = 82301,
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_02"
        },
        [90050701] = {
          ContentTC = "你對著劍說話的樣子好好玩！薩麥爾，你喜歡這個地方嗎，我們還要一起去更多的地方哦！\n嗯……？你怎麼在那裡幹憋氣不出聲，這樣子更好玩了嘻嘻嘻！",
          DialogueId = 90050701,
          GUID = "E16EB722",
          SpeakNpcId = 82301,
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_03"
        },
        [90060000] = {
          ContentTC = "真是愜意自得……不害怕我的煉火嗎？哈，無知的螻蟻，或許把你踩在腳下時你才會後悔。",
          DialogueId = 90060000,
          GUID = "E174ACE9",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_idle"
        },
        [90060001] = {
          ContentTC = "今天準備好接受拷問了嗎？！",
          DialogueId = 90060001,
          GUID = "E174ACEA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextOptions = {
            [1] = 900600011,
            [2] = 900600012,
            [3] = 900600013,
            [4] = 900600014,
            [5] = 900600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_welcome",
          bForbidSkipOptions = true
        },
        [90060002] = {
          ContentTC = "聊點別的",
          DialogueId = 90060002,
          GUID = "90060002.0",
          NextDialogue = 90060001
        },
        [90060003] = {
          ContentTC = "再見",
          DialogueId = 90060003,
          GUID = "90060003.0"
        },
        [90060101] = {
          ContentTC = "如果你熟讀歷史的話，就會知道，皇家軍事監獄的初代典獄長也有著熔岩一般的皮膚，再兇惡的罪徒也會畏懼她的拷問。",
          DialogueId = 90060101,
          GUID = "E174BD52",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060102,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_1"
        },
        [90060102] = {
          ContentTC = "而我，作為她的後代，繼承了她的名號，同樣會用煉火將一切罪行燒成爐灰。",
          DialogueId = 90060102,
          GUID = "E174BD53",
          NextDialogue = 90060103,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_2"
        },
        [90060103] = {
          ContentTC = "那……你滾燙的皮膚會不會讓你生活不太方便？",
          DialogueId = 90060103,
          GUID = "E174BD54",
          NextDialogue = 90060104,
          SpeakNpcId = 100001
        },
        [90060104] = {
          ContentTC = "有一些影響，我只能睡在鐵製的床上，也不能在木頭屋子裡待上太久。但與之相對地，我能在火場裡把罪犯帶出來讓他們直面法律，也從不怕冷。",
          DialogueId = 90060104,
          GUID = "E174BD55",
          NextDialogue = 90060105,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_3"
        },
        [90060105] = {
          ContentTC = "異於常人的外表於我而言，更像是一份饋贈，非要說有什麽不方便的……我一直想嘗一嘗那種叫做冰激淩的甜品，但它總是在我手上就化掉了……",
          DialogueId = 90060105,
          GUID = "E174BD56",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90060201] = {
          ContentTC = "從帝國誕生起，我的家族就世代執掌著關押罪大惡極的犯人們的牢獄，理清冤罪，或是斬除禍患。",
          DialogueId = 90060201,
          GUID = "E174CDBA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060202,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_1"
        },
        [90060202] = {
          ContentTC = "而我與生俱來和先祖同樣的火紅膚色，就註定了我要拿起她留下的鐵鑄法典。所以並非是我選擇成為典獄長，而是典獄長的頭銜選擇了我。",
          DialogueId = 90060202,
          GUID = "E174CDBB",
          NextDialogue = 90060203,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_2"
        },
        [90060203] = {
          ContentTC = "這麽說你已經實現了自己的願望？",
          DialogueId = 90060203,
          GUID = "E174CDBC",
          NextDialogue = 90060204,
          SpeakNpcId = 100001
        },
        [90060204] = {
          ContentTC = "成為典獄長並非願望的終點，相反，這只是一個開始，它意味著我需要時刻保持戒備和警醒一一斬除帝國土地上孳生的任何不義，直到死亡將我熄滅。",
          DialogueId = 90060204,
          GUID = "E174CDBD",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90060301] = {
          ContentTC = "那當然，帝國監獄裡多的是難纏的犯人，審訊案件、查閱卷宗、防止那些狡猾的老鼠設法逃走都是典獄長的職責所在。",
          DialogueId = 90060301,
          GUID = "E174DE22",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060302,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_1"
        },
        [90060302] = {
          ContentTC = "每休息一分，都會讓正義遲到一分——而當正義遲遲不來時，混亂與弱肉強食就會代替法條成為新的規則。",
          DialogueId = 90060302,
          GUID = "E174DE23",
          NextDialogue = 90060303,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_2"
        },
        [90060303] = {
          ContentTC = "如果監獄裡的犯人越來越少，你會不會輕松一點。",
          DialogueId = 90060303,
          GUID = "E174DE24",
          NextDialogue = 90060304,
          SpeakNpcId = 100001
        },
        [90060304] = {
          ContentTC = "確實有學者設想過沒有罪犯的世界。如果真的有那天，我也將不復存在，因為正是罪惡造就了典獄長。但是在那之前，我會盡力維護好現存的秩序。",
          DialogueId = 90060304,
          GUID = "E174DE25",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90060401] = {
          ContentTC = "正義？正義是權力約束慾望，力量桎梏罪孽，強者鞭撻惡徒。",
          DialogueId = 90060401,
          GUID = "E174EE8A",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060402,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_1"
        },
        [90060402] = {
          ContentTC = "這樣的規則也太絕對了吧。",
          DialogueId = 90060402,
          GUID = "E174EE8B",
          NextDialogue = 90060403,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83201:Explain01_End"
          }
        },
        [90060403] = {
          ContentTC = "哼，絕對？不然呢，天真的小朋友，難道指望人人都手拉手過家家？絕對的力量、絕對的秩序，這就是我的正義！",
          DialogueId = 90060403,
          GUID = "E174EE8C",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90060501] = {
          ContentTC = "帝國的罪犯還在滿大街地跑，身為典獄長哪有什麽閑暇時間。只能在忙裡偷閒的時候，喝幾杯烈酒。",
          DialogueId = 90060501,
          GUID = "E174FEF2",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060502,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_1"
        },
        [90060502] = {
          ContentTC = "什麽！你會喝酒？",
          DialogueId = 90060502,
          GUID = "E174FF1C",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060503,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83201:Talk01_End"
          }
        },
        [90060503] = {
          ContentTC = "怎麽，很驚訝？消遣而已：審訊時總會聽到各種酒的名字，就開始好奇，這到底是什麽邪惡藥水，總是和犯罪沾邊，於是偶爾會來上一些。",
          DialogueId = 90060503,
          GUID = "E174FF1D",
          NextDialogue = 90060504,
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_2"
        },
        [90060504] = {
          ContentTC = "喝得越多，我越是確信，邪惡的並不是酒。",
          DialogueId = 90060504,
          GUID = "E174FF1E",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90060601] = {
          ContentTC = "典獄長和軍團長，都是帝國「黑暗」秩序的維護者。我們心狠手辣、聲名狼藉——但是為了海伯利亞，這點惡名又算得上什麽？！",
          DialogueId = 90060601,
          GUID = "E1750F5A",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_01"
        },
        [90060701] = {
          ContentTC = "又是你。",
          DialogueId = 90060701,
          GUID = "E1751FC2",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_02"
        },
        [90060801] = {
          ContentTC = "嘖，西比爾的副官……那個總被指責不盡職的傢伙，對吧？可惜，你那些隱藏實力的拙劣技巧瞞不過我的眼睛！藏匿鋒芒混跡在軍團長身邊，你到底有什麽居心？！",
          DialogueId = 90060801,
          GUID = "E175302A",
          SpeakNpcId = 83201,
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_03"
        },
        [90070000] = {
          ContentTC = "無事，便是好事。",
          DialogueId = 90070000,
          GUID = "E17B1589",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_idle"
        },
        [90070001] = {
          ContentTC = "趁著你還沒有被各種律法束縛，想做什麼事情，就去做吧。",
          DialogueId = 90070001,
          GUID = "E17B158A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextOptions = {
            [1] = 900700011,
            [2] = 900700012,
            [3] = 900700013,
            [4] = 900700014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_welcome",
          bForbidSkipOptions = true
        },
        [90070002] = {
          ContentTC = "聊點別的",
          DialogueId = 90070002,
          GUID = "90070002.0",
          NextDialogue = 90070001
        },
        [90070003] = {
          ContentTC = "再見",
          DialogueId = 90070003,
          GUID = "90070003.0"
        },
        [90070101] = {
          ContentTC = "……這等閒聊，有更適合的人選吧。找那些販賣貨物的織星客吧，或者看看書也好。",
          DialogueId = 90070101,
          GUID = "E17B25F2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070102,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_1"
        },
        [90070102] = {
          ContentTC = "每個人眼中的世界各不相同，我是在問你的看法。",
          DialogueId = 90070102,
          GUID = "E17B25F3",
          NextDialogue = 90070103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Talk03_End"
          }
        },
        [90070103] = {
          ContentTC = "我平素繁忙，所以眼見多有偏狹。你若是真的好奇，與其假他人言語，不如親自踏足那裡，如何？",
          DialogueId = 90070103,
          GUID = "E17B25F4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90070201] = {
          ContentTC = "《大風九章》是華胥的律法，誰都不能違抗。但倘若真要有人倒反天命，那自然要有人去收拾亂局。",
          DialogueId = 90070201,
          GUID = "E17B365A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070202,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_1"
        },
        [90070202] = {
          ContentTC = "那麼你一定很受崇敬吧。",
          DialogueId = 90070202,
          GUID = "E17B365B",
          NextDialogue = 90070203,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Explain01_End"
          }
        },
        [90070203] = {
          ContentTC = "……也許吧，我不常與人們閒談，畢竟但凡需要我出手的地方，總有傷逝。大部華胥之民，是並不樂見我的。",
          DialogueId = 90070203,
          GUID = "E17B365C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90070301] = {
          ContentTC = "無事可樂，自然如此。",
          DialogueId = 90070301,
          GUID = "E17B46C2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070302,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_1"
        },
        [90070302] = {
          ContentTC = "也許我可以分享你的煩惱。",
          DialogueId = 90070302,
          GUID = "E17B46C3",
          NextDialogue = 90070303,
          SpeakNpcId = 100001
        },
        [90070303] = {
          ContentTC = "謝了，但是說與你聽，也不過是徒然讓這世上又多了一個煩惱之人，何必。",
          DialogueId = 90070303,
          GUID = "E17B46C4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90070401] = {
          ContentTC = "是啊，月亮很好，很好。無論前一天發生過什麼，杯盤狼籍還是血濺五步，月光都能洗淨一切。不管過去多久，天邊的一角總是會為你留下一彎月亮。",
          DialogueId = 90070401,
          GUID = "E17B572A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070402,
          SpeakNpcId = 84201,
          TalkActionId = {
            [1] = "84201:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_1"
        },
        [90070402] = {
          ContentTC = "你在想過去的事？",
          DialogueId = 90070402,
          GUID = "E17B572B",
          NextDialogue = 90070403,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84201:Talk02_End"
          }
        },
        [90070403] = {
          ContentTC = "不，我是與過去訣別之人，沒有過去，只是今天多喝了半杯酒而已。",
          DialogueId = 90070403,
          GUID = "E17B572C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90070501] = {
          ContentTC = "雖然不知道你告別了怎樣的過去，但我們氣息相似，保持距離吧：我並不喜歡同類。",
          DialogueId = 90070501,
          GUID = "E17B6792",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_01"
        },
        [90070601] = {
          ContentTC = "我早已不是你的故知。世人萍水相逢本就如風過耳，放下吧。",
          DialogueId = 90070601,
          GUID = "E17B77FA",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_02"
        },
        [90070701] = {
          ContentTC = "我羡慕你的意志與同樣堅固的法條，不知道你可有過什麼時刻，曾自我懷疑過。",
          DialogueId = 90070701,
          GUID = "E17B8862",
          SpeakNpcId = 84201,
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_03"
        },
        [90080000] = {
          ContentTC = "嗯……這個自動繞後的折疊槍可以升級成連發的……火力也可以再猛一些……嗯，不錯不錯，下次出任務就可以更快地解決敵人，然後回家休息了。",
          DialogueId = 90080000,
          GUID = "E1817E29",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_idle"
        },
        [90080001] = {
          ContentTC = "呼~剛睡醒的感覺好舒爽啊，你呀，也不要每天太緊繃了，任務是永遠也做不完的，要懂得休息。",
          DialogueId = 90080001,
          GUID = "E1817E2A",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextOptions = {
            [1] = 900800011,
            [2] = 900800012,
            [3] = 900800013,
            [4] = 900800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90080002] = {
          ContentTC = "聊點別的",
          DialogueId = 90080002,
          GUID = "90080002.0",
          NextDialogue = 90080001
        },
        [90080003] = {
          ContentTC = "再見",
          DialogueId = 90080003,
          GUID = "90080003.0"
        },
        [90080101] = {
          ContentTC = "家裡人？我爸媽都好多年沒管過我了，也就兩位姐姐偶爾會對我指手畫腳，不過啊我現在進了軍團，她們進不來。",
          DialogueId = 90080101,
          GUID = "E1818E92",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080103,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_1"
        },
        [90080103] = {
          ContentTC = "聽起來你的姐姐們很凶。",
          DialogueId = 90080103,
          GUID = "E1818EE6",
          NextDialogue = 90080104,
          SpeakNpcId = 100001
        },
        [90080104] = {
          ContentTC = "不，不是的，她們都是潑可愛動人聰明賢慧溫柔樂觀善良積極天真爛漫落落大方的美人！不過，如果能端莊一點就更好了……",
          DialogueId = 90080104,
          GUID = "E1818F10",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90080201] = {
          ContentTC = "呵，你們這些不懂休息好的人有難了！聽我說：床是撫慰心靈的港灣，屋頂是洗滌靈魂的聖地，午後的花園是光明降臨的方向，小憩的時刻是甜蜜的交響詩……",
          DialogueId = 90080201,
          GUID = "E1819EFA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080203,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_1"
        },
        [90080203] = {
          ContentTC = "（轉身離開。）",
          DialogueId = 90080203,
          GUID = "E1819F4E",
          NextDialogue = 90080204,
          SpeakNpcId = 100001
        },
        [90080204] = {
          ContentTC = "……誒！你等我念完啊！",
          DialogueId = 90080204,
          GUID = "E1819F78",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90080301] = {
          ContentTC = "她可太能使喚人了，一個人劈三份都不夠用……咳，我是說，西比爾大人作為長官，對下屬一向嚴格。",
          DialogueId = 90080301,
          GUID = "E181AF62",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080303,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_1"
        },
        [90080303] = {
          ContentTC = "改口也沒用，我已經聽到了。",
          DialogueId = 90080303,
          GUID = "E181AFB6",
          NextDialogue = 90080304,
          SpeakNpcId = 100001
        },
        [90080304] = {
          ContentTC = "哎呀，這可怎麼辦才好呢……要不，我請你一份下午茶，你就當什麼都沒有聽見，怎麼樣？別擔心，裡面沒有下藥。",
          DialogueId = 90080304,
          GUID = "E181AFE0",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90080401] = {
          ContentTC = "我給你設計了一個好東西，一個小型機器人偶！戰鬥的時候它可以跟在你後面一邊搖小旗，一邊大喊「加油！」「你揍人的樣子真的很酷！」",
          DialogueId = 90080401,
          GUID = "E181BFCA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080403,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_1"
        },
        [90080403] = {
          ContentTC = "怎麼樣，是不是感覺渾身充滿力量？等我把它做出來……",
          DialogueId = 90080403,
          GUID = "E181BFF4",
          NextDialogue = 90080404,
          SpeakNpcId = 84202,
          TalkActionId = {
            [1] = "84202:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_2"
        },
        [90080404] = {
          ContentTC = "（轉身離開。）",
          DialogueId = 90080404,
          GUID = "E181BFF5",
          NextDialogue = 90080405,
          SpeakNpcId = 100001
        },
        [90080405] = {
          ContentTC = "喂喂，別走啊，圖紙可是我瞞著西比爾長官，用寶貴的休息時間畫的——",
          DialogueId = 90080405,
          GUID = "E181BFF6",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90080501] = {
          ContentTC = "報告軍團長，今日的工作已經安排完畢，您如果有其他的需要，可以隨時下達指示。不過今日的工作已經很飽和了，您還是要注意歇息，不要再給自己增添額外的負擔了。",
          DialogueId = 90080501,
          GUID = "E181D032",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_01"
        },
        [90080601] = {
          ContentTC = "上次的任務真是辛苦你了，不過我接到了一些投訴，說是你在執行任務中損壞公物，唉，你是知道我的，我這麼羞澀內向，還要替你去賠不是，這也太難為我了。所以……這幾個緊急任務就麻煩你代勞了，相信美麗善良和藹可親的琳恩小姐一定不會拒絕的吧！",
          DialogueId = 90080601,
          GUID = "E181E09A",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_02"
        },
        [90080701] = {
          ContentTC = "嗯，你怎麼會……？哎呀，看來我還是休息太少，竟然都出現幻覺，能看見不存在的人了！之後向長官打個工傷報告，再休兩天病假好了。",
          DialogueId = 90080701,
          GUID = "E181F102",
          SpeakNpcId = 84202,
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_03"
        },
        [90090000] = {
          ContentTC = "居然把後背輕易暴露給自己的敵人…… 該說你天真還是愚蠢？",
          DialogueId = 90090000,
          GUID = "E187E6C9",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_idle"
        },
        [90090001] = {
          ContentTC = "看到你日復一日這樣奔波努力，我就忍不住開始想像，想像你再次挑戰我的那一天，讓人期待。",
          DialogueId = 90090001,
          GUID = "E187E6CA",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextOptions = {
            [1] = 900900011,
            [2] = 900900012,
            [3] = 900900013,
            [4] = 900900014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90090002] = {
          ContentTC = "聊點別的",
          DialogueId = 90090002,
          GUID = "90090002.0",
          NextDialogue = 90090001
        },
        [90090003] = {
          ContentTC = "再見",
          DialogueId = 90090003,
          GUID = "90090003.0"
        },
        [90090101] = {
          ContentTC = "直屬於皇帝的特殊軍團，執行機密的任務，以及作為戰場上隨時擊出的鐵錘。",
          DialogueId = 90090101,
          GUID = "E187F732",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090103,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_1"
        },
        [90090103] = {
          ContentTC = "有皇帝在背後支持，難怪這麼蠻橫。",
          DialogueId = 90090103,
          GUID = "E187F786",
          NextDialogue = 90090104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84301:Talk03_End"
          }
        },
        [90090104] = {
          ContentTC = "你誤會了。沒有皇帝，軍團依舊是軍團，但沒有軍團，皇冠可就要落地了。",
          DialogueId = 90090104,
          GUID = "E187F7B0",
          NextDialogue = 90090105,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_2"
        },
        [90090105] = {
          ContentTC = "憑這句話，我是不是可以檢舉你打算謀反？",
          DialogueId = 90090105,
          GUID = "E187F7DA",
          NextDialogue = 90090106,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84301:Confident_Start"
          }
        },
        [90090106] = {
          ContentTC = "你大可以這麼做，畢竟謀逆可是重罪，然後你的狀告書會立刻被逐級上報，最後呈到我的書桌上。",
          DialogueId = 90090106,
          GUID = "E187F804",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90090201] = {
          ContentTC = "呵，我並非忠於帝國，只是忠於理想罷了。曾有一個人為了這個理想付出了他的一切，而我要銘記與踐行他的意志。",
          DialogueId = 90090201,
          GUID = "E188079A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090203,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_1"
        },
        [90090203] = {
          ContentTC = "你在詭辯。不管原因為何，你的所作所為就是為虎作倀。",
          DialogueId = 90090203,
          GUID = "E18807EE",
          NextDialogue = 90090204,
          SpeakNpcId = 100001
        },
        [90090204] = {
          ContentTC = "我不否認，不過為了我想要的，我會抓緊能利用的一切，不擇手段地往上爬。但我每爬一步，都離我的理想更近一步。而你，又走到了哪一步呢？",
          DialogueId = 90090204,
          GUID = "E1880818",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90090301] = {
          ContentTC = "沒關係，我的家人很早就不在了。",
          DialogueId = 90090301,
          GUID = "E1881802",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090303,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_1"
        },
        [90090303] = {
          ContentTC = "…………",
          DialogueId = 90090303,
          GUID = "E1881856",
          NextDialogue = 90090304,
          SpeakNpcId = 100001
        },
        [90090304] = {
          ContentTC = "我甚至為此慶倖，這樣一來我就沒有了後顧之憂，只需要專心和正面與背面的敵人們廝殺。",
          DialogueId = 90090304,
          GUID = "E1881880",
          NextDialogue = 90090305,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_2"
        },
        [90090305] = {
          ContentTC = "情感，對於每一個踏入軍團的人來說，都是破綻罷了。",
          DialogueId = 90090305,
          GUID = "E18818AA",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90090401] = {
          ContentTC = "當然，當面的咒駡和揶揄我已經聽過不少，陰溝裡的碩鼠們的抱怨只會更多。",
          DialogueId = 90090401,
          GUID = "E188286A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090403,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_1"
        },
        [90090403] = {
          ContentTC = "所幸，儘管這個世界有萬般不公，但只要坐擁眾人之上的力量，就能獲得最起碼的善意。",
          DialogueId = 90090403,
          GUID = "E18828BE",
          NextDialogue = 90090404,
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_2"
        },
        [90090404] = {
          ContentTC = "那麼如果你失去了力量，他們一定會落井下石。",
          DialogueId = 90090404,
          GUID = "E18828E8",
          NextDialogue = 90090405,
          SpeakNpcId = 100001
        },
        [90090405] = {
          ContentTC = "那是自然，所以我永遠不會對他們卑躬屈膝，否則，他們會立刻變成聞到血腥味的狼群。",
          DialogueId = 90090405,
          GUID = "E1882912",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90090501] = {
          ContentTC = "……你與我，是時候做個了斷了。",
          DialogueId = 90090501,
          GUID = "E18838D2",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_01"
        },
        [90090601] = {
          ContentTC = "你和我踏上的道路完全相反，曾經我也自我懷疑過，是否你是對的。可惜，你的名字只能作為敗者而流傳。",
          DialogueId = 90090601,
          GUID = "E188493A",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_02"
        },
        [90090701] = {
          ContentTC = "如果您不是他的繼承者……我手中的劍，早就已經貫穿了您的心臟。",
          DialogueId = 90090701,
          GUID = "E18859A2",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_03"
        },
        [90090801] = {
          ContentTC = "你的偽裝越是完美，就說明你的獠牙在暗地裡打磨得越發鋒銳，我等著你脫韁的那一天，親手敲斷你的大牙。",
          DialogueId = 90090801,
          GUID = "E1886A0A",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_04"
        },
        [90091001] = {
          ContentTC = "近期的任務說明、作戰計畫、後勤運輸、損失條目都整理好了嗎。\n好，那今天再和我把對外宣傳標語、對內案例分析、對皇帝的定期報告以及佩劍煉金院新武器的測試數據做完。工作，可不能叫額外的負擔。",
          DialogueId = 90091001,
          GUID = "E1888ADA",
          SpeakNpcId = 84301,
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_05"
        },
        [90100000] = {
          ContentTC = "什麼都不做，只是就這樣看著大家，就感覺過得好快好快……真希望時間能走慢一點兒呀。",
          DialogueId = 90100000,
          GUID = "E18E4F69",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_idle"
        },
        [90100001] = {
          ContentTC = "太好了，今天我還在這兒。而且，你也在這兒……",
          DialogueId = 90100001,
          GUID = "E18E4F6A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextOptions = {
            [1] = 901000011,
            [2] = 901000012,
            [3] = 901000013,
            [4] = 901000014,
            [5] = 901000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90100002] = {
          ContentTC = "聊點別的",
          DialogueId = 90100002,
          GUID = "90100002.0",
          NextDialogue = 90100001
        },
        [90100003] = {
          ContentTC = "再見",
          DialogueId = 90100003,
          GUID = "90100003.0"
        },
        [90100101] = {
          ContentTC = "謝謝，著涼的話不用擔心啦，卡戎之民是不怎麼怕冷的，正好也不用再去買又厚又貴的大衣。",
          DialogueId = 90100101,
          GUID = "E18E5FD2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100103,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_1"
        },
        [90100103] = {
          ContentTC = "現在的衣服是媽媽幫我裁的，不過顏色是我自己選的，嫩綠色，這些蝴蝶形狀的裝飾也是我自己挑的，如果在暖和的南方的話，這一身應該就不奇怪了。",
          DialogueId = 90100103,
          GUID = "E18E6026",
          NextDialogue = 90100104,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_2"
        },
        [90100104] = {
          ContentTC = "原來是這樣，蝴蝶裝飾確實很適合你。",
          DialogueId = 90100104,
          GUID = "E18E6050",
          NextDialogue = 90100105,
          SpeakNpcId = 100001
        },
        [90100105] = {
          ContentTC = "真的嗎？太好了。其實我只見過冰湖城附近的蝴蝶，都是藍色的。要是能去其他地方，看一看不同顏色的蝴蝶就好了。",
          DialogueId = 90100105,
          GUID = "E18E607A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90100201] = {
          ContentTC = "是的，據說幾百年來一直都是這個樣子。人們看到我們總像看到老鼠一樣，我自己也被人追著罵過很難聽的話。",
          DialogueId = 90100201,
          GUID = "E18E703A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100203,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_1"
        },
        [90100203] = {
          ContentTC = "因為索拉畏懼卡戎的力量？",
          DialogueId = 90100203,
          GUID = "E18E708E",
          NextDialogue = 90100204,
          SpeakNpcId = 100001
        },
        [90100204] = {
          ContentTC = "或許吧。「魔法是最邪惡的東西」，大家總是這麼說。歷史書上也寫著，卡戎之民的先祖在一千多年前，曾經憑藉魔法支配索拉之民，做出了很多惡事。",
          DialogueId = 90100204,
          GUID = "E18E70B8",
          NextDialogue = 90100205,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_2"
        },
        [90100205] = {
          ContentTC = "說實話我有點難想像……因為我看到的卡戎們都很害怕索拉之民，不太敢和他們說話，在他們面前總是小心翼翼的，更不敢使用魔法。",
          DialogueId = 90100205,
          GUID = "E18E70E2",
          NextDialogue = 90100206,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_3"
        },
        [90100206] = {
          ContentTC = "而且其實大多數卡戎魔法都很尋常，也就是能用來點點壁爐，冰凍一下食物之類的。",
          DialogueId = 90100206,
          GUID = "E18E710C",
          NextDialogue = 90100207,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_4"
        },
        [90100207] = {
          ContentTC = "你會想回到那個時代嗎－－卡戎之民支配索拉之民的時代？",
          DialogueId = 90100207,
          GUID = "E18E7136",
          NextDialogue = 90100208,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85301:Talk01_End"
          }
        },
        [90100208] = {
          ContentTC = "不，一點也不。為什麼卡戎之民和索拉之民之間，一定要一個支配另一個，一個畏懼另一個呢？",
          DialogueId = 90100208,
          GUID = "E18E7160",
          NextDialogue = 90100209,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_5"
        },
        [90100209] = {
          ContentTC = "我希望的只是……到了春天，所有人都能一起肩並著肩，一起去原野上看各種各樣的花。只要這樣就夠了。",
          DialogueId = 90100209,
          GUID = "E18E718A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90100301] = {
          ContentTC = "啊，大概是因為我在試著培育新的花朵。修普諾斯之家前面的庭院只有幾棵樹，總覺得有點兒光禿禿的。所以，我想在那裡種滿白色的花……",
          DialogueId = 90100301,
          GUID = "E18E80A2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100303,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_1"
        },
        [90100303] = {
          ContentTC = "在這裡也種一點吧，鈴蘭，銀蓮，仙女木……哪種更合適呢？",
          DialogueId = 90100303,
          GUID = "E18E80F6",
          NextDialogue = 90100304,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_2"
        },
        [90100304] = {
          ContentTC = "也許可以問問大家的意見。",
          DialogueId = 90100304,
          GUID = "E18E8120",
          NextDialogue = 90100305,
          SpeakNpcId = 100001
        },
        [90100305] = {
          ContentTC = "你說得對，應該讓大家一起決定……我會去問問看的！啊，對了，這些花裡有你喜歡的品種嗎？等花開了，我摘一些送給你吧。",
          DialogueId = 90100305,
          GUID = "E18E814A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90100401] = {
          ContentTC = "嗯，我從出生起就一直住在這裡，雖然每天都能聽到列車的聲音，但從來沒去過其他地方。如果有機會的話，真想去外面看一看。",
          DialogueId = 90100401,
          GUID = "E18E80CC",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100403,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_1"
        },
        [90100403] = {
          ContentTC = "想去哪些地方呢？",
          DialogueId = 90100403,
          GUID = "E18E80CB",
          NextDialogue = 90100404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85301:Explain02_End"
          }
        },
        [90100404] = {
          ContentTC = "唔，我想想，帝都總是要去的，恩里克叔叔說過紅溪城的落日也很好看。對了，還想去你說的淨界島，在南方的海島上，聞一聞海風是不是真的是鹹的！",
          DialogueId = 90100404,
          GUID = "E18E910A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90100501] = {
          ContentTC = "沒什麼，我只是想……再多看幾眼，這樣我就可以把你們的樣子記得更清楚了。",
          DialogueId = 90100501,
          GUID = "E18EA172",
          NextDialogue = 90100502,
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_1"
        },
        [90100502] = {
          ContentTC = "如果可以，你可以也多看我幾眼嗎？我也想讓你記住我的樣子……我現在的樣子。",
          DialogueId = 90100502,
          GUID = "E18EA19C",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90100601] = {
          Content = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
          DialogueId = 90100601,
          GUID = "E18EB1DA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_01"
        },
        [90100701] = {
          ContentTC = "看見卡蜜拉女士總會讓我想起那間吵鬧卻溫馨的酒館……這些年能夠認識大家，真是太好了。",
          DialogueId = 90100701,
          GUID = "E18EC242",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_02"
        },
        [90100801] = {
          ContentTC = "你要講艾利西安的故事給我聽嗎？太感謝了！唔……作為回禮，我應該送你什麼花好呢……\n咦，你最喜歡好吃的花？",
          DialogueId = 90100801,
          GUID = "E18ED2AA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_03"
        },
        [90110000] = {
          ContentTC = "晨間打掃後通風，午後四處噴灑烈酒，薄暮時再點幾支香驅散蚊蟲，只有這樣才能保持室內潔淨。",
          DialogueId = 90110000,
          GUID = "E194B809",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_idle"
        },
        [90110001] = {
          ContentTC = "居移氣，養移體，不妨趁天氣晴朗出去走走，想必對身體會有所裨益。",
          DialogueId = 90110001,
          GUID = "E194B80A",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextOptions = {
            [1] = 901100011,
            [2] = 901100012,
            [3] = 901100013,
            [4] = 901100014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_welcome",
          bForbidSkipOptions = true
        },
        [90110002] = {
          ContentTC = "聊點別的",
          DialogueId = 90110002,
          GUID = "90110002.0",
          NextDialogue = 90110001
        },
        [90110003] = {
          ContentTC = "再見",
          DialogueId = 90110003,
          GUID = "90110003.0"
        },
        [90110101] = {
          ContentTC = "確然。只是書中的內容晦澀難懂，藥石之間的差異，在我看來也難以辨別。或許，我在此道上確實沒什麼天賦。",
          DialogueId = 90110101,
          GUID = "E194C872",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110103,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_1"
        },
        [90110103] = {
          ContentTC = "咦？我還以為對醫師來說，這些都信手拈來呢。",
          DialogueId = 90110103,
          GUID = "E194C8C6",
          NextDialogue = 90110104,
          SpeakNpcId = 100001
        },
        [90110104] = {
          ContentTC = "在我的時代……藥物並不是醫治疾病的主流方式，人們通常依靠一種名為「祝由術」的奇跡驅退病魔。",
          DialogueId = 90110104,
          GUID = "E194C8F0",
          NextDialogue = 90110105,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_2"
        },
        [90110105] = {
          ContentTC = "然而，這種治療方式雖然會帶來「治愈」與「平安」，但也代表著「交換」與「犧牲」。從沒有壽終正寢的醫者，透支生命直至亡故才是我們唯一的選擇。",
          DialogueId = 90110105,
          GUID = "E194C8F1",
          NextDialogue = 90110106,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_3"
        },
        [90110106] = {
          ContentTC = "……真是沉重的使命啊。",
          DialogueId = 90110106,
          GUID = "E194C8F2",
          NextDialogue = 90110107,
          SpeakNpcId = 100001
        },
        [90110107] = {
          ContentTC = "枯榮閣雖然已是歲月的一件遺物，但在救病治人的道路上，永遠不缺後繼者。即便使命沉重，總有人會肩負起這份責任，矢志不渝地走下去。",
          DialogueId = 90110107,
          GUID = "E194C8F3",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90110201] = {
          ContentTC = "願世間再無「無藥可醫」的頑疾。",
          DialogueId = 90110201,
          GUID = "E194D8DA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110203,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_1"
        },
        [90110203] = {
          ContentTC = "好宏大的夢想……",
          DialogueId = 90110203,
          GUID = "E194D92E",
          NextDialogue = 90110204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "82401:Explain02_End"
          }
        },
        [90110204] = {
          ContentTC = "聽起來與空想無異吧？但即使沒有術法帶來的奇跡，醫師所要做的事也從未改變。這樣的話由我這個醫書都未讀通的人說出口，實在貽笑大方。",
          DialogueId = 90110204,
          GUID = "E194D958",
          NextDialogue = 90110205,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_2"
        },
        [90110205] = {
          ContentTC = "但……我會繼續在這條路上走下去，不止是為了黎民百姓，為了枯榮閣，也是為了我自己。",
          DialogueId = 90110205,
          GUID = "E194D982",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90110301] = {
          ContentTC = "一個治病救人的地方。",
          DialogueId = 90110301,
          GUID = "E194E942",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110303,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_1"
        },
        [90110303] = {
          ContentTC = "還有別的嗎？",
          DialogueId = 90110303,
          GUID = "E194E944",
          NextDialogue = 90110304,
          SpeakNpcId = 100001
        },
        [90110304] = {
          ContentTC = "枯榮閣的使命，僅此而已。若說其他……每位入枯榮閣修行的醫師，都要手植杏樹一株，只是歲月流逝，風雨摧折，留存至今的已不足半數。",
          DialogueId = 90110304,
          GUID = "E194E943",
          NextDialogue = 90110305,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_2"
        },
        [90110305] = {
          ContentTC = "從長眠中蘇醒後，我也曾去尋找回憶那株屬於我的杏樹，但天不垂憐，花樹已成枯木，今春雖暖，也未曾發出新芽來。",
          DialogueId = 90110305,
          GUID = "E194E945",
          NextDialogue = 90110306,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_3"
        },
        [90110306] = {
          ContentTC = "歎隙中駒，石中火，夢中身，幾時歸去，空作閑人。過去的已無法挽留，就算想要彌補，也再無可能了。",
          DialogueId = 90110306,
          GUID = "E194E946",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90110401] = {
          ContentTC = "人死如燈滅，一切痕跡湮沒，一切聲息斷絕。那種與世隔絕的寂靜會吞沒一切希望與可能，如果可以，我不希望任何一個病人落入那種境地。",
          DialogueId = 90110401,
          GUID = "E194F9AA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110403,
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_1"
        },
        [90110403] = {
          ContentTC = "聽起來，就像扶疏親身體驗過一樣。",
          DialogueId = 90110403,
          GUID = "E194F9FE",
          NextDialogue = 90110404,
          SpeakNpcId = 100001
        },
        [90110404] = {
          ContentTC = "的確如你所說，我……曾經從一場重病中逃出生天。假使讓我再次面對這樣的考驗，我也不知道自己是否還會堅持當初的選擇。",
          DialogueId = 90110404,
          GUID = "E194FA28",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90110501] = {
          ContentTC = "蘭迪先生，依我看來，懶惰散漫也是身患疾病的一種表現，如今雖一時無恙，但畢竟也是個隱患。不如我來陪你過上兩招，活動活動筋骨，可好？",
          DialogueId = 90110501,
          GUID = "E1950A12",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_01"
        },
        [90110601] = {
          ContentTC = "醫者療疾，卻終究無法逆天改命。我可以為您開一貼緩解心熱的藥方，但病因卻無法根除，但願您能順天應時，自渡為好……",
          DialogueId = 90110601,
          GUID = "E1951A7A",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_02"
        },
        [90110701] = {
          ContentTC = "有時會聽到另一個人在說話？只有你能聽見嗎？近日睡眠如何？是否心有鬱結？最怕心病難醫，即使用上祝由術也無能為力，但身為醫者，我必定竭盡全力。",
          DialogueId = 90110701,
          GUID = "E1952AE2",
          SpeakNpcId = 82401,
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_03"
        },
        [90120000] = {
          ContentTC = "休息一會兒吧，榛子，吃點小麥，吃點堅果。再來上幾朵花當零食，要是吃不完的話，我就先插在帽子上。",
          DialogueId = 90120000,
          GUID = "E19B20A9",
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_idle"
        },
        [90120001] = {
          ContentTC = "太陽熱氣騰騰，雲朵鬆軟蓬蓬，早起的鳥兒吃個飽飽。你的肚子有沒有像鳥兒一樣咕咕叫呢？",
          DialogueId = 90120001,
          GUID = "E19B20AA",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextOptions = {
