        },
        [90120003] = {
          ContentTC = "再見",
          DialogueId = 90120003,
          GUID = "90120003.0"
        },
        [90120101] = {
          ContentTC = "咦？你不知道嗎？糧秣專員就是負責填飽大家肚子的人哦，每天都要和各種食物打交道。",
          DialogueId = 90120101,
          GUID = "E19B3112",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120103,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_1"
        },
        [90120103] = {
          ContentTC = "比如我的話，就會去野外收集各種各樣的食物，讓榛子馱回城裡，然後再去委託麵包店的鬍子叔叔做成吃的，分給大家。",
          DialogueId = 90120103,
          GUID = "E19B3166",
          NextDialogue = 90120104,
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_2"
        },
        [90120104] = {
          ContentTC = "順帶一說，和那位鬍子叔叔討價還價，也是我的工作！哼哼。",
          DialogueId = 90120104,
          GUID = "E19B3190",
          NextDialogue = 90120105,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_3"
        },
        [90120105] = {
          ContentTC = "哇！聽起來很厲害，不過所有的糧秣專員的工作都是這樣的嗎？",
          DialogueId = 90120105,
          GUID = "E19B31BA",
          NextDialogue = 90120106,
          SpeakNpcId = 100001
        },
        [90120106] = {
          ContentTC = "那當然不是啦，其他的糧秣官好像都是一些腦子很好的傢伙，寫什麼手續呀文書呀申請呀，然後就會有火車頭拖著小山一樣的吃的過來。",
          DialogueId = 90120106,
          GUID = "E19B31E4",
          NextDialogue = 90120107,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_4"
        },
        [90120107] = {
          ContentTC = "不過，我住的鎮子上人不是很多，有我和榛子就夠啦！否則可能我就也得去學怎麼寫那些什麼申請書之類的，唉，誰懂那些啊。",
          DialogueId = 90120107,
          GUID = "E19B320E",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90120201] = {
          ContentTC = "誒？會吧……沒太想過，不過反正榛子撞飛的一定都是那些喜歡哇哇亂叫，打來打去的壞傢伙！是他們活該！",
          DialogueId = 90120201,
          GUID = "E19B417A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120203,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_1"
        },
        [90120203] = {
          ContentTC = "這些傢伙，打打殺殺後又會叫餓連天。有揮武器的勁頭不如多墾一會兒地啦，這樣才會有更多人吃飽。",
          DialogueId = 90120203,
          GUID = "E19B41CE",
          NextDialogue = 90120204,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_2"
        },
        [90120204] = {
          ContentTC = "所以你也很討厭戰爭嘍？",
          DialogueId = 90120204,
          GUID = "E19B41F8",
          NextDialogue = 90120205,
          SpeakNpcId = 100001
        },
        [90120205] = {
          ContentTC = "那是當然！戰鬥是饑餓之母，是壞傢伙！聽說一旦遇到戰爭，那麼大家都會餓肚子，非常討厭！希望我不要遇上就是了。",
          DialogueId = 90120205,
          GUID = "E19B4222",
          NextDialogue = 90120206,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_3"
        },
        [90120206] = {
          ContentTC = "真要遇到戰爭，就騎上榛子，撞飛開戰的壞人。",
          DialogueId = 90120206,
          GUID = "E19B424C",
          NextDialogue = 90120207,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85101:Confident_End"
          }
        },
        [90120207] = {
          ContentTC = "沒錯，誰讓人餓肚子，誰就遲早會被榛子撞飛！",
          DialogueId = 90120207,
          GUID = "E19B4276",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90120301] = {
          ContentTC = "是不少啦，不過其實不用特別為她準備吃的，她會自己找的。哪怕隔著幾條小溪，榛子也能聞到熟透漿果的味道，然後馱著我飛奔過去，可能幹啦。",
          DialogueId = 90120301,
          GUID = "E19B51E2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120303,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_1"
        },
        [90120303] = {
          ContentTC = "那還好，不用擔心破產了。",
          DialogueId = 90120303,
          GUID = "E19B5236",
          NextDialogue = 90120304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85101:Talk02_End"
          }
        },
        [90120304] = {
          ContentTC = "別擔心別擔心，榛子只會帶來食物，不會吃垮這裡的！所以，一定一定不要拿榛子開玩笑哦，她聽到的話會傷心的，我也會。",
          DialogueId = 90120304,
          GUID = "E19B5260",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90120401] = {
          ContentTC = "謝謝誇獎，不過我要糾正一下，這其實是褲子。一開始倒的確是裙子，白色的，長長的，可好看啦。是裁縫店的婆婆幫我改成了褲子。",
          DialogueId = 90120401,
          GUID = "E19B624A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120403,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_1"
        },
        [90120403] = {
          ContentTC = "為什麼呀？",
          DialogueId = 90120403,
          GUID = "E19B629E",
          NextDialogue = 90120404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85101:Explain01_End"
          }
        },
        [90120404] = {
          ContentTC = "因為穿著裙子到處跑太不方便啦，有一次我跑得快了，都被裙擺絆倒，手裡的麵包都撒了。",
          DialogueId = 90120404,
          GUID = "E19B62C8",
          NextDialogue = 90120405,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_2"
        },
        [90120405] = {
          ContentTC = "所以，哎……要是哪天，沒有人挨餓了，我就拜託婆婆再把這條褲子改回去！",
          DialogueId = 90120405,
          GUID = "E19B62F2",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90120501] = {
          ContentTC = "才不是發呆，是在冥想。不管怎麼說我都是傳頌會的一員，所以偶爾也會像這樣用力想事情的。",
          DialogueId = 90120501,
          GUID = "E19B72B2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120503,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_1"
        },
        [90120503] = {
          ContentTC = "那在想什麼呢？為什麼沒有吃飽飯之神？",
          DialogueId = 90120503,
          GUID = "E19B7306",
          NextDialogue = 90120504,
          SpeakNpcId = 100001
        },
        [90120504] = {
          ContentTC = "之前想過，不過修士們說，想這種事情是什麼瀆……神？所以我就不想這些了。",
          DialogueId = 90120504,
          GUID = "E19B7330",
          NextDialogue = 90120505,
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_2"
        },
        [90120505] = {
          ContentTC = "唉，修士們的話我總是聽得半懂不懂的，比如他們總是說貪吃是非常非常嚴重的罪過……可是好像越是大吃大喝的人，地位就越高哦。",
          DialogueId = 90120505,
          GUID = "E19B735A",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90120601] = {
          ContentTC = "你在垃圾桶裡翻到了發了芽的土豆？不要扔不要扔，我們把它種起來，鬆鬆土、澆澆水，就會有好多好多土豆可以吃啦！",
          DialogueId = 90120601,
          GUID = "E19B831A",
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_01"
        },
        [90120701] = {
          ContentTC = "一直忙著幹活，不餓嗎？要不要加入傳頌會，我會餵飽你的！",
          DialogueId = 90120701,
          GUID = "E19B9382",
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_02"
        },
        [90120801] = {
          ContentTC = "你好你好，我想請教一下……據說祈禱可以讓人的靈魂感到滿足，我覺得吃飯也可以，那麼吃飯和祈禱哪個更管用呀？",
          DialogueId = 90120801,
          GUID = "E19BA3EA",
          SpeakNpcId = 85101,
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_03"
        },
        [90130000] = {
          ContentTC = "……還好，這個月的錢一分不少，還以為真被蘭迪那傻*扣光了……嗯，這些寄回家裡，剩下的生活費應該還夠用。",
