          GUID = "E1A1CAEA",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130403,
          SpeakNpcId = 83101,
          TalkActionId = {
            [1] = "83101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_1"
        },
        [90130403] = {
          ContentTC = "但勞逸結合也是很重要的呀。",
          DialogueId = 90130403,
          GUID = "E1A1CB3E",
          NextDialogue = 90130404,
          SpeakNpcId = 100001
        },
        [90130404] = {
          ContentTC = "我倒是想，但是那些雇主們可不這麼想，隔三差五就問我委託做完沒有，快點做之類，催催催，要不是我還有一家子要養活，真想給他們來上幾發。",
          DialogueId = 90130404,
          GUID = "E1A1CB68",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          TalkActionId = {
            [1] = "83101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90130501] = {
          ContentTC = "下次派任務能不能直說？嘮嘮叨叨的，煩死了。",
          DialogueId = 90130501,
          GUID = "E1A1DB52",
          SpeakNpcId = 83101,
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_01"
        },
        [90130601] = {
          ContentTC = "……長官好。",
          DialogueId = 90130601,
          GUID = "E1A1EBBA",
          SpeakNpcId = 83101,
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_02"
        },
        [90130701] = {
          ContentTC = "你是優秀的士兵，僅此一句。哦，還有……好好工作之餘，也得好好生活……嘖，聽完了還不快走？",
          DialogueId = 90130701,
          GUID = "E1A1FC22",
          SpeakNpcId = 83101,
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_03"
        },
        [90140000] = {
          ContentTC = "從太陽升起前到月亮升起後，女僕永遠在忙裡忙外，永不止歇。有時呢，她還會遇到意想不到的攪擾——在思考接下來一周的菜單時，被晃蕩的閒人搭話。",
          DialogueId = 90140000,
          GUID = "E1A7F1E9",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_idle"
        },
        [90140001] = {
          ContentTC = "說吧，今天想拜託我做什麼？是想來上一杯花茶呢？還是想要清掃一些敵人？",
          DialogueId = 90140001,
          GUID = "E1A7F1EA",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextOptions = {
            [1] = 901400011,
            [2] = 901400012,
            [3] = 901400013,
            [4] = 901400014,
            [5] = 901400015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_welcome",
          bForbidSkipOptions = true
        },
        [90140002] = {
          ContentTC = "聊點別的",
          DialogueId = 90140002,
          GUID = "90140002.0",
          NextDialogue = 90140001
        },
        [90140003] = {
          ContentTC = "再見",
          DialogueId = 90140003,
          GUID = "90140003.0"
        },
        [90140101] = {
          ContentTC = "確實如此，起霧的日子不少，洗好的衣服在那樣的天氣裡無法晾乾，還會沾染彌漫的灰塵。",
          DialogueId = 90140101,
          GUID = "E1A80252",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140103,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_1"
        },
        [90140103] = {
          ContentTC = "有時，還會有一些汙物趁著濃密的霧氣接近芙羅拉小姐，意圖不軌。",
          DialogueId = 90140103,
          GUID = "E1A802A6",
          NextDialogue = 90140104,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_2"
        },
        [90140104] = {
          ContentTC = "那你應該很喜歡晴天？",
          DialogueId = 90140104,
          GUID = "E1A802D0",
          NextDialogue = 90140105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Talk01_End"
          }
        },
        [90140105] = {
          ContentTC = "晴天嘛，確實很適合洗曬，但是也意味著芙羅拉小姐和我的行跡更容易被注意到——對我來說，哪種天氣都一樣壞，只不過有的天氣更壞一點而已。",
          DialogueId = 90140105,
          GUID = "E1A802FA",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90140201] = {
          ContentTC = "一名女僕能戰鬥，很正常，沒什麼值得問的。",
          DialogueId = 90140201,
          GUID = "E1A812BA",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140203,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_02_1"
        },
        [90140203] = {
          ContentTC = "這不正常吧，據我所知，女僕不是應該在大宅子裡打掃衛生嗎？",
          DialogueId = 90140203,
          GUID = "E1A8130E",
          NextDialogue = 90140204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Confident_End"
          }
        },
        [90140204] = {
          ContentTC = "在我的眼中，嗡嗡作響的飛蠅與穢獸都是應當清掃的汙物。所謂的戰鬥，也不過是一項令人愉快的清掃工作而已。",
          DialogueId = 90140204,
          GUID = "E1A81338",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90140301] = {
          ContentTC = "危險品？我不明白……您能不能說清楚一些，別讓人猜來猜去。",
          DialogueId = 90140301,
          GUID = "E1A82322",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140303,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_1"
        },
        [90140303] = {
          ContentTC = "槍，槍，槍！你我看你已經買了許多支了。",
          DialogueId = 90140303,
          GUID = "E1A82376",
          NextDialogue = 90140304,
          SpeakNpcId = 100001
        },
        [90140304] = {
          ContentTC = "......我承認，我對槍械有一些偏好，畢竟女僕日常會接觸的那些工具裡，槍械的使用手感最為特別，清除汙物的效率也是首屈一指的。",
          DialogueId = 90140304,
          GUID = "E1A823A0",
          NextDialogue = 90140305,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_2"
        },
        [90140305] = {
          ContentTC = "如果您平時也積攢了不少壓力的話，我可以借您幾支，噠噠噠噠，我想您也會喜歡的。",
          DialogueId = 90140305,
          GUID = "E1A823CA",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90140401] = {
          ContentTC = "呃，也許有吧，我不喜歡與無關緊要的人寒暄太久。",
          DialogueId = 90140401,
          GUID = "E1A8338A",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140403,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_1"
        },
        [90140403] = {
          ContentTC = "喔，這麼說來，你和我說了不少話的。",
          DialogueId = 90140403,
          GUID = "E1A833DE",
          NextDialogue = 90140404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Think_End"
          }
        },
        [90140404] = {
          ContentTC = "看來您誤會了，這是因為您給我付了足夠的傭金，如果有一天您身無分文，那我或許會棄您不顧。",
          DialogueId = 90140404,
          GUID = "E1A83408",
          NextDialogue = 90140405,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_2"
        },
        [90140405] = {
          ContentTC = "哇，那我可真是太傷心了。",
          DialogueId = 90140405,
          GUID = "E1A83432",
          NextDialogue = 90140406,
          SpeakNpcId = 100001
        },
        [90140406] = {
          ContentTC = "不用太擔心，相信我，我不會讓您陷入那般窘境。",
          DialogueId = 90140406,
          GUID = "E1A8345C",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90140501] = {
          ContentTC = "嗯？在……在哪裡？按照今天的行程她現在應該不在這裡才是……",
          DialogueId = 90140501,
          GUID = "E1A843F2",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140503,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_1"
        },
        [90140503] = {
          ContentTC = "你騙我。",
          DialogueId = 90140503,
          GUID = "E1A84446",
          NextDialogue = 90140504,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_2"
        },
        [90140504] = {
          ContentTC = "你是不是有點反應過度了？",
          DialogueId = 90140504,
          GUID = "E1A84470",
          NextDialogue = 90140505,
          SpeakNpcId = 100001
        },
        [90140505] = {
          ContentTC = "並沒有，她很重要。僭越地說，芙羅拉小姐對我而言，除了主人以外，尚有其他身份，所以……",
          DialogueId = 90140505,
          GUID = "E1A8449A",
          NextDialogue = 90140506,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_3"
        },
        [90140506] = {
          ContentTC = "可惜我並不是吟游詩人，無法找到一個詞彙，能夠兼有朋友與親人的含義。",
          DialogueId = 90140506,
          GUID = "E1A844C4",
          NextDialogue = 90140507,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_4"
        },
        [90140507] = {
          ContentTC = "我相信有些情感不需要語言也能傳達。",
          DialogueId = 90140507,
          GUID = "E1A844EE",
          NextDialogue = 90140508,
          SpeakNpcId = 100001
        },
        [90140508] = {
          ContentTC = "我無意讓芙羅拉小姐知曉——清理主人前路的雜物是女僕的天職，我為此榮幸不已。",
          DialogueId = 90140508,
          GUID = "E1A84518",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_5",
          bForbidSkipOptions = true
        },
        [90140601] = {
          Content = "我最喜欢的花，生长在恒温的穹顶下。只需一片花瓣就可以制成安神的晚茶，而十片花瓣，又可以萃出一滴让人长眠的毒液。偶尔在梦里我还会修剪那片花圃，而醒来后，我会庆幸不用再照料它们。",
          DialogueId = 90140601,
          GUID = "E1A8545A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_01"
        },
        [90140701] = {
          ContentTC = "真厲害，我由內心深處湧出敬意，您每天都在思考一些重大的事情。不像我這樣的女僕，只會關心眼前的瑣事。",
          DialogueId = 90140701,
          GUID = "E1A864C2",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_02"
        },
        [90140801] = {
          ContentTC = "這些堆積的無用雜物令我頭痛了許久，如果您想帶走它們當然樂意至極。不過在您進入房間前，請務必允許我為您提供清潔服務，您無權拒絕，不許掙扎。",
          DialogueId = 90140801,
          GUID = "E1A8752A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_03"
        },
        [90150000] = {
          ContentTC = "♪ 我的小小的、小小的家……藏在樹梢的新綠裡，藏在金色的河流間……溫暖的壁爐呀，小火苗劈啪劈啪……握著爸爸剛修好的錫兵，聽媽媽唱起搖籃曲……睡吧……",
          DialogueId = 90150000,
          GUID = "E1AE5A8B",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_idle"
        },
        [90150001] = {
          ContentTC = "……唔……是你。你好，你好呀。",
          DialogueId = 90150001,
          GUID = "E1AE5A8A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextOptions = {
            [1] = 901500011,
            [2] = 901500012,
            [3] = 901500013,
            [4] = 901500014,
            [5] = 901500015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_welcome",
          bForbidSkipOptions = true
        },
        [90150002] = {
          ContentTC = "聊點別的",
          DialogueId = 90150002,
          GUID = "90150002.0",
          NextDialogue = 90150001
        },
        [90150003] = {
          ContentTC = "再見",
          DialogueId = 90150003,
          GUID = "90150003.0"
        },
        [90150101] = {
          ContentTC = "唔，我想吃掉可以讓人變得很大很大的糖果……",
          DialogueId = 90150101,
          GUID = "E1AE6AF2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150103,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_1"
        },
        [90150103] = {
          ContentTC = "吃下那樣的糖果，我就會長得比雲還高，可以摸一摸天上的星星了吧？",
          DialogueId = 90150103,
          GUID = "E1AE6B46",
          NextDialogue = 90150104,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_2"
        },
        [90150104] = {
          ContentTC = "會不會一不留神一腳把我踩扁了……",
          DialogueId = 90150104,
          GUID = "E1AE6B70",
          NextDialogue = 90150105,
          SpeakNpcId = 100001
        },
        [90150105] = {
          ContentTC = "不會的，我會很小心的！嗯……如果你實在害怕的話，就坐在我的手心裡，我帶你出去兜風，怎麼樣？",
          DialogueId = 90150105,
          GUID = "E1AE6B9A",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90150201] = {
          ContentTC = "我有一個很大很大的玻璃盒子，盒子裡面裝著窗戶外軟綿綿的雪，裝著雪一樣白白的棉花糖。我還想裝進去棉花糖一樣輕飄飄的雲朵，雲朵一樣暖乎乎的風……",
          DialogueId = 90150201,
          GUID = "E1AE7B5A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150203,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_1"
        },
        [90150203] = {
          ContentTC = "連同你們的笑聲一起，全～都裝進盒子。",
          DialogueId = 90150203,
          GUID = "E1AE7BAE",
          NextDialogue = 90150204,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_2"
        },
        [90150204] = {
          ContentTC = "真好啊，想鑽進去。",
          DialogueId = 90150204,
          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001
        },
        [90150205] = {
          ContentTC = "嗯……如果你能吃下讓人變得很小很小的糖果，就可以進去玩啦。不過，這個盒子裡到處都是白色的，你要小心，別在裡面迷路哦。",
          DialogueId = 90150205,
          GUID = "E1AE7C02",
          NextDialogue = 90150206,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_3"
        },
        [90150206] = {
          ContentTC = "如果我迷路了，菲娜會來救我嗎？",
          DialogueId = 90150206,
          GUID = "E1AE7C2C",
          NextDialogue = 90150207,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Think_Start"
          }
        },
        [90150207] = {
          ContentTC = "讓我想想……如果你迷路了，菲娜就把麵包掰成一小塊一小塊，連成一條路……這樣，你只要沿著麵包屑向前走，就能找到出口啦！",
          DialogueId = 90150207,
          GUID = "E1AE7C56",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90150301] = {
          ContentTC = "嗯……！在夢裡，我看到了一隻純白羽毛的夜鶯，它一會兒落在我的手上，一會兒繞著屋子和我捉迷藏……唔……到底是我夢見了它，還是它夢見了我呢……",
          DialogueId = 90150301,
          GUID = "E1AE8BC2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150303,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_1"
        },
        [90150303] = {
          ContentTC = "也許是你們做了同一個夢呢？",
          DialogueId = 90150303,
          GUID = "E1AE8C16",
          NextDialogue = 90150304,
          SpeakNpcId = 100001
        },
        [90150304] = {
          ContentTC = "你說得對！也許那是一個仙境，所有睡著的孩子和小動物都可以在那裡一起玩。嗯……下次的夢裡會遇到誰呢？貓頭鷹爺爺、金絲雀小姐，還是白兔先生？",
          DialogueId = 90150304,
          GUID = "E1AE8C40",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90150401] = {
          ContentTC = "菲娜曾經有一個媽媽，兩個爸爸。不過，他們都不在了……",
          DialogueId = 90150401,
          GUID = "E1AE9C2A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150402,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_1"
        },
        [90150402] = {
          ContentTC = "第一個爸爸，和媽媽一起，去了很遠很遠的國度。第二個爸爸，也去了很遠很遠的國度……是我帶他去的哦。",
          DialogueId = 90150402,
          GUID = "E1AE9C54",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90150501] = {
          ContentTC = "他是最偉大的魔法師，是說話最好聽的人，是全世界最溫柔最溫柔的人……",
          DialogueId = 90150501,
          GUID = "E1AEAC92",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150503,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_1"
        },
        [90150503] = {
          ContentTC = "？",
          DialogueId = 90150503,
          GUID = "E1AEACE6",
          NextDialogue = 90150504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Explain02_End"
          }
        },
        [90150504] = {
          ContentTC = "唔，你看起來有很多很多問題，我哪裡說的不對嗎？",
          DialogueId = 90150504,
          GUID = "E1AEAD10",
          NextDialogue = 90150505,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_2"
        },
        [90150505] = {
          ContentTC = "和我認識的奧特賽德完全是兩個人吧！",
          DialogueId = 90150505,
          GUID = "E1AEAD3A",
          NextDialogue = 90150506,
          SpeakNpcId = 100001
        },
        [90150506] = {
          ContentTC = "咦……？他對你說話不好聽、不溫柔嗎？真對不起……我會敲敲他的腦袋，要他改正的！",
          DialogueId = 90150506,
          GUID = "E1AEAD64",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90150601] = {
          ContentTC = "答應菲娜，再也再也再也……不要去那些有很多很多壞巫師的危險地方了，好嗎？",
          DialogueId = 90150601,
          GUID = "E1AEBCFA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_01"
        },
        [90150701] = {
          ContentTC = "那是什麼？倉鼠小姐飼養的精靈嗎？不可思議……它一定可以載著你飛過所有城堡的圍牆！",
          DialogueId = 90150701,
          GUID = "E1AECD62",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_02"
        },
        [90150801] = {
          ContentTC = "獅子小姐，你想要喚醒沉睡在巨劍中的仙女嗎？也許你需要吟誦很多很多咒語，比如——「喚醒聖劍薩麥爾之人啊，必將成為艾利西安之王！」",
          DialogueId = 90150801,
          GUID = "E1AEDDCA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_03"
        },
        [90150901] = {
          ContentTC = "南國來的海馬先生，我好像在哪兒見過你……唔……我想起來了！很久很久之前，爸爸在家裡的牆上，掛了一張你的肖像。",
          DialogueId = 90150901,
          GUID = "E1AEEE32",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_04"
        },
        [90160000] = {
          ContentTC = "現在這種安心的感覺也不錯，甚至讓我在過了那麼多年後，還能對一個地方產生一絲歸屬感。",
          DialogueId = 90160000,
          GUID = "E1B4C329",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_idle"
        },
        [90160001] = {
          ContentTC = "你可來了，我把之前剩下的雜活清了一下，錢沒賺多少還差點把自己累死，唉，為了這個家我真是付出了太多啊。",
          DialogueId = 90160001,
          GUID = "E1B4C32A",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextOptions = {
            [1] = 901600011,
            [2] = 901600012,
            [3] = 901600013,
            [4] = 901600014,
            [5] = 901600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_welcome",
          bForbidSkipOptions = true
        },
        [90160002] = {
          ContentTC = "聊點別的",
          DialogueId = 90160002,
          GUID = "90160002.0",
          NextDialogue = 90160001
        },
        [90160003] = {
          ContentTC = "再見",
          DialogueId = 90160003,
          GUID = "90160003.0"
        },
        [90160101] = {
          ContentTC = "手冊？沒有，乾這行的可大部分沒看書的耐性，但是口訣倒是不少，比如我自創的打人口訣：「兩下腰子一下頭，皇帝看了說沒救」。",
          DialogueId = 90160101,
          GUID = "E1B4D392",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160103,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_1"
        },
        [90160103] = {
          ContentTC = "有意思，再來上幾句？",
          DialogueId = 90160103,
          GUID = "E1B4D3E6",
          NextDialogue = 90160104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          }
        },
        [90160104] = {
          ContentTC = "別貪多，飯一口一口吃，乾這行的，最大的敵人永遠是貪婪，有時候來自別人，但更多時候來自自己。",
          DialogueId = 90160104,
          GUID = "E1B4D410",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90160201] = {
          ContentTC = "他們是一團未熄滅的野火，稍不留神就會燒成滿山烈焰。為你個人考慮，還是少與他們接觸為好……",
          DialogueId = 90160201,
          GUID = "E1B4E3FA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160203,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_1"
        },
        [90160203] = {
          ContentTC = "這麼嚴肅，為什麼？",
          DialogueId = 90160203,
          GUID = "E1B4E44E",
          NextDialogue = 90160204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Talk03_End"
          }
        },
        [90160204] = {
          ContentTC = "那當然是因為……有過一些小過節，要是哪天你和他們打上交道，可千萬記得別報我名字。",
          DialogueId = 90160204,
          GUID = "E1B4E478",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90160301] = {
          ContentTC = "嗯，能幫我拿一下那邊的紗布嗎？可不能被菲娜發現，不然她又要嘮叨了。",
          DialogueId = 90160301,
          GUID = "E1B4F462",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160303,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_1"
        },
        [90160303] = {
          ContentTC = "她那是在關心你。",
          DialogueId = 90160303,
          GUID = "E1B4F4B6",
          NextDialogue = 90160304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Explain02_End"
          }
        },
        [90160304] = {
          ContentTC = "我知道，但乾咱們這一行總免不了受點傷，我也不想她一直擔心嘛。她要是真的問起來，你記得幫我打個圓場啊，回頭請你吃飯。",
          DialogueId = 90160304,
          GUID = "E1B4F4E0",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90160401] = {
          ContentTC = "噢，你要不要也試試這些小家伙？別看它們長得醜，去掉頭就跟小餅乾一樣脆脆的，甚至能在嘴巴留下一絲肉類的回甘……",
          DialogueId = 90160401,
          GUID = "E1B504CA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160403,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Give"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_1"
        },
        [90160403] = {
          ContentTC = "（轉身逃跑。）",
          DialogueId = 90160403,
          GUID = "E1B5051E",
          NextDialogue = 90160404,
          SpeakNpcId = 100001
        },
        [90160404] = {
          ContentTC = "你別跑啊，這可是很有用的生存智慧……等你迷失在野外，乾糧吃完的時候，它們就是最寶貴的能量來源。",
          DialogueId = 90160404,
          GUID = "E1B50548",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90160501] = {
          ContentTC = "嗯……等等，你手上怎麼才這麼幾個錢，是不是又把你那份報酬隨便分給其他人了？",
          DialogueId = 90160501,
          GUID = "E1B51532",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160503,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_1"
        },
        [90160503] = {
          ContentTC = "他們比我更需要那些錢。",
          DialogueId = 90160503,
          GUID = "E1B51586",
          NextDialogue = 90160504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_End"
          }
        },
        [90160504] = {
          ContentTC = "你……哎，算了，這大概就是你的優點吧。手頭緊的時候記得跟我說。",
          DialogueId = 90160504,
          GUID = "E1B515B0",
          NextDialogue = 90160505,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_2"
        },
        [90160505] = {
          ContentTC = "好，那我現在手頭緊了！",
          DialogueId = 90160505,
          GUID = "E1B515DA",
          NextDialogue = 90160506,
          SpeakNpcId = 100001
        },
        [90160506] = {
          ContentTC = "……我這是身為朋友在關心你，你別得寸進尺耍無賴啊！",
          DialogueId = 90160506,
          GUID = "E1B51604",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90160601] = {
          Content = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
          DialogueId = 90160601,
          GUID = "E1B5259A",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_01"
        },
        [90160701] = {
          ContentTC = "你是跟{nickname}關係很好的那個女孩子吧……聽說你身體不太好，就坐下好好休息一會兒吧。",
          DialogueId = 90160701,
          GUID = "E1B53602",
          NextDialogue = 90160702,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_1"
        },
        [90160702] = {
          ContentTC = "不用跟我客氣，我家也有個體弱多病的妹妹，早就習慣照顧人了……要是餓了、渴了，儘管跟我說，{nickname}的朋友就是我的朋友。",
          DialogueId = 90160702,
          GUID = "E1B5362C",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_2"
        },
        [90160801] = {
          ContentTC = "喲，老板娘，你怎麼也在這兒……難不成是有什麼緊急的委托？{nickname}這段時間已經累壞了，暫時就讓我們歇歇吧……",
          DialogueId = 90160801,
          GUID = "E1B5466A",
          NextDialogue = 90160802,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_1"
        },
        [90160802] = {
          ContentTC = "噢，不過，如果報酬夠高的話，還是說來聽聽吧。",
          DialogueId = 90160802,
          GUID = "E1B54694",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_2"
        },
        [90160901] = {
          ContentTC = "還記得我小時候嗎？你對我來說是位溫柔的姐姐，也是位嚴苛的父親……呃，沒有說你又老又暴力的意思，只是想說……謝謝你在那時給了我一個歸屬。",
          DialogueId = 90160901,
          GUID = "E1B556D2",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_04"
        },
        [90170000] = {
          ContentTC = "嗯~天氣不錯，正適合去採一些花，熏得身上香香的！{nickname}，想一起出門逛逛嗎？",
          DialogueId = 90170000,
          GUID = "E1BB2BC9",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_idle"
        },
        [90170001] = {
          ContentTC = "我來的時候順手把你家門口的雪給鏟了！是不是特別感動，特別想請我喝一杯熱可可呀~",
          DialogueId = 90170001,
          GUID = "E1BB2BCA",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextOptions = {
            [1] = 901700011,
            [2] = 901700012,
            [3] = 901700013,
            [4] = 901700014,
            [5] = 901700015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90170002] = {
          ContentTC = "聊點別的",
          DialogueId = 90170002,
          GUID = "90170002.0",
          NextDialogue = 90170001
        },
        [90170003] = {
          ContentTC = "再見",
          DialogueId = 90170003,
          GUID = "90170003.0"
        },
        [90170101] = {
          ContentTC = "嗯……大概是為那些被捨棄的物品找到合適的主人的營生，唔，也能讓那些遭受物資匱乏之苦的人，得到更好的生活。",
          DialogueId = 90170101,
          GUID = "E1BB3C32",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170103,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_1"
        },
        [90170103] = {
          ContentTC = "具體要怎麼做？",
          DialogueId = 90170103,
          GUID = "E1BB3C86",
          NextDialogue = 90170104,
          SpeakNpcId = 100001
        },
        [90170104] = {
          ContentTC = "比如，把貴族老爺淘汰下來的絲絨窗簾換成冬衣，讓老人們暖暖過冬；把被丟棄的玩偶小人帶給那些只能拋石頭玩的孩子，他們能高興很久。",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          ContentTC = "還有一次，我把不知道哪家丟掉的破爛書架搬了回來，累得半死，但沒過多久，就有一群貓媽媽貓小孩過來上躥下跳，從太陽上山玩到月亮落山。",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          ContentTC = "拾荒者的工作就是這樣啦！大多是些雞毛蒜皮的小事，但永遠不會無聊，怎麼樣，想不想加入我們！",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90170201] = {
          ContentTC = "噓噓噓，這可是拾荒者的最高機密！要不是你幫我抓過賊，才不會輕易透露給你呢！",
          DialogueId = 90170201,
          GUID = "E1BB4C9A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170203,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          ContentTC = "這張圖標明了冰湖城所有垃圾桶的位置，我在上面標了好東西最多的幾個，不僅把那邊的垃圾桶換成了大號，就連什麼時候去進貨都經過我嚴密的計算！",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Give"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_2"
        },
        [90170204] = {
          ContentTC = "不過我們這行旱澇不保收，能有多少進帳，大部分時候還得靠運氣……",
          DialogueId = 90170204,
          GUID = "E1BB4D18",
          NextDialogue = 90170205,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_3"
        },
        [90170205] = {
          ContentTC = "撿垃圾也真不容易……",
          DialogueId = 90170205,
          GUID = "E1BB4D42",
          NextDialogue = 90170206,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Sigh_End"
          }
        },
        [90170206] = {
          ContentTC = "可不是嘛，嘿，我就說你是個明眼人！",
          DialogueId = 90170206,
          GUID = "E1BB4D6C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          ContentTC = "不，你說反啦！我非常喜歡冰湖城。只是我常常回想起和爸爸一起在雪原上流浪的日子，我的整個童年都是在那裡度過的。",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          ContentTC = "你怎麼看待那些時光呢？",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          ContentTC = "從這裡看向雪原，美得像童話裡的冰國雪國。可一步一步走進去，又會覺得自己好小好小。在齊膝的雪地裡邁著腿，不管走了多久，看到的景色都不會改變。",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          ContentTC = "我不討厭那段時光，但我最喜歡的，果然還是熱熱鬧鬧，充滿煙火味的冰湖城！",
          DialogueId = 90170305,
          GUID = "E1BB5DAA",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90170401] = {
          ContentTC = "是小時候和我在雪原上一起流浪的大貓！它叫「胖尾巴」，平時得用肉乾賄賂才願意給我摸摸，但那個手感——嘿嘿嘿嘿，一個字，絕啦！",
          DialogueId = 90170401,
          GUID = "E1BB6D6A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170403,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_1"
        },
        [90170403] = {
          ContentTC = "雪原大貓怎麼叫？像貓還是像老虎？",
          DialogueId = 90170403,
          GUID = "E1BB6DBE",
          NextDialogue = 90170404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          }
        },
        [90170404] = {
          ContentTC = "嗯……反正不是喵喵喵，大概是，嗷嗚——嗷嗚——嗷嗚——的聲音！",
          DialogueId = 90170404,
          GUID = "E1BB6DE8",
          NextDialogue = 90170405,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_2"
        },
        [90170405] = {
          ContentTC = "現在還能見到它嗎？",
          DialogueId = 90170405,
          GUID = "E1BB6E12",
          NextDialogue = 90170406,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Think_End"
          }
        },
        [90170406] = {
          ContentTC = "胖尾巴畢竟是生活在雪原的野獸，它不願意靠近城市，等待我們的只有分道揚鑣。但它會一直留在我的記憶裡，和那片雪原一起。",
          DialogueId = 90170406,
          GUID = "E1BB6E3C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90170501] = {
          ContentTC = "我沒有，我不是，別瞎說！我都這麼大了，怎麼還用這種哄小孩的稱呼！算我求你了，別再提這個了！",
          DialogueId = 90170501,
          GUID = "E1BB7DD2",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170503,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_1"
        },
        [90170503] = {
          ContentTC = "那瑪爾潔希望被人們怎樣稱呼呢？",
          DialogueId = 90170503,
          GUID = "E1BB7E26",
          NextDialogue = 90170504,
          SpeakNpcId = 100001
        },
        [90170504] = {
          ContentTC = "那當然是——咳咳，於城市背面孤獨行走，緘默的偵探——瑪爾潔小姐！今天，也為你揭示冰湖城不為人知的隱秘！",
          DialogueId = 90170504,
          GUID = "E1BB7E50",
          NextDialogue = 90170505,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_2"
        },
        [90170505] = {
          ContentTC = "嘿嘿，這才是與我相稱的外號嘛~",
          DialogueId = 90170505,
          GUID = "E1BB7E7A",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90170601] = {
          ContentTC = "這個布料，這個徽章，這個皮革！希爾妲大姐，你是我的神嗎？！要是還有這種不法之徒的東西需要「妥善處理」，找我就對了，包準給您處理得安全無憂！",
          DialogueId = 90170601,
          GUID = "E1BB8E3A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_01"
        },
        [90170701] = {
          ContentTC = "小菲娜！好久不見啦~想聽《雪貓遊俠與橘貓偵探》的後續？好！等我搬個小板凳，坐下來慢慢給你講！",
          DialogueId = 90170701,
          GUID = "E1BB9EA2",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_02"
        },
        [90170801] = {
          ContentTC = "典獄長大人，我可是徹頭徹尾的良民！一沒偷二沒搶，只是從垃圾桶裡拿一點點殘羹剩飯果腹罷了，您再敬業，也管不到垃圾頭上吧？",
          DialogueId = 90170801,
          GUID = "E1BBAF0A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_03"
        },
        [90170901] = {
          ContentTC = "你這日子過得也太緊巴巴了吧！好、好慘……你要不要來和我一起撿垃圾，說不定日子還能過得寬裕一點？",
          DialogueId = 90170901,
          GUID = "E1BBBF72",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_04"
        },
        [90171001] = {
          ContentTC = "最最最善良美麗的卡蜜拉姐，我這裡有一點小小小小的麻煩，得拜託你幫我個忙——這回絕對是最後一次！呃，本月的最後一次！你一定會答應我的，對吧？",
          DialogueId = 90171001,
          GUID = "E1BBCFDA",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_05"
        },
        [90180000] = {
          ContentTC = "耶爾：紅鯉魚，有頭小綠、綠，綠鯉，綠驢，綠縷魚…….",
          DialogueId = 90180000,
          GUID = "E1C19467",
          NextDialogue = 90180002,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_1"
        },
        [90180001] = {
          ContentTC = "耶爾：你來啦……天氣真好……很適合做爆炸實驗……唔，天氣真好。",
          DialogueId = 90180001,
          GUID = "E1C1946A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextOptions = {
            [1] = 901800011,
            [2] = 901800012,
            [3] = 901800013,
            [4] = 901800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90180002] = {
          ContentTC = "奧利弗：是「紅鯉魚有頭小綠驢，綠鯉魚有頭小紅驢！」笨蛋耶爾，快跟我念！",
          DialogueId = 90180002,
          GUID = "E1C19468",
          NextDialogue = 90180003,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_2"
        },
        [90180003] = {
          ContentTC = "耶爾：好、好的！紅、紅鯉魚……",
          DialogueId = 90180003,
          GUID = "E1C19469",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_3"
        },
        [90180004] = {
          ContentTC = "聊點別的",
          DialogueId = 90180004,
          GUID = "90180004.0",
          NextDialogue = 90180001
        },
        [90180005] = {
          ContentTC = "再見",
          DialogueId = 90180005,
          GUID = "90180005.0"
        },
        [90180101] = {
          ContentTC = "耶爾：奧利弗不是會說話的炸彈……可能聽起來有些不可思議，但……他其實是……",
          DialogueId = 90180101,
          GUID = "E1C1A4D2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180103,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_1"
        },
        [90180103] = {
          ContentTC = "奧利弗：閉嘴，被你急死了！我就是耶爾，耶爾就是我。聽明白了嗎？不明白也無所謂，也沒指望你木屑一樣的腦子能搞懂。",
          DialogueId = 90180103,
          GUID = "E1C1A526",
          NextDialogue = 90180104,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_2"
        },
        [90180104] = {
          ContentTC = "好沒禮貌的炸彈，扔了算了。",
          DialogueId = 90180104,
          GUID = "E1C1A550",
          NextDialogue = 90180105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Angry01_End"
          }
        },
        [90180105] = {
          ContentTC = "耶爾：奧利弗他、他他是個好孩子！雖然看看上去脾氣不好，說話有點凶，還總總總是突然冒出來，但……",
          DialogueId = 90180105,
          GUID = "E1C1A57A",
          NextDialogue = 90180106,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_3"
        },
        [90180106] = {
          ContentTC = "奧利弗：喂，有你這麼誇獎人的嗎？",
          DialogueId = 90180106,
          GUID = "E1C1A5A4",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90180201] = {
          ContentTC = "耶爾：我……可能派不上什麼用場。唯一擅長的……可能就只有製作「小可愛」了吧？",
          DialogueId = 90180201,
          GUID = "E1C1B53A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180203,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_1"
        },
        [90180203] = {
          ContentTC = "嗯？「小可愛」是什麼？",
          DialogueId = 90180203,
          GUID = "E1C1B58E",
          NextDialogue = 90180204,
          SpeakNpcId = 100001
        },
        [90180204] = {
          ContentTC = "耶爾：「小可愛」……是「劈里啪啦」玩具店中……最受歡迎的商品，製作它們，要花費不少時間。",
          DialogueId = 90180204,
          GUID = "E1C1B5B8",
          NextDialogue = 90180205,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_2"
        },
        [90180205] = {
          ContentTC = "耶爾：但，不是因為我的技藝……有多好，只是因為，奧利弗他很熟悉。",
          DialogueId = 90180205,
          GUID = "E1C1B5E2",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90180301] = {
          ContentTC = "耶爾：啊，抱歉！但、但是要是說得快了，我的舌頭就就就容易打結。",
          DialogueId = 90180301,
          GUID = "E1C1C5A2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180303,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_1"
        },
        [90180303] = {
          ContentTC = "那和別人交流起來應該還挺不容易的。",
          DialogueId = 90180303,
          GUID = "E1C1C5F6",
          NextDialogue = 90180304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Sigh_End"
          }
        },
        [90180304] = {
          ContentTC = "耶爾：還、還好，有時候奧利弗會幫我說......而且，旁邊沒有人的時候，奧利弗總會把我想說的話聽完的。",
          DialogueId = 90180304,
          GUID = "E1C1C620",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90180401] = {
          ContentTC = "耶爾：我沒有「小時候」……我從記事的時候，就在這個大孩子的身體裡了。奧利弗也許有吧。",
          DialogueId = 90180401,
          GUID = "E1C1D60A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180403,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_1"
        },
        [90180403] = {
          ContentTC = "少了很多回憶，有點遺憾。",
          DialogueId = 90180403,
          GUID = "E1C1D65E",
          NextDialogue = 90180404,
          SpeakNpcId = 100001
        },
        [90180404] = {
          ContentTC = "耶爾：我也想過如果能有「童年」，應該會是……怎樣的呢？每晚睡覺前……瓊斯先生會不會像普通的爸爸一樣，坐在我的床頭……給我講故事……",
          DialogueId = 90180404,
          GUID = "E1C1D688",
          NextDialogue = 90180405,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_2"
        },
        [90180405] = {
          ContentTC = "奧利弗：瓊斯那混蛋講故事？你腦子進膠水了嗎？",
          DialogueId = 90180405,
          GUID = "E1C1D6B2",
          NextDialogue = 90180406,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_3"
        },
        [90180406] = {
          ContentTC = "耶爾：對對對不起！我我知道的，他只關心實驗，不會做這些……",
          DialogueId = 90180406,
          GUID = "E1C1D6DC",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90180501] = {
          ContentTC = "耶爾：您，您好……您的歌聲，真的很、很動聽。",
          DialogueId = 90180501,
          GUID = "E1C1E672",
          NextDialogue = 90180502,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_1"
        },
        [90180502] = {
          ContentTC = "奧利弗：哼，又一隻可憐蟲。",
          DialogueId = 90180502,
          GUID = "E1C1E69C",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_2"
        },
        [90180601] = {
          ContentTC = "榛子……是你的朋友嗎？我也有很好的朋友，他像榛、榛子一樣可靠。",
          DialogueId = 90180601,
          GUID = "E1C1F6DA",
          NextDialogue = 90180602,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_1"
        },
        [90180602] = {
          ContentTC = "奧利弗：你罵誰呢？",
          DialogueId = 90180602,
          GUID = "E1C1F704",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_2"
        },
        [90180701] = {
          ContentTC = "耶爾：唔啊……你、你不要生氣，我的炸彈實驗都是符！符符符符合安全規定的……",
          DialogueId = 90180701,
          GUID = "E1C20742",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_03"
        },
        [90190000] = {
          ContentTC = "難得有這麼悠閒的時光，沒有傷患的呼救，也沒有緊急的戰報。嗯……泡杯咖啡，把那本小說看完吧。公主最後到底跟誰在一起了呢……",
          DialogueId = 90190000,
          GUID = "E1C7FD09",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_idle"
        },
        [90190001] = {
          ContentTC = "很高興看到您今天健康平安。請多加珍重……為了終有一天會到來的和平。",
          DialogueId = 90190001,
          GUID = "E1C7FD0A",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextOptions = {
            [1] = 901900011,
            [2] = 901900012,
            [3] = 901900013,
            [4] = 901900014,
            [5] = 901900015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90190002] = {
          ContentTC = "聊點別的",
          DialogueId = 90190002,
          GUID = "90190002.0",
          NextDialogue = 90190001
        },
        [90190003] = {
          ContentTC = "再見",
          DialogueId = 90190003,
          GUID = "90190003.0"
        },
        [90190101] = {
          ContentTC = "我……沒有什麼特別的愛好。也許讀書算一個吧？",
          DialogueId = 90190101,
          GUID = "E1C80D72",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190102,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_1"
        },
        [90190102] = {
          ContentTC = "雖然媽媽總是嘮叨，說我一直把自己關在家裡，錯過了那些舞會和沙龍，會失去很多躋身更上一層的機會……",
          DialogueId = 90190102,
          GUID = "E1C80D9C",
          NextDialogue = 90190103,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_2"
        },
        [90190103] = {
          ContentTC = "但我還是覺得，這樣就很好。",
          DialogueId = 90190103,
          GUID = "E1C80DC6",
          NextDialogue = 90190104,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_3"
        },
        [90190104] = {
          ContentTC = "那你最近在看什麼書？",
          DialogueId = 90190104,
          GUID = "E1C80DF0",
          NextDialogue = 90190105,
          SpeakNpcId = 100001
        },
        [90190105] = {
          ContentTC = "主要是戰傷救治相關的書籍，《戰地應急救援策略》、《常規外傷處理》、《野戰醫院的臨時搭建》……",
          DialogueId = 90190105,
          GUID = "E1C80E1A",
          NextDialogue = 90190106,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_4"
        },
        [90190106] = {
          ContentTC = "您也許知道，我過去學習的方向並非救護相關，儘管我已經獲得了軍團隨行醫務員的資格，但仍然時常感到沉重與惶恐。",
          DialogueId = 90190106,
          GUID = "E1C80E44",
          NextDialogue = 90190107,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_5"
        },
        [90190107] = {
          ContentTC = "你也要適當放鬆一下，不要讓自己太緊繃了。",
          DialogueId = 90190107,
          GUID = "E1C80E6E",
          NextDialogue = 90190108,
          SpeakNpcId = 100001
        },
        [90190108] = {
          ContentTC = "嗯，最近我也在看一本叫做《玻璃鞋》的書。是關於……呃，公主和騎士……我、我並不是非常喜歡看浪漫小說！只是，隨便……翻一下……",
          DialogueId = 90190108,
          GUID = "E1C80E98",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90190201] = {
          ContentTC = "嗯，當然可以！它是海伯利亞的基石，是學者們口中「原初的奇蹟」！",
          DialogueId = 90190201,
          GUID = "E1C81DDA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190202,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_1"
        },
        [90190202] = {
          ContentTC = "最一開始，人們試圖從月石中分離出黃金，但後來，人們發現這枚小小的石頭還有更多用途——轉動機械的齒輪，釋放電的火花……它就是索拉之民的「魔法」。",
          DialogueId = 90190202,
          GUID = "E1C81E04",
          NextDialogue = 90190203,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_2"
        },
        [90190203] = {
          ContentTC = "……只是後來，煉金院……",
          DialogueId = 90190203,
          GUID = "E1C81E2E",
          NextDialogue = 90190204,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_3"
        },
        [90190204] = {
          ContentTC = "你好像在煉金院待過？",
          DialogueId = 90190204,
          GUID = "E1C81E58",
          NextDialogue = 90190205,
          SpeakNpcId = 100001
        },
        [90190205] = {
          ContentTC = "……是的。不過，那已經是過去的事了。",
          DialogueId = 90190205,
          GUID = "E1C81E82",
          NextDialogue = 90190206,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_4"
        },
        [90190206] = {
          ContentTC = "你為什麼要離開煉金院？",
          DialogueId = 90190206,
          GUID = "E1C81EAC",
          NextDialogue = 90190207,
          SpeakNpcId = 100001
        },
        [90190207] = {
          ContentTC = "因為後來的佩劍煉金院偏離了軌道，走在了一條錯誤的路上。它是海伯利亞這座戰車最熾熱的爐芯，但燃料卻是太多人的痛苦和不幸。",
          DialogueId = 90190207,
          GUID = "E1C81ED6",
          NextDialogue = 90190208,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_5"
        },
        [90190208] = {
          ContentTC = "我想，我遠比自己想像中更軟弱。我無法說服自己接受它，也沒有勇氣和力量阻止它。所以，我只能選擇逃離它。",
          DialogueId = 90190208,
          GUID = "E1C81F00",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90190301] = {
          ContentTC = "一些應急的器械和藥品。繃帶，消毒劑，麻醉劑，還有處理外傷的刀片和縫線。",
          DialogueId = 90190301,
          GUID = "E1C82E42",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190302,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_1"
        },
        [90190302] = {
          ContentTC = "此外，還有一張手帕和一把梳子。",
          DialogueId = 90190302,
          GUID = "E1C82E6C",
          NextDialogue = 90190303,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_2"
        },
        [90190303] = {
          ContentTC = "戰場上也要梳妝嗎？達芙涅很愛美呢。",
          DialogueId = 90190303,
          GUID = "E1C82E96",
          NextDialogue = 90190304,
          SpeakNpcId = 100001
        },
        [90190304] = {
          ContentTC = "啊，這個……不是我自己用的。如果救護的傷員不幸離世，我會幫他們簡單整理一下儀容。",
          DialogueId = 90190304,
          GUID = "E1C82EC0",
          NextDialogue = 90190305,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_3"
        },
        [90190305] = {
          ContentTC = "傷痛是很殘忍的東西，它從人們那裡奪走的，除了生命，還有生而為人的全部尊嚴。",
          DialogueId = 90190305,
          GUID = "E1C82EEA",
          NextDialogue = 90190306,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_4"
        },
        [90190306] = {
          ContentTC = "我希望……他們的家人看到的他們，可以乾淨一些、安詳一些……久別重逢，父母應該看到孩子們安然睡去的臉，而不是被疼痛扭曲五官的悽慘面容。",
          DialogueId = 90190306,
          GUID = "E1C82F14",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90190401] = {
          ContentTC = "我沒關係，不辛苦的！……呃，其實還是有點……急救和護理知識的學習還好，但體能測驗確實令人苦惱。",
          DialogueId = 90190401,
          GUID = "E1C83EAA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190402,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_1"
        },
        [90190402] = {
          ContentTC = "就算每天比大家起得更早獨自加練，還是只能拿勉強及格的分數……唉，不要笑話我，鍛鍊體力真是比讀書難太多了。",
          DialogueId = 90190402,
          GUID = "E1C83ED4",
          NextDialogue = 90190403,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_2"
        },
        [90190403] = {
          ContentTC = "早起加練，聽起來好累啊。",
          DialogueId = 90190403,
          GUID = "E1C83EFE",
          NextDialogue = 90190404,
          SpeakNpcId = 100001
        },
        [90190404] = {
          ContentTC = "嗯，的確很累。不過當我把注意力從腳下移開，去看城郊的麥田，地平線盡頭的小屋，去聽風車的每一聲轉動和牧牛人的每一聲哨笛，就覺得平靜許多。",
          DialogueId = 90190404,
          GUID = "E1C83F28",
          NextDialogue = 90190405,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_3"
        },
        [90190405] = {
          ContentTC = "因為……也許我奔跑在這條路上，就是為了保護這些最普通、最尋常的東西不被毀掉吧。",
          DialogueId = 90190405,
          GUID = "E1C83F52",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90190501] = {
          ContentTC = "……我最後一次和爸爸說話，就是在對講機裡。那時還在龍莎要塞危機四伏的戰場，他卻對我說，「你放心。」",
          DialogueId = 90190501,
          GUID = "E1C84F12",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190502,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_1"
        },
        [90190502] = {
          ContentTC = "後來我還是會常常在深夜打開自己的對講機，調到爸爸的頻段，按下呼叫按鈕，期待著他的聲音從對講機那頭傳來……",
          DialogueId = 90190502,
          GUID = "E1C84F3C",
          NextDialogue = 90190503,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_2"
        },
        [90190503] = {
          ContentTC = "直到我對著聽筒等了十幾分鐘，我才突然發現，他是真的回不來了。",
          DialogueId = 90190503,
          GUID = "E1C84F66",
          NextDialogue = 90190504,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_3"
        },
        [90190504] = {
          ContentTC = "請你節哀……",
          DialogueId = 90190504,
          GUID = "E1C84F90",
          NextDialogue = 90190505,
          SpeakNpcId = 100001
        },
        [90190505] = {
          ContentTC = "謝謝，我明白的。我會好好活下去，在為父親、為龍莎戰役的死難者洗刷冤屈之前，我不會停下腳步。",
          DialogueId = 90190505,
          GUID = "E1C84FBA",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_4",
          bForbidSkipOptions = true
        },
        [90190601] = {
          ContentTC = "我曾在皇都的圖書館中閱讀過華胥的醫書，雖然與海伯利亞的醫理不太相同，但應用於救治卻十分有效。這本書中我仍有一些問題，方便向您請教嗎？",
          DialogueId = 90190601,
          GUID = "E1C85F7A",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_01"
        },
        [90190701] = {
          ContentTC = "典獄長女士，遲來的正義真的還是正義嗎？",
          DialogueId = 90190701,
          GUID = "E1C86FE2",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_02"
        }
      }
    end
  },
  {
    MinKey = 90190801,
    MaxKey = 90250403,
    Loader = function()
      return {
        [90190801] = {
          ContentTC = "好久不見，自離開煉金院後我們就很少聯繫了，你還……好嗎？",
          DialogueId = 90190801,
          GUID = "E1C8804A",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_03"
        },
        [90190901] = {
          ContentTC = "雖然我已經離開了佩劍煉金院，但那依舊是我學習過的地方。也許您永遠不會選擇寬恕，但還是請允許我說一句，對不起。",
          DialogueId = 90190901,
          GUID = "E1C890B2",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_04"
        },
        [90200000] = {
          ContentTC = "噓……我就快要進入角色了。",
          DialogueId = 90200000,
          GUID = "E1CE65A9",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_idle"
        },
        [90200001] = {
          ContentTC = "如今我扮演破碎的囚徒，而你是為我執掌枷鎖的典獄長。",
          DialogueId = 90200001,
          GUID = "E1CE65AA",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextOptions = {
