          },
          RandomOptionNum = 3,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90200002] = {
          ContentTC = "聊點別的",
          DialogueId = 90200002,
          GUID = "90200002.0",
          NextDialogue = 90200001
        },
        [90200003] = {
          ContentTC = "再見",
          DialogueId = 90200003,
          GUID = "90200003.0"
        },
        [90200101] = {
          ContentTC = "他是被摔碎的玻璃燈，是灑在汙水溝裡的星星。",
          DialogueId = 90200101,
          GUID = "E1CE7612",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200102,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_1"
        },
        [90200102] = {
          ContentTC = "…………？",
          DialogueId = 90200102,
          GUID = "E1CE763C",
          NextDialogue = 90200103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81103:Talk01_End"
          }
        },
        [90200103] = {
          ContentTC = "和那些東西一樣，荒誕的惹人發笑，卻又閃閃發亮。",
          DialogueId = 90200103,
          GUID = "E1CE7666",
          NextDialogue = 90200104,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_2"
        },
        [90200104] = {
          ContentTC = "我們的牢房只隔著一道牆，隔音差得讓人絕望。他就在我看不見的一米之外，一會兒回憶家人，一會兒憧憬未來，一會兒又五音不全地哼起歌。",
          DialogueId = 90200104,
          GUID = "E1CE7690",
          NextDialogue = 90200105,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_3"
        },
        [90200105] = {
          ContentTC = "有時我甚至恍惚覺得，我不是被關在籠子裡的困獸，而是一個無憂無慮的普通學生，在午後打盹時做了個惡夢，被鄰座聒噪的同學吵醒了。",
          DialogueId = 90200105,
          GUID = "E1CE76BA",
          NextDialogue = 90200106,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_4"
        },
        [90200106] = {
          ContentTC = "所以，你被他吸引，和他成為了朋友。",
          DialogueId = 90200106,
          GUID = "E1CE76E4",
          NextDialogue = 90200107,
          SpeakNpcId = 100001
        },
        [90200107] = {
          ContentTC = "……呵，也許吧。",
          DialogueId = 90200107,
          GUID = "E1CE770E",
          NextDialogue = 90200108,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_5"
        },
        [90200108] = {
          ContentTC = "但「朋友」是一個過於耀眼的詞語，我不配擁有它。或許更應該算是，乾枯河床裡擱淺的兩條魚吧。",
          DialogueId = 90200108,
          GUID = "E1CE7738",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90200201] = {
          ContentTC = "為什麼？「帕西法爾」的人生早已落幕。那個名字太遙遠了，遠到我懷疑自己是否曾真的擁有它。",
          DialogueId = 90200201,
          GUID = "E1CE867A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200202,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_1"
        },
        [90200202] = {
          ContentTC = "但對我來說，你的存在是真實的。",
          DialogueId = 90200202,
          GUID = "E1CE86A4",
          NextDialogue = 90200203,
          SpeakNpcId = 100001
        },
        [90200203] = {
          ContentTC = "……是嗎？",
          DialogueId = 90200203,
          GUID = "E1CE86CE",
          NextDialogue = 90200204,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_2"
        },
        [90200204] = {
          ContentTC = "好吧。既然如此，我會把這最後一場戲一直演下去──為了我最後的、唯一的觀眾。",
          DialogueId = 90200204,
          GUID = "E1CE86F8",
          NextDialogue = 90200205,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_3"
        },
        [90200205] = {
          ContentTC = "謝謝你，讓我停駐在你的舞台上。",
          DialogueId = 90200205,
          GUID = "E1CE8722",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90200301] = {
          ContentTC = "多謝你的慷慨。但我的承諾都已兌現，我已經不再有什麼值得眷念的事。",
          DialogueId = 90200301,
          GUID = "E1CE96E2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200302,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_1"
        },
        [90200302] = {
          ContentTC = "…………",
          DialogueId = 90200302,
          GUID = "E1CE970C",
          NextDialogue = 90200303,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_2"
        },
        [90200303] = {
          ContentTC = "若你有一天在蓋雷亞劇院遇到我的恩師薇奧萊塔女士，請轉告她，我已在伊瑟爾定居。現在過得很好，請不要擔憂。",
          DialogueId = 90200303,
          GUID = "E1CE9736",
          NextDialogue = 90200304,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_3"
        },
        [90200304] = {
          ContentTC = "「那是音樂與詩的國度，那裡的每一顆卵石都敲擊著節拍，每一泓泉水都歌唱著旋律。」",
          DialogueId = 90200304,
          GUID = "E1CE9760",
          NextDialogue = 90200305,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_4"
        },
        [90200305] = {
          ContentTC = "這樣一來，或許她就不會再打聽我的下落了。我曾是她欣賞的學生……我不希望她因我蒙羞。",
          DialogueId = 90200305,
          GUID = "E1CE978A",
          NextDialogue = 90200306,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_5"
        },
        [90200306] = {
          ContentTC = "善意的欺騙嗎……",
          DialogueId = 90200306,
          GUID = "E1CE97B4",
          NextDialogue = 90200307,
          SpeakNpcId = 100001
        },
        [90200307] = {
          ContentTC = "嗯，一無所知總會是更加幸福的。",
          DialogueId = 90200307,
          GUID = "E1CE97DE",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
          bForbidSkipOptions = true
        },
        [90200401] = {
          ContentTC = "為什麼想學表演？你不需要變成任何人。",
          DialogueId = 90200401,
          GUID = "E1CEA74A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200402,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_1"
        },
        [90200402] = {
          ContentTC = "「變成任何人」？",
          DialogueId = 90200402,
          GUID = "E1CEA774",
          NextDialogue = 90200403,
          SpeakNpcId = 100001
        },
        [90200403] = {
          ContentTC = "只要站在舞台上，把你的每一寸骨骼，每一縷氣息奉獻給演出，你就可以徹底變成另一個人，忘記帶給你痛苦的一切，走向你前所未見的世界。",
          DialogueId = 90200403,
          GUID = "E1CEA79E",
          NextDialogue = 90200404,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_2"
        },
        [90200404] = {
          ContentTC = "但你生而就是一位冒險故事裡被祝福的主人公，擁有所有角色的矚目和信賴。你無需舞台，便足以熠熠生輝。",
          DialogueId = 90200404,
          GUID = "E1CEA7C8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90200501] = {
          ContentTC = "它站在那兒，歷經遠比我的生命悠長的歲月。在它外牆的這一邊，是巍峨的內城，和烏雲一樣高，比烏雲更冷。",
          DialogueId = 90200501,
          GUID = "E1CEB7B2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200502,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_1"
        },
        [90200502] = {
          ContentTC = "人們從裹著絲綢的馬車走來，談論總不放晴的天氣，談論詩歌與繪畫，談論舞會與婚事，抱怨外城污濁的雪水弄髒了漂亮的皮靴。",
          DialogueId = 90200502,
          GUID = "E1CEB7DC",
          NextDialogue = 90200503,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_2"
        },
        [90200503] = {
          ContentTC = "外牆的另一側，是嘈雜的霧區。在那裡，小販扯尖嗓子叫賣，母親抱著自己的孩子，乞求一片黑麵包果腹。好事者一邊躲著衛兵，一邊在牆上塗鴉。",
          DialogueId = 90200503,
          GUID = "E1CEB806",
          NextDialogue = 90200504,
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_3"
        },
        [90200504] = {
          ContentTC = "這就是我們的蓋雷亞劇院。它站在那兒，聽著這些聲音，但又聽不懂這些聲音。",
          DialogueId = 90200504,
          GUID = "E1CEB830",
          NextDialogue = 90200505,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_4"
        },
        [90200505] = {
          ContentTC = "那，那裡有什麼關於你自己的回憶嗎？",
          DialogueId = 90200505,
          GUID = "E1CEB85A",
          NextDialogue = 90200506,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81103:Confident_End"
          }
        },
        [90200506] = {
          ContentTC = "……不知為什麼，我第一個想起的不是各種劇本，不是花俏的戲服和首飾，甚至不是每天打掃的小道具間。",
          DialogueId = 90200506,
          GUID = "E1CEB884",
          NextDialogue = 90200507,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_5"
        },
        [90200507] = {
          ContentTC = "我想起的是演出落幕後，舞台上那襲薄毛毯。小時候，記憶裡的第一場演出結束後，我和母親在那兒重複著劇裡的唱詞，跳了整夜的舞。",
          DialogueId = 90200507,
          GUID = "E1CEB8AE",
          NextDialogue = 90200508,
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_6"
        },
        [90200508] = {
          ContentTC = "日出時分我累了，就躺在那襲絨毯上，枕著她的兩膝，做了一個長長的夢。",
          DialogueId = 90200508,
          GUID = "E1CEB8D8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          TalkActionId = {
            [1] = "81103:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
          bForbidSkipOptions = true
        },
        [90200601] = {
          ContentTC = "你最近過得好嗎？\n……抱歉，是我唐突了。我們並不相識，我只是……替一個朋友問問罷了。",
          DialogueId = 90200601,
          GUID = "E1CEC81A",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_01"
        },
        [90200701] = {
          ContentTC = "是嗎，你現在有了一個新家，也有了會關心照顧你的家人……真是太好了。你逃出了自己的囚籠，是個勇敢的孩子。",
          DialogueId = 90200701,
          GUID = "E1CED882",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_02"
        },
        [90200801] = {
          ContentTC = "詩人小姐，您演奏的這首樂曲十分動聽，請問它的曲名是？\n原來是您自己寫的曲子……真是令人羨慕的才華。或許，我能有幸看一看樂譜嗎？",
          DialogueId = 90200801,
          GUID = "E1CEE8EA",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_03"
        },
        [90200901] = {
          ContentTC = "你的擬態能力非常特別，哪怕是最優秀的舞台道具師也未必能做出這樣精妙絕倫的效果。",
          DialogueId = 90200901,
          GUID = "E1CEF952",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_04"
        },
        [90201001] = {
          ContentTC = "我不需要一面鏡子，來時刻提醒自己醜陋的模樣。",
          DialogueId = 90201001,
          GUID = "E1CF09BA",
          SpeakNpcId = 81103,
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_05"
        },
        [90210000] = {
          ContentTC = "有沒有什麼任務可以安排給我？不，我並非有多喜歡工作，而是……一種慣性吧。如果無法讓自己忙碌起來，我總覺得坐立難安。",
          DialogueId = 90210000,
          GUID = "E1D4CE49",
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_idle"
        },
        [90210001] = {
          ContentTC = "今日據點巡邏結束。未發現危險生物，未發現牆壁開裂，未發現可疑記號，潛在威脅排除，可照例進行日常生活，報告完畢。",
          DialogueId = 90210001,
          GUID = "E1D4CE4A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextOptions = {
            [1] = 902100011,
            [2] = 902100012,
            [3] = 902100013,
            [4] = 902100014,
            [5] = 902100015,
            [6] = 902100016,
            [7] = 902100017
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_welcome",
          bForbidSkipOptions = true
        },
        [90210002] = {
          ContentTC = "聊點別的",
          DialogueId = 90210002,
          GUID = "90210002.0",
          NextDialogue = 90210001
        },
        [90210003] = {
          ContentTC = "再見",
          DialogueId = 90210003,
          GUID = "90210003.0"
        },
        [90210101] = {
          ContentTC = "呃……你注意到了啊，我是有一把親人留下的口琴。好好地鎖了起來，但又總擔心它會突然消失不見，所以會時不時，忍不住地去確認一下。",
          DialogueId = 90210101,
          GUID = "E1D4DEB2",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210102,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_1"
        },
        [90210102] = {
          ContentTC = "那麼你一定會很多首曲子啦？",
          DialogueId = 90210102,
          GUID = "E1D4DEDC",
          NextDialogue = 90210103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84101:Explain02_End"
          }
        },
        [90210103] = {
          ContentTC = "其實只會一首，還是親人教給我的。我學得也不是很快，因為實在不擅長音樂這樣需要情緒起伏的東西……",
          DialogueId = 90210103,
          GUID = "E1D4DF06",
          NextDialogue = 90210104,
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_2"
        },
        [90210104] = {
          ContentTC = "不過，每當我太過緊張或者太過開心的時候，總會暗暗握住它，這能讓我想到很多我確信的事，反而能夠讓我冷靜一些。",
          DialogueId = 90210104,
          GUID = "E1D4DF30",
          NextDialogue = 90210105,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_3"
        },
        [90210105] = {
          ContentTC = "我的許多同僚會因為壓力而去找醫生，需要鎮定或者興奮。我不需要那些，心跳快一拍也好慢一拍也罷，口琴會幫找回正常的節拍。",
          DialogueId = 90210105,
          GUID = "E1D4DF5A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90210201] = {
          ContentTC = "還不錯，軍團是一個只要努力就能獲得回報的地方。我現在受到了認可，擁有幾名部下，我還可以命令他們一定要平等對待卡戎之民和索拉之民。",
          DialogueId = 90210201,
          GUID = "E1D4EF1A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210202,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_1"
        },
        [90210202] = {
          ContentTC = "我聽過許多人抱怨甚至謾罵軍團對於卡戎之民過度嚴苛，而我能盡可能去緩和這些聲音……我希望日子久了，可以讓大家眼裡的軍團變得有那麼一點點不一樣。",
          DialogueId = 90210202,
          GUID = "E1D4EF44",
          NextDialogue = 90210203,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_2"
        },
        [90210203] = {
          ContentTC = "可是像你這樣的人還是太少了。",
          DialogueId = 90210203,
          GUID = "E1D4EF6E",
          NextDialogue = 90210204,
          SpeakNpcId = 100001
        },
        [90210204] = {
          ContentTC = "會慢慢多起來的，在更早之前軍團裡連一個卡戎都沒有呢。我雖然能做的不多，但是只要我堅持這樣教導部下，那麼卡戎之民和索拉之民的矛盾就會變少。",
          DialogueId = 90210204,
          GUID = "E1D4EF98",
          NextDialogue = 90210205,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_3"
        },
        [90210205] = {
          ContentTC = "是的，平等對待所有人，努力保護大家遠離穢獸和穢蝕的威脅，就一定能讓卡戎們的境遇好上一些，冰湖城裡的嘆氣聲也能少一些。",
          DialogueId = 90210205,
          GUID = "E1D4EFC2",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90210301] = {
          ContentTC = "談不上負責，我只是嚴格遵守了衛戍部隊規章的所有內容而已。",
          DialogueId = 90210301,
          GUID = "E1D4FF82",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210302,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_1"
        },
        [90210302] = {
          ContentTC = "可是其他人好像都不遵守什麼規定，橫行霸道的。",
          DialogueId = 90210302,
          GUID = "E1D4FFAC",
          NextDialogue = 90210303,
          SpeakNpcId = 100001
        },
        [90210303] = {
          ContentTC = "規章規定不允許隨意討論同僚的言行，否則會被視為違背軍紀。",
          DialogueId = 90210303,
          GUID = "E1D4FFD6",
          NextDialogue = 90210304,
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_2"
        },
        [90210304] = {
          ContentTC = "不過實話說，我不理解他們是怎麼想的，可能覺得衛戍部隊就只是一份普通的工作，只要不被上司發現，怎麼胡鬧都無所謂。",
          DialogueId = 90210304,
          GUID = "E1D50000",
          NextDialogue = 90210305,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_3"
        },
        [90210305] = {
          ContentTC = "我覺得，不應該這樣，人應該遵循著固定的規則而活著，否則的話，就會不斷放低對自己的要求，過一天算一天，最後只能和下水道的老鼠混在一起。",
          DialogueId = 90210305,
          GUID = "E1D5002A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90210401] = {
          ContentTC = "不用了……抱歉，我不太喜歡照鏡子。畢竟一眼就能看到頭上的角，總覺得有些難受……",
          DialogueId = 90210401,
          GUID = "E1D50FEA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210402,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_1"
        },
        [90210402] = {
          ContentTC = "原來你不喜歡卡戎之民的外表啊……",
          DialogueId = 90210402,
          GUID = "E1D51014",
          NextDialogue = 90210403,
          SpeakNpcId = 100001
        },
        [90210403] = {
          ContentTC = "不，我並非對我們一族的外表自輕自賤。我只是覺得，如果它能長得更規則、更對稱一些，也許會看起來舒服很多。啊，不是，我也沒有在說你的角……",
          DialogueId = 90210403,
          GUID = "E1D5103E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90210501] = {
          ContentTC = "還在，只是它現在變得好沉重，太沉重了……我不知道自己是否還有力氣再次握起它，吹奏下去。",
          DialogueId = 90210501,
          GUID = "E1D52052",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210502,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_1"
        },
        [90210502] = {
          ContentTC = "畢竟，這把口琴曾裝載了我全部的期待與夢想。",
          DialogueId = 90210502,
          GUID = "E1D5207C",
          NextDialogue = 90210503,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_2"
        },
        [90210503] = {
          ContentTC = "如果有一天你能重新吹起它，讓我做你的第一個聽眾吧。",
          DialogueId = 90210503,
          GUID = "E1D520A6",
          NextDialogue = 90210504,
          SpeakNpcId = 100001
        },
        [90210504] = {
          ContentTC = "……我明白了。我答應你，等將來有一天，我能夠再次拿起這把口琴，去學習新曲子的時候……一定第一個吹奏給你聽。",
          DialogueId = 90210504,
          GUID = "E1D520D0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90210601] = {
          ContentTC = "我每天都會接到一些零工，夠我一個人日常開銷和吃穿用度。不過，對現在的我來說，工作與其說是為了糊口，不如說是為了工作本身。",
          DialogueId = 90210601,
          GUID = "E1D530BA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210602,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_1"
        },
        [90210602] = {
          ContentTC = "為了工作本身？",
          DialogueId = 90210602,
          GUID = "E1D530E4",
          NextDialogue = 90210603,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84101:Talk02_End"
          }
        },
        [90210603] = {
          ContentTC = "工作讓我的生活充實無比，工作讓我的心情更加快樂，有工作的日子，太陽都會更暖和一點。",
          DialogueId = 90210603,
          GUID = "E1D5310E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_2",
          bForbidSkipOptions = true
        },
        [90210701] = {
          ContentTC = "至少比待在裡面要好。軍團曾是我安身的庇護所，是我的夢想所在。但是現在夢想成了謊言，我以為的庇護所是讓家人萬劫不復的地獄……",
          DialogueId = 90210701,
          GUID = "E1D54122",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210702,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_1"
        },
        [90210702] = {
          ContentTC = "我無法釋懷家人的仇，可是我也無法對昔日的同僚拔槍相向。我真的不知道……告訴我，我應該怎麼辦才好？",
          DialogueId = 90210702,
          GUID = "E1D5414C",
          NextDialogue = 90210703,
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_2"
        },
        [90210703] = {
          ContentTC = "我想這個問題只能由你自己回答。",
          DialogueId = 90210703,
          GUID = "E1D54176",
          NextDialogue = 90210704,
          SpeakNpcId = 100001
        },
        [90210704] = {
          ContentTC = "……抱歉，剛才是我失態了。你說得沒錯，我應該自己找出答案，而不是把問題推給你。雖然，這可能還要花上很長的時間吧……",
          DialogueId = 90210704,
          GUID = "E1D541A0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_3",
          bForbidSkipOptions = true
        },
        [90210801] = {
          ContentTC = "每次看見歪歪扭扭的東西時，我總是忍不住想要把它們擺正一些。但是在希爾妲小姐這裡就完全不會遇上這種問題，你在的地方總是井井有條，真好。",
          DialogueId = 90210801,
          GUID = "E1D5518A",
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_01"
        },
        [90210901] = {
          ContentTC = "這份計劃書上的安排詳略得當，精確到秒，逐步完成這些安排想必能獲得巨大的滿足感。只是……真的很難把這樣嚴密的計畫與蘭迪長官聯繫起來。",
          DialogueId = 90210901,
          GUID = "E1D561F2",
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_02"
        },
        [90211001] = {
          ContentTC = "如果可以，可以請你換一首曲子嗎？不……你彈的旋律很美，只是我有些……害怕聽到那支曲子，它總讓我想起一些舊事。",
          DialogueId = 90211001,
          GUID = "E1D5725A",
          SpeakNpcId = 84101,
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_03"
        },
        [90220000] = {
          ContentTC = "在這紛爭的土地上，能擁有這麼一方安寧天地，享受片刻放鬆的時光，也不錯。",
          DialogueId = 90220000,
          GUID = "E1DB36E9",
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_idle"
        },
        [90220001] = {
          ContentTC = "是你呀，親愛的孩子。日安，有什麼事想要講給我聽嗎？",
          DialogueId = 90220001,
          GUID = "E1DB36EA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextOptions = {
            [1] = 902200011,
            [2] = 902200012,
            [3] = 902200013,
            [4] = 902200014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90220002] = {
          ContentTC = "聊點別的",
          DialogueId = 90220002,
          GUID = "90220002.0",
          NextDialogue = 90220001
        },
        [90220003] = {
          ContentTC = "再見",
          DialogueId = 90220003,
          GUID = "90220003.0"
        },
        [90220101] = {
          ContentTC = "是的，在漫長的時間中，我在阿特拉西亞的各處旅行——或者流浪。我用雙足丈量過這片土地的每一寸刻度，也用手指摩挲過它的每一縷紋理。",
          DialogueId = 90220101,
          GUID = "E1DB4752",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220102,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_1"
        },
        [90220102] = {
          ContentTC = "那你最喜歡的地方是哪裡？",
          DialogueId = 90220102,
          GUID = "E1DB477C",
          NextDialogue = 90220103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81502:Explain01_End"
          }
        },
        [90220103] = {
          ContentTC = "如果你走過足夠多的地方，會覺得各處的風景並無太多差別。北境的飛雪，赫墨的砂礫，或者華胥的炊煙，無非也是另一種林間的薄霧而已。",
          DialogueId = 90220103,
          GUID = "E1DB47A6",
          NextDialogue = 90220104,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_2"
        },
        [90220104] = {
          ContentTC = "如果一定要說個地方的話……那便是伊瑟爾的群山和林地。那裡的氣息最讓我感到安心。",
          DialogueId = 90220104,
          GUID = "E1DB47D0",
          NextDialogue = 90220105,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_3"
        },
        [90220105] = {
          ContentTC = "那我有機會也要去看看。",
          DialogueId = 90220105,
          GUID = "E1DB47FA",
          NextDialogue = 90220106,
          SpeakNpcId = 100001
        },
        [90220106] = {
          ContentTC = "好啊。",
          DialogueId = 90220106,
          GUID = "E1DB4824",
          NextDialogue = 90220107,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_4"
        },
        [90220107] = {
          ContentTC = "若有一天你去翡翠森林，請幫我帶一束白堇致候吧。在那裡長眠的啊，是我的友人、我的孩子、以及少時的我。",
          DialogueId = 90220107,
          GUID = "E1DB484E",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90220201] = {
          ContentTC = "霧海是一切生者的來處與歸途。萬物歸於霧海，霧海又孕育新的萬物……就像死去的雲滴落泥土，鮮花又自泥土中盛開。",
          DialogueId = 90220201,
          GUID = "E1DB57BA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220202,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_1"
        },
        [90220202] = {
          ContentTC = "有一天我也會去往那裡嗎？",
          DialogueId = 90220202,
          GUID = "E1DB57E4",
          NextDialogue = 90220203,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81502:Confident_End"
          }
        },
        [90220203] = {
          ContentTC = "我想是的。終有一天，你會前往霧海，前往茵布拉女神的懷抱。",
          DialogueId = 90220203,
          GUID = "E1DB580E",
          NextDialogue = 90220204,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_2"
        },
        [90220204] = {
          ContentTC = "聽上去有些可怕……",
          DialogueId = 90220204,
          GUID = "E1DB5838",
          NextDialogue = 90220205,
          SpeakNpcId = 100001
        },
        [90220205] = {
          ContentTC = "孩子，請你愛著生的一切，亦不要畏懼消亡。消亡並非苦痛，只是生命必經的終點。",
          DialogueId = 90220205,
          GUID = "E1DB5862",
          NextDialogue = 90220206,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_3"
        },
        [90220206] = {
          ContentTC = "若你累了，就在我的臂彎中安歇片刻吧……別害怕，這不會是永眠。現在的你，還有太多未竟之事。",
          DialogueId = 90220206,
          GUID = "E1DB588C",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90220301] = {
          ContentTC = "怎麼，這很讓你驚訝嗎？實不相瞞，在昔日「大遷徙」時，我還曾是一位在前線衝鋒陷陣的戰士，一位格鬥的好手。",
          DialogueId = 90220301,
          GUID = "E1DB6822",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220302,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_1"
        },
        [90220302] = {
          ContentTC = "雖說那是十分遙遠的過去，但基本的戰鬥技巧，我大體都還記得。",
          DialogueId = 90220302,
          GUID = "E1DB684C",
          NextDialogue = 90220303,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_2"
        },
        [90220303] = {
          ContentTC = "在旅途中，我也會時不時要與盤桓的獸群搏鬥，它們也曾帶給我爪痕，淤傷，甚至理當的死亡。",
          DialogueId = 90220303,
          GUID = "E1DB6876",
          NextDialogue = 90220304,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_3"
        },
        [90220304] = {
          ContentTC = "好難想像你近身搏鬥的樣子。",
          DialogueId = 90220304,
          GUID = "E1DB68A0",
          NextDialogue = 90220305,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81502:Talk02_End"
          }
        },
        [90220305] = {
          ContentTC = "亙古的月亮尚且每天都在變幻，人類當然更加複雜。更何況如我一般，經歷過數倍於常人歲月的人呢？",
          DialogueId = 90220305,
          GUID = "E1DB68CA",
          NextDialogue = 90220306,
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_4"
        },
        [90220306] = {
          ContentTC = "若是你對這段過往有興趣，改日我細細說於你聽吧。",
          DialogueId = 90220306,
          GUID = "E1DB68F4",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90220401] = {
          ContentTC = "「朋友」……以人們對這二字的通常定義來看，我有過很多朋友。",
          DialogueId = 90220401,
          GUID = "E1DB788A",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220402,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_1"
        },
        [90220402] = {
          ContentTC = "不過，提起這個詞，我最先想到的還是萊克西斯和艾瑞卡——就是帶我離開艾利西安的那兩位朋友。",
          DialogueId = 90220402,
          GUID = "E1DB78B4",
          NextDialogue = 90220403,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_2"
        },
        [90220403] = {
          ContentTC = "他們是怎樣的人？",
          DialogueId = 90220403,
          GUID = "E1DB78DE",
          NextDialogue = 90220404,
          SpeakNpcId = 100001
        },
        [90220404] = {
          ContentTC = "在後世的史書和英雄故事裡，他們通常被描述成揭下神明蒙昧的紗幕、將真理帶給人們的「智者」，以及為了智者崇奉的真理而犧牲的「英雄」……",
          DialogueId = 90220404,
          GUID = "E1DB7908",
          NextDialogue = 90220405,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_3"
        },
        [90220405] = {
          ContentTC = "但我常常回憶起他們還僅僅是「萊克西斯」和「艾瑞卡」的時候。",
          DialogueId = 90220405,
          GUID = "E1DB7932",
          NextDialogue = 90220406,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_4"
        },
        [90220406] = {
          ContentTC = "那時艾瑞卡是個勇敢活潑的姑娘，大家都很喜歡她。萊克西斯雖然頭腦很聰明，但有時候太較真，經常突然陷入沉思，所以反而會顯得有些遲鈍。",
          DialogueId = 90220406,
          GUID = "E1DB795C",
          NextDialogue = 90220407,
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_5"
        },
        [90220407] = {
          ContentTC = "你還記得什麼趣事嗎？",
          DialogueId = 90220407,
          GUID = "E1DB7986",
          NextDialogue = 90220408,
          SpeakNpcId = 100001
        },
        [90220408] = {
          ContentTC = "嗯……有一次，萊克西斯為了某件事去給艾瑞卡道歉，艾瑞卡便隨口指著士兵們用來練箭的靶子說，他要是能射中紅心就原諒他……",
          DialogueId = 90220408,
          GUID = "E1DB79B0",
          NextDialogue = 90220409,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_6"
        },
        [90220409] = {
          ContentTC = "當然，這是一句氣話。連士兵都不是每個人都做得到，更何況萊克西斯的雙手並不是用來握劍，而是用來書寫靈智與真理的。",
          DialogueId = 90220409,
          GUID = "E1DB79DA",
          NextDialogue = 90220410,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_7"
        },
        [90220410] = {
          ContentTC = "但他卻把這話當真了，趁士兵們歇息之後，一個人練習了一晚上。",
          DialogueId = 90220410,
          GUID = "E1DB7A04",
          NextDialogue = 90220411,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_8"
        },
        [90220411] = {
          ContentTC = "當然，歷史不是英雄傳說。即使是聰慧如萊克西斯，也有學不會的事。他一直練習到手心被磨出血，艾瑞卡為他包上麻布，也沒能射中靶心。",
          DialogueId = 90220411,
          GUID = "E1DB7A2E",
          NextDialogue = 90220412,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_9"
        },
        [90220412] = {
          ContentTC = "呵呵……最開始他們到底是為了什麼吵架，我反而記不起來了。真是奇怪……現在回憶有關他們的事，最先浮現的總是這些微不足道的細節。",
          DialogueId = 90220412,
          GUID = "E1DB7A58",
          NextDialogue = 90220413,
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_10"
        },
        [90220413] = {
          ContentTC = "聽起來是一段非常快樂的時光。",
          DialogueId = 90220413,
          GUID = "E1DB7A82",
          NextDialogue = 90220414,
          SpeakNpcId = 100001
        },
        [90220414] = {
          ContentTC = "嗯，是啊。那確實是……非常、非常快樂的日子。只是，已經是很久很久以前的事了。",
          DialogueId = 90220414,
          GUID = "E1DB7AAC",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_11",
          bForbidSkipOptions = true
        },
        [90220501] = {
          ContentTC = "人無法真正逃離自己的過去。總有一天，你會需要面對它們……希望到那時，你已經獲得了足夠與之對抗的力量。",
          DialogueId = 90220501,
          GUID = "E1DB88F2",
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_01"
        },
        [90220601] = {
          ContentTC = "姑娘，你身上有股熟悉的氣息，莫不是與我同為舊日之人？",
          DialogueId = 90220601,
          GUID = "E1DB995A",
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_02"
        },
        [90220701] = {
          ContentTC = "你好，孩子。呵呵……是啊，我們有著相似的角，說不定過去有些淵源。但那不是你的故事，不必深究，不必介懷，只管去做你想做的事就好。",
          DialogueId = 90220701,
          GUID = "E1DBA9C2",
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_03"
        },
        [90220801] = {
          ContentTC = "我雖擁有漫長的記憶，然而所見多為殘酷，能夠遺忘未必不是一種幸運。請相信，那些真正重要的東西，即便不被銘記，也終會回到你身邊。",
          DialogueId = 90220801,
          GUID = "E1DBBA2A",
          SpeakNpcId = 81502,
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_04"
        },
        [90230000] = {
          ContentTC = "薩麥爾，我們出發！",
          DialogueId = 90230000,
          GUID = "E1E19F60",
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_idle"
        },
        [90230001] = {
          ContentTC = "在傳頌會，只有被七件聖器選中的人才能成為「七美德」。當時有那麼多那麼多大力士，但只有我能拔出薩麥爾——既然它選擇了我，我也一定會好好對待它的！",
          DialogueId = 90230001,
          GUID = "E1E19F8A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextOptions = {
            [1] = 902300011,
            [2] = 902300012,
            [3] = 902300013,
            [4] = 902300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90230002] = {
          ContentTC = "聊點別的",
          DialogueId = 90230002,
          GUID = "E1E19FB4",
          NextDialogue = 90230001
        },
        [90230003] = {
          ContentTC = "再見",
          DialogueId = 90230003,
          GUID = "E1E19FDE"
        },
        [90230101] = {
          ContentTC = "你天天往劍刃上抹奶油，它當然不會回應你。",
          DialogueId = 90230101,
          GUID = "E1E1AFF2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230102,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_1"
        },
        [90230102] = {
          ContentTC = "啊？難道它不喜歡冰淇淋？！那……土豆泥怎麼樣？沙拉醬呢？",
          DialogueId = 90230102,
          GUID = "E1E1B01C",
          NextDialogue = 90230103,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84102:Explain01_End"
          }
        },
        [90230103] = {
          ContentTC = "艾利西安傳頌會的人對你怎麼樣？",
          DialogueId = 90230103,
          GUID = "E1E1B046",
          NextDialogue = 90230104,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_2"
        },
        [90230104] = {
          ContentTC = "閉嘴閉嘴！別和我提那群老頑固！啊啊，真是的，好好的心情都被你……啊，我不能生氣，不能生氣……",
          DialogueId = 90230104,
          GUID = "E1E1B070",
          NextDialogue = 90230105,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_3"
        },
        [90230105] = {
          ContentTC = "聽起來你對他們意見很大啊……",
          DialogueId = 90230105,
          GUID = "E1E1B09A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90230201] = {
          ContentTC = "「堅忍」意味著什麼？",
          DialogueId = 90230201,
          GUID = "E1E1C05A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230202,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_1"
        },
        [90230202] = {
          ContentTC = "就是字面意思啊，「堅忍」就是要堅定、要忍耐，無論遇到什麼事都不能生氣！",
          DialogueId = 90230202,
          GUID = "E1E1C084",
          NextDialogue = 90230203,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84102:Think_End"
          }
        },
        [90230203] = {
          ContentTC = "那也太難了吧……",
          DialogueId = 90230203,
          GUID = "E1E1C0AE",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90230301] = {
          ContentTC = "唔，他們說憤怒是很大的罪惡，我不能生氣，不能生氣……",
          DialogueId = 90230301,
          GUID = "E1E1D0C2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230302,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_1"
        },
        [90230302] = {
          ContentTC = "真是辛苦你了。",
          DialogueId = 90230302,
          GUID = "E1E1D0EC",
          NextDialogue = 90230303,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_2"
        },
        [90230303] = {
          ContentTC = "哼哼，誰叫我是「堅忍」大人呢！",
          DialogueId = 90230303,
          GUID = "E1E1D116",
          NextDialogue = 90230304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84102:Think_End"
          }
        },
        [90230304] = {
          ContentTC = "「七美德」是什麼?",
          DialogueId = 90230304,
          GUID = "E1E1D140",
          NextDialogue = 90230305,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_3"
        },
        [90230305] = {
          ContentTC = "「七美德」是艾利西安最威風，最高貴，最強大帥氣的七個人。當然，顧名思義，也是美德最豐沛的七個人啦。",
          DialogueId = 90230305,
          GUID = "E1E1D16A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90230401] = {
          ContentTC = "你那是什麼表情……真是放肆！竟然趕質疑本大人，我要罰你抄寫戒律三十……不，一百遍！",
          DialogueId = 90230401,
          GUID = "E1E1E12A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230402,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_1"
        },
        [90230402] = {
          ContentTC = "薩麥爾，今天外面正豔陽高照呢，那我們吃點涼的怎麼樣？唔，聽說聖都最近有一種叫「冰淇淋」的甜品，莉茲偷偷買給你吧！雖然是平民的食物，但肯定比那些老頑固給的餐點美味很多！",
          DialogueId = 90230402,
          GUID = "E1E1E154",
          NextDialogue = 90230403,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_2"
        },
        [90230403] = {
          ContentTC = "薩麥爾？它每天都好得很啊，早上叫我起床，戰鬥時幫我鼓勁，晚上還要給我講十二個睡前小故事！哼哼，才不勞你掛心。",
          DialogueId = 90230403,
          GUID = "E1E1E17E",
          NextDialogue = 90230404,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_3"
        },
        [90230404] = {
          ContentTC = "「堅忍，是七大美德之一……心中常存忍耐，就能夠見到常人不能見的，行世人難以……難以……」\n啊啊啊不行受不了啦！小矮子你再在那裡模仿本大人的樣子本大人就要忍不住拿薩麥爾切水產了我以九神之名發誓真的會做到的！！",
          DialogueId = 90230404,
          GUID = "E1E1E1A8",
          NextDialogue = 90230405,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "84102:Talk02_End"
          }
        },
        [90230405] = {
          ContentTC = "抹奶油？怎麼啦。我們艾利西安人就是這樣保養武器的，有什麼意見嗎？",
          DialogueId = 90230405,
          GUID = "E1E1E1D2",
          NextDialogue = 90230406,
          SpeakNpcId = 84102,
          TalkActionId = {
            [1] = "84102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_4"
        },
        [90230406] = {
          ContentTC = "話說，我都沒見過你生氣的樣子誒……\n這樣！本大人以七美德候補的名義命令你，氣一個給我看看！不許重複那些老頑固的話，什麼美德啊戒律啊第幾卷第幾條的！就表演一下那個那個，生氣！",
          DialogueId = 90230406,
          GUID = "E1E1E1FC",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
          bForbidSkipOptions = true
        },
        [90230501] = {
          ContentTC = "薩麥爾，我又變強了哦，讓我們一起保護那些煩人的傢伙吧。",
          DialogueId = 90230501,
          GUID = "E1E1F192",
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_01"
        },
        [90230601] = {
          ContentTC = "你不講美德！",
          DialogueId = 90230601,
          GUID = "E1E201FA",
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_03"
        },
        [90230701] = {
          ContentTC = "薩麥爾！",
          DialogueId = 90230701,
          GUID = "E1E21262",
          SpeakNpcId = 84102,
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_04"
        },
        [90240000] = {
          ContentTC = "這裡很是亮堂又寬敞，就是桌椅板凳多了些，否則倒是演武對練的好地方。",
          DialogueId = 90240000,
          GUID = "E1E80800",
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_idle"
        },
        [90240001] = {
          ContentTC = "今天宜飲酒縱歌，來來，待我飲完這杯，一起去誅盡那些應殺之人。什麼？你說昨天我也是這樣說的？那當然，一年三百六十日，日日都宜如此過活。",
          DialogueId = 90240001,
          GUID = "E1E8082A",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextOptions = {
            [1] = 902400011,
            [2] = 902400012,
            [3] = 902400013,
            [4] = 902400014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_welcome",
          bForbidSkipOptions = true
        },
        [90240002] = {
          ContentTC = "聊點別的",
          DialogueId = 90240002,
          GUID = "E1E80854",
          NextDialogue = 90240001
        },
        [90240003] = {
          ContentTC = "再見",
          DialogueId = 90240003,
          GUID = "E1E8087E"
        },
        [90240101] = {
          ContentTC = "怎麼，你也對劍法有興趣嗎？是了，我看你也帶著一把好劍，想必是有家傳的功夫。比一比就知道啦。",
          DialogueId = 90240101,
          GUID = "E1E81892",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240102,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_1"
        },
        [90240102] = {
          ContentTC = "老實說，我已經很久沒有遇到過勢均力敵的對手了。但是按照我師父的說法，我個性太直，不會演戲，還需要繼續磨練。",
          DialogueId = 90240102,
          GUID = "E1E818BC",
          NextDialogue = 90240103,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_2"
        },
        [90240103] = {
          ContentTC = "演技也是劍法的一種嗎？",
          DialogueId = 90240103,
          GUID = "E1E818E6",
          NextDialogue = 90240104,
          SpeakNpcId = 100001
        },
        [90240104] = {
          ContentTC = "其實我覺得不是，但是師父有說用劍需要會演：「能而示之不能」，和「不戰而屈人之兵」、「以眾擊寡」一樣，都是上等的劍法。",
          DialogueId = 90240104,
          GUID = "E1E81910",
          NextDialogue = 90240105,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_3"
        },
        [90240105] = {
          ContentTC = "我小的時候他就是這樣對待我的，說自己本領稀鬆平常，只要把他打倒在地就可以不用練習之類的話。我試了一年，從沒碰到過他的衣袖。",
          DialogueId = 90240105,
          GUID = "E1E8193A",
          NextDialogue = 90240106,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_4"
        },
        [90240106] = {
          ContentTC = "直到有一天累到趴在地上，看他腳底下連一滴汗都沒有。才確信他那副顛顛又倒倒的樣子都是演的。",
          DialogueId = 90240106,
          GUID = "E1E81964",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90240201] = {
          ContentTC = "理由可以舉出無數個，但是歸根究底無非三個字：我不願。",
          DialogueId = 90240201,
          GUID = "E1E828FA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240202,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_1"
        },
        [90240202] = {
          ContentTC = "從小逍遙自在慣了，只知道路見不平拔刀相助。師父和師兄的話我都只聽愛聽的，大半當作秋風過耳。又怎麼會受什麼律法的羈絆。",
          DialogueId = 90240202,
          GUID = "E1E82924",
          NextDialogue = 90240203,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_2"
        },
        [90240203] = {
          ContentTC = "那說一說最重要的理由吧。",
          DialogueId = 90240203,
          GUID = "E1E8294E",
          NextDialogue = 90240204,
          SpeakNpcId = 100001
        },
        [90240204] = {
          ContentTC = "身為劍客的擔憂吧：打個比方，習劍的基礎是熟記圖譜上的一招一式，面對一般的敵人時可以不多加思索，頃刻間拔劍迎敵。",
          DialogueId = 90240204,
          GUID = "E1E82978",
          NextDialogue = 90240205,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_3"
        },
        [90240205] = {
          ContentTC = "但太過依賴圖譜，不會隨機應變，那手中的劍就會變成死劍、呆劍、傻瓜劍。面對未曾謀面的敵人就會方寸大亂，如同呆頭鵝。",
          DialogueId = 90240205,
          GUID = "E1E829A2",
          NextDialogue = 90240206,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_4"
        },
        [90240206] = {
          ContentTC = "在我看來，現在的華胥就是把《大風九章》翻爛的拙劍客，連我這樣的飄零人都斬不盡，要是遇到真正的強敵，是會敗的。",
          DialogueId = 90240206,
          GUID = "E1E829CC",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
          bForbidSkipOptions = true
        },
        [90240301] = {
          ContentTC = "當然了，劍客的意思是擅長用劍，不是只會用劍。否則的話，華胥還有人能把筆和筷子當作武器，那劍客豈不是不能寫字吃飯？",
          DialogueId = 90240301,
          GUID = "E1E83962",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240302,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Agree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_1"
        },
        [90240302] = {
          ContentTC = "好遺憾，我還以為你真能做到用劍切開子彈。",
          DialogueId = 90240302,
          GUID = "E1E8398C",
          NextDialogue = 90240303,
          SpeakNpcId = 100001
        },
        [90240303] = {
          ContentTC = "我能啊，但能這樣做不代表必須這麼做，躲開可要比硬接容易多了。山裡的野豬都知道能吃蘿蔔的時候絕不去啃樹皮呢。",
          DialogueId = 90240303,
          GUID = "E1E839B6",
          NextDialogue = 90240304,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_2"
        },
        [90240304] = {
          ContentTC = "但是，如果碰見能痛快打上一場的對手，我肯定會拔出劍來，全力以赴。",
          DialogueId = 90240304,
          GUID = "E1E839E0",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90240401] = {
          ContentTC = "確實，你這麼一問我能想到不少。啥啥一哥，什麼王，某仙之類，用動物來做外號的尤其多，龍虎獅鶴，飛禽走獸都有，非常熱鬧。",
          DialogueId = 90240401,
          GUID = "E1E849CA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240402,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_1"
        },
        [90240402] = {
          ContentTC = "然後這些外號啊，往往字數越長，功夫越差。四個字的一看就是剛入門，三個字的有頭有臉，兩個字，高手。至於沒有外號的，那都是大宗師了。",
          DialogueId = 90240402,
          GUID = "E1E849F4",
          NextDialogue = 90240403,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_2"
        },
        [90240403] = {
          ContentTC = "刻舟是真名還是外號？",
          DialogueId = 90240403,
          GUID = "E1E84A1E",
          NextDialogue = 90240404,
          SpeakNpcId = 100001
        },
        [90240404] = {
          ContentTC = "行不更名坐不改姓，是真名。我知道你想說這個聽起來像是外號。師父也這麼說過，說是容易小小年紀就被當做高手，會吃虧。",
          DialogueId = 90240404,
          GUID = "E1E84A48",
          NextDialogue = 90240405,
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_3"
        },
        [90240405] = {
          ContentTC = "可畢竟這個名字是老爹給我起的，可能也是希望我成為一個俠客吧。他留下的東西不多，但只要這個名字還在，就總歸證明他在世上還留有劍痕一道。",
          DialogueId = 90240405,
          GUID = "E1E84A72",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          TalkActionId = {
            [1] = "81503:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90240501] = {
          ContentTC = "所謂劍之極為無劍，一草一木皆可為劍。我聽聞你會使用清潔工具當作武器禦敵，想必你也是用劍的高手，還望不吝賜教。",
          DialogueId = 90240501,
          GUID = "E1E85A32",
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_01"
        },
        [90240601] = {
          ContentTC = "你的舊劍我先代為保管，等你什麼時候不再緊鎖著眉頭哭喪著臉，我就還你。當然，得先比試一場，如果輸了，這劍就當你送我了。",
          DialogueId = 90240601,
          GUID = "E1E86A9A",
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_02"
        },
        [90240701] = {
          ContentTC = "劍可以是朋友，可以是玩物，甚至也可以是餐具、撬棍和剃鬚刀，但是唯獨不可以是主人。希望你前行的旅途不要被這柄劍困住。",
          DialogueId = 90240701,
          GUID = "E1E87B02",
          SpeakNpcId = 81503,
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_03"
        },
        [90250000] = {
          ContentTC = "薩麥爾，今天外面正豔陽高照呢，那我們吃點涼的怎麼樣？唔，聽說聖都最近有一種叫「冰淇淋」的甜品，莉茲偷偷買給你吧！雖然是平民的食物，但肯定比那些老頑固給的餐點美味很多！",
          DialogueId = 90250000,
          GUID = "E1EE70A0",
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_idle"
        },
        [90250001] = {
          ContentTC = "你好啊，我在帶著薩麥爾呼吸新鮮空氣，熟悉這裡的氛圍和陽光，你要和它打招呼嗎？它會很高興的，嗯嗯，應該會的！",
          DialogueId = 90250001,
          GUID = "E1EE70CA",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextOptions = {
            [1] = 90250100,
            [2] = 90250200,
            [3] = 90250300,
            [4] = 90250400
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90250002] = {
          ContentTC = "聊點別的",
          DialogueId = 90250002,
          GUID = "E1EE70F4",
          NextDialogue = 90250001
        },
        [90250003] = {
          ContentTC = "再見",
          DialogueId = 90250003,
          GUID = "E1EE711E"
        },
        [90250100] = {
          ContentTC = "你的兵器好像很厲害的樣子……",
          DialogueId = 90250100,
          GUID = "E1EE8108",
          NextDialogue = 90250101
        },
        [90250101] = {
          ContentTC = "薩麥爾可不是什麼普通兵器，它是我最好的朋友！",
          DialogueId = 90250101,
          GUID = "E1EE8132",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250102,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_1"
        },
        [90250102] = {
          ContentTC = "為什麼莉茲貝爾會把一把劍當做朋友呢？",
          DialogueId = 90250102,
          GUID = "E1EE815C",
          NextDialogue = 90250103,
          SpeakNpcId = 100001
        },
        [90250103] = {
          ContentTC = "在傳頌會，只有被七件聖器選中的人才能成為「七美德」。當時有那麼多那麼多大力士，但只有我能拔出薩麥爾——既然它選擇了我，我也一定會好好對待它的！",
          DialogueId = 90250103,
          GUID = "E1EE8186",
          NextDialogue = 90250104,
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_2"
        },
        [90250104] = {
          ContentTC = "只是，雖然我拔出了它，但從那天開始，它再也沒有回應過我的呼喚了……等等，這是秘密，絕對不要說出去！",
          DialogueId = 90250104,
          GUID = "E1EE81B0",
          NextDialogue = 90250105,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_3"
        },
        [90250105] = {
          ContentTC = "你天天往劍刃上抹奶油，它當然不會回應你。",
          DialogueId = 90250105,
          GUID = "E1EE81DA",
          NextDialogue = 90250106,
          SpeakNpcId = 100001
        },
        [90250106] = {
          ContentTC = "啊？難道它不喜歡冰淇淋？！那……土豆泥怎麼樣？沙拉醬呢？",
          DialogueId = 90250106,
          GUID = "E1EE8204",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90250200] = {
          ContentTC = "艾利西安傳頌會的人對你怎麼樣？",
          DialogueId = 90250200,
          GUID = "E1EE9170",
          NextDialogue = 90250201
        },
        [90250201] = {
          ContentTC = "閉嘴閉嘴！別和我提那群老頑固！啊啊，真是的，好好的心情都被你……啊，我不能生氣，不能生氣……",
          DialogueId = 90250201,
          GUID = "E1EE919A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250202,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_1"
        },
        [90250202] = {
          ContentTC = "聽起來你對他們意見很大啊……",
          DialogueId = 90250202,
          GUID = "E1EE91C4",
          NextDialogue = 90250203,
          SpeakNpcId = 100001
        },
        [90250203] = {
          ContentTC = "咳咳，才沒有呢！司祭們人都好棒的，一個個都特別和藹可親的。背錯的經文只需要抄三十遍，喂薩麥爾吃奶油被發現也只要面壁思過兩天就行了，超喜歡大家的。",
          DialogueId = 90250203,
          GUID = "E1EE91EE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90250300] = {
          ContentTC = "「堅忍」意味著什麼？",
          DialogueId = 90250300,
          GUID = "E1EEA1D8",
          NextDialogue = 90250301
        },
        [90250301] = {
          ContentTC = "就是字面意思啊，「堅忍」就是要堅定、要忍耐，無論遇到什麼事都不能生氣！",
          DialogueId = 90250301,
          GUID = "E1EEA202",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250302,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_1"
        },
        [90250302] = {
          ContentTC = "那也太難了吧……",
          DialogueId = 90250302,
          GUID = "E1EEA22C",
          NextDialogue = 90250303,
          SpeakNpcId = 100001
        },
        [90250303] = {
          ContentTC = "可不是嘛……因為這個稱號，我總是被教導要用忍耐去對抗憤怒。可這就像是打哈欠打到一半被人搭話，又或是舉劍後被告知眼前的敵人並非敵人而是同伴一樣。總之就是，反而會讓人更加生……",
          DialogueId = 90250303,
          GUID = "E1EEA256",
          NextDialogue = 90250304,
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_2"
        },
        [90250304] = {
          ContentTC = "唔，他們說憤怒是很大的罪惡，我不能生氣，不能生氣……",
          DialogueId = 90250304,
          GUID = "E1EEA280",
          NextDialogue = 90250305,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_3"
        },
        [90250305] = {
          ContentTC = "真是辛苦你了。",
          DialogueId = 90250305,
          GUID = "E1EEA2AA",
          NextDialogue = 90250306,
          SpeakNpcId = 100001
        },
        [90250306] = {
          ContentTC = "哼哼，誰叫我是「堅忍」大人呢！",
          DialogueId = 90250306,
          GUID = "E1EEA2D4",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90250400] = {
          ContentTC = "「七美德」是什麼?",
          DialogueId = 90250400,
          GUID = "E1EEB240",
          NextDialogue = 90250401
        },
        [90250401] = {
          ContentTC = "「七美德」是艾利西安最威風，最高貴，最強大帥氣的七個人。當然，顧名思義，也是美德最豐沛的七個人啦。",
          DialogueId = 90250401,
          GUID = "E1EEB26A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250402,
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_1"
        },
        [90250402] = {
          ContentTC = "呃……",
          DialogueId = 90250402,
          GUID = "E1EEB294",
          NextDialogue = 90250403,
          SpeakNpcId = 100001
        },
        [90250403] = {
          ContentTC = "你那是什麼表情……真是放肆！竟然趕質疑本大人，我要罰你抄寫戒律三十……不，一百遍！",
          DialogueId = 90250403,
          GUID = "E1EEB2BE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_2",
          bForbidSkipOptions = true
        }
      }
    end
  },
  {
    MinKey = 90250501,
    MaxKey = 200048042,
    Loader = function()
      return {
        [90250501] = {
          ContentTC = "薩麥爾？它每天都好得很啊，早上叫我起床，戰鬥時幫我鼓勁，晚上還要給我講十二個睡前小故事！哼哼，才不勞你掛心。",
          DialogueId = 90250501,
          GUID = "E1EEC2D2",
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_01"
        },
        [90250601] = {
          ContentTC = "「堅忍，是七大美德之一……心中常存忍耐，就能夠見到常人不能見的，行世人難以……難以……」\n啊啊啊不行受不了啦！小矮子你再在那裡模仿本大人的樣子本大人就要忍不住拿薩麥爾切水產了我以九神之名發誓真的會做到的！！",
          DialogueId = 90250601,
          GUID = "E1EED33A",
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_02"
        },
        [90250701] = {
          ContentTC = "抹奶油？怎麼啦。我們艾利西安人就是這樣保養武器的，有什麼意見嗎？",
          DialogueId = 90250701,
          GUID = "E1EEE3A2",
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_03"
        },
        [90250801] = {
          ContentTC = "話說，我都沒見過你生氣的樣子誒…… \n這樣！本大人以七美德候補的名義命令你，氣一個給我看看！不許重複那些老頑固的話，什麼美德啊戒律啊第幾卷第幾條的！就表演一下那個那個，生氣！",
          DialogueId = 90250801,
          GUID = "E1EEF40A",
          SpeakNpcId = 81501,
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_04"
        },
