        },
        [200071013] = {
          ContentTC = "沒什麼事。",
          DialogueId = 200071013,
          GUID = "200071013",
          SpeakNpcId = 100001
        },
        [510001041] = {
          ContentTC = "啊啊啊！我喝！讓我自己來！",
          DialogueId = 510001041,
          GUID = "510001041.0",
          ImprPlusId = 1004,
