          DialogueId = 510003023,
          GUID = "510003023.0",
          ImprPlusId = 1004,
          NextDialogue = 51000305
        },
        [510003051] = {
          ContentTC = "（也許可以幫上什麽忙。）",
          DialogueId = 510003051,
          GUID = "510003051.0",
          NextDialogue = 510003052
        },
        [510003052] = {
