        },
        [510003053] = {
          ContentTC = "（離開。）",
          DialogueId = 510003053,
          GUID = "510003053.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [510003054] = {
          ContentTC = "（詢問她是不是遇到了什麽煩心事。付一些報酬的話，可以考慮幫忙解決。）",
          DialogueId = 510003054,
          FailDialogue = 51000306,
          GUID = "510003054.0",
          ImprCheckId = 1001,
          NextDialogue = 51000307
        },
        [510003055] = {
          ContentTC = "（詢問她是否在找什麽人，也許日後出城的時候可以幫她留意一下。）",
          DialogueId = 510003055,
          FailDialogue = 51000306,
          GUID = "510003055.0",
          ImprCheckId = 1002,
          NextDialogue = 51000307
        },
        [510003056] = {
          ContentTC = "（詢問她是不是有什麽困難，或許能提供一些幫助。）",
          DialogueId = 510003056,
          FailDialogue = 51000306,
          GUID = "510003056.0",
          ImprCheckId = 1003,
          NextDialogue = 51000307
        },
        [510003111] = {
          ContentTC = "對此沒有印象。",
          DialogueId = 510003111,
          GUID = "510003111.0",
          NextDialogue = 51000312
        },
        [510004031] = {
          ContentTC = "那個……{性别:我是男的。|我不是你的女兒。}",
          DialogueId = 510004031,
          GUID = "510004031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000490,
          Subtitle = "Umm... {性别:I am a man.|I am not your daughter.}"
        },
        [510004032] = {
          ContentTC = "冷靜一下。你在找人？我會幫你留意。",
          DialogueId = 510004032,
          GUID = "510004032.0",
          ImprPlusId = 1004,
          NextDialogue = 51000490,
          Subtitle = "Please calm down. Are you looking for someone? I'll keep an eye out for you."
        },
        [510004033] = {
          ContentTC = "媽！！！",
          DialogueId = 510004033,
          GUID = "510004033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000404,
          Subtitle = "Mom!!!"
        },
        [510004071] = {
          ContentTC = "（接受）",
          DialogueId = 510004071,
          GUID = "510004071.0",
          NextDialogue = 51000408,
          Subtitle = "(Accept)"
        },
        [510004921] = {
          ContentTC = "請好好回想一下你女兒的特徵與失蹤的經過，這樣我才能確定能否幫到你。",
          DialogueId = 510004921,
          FailDialogue = 51000405,
          GUID = "510004921.0",
          ImprCheckId = 1007,
          NextDialogue = 51000406,
          Subtitle = "Please think carefully about your daughter's features and how she disappeared, so I can see what I can do."
        },
        [510005011] = {
          ContentTC = "愛爾莎，我有了安妮的消息……",
          DialogueId = 510005011,
          GUID = "510005011.0",
          NextDialogue = 51000502
        },
        [510005021] = {
          ContentTC = "請您節哀，安妮已經去世了……在她生命的最後，她幫助另一個女孩活了下來，她的善良值得被銘記。",
          DialogueId = 510005021,
          GUID = "510005021.0",
          NextDialogue = 51000503
        },
        [510006011] = {
          ContentTC = "愛爾莎，我找到你女兒了。",
          DialogueId = 510006011,
          GUID = "510006011.0",
          NextDialogue = 51000602
        },
        [510007011] = {
          ContentTC = "你一直在這裡徘徊，有什麼能幫你的嗎？",
          DialogueId = 510007011,
          GUID = "510007011.0",
          NextDialogue = 51000702,
          Subtitle = "Have you been wandering around here all this time? Is there anything I can help you with?"
        },
        [510007031] = {
          ContentTC = "我理解你的迷茫，失去歸屬感的確很糟。",
          DialogueId = 510007031,
          GUID = "510007031.0",
          ImprPlusId = 1004,
          NextDialogue = 51000705,
          Subtitle = "I understand. Losing a sense of belonging is awful."
        },
        [510007032] = {
          ContentTC = "滯留在外並不安全，還是儘早弄清你的真實身份為妙。",
          DialogueId = 510007032,
          GUID = "510007032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000705,
          Subtitle = "Staying out here isn't safe. It's best to figure out your true identity as soon as possible."
        },
        [510007033] = {
          ContentTC = "眼見不一定為實。一切都需要調查後才能得出結論。",
          DialogueId = 510007033,
          GUID = "510007033.0",
          ImprPlusId = 1003,
          NextDialogue = 51000705,
          Subtitle = "Seeing is not always believing. You've got to investigate everything thoroughly before jumping to conclusions."
        },
        [510007051] = {
          ContentTC = "（接受）",
          DialogueId = 510007051,
          GUID = "510007051.0",
          NextDialogue = 51000706,
          Subtitle = "(Accept)"
        },
        [510008121] = {
          ContentTC = "（不展示愛麗絲的日記）",
          DialogueId = 510008121,
          GUID = "510008121.0",
          NextDialogue = 51000813,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}"
        },
        [510008141] = {
          ContentTC = "正是你母親托我來尋找你，我會帶你去見她。",
          DialogueId = 510008141,
          GUID = "510008141.0",
          NextDialogue = 51000814
        },
        [510008921] = {
          ContentTC = "（展示愛麗絲的日記）",
          DialogueId = 510008921,
          GUID = "510008921.0",
          NextDialogue = 51000803,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "(Show Alice's diary)"
        },
        [510009031] = {
          ContentTC = "我只看到了一些破爛，據我估價，他們不會比幾塊石頭更有價值。",
          DialogueId = 510009031,
          GUID = "510009031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000904,
          Subtitle = "I only see some junk here. According to my evaluation, they're not worth more than a few stones."
        },
        [510009032] = {
          ContentTC = "不問自取的行為還是少做為妙。",
          DialogueId = 510009032,
          GUID = "510009032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000905,
          Subtitle = "It's better not to take things without asking."
        },
        [510009033] = {
          ContentTC = "從哪兒摸的！帶我一個！",
          DialogueId = 510009033,
          GUID = "510009033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000906,
          Subtitle = "Where did you swipe these from? Teach me that!"
        },
        [510009071] = {
          ContentTC = "很可惜，這裡沒有我需要的商品。",
          DialogueId = 510009071,
          GUID = "510009071.0",
          NextDialogue = 51000907,
          Subtitle = "Sadly, there's nothing I need here."
        },
        [510009072] = {
          ContentTC = "（他仔仔細細地打量著你，露出了一個深思的表情）",
          DialogueId = 510009072,
          GUID = "510009072.0",
          ImprCheckId = 1004,
          NextDialogue = 51000909,
          Subtitle = "(He scrutinises you closely, revealing a thoughtful expression)"
        },
        [510009101] = {
          ContentTC = "我聽說有人可以提供一部分價格低廉的燃料與布匹，這讓不少窮人能安然渡過隆冬。",
          DialogueId = 510009101,
          GUID = "510009101.0",
          ImprPlusId = 1002,
          Subtitle = "I heard someone can provide some low-priced fuel and cloth to help many poor people get through the winter."
        },
        [510009102] = {
          ContentTC = "你售賣情報，但你看起來不像個私家偵探，難道你有特別的情報來源？",
          DialogueId = 510009102,
          GUID = "510009102.0",
          ImprPlusId = 1003,
          Subtitle = "You sell information, but you don't look like a private detective. Do you have a special source for receiving intelligence?"
        },
        [510009103] = {
          ContentTC = "我已經聽你說過三遍馬丁了，你到底誰啊？",
          DialogueId = 510009103,
          GUID = "510009103.0",
          ImprPlusId = 1005,
          Subtitle = "I've already heard you say Martin three times. Who exactly are you?"
        },
        [510009121] = {
          ContentTC = "真有那麼神奇嗎？",
          DialogueId = 510009121,
          GUID = "510009121",
          Subtitle = "Is it really that magical?"
        },
        [510009161] = {
          ContentTC = "（接受）",
          DialogueId = 510009161,
          GUID = "510009161.0",
          Subtitle = "(Accept)"
        },
        [510010071] = {
          ContentTC = "你丟了一樣東西。這件東西證明了你不過也是個和他一樣的窩棚板富豪。",
          DialogueId = 510010071,
          GUID = "510010071.0",
          ImprCheckId = 1005,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. That thing proves that you are a shack-dwelling tycoon just like him."
        },
        [510010072] = {
          ContentTC = "你丟了一樣東西。通常來說，過期車票應該銷毀以防模仿造假，而私藏顯然是個違規行為。",
          DialogueId = 510010072,
          GUID = "510010072.0",
          ImprCheckId = 1006,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. Normally, expired tickets should be destroyed to prevent counterfeiting, and keeping them is obviously a violation."
        },
        [510010101] = {
          ContentTC = "傳說星星有實現願望的能力，你用車票疊了上百顆星星，又想實現什麼樣的願望呢？",
          DialogueId = 510010101,
          GUID = "510010101.0",
          Subtitle = "Legend has it that stars have the power to fulfill wishes. You folded hundreds of stars from tickets, so what's your wish?"
        },
        [510010181] = {
          ContentTC = "我理解你的不甘與悲痛，人生總有不如意的時候，但現在無法跨越的天塹也許終有一天會成為坦途。",
          DialogueId = 510010181,
          GUID = "510010181.0",
          ImprPlusId = 1004,
          NextDialogue = 51001019,
          Subtitle = "I understand your frustration and sorrow. Life always has disappointment, but what's insurmountable now might one day become a clear path."
        },
        [510010182] = {
          ContentTC = "不論如何，剛才的先生都不應該被你這麼羞辱，恕我難以苟同你把怒火發洩到別人身上的行為。",
          DialogueId = 510010182,
          GUID = "510010182.0",
          ImprPlusId = 1002,
          NextDialogue = 51001020,
          Subtitle = "Regardless, the gentleman earlier should not have been humiliated by you, and I disagree with your act of venting your anger on others."
        },
        [510010183] = {
          ContentTC = "不管你怎麼想，要是不想攤上事，你就該把這東西收回去，妥善保存也罷，銷毀也好，那是你的問題。",
          DialogueId = 510010183,
          GUID = "510010183.0",
          ImprPlusId = 1001,
          NextDialogue = 51001021,
          Subtitle = "Whatever you think, if you don't want any trouble, you should either take this thing back and store it properly or destroy it. That's something you should take care of."
        },
        [510010184] = {
          ContentTC = "你幹嘛不扒在車頂坐個來回過過癮？",
          DialogueId = 510010184,
          GUID = "510010184.0",
          ImprPlusId = 1005,
          NextDialogue = 51001022,
          Subtitle = "Why don't you sit up on the roof of the car for a round trip for fun?"
        },
        [510012011] = {
          ContentTC = "這些金翎鳥都是你養的嗎？",
          DialogueId = 510012011,
          GUID = "510012011.0",
          ImprPlusId = 1003,
          NextDialogue = 51001202,
          Subtitle = "Are these golden plume birds yours?"
        },
        [510012012] = {
          ContentTC = "原來這些是你養的啊，我還以為今天可以加餐了呢。",
          DialogueId = 510012012,
          GUID = "510012012.0",
          ImprPlusId = 1005,
          NextDialogue = 51001203,
          Subtitle = "So, these birds are yours? I was hoping to have some fresh poultry for dinner."
        },
        [510012041] = {
          ContentTC = "（回憶你從書本上看到的金翎鳥的知識——它們的習性，以及為什麼它們可以成為探測工具。）",
          DialogueId = 510012041,
          GUID = "510012041.0",
          ImprPlusId = 1003,
          NextDialogue = 51001205,
          Subtitle = "(Recalling what you've read about golden plume birds — their behaviour and their utility as detection tools.)"
        },
        [510012042] = {
          ContentTC = "（附和面前這位礦工，批判人們對傳統的遺棄。）",
          DialogueId = 510012042,
          GUID = "510012042.0",
          ImprPlusId = 1004,
          NextDialogue = 51001206,
          Subtitle = "(Agree with him and lament the disregard for tradition.)"
        },
        [510012043] = {
          ContentTC = "（向面前這位礦工讚揚技術發展能讓人類社會更高效地運轉。）",
          DialogueId = 510012043,
          GUID = "510012043.0",
          ImprPlusId = 1001,
          NextDialogue = 51001207,
          Subtitle = "(Commend the progress in technology for enhancing the efficiency of human society.)"
        },
        [510013011] = {
          ContentTC = "你不能這樣侮辱一位受尊敬的女士。",
          DialogueId = 510013011,
          GUID = "510013011.0",
          ImprPlusId = 1002,
          NextDialogue = 51001302,
          Subtitle = "Oi! You can't insult a respected lady at the doorstep of The Asphodel!"
        },
        [510013012] = {
          ContentTC = "（上去就是一拳）",
          DialogueId = 510013012,
          GUID = "510013012.0",
          ImprPlusId = 1005,
          NextDialogue = 51001303,
          Subtitle = "(Throw a punch at his face)"
        },
        [510013013] = {
          ContentTC = "給她點面子就敢蹬鼻子上臉，還說什麽看不上老子的酒，老子早晚讓她吃不了兜著走！",
          DialogueId = 510013013,
          GUID = "510013013",
          NextOptions = {
            [1] = 510013011,
            [2] = 510013012
          },
          SpeakNpcId = 700014,
          bForbidSkipOptions = true
        },
        [510013041] = {
          ContentTC = "我更願意把卡蜜拉視為一位堅定而出色的盟友，她幫了我們好幾次，不止我們，冰湖城裡起碼有一半人欠她人情。",
          DialogueId = 510013041,
          FailDialogue = 51001305,
          GUID = "510013041.0",
          ImprCheckId = 1008,
          NextDialogue = 51001306,
          Subtitle = "I'd rather see Camilla as a reliable and strong ally. She's been our saviour on numerous occasions. Not just us — at least half the city is in her debt."
        },
        [510013042] = {
          ContentTC = "這不是你在這裡大放厥詞的理由，我相信卡蜜拉的人品，這不是你憑空幾句話就能抹黑的。",
          DialogueId = 510013042,
          FailDialogue = 51001305,
          GUID = "510013042.0",
          ImprCheckId = 1009,
          NextDialogue = 51001306,
          Subtitle = "That doesn't give you the right to spout nonsense here. Camilla's integrity is not up for debate, and it's certainly not to be smeared by your baseless accusations."
        },
        [510013043] = {
          ContentTC = "我領教過卡蜜拉的慧眼，無論是人品還是酒品都能被她一眼鑒別出來，不識貨的是你才對。",
          DialogueId = 510013043,
          FailDialogue = 51001305,
          GUID = "510013043.0",
          ImprCheckId = 1010,
          NextDialogue = 51001306,
          Subtitle = "I've seen Camilla's discernment in action. She has an eye for both people and liquor. It seems to me that you're the one who can't recognise good stuff."
        },
        [510013061] = {
          ContentTC = "嗯，咳，聽口音你不是本地人吧。我猜，自從來到冰湖城，你就沒去水仙平原之外的地方喝過吧？",
          DialogueId = 510013061,
          GUID = "510013061.0",
          SpeakNpcId = 700014
        },
        [510013062] = {
          ContentTC = "那又如何？",
          DialogueId = 510013062,
          GUID = "510013062",
          Subtitle = "So what?"
        },
        [510013091] = {
          ContentTC = "好吧，來一桶。",
          DialogueId = 510013091,
          GUID = "510013091.0",
          NextDialogue = 51001310,
          Subtitle = "Fine, I'll take a can."
        },
        [510013092] = {
          ContentTC = "便宜沒好貨。",
          DialogueId = 510013092,
          GUID = "510013092.0",
          NextDialogue = 51001313,
          Subtitle = "You get what you pay for."
        },
        [510013231] = {
          ContentTC = "搶生意也就算了，萬一假酒把人喝出毛病怎麽辦？",
          DialogueId = 510013231,
          GUID = "510013231.0",
          ImprPlusId = 1002,
          NextDialogue = 51001324
        },
        [510013232] = {
          ContentTC = "就是！還怕她一張嘴！兄弟你喝一桶看看實力！",
          DialogueId = 510013232,
          GUID = "510013232.0",
          ImprPlusId = 1005,
          NextDialogue = 51001326
        },
        [510013281] = {
          ContentTC = "假貨害人啊……",
          DialogueId = 510013281,
          GUID = "510013281.0",
          NextDialogue = 51001329
        },
        [510014021] = {
          ContentTC = "孩子本就是天生通透的詩人。",
          DialogueId = 510014021,
          GUID = "510014021.0",
          ImprPlusId = 1004,
          NextDialogue = 51001403,
          Subtitle = "Children are natural poets seeing through life's essence, aren't they?"
        },
        [510014022] = {
          ContentTC = "你看起來非常為他們自豪。",
          DialogueId = 510014022,
          GUID = "510014022.0",
          ImprPlusId = 1003,
          NextDialogue = 51001403,
          Subtitle = "You seem to be very proud of them."
        },
        [510014023] = {
          ContentTC = "可惡，原來我輸在了起跑線上。",
          DialogueId = 510014023,
          GUID = "510014023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001403,
          Subtitle = "Darn it, it seems I was behind right from the start."
        },
        [510014061] = {
          ContentTC = "才不是呢，你教會了孩子可貴的純真與浪漫。",
          DialogueId = 510014061,
          FailDialogue = 51001407,
          GUID = "510014061.0",
          ImprCheckId = 1011,
          NextDialogue = 51001409,
          Subtitle = "Not at all. You've preserved the children's precious innocence and sense of wonder."
        },
        [510014901] = {
          ContentTC = "你看起來在和孩子們的相處中收穫了很多。",
          DialogueId = 510014901,
          GUID = "510014901.0",
          ImprPlusId = 1003,
          NextDialogue = 51001412,
          Subtitle = "It seems you've gained a lot from your time with the children."
        },
        [510014902] = {
          ContentTC = "為這些孩子們做出犧牲，真的是值得的嗎？",
          DialogueId = 510014902,
          GUID = "510014902.0",
          ImprPlusId = 1001,
          NextDialogue = 51001412,
          Subtitle = "Is it really worth it?"
        },
        [510015021] = {
          ContentTC = "用清潔劑泡一泡再擦？",
          DialogueId = 510015021,
          GUID = "510015021.0",
          ImprPlusId = 1003,
          NextDialogue = 51001503,
          Subtitle = "Maybe try soaking it in detergent first?"
        },
        [510015022] = {
          ContentTC = "你付錢給我，我給你擦。",
          DialogueId = 510015022,
          GUID = "510015022.0",
          ImprPlusId = 1001,
          NextDialogue = 51001503,
          Subtitle = "You got cash? I can clean it for you."
        },
        [510015023] = {
          ContentTC = "挨打挨駡是好事，有助於鍛煉精神。",
          DialogueId = 510015023,
          GUID = "510015023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001503,
          Subtitle = "Getting beaten up is good for character building, isn't it?"
        },
        [510015071] = {
          ContentTC = "你不覺得說這種話太冷漠了嗎？",
          DialogueId = 510015071,
          GUID = "510015071.0",
          ImprCheckId = 1012,
          NextDialogue = 51001509,
          Subtitle = "What a heartless thing to say!"
        },
        [510016021] = {
          ContentTC = "（此人脾氣有點暴躁，摸一摸他的惡魔角安撫下吧。）",
          DialogueId = 510016021,
          GUID = "510016021.0",
          ImprPlusId = 1005,
          NextDialogue = 51001603,
          Subtitle = "(He seems temperamental. Maybe touching his horns will calm him down.)"
        },
        [510016022] = {
          ContentTC = "卡戎和人類是平等的。你不該心存偏見。",
          DialogueId = 510016022,
          GUID = "510016022.0",
          ImprPlusId = 1002,
          NextDialogue = 51001605,
          Subtitle = "Charons and humans are equals. Prejudice is not cool."
        },
        [510016023] = {
          ContentTC = "可是你也是個卡戎啊……？",
          DialogueId = 510016023,
          GUID = "510016023.0",
          ImprPlusId = 1003,
          NextDialogue = 51001607,
          Subtitle = "But you're a Charon too... aren't you?"
        },
        [510016121] = {
          ContentTC = "我可以看看您的「桂冠卡戎」獎章嗎？",
          DialogueId = 510016121,
          FailDialogue = 51001690,
          GUID = "510016121.0",
          ImprCheckId = 1013,
          NextDialogue = 51001613,
          Subtitle = "May I have the honour to take a peek at your \"Laurelled Charon\" medal?"
        },
        [510017031] = {
          ContentTC = "（真誠建議他注意個人衛生問題）",
          DialogueId = 510017031,
          GUID = "510017031.0",
          ImprPlusId = 1003,
          NextDialogue = 51001704,
          Subtitle = "(Sincerely suggest he looks into personal hygiene.)"
        },
        [510017032] = {
          ContentTC = "（為自己剛才失禮的動作道歉）",
          DialogueId = 510017032,
          GUID = "510017032.0",
          ImprPlusId = 1004,
          NextDialogue = 51001704,
          Subtitle = "(Apologise for your rather impolite reaction just now.)"
        },
        [510017033] = {
          ContentTC = "（指責他的味道過於腥臭有惡劣影響）",
          DialogueId = 510017033,
          GUID = "510017033.0",
          ImprPlusId = 1002,
          NextDialogue = 51001704,
          Subtitle = "(Complain that his stench is unbearable and affects those around him.)"
        },
        [510017081] = {
          ContentTC = "一個本該救死扶傷的人不應該來修理下水道。",
          DialogueId = 510017081,
          FailDialogue = 51001709,
          GUID = "510017081.0",
          ImprCheckId = 1014,
          NextDialogue = 51001711,
          Subtitle = "A life-saver like you shouldn't be stuck mending sewers."
        },
        [510017161] = {
          ContentTC = "如果再給你的人生重來一次的機會，你還會救他嗎？",
          DialogueId = 510017161,
          GUID = "510017161.0",
          NextDialogue = 51001717,
          Subtitle = "If you had a chance to do it all over, would you make the same choice to save him?"
        },
        [510018011] = {
          ContentTC = "（接受。）",
          DialogueId = 510018011,
          GUID = "510018011.0",
          NextDialogue = 51001802,
          Subtitle = "(Accept)"
        },
        [510018012] = {
          ContentTC = "（拒絕。）",
          DialogueId = 510018012,
          GUID = "510018012.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Refuse)"
        },
        [510019231] = {
          ContentTC = "這裂紋的形狀……原來如此，它替威爾斯先生擋下了胸口的致命傷啊。",
          DialogueId = 510019231,
          GUID = "510019231.0",
          ImprPlusId = 1003,
          NextDialogue = 51001924,
          Subtitle = "The shape of these cracks... I see. It protected you from a fatal blow to the chest."
        },
        [510019232] = {
          ContentTC = "……威爾斯先生就算過得再怎麼慘，也不該去偷別人的懷錶吧。",
          DialogueId = 510019232,
          GUID = "510019232.0",
          ImprPlusId = 1005,
          NextDialogue = 51001924,
          Subtitle = "...Mr. Wells, no matter how hard life is, you shouldn't steal someone else's watch."
        },
        [510019911] = {
          ContentTC = "威爾斯先生沒你說的不堪，別太過分了。",
          DialogueId = 510019911,
          FailDialogue = 51001916,
          GUID = "510019911.0",
          ImprCheckId = 1015,
          NextDialogue = 51001918,
          Subtitle = "Mr. Wells isn't as bad as you say. You're pushing things too far."
        },
        [510019912] = {
          ContentTC = "桂冠卡戎我們沒有任何吸引力，別拿你淺薄的認知定義所有人。",
          DialogueId = 510019912,
          FailDialogue = 51001916,
          GUID = "510019912.0",
          ImprCheckId = 1016,
          NextDialogue = 51001918,
          Subtitle = "We have no interest in becoming laurelled Charon. Don't try to put everyone into a box with your shallow understanding."
        },
        [510019913] = {
          ContentTC = "嘴巴放乾淨點。不然今天像狗一樣被打一頓的，就是另一個「威爾斯先生」了。",
          DialogueId = 510019913,
          FailDialogue = 51001916,
          GUID = "510019913.0",
          ImprCheckId = 1017,
          NextDialogue = 51001918,
          Subtitle = "Watch your mouth. Otherwise, another \"Mr. Wells\" might end up getting beaten up like a dog today."
        },
        [510020031] = {
          ContentTC = "為什麼你不自己去尋寶呢？",
          DialogueId = 510020031,
          GUID = "510020031.0",
          ImprPlusId = 1003,
          NextDialogue = 51002004,
          Subtitle = "Why don't you go treasure hunting yourself?"
        },
        [510020032] = {
