          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [510033051] = {
          ContentTC = "今天生意怎麽樣，足夠購買過夜的燃料嗎？",
          DialogueId = 510033051,
          GUID = "510033051.0",
          ImprPlusId = 1002,
          NextDialogue = 510033053
        },
        [510033052] = {
          ContentTC = "你這點哪夠我吃的。",
          DialogueId = 510033052,
          GUID = "510033052.0",
          ImprPlusId = 1005,
          NextDialogue = 510033054
        },
        [510033053] = {
          ContentTC = "托您的福，食物和燃料，我總能得到其中一個，人生就是一場取舍。",
          DialogueId = 510033053,
          GUID = "510033053.0",
          NextDialogue = 51003306,
          SpeakNpcId = 700080
        },
        [510033054] = {
          ContentTC = "給您塞塞牙縫！雖然數量不足 ，但口味可以保證！",
          DialogueId = 510033054,
          GUID = "510033054.0",
          NextDialogue = 51003306,
          SpeakNpcId = 700080
        },
        [510033141] = {
          ContentTC = "你並不怨恨他，也沒有偷竊他家的財物，讓我來猜猜看你為什麽要半夜闖空門吧。",
          DialogueId = 510033141,
          FailDialogue = 51003315,
          GUID = "510033141.0",
          ImprCheckId = 1022,
          NextDialogue = 51003316
        },
        [510034141] = {
          ContentTC = "有什麽將要發生了！我們站在凍結的湖面，能看到的只是冷漠，深邃，凝結。",
          DialogueId = 510034141,
          GUID = "510034141.0",
          NextDialogue = 510034142,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700093:Talk01_Start"
          }
        },
        [510034142] = {
          ContentTC = "但我們誰都知道暗流正在醞釀，正在壯大，終有一天，它會吞噬我們現有的一切。在這之前，我會乘上火車前往預兆的源頭。",
          DialogueId = 510034142,
          GUID = "510034142.0",
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700093:Talk01_End"
          }
        },
        [510034143] = {
          ContentTC = "冬天的寒冷已經不再困擾我了，謝謝你，狩月人。",
          DialogueId = 510034143,
          GUID = "510034143.0",
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700094:Explain02_Start"
          }
        },
        [510035031] = {
          ContentTC = "（艾瑪匆忙將花放在指定地點，並按流程獻上了感謝致辭，但她的走神還是引起了老師的嘀咕。）",
          DialogueId = 510035031,
