        },
        [800202022] = {
          ContentTC = "有這麼誇張嗎？",
          DialogueId = 800202022,
          GUID = "800202022.0",
          NextDialogue = 80020204
        },
        [800202091] = {
          ContentTC = "你真的只是一名女僕嗎？",
          DialogueId = 800202091,
          GUID = "800202091.0",
          NextDialogue = 80020210
        },
        [800202092] = {
          ContentTC = "太危險了。",
          DialogueId = 800202092,
          GUID = "800202092.0",
          NextDialogue = 80020211
        },
        [800202161] = {
          ContentTC = "聽起來有些浪漫。",
