        [800202162] = {
          ContentTC = "聽起來很辛苦。",
          DialogueId = 800202162,
          GUID = "800202162.0",
          NextDialogue = 80020218
        },
        [800203021] = {
          ContentTC = "我可以一起嗎？",
          DialogueId = 800203021,
          GUID = "800203021.0",
          NextDialogue = 80020303
        },
        [800203022] = {
          ContentTC = "你也會逛街嗎？",
          DialogueId = 800203022,
          GUID = "800203022.0",
          NextDialogue = 80020304
        },
        [800203121] = {
          ContentTC = "真的這麼神奇？",
          DialogueId = 800203121,
          GUID = "800203121.0",
          NextDialogue = 80020313
        },
        [800203122] = {
          ContentTC = "聽上去確實會很好看。",
          DialogueId = 800203122,
          GUID = "800203122.0",
          NextDialogue = 80020314
        },
        [800203161] = {
          ContentTC = "王子？",
          DialogueId = 800203161,
          GUID = "800203161.0",
          NextDialogue = 80020317
        },
        [800204021] = {
          ContentTC = "聽起來心情不錯？",
          DialogueId = 800204021,
          GUID = "800204021.0",
          NextDialogue = 80020403
        },
        [800204022] = {
          ContentTC = "這才更像是女僕的工作啊。",
          DialogueId = 800204022,
          GUID = "800204022.0",
          NextDialogue = 80020404
        },
        [800204091] = {
          ContentTC = "那麼你是遇到了什麼煩心事？",
          DialogueId = 800204091,
          GUID = "800204091.0",
          NextDialogue = 80020410
        },
        [800204092] = {
          ContentTC = "展開講講你的前同僚們？",
          DialogueId = 800204092,
          GUID = "800204092.0",
          NextDialogue = 80020411
        },
        [800204171] = {
          ContentTC = "好奇的話，不如直接去見她？",
          DialogueId = 800204171,
          GUID = "800204171.0",
          NextDialogue = 80020418
        },
        [800205011] = {
          ContentTC = "啊？只是巧合而已。",
          DialogueId = 800205011,
          GUID = "800205011.0",
          NextDialogue = 80020503
        },
        [800205012] = {
          ContentTC = "你的頭髮那麼顯眼，很難不注意到。",
          DialogueId = 800205012,
          GUID = "800205012.0",
          NextDialogue = 80020503
        },
        [800205071] = {
          ContentTC = "聽起來像是解開了心結？",
          DialogueId = 800205071,
          GUID = "800205071.0",
          NextDialogue = 80020508
        },
        [800205072] = {
          ContentTC = "不會覺得可惜嗎？",
          DialogueId = 800205072,
          GUID = "800205072.0",
          NextDialogue = 80020509
        },
        [800205121] = {
          ContentTC = "當我尚在猶豫之時，她毫不遲疑地想要去完成任務——甚至把我也視為必要時可以除去的阻礙。",
          DialogueId = 800205121,
          GUID = "C852AD41",
          NextDialogue = 80020513,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD41"
        },
        [800205141] = {
          ContentTC = "你還恨著她嗎？",
          DialogueId = 800205141,
          GUID = "C852AD6C",
          NextDialogue = 800205143
        },
        [800205142] = {
          ContentTC = "你還愛著她嗎？",
          DialogueId = 800205142,
          GUID = "C852AD6D",
          NextDialogue = 800205143
        },
        [800205143] = {
          ContentTC = "坦白說，我不知道。我對她只是有些氣惱，有些委屈，還有些想念。對於兩個密探來說，你提到的愛和恨，都太奢侈了。",
          DialogueId = 800205143,
          FacialId = {
            [1] = "93102:Unhappy01"
          },
          GUID = "C852AD94",
          NextDialogue = 80020515,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD94"
        },
        [800205181] = {
          ContentTC = "嗯？你剛才說了「謝謝」吧？",
          DialogueId = 800205181,
          GUID = "800205181.0",
          NextDialogue = 80020522
        },
        [800205182] = {
          ContentTC = "沒聽清，再說一遍。",
          DialogueId = 800205182,
          GUID = "800205182.0",
          NextDialogue = 80020522
        },
        [800301051] = {
          ContentTC = "蘭迪在這些方面可真有原則啊。",
          DialogueId = 800301051,
          GUID = "800301051.0",
          NextDialogue = 80030106
        },
        [800301052] = {
          ContentTC = "蘭迪總是偷懶呢。",
          DialogueId = 800301052,
          GUID = "800301052.0",
          NextDialogue = 80030107
        },
        [800302051] = {
          ContentTC = "為了休假編謊，這也能叫紳士？",
          DialogueId = 800302051,
          GUID = "800302051.0",
          NextDialogue = 80030206
        },
        [800302052] = {
          ContentTC = "嗯，對對，風度翩翩，紳士極了。",
          DialogueId = 800302052,
          GUID = "800302052.0",
          NextDialogue = 80030207
        },
        [800302091] = {
          ContentTC = "姐姐們？聽起來應該也都是淑女。",
          DialogueId = 800302091,
          GUID = "800302091.0",
          NextDialogue = 80030210
        },
        [800302092] = {
          ContentTC = "無法想像你還是小男孩的時候。",
          DialogueId = 800302092,
          GUID = "800302092.0",
          NextDialogue = 80030211
        },
        [800302131] = {
          ContentTC = "「關愛」？聽上去並不壞啊。",
          DialogueId = 800302131,
          GUID = "800302131.0",
          NextDialogue = 80030214
        },
        [800302132] = {
          ContentTC = "「關愛」？聽起來和「紳士」是差不多的用法，辛苦你了。",
          DialogueId = 800302132,
          GUID = "800302132.0",
          NextDialogue = 80030215
        },
        [800304031] = {
          ContentTC = "是不是遇到什麼煩心事了？你平時不這樣。",
          DialogueId = 800304031,
          GUID = "800304031.0",
          NextDialogue = 80030404
        },
        [800304032] = {
          ContentTC = "這麼急著走，是被人約了跳舞嗎？",
          DialogueId = 800304032,
          GUID = "800304032.0",
          NextDialogue = 80030406
        },
        [800304071] = {
          ContentTC = "噩夢？",
          DialogueId = 800304071,
          GUID = "800304071.0",
          NextDialogue = 80030408
        },
        [800304081] = {
          ContentTC = "蘭迪的父親？頭一次聽你提到他。",
          DialogueId = 800304081,
          GUID = "800304081.0",
          NextDialogue = 80030409
        },
        [800304321] = {
          ContentTC = "真的是這樣嗎？",
          DialogueId = 800304321,
          GUID = "800304321.0",
          NextDialogue = 80030433
        },
        [800304351] = {
          ContentTC = "他要是現在醒來的話，一定會為你驕傲的。",
          DialogueId = 800304351,
          GUID = "800304351.0",
          NextDialogue = 80030436
        },
        [800304352] = {
          ContentTC = "我再給你調一杯。",
          DialogueId = 800304352,
          GUID = "800304352.0",
          NextDialogue = 80030437
        },
        [800305011] = {
          ContentTC = "謝謝，看上去心情不錯？",
          DialogueId = 800305011,
          GUID = "C8790EF4",
          NextDialogue = 80030502
        },
        [800305012] = {
          ContentTC = "你是不是有什麼企圖？",
          DialogueId = 800305012,
          GUID = "C8790F48",
          NextDialogue = 80030503
        },
        [800305081] = {
          ContentTC = "一位女士？那找我幹什麼？",
          DialogueId = 800305081,
          GUID = "C879106E",
          NextDialogue = 80030509,
          TriggerCondition = {
            IsBoy = {}
          }
        },
        [800305082] = {
          ContentTC = "所以你是為了這個才邀請我……",
