          GUID = "800305082.0",
          NextDialogue = 80030526,
          TriggerCondition = {
            IsGirl = {}
          }
        },
        [800305091] = {
          ContentTC = "你自己怎麼不扮？",
          DialogueId = 800305091,
          GUID = "800305091.0",
          NextDialogue = 80030510
        },
        [800305092] = {
          ContentTC = "？",
          DialogueId = 800305092,
          GUID = "800305092.0",
          NextDialogue = 80030511
        },
        [800305141] = {
          ContentTC = "？？？什麼情況，兄弟。",
          DialogueId = 800305141,
          GUID = "800305141.0",
          NextDialogue = 80030515
        },
        [800305142] = {
          ContentTC = "其實根本就是你想自己穿吧。",
          DialogueId = 800305142,
          GUID = "800305142.0",
          NextDialogue = 80030515
        },
        [800305161] = {
          ContentTC = "後面兩個是什麼奇怪的東西……",
          DialogueId = 800305161,
          GUID = "800305161.0",
          NextDialogue = 80030517
        },
        [800305171] = {
          ContentTC = "那我就勉為其難地答應了。",
          DialogueId = 800305171,
          GUID = "80030571",
          NextDialogue = 80030518
        },
        [800305172] = {
          ContentTC = "讓我再想想。",
          DialogueId = 800305172,
          GUID = "800305172",
          NextDialogue = 80030523
        },
        [800305261] = {
          ContentTC = "你是不是想要在舞會上活捉我？",
          DialogueId = 800305261,
          GUID = "C87910C2",
          NextDialogue = 80030527
        },
        [800305311] = {
          ContentTC = "當然是開玩笑。",
          DialogueId = 800305311,
          GUID = "C87911BE",
          NextDialogue = 80030532
        },
        [800305312] = {
          ContentTC = "這兩者並不矛盾啊！",
          DialogueId = 800305312,
          GUID = "C8791212",
          NextDialogue = 80030533
        },
        [800305351] = {
          ContentTC = "抱歉，因為覺得你驚慌的樣子一定會很有趣，沒忍住……",
          DialogueId = 800305351,
          GUID = "C87912BA",
          NextDialogue = 80030536
        },
        [800305352] = {
          ContentTC = "不，我是真的很擔心會被你抓走！",
          DialogueId = 800305352,
          GUID = "C8791362",
          NextDialogue = 80030539
        },
        [800305431] = {
          ContentTC = "那，好吧，我答應你。",
          DialogueId = 800305431,
          GUID = "C879145E",
          NextDialogue = 80030544
        },
        [800701271] = {
          DialogueId = 800701271,
          GUID = "800701271.0",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/gun_kill\"},PlayAs2D{true}}"
        },
        [801001021] = {
          ContentTC = "薄情？我做了什麽了？",
          DialogueId = 801001021,
          GUID = "801001021.0",
          NextDialogue = 80100103
        },
        [801001022] = {
          ContentTC = "沒錯，我就是無情的人，你要幹什麽？",
          DialogueId = 801001022,
          GUID = "801001022.0",
          NextDialogue = 80100104
        },
        [801001041] = {
          ContentTC = "戀情？誰和誰的？",
          DialogueId = 801001041,
          GUID = "801001041.0",
          NextDialogue = 80100105
        },
        [801001091] = {
          ContentTC = "你冷靜一點，我們才認識沒多久。",
          DialogueId = 801001091,
          GUID = "801001091.0",
          NextDialogue = 80100110
        },
        [801001092] = {
          ContentTC = "我知道了，你在練習舞臺劇，所以才會一直念詩。",
          DialogueId = 801001092,
          GUID = "801001092.0",
          NextDialogue = 80100111
        },
        [801002011] = {
          ContentTC = "「那一面」？",
          DialogueId = 801002011,
          GUID = "801002011.0",
          NextDialogue = 80100202
        },
        [801002071] = {
          ContentTC = "原來你也有過這樣的夢想啊。",
          DialogueId = 801002071,
          GUID = "801002071.0",
          NextDialogue = 80100208
        },
        [801002072] = {
          ContentTC = "曾經……也就是說現在已經習慣了？",
          DialogueId = 801002072,
          GUID = "801002072.0",
          NextDialogue = 80100209
        },
        [801002151] = {
          ContentTC = "太危險了，我拒絕。",
          DialogueId = 801002151,
          GUID = "801002151.0",
          NextDialogue = 80100216
        },
        [801002152] = {
          ContentTC = "你可以試一試。",
          DialogueId = 801002152,
          GUID = "801002152.0",
          NextDialogue = 80100217
        },
        [801002191] = {
          ContentTC = "我不會給你這樣的機會。",
          DialogueId = 801002191,
          GUID = "801002191.0",
          NextDialogue = 80100220
        },
        [801003021] = {
          ContentTC = "我討厭揣測別人的想法。",
          DialogueId = 801003021,
          GUID = "801003021.0",
          NextDialogue = 80100303
        },
        [801003022] = {
          ContentTC = "有關你過去的故事？",
          DialogueId = 801003022,
          GUID = "801003022.0",
          NextDialogue = 80100305
        },
        [801003091] = {
          ContentTC = "她在追捕你？",
          DialogueId = 801003091,
          GUID = "801003091.0",
          NextDialogue = 80100310
        },
        [801003141] = {
          ContentTC = "我本來就被帝國通緝，罪多不壓身。",
          DialogueId = 801003141,
          GUID = "801003141.0",
          NextDialogue = 80100315
        },
        [801003142] = {
          ContentTC = "看來，我應該和你保持適當的距離。",
          DialogueId = 801003142,
          GUID = "801003142.0",
          NextDialogue = 80100327
        },
        [801003191] = {
          ContentTC = "命定之人？",
          DialogueId = 801003191,
          GUID = "801003191.0",
          NextDialogue = 80100320
        },
        [801003221] = {
          ContentTC = "已經聽到了。",
          DialogueId = 801003221,
          GUID = "801003221.0",
          NextDialogue = 80100323
        },
        [801003222] = {
          ContentTC = "是誰啊，要不我幫你傳個信唄？",
          DialogueId = 801003222,
          GUID = "801003222.0",
          NextDialogue = 80100323
        },
        [801003321] = {
          ContentTC = "我怎麽感覺你樂在其中？",
          DialogueId = 801003321,
          GUID = "801003321.0",
          NextDialogue = 80100333
        },
        [801003331] = {
          ContentTC = "命定之人？",
          DialogueId = 801003331,
          GUID = "801003331.0",
          NextDialogue = 80100334
        },
        [801004011] = {
          ContentTC = "是遇到了什麽煩心事嗎？",
          DialogueId = 801004011,
          GUID = "801004011.0",
          NextDialogue = 80100402
        },
        [801004012] = {
          ContentTC = "看來我邀請你的時間不合時宜。",
          DialogueId = 801004012,
          GUID = "801004012.0",
          NextDialogue = 80100403
        },
        [801004121] = {
          ContentTC = "你在逃避真實的自己。",
          DialogueId = 801004121,
          GUID = "801004121.0",
          NextDialogue = 80100413
        },
        [801004122] = {
          ContentTC = "演技真差！",
          DialogueId = 801004122,
          GUID = "801004122.0",
          NextDialogue = 80100415
        },
        [801101021] = {
          ContentTC = "看來還是軍團好吃好喝的太多了。",
          DialogueId = 801101021,
          GUID = "801101021.0",
          NextDialogue = 80110103
        },
        [801101051] = {
          ContentTC = "我聽說軍團好像得到了一個叫「零號」的寶貝……",
          DialogueId = 801101051,
          GUID = "801101051.0",
          NextDialogue = 80110106
        },
        [801101052] = {
          ContentTC = "你想太多了，就是單純請你喝杯酒而已。",
          DialogueId = 801101052,
          GUID = "801101052.0",
          NextDialogue = 80110112
        },
        [801101141] = {
          ContentTC = "原來你也做過狩月人。",
          DialogueId = 801101141,
          GUID = "801101141.0",
          NextDialogue = 80110115
        },
        [801101142] = {
          ContentTC = "原來你是冰湖城本地人。",
          DialogueId = 801101142,
          GUID = "801101142.0",
          NextDialogue = 80110115
        },
        [801101161] = {
          ContentTC = "你好像很害怕說錯話？",
          DialogueId = 801101161,
          GUID = "801101161.0",
          NextDialogue = 80110117
        },
        [801101201] = {
          ContentTC = "那你在軍團不會覺得很拘束嗎？",
          DialogueId = 801101201,
          GUID = "801101201.0",
          NextDialogue = 80110121
        },
        [801101202] = {
          ContentTC = "看不出來，我看你還挺威風的。",
          DialogueId = 801101202,
          GUID = "801101202.0",
          NextDialogue = 80110122
        },
        [801101261] = {
          ContentTC = "這是我可以聽的嗎？",
          DialogueId = 801101261,
          GUID = "801101261.0",
          NextDialogue = 80110127
        },
        [801101301] = {
          ContentTC = "我就開個玩笑！",
          DialogueId = 801101301,
          GUID = "801101301.0",
          NextDialogue = 80110131
        },
        [801101361] = {
          ContentTC = "這……也是我可以聽的嗎？",
          DialogueId = 801101361,
          GUID = "801101361.0",
          NextDialogue = 80110137
        },
        [801102021] = {
          ContentTC = "是的。在卡蜜拉女士那裡。",
          DialogueId = 801102021,
          GUID = "801102021.0",
          NextDialogue = 80110203
        },
        [801102031] = {
          ContentTC = "還有殺人越貨的委托？！",
          DialogueId = 801102031,
          GUID = "801102031.0",
          NextDialogue = 80110204
        },
        [801102051] = {
          ContentTC = "不，她挺和善的。",
          DialogueId = 801102051,
          GUID = "801102051.0",
          NextDialogue = 80110206
        },
        [801102052] = {
          ContentTC = "沒錯，很是兇惡。",
          DialogueId = 801102052,
          GUID = "801102052.0",
          NextDialogue = 80110207
        },
        [801102071] = {
          ContentTC = "……你長官是誰？",
          DialogueId = 801102071,
          GUID = "801102071.0",
          NextDialogue = 80110208
